const DRAG_THRESHOLD = 8;
const SCROLL_THRESHOLD = 4;
const PICKUP_DELAY = 120;
const FRICTION = 0.95; 
const BOUNCE_FRICTION = 0.8;
const SPRING_STRENGTH = 0.15;
const MIN_VELOCITY = 0.1;

export const useCollectionDrag = ({ onAdd, onRemove, scrollRef }: UseCollectionDragProps) => {
    const { user, inspect } = useUser();
    const [dragState, setDragState] = useState<CollectionDragState | null>(null);

    const stateRef = useRef({
        isScrolling: false,
        isDragging: false,
        canDrag: false,
        startPos: { x: 0, y: 0 },
        startScrollTop: 0,
        hasCard: false,
        lastY: 0,
        lastTime: 0,
        velocity: 0,
        overscroll: 0, 
        samples: [] as { dy: number, dt: number }[]
    });

    const animationFrameRef = useRef<number | null>(null);
    const dragTargetRef = useRef<HTMLElement | null>(null);
    const pickupTimerRef = useRef<number | null>(null);

    const runPhysics = useCallback(() => {
        const el = scrollRef.current;
        if (!el) return;

        const s = stateRef.current;
        const maxScroll = el.scrollHeight - el.clientHeight;
        let currentScroll = el.scrollTop;

        if (currentScroll < 0 || currentScroll > maxScroll) {
            const target = currentScroll < 0 ? 0 : maxScroll;
            const diff = target - currentScroll;
            s.velocity = (s.velocity + diff * SPRING_STRENGTH) * BOUNCE_FRICTION;

            if (Math.abs(diff) < 1 && Math.abs(s.velocity) < 1) {
                el.scrollTop = target;
                s.velocity = 0;
                animationFrameRef.current = null;
                return;
            }
        } else {
            s.velocity *= FRICTION;
        }

        el.scrollTop -= s.velocity;

        if (Math.abs(s.velocity) > MIN_VELOCITY || currentScroll < 0 || currentScroll > maxScroll) {
            animationFrameRef.current = requestAnimationFrame(runPhysics);
        } else {
            s.velocity = 0;
            animationFrameRef.current = null;
        }
    }, [scrollRef]);

    const stopPhysics = useCallback(() => {
        if (animationFrameRef.current !== null) {
            cancelAnimationFrame(animationFrameRef.current);
            animationFrameRef.current = null;
        }
    }, []);

    const handlePointerDown = useCallback((
        e: React.PointerEvent, 
        card: CardDefinition | null,
        origin: 'archive' | 'vault'
    ) => {
        if (e.button !== 0) return;

        stopPhysics();

        const target = e.currentTarget as HTMLElement;
        dragTargetRef.current = target;
        try { target.setPointerCapture(e.pointerId); } catch (err) {}

        const rect = target.getBoundingClientRect();
        const startPos = { x: e.clientX, y: e.clientY };

        // DRAG ELIGIBILITY CHECK
        const isOwned = user.collection.includes(card?.id || '');
        const inDeck = user.decks[user.activeDeckId]?.includes(card?.id || '');
        const canDrag = card && (origin === 'vault' || (isOwned && !inDeck));

        stateRef.current = {
            isScrolling: false,
            isDragging: false,
            canDrag: !!canDrag,
            startPos,
            startScrollTop: scrollRef.current?.scrollTop || 0,
            hasCard: !!card,
            lastY: e.clientY,
            lastTime: performance.now(),
            velocity: 0,
            overscroll: 0,
            samples: []
        };

        setDragState({
            card: card || ({} as CardDefinition),
            origin,
            active: false,
            startPos,
            currentPos: startPos,
            rect,
            offset: card ? { x: e.clientX - rect.left, y: e.clientY - rect.top } : { x: 0, y: 0 },
        });

        if (canDrag) {
            if (origin === 'vault') {
                stateRef.current.isDragging = true;
                setDragState(prev => prev ? { ...prev, active: true } : null);
            } else {
                pickupTimerRef.current = window.setTimeout(() => {
                    if (!stateRef.current.isScrolling) {
                        stateRef.current.isDragging = true;
                        setDragState(prev => prev ? { ...prev, active: true } : null);
                    }
                }, PICKUP_DELAY);
            }
        }

    }, [scrollRef, stopPhysics, user.collection, user.decks, user.activeDeckId]);

    useEffect(() => {
        if (!dragState) return;

        const handlePointerMove = (e: PointerEvent) => {
            const s = stateRef.current;
            const el = scrollRef.current;
            const now = performance.now();
            const dt = now - s.lastTime;
            const deltaX = e.clientX - s.startPos.x;
            const deltaY = e.clientY - s.startPos.y;

            if (dt > 0) {
                const dy = e.clientY - s.lastY;
                s.samples.push({ dy, dt });
                if (s.samples.length > 3) s.samples.shift();

                const totalDy = s.samples.reduce((sum, val) => sum + val.dy, 0);
                const totalDt = s.samples.reduce((sum, val) => sum + val.dt, 0);
                s.velocity = totalDy / (totalDt / 16.67);

                s.lastY = e.clientY;
                s.lastTime = now;
            }

            if (!s.isScrolling && !s.isDragging) {
                const absX = Math.abs(deltaX);
                const absY = Math.abs(deltaY);

                if (absY > SCROLL_THRESHOLD) {
                    const isFastSwipe = Math.abs(s.velocity) > 12;
                    if (s.hasCard && s.canDrag && !isFastSwipe && deltaY < 0 && absY > DRAG_THRESHOLD) {
                        s.isDragging = true;
                        if (pickupTimerRef.current) clearTimeout(pickupTimerRef.current);
                        setDragState(prev => prev ? { ...prev, active: true, currentPos: { x: e.clientX, y: e.clientY } } : null);
                    } else {
                        s.isScrolling = true;
                        if (pickupTimerRef.current) clearTimeout(pickupTimerRef.current);
                    }
                } else if (absX > DRAG_THRESHOLD && s.hasCard && s.canDrag) {
                    s.isDragging = true;
                    if (pickupTimerRef.current) clearTimeout(pickupTimerRef.current);
                    setDragState(prev => prev ? { ...prev, active: true, currentPos: { x: e.clientX, y: e.clientY } } : null);
                }
            }

            if (s.isScrolling && el) {
                const maxScroll = el.scrollHeight - el.clientHeight;
                let targetScroll = s.startScrollTop - deltaY;
                if (targetScroll < 0) targetScroll = targetScroll * 0.4;
                else if (targetScroll > maxScroll) targetScroll = maxScroll + ((targetScroll - maxScroll) * 0.4);
                el.scrollTop = targetScroll;
                return;
            }

            if (s.isDragging) {
                if (e.cancelable) e.preventDefault();
                setDragState(prev => prev ? { ...prev, currentPos: { x: e.clientX, y: e.clientY } } : null);
            }
        };

        const handlePointerUp = (e: PointerEvent) => {
            if (pickupTimerRef.current) clearTimeout(pickupTimerRef.current);
            if (dragTargetRef.current) {
                try { dragTargetRef.current.releasePointerCapture(e.pointerId); } catch (err) {}
                dragTargetRef.current = null;
            }

            const s = stateRef.current;
            const { isDragging, isScrolling, startPos, hasCard } = s;

            if (isScrolling || (scrollRef.current && (scrollRef.current.scrollTop < 0 || scrollRef.current.scrollTop > scrollRef.current.scrollHeight - scrollRef.current.clientHeight))) {
                animationFrameRef.current = requestAnimationFrame(runPhysics);
            }

            if (isDragging && hasCard) {
                const els = document.elementsFromPoint(e.clientX, e.clientY);
                const vaultZone = els.find((el) => el.getAttribute('data-drop-zone') === 'vault');
                const archiveZone = els.find((el) => el.getAttribute('data-drop-zone') === 'archive');

                if (dragState.origin === 'archive' && vaultZone) {
                    onAdd(dragState.card.id);
                } else if (dragState.origin === 'vault' && (archiveZone || !user.collection.includes(dragState.card.id))) {
                    onRemove(dragState.card.id);
                }
            } else if (!isScrolling && !isDragging && hasCard) {
                const dist = Math.hypot(e.clientX - startPos.x, e.clientY - startPos.y);
                if (dist < DRAG_THRESHOLD) inspect(dragState.card);
            }

            setDragState(null);
            s.isScrolling = false;
            s.isDragging = false;
        };

        window.addEventListener('pointermove', handlePointerMove, { passive: false });
        window.addEventListener('pointerup', handlePointerUp);
        window.addEventListener('pointercancel', handlePointerUp);

        return () => {
            window.removeEventListener('pointermove', handlePointerMove);
            window.removeEventListener('pointerup', handlePointerUp);
            window.removeEventListener('pointercancel', handlePointerUp);
            if (pickupTimerRef.current) clearTimeout(pickupTimerRef.current);
        };
    }, [dragState, inspect, onAdd, onRemove, scrollRef, runPhysics, user]);

    return { dragState, handlePointerDown };
};

import React, { useMemo } from 'react';
import { CARDS } from '../../constants';
import { Card } from '../Card';
import { CardDefinition } from '../../types';
import { useUser } from '../../contexts/UserContext';

interface CollectionGridProps {
    scrollRef: React.RefObject<HTMLDivElement>;
    ownedIds: string[];
    activeDeckIds: string[];
    draggingCardId?: string;
    onPointerDown: (e: React.PointerEvent, card: CardDefinition | null) => void;
}

export const CollectionGrid: React.FC<CollectionGridProps> = ({ 
    scrollRef, ownedIds, activeDeckIds, draggingCardId, onPointerDown 
}) => {
    const { collectionSort, collectionFilterSearch, collectionFilterTags } = useUser();

    const filteredAndSortedCards = useMemo(() => {
        let results = [...CARDS];

        if (collectionFilterSearch) {
            const query = collectionFilterSearch.toLowerCase();
            results = results.filter(c => 
                c.name.toLowerCase().includes(query) || 
                c.baseText.toLowerCase().includes(query)
            );
        }

        if (collectionFilterTags.length > 0) {
            results = results.filter(c => {
                return collectionFilterTags.some(tag => {
                    if (tag === 'None') return c.tags.length === 0;
                    return c.tags.includes(tag);
                });
            });
        }

        return results.sort((a, b) => {
            const aOwned = ownedIds.includes(a.id);
            const bOwned = ownedIds.includes(b.id);
            if (aOwned !== bOwned) return aOwned ? -1 : 1;

            if (collectionSort === 'Cost') return a.baseCost - b.baseCost;
            if (collectionSort === 'Power') return b.basePower - a.basePower;
            if (collectionSort === 'Newest') {
                const aIdx = CARDS.findIndex(c => c.id === a.id);
                const bIdx = CARDS.findIndex(c => c.id === b.id);
                return bIdx - aIdx;
            }
            return a.name.localeCompare(b.name);
        });
    }, [ownedIds, collectionSort, collectionFilterSearch, collectionFilterTags]);

    return (
        <div className="w-full h-full flex flex-col">
            <div 
                ref={scrollRef} 
                className="flex-1 overflow-hidden px-4 pt-1.5 pb-52 touch-none select-none"
                onPointerDown={(e) => onPointerDown(e, null)} 
            >
                 {filteredAndSortedCards.length === 0 ? (
                     <div className="w-full py-20 flex flex-col items-center justify-center text-slate-700 pointer-events-none">
                         <svg className="w-12 h-12 mb-2 opacity-20" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                         <span className="text-[0.6rem] font-black uppercase tracking-widest">No matching cards</span>
                     </div>
                 ) : (
                     <div className="grid grid-cols-4 gap-x-2 gap-y-3">
                         {filteredAndSortedCards.map((def) => {
                             const isOwned = ownedIds.includes(def.id);
                             const inDeck = activeDeckIds.includes(def.id);
                             const isDragging = draggingCardId === def.id;

                             let stateClasses = '';
                             if (isDragging) {
                                 stateClasses = 'opacity-0';
                             } else if (!isOwned) {
                                 stateClasses = 'opacity-40 grayscale scale-90'; 
                             } else if (inDeck) {
                                 stateClasses = 'opacity-50 grayscale'; 
                             } else {
                                 stateClasses = 'hover:scale-105'; 
                             }

                             return (
                                 <div 
                                    key={def.id} 
                                    className={`relative transition-all duration-300 rounded-md ${stateClasses}`}
                                    onPointerDown={(e) => {
                                        // Always allow pointer down for inspection detection in useCollectionDrag
                                        e.stopPropagation(); 
                                        onPointerDown(e, def);
                                    }}
                                    onContextMenu={(e) => e.preventDefault()}
                                 >
                                     <div className="aspect-[5/7] rounded-md transition-all duration-300 cursor-grab active:cursor-grabbing">
                                         <Card 
                                            card={def} 
                                            size="xs" 
                                            variant="default" 
                                         />
                                     </div>
                                 </div>
                             );
                         })}
                     </div>
                 )}

                 <div className="h-12 w-full flex items-center justify-center mt-12 mb-8 pointer-events-none">
                     <div className="text-[0.55rem] text-slate-800 font-black uppercase tracking-[0.5em]">Terminal Archive End</div>
                 </div>
            </div>
        </div>
    );
}

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { CardDefinition } from '../types';
import { useUser } from '../contexts/UserContext';

export interface CollectionDragState {
  card: CardDefinition;
  origin: 'archive' | 'vault';
  startPos: { x: number; y: number };
  currentPos: { x: number; y: number };
  offset: { x: number; y: number };
  rect: DOMRect;
  active: boolean;
}

interface UseCollectionDragProps {
  onAdd: (id: string) => void;
  onRemove: (id: string) => void;
  scrollRef: React.RefObject<HTMLElement>;
}

// Physics Constants
const DRAG_THRESHOLD = 6; // Tightened for better tap detection
const SCROLL_THRESHOLD = 4;
const PICKUP_DELAY = 120;
const FRICTION = 0.95; 
const BOUNCE_FRICTION = 0.8;
const SPRING_STRENGTH = 0.15;
const MIN_VELOCITY = 0.1;

export const useCollectionDrag = ({ onAdd, onRemove, scrollRef }: UseCollectionDragProps) => {
    const { user, inspect } = useUser();
    const [dragState, setDragState] = useState<CollectionDragState | null>(null);

    const stateRef = useRef({
        isScrolling: false,
        isDragging: false,
        canDrag: false,
        startPos: { x: 0, y: 0 },
        startScrollTop: 0,
        hasCard: false,
        lastY: 0,
        lastTime: 0,
        velocity: 0,
        overscroll: 0, 
        samples: [] as { dy: number, dt: number }[]
    });

    const animationFrameRef = useRef<number | null>(null);
    const dragTargetRef = useRef<HTMLElement | null>(null);
    const pickupTimerRef = useRef<number | null>(null);

    const runPhysics = useCallback(() => {
        const el = scrollRef.current;
        if (!el) return;

        const s = stateRef.current;
        const maxScroll = el.scrollHeight - el.clientHeight;
        let currentScroll = el.scrollTop;

        if (currentScroll < 0 || currentScroll > maxScroll) {
            const target = currentScroll < 0 ? 0 : maxScroll;
            const diff = target - currentScroll;
            s.velocity = (s.velocity + diff * SPRING_STRENGTH) * BOUNCE_FRICTION;

            if (Math.abs(diff) < 1 && Math.abs(s.velocity) < 1) {
                el.scrollTop = target;
                s.velocity = 0;
                animationFrameRef.current = null;
                return;
            }
        } else {
            s.velocity *= FRICTION;
        }

        el.scrollTop -= s.velocity;

        if (Math.abs(s.velocity) > MIN_VELOCITY || currentScroll < 0 || currentScroll > maxScroll) {
            animationFrameRef.current = requestAnimationFrame(runPhysics);
        } else {
            s.velocity = 0;
            animationFrameRef.current = null;
        }
    }, [scrollRef]);

    const stopPhysics = useCallback(() => {
        if (animationFrameRef.current !== null) {
            cancelAnimationFrame(animationFrameRef.current);
            animationFrameRef.current = null;
        }
    }, []);

    const handlePointerDown = useCallback((
        e: React.PointerEvent, 
        card: CardDefinition | null,
        origin: 'archive' | 'vault'
    ) => {
        if (e.button !== 0) return;

        stopPhysics();

        const target = e.currentTarget as HTMLElement;
        dragTargetRef.current = target;
        try { target.setPointerCapture(e.pointerId); } catch (err) {}

        const rect = target.getBoundingClientRect();
        const startPos = { x: e.clientX, y: e.clientY };

        // DRAG ELIGIBILITY CHECK
        const isOwned = user.collection.includes(card?.id || '');
        const inDeck = user.decks[user.activeDeckId]?.includes(card?.id || '');
        const canDrag = card && (origin === 'vault' || (isOwned && !inDeck));

        stateRef.current = {
            isScrolling: false,
            isDragging: false,
            canDrag: !!canDrag,
            startPos,
            startScrollTop: scrollRef.current?.scrollTop || 0,
            hasCard: !!card,
            lastY: e.clientY,
            lastTime: performance.now(),
            velocity: 0,
            overscroll: 0,
            samples: []
        };

        setDragState({
            card: card || ({} as CardDefinition),
            origin,
            active: false,
            startPos,
            currentPos: startPos,
            rect,
            offset: card ? { x: e.clientX - rect.left, y: e.clientY - rect.top } : { x: 0, y: 0 },
        });

        if (canDrag) {
            if (origin === 'vault') {
                // Instantly lift vault cards
                stateRef.current.isDragging = true;
                setDragState(prev => prev ? { ...prev, active: true } : null);
            } else {
                pickupTimerRef.current = window.setTimeout(() => {
                    if (!stateRef.current.isScrolling) {
                        stateRef.current.isDragging = true;
                        setDragState(prev => prev ? { ...prev, active: true } : null);
                    }
                }, PICKUP_DELAY);
            }
        }

    }, [scrollRef, stopPhysics, user.collection, user.decks, user.activeDeckId]);

    useEffect(() => {
        if (!dragState) return;

        const handlePointerMove = (e: PointerEvent) => {
            const s = stateRef.current;
            const el = scrollRef.current;
            const now = performance.now();
            const dt = now - s.lastTime;
            const deltaX = e.clientX - s.startPos.x;
            const deltaY = e.clientY - s.startPos.y;

            if (dt > 0) {
                const dy = e.clientY - s.lastY;
                s.samples.push({ dy, dt });
                if (s.samples.length > 3) s.samples.shift();

                const totalDy = s.samples.reduce((sum, val) => sum + val.dy, 0);
                const totalDt = s.samples.reduce((sum, val) => sum + val.dt, 0);
                s.velocity = totalDy / (totalDt / 16.67);

                s.lastY = e.clientY;
                s.lastTime = now;
            }

            if (!s.isScrolling && !s.isDragging) {
                const absX = Math.abs(deltaX);
                const absY = Math.abs(deltaY);

                if (absY > SCROLL_THRESHOLD) {
                    const isFastSwipe = Math.abs(s.velocity) > 12;
                    if (s.hasCard && s.canDrag && !isFastSwipe && deltaY < 0 && absY > DRAG_THRESHOLD) {
                        s.isDragging = true;
                        if (pickupTimerRef.current) clearTimeout(pickupTimerRef.current);
                        setDragState(prev => prev ? { ...prev, active: true, currentPos: { x: e.clientX, y: e.clientY } } : null);
                    } else {
                        s.isScrolling = true;
                        if (pickupTimerRef.current) clearTimeout(pickupTimerRef.current);
                    }
                } else if (absX > DRAG_THRESHOLD && s.hasCard && s.canDrag) {
                    s.isDragging = true;
                    if (pickupTimerRef.current) clearTimeout(pickupTimerRef.current);
                    setDragState(prev => prev ? { ...prev, active: true, currentPos: { x: e.clientX, y: e.clientY } } : null);
                }
            }

            if (s.isScrolling && el) {
                // Prevent browser "native" overscroll pull when we are handling the list
                if (e.cancelable) e.preventDefault();

                const maxScroll = el.scrollHeight - el.clientHeight;
                let targetScroll = s.startScrollTop - deltaY;
                if (targetScroll < 0) targetScroll = targetScroll * 0.4;
                else if (targetScroll > maxScroll) targetScroll = maxScroll + ((targetScroll - maxScroll) * 0.4);
                el.scrollTop = targetScroll;
                return;
            }

            if (s.isDragging) {
                if (e.cancelable) e.preventDefault();
                setDragState(prev => prev ? { ...prev, currentPos: { x: e.clientX, y: e.clientY } } : null);
            }
        };

        const handlePointerUp = (e: PointerEvent) => {
            if (pickupTimerRef.current) clearTimeout(pickupTimerRef.current);
            if (dragTargetRef.current) {
                try { dragTargetRef.current.releasePointerCapture(e.pointerId); } catch (err) {}
                dragTargetRef.current = null;
            }

            const s = stateRef.current;
            const { isDragging, isScrolling, startPos, hasCard } = s;

            // Start kinetic movement or spring-back
            if (isScrolling || (scrollRef.current && (scrollRef.current.scrollTop < 0 || scrollRef.current.scrollTop > scrollRef.current.scrollHeight - scrollRef.current.clientHeight))) {
                animationFrameRef.current = requestAnimationFrame(runPhysics);
            }

            const dist = Math.hypot(e.clientX - startPos.x, e.clientY - startPos.y);

            // PRIORITY 1: INSPECTION (TAP)
            // If the finger hasn't moved much, it's a tap regardless of isDragging state.
            // This fixes Vault cards which are set to 'isDragging' instantly.
            if (hasCard && dist < DRAG_THRESHOLD) {
                inspect(dragState.card);
            } 
            // PRIORITY 2: DROP LOGIC
            else if (isDragging && hasCard) {
                const els = document.elementsFromPoint(e.clientX, e.clientY);
                const vaultZone = els.find((el) => el.getAttribute('data-drop-zone') === 'vault');
                const archiveZone = els.find((el) => el.getAttribute('data-drop-zone') === 'archive');

                if (dragState.origin === 'archive' && vaultZone) {
                    onAdd(dragState.card.id);
                } else if (dragState.origin === 'vault' && (archiveZone || !user.collection.includes(dragState.card.id))) {
                    onRemove(dragState.card.id);
                }
            }

            setDragState(null);
            s.isScrolling = false;
            s.isDragging = false;
        };

        window.addEventListener('pointermove', handlePointerMove, { passive: false });
        window.addEventListener('pointerup', handlePointerUp);
        window.addEventListener('pointercancel', handlePointerUp);

        return () => {
            window.removeEventListener('pointermove', handlePointerMove);
            window.removeEventListener('pointerup', handlePointerUp);
            window.removeEventListener('pointercancel', handlePointerUp);
            if (pickupTimerRef.current) clearTimeout(pickupTimerRef.current);
        };
    }, [dragState, inspect, onAdd, onRemove, scrollRef, runPhysics, user]);

    return { dragState, handlePointerDown };
};

