import React, { useState, useEffect, useCallback, useRef } from 'react';
import { CardDefinition } from '../types';
import { useUser } from '../contexts/UserContext';

export interface CollectionDragState {
  card: CardDefinition;
  origin: 'archive' | 'vault';
  startPos: { x: number; y: number };
  currentPos: { x: number; y: number };
  offset: { x: number; y: number };
  rect: DOMRect;
  active: boolean;
}

interface UseCollectionDragProps {
  onAdd: (id: string) => void;
  onRemove: (id: string) => void;
  scrollRef: React.RefObject<HTMLElement>;
}

// Physics & Gesture Constants
const DRAG_THRESHOLD = 6;    // How far to move before showing the "ghost" card
const TAP_THRESHOLD = 14;     // Forgiving threshold for inspection (accounts for thumb roll at edges)
const SCROLL_THRESHOLD = 4;
const PICKUP_DELAY = 120;
const FRICTION = 0.95; 
const BOUNCE_FRICTION = 0.8;
const SPRING_STRENGTH = 0.15;
const MIN_VELOCITY = 0.1;

export const useCollectionDrag = ({ onAdd, onRemove, scrollRef }: UseCollectionDragProps) => {
    const { user, inspect } = useUser();
    const [dragState, setDragState] = useState<CollectionDragState | null>(null);

    const stateRef = useRef({
        isScrolling: false,
        isDragging: false,
        canDrag: false,
        startPos: { x: 0, y: 0 },
        startScrollTop: 0,
        hasCard: false,
        lastY: 0,
        lastTime: 0,
        velocity: 0,
        overscroll: 0, 
        samples: [] as { dy: number, dt: number }[]
    });

    const animationFrameRef = useRef<number | null>(null);
    const dragTargetRef = useRef<HTMLElement | null>(null);
    const pickupTimerRef = useRef<number | null>(null);

    const runPhysics = useCallback(() => {
        const el = scrollRef.current;
        if (!el) return;

        const s = stateRef.current;
        const maxScroll = el.scrollHeight - el.clientHeight;
        let currentScroll = el.scrollTop;

        if (currentScroll < 0 || currentScroll > maxScroll) {
            const target = currentScroll < 0 ? 0 : maxScroll;
            const diff = target - currentScroll;
            s.velocity = (s.velocity + diff * SPRING_STRENGTH) * BOUNCE_FRICTION;

            if (Math.abs(diff) < 1 && Math.abs(s.velocity) < 1) {
                el.scrollTop = target;
                s.velocity = 0;
                animationFrameRef.current = null;
                return;
            }
        } else {
            s.velocity *= FRICTION;
        }

        el.scrollTop -= s.velocity;

        if (Math.abs(s.velocity) > MIN_VELOCITY || currentScroll < 0 || currentScroll > maxScroll) {
            animationFrameRef.current = requestAnimationFrame(runPhysics);
        } else {
            s.velocity = 0;
            animationFrameRef.current = null;
        }
    }, [scrollRef]);

    const stopPhysics = useCallback(() => {
        if (animationFrameRef.current !== null) {
            cancelAnimationFrame(animationFrameRef.current);
            animationFrameRef.current = null;
        }
    }, []);

    const handlePointerDown = useCallback((
        e: React.PointerEvent, 
        card: CardDefinition | null,
        origin: 'archive' | 'vault'
    ) => {
        if (e.button !== 0) return;

        stopPhysics();

        const target = e.currentTarget as HTMLElement;
        dragTargetRef.current = target;
        try { target.setPointerCapture(e.pointerId); } catch (err) {}

        const rect = target.getBoundingClientRect();
        const startPos = { x: e.clientX, y: e.clientY };

        // DRAG ELIGIBILITY CHECK
        const isOwned = user.collection.includes(card?.id || '');
        const inDeck = user.decks[user.activeDeckId]?.includes(card?.id || '');
        const canDrag = card && (origin === 'vault' || (isOwned && !inDeck));

        stateRef.current = {
            isScrolling: false,
            isDragging: false,
            canDrag: !!canDrag,
            startPos,
            startScrollTop: scrollRef.current?.scrollTop || 0,
            hasCard: !!card,
            lastY: e.clientY,
            lastTime: performance.now(),
            velocity: 0,
            overscroll: 0,
            samples: []
        };

        setDragState({
            card: card || ({} as CardDefinition),
            origin,
            active: false,
            startPos,
            currentPos: startPos,
            rect,
            offset: card ? { x: e.clientX - rect.left, y: e.clientY - rect.top } : { x: 0, y: 0 },
        });

        if (canDrag) {
            if (origin === 'vault') {
                // Instantly lift vault cards but don't set 'active' visual yet
                // Setting isDragging=true here allows movement tracking to start
                stateRef.current.isDragging = true;
            } else {
                pickupTimerRef.current = window.setTimeout(() => {
                    if (!stateRef.current.isScrolling) {
                        stateRef.current.isDragging = true;
                        setDragState(prev => prev ? { ...prev, active: true } : null);
                    }
                }, PICKUP_DELAY);
            }
        }

    }, [scrollRef, stopPhysics, user.collection, user.decks, user.activeDeckId]);

    useEffect(() => {
        if (!dragState) return;

        const handlePointerMove = (e: PointerEvent) => {
            const s = stateRef.current;
            const el = scrollRef.current;
            const now = performance.now();
            const dt = now - s.lastTime;
            const deltaX = e.clientX - s.startPos.x;
            const deltaY = e.clientY - s.startPos.y;

            if (dt > 0) {
                const dy = e.clientY - s.lastY;
                s.samples.push({ dy, dt });
                if (s.samples.length > 3) s.samples.shift();

                const totalDy = s.samples.reduce((sum, val) => sum + val.dy, 0);
                const totalDt = s.samples.reduce((sum, val) => sum + val.dt, 0);
                s.velocity = totalDy / (totalDt / 16.67);

                s.lastY = e.clientY;
                s.lastTime = now;
            }

            if (!s.isScrolling && !s.isDragging) {
                const absX = Math.abs(deltaX);
                const absY = Math.abs(deltaY);

                if (absY > SCROLL_THRESHOLD) {
                    const isFastSwipe = Math.abs(s.velocity) > 12;
                    if (s.hasCard && s.canDrag && !isFastSwipe && deltaY < 0 && absY > DRAG_THRESHOLD) {
                        s.isDragging = true;
                        if (pickupTimerRef.current) clearTimeout(pickupTimerRef.current);
                        setDragState(prev => prev ? { ...prev, active: true, currentPos: { x: e.clientX, y: e.clientY } } : null);
                    } else {
                        s.isScrolling = true;
                        if (pickupTimerRef.current) clearTimeout(pickupTimerRef.current);
                    }
                } else if (absX > DRAG_THRESHOLD && s.hasCard && s.canDrag) {
                    s.isDragging = true;
                    if (pickupTimerRef.current) clearTimeout(pickupTimerRef.current);
                    setDragState(prev => prev ? { ...prev, active: true, currentPos: { x: e.clientX, y: e.clientY } } : null);
                }
            }

            if (s.isScrolling && el) {
                if (e.cancelable) e.preventDefault();
                const maxScroll = el.scrollHeight - el.clientHeight;
                let targetScroll = s.startScrollTop - deltaY;
                if (targetScroll < 0) targetScroll = targetScroll * 0.4;
                else if (targetScroll > maxScroll) targetScroll = maxScroll + ((targetScroll - maxScroll) * 0.4);
                el.scrollTop = targetScroll;
                return;
            }

            if (s.isDragging) {
                // Threshold check for visual 'active' state if not already set
                if (!dragState.active) {
                    const dist = Math.hypot(deltaX, deltaY);
                    if (dist > DRAG_THRESHOLD) {
                        setDragState(prev => prev ? { ...prev, active: true, currentPos: { x: e.clientX, y: e.clientY } } : null);
                    }
                }

                if (dragState.active) {
                    if (e.cancelable) e.preventDefault();
                    setDragState(prev => prev ? { ...prev, currentPos: { x: e.clientX, y: e.clientY } } : null);
                }
            }
        };

        const handlePointerUp = (e: PointerEvent) => {
            if (pickupTimerRef.current) clearTimeout(pickupTimerRef.current);
            if (dragTargetRef.current) {
                try { dragTargetRef.current.releasePointerCapture(e.pointerId); } catch (err) {}
                dragTargetRef.current = null;
            }

            const s = stateRef.current;
            const { isDragging, isScrolling, startPos, hasCard } = s;

            if (isScrolling || (scrollRef.current && (scrollRef.current.scrollTop < 0 || scrollRef.current.scrollTop > scrollRef.current.scrollHeight - scrollRef.current.clientHeight))) {
                animationFrameRef.current = requestAnimationFrame(runPhysics);
            }

            const dist = Math.hypot(e.clientX - startPos.x, e.clientY - startPos.y);

            // PRIORITY 1: INSPECTION (TAP)
            // Using TAP_THRESHOLD (14px) for final decision on whether it was a tap.
            // This allows edge cards to be tapped even if the thumb rolls significantly.
            if (hasCard && dist < TAP_THRESHOLD) {
                inspect(dragState.card);
            } 
            // PRIORITY 2: DROP LOGIC
            else if (isDragging && hasCard && dragState.active) {
                const els = document.elementsFromPoint(e.clientX, e.clientY);
                const vaultZone = els.find((el) => el.getAttribute('data-drop-zone') === 'vault');
                const archiveZone = els.find((el) => el.getAttribute('data-drop-zone') === 'archive');

                if (dragState.origin === 'archive' && vaultZone) {
                    onAdd(dragState.card.id);
                } else if (dragState.origin === 'vault' && archiveZone) {
                    // Only remove if it landed CLEARLY in the archive zone.
                    // If it landed in 'no-mans land' or near a screen edge outside the zones, 
                    // we snap it back to prevent accidental removal during edge taps.
                    onRemove(dragState.card.id);
                }
            }

            setDragState(null);
            s.isScrolling = false;
            s.isDragging = false;
        };

        window.addEventListener('pointermove', handlePointerMove, { passive: false });
        window.addEventListener('pointerup', handlePointerUp);
        window.addEventListener('pointercancel', handlePointerUp);

        return () => {
            window.removeEventListener('pointermove', handlePointerMove);
            window.removeEventListener('pointerup', handlePointerUp);
            window.removeEventListener('pointercancel', handlePointerUp);
            if (pickupTimerRef.current) clearTimeout(pickupTimerRef.current);
        };
    }, [dragState, inspect, onAdd, onRemove, scrollRef, runPhysics, user]);

    return { dragState, handlePointerDown };
};

