// Gesture Constants
const DRAG_MOVE_THRESHOLD = 15; // Increased to give tap more room
const TAP_DIST_THRESHOLD = 25;  // Very forgiving tap radius
const SCROLL_MIN_THRESHOLD = 5; // Minimal scroll movement
const PICKUP_DELAY = 250;       
const FRICTION = 0.95; 
const MIN_VELOCITY = 0.1;

export const useCollectionDrag = ({ onAdd, onRemove, scrollRef, vaultRef, archiveRef }: UseCollectionDragProps) => {
    const { user, inspect } = useUser();
    const [dragState, setDragState] = useState<CollectionDragState | null>(null);

