import React, { useState, useEffect, useCallback, useRef } from 'react';
import { CardDefinition } from '../types';
import { useUser } from '../contexts/UserContext';

export interface CollectionDragState {
  card: CardDefinition;
  origin: 'archive' | 'vault';
  startPos: { x: number; y: number };
  currentPos: { x: number; y: number };
  offset: { x: number; y: number };
  rect: DOMRect;
  active: boolean;
}

interface UseCollectionDragProps {
  onAdd: (id: string) => void;
  onRemove: (id: string) => void;
  scrollRef: React.RefObject<HTMLElement>;
  vaultRef: React.RefObject<HTMLElement>;
  archiveRef: React.RefObject<HTMLElement>;
}

// Gesture Constants
const DRAG_MOVE_THRESHOLD = 15;
const SCROLL_MIN_THRESHOLD = 8;
const PICKUP_DELAY = 250;       
const FRICTION = 0.95; 
const MIN_VELOCITY = 0.1;

export const useCollectionDrag = ({ onAdd, onRemove, scrollRef, vaultRef, archiveRef }: UseCollectionDragProps) => {
    const { inspect } = useUser();
    const [dragState, setDragState] = useState<CollectionDragState | null>(null);

    // Using a ref for 'wasDragging' ensures we have immediate access in pointer handlers
    // without waiting for React state cycles.
    const stateRef = useRef({
        isScrolling: false,
        isDragging: false,
        isIntentLocked: false, 
        startPos: { x: 0, y: 0 },
        lastValidPos: { x: 0, y: 0 },
        startScrollTop: 0,
        hasCard: false,
        lastY: 0,
        lastTime: 0,
        velocity: 0,
        samples: [] as { dy: number, dt: number }[]
    });

    const inertiaFrameRef = useRef<number | null>(null);
    const dragTargetRef = useRef<HTMLElement | null>(null);
    const pickupTimerRef = useRef<number | null>(null);

    const runInertia = useCallback(() => {
        const el = scrollRef.current;
        if (!el) return;
        const g = stateRef.current;
        el.scrollTop -= g.velocity;
        g.velocity *= FRICTION;
        if (el.scrollTop <= 0 || el.scrollTop >= el.scrollHeight - el.clientHeight) g.velocity = 0;
        if (Math.abs(g.velocity) > MIN_VELOCITY) {
            inertiaFrameRef.current = requestAnimationFrame(runInertia);
        } else {
            g.velocity = 0;
            inertiaFrameRef.current = null;
        }
    }, [scrollRef]);

    const stopInertia = useCallback(() => {
        if (inertiaFrameRef.current !== null) {
            cancelAnimationFrame(inertiaFrameRef.current);
            inertiaFrameRef.current = null;
        }
    }, []);

    const handlePointerDown = useCallback((
        e: React.PointerEvent, 
        card: CardDefinition | null,
        origin: 'archive' | 'vault'
    ) => {
        if (e.button !== 0) return;
        stopInertia();

        const target = e.currentTarget as HTMLElement;
        dragTargetRef.current = target;
        try { target.setPointerCapture(e.pointerId); } catch (err) {}

        const rect = target.getBoundingClientRect();
        const startPos = { x: e.clientX, y: e.clientY };

        stateRef.current = {
            isScrolling: false,
            isDragging: false,
            isIntentLocked: false,
            startPos,
            lastValidPos: startPos,
            startScrollTop: scrollRef.current?.scrollTop || 0,
            hasCard: !!card,
            lastY: e.clientY,
            lastTime: performance.now(),
            velocity: 0,
            samples: []
        };

        setDragState({
            card: card || ({} as CardDefinition),
            origin,
            active: false,
            startPos,
            currentPos: startPos,
            rect,
            offset: card ? { x: e.clientX - rect.left, y: e.clientY - rect.top } : { x: 0, y: 0 },
        });

        if (card) {
            pickupTimerRef.current = window.setTimeout(() => {
                stateRef.current.isIntentLocked = true;
            }, PICKUP_DELAY);
        }
    }, [scrollRef, stopInertia]);

    // This is the "Magic Sauce": A unified handler for the native click
    // that cards can use to guarantee 100% reliable taps.
    const handleCardClick = useCallback((card: CardDefinition) => {
        const g = stateRef.current;
        // If the gesture engine didn't decide this was a drag or a scroll,
        // we let the inspect fire.
        if (!g.isDragging && !g.isScrolling) {
            inspect(card);
        }
    }, [inspect]);

    useEffect(() => {
        if (!dragState) return;

        const handlePointerMove = (e: PointerEvent) => {
            const g = stateRef.current;
            const now = performance.now();
            const dt = now - g.lastTime;
            const deltaX = e.clientX - g.startPos.x;
            const deltaY = e.clientY - g.startPos.y;
            const moveDist = Math.hypot(deltaX, deltaY);

            g.lastValidPos = { x: e.clientX, y: e.clientY };

            if (dt > 0) {
                const dy = e.clientY - g.lastY;
                g.samples.push({ dy, dt });
                if (g.samples.length > 3) g.samples.shift();
                const totalDy = g.samples.reduce((sum, s) => sum + s.dy, 0);
                const totalDt = g.samples.reduce((sum, s) => sum + s.dt, 0);
                g.velocity = totalDy / (totalDt / 16.67);
                g.lastY = e.clientY;
                g.lastTime = now;
            }

            if (!g.isScrolling && !g.isDragging) {
                if (Math.abs(deltaX) > DRAG_MOVE_THRESHOLD || (g.isIntentLocked && moveDist > DRAG_MOVE_THRESHOLD)) {
                    g.isDragging = true;
                    if (pickupTimerRef.current) clearTimeout(pickupTimerRef.current);
                } 
                else if (Math.abs(deltaY) > SCROLL_MIN_THRESHOLD && !g.isIntentLocked) {
                    g.isScrolling = true;
                    if (pickupTimerRef.current) clearTimeout(pickupTimerRef.current);
                }
            }

            if (g.isScrolling && scrollRef.current) {
                scrollRef.current.scrollTop = g.startScrollTop - deltaY;
                return;
            }

            if (g.isDragging) {
                if (e.cancelable) e.preventDefault();
                if (!dragState.active && moveDist > DRAG_MOVE_THRESHOLD) {
                    setDragState(prev => prev ? { ...prev, active: true } : null);
                }
                setDragState(prev => prev ? { ...prev, currentPos: { x: e.clientX, y: e.clientY } } : null);
            }
        };

        const handlePointerUp = (e: PointerEvent) => {
            if (pickupTimerRef.current) clearTimeout(pickupTimerRef.current);
            if (dragTargetRef.current) {
                try { dragTargetRef.current.releasePointerCapture(e.pointerId); } catch (err) {}
                dragTargetRef.current = null;
            }

            const g = stateRef.current;
            const endX = e.type === 'pointercancel' ? g.lastValidPos.x : e.clientX;
            const endY = e.type === 'pointercancel' ? g.lastValidPos.y : e.clientY;

            const isInside = (ref: React.RefObject<HTMLElement>, x: number, y: number) => {
                if (!ref.current) return false;
                const rect = ref.current.getBoundingClientRect();
                return x >= rect.left && x <= rect.right && y >= rect.top && y <= rect.bottom;
            };

            if (dragState.active && g.hasCard) {
                if (dragState.origin === 'archive' && isInside(vaultRef, endX, endY)) {
                    onAdd(dragState.card.id);
                } else if (dragState.origin === 'vault' && isInside(archiveRef, endX, endY)) {
                    onRemove(dragState.card.id);
                }
            }

            if (g.isScrolling && Math.abs(g.velocity) > MIN_VELOCITY) {
                inertiaFrameRef.current = requestAnimationFrame(runInertia);
            }

            setDragState(null);
            // We do NOT clear g.isDragging/isScrolling immediately. 
            // We wait a tiny bit (next tick) so that any pending onClick event
            // that fires immediately after pointerUp can still read the 'wasDragging' state.
            setTimeout(() => {
                g.isScrolling = false;
                g.isDragging = false;
            }, 0);
        };

        window.addEventListener('pointermove', handlePointerMove, { passive: false });
        window.addEventListener('pointerup', handlePointerUp);
        window.addEventListener('pointercancel', handlePointerUp);

        return () => {
            window.removeEventListener('pointermove', handlePointerMove);
            window.removeEventListener('pointerup', handlePointerUp);
            window.removeEventListener('pointercancel', handlePointerUp);
            if (pickupTimerRef.current) clearTimeout(pickupTimerRef.current);
        };
    }, [dragState, onAdd, onRemove, scrollRef, vaultRef, archiveRef, runInertia]);

    return { dragState, handlePointerDown, handleCardClick };
};

import React, { useMemo } from 'react';
import { CARDS } from '../../constants';
import { Card } from '../Card';
import { CardDefinition } from '../../types';
import { useUser } from '../../contexts/UserContext';

interface CollectionGridProps {
    scrollRef: React.RefObject<HTMLDivElement>;
    ownedIds: string[];
    activeDeckIds: string[];
    draggingCardId?: string;
    onPointerDown: (e: React.PointerEvent, card: CardDefinition | null) => void;
    onCardClick: (card: CardDefinition) => void;
}

export const CollectionGrid: React.FC<CollectionGridProps> = ({ 
    scrollRef, ownedIds, activeDeckIds, draggingCardId, onPointerDown, onCardClick
}) => {
    const { collectionSort, collectionFilterSearch, collectionFilterTags } = useUser();

    const filteredAndSortedCards = useMemo(() => {
        let results = [...CARDS];

        if (collectionFilterSearch) {
            const query = collectionFilterSearch.toLowerCase();
            results = results.filter(c => 
                c.name.toLowerCase().includes(query) || 
                c.baseText.toLowerCase().includes(query)
            );
        }

        if (collectionFilterTags.length > 0) {
            results = results.filter(c => {
                return collectionFilterTags.some(tag => {
                    if (tag === 'None') return c.tags.length === 0;
                    return c.tags.includes(tag);
                });
            });
        }

        return results.sort((a, b) => {
            const aOwned = ownedIds.includes(a.id);
            const bOwned = ownedIds.includes(b.id);
            if (aOwned !== bOwned) return aOwned ? -1 : 1;

            if (collectionSort === 'Cost') return a.baseCost - b.baseCost;
            if (collectionSort === 'Power') return b.basePower - a.basePower;
            if (collectionSort === 'Newest') {
                const aIdx = CARDS.findIndex(c => c.id === a.id);
                const bIdx = CARDS.findIndex(c => c.id === b.id);
                return bIdx - aIdx;
            }
            return a.name.localeCompare(b.name);
        });
    }, [ownedIds, collectionSort, collectionFilterSearch, collectionFilterTags]);

    return (
        <div className="w-full h-full flex flex-col">
            <div 
                ref={scrollRef} 
                className="flex-1 overflow-hidden px-4 pt-1.5 pb-52 touch-none select-none"
                onPointerDown={(e) => onPointerDown(e, null)} 
            >
                 {filteredAndSortedCards.length === 0 ? (
                     <div className="w-full py-20 flex flex-col items-center justify-center text-slate-700 pointer-events-none">
                         <svg className="w-12 h-12 mb-2 opacity-20" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                         <span className="text-[0.6rem] font-black uppercase tracking-widest">No matching cards</span>
                     </div>
                 ) : (
                     <div className="grid grid-cols-4 gap-x-2 gap-y-3">
                         {filteredAndSortedCards.map((def) => {
                             const isOwned = ownedIds.includes(def.id);
                             const inDeck = activeDeckIds.includes(def.id);
                             const isDragging = draggingCardId === def.id;

                             let stateClasses = '';
                             if (isDragging) {
                                 stateClasses = 'opacity-0';
                             } else if (!isOwned) {
                                 stateClasses = 'opacity-40 grayscale pointer-events-none scale-90';
                             } else if (inDeck) {
                                 stateClasses = 'opacity-50 grayscale'; 
                             } else {
                                 stateClasses = 'hover:scale-105'; 
                             }

                             return (
                                 <div 
                                    key={def.id} 
                                    className={`relative transition-all duration-300 rounded-md ${stateClasses}`}
                                    onPointerDown={(e) => {
                                        if (isOwned && !inDeck) {
                                            e.stopPropagation(); 
                                            onPointerDown(e, def);
                                        }
                                    }}
                                    onClick={() => isOwned && onCardClick(def)}
                                    onContextMenu={(e) => e.preventDefault()}
                                 >
                                     <div className="aspect-[5/7] rounded-md transition-all duration-300 cursor-grab active:cursor-grabbing">
                                         <Card 
                                            card={def} 
                                            size="xs" 
                                            variant="default" 
                                         />
                                     </div>
                                 </div>
                             );
                         })}
                     </div>
                 )}

                 <div className="h-12 w-full flex items-center justify-center mt-12 mb-8 pointer-events-none">
                     <div className="text-[0.55rem] text-slate-800 font-black uppercase tracking-[0.5em]">Terminal Archive End</div>
                 </div>
            </div>
        </div>
    );
}

import React, { useCallback, useMemo, useRef } from 'react';
import { StandardHeader } from '../ui/StandardHeader';
import { DeckSelector } from '../game/DeckSelector';
import { CollectionGrid } from '../deck/CollectionGrid';
import { DeckVault } from '../deck/DeckVault';
import { CollectionDragOverlay } from '../CollectionDragOverlay';
import { useUser } from '../../contexts/UserContext';
import { useCollectionDrag } from '../../hooks/useCollectionDrag';
import { CARDS } from '../../constants';
import { CardDefinition } from '../../types';

export const DeckScreen: React.FC = () => {
    const { user, updateDeck, activeDeck, setActiveDeck } = useUser();
    const scrollRef = useRef<HTMLDivElement>(null);
    const vaultRef = useRef<HTMLDivElement>(null);
    const archiveRef = useRef<HTMLDivElement>(null);

    const handleAddCard = useCallback((cardId: string) => {
        if (activeDeck.length < 12 && !activeDeck.includes(cardId)) {
            updateDeck(user.activeDeckId, [...activeDeck, cardId]);
        }
    }, [activeDeck, user.activeDeckId, updateDeck]);

    const handleRemoveCard = useCallback((cardId: string) => {
        updateDeck(user.activeDeckId, activeDeck.filter(id => id !== cardId));
    }, [activeDeck, user.activeDeckId, updateDeck]);

    const { dragState, handlePointerDown, handleCardClick } = useCollectionDrag({
        onAdd: handleAddCard,
        onRemove: handleRemoveCard,
        scrollRef: scrollRef,
        vaultRef: vaultRef,
        archiveRef: archiveRef
    });

    const deckCards = useMemo(() => {
        return activeDeck
            .map(id => CARDS.find(c => c.id === id))
            .filter((c): c is CardDefinition => !!c)
            .sort((a, b) => {
                if (a.baseCost !== b.baseCost) {
                    return a.baseCost - b.baseCost;
                }
                return a.name.localeCompare(b.name);
            });
    }, [activeDeck]);

    return (
        <div className="w-full h-full flex flex-col bg-slate-950 overflow-hidden relative">
            <StandardHeader title="Collection" showCurrency />

            <CollectionDragOverlay dragState={dragState} />

            {/* 1. DECK SELECTION & VAULT ZONE */}
            <div 
                ref={vaultRef}
                className={`shrink-0 border-b border-slate-700 z-20 transition-all duration-300 ${dragState?.active && dragState.origin === 'archive' ? 'ring-2 ring-inset ring-indigo-500/50' : ''}`}
                data-drop-zone="vault"
            >
                <DeckSelector 
                    activeDeckId={user.activeDeckId} 
                    onSelectDeck={setActiveDeck}
                />

                <div className="px-3 pb-3">
                    <DeckVault 
                        cards={deckCards} 
                        draggingCardId={dragState?.active && dragState.origin === 'vault' ? dragState.card.id : undefined}
                        onPointerDown={(e, card) => handlePointerDown(e, card, 'vault')}
                        onCardClick={handleCardClick}
                    />
                </div>
            </div>

            {/* 2. COLLECTION ARCHIVE */}
            <div 
                ref={archiveRef}
                className={`flex-1 min-h-0 relative transition-all duration-300 ${dragState?.active && dragState.origin === 'vault' ? 'bg-red-500/5' : ''}`}
                data-drop-zone="archive"
            >
                <CollectionGrid 
                    scrollRef={scrollRef}
                    ownedIds={user.collection}
                    activeDeckIds={activeDeck}
                    draggingCardId={dragState?.active && dragState.origin === 'archive' ? dragState.card.id : undefined}
                    onPointerDown={(e, card) => handlePointerDown(e, card, 'archive')}
                    onCardClick={handleCardClick}
                />
            </div>
        </div>
    );
};

import React from 'react';
import { CardDefinition } from '../../types';
import { Card } from '../Card';

interface DeckVaultProps {
    cards: CardDefinition[];
    draggingCardId?: string;
    onPointerDown: (e: React.PointerEvent, card: CardDefinition) => void;
    onCardClick: (card: CardDefinition) => void;
}

export const DeckVault: React.FC<DeckVaultProps> = ({ cards, draggingCardId, onPointerDown, onCardClick }) => {
    const slots = Array.from({ length: 12 }).map((_, i) => cards[i] || null);

    return (
        <div className="grid grid-cols-6 gap-1">
            {slots.map((card, idx) => (
                <div key={idx} className="aspect-[5/7] w-full relative">
                    {card ? (
                        <div 
                            className={`w-full h-full animate-pop group cursor-grab active:cursor-grabbing transition-opacity touch-none ${draggingCardId === card.id ? 'opacity-0' : 'opacity-100'}`}
                            onPointerDown={(e) => onPointerDown(e, card)}
                            onClick={() => onCardClick(card)}
                            onContextMenu={(e) => e.preventDefault()}
                        >
                            <Card card={card} size="xs" variant="thumbnail" />
                        </div>
                    ) : (
                        <div className="w-full h-full rounded-md border border-slate-700/50 bg-slate-950/40 flex items-center justify-center shadow-inner">
                            <div className="w-1 h-1 rounded-full bg-slate-800"></div>
                        </div>
                    )}
                </div>
            ))}
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { useUser } from '../contexts/UserContext';
import { CardInstance, CardDefinition, CardRarity } from '../types';
import { Card } from './Card';
import { LocationCard } from './LocationCard';
import { StatHistory } from './inspector/StatHistory';
import { KeywordText } from './ui/KeywordText';
import { HexButton } from './ui/HexButton';

export const InspectorOverlay: React.FC = () => {
    const { 
        user,
        inspectingCard, 
        inspectingLocation, 
        inspectingCurrency,
        upgradeCard,
        closeInspector 
    } = useUser();

    // Interaction protection: Ignore clicks for the first 150ms to prevent 
    // trailing click events from the opening tap from closing the window.
    const [isInteractionEnabled, setIsInteractionEnabled] = useState(false);

    useEffect(() => {
        if (inspectingCard || inspectingLocation || inspectingCurrency) {
            const timer = setTimeout(() => setIsInteractionEnabled(true), 150);
            return () => clearTimeout(timer);
        } else {
            setIsInteractionEnabled(false);
        }
    }, [inspectingCard, inspectingLocation, inspectingCurrency]);

    if (!inspectingCard && !inspectingLocation && !inspectingCurrency) return null;

    const isInstance = (c: any): c is CardInstance => c && 'instanceId' in c;

    const getDef = (): CardDefinition | null => {
        if (!inspectingCard) return null;
        return isInstance(inspectingCard) ? inspectingCard.def : inspectingCard as CardDefinition;
    };

    const def = getDef();

    const currentRarity = def ? (user.cardRarities[def.id] || def.rarity) : "Common";
    const rarityPath: CardRarity[] = ["Common", "Rare", "Epic", "Legendary"];
    const nextRarity = rarityPath[rarityPath.indexOf(currentRarity) + 1];
    const costMap: Record<string, number> = { "Rare": 100, "Epic": 400, "Legendary": 1000 };
    const upgradeCost = nextRarity ? costMap[nextRarity] : null;

    const handleBackgroundClick = (e: React.MouseEvent) => {
        // Only close if interaction is enabled (protection period over)
        if (isInteractionEnabled) {
            closeInspector();
        }
    };

    return (
        <div 
            className="fixed inset-0 z-[500] bg-black/90 backdrop-blur-md flex flex-col items-center justify-center p-6 animate-pop overflow-y-auto"
            onClick={handleBackgroundClick}
        >
            {/* CARD INSPECTOR */}
            {inspectingCard && def && (
                <div 
                    className="flex flex-col items-center w-full max-w-[13rem]"
                    onClick={(e) => e.stopPropagation()} 
                > 
                    <div className="relative z-40 mb-5 shadow-[0_0_3rem_rgba(0,0,0,0.8)]">
                        {isInstance(inspectingCard) && (
                            <>
                                <StatHistory modifiers={inspectingCard.costModifiers} type="cost" side="left" />
                                <StatHistory modifiers={inspectingCard.powerModifiers} type="power" side="right" />
                            </>
                        )}
                        <Card card={{ ...def, rarity: currentRarity }} size="lg" />
                    </div>

                    <div className="w-full text-center mb-4 px-1">
                         <KeywordText className="text-[0.7rem]" text={isInstance(inspectingCard) ? inspectingCard.currentText : def.baseText} />
                    </div>

                    {!isInstance(inspectingCard) && nextRarity && (
                        <div className="w-full mb-4">
                            <HexButton 
                                variant="success" 
                                fullWidth 
                                size="sm"
                                onClick={() => upgradeCard(def.id)}
                                disabled={user.credits < (upgradeCost || 0)}
                            >
                                <div className="flex items-center justify-center gap-2">
                                    <div className="flex flex-col items-start leading-none">
                                        <span className="text-[0.45rem] opacity-70">UPGRADE TO</span>
                                        <span className="text-[0.6rem]">{nextRarity.toUpperCase()}</span>
                                    </div>
                                    <div className="h-4 w-px bg-white/20"></div>
                                    <span className="text-xs">{upgradeCost} CREDITS</span>
                                </div>
                            </HexButton>
                        </div>
                    )}

                    {def.flavorText && (
                        <div className="w-full bg-slate-900/60 border border-slate-800 rounded-lg p-2 min-h-[2.5rem] flex flex-col items-center justify-center relative group overflow-hidden">
                            <p className="text-[0.55rem] text-indigo-200/70 italic leading-tight font-mono text-center px-1">
                                "{def.flavorText}"
                            </p>
                        </div>
                    )}
                </div>
            )}

            {/* LOCATION INSPECTOR */}
            {inspectingLocation && (
                <div 
                    className="relative z-40 animate-pop drop-shadow-2xl max-w-[20rem]"
                    onClick={(e) => e.stopPropagation()}
                >
                    <LocationCard location={inspectingLocation} size="lg" />
                </div>
            )}

