import React, { useState, useLayoutEffect, useRef } from 'react';

interface GameTextProps {
  text: string;
  className?: string;
  /** The starting font size in pixels (or rem, but converted to px for math) */
  baseFontSize: number;
  /** Minimum scale factor (e.g., 0.5 means it won't shrink smaller than half size) */
  minScale?: number;
}

/**
 * GameText: A Unity-style "Best Fit" text component.
 * It measures its parent container and shrinks the font size to ensure 
 * the text never wraps or overflows.
 */
export const GameText: React.FC<GameTextProps> = ({ 
  text, 
  className = '', 
  baseFontSize, 
  minScale = 0.5 
}) => {
  const [scale, setScale] = useState(1);
  const [ready, setReady] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);
  const textRef = useRef<HTMLSpanElement>(null);

  useLayoutEffect(() => {
    const container = containerRef.current;
    const textEl = textRef.current;
    if (!container || !textEl) return;

    // Reset scale to 1 to measure natural width
    textEl.style.fontSize = `${baseFontSize}px`;

    // Measure
    const containerWidth = container.offsetWidth;
    const textWidth = textEl.scrollWidth;

    if (textWidth > containerWidth && containerWidth > 0) {
      const ratio = containerWidth / textWidth;
      const finalScale = Math.max(minScale, ratio);
      setScale(finalScale);
    } else {
      setScale(1);
    }

    setReady(true);
  }, [text, baseFontSize, minScale]);

  return (
    <div 
      ref={containerRef} 
      className={`w-full overflow-hidden whitespace-nowrap flex justify-center items-center ${className}`}
    >
      <span
        ref={textRef}
        style={{ 
          fontSize: `${baseFontSize * scale}px`,
          opacity: ready ? 1 : 0 
        }}
        className="inline-block transition-opacity duration-150 leading-none font-black italic uppercase tracking-tighter"
      >
        {text}
      </span>
    </div>
  );
};

import React from 'react';
