import React, { useState, useLayoutEffect, useRef } from 'react';

interface GameTextProps {
  text: string;
  className?: string;
  /** The "Aspirational" font size. We set this high to force every card to find its own best fit. */
  baseFontSize: number;
  /** How much we allow the text to shrink. 0.2 allows for very long names. */
  minScale?: number;
}

/**
 * GameText: Unity-style "Best Fit" component.
 * It forces the text to occupy the maximum available width without ever overflowing.
 */
export const GameText: React.FC<GameTextProps> = ({ 
  text, 
  className = '', 
  baseFontSize, 
  minScale = 0.2 
}) => {
  const [scale, setScale] = useState(1);
  const containerRef = useRef<HTMLDivElement>(null);
  const textRef = useRef<HTMLSpanElement>(null);

  useLayoutEffect(() => {
    const container = containerRef.current;
    const textEl = textRef.current;
    if (!container || !textEl) return;

    const measure = () => {
      // 1. Get container width (inner width)
      const containerWidth = container.getBoundingClientRect().width;
      if (containerWidth <= 0) return;

      // 2. Measure text at full size
      // We use a temporary clone or just measure carefully to avoid flash
      textEl.style.fontSize = `${baseFontSize}px`;
      textEl.style.transform = 'scale(1)';

      const textWidth = textEl.scrollWidth;

      if (textWidth > containerWidth) {
        // 3. Calculate exact ratio with a 2% safety margin
        const ratio = (containerWidth / textWidth) * 0.98;
        setScale(Math.max(minScale, ratio));
      } else {
        setScale(1);
      }
    };

    // Initial measurement
    measure();

    // Re-measure if container size changes (e.g. during screen transitions or window resize)
    const observer = new ResizeObserver(() => {
        requestAnimationFrame(measure);
    });
    observer.observe(container);

    return () => observer.disconnect();
  }, [text, baseFontSize, minScale]);

  return (
    <div 
      ref={containerRef} 
      className={`w-full overflow-hidden whitespace-nowrap flex justify-center items-center relative ${className}`}
      style={{ height: `${baseFontSize * 1.1}px` }}
    >
      <span
        ref={textRef}
        style={{ 
          fontSize: `${baseFontSize}px`,
          transformOrigin: 'center center',
          transform: `scale(${scale})`,
          display: 'inline-block',
          whiteSpace: 'nowrap'
        }}
        className="font-black italic uppercase tracking-tighter leading-none"
      >
        {text}
      </span>
    </div>
  );
};

