import React, { useState, useLayoutEffect, useRef } from 'react';

interface GameTextProps {
  text: string;
  className?: string;
  /** The "Aspirational" font size. */
  baseFontSize: number;
  /** How much we allow the text to shrink. 0.3 is usually the limit for legibility. */
  minScale?: number;
}

/**
 * GameText: Bulletproof "Best Fit" Typography.
 * Uses a hidden ghost element to measure the "natural" width of the text at full size
 * without any interference from parent overflow or clipping rules.
 */
export const GameText: React.FC<GameTextProps> = ({ 
  text, 
  className = '', 
  baseFontSize, 
  minScale = 0.3 
}) => {
  const [scale, setScale] = useState(1);
  const containerRef = useRef<HTMLDivElement>(null);
  const ghostRef = useRef<HTMLSpanElement>(null);

  useLayoutEffect(() => {
    const container = containerRef.current;
    const ghost = ghostRef.current;
    if (!container || !ghost) return;

    const measure = () => {
      // 1. Get the actual available width of the container
      const containerWidth = container.getBoundingClientRect().width;
      if (containerWidth <= 0) return;

      // 2. Measure the "Ghost" which is NOT clipped and NOT scaled
      // Its width represents the "Ideal" space needed at 1:1 scale
      const idealWidth = ghost.offsetWidth;

      if (idealWidth > containerWidth && idealWidth > 0) {
        // 3. Calculate exact ratio with a safety buffer
        const ratio = (containerWidth / idealWidth) * 0.96;
        setScale(Math.max(minScale, ratio));
      } else {
        setScale(1);
      }
    };

    // Initial measurement
    measure();

    // Re-measure if container size changes
    const observer = new ResizeObserver(() => {
        requestAnimationFrame(measure);
    });
    observer.observe(container);

    return () => observer.disconnect();
  }, [text, baseFontSize, minScale]);

  return (
    <div 
      ref={containerRef} 
      className={`w-full overflow-hidden whitespace-nowrap flex justify-center items-center relative leading-none ${className}`}
      style={{ height: `${baseFontSize * 1.15}px` }}
    >
      {/* GHOST: Invisible, unconstrained, used only for measurement */}
      <span
        ref={ghostRef}
        className="absolute opacity-0 pointer-events-none whitespace-nowrap font-black italic uppercase tracking-tighter"
        style={{ fontSize: `${baseFontSize}px`, left: -9999 }}
      >
        {text}
      </span>

      {/* VISIBLE: Scaled to fit based on Ghost's measurement */}
      <span
        style={{ 
          fontSize: `${baseFontSize}px`,
          transformOrigin: 'center center',
          transform: `scale(${scale})`,
          display: 'inline-block',
          whiteSpace: 'nowrap'
        }}
        className="font-black italic uppercase tracking-tighter leading-none"
      >
        {text}
      </span>
    </div>
  );
};

