    };

    const spendCredits = (amount: number): boolean => {
        if (user.credits >= amount) {
            setUser(prev => ({ ...prev, credits: prev.credits - amount }));
            return true;
        }
        return false;
    };

    const addGold = (amount: number) => {
        setUser(prev => ({ ...prev, gold: prev.gold + amount }));
    };

    const spendGold = (amount: number): boolean => {
        if (user.gold >= amount) {
            setUser(prev => ({ ...prev, gold: prev.gold - amount }));
            return true;
        }
        return false;
    };

    const setActiveDeck = async (id: number) => {
        audio.playUiClick();
        try {
            const updatedUser = await api.updateActiveDeck(user, id);
            setUser(updatedUser);
        } catch (e) {
            console.error("Failed to update active deck on server:", e);
        }
    };

    const updateDeck = (deckId: number, cardIds: string[]) => {
        setUser(prev => ({
            ...prev,
            decks: { ...prev.decks, [deckId]: cardIds }
        }));
    };

    const upgradeCard = (cardId: string): boolean => {
        const currentRarity = user.cardRarities[cardId] || "Common";
        const rarityPath: CardRarity[] = ["Common", "Rare", "Epic", "Legendary"];
        const currentIndex = rarityPath.indexOf(currentRarity);

        if (currentIndex === -1 || currentIndex === rarityPath.length - 1) return false;

        const nextRarity = rarityPath[currentIndex + 1];
        const costMap: Record<string, number> = { "Rare": 100, "Epic": 400, "Legendary": 1000 };
        const cost = costMap[nextRarity];

        if (user.credits >= cost) {
            setUser(prev => ({
                ...prev,
                credits: prev.credits - cost,
                level: prev.level + (currentIndex + 1), // Gain level on upgrade
                cardRarities: { ...prev.cardRarities, [cardId]: nextRarity }
            }));
            audio.play('sfx_victory');
            return true;
        }
        return false;
    };

    const processPurchase = async (offerId: string): Promise<boolean> => {
        const transactionId = `txn_${generateInstanceId()}`;
        try {
            const response = await api.purchaseOffer(user, offerId, transactionId);
            if (response.success && response.updatedProfile) {
                audio.play('sfx_victory');
                setUser(response.updatedProfile);
                return true;
            } else {
                audio.play('sfx_ui_hover');
                return false;
            }
        } catch (err) {
            console.error("Network Exception:", err);
            return false;
        }
    };

    const activeDeck = useMemo(() => user.decks[user.activeDeckId] || [], [user.decks, user.activeDeckId]);

    return (
        <UserContext.Provider value={{ 
            user, 
            storeData,
            isStoreLoading,
            storeScrollTarget,
            setStoreScrollTarget,
            inspectingCard, 
            inspectingLocation, 
            inspectingCurrency,
            collectionSort,
            setCollectionSort,
            collectionFilterSearch,
            setCollectionFilterSearch,
            collectionFilterTags,
            toggleCollectionFilterTag,
            addCredits, 
            spendCredits, 
            addGold, 
            spendGold, 
            setActiveDeck, 
            updateDeck,
            upgradeCard,
            processPurchase,
            syncStore,
            inspect,
            closeInspector,
            activeDeck
        }}>
            {children}
        </UserContext.Provider>
    );
};

export const useUser = () => {
    const context = useContext(UserContext);
    if (!context) {
        throw new Error('useUser must be used within a UserProvider');
    }
    return context;
};

import React, { useState, useRef, useEffect } from 'react';
import { GameText } from './GameText';

type ButtonVariant = 'primary' | 'secondary' | 'success' | 'danger' | 'warning' | 'blue';

interface HexButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
    variant?: ButtonVariant;
    fullWidth?: boolean;
    size?: 'sm' | 'md' | 'lg';
    holdDuration?: number; 
    onHoldChange?: (isHolding: boolean) => void;
    onProgressChange?: (progress: number) => void;
}

export const HexButton: React.FC<HexButtonProps> = ({ 
    children, 
    variant = 'primary', 
    fullWidth = false,
    size = 'md',
    className = '',
    holdDuration = 0,
    onHoldChange,
    onProgressChange,
    onClick,
    ...props 
}) => {
    const [progress, setProgress] = useState(0);
    const [isHolding, setIsHolding] = useState(false);
    const timerRef = useRef<number | null>(null);
    const startTimeRef = useRef<number>(0);

    const variants = {
        primary: "from-purple-600 to-purple-900 border-purple-400 shadow-[0_0.2rem_0_rgb(88,28,135)]",
        secondary: "from-slate-700 to-slate-900 border-slate-500 shadow-[0_0.2rem_0_rgb(15,23,42)]",
        success: "from-emerald-600 to-emerald-900 border-emerald-400 shadow-[0_0.2rem_0_rgb(6,78,59)]",
        danger: "from-red-600 to-red-900 border-red-400 shadow-[0_0.2rem_0_rgb(127,29,29)]",
        warning: "from-amber-600 to-amber-900 border-amber-400 shadow-[0_0.2rem_0_rgb(120,53,15)]",
        blue: "from-blue-600 to-blue-900 border-blue-400 shadow-[0_0.2rem_0_rgb(30,58,138)]",
    };

    const sizeConfigs = {
        sm: { height: "h-7", fontSize: 14 },
        md: { height: "h-9", fontSize: 18 },
        lg: { height: "h-12", fontSize: 24 }
    };

    const config = sizeConfigs[size];

    const startHold = (e: React.PointerEvent) => {
        if (!holdDuration || props.disabled) return;

        setIsHolding(true);
        onHoldChange?.(true);
        startTimeRef.current = Date.now();

        timerRef.current = window.setInterval(() => {
            const elapsed = Date.now() - startTimeRef.current;
            const p = Math.min((elapsed / holdDuration) * 100, 100);
            setProgress(p);
            onProgressChange?.(p);

            if (p >= 100) {
                if (timerRef.current) clearInterval(timerRef.current);
                timerRef.current = null;

                setProgress(100);
                onProgressChange?.(100);

                setTimeout(() => {
                    if (onClick) {
                        const syntheticEvent = { 
                            clientX: e.clientX,
                            clientY: e.clientY,
                            target: e.target,
                            currentTarget: e.currentTarget,
                            type: 'click',
                            bubbles: true,
                            cancelable: true,
                            nativeEvent: e.nativeEvent,
                        } as unknown as React.MouseEvent<HTMLButtonElement>;
                        onClick(syntheticEvent);
                    }
                    setIsHolding(false);
                    onHoldChange?.(false);
                    setProgress(0);
                    onProgressChange?.(0);
                }, 60);
            }
        }, 16);
    };

    const cancelHold = () => {
        if (timerRef.current) {
            clearInterval(timerRef.current);
            timerRef.current = null;
        }
        setIsHolding(false);
        onHoldChange?.(false);
        setProgress(0);
        onProgressChange?.(0);
    };

    useEffect(() => {
        return () => {
            if (timerRef.current) clearInterval(timerRef.current);
        };
    }, []);

    const widthClass = fullWidth ? 'w-full' : 'w-max min-w-[4rem]';

    return (
        <div className={`relative group ${widthClass} ${config.height} ${props.disabled ? 'opacity-50 pointer-events-none' : ''}`}>
            <button 
                className={`w-full h-full relative z-10 active:translate-y-0.5 transition-all outline-none ${className}`}
                onPointerDown={holdDuration ? startHold : undefined}
                onPointerUp={holdDuration ? cancelHold : undefined}
                onPointerLeave={holdDuration ? cancelHold : undefined}
                onClick={holdDuration ? undefined : onClick}
                role="button"
                aria-busy={isHolding}
                {...props}
            >
                <div className={`
                    absolute inset-0 bg-gradient-to-b border rounded skew-x-[-10deg] 
                    group-hover:brightness-110 transition-all duration-200 overflow-hidden
                    ${variants[variant]}
                `}>
                    {holdDuration > 0 && (
                        <div 
                            className="absolute inset-y-0 left-0 bg-white/20 transition-all duration-75 ease-linear pointer-events-none"
                            style={{ width: `${progress}%` }}
                        />
                    )}
                </div>

                {/* 
                    CONTENT LAYER 
                    We use a container that skews back to keep text upright,
                    then pass it into GameText for auto-fitting.
                */}
                <div className="relative z-20 skew-x-[-10deg] px-4 flex items-center justify-center h-full pointer-events-none">
                    {typeof children === 'string' ? (
                        <div className={`w-full flex items-center justify-center transition-opacity ${isHolding ? 'opacity-40' : 'opacity-100'}`}>
                            <GameText 
                                text={children} 
                                baseFontSize={config.fontSize} 
                                className="text-white drop-shadow-md"
                                minScale={0.5} // Don't let buttons get microscopic
                            />
                        </div>
                    ) : (
                        <div className={`font-black text-white italic tracking-tight uppercase drop-shadow-md flex items-center gap-1 whitespace-nowrap transition-opacity ${isHolding ? 'opacity-40' : 'opacity-100'}`} style={{ fontSize: `${config.fontSize}px` }}>
                            {children}
                        </div>
                    )}
                </div>
            </button>
        </div>
    );
};

