import React, { useState } from 'react';
import { useUser, CollectionSortOption } from '../../contexts/UserContext';
import { HexButton } from '../ui/HexButton';

export const DeckCommandBar: React.FC = () => {
    const { 
        collectionSort, setCollectionSort, 
        collectionFilterSearch, setCollectionFilterSearch,
        collectionFilterTags, toggleCollectionFilterTag
    } = useUser();

    const [showSortMenu, setShowSortMenu] = useState(false);
    const [showFilterMenu, setShowFilterMenu] = useState(false);

    const sortOptions: CollectionSortOption[] = ['Cost', 'Power', 'Name', 'Newest'];
    const filterTags = [
        { label: 'On Reveal', tag: 'OnReveal' },
        { label: 'Ongoing', tag: 'Ongoing' },
        { label: 'Destroy', tag: 'Destroy' },
        { label: 'No Ability', tag: 'None' }
    ];

    return (
        <div className="w-full flex items-end justify-between px-4 pb-1.5 gap-3 relative pointer-events-none">

            {/* Popovers Layer */}
            {showSortMenu && (
                <div className="absolute bottom-16 left-4 w-40 bg-slate-800 border border-slate-600 rounded-xl shadow-2xl p-1 z-50 animate-pop flex flex-col gap-1 pointer-events-auto">
                    {sortOptions.map(opt => (
                        <button 
                            key={opt}
                            onClick={() => { setCollectionSort(opt); setShowSortMenu(false); }}
                            className={`px-3 py-2.5 rounded-lg text-left text-sm font-black flex justify-between items-center ${collectionSort === opt ? 'bg-indigo-600 text-white' : 'text-slate-300 hover:bg-slate-700'}`}
                        >
                            {opt}
                            {collectionSort === opt && <div className="w-2.5 h-2.5 rounded-full bg-white"></div>}
                        </button>
                    ))}
                </div>
            )}

            {/* Filter Menu */}
            {showFilterMenu && (
                <div className="absolute bottom-16 right-4 w-64 bg-slate-800 border border-slate-600 rounded-xl shadow-2xl p-3 z-50 animate-pop pointer-events-auto">
                    <div className="mb-3">
                        <div className="relative">
                            <input 
                                type="text" 
                                placeholder="Search cards..." 
                                value={collectionFilterSearch}
                                onChange={(e) => setCollectionFilterSearch(e.target.value)}
                                className="w-full bg-slate-900 border border-slate-700 rounded-lg py-2 pl-8 pr-3 text-sm text-white focus:outline-none focus:border-indigo-500" 
                            />
                            <svg className="w-4 h-4 text-slate-500 absolute left-2.5 top-2.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                        </div>
                    </div>
                    <div className="grid grid-cols-2 gap-2">
                        {filterTags.map(({ label, tag }) => {
                            const isActive = collectionFilterTags.includes(tag);
                            return (
                                <button 
                                    key={tag} 
                                    onClick={() => toggleCollectionFilterTag(tag)}
                                    className={`px-2 py-2 border rounded text-[0.7rem] font-black transition-colors text-center uppercase tracking-tighter ${isActive ? 'bg-indigo-600 text-white border-indigo-400' : 'bg-slate-700/50 border-slate-600 text-slate-300 hover:bg-slate-700'}`}
                                >
                                    {label}
                                </button>
                            );
                        })}
                    </div>
                </div>
            )}

            {/* Click Outside Overlay */}
            {(showSortMenu || showFilterMenu) && (
                <div className="fixed inset-0 z-40 pointer-events-auto" onClick={() => { setShowSortMenu(false); setShowFilterMenu(false); }}></div>
            )}

            {/* SORT BUTTON (Left) */}
            <HexButton 
                variant={showSortMenu ? 'primary' : 'secondary'}
                size="md"
                className="pointer-events-auto shadow-lg"
                onClick={() => { setShowSortMenu(!showSortMenu); setShowFilterMenu(false); }}
                icon={
                    <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M3 4h13M3 8h9m-9 4h6m4 0l4-4m0 0l4 4m-4-4v12" />
                    </svg>
                }
            />

            {/* FILTER BUTTON (Right) */}
            <HexButton 
                variant={showFilterMenu ? 'primary' : 'secondary'}
                size="md"
                className="pointer-events-auto shadow-lg"
