import { DeckCommandBar } from '../navigation/DeckCommandBar';
import { InboxCommandBar } from '../navigation/InboxCommandBar';
import { NavItem } from '../navigation/NavItem';

interface NavigationBarProps {
    activeScreen: ScreenKey;
    onNavigate: (screen: ScreenKey) => void;
}

export const NavigationBar: React.FC<NavigationBarProps> = ({ activeScreen, onNavigate }) => {

    // Determine which Command Bar to show based on context
    const renderCommandBar = () => {
        switch (activeScreen) {
            case 'MENU':
                return <HomeCommandBar onNavigate={onNavigate} />;
            case 'DECK':
                return <DeckCommandBar />;
            case 'INBOX':
                return <InboxCommandBar />;
            case 'STORE':
            case 'COMIC':
            case 'HISTORY':
            default:
                return null; // No command bar for these screens
        }
    };

    const commandBar = renderCommandBar();

    return (
        <div className="fixed bottom-0 left-0 right-0 z-50 max-w-[23rem] mx-auto pointer-events-none flex flex-col justify-end h-auto select-none">

            {/* CONTEXT-AWARE COMMAND BAR */}
            <div className="pointer-events-none relative z-50 transition-all duration-300 ease-in-out">
                {/* Backdrop for the command bar when active */}
                {commandBar && (
                    <div className="absolute inset-x-0 bottom-0 -top-12 bg-gradient-to-t from-black/95 via-black/60 to-transparent -z-10 pointer-events-none" />
                )}
                {commandBar}
            </div>

            {/* BOTTOM NAV BAR - GROUNDED HUD STYLE */}
            <div className="h-[3.8rem] flex items-center justify-between px-3 gap-2 pointer-events-auto relative z-40 pb-2 bg-black/90 backdrop-blur-md border-t border-white/5">
                <NavItem 
                    label="Store" 
                    active={activeScreen === 'STORE'}
                    onClick={() => onNavigate('STORE')}
                    icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z" /></svg>}
                />

                <NavItem 
                    label="Collection" 
                    active={activeScreen === 'DECK'}
                    onClick={() => onNavigate('DECK')}
                    icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" /></svg>}
                />

                <NavItem 
                    label="Main" 
                    active={activeScreen === 'MENU'}
                    onClick={() => onNavigate('MENU')}
                    icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>}
                />

                <NavItem 
                    label="Inbox" 
                    active={activeScreen === 'INBOX'}
                    onClick={() => onNavigate('INBOX')}
                    icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20 13V6a2 2 0 00-2-2H6a2 2 0 00-2 2v7m16 0v5a2 2 0 01-2 2H6a2 2 0 01-2 2H6a2 2 0 01-2-2v-5m16 0h-2.586a1 1 0 00-.707.293l-2.414 2.414a1 1 0 01-.707.293h-3.172a1 1 0 01-.707-.293l-2.414-2.414A1 1 0 006.586 13H4" /></svg>}
                />

                <NavItem 
                    label="Lore" 
                    active={activeScreen === 'COMIC'}
                    onClick={() => onNavigate('COMIC')}
                    icon={<svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" /></svg>}
                />

            </div>
        </div>
    );
};

