import React from 'react';
import { GameText } from '../ui/GameText';

interface NavItemProps {
    label: string;
    icon: React.ReactNode;
    active: boolean;
    onClick: () => void;
}

export const NavItem: React.FC<NavItemProps> = ({ label, icon, onClick, active }) => {
    // Exact mapping of HexButton variants
    // Primary (Active) and Secondary (Inactive)
    const variantStyles = active 
        ? "from-purple-600 to-purple-900 border-purple-400 shadow-[0_0.2rem_0_rgb(88,28,135)]"
        : "from-slate-700 to-slate-900 border-slate-500 shadow-[0_0.2rem_0_rgb(15,23,42)]";

    return (
        <button 
            onClick={onClick}
            className="flex-1 h-full relative group outline-none active:translate-y-0.5 transition-transform"
        >
            {/* Hex Background Plate */}
            <div className={`
                absolute inset-0 rounded skew-x-[-10deg] border transition-all duration-300 bg-gradient-to-b
                ${variantStyles}
                ${active ? 'opacity-100 shadow-[0_0_20px_rgba(168,85,247,0.3),0_0.2rem_0_rgb(88,28,135)]' : 'opacity-80 group-hover:opacity-100'}
            `} />

            {/* Content Layer */}
            <div className={`
                relative h-full flex flex-col items-center justify-center transition-all duration-300 skew-x-[-10deg]
                ${active ? 'text-white' : 'text-slate-400'}
            `}>
                <div className={`transition-all duration-300 ${active ? 'scale-110 drop-shadow-[0_0_10px_rgba(255,255,255,0.4)]' : 'group-hover:text-slate-200'}`}>
                    {icon}
                </div>

                {/* Adaptive Label Container */}
                <div className="w-full h-3 px-1 mt-0.5">
                    <GameText 
                        text={label}
                        baseFontSize={14}
                        minScale={0.4}
                        className={`transition-all duration-300 ${active ? 'text-indigo-200 drop-shadow-[0_0_8px_rgba(129,140,248,0.5)]' : 'text-slate-500 group-hover:text-slate-400'}`}
                    />
                </div>
            </div>
        </button>
    );
};

