import React, { useState, useRef, useEffect } from 'react';
import { GameText } from './GameText';

type ButtonVariant = 'primary' | 'secondary' | 'success' | 'danger' | 'warning' | 'blue';

interface HexButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
    variant?: ButtonVariant;
    fullWidth?: boolean;
    size?: 'sm' | 'md' | 'lg';
    icon?: React.ReactNode;
    holdDuration?: number; 
    onHoldChange?: (isHolding: boolean) => void;
    onProgressChange?: (progress: number) => void;
}

export const HexButton: React.FC<HexButtonProps> = ({ 
    children, 
    variant = 'primary', 
    fullWidth = false,
    size = 'md',
    icon,
    className = '',
    holdDuration = 0,
    onHoldChange,
    onProgressChange,
    onClick,
    ...props 
}) => {
    const [progress, setProgress] = useState(0);
    const [isHolding, setIsHolding] = useState(false);
    const timerRef = useRef<number | null>(null);
    const startTimeRef = useRef<number>(0);

    const variants = {
        primary: "from-purple-600 to-purple-900 border-purple-400 shadow-[0_0.2rem_0_rgb(88,28,135)]",
        secondary: "from-slate-700 to-slate-900 border-slate-500 shadow-[0_0.2rem_0_rgb(15,23,42)]",
        success: "from-emerald-600 to-emerald-900 border-emerald-400 shadow-[0_0.2rem_0_rgb(6,78,59)]",
        danger: "from-red-600 to-red-900 border-red-400 shadow-[0_0.2rem_0_rgb(127,29,29)]",
        warning: "from-amber-600 to-amber-900 border-amber-400 shadow-[0_0.2rem_0_rgb(120,53,15)]",
        blue: "from-blue-600 to-blue-900 border-blue-400 shadow-[0_0.2rem_0_rgb(30,58,138)]",
    };

    const sizeConfigs = {
        sm: { height: "h-8", fontSize: 18, padding: "px-3" },
        md: { height: "h-10", fontSize: 22, padding: "px-4" },
        lg: { height: "h-14", fontSize: 28, padding: "px-6" }
    };

    const config = sizeConfigs[size];

    const startHold = (e: React.PointerEvent) => {
        if (!holdDuration || props.disabled) return;

        setIsHolding(true);
        onHoldChange?.(true);
        startTimeRef.current = Date.now();

        timerRef.current = window.setInterval(() => {
            const elapsed = Date.now() - startTimeRef.current;
            const p = Math.min((elapsed / holdDuration) * 100, 100);
            setProgress(p);
            onProgressChange?.(p);

            if (p >= 100) {
                if (timerRef.current) clearInterval(timerRef.current);
                timerRef.current = null;

                setProgress(100);
                onProgressChange?.(100);

                setTimeout(() => {
                    if (onClick) {
                        const syntheticEvent = { 
                            clientX: e.clientX,
                            clientY: e.clientY,
                            target: e.target,
                            currentTarget: e.currentTarget,
                            type: 'click',
                            bubbles: true,
                            cancelable: true,
                            nativeEvent: e.nativeEvent,
                        } as unknown as React.MouseEvent<HTMLButtonElement>;
                        onClick(syntheticEvent);
                    }
                    setIsHolding(false);
                    onHoldChange?.(false);
                    setProgress(0);
                    onProgressChange?.(0);
                }, 60);
            }
        }, 16);
    };

    const cancelHold = () => {
        if (timerRef.current) {
            clearInterval(timerRef.current);
            timerRef.current = null;
        }
        setIsHolding(false);
        onHoldChange?.(false);
        setProgress(0);
        onProgressChange?.(0);
    };

    useEffect(() => {
        return () => {
            if (timerRef.current) clearInterval(timerRef.current);
        };
    }, []);

    const widthClass = fullWidth ? 'w-full' : 'w-max min-w-[3.5rem]';

    return (
        <div className={`relative group ${widthClass} ${config.height} ${props.disabled ? 'opacity-50 pointer-events-none' : ''}`}>
            <button 
                className={`w-full h-full relative z-10 active:translate-y-0.5 transition-all outline-none ${className}`}
                onPointerDown={holdDuration ? startHold : undefined}
                onPointerUp={holdDuration ? cancelHold : undefined}
                onPointerLeave={holdDuration ? cancelHold : undefined}
                onClick={holdDuration ? undefined : onClick}
                role="button"
                aria-busy={isHolding}
                {...props}
            >
                <div className={`
                    absolute inset-0 bg-gradient-to-b border rounded skew-x-[-10deg] 
                    group-hover:brightness-110 transition-all duration-200 overflow-hidden
                    ${variants[variant]}
                `}>
                    {holdDuration > 0 && (
                        <div 
                            className="absolute inset-y-0 left-0 bg-white/20 transition-all duration-75 ease-linear pointer-events-none"
                            style={{ width: `${progress}%` }}
                        />
                    )}
                </div>

                <div className={`relative z-20 skew-x-[-10deg] ${config.padding} flex items-center justify-center h-full pointer-events-none`}>
                    <div className={`w-full h-full flex items-center justify-center gap-1 transition-opacity ${isHolding ? 'opacity-40' : 'opacity-100'}`}>
                        {icon && (
                            <div className="shrink-0 flex items-center justify-center">
                                {icon}
                            </div>
                        )}

                        {typeof children === 'string' ? (
                            <div className="flex-1 h-full min-w-0">
                                <GameText 
                                    text={children} 
                                    baseFontSize={config.fontSize} 
                                    className="text-white drop-shadow-md"
                                    minScale={0.3} 
                                />
                            </div>
                        ) : (
                            <div className="font-black text-white italic tracking-tight uppercase drop-shadow-md flex items-center gap-1 h-full w-full" style={{ fontSize: `${config.fontSize}px` }}>
                                {children}
                            </div>
                        )}
                    </div>
                </div>
            </button>
        </div>
    );
};

import React, { useState, useLayoutEffect, useRef } from 'react';

interface GameTextProps {
  text: string;
  className?: string;
  /** The "Aspirational" font size. */
  baseFontSize: number;
  /** How much we allow the text to shrink. 0.3 is usually the limit for legibility. */
  minScale?: number;
  /** If > 1, allows the text to wrap and scales based on both width and height. */
  maxLines?: number;
}

/**
 * GameText: Bulletproof "Best Fit" Typography.
 * Intelligent scaling that respects single-line punchiness while supporting multi-line area fitting.
 */
export const GameText: React.FC<GameTextProps> = ({ 
  text, 
  className = '', 
  baseFontSize, 
  minScale = 0.3,
  maxLines = 1
}) => {
  const [scale, setScale] = useState(1);
  const containerRef = useRef<HTMLDivElement>(null);
  const ghostRef = useRef<HTMLSpanElement>(null);

  useLayoutEffect(() => {
    const container = containerRef.current;
    const ghost = ghostRef.current;
    if (!container || !ghost) return;

    const measure = () => {
      const rect = container.getBoundingClientRect();
      const containerWidth = rect.width;
      const containerHeight = rect.height;

      // Safety check for unmounted or hidden containers
      if (containerWidth <= 0 || containerHeight <= 0) return;

      // 1. Measure the "Ideal" space needed (Ghost is at 1.0 scale)
      // For multi-line, we force the ghost to wrap at the same width as the container
      if (maxLines > 1) {
          ghost.style.width = `${containerWidth}px`;
          ghost.style.whiteSpace = 'normal';
      } else {
          ghost.style.width = 'auto';
          ghost.style.whiteSpace = 'nowrap';
      }

      const idealWidth = ghost.offsetWidth;
      const idealHeight = ghost.offsetHeight;

      if (idealWidth <= 0 || idealHeight <= 0) return;

      // 2. Calculate scaling ratios
      const widthRatio = (containerWidth / idealWidth) * 0.98;
      const heightRatio = (containerHeight / idealHeight) * 0.98;

      let finalRatio = widthRatio;

      // 3. Logic: Only constrain by height if we are multi-line 
      // OR if the single line is physically too tall for the box.
      if (maxLines > 1 || idealHeight > containerHeight) {
          finalRatio = Math.min(widthRatio, heightRatio);
      }

      // Clamp to [minScale, 1.0]
      setScale(Math.max(minScale, Math.min(1, finalRatio)));
    };

    measure();

    const observer = new ResizeObserver(() => {
        requestAnimationFrame(measure);
    });
    observer.observe(container);

    return () => observer.disconnect();
  }, [text, baseFontSize, minScale, maxLines]);

  return (
    <div 
      ref={containerRef} 
      className={`w-full h-full flex justify-center items-center relative leading-tight ${className}`}
    >
      {/* GHOST: Invisible, used for measurement. */}
      <span
        ref={ghostRef}
        className={`absolute opacity-0 pointer-events-none font-black italic uppercase tracking-tighter inline-block`}
        style={{ 
            fontSize: `${baseFontSize}px`, 
            left: -9999,
        }}
      >
        {text}
      </span>

      {/* VISIBLE: Scaled to fit based on Ghost's measurement */}
      <span
        style={{ 
          fontSize: `${baseFontSize}px`,
          transformOrigin: 'center center',
          transform: `scale(${scale})`,
          display: 'inline-block',
          textAlign: 'center',
          width: maxLines > 1 ? '100%' : 'auto'
        }}
        className={`font-black italic uppercase tracking-tighter leading-none ${maxLines === 1 ? 'whitespace-nowrap' : ''}`}
      >
        {text}
      </span>
    </div>
  );
};

import React, { useState } from 'react';
import { useUser } from '../../contexts/UserContext';
import { CARDS } from '../../constants';
import { HexButton } from '../ui/HexButton';
import { GameText } from '../ui/GameText';

interface DeckSelectorProps {
    activeDeckId: number;
    onSelectDeck: (id: number) => void;
}

export const DeckSelector: React.FC<DeckSelectorProps> = ({ activeDeckId, onSelectDeck }) => {
    const { user } = useUser();
    const [flippedId, setFlippedId] = useState<number | null>(null);

    const handleDeckClick = (id: number) => {
        if (activeDeckId === id) {
            setFlippedId(flippedId === id ? null : id);
        } else {
            onSelectDeck(id);
            setFlippedId(null);
        }
    };

    const getStats = (deckId: number) => {
        const cardIds = user.decks[deckId] || [];
        if (cardIds.length === 0) return { avgCost: 0, avgPower: 0, count: 0 };

        const deckCards = cardIds.map(id => CARDS.find(c => c.id === id)).filter(Boolean);
        const totalCost = deckCards.reduce((acc, c) => acc + (c?.baseCost || 0), 0);
        const totalPower = deckCards.reduce((acc, c) => acc + (c?.basePower || 0), 0);

        return {
            avgCost: (totalCost / deckCards.length).toFixed(1),
            avgPower: (totalPower / deckCards.length).toFixed(1),
            count: deckCards.length
        };
    };

    return (
        <div className="w-full flex overflow-x-auto py-2 px-3 gap-2 shrink-0 scrollbar-hide perspective-1000">
            {[1, 2, 3].map(i => {
                const isSelected = activeDeckId === i;
                const isFlipped = flippedId === i && isSelected;
                const stats = getStats(i);
                const deckName = user.deckNames[i] || 'UNTITLED';
                const isIncomplete = stats.count < 12;

                return (
                    <div 
                        key={i} 
                        className="min-w-[7.5rem] h-14 relative"
                    >
                        <div className={`
                            w-full h-full relative transition-transform duration-500 transform-style-3d
                            ${isFlipped ? 'rotate-y-180' : ''}
                        `}>
                            {/* FRONT: HexButton View */}
                            <div className="absolute inset-0 backface-hidden">
                                <HexButton 
