import React, { useState, useLayoutEffect, useRef } from 'react';

interface GameTextProps {
  text: string;
  className?: string;
  /** The "Aspirational" font size. */
  baseFontSize: number;
  /** How much we allow the text to shrink. 0.3 is usually the limit for legibility. */
  minScale?: number;
  /** If > 1, allows the text to wrap and scales based on both width and height. */
  maxLines?: number;
}

/**
 * GameText: Iterative Balanced-Wrap Typography.
 * 1. Tries to fit on 1 line.
 * 2. If scale is too small, tries 2, then 3, then 4 lines.
 * 3. For each line count, it finds the "most balanced" word-split (minimizing width variance).
 * 4. Selects the configuration with the highest resulting scale.
 */
export const GameText: React.FC<GameTextProps> = ({ 
  text, 
  className = '', 
  baseFontSize, 
  minScale = 0.3,
  maxLines = 1
}) => {
  const [layout, setLayout] = useState<{ lines: string[], scale: number }>({ lines: [text], scale: 1 });
  const containerRef = useRef<HTMLDivElement>(null);
  const ghostRef = useRef<HTMLDivElement>(null);

  useLayoutEffect(() => {
    const container = containerRef.current;
    const ghost = ghostRef.current;
    if (!container || !ghost) return;

    const words = text.split(/\s+/);

    /**
     * Helper: Splits words into N lines as evenly as possible (by character length).
     */
    const splitIntoLines = (numLines: number): string[] => {
      if (numLines <= 1 || words.length <= 1) return [text];

      const totalChars = text.length;
      const targetCharsPerLine = totalChars / numLines;

      const result: string[][] = Array.from({ length: numLines }, () => []);
      let currentLine = 0;
      let currentChars = 0;

      words.forEach((word, idx) => {
        // Decide if we should move to next line
        // If we aren't on the last line, and adding this word puts us over the target, 
        // check if it's better to stay or move.
        if (currentLine < numLines - 1) {
            const charsIfStay = currentChars + word.length;
            const distIfStay = Math.abs(charsIfStay - targetCharsPerLine);
            const distIfMove = Math.abs(currentChars - targetCharsPerLine);

            // Heuristic: if current line is already non-empty and moving is "closer" to target
            if (currentChars > 0 && distIfMove < distIfStay) {
                currentLine++;
                currentChars = 0;
            }
        }

        result[currentLine].push(word);
        currentChars += word.length + 1; // +1 for space
      });

      return result.map(l => l.join(' ')).filter(s => s.length > 0);
    };

    const measureLayout = (lines: string[]) => {
      // Setup ghost for measurement
      ghost.innerHTML = lines.map(l => `<div>${l}</div>`).join('');
      ghost.style.fontSize = `${baseFontSize}px`;

      const containerWidth = container.offsetWidth;
      const containerHeight = container.offsetHeight;

      if (containerWidth <= 0 || containerHeight <= 0) return 0;

      // Measure ghost
      const ghostWidth = ghost.offsetWidth;
      const ghostHeight = ghost.offsetHeight;

      if (ghostWidth <= 0 || ghostHeight <= 0) return 0;

      const widthRatio = (containerWidth / ghostWidth) * 0.96;
      const heightRatio = (containerHeight / ghostHeight) * 0.96;

      // For single line, we don't care about height unless it's physically taller than the box
      if (lines.length === 1 && ghostHeight <= containerHeight) {
          return Math.min(1, widthRatio);
      }

      return Math.min(1, widthRatio, heightRatio);
    };

    const findBestLayout = () => {
      let bestScale = 0;
      let bestLines: string[] = [text];

      // Test 1 line up to maxLines
      const limit = Math.min(maxLines, 4); 
      for (let i = 1; i <= limit; i++) {
        // Don't try more lines than words
        if (i > words.length) break;

        const candidateLines = splitIntoLines(i);
        const scale = measureLayout(candidateLines);

        // We want the layout that gives us the BIGGEST text.
        // If a multi-line layout allows a significantly better scale, we take it.
        // We add a small bias (0.1) for fewer lines to keep it "punchy".
        const bias = (limit - i) * 0.02; 
        if (scale + bias > bestScale) {
          bestScale = scale;
          bestLines = candidateLines;
        }

        // Optimization: if 1 line fits almost perfectly, stop.
        if (i === 1 && scale > 0.9) break;
      }

      setLayout({ 
          lines: bestLines, 
          scale: Math.max(minScale, bestScale) 
      });
    };

    findBestLayout();

    const observer = new ResizeObserver(() => {
        requestAnimationFrame(findBestLayout);
    });
    observer.observe(container);

    return () => observer.disconnect();
  }, [text, baseFontSize, minScale, maxLines]);

  return (
    <div 
      ref={containerRef} 
      className={`w-full h-full flex justify-center items-center relative leading-tight overflow-hidden ${className}`}
    >
      {/* GHOST: Invisible, used for measurement. Needs to be block/flex to measure stacked lines. */}
      <div
        ref={ghostRef}
        className="absolute opacity-0 pointer-events-none font-black italic uppercase tracking-tighter flex flex-col items-center"
        style={{ 
            fontSize: `${baseFontSize}px`, 
            left: -9999,
            whiteSpace: 'nowrap'
        }}
      />

      {/* VISIBLE: Scaled to fit based on Ghost's measurement */}
      <div
        style={{ 
          transformOrigin: 'center center',
          transform: `scale(${layout.scale})`,
          fontSize: `${baseFontSize}px`,
          width: 'max-content',
          minWidth: '100%'
        }}
        className="flex flex-col items-center justify-center leading-none"
      >
        {layout.lines.map((line, idx) => (
            <div key={idx} className="font-black italic uppercase tracking-tighter whitespace-nowrap">
                {line}
            </div>
        ))}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { useUser } from '../../contexts/UserContext';
import { CARDS } from '../../constants';
import { HexButton } from '../ui/HexButton';
import { GameText } from '../ui/GameText';

interface DeckSelectorProps {
    activeDeckId: number;
    onSelectDeck: (id: number) => void;
}

export const DeckSelector: React.FC<DeckSelectorProps> = ({ activeDeckId, onSelectDeck }) => {
    const { user } = useUser();
    const [flippedId, setFlippedId] = useState<number | null>(null);

    const handleDeckClick = (id: number) => {
        if (activeDeckId === id) {
            setFlippedId(flippedId === id ? null : id);
        } else {
            onSelectDeck(id);
            setFlippedId(null);
        }
    };

    const getStats = (deckId: number) => {
        const cardIds = user.decks[deckId] || [];
        if (cardIds.length === 0) return { avgCost: 0, avgPower: 0, count: 0 };

        const deckCards = cardIds.map(id => CARDS.find(c => c.id === id)).filter(Boolean);
        const totalCost = deckCards.reduce((acc, c) => acc + (c?.baseCost || 0), 0);
        const totalPower = deckCards.reduce((acc, c) => acc + (c?.basePower || 0), 0);

        return {
            avgCost: (totalCost / deckCards.length).toFixed(1),
            avgPower: (totalPower / deckCards.length).toFixed(1),
            count: deckCards.length
        };
    };

    return (
        /* Reduced py-2 to pt-2 pb-0.5 to minimize gap below the selector */
        <div className="w-full flex overflow-x-auto pt-2 pb-0.5 px-3 gap-2 shrink-0 scrollbar-hide perspective-1000">
            {[1, 2, 3].map(i => {
                const isSelected = activeDeckId === i;
                const isFlipped = flippedId === i && isSelected;
                const stats = getStats(i);
                const deckName = user.deckNames[i] || 'UNTITLED';
                const isIncomplete = stats.count < 12;

                return (
                    <div 
                        key={i} 
                        className="min-w-[7.5rem] h-14 relative"
                    >
                        <div className={`
                            w-full h-full relative transition-transform duration-500 transform-style-3d
                            ${isFlipped ? 'rotate-y-180' : ''}
                        `}>
                            {/* FRONT: HexButton View */}
                            <div className="absolute inset-0 backface-hidden">
                                <HexButton 
                                    variant={isSelected ? 'primary' : 'secondary'}
                                    fullWidth
                                    size="md"
                                    className="!h-full"
                                    onClick={() => handleDeckClick(i)}
                                >
                                    <div className="flex flex-col items-center justify-center w-full h-full pointer-events-none pt-1 pb-0.5">
                                        <div className="flex items-center gap-1">
                                            <span className="text-[0.45rem] font-black text-white/40 uppercase tracking-widest">Deck {i}</span>
                                            {isIncomplete && <div className="w-1.5 h-1.5 rounded-full bg-amber-500 animate-pulse shadow-[0_0_5px_rgba(245,158,11,0.8)]" />}
                                        </div>
                                        <div className="flex-1 w-full min-h-0 flex items-center justify-center">
                                            <GameText 
                                                text={deckName} 
                                                baseFontSize={22} 
                                                maxLines={2}
                                                className="text-white drop-shadow-md"
                                            />
                                        </div>
                                    </div>
                                </HexButton>
                            </div>

                            {/* BACK: STATS VIEW */}
                            <div 
                                className="absolute inset-0 backface-hidden rotate-y-180 flex items-center justify-around px-1 rounded-lg border-2 border-indigo-400 bg-indigo-900 shadow-xl cursor-pointer"
                                onClick={() => handleDeckClick(i)}
                            >
                                <div className="flex flex-col items-center">
                                    <span className="text-[0.4rem] font-black text-indigo-200 uppercase leading-none mb-1">Cost</span>
                                    <span className="text-sm font-black text-white italic">{stats.avgCost}</span>
                                </div>
                                <div className="w-px h-8 bg-white/20" />
                                <div className="flex flex-col items-center">
                                    <span className="text-[0.4rem] font-black text-indigo-200 uppercase leading-none mb-1">Power</span>
                                    <span className="text-sm font-black text-white italic">{stats.avgPower}</span>
                                </div>
                            </div>
                        </div>
                    </div>
                );
            })}

            <style>{`
                .perspective-1000 { perspective: 1000px; }
                .transform-style-3d { transform-style: preserve-3d; }
                .backface-hidden { backface-visibility: hidden; }
                .rotate-y-180 { transform: rotateY(180deg); }
            `}</style>
        </div>
    );
};

import React, { useCallback, useMemo, useRef } from 'react';
import { StandardHeader } from '../ui/StandardHeader';
import { DeckSelector } from '../game/DeckSelector';
import { CollectionGrid } from '../deck/CollectionGrid';
import { DeckVault } from '../deck/DeckVault';
import { CollectionDragOverlay } from '../CollectionDragOverlay';
import { useUser } from '../../contexts/UserContext';
import { useCollectionDrag } from '../../hooks/useCollectionDrag';
import { CARDS } from '../../constants';
import { CardDefinition } from '../../types';

export const DeckScreen: React.FC = () => {
    const { user, updateDeck, activeDeck, setActiveDeck } = useUser();
    const scrollRef = useRef<HTMLDivElement>(null);
    const vaultRef = useRef<HTMLDivElement>(null);
    const archiveRef = useRef<HTMLDivElement>(null);

    const handleAddCard = useCallback((cardId: string) => {
        if (activeDeck.length < 12 && !activeDeck.includes(cardId)) {
            updateDeck(user.activeDeckId, [...activeDeck, cardId]);
        }
    }, [activeDeck, user.activeDeckId, updateDeck]);

    const handleRemoveCard = useCallback((cardId: string) => {
        updateDeck(user.activeDeckId, activeDeck.filter(id => id !== cardId));
    }, [activeDeck, user.activeDeckId, updateDeck]);

    const { dragState, handlePointerDown } = useCollectionDrag({
        onAdd: handleAddCard,
        onRemove: handleRemoveCard,
        scrollRef: scrollRef,
        vaultRef: vaultRef,
        archiveRef: archiveRef
    });

    const deckCards = useMemo(() => {
        return activeDeck
            .map(id => CARDS.find(c => c.id === id))
            .filter((c): c is CardDefinition => !!c)
            .sort((a, b) => {
                if (a.baseCost !== b.baseCost) {
                    return a.baseCost - b.baseCost;
                }
                return a.name.localeCompare(b.name);
            });
    }, [activeDeck]);

    return (
        <div className="w-full h-full flex flex-col bg-slate-950 overflow-hidden relative">
            <StandardHeader title="Collection" showCurrency />

            <CollectionDragOverlay dragState={dragState} />

            {/* 1. DECK SELECTION & VAULT ZONE */}
            <div 
                ref={vaultRef}
                className={`shrink-0 border-b border-slate-700 z-20 transition-all duration-300 ${dragState?.active && dragState.origin === 'archive' ? 'ring-2 ring-inset ring-indigo-500/50' : ''}`}
                data-drop-zone="vault"
            >
                <DeckSelector 
                    activeDeckId={user.activeDeckId} 
                    onSelectDeck={setActiveDeck}
                />

                {/* Reduced vertical padding to pull cards closer to the selector */}
                <div className="px-3 pb-2">
                    <DeckVault 
                        cards={deckCards} 
                        draggingCardId={dragState?.active && dragState.origin === 'vault' ? dragState.card.id : undefined}
                        onPointerDown={(e, card) => handlePointerDown(e, card, 'vault')}
                    />
                </div>
            </div>

            {/* 2. COLLECTION ARCHIVE */}
            <div 
                ref={archiveRef}
                className={`flex-1 min-h-0 relative transition-all duration-300 ${dragState?.active && dragState.origin === 'vault' ? 'bg-red-500/5' : ''}`}
                data-drop-zone="archive"
            >
                <CollectionGrid 
                    scrollRef={scrollRef}
                    ownedIds={user.collection}
                    activeDeckIds={activeDeck}
                    draggingCardId={dragState?.active && dragState.origin === 'archive' ? dragState.card.id : undefined}
                    onPointerDown={(e, card) => handlePointerDown(e, card, 'archive')}
                />
            </div>
        </div>
    );
};

