import React, { useState } from 'react';
import { useUser } from '../../contexts/UserContext';
import { CARDS } from '../../constants';
import { SlantedButton } from '../ui/SlantedButton';
import { GameText } from '../ui/GameText';

interface DeckSelectorProps {
    activeDeckId: number;
    onSelectDeck: (id: number) => void;
}

export const DeckSelector: React.FC<DeckSelectorProps> = ({ activeDeckId, onSelectDeck }) => {
    const { user } = useUser();
    const [flippedId, setFlippedId] = useState<number | null>(null);

    const handleDeckClick = (id: number) => {
        if (activeDeckId === id) {
            setFlippedId(flippedId === id ? null : id);
        } else {
            onSelectDeck(id);
            setFlippedId(null);
        }
    };

    const getStats = (deckId: number) => {
        const cardIds = user.decks[deckId] || [];
        if (cardIds.length === 0) return { avgCost: 0, avgPower: 0, count: 0 };

        const deckCards = cardIds.map(id => CARDS.find(c => c.id === id)).filter(Boolean);
        const totalCost = deckCards.reduce((acc, c) => acc + (c?.baseCost || 0), 0);
        const totalPower = deckCards.reduce((acc, c) => acc + (c?.basePower || 0), 0);

        return {
            avgCost: (totalCost / deckCards.length).toFixed(1),
            avgPower: (totalPower / deckCards.length).toFixed(1),
            count: deckCards.length
        };
    };

    return (
        /* Reduced py-2 to pt-2 pb-0.5 to minimize gap below the selector */
        <div className="w-full flex overflow-x-auto pt-2 pb-0.5 px-3 gap-2 shrink-0 scrollbar-hide perspective-1000">
            {[1, 2, 3].map(i => {
                const isSelected = activeDeckId === i;
                const isFlipped = flippedId === i && isSelected;
                const stats = getStats(i);
                const deckName = user.deckNames[i] || 'UNTITLED';
                const isIncomplete = stats.count < 12;

                return (
                    <div 
                        key={i} 
                        className="min-w-[7.5rem] h-14 relative"
                    >
                        <div className={`
                            w-full h-full relative transition-transform duration-500 transform-style-3d
                            ${isFlipped ? 'rotate-y-180' : ''}
                        `}>
                            {/* FRONT: SlantedButton View */}
                            <div className="absolute inset-0 backface-hidden">
                                <SlantedButton 
                                    variant={isSelected ? 'primary' : 'secondary'}
                                    fullWidth
                                    size="md"
                                    className="!h-full"
                                    onClick={() => handleDeckClick(i)}
                                >
                                    <div className="flex flex-col items-center justify-center w-full h-full pointer-events-none pt-1 pb-0.5">
                                        <div className="flex items-center gap-1">
                                            <span className="text-[0.45rem] font-black text-white/40 uppercase tracking-widest">Deck {i}</span>
                                            {isIncomplete && <div className="w-1.5 h-1.5 rounded-full bg-amber-500 animate-pulse shadow-[0_0_5px_rgba(245,158,11,0.8)]" />}
                                        </div>
                                        <div className="flex-1 w-full min-h-0 flex items-center justify-center">
                                            <GameText 
                                                text={deckName} 
                                                baseFontSize={22} 
                                                maxLines={2}
                                                className="text-white drop-shadow-md"
                                            />
                                        </div>
                                    </div>
                                </SlantedButton>
                            </div>

                            {/* BACK: STATS VIEW */}
                            <div 
                                className="absolute inset-0 backface-hidden rotate-y-180 flex items-center justify-around px-1 rounded-lg border-2 border-indigo-400 bg-indigo-900 shadow-xl cursor-pointer"
                                onClick={() => handleDeckClick(i)}
                            >
                                <div className="flex flex-col items-center">
                                    <span className="text-[0.4rem] font-black text-indigo-200 uppercase leading-none mb-1">Cost</span>
                                    <span className="text-sm font-black text-white italic">{stats.avgCost}</span>
                                </div>
                                <div className="w-px h-8 bg-white/20" />
                                <div className="flex flex-col items-center">
                                    <span className="text-[0.4rem] font-black text-indigo-200 uppercase leading-none mb-1">Power</span>
                                    <span className="text-sm font-black text-white italic">{stats.avgPower}</span>
                                </div>
                            </div>
                        </div>
                    </div>
                );
            })}

            <style>{`
                .perspective-1000 { perspective: 1000px; }
                .transform-style-3d { transform-style: preserve-3d; }
                .backface-hidden { backface-visibility: hidden; }
                .rotate-y-180 { transform: rotateY(180deg); }
            `}</style>
        </div>
    );
};

import React from 'react';
import { useGame } from '../contexts/GameContext';
import { SlantedButton } from './ui/SlantedButton';
import { EnergyOrb } from './game/EnergyOrb';

export const ControlBar: React.FC = () => {
    const { 
        gameState, 
        isResolving, 
        isWaiting,
        currentEnergy, 
        isResultsHidden, 
        showUndoMenu, 
        actions, 
        setShowUndoMenu 
    } = useGame();

    const isInteractionDisabled = isResolving || isWaiting || gameState.phase !== 'planning';
    const isGameOver = gameState.winner !== null;

    return (
        <div className="h-10 px-2 pb-1 flex items-center justify-between relative bg-slate-950/50 border-t border-slate-800">
            {/* 
                ABSOLUTE CENTERED ORB 
                We hide this entirely when the game is over.
            */}
            {!isGameOver && (
                <div className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 z-40">
                    <EnergyOrb 
                        energy={currentEnergy}
                        showMenu={showUndoMenu}
                        disabled={isInteractionDisabled}
                        onClick={() => setShowUndoMenu(!showUndoMenu)}
                        onCloseMenu={() => setShowUndoMenu(false)}
                        onUndoAll={actions.handleUndoAll}
                    />
                </div>
            )}

            {isGameOver ? (
                /* GAME OVER CONTROLS: Left: Toggle, Center: Menu, Right: Retry */
                <div className="flex w-full items-center justify-between gap-2 h-full">
                    {/* LEFT: RESULTS TOGGLE */}
                    <div className="flex-1 flex justify-start">
                        <SlantedButton 
                            variant="secondary" 
                            size="sm" 
                            onClick={() => actions.toggleResults(!isResultsHidden)}
                        >
                            {isResultsHidden ? 'SHOW' : 'HIDE'}
                        </SlantedButton>
                    </div>

                    {/* CENTER: MENU */}
                    <div className="flex-1 flex justify-center">
                        <SlantedButton 
                            variant="secondary" 
                            size="sm" 
                            onClick={actions.handleExit}
                        >
                            MENU
                        </SlantedButton>
                    </div>

                    {/* RIGHT: PLAY AGAIN */}
                    <div className="flex-1 flex justify-end">
                        <SlantedButton 
                            variant="success" 
                            size="sm" 
                            onClick={actions.restartGame}
                        >
                            PLAY AGAIN
                        </SlantedButton>
                    </div>
                </div>
            ) : (
                /* GAMEPLAY CONTROLS */
                <>
                    {/* LEFT SIDE: RESIGN */}
                    <div className="flex-1 flex justify-start">
                        <SlantedButton 
                            variant="danger" 
                            size="sm" 
                            onClick={actions.handleResign} 
                            disabled={isResolving}
                        >
                            RESIGN
                        </SlantedButton>
                    </div>

                    {/* SPACER FOR ORB */}
                    <div className="w-12 h-10 flex-none" />

                    {/* RIGHT SIDE: END TURN */}
                    <div className="flex-1 flex justify-end">
                        <SlantedButton 
                            variant="primary" 
                            size="sm"
                            onClick={actions.handleEndTurn} 
                            disabled={isResolving || isWaiting}
                        >
                            {isResolving ? 'WAITING' : (isWaiting ? 'READY' : 'END TURN')}
                        </SlantedButton>
                    </div>
                </>
            )}
        </div>
    );
};

