import React, { useState } from 'react';
import { SlantedButton } from '../ui/SlantedButton';
import { GameText } from '../ui/GameText';
import { useUser } from '../../contexts/UserContext';
import { audio } from '../../services/audio';
import { GoldIcon } from '../ui/CurrencyIcons';

interface StoreGoldItemProps {
    amount: number;
    price: string;
    badge: string | null;
    visualIndex: number; 
}

export const StoreGoldItem: React.FC<StoreGoldItemProps> = ({ amount, price, badge, visualIndex }) => {
    const { addGold } = useUser();
    const [holdProgress, setHoldProgress] = useState(0);
    const [isHolding, setIsHolding] = useState(false);
    const [status, setStatus] = useState<'idle' | 'processing' | 'success'>('idle');

    const handlePurchase = () => {
        if (status !== 'idle') return;

        setStatus('processing');
        setTimeout(() => {
            addGold(amount);
            setStatus('success');
            audio.play('sfx_victory', 0.5);

            setTimeout(() => {
                setStatus('idle');
                setHoldProgress(0);
            }, 2500);
        }, 900);
    };

    return (
        <div className={`bg-gradient-to-b from-slate-800 via-slate-900 to-black border-2 transition-all duration-300 rounded p-2 flex flex-col items-center justify-between h-[10rem] relative group overflow-hidden shadow-[0_4px_15_rgba(0,0,0,0.8)] ${status === 'success' ? 'border-emerald-400 ring-2 ring-emerald-500/50 bg-emerald-950' : 'border-slate-700'}`}>
            {status === 'success' && (
                <div className="absolute inset-0 bg-white/40 animate-pulse z-40 pointer-events-none" />
            )}

            {/* Hold progress background - remove transition for sync */}
            {holdProgress > 0 && status === 'idle' && (
                <div 
                    className="absolute inset-y-0 left-0 bg-amber-300 shadow-[0_0_2rem_rgba(251,191,36,1),0_0_4rem_rgba(251,191,36,0.5)] z-0 pointer-events-none"
                    style={{ width: `${holdProgress}%` }}
                />
            )}

            {badge && status === 'idle' && (
                <div className="absolute -top-1 -right-1 z-30 bg-red-600 border border-red-400 text-white text-[0.45rem] font-black px-1.5 py-0.5 rounded shadow-[0_0_10px_rgba(220,38,38,0.8)] uppercase tracking-tight skew-x-[-10deg]">
                    {badge}
                </div>
            )}

            <div className="mt-1 flex flex-col items-center justify-center gap-0.5 w-full relative z-10 px-1">
                <div className="h-6 w-full">
                    <GameText 
                        text={amount.toLocaleString()} 
                        baseFontSize={24} 
                        className="text-white drop-shadow-md"
                    />
                </div>
                <div className="flex items-center gap-1">
                    <GoldIcon size="xs" />
                    <span className="text-[0.45rem] font-black text-amber-500 uppercase tracking-widest leading-none">GOLD</span>
                </div>
            </div>

            <div className="w-full flex-1 flex items-center justify-center py-2 relative min-h-[3rem] z-10">
                <div className="absolute inset-0 bg-amber-500/15 blur-xl rounded-full scale-75"></div>

                <div className={`relative z-10 flex flex-wrap gap-0.5 justify-center items-center transition-all duration-500 ${status === 'success' ? 'scale-110' : ''}`}>
                    {status === 'success' ? (
                         <div className="w-10 h-10 rounded-full bg-emerald-500 border-2 border-emerald-300 flex items-center justify-center shadow-[0_0_20px_rgba(16,185,129,1)]">
                            <svg className="w-7 h-7 text-white animate-pop" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={4} d="M5 13l4 4L19 7" /></svg>
                         </div>
                    ) : (
                        <GoldIcon size="md" />
                    )}
                </div>
            </div>

            <div className="w-full h-1 relative flex items-center justify-center pointer-events-none mb-0.5 z-10 overflow-visible">
                {isHolding && status === 'idle' && (
                    <div className="relative font-black text-[0.45rem] uppercase tracking-widest leading-none drop-shadow-[0_1px_2px_rgba(0,0,0,1)]">
                        <span className="text-white/40 whitespace-nowrap">HOLD TO BUY</span>
                        <div 
                            className="absolute inset-0 text-white whitespace-nowrap overflow-hidden"
                            style={{ width: `${holdProgress}%` }}
                        >
                            HOLD TO BUY
                        </div>
                    </div>
                )}
                {status === 'processing' && (
                    <span className="text-[0.45rem] font-black text-amber-300 uppercase tracking-[0.25em] leading-none animate-pulse drop-shadow-[0_0_5px_rgba(245,158,11,0.8)]">SYNCING...</span>
                )}
                {status === 'success' && (
                    <span className="text-[0.45rem] font-black text-emerald-400 uppercase tracking-[0.25em] leading-none animate-bounce origin-bottom drop-shadow-[0_0_5px_rgba(52,211,153,0.8)]">DEPOSITED</span>
                )}
            </div>

            <div className="w-full mt-1 relative z-10">
                <div className="h-7">
                    <SlantedButton 
                        variant={status === 'success' ? 'success' : 'primary'} 
                        size="sm"
                        fullWidth 
                        onClick={handlePurchase}
                        disabled={status !== 'idle'}
                        holdDuration={1000}
                        onHoldChange={setIsHolding}
                        onProgressChange={setHoldProgress}
                    >
                        {status === 'processing' ? 'SYNCING' : (status === 'success' ? 'SUCCESS' : price)}
                    </SlantedButton>
                </div>
            </div>
        </div>
    );
};

import React, { useEffect, useState } from 'react';
import { SlantedButton } from '../ui/SlantedButton';
import { GameText } from '../ui/GameText';
import { useUser } from '../../contexts/UserContext';
import { usePurchaseOffer } from '../../hooks/usePurchaseOffer';
import { CreditIcon, GoldIcon } from '../ui/CurrencyIcons';

interface StoreResourceItemProps {
    type: 'gold' | 'credits';
    amount: number;
    costLabel: string;
    costAmount?: number;
    costType: 'gold' | 'real' | 'free';
    offerId?: string;
    availableAt?: string;
}

export const StoreResourceItem: React.FC<StoreResourceItemProps> = ({ 
    type, amount, costLabel, costAmount, costType, offerId, availableAt 
}) => {
    const { user, spendGold, addCredits, addGold, processPurchase, syncStore } = useUser();
    const [timeLeft, setTimeLeft] = useState<number>(0);

    const isFree = costType === 'free';
    const hasEnoughCurrency = isFree || costType === 'real' || (costType === 'gold' && user.gold >= (costAmount || 0));

    // Time-based locking (Daily rewards)
    useEffect(() => {
        if (!availableAt) return;
        const updateTimer = () => {
            const now = Date.now();
            const target = new Date(availableAt).getTime();
            const diff = Math.max(0, Math.floor((target - now) / 1000));
            setTimeLeft(diff);
        };
        updateTimer();
        const interval = setInterval(updateTimer, 1000);
        return () => clearInterval(interval);
    }, [availableAt]);

    const handleAction = async () => {
        if (!hasEnoughCurrency) {
            syncStore();
            return false;
        }

        if (isFree && offerId) {
            return await processPurchase(offerId);
        } else if (costType === 'gold' && costAmount) {
            if (spendGold(costAmount)) {
                if (type === 'credits') addCredits(amount);
                else addGold(amount);
                return true;
            }
        } else if (costType === 'real') {
            // Mock IAP
            if (type === 'gold') addGold(amount);
            else addCredits(amount);
            return true;
        }
        return false;
    };

    const { status, holdProgress, isHolding, setHoldProgress, setIsHolding, executePurchase } = usePurchaseOffer({
        onPurchase: handleAction
    });

    const isLocked = timeLeft > 0;
    const isSuccess = status === 'success';
    const isProcessing = status === 'processing';

    return (
        <div className={`
            bg-gradient-to-b from-slate-800 via-slate-900 to-black border-2 transition-all duration-300 rounded p-2 flex flex-col items-center justify-between h-[10.5rem] relative overflow-hidden shadow-2xl
            ${isSuccess ? 'border-emerald-400 ring-2 ring-emerald-500/50 bg-emerald-950' : 'border-slate-700'}
        `}>
            {/* Success Flash */}
            {isSuccess && <div className="absolute inset-0 bg-white/20 animate-pulse z-40 pointer-events-none" />}

            {/* Hold Progress Bar Overlay */}
            {holdProgress > 0 && status === 'idle' && !isLocked && (
                <div 
                    className={`absolute inset-y-0 left-0 z-0 pointer-events-none ${type === 'gold' ? 'bg-amber-400/30' : 'bg-blue-400/30'}`}
                    style={{ width: `${holdProgress}%` }}
                />
            )}

            {/* Amount & Label */}
            <div className="relative z-10 text-center w-full px-1">
                <div className="h-6 w-full mb-0.5">
                    <GameText 
                        text={amount.toLocaleString()} 
                        baseFontSize={24} 
                        className="text-white drop-shadow-md"
                    />
                </div>
                <div className={`text-[0.45rem] font-black uppercase tracking-[0.2em] leading-none ${type === 'gold' ? 'text-amber-500' : 'text-blue-400'}`}>
                    {type}
                </div>
            </div>

            {/* Resource Icon Visual */}
            <div className="relative z-10 flex-1 flex items-center justify-center">
                <div className={`
                    w-12 h-12 rounded-full flex items-center justify-center border-2 transition-all duration-500
                    ${isSuccess ? 'bg-emerald-500 border-emerald-300 scale-110 shadow-[0_0_20px_rgba(16,185,129,0.8)]' : 'bg-slate-900 border-slate-700'}
                `}>
                    {isSuccess ? (
                        <svg className="w-7 h-7 text-white animate-pop" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={4} d="M5 13l4 4L19 7" /></svg>
                    ) : (
                        type === 'gold' ? <GoldIcon size="md" /> : <CreditIcon size="md" />
                    )}
                </div>
            </div>

            {/* Bottom Status / Timer / Button */}
            <div className="w-full relative z-10">
                <div className="h-1.5 flex items-center justify-center mb-1">
                    {isHolding && status === 'idle' && !isLocked && (
                        <span className="text-[0.4rem] font-black text-white/60 uppercase tracking-widest animate-pulse">Hold to acquire</span>
                    )}
                    {isProcessing && <span className="text-[0.45rem] font-black text-indigo-400 animate-pulse uppercase tracking-widest">Processing...</span>}
                </div>

                {isLocked ? (
                    <div className="h-8 w-full bg-slate-900 border border-slate-700 rounded flex items-center justify-center gap-1.5 grayscale opacity-60">
                         <svg className="w-2.5 h-2.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                         <span className="text-[0.6rem] font-black tabular-nums">{Math.floor(timeLeft / 60)}:{(timeLeft % 60).toString().padStart(2, '0')}</span>
                    </div>
                ) : (
                    <SlantedButton 
                        variant={isSuccess ? 'success' : (type === 'gold' ? 'primary' : 'blue')} 
                        size="sm" 
                        fullWidth
                        holdDuration={isFree ? 0 : 800}
                        onHoldChange={setIsHolding}
                        onProgressChange={setHoldProgress}
                        onClick={executePurchase}
                        disabled={isProcessing || isSuccess}
                    >
                        {isSuccess ? 'READY' : costLabel}
                    </SlantedButton>
                )}
            </div>
        </div>
    );
};

import React, { useState } from 'react';
