    | 'ERR_OFFER_NOT_FOUND' 
    | 'ERR_INSUFFICIENT_FUNDS' 
    | 'ERR_STALE_OFFER' 
    | 'ERR_DUPLICATE_TRANSACTION' 
    | 'ERR_BALANCE_DESYNC'
    | 'ERR_COOLDOWN_ACTIVE';

