import React, { useState, useRef, useEffect } from 'react';
import { useUser } from '../../contexts/UserContext';
import { SlantedButton } from '../ui/SlantedButton';
import { GameText } from '../ui/GameText';
import { audio } from '../../services/audio';

/**
 * DECK COMMAND BAR
 * A futuristic "Deck Roller" interaction.
 * Provides quick deck switching without screen reloads.
 */
export const DeckCommandBar: React.FC = () => {
    const { user, setActiveDeck } = useUser();
    const [isExpanded, setIsExpanded] = useState(false);
    const scrollRef = useRef<HTMLDivElement>(null);

    const activeDeckId = user.activeDeckId;
    const activeDeckName = user.deckNames[activeDeckId] || 'UNTITLED';

    const deckIds = [1, 2, 3]; // Available deck slots

    // Handle Selection
    const handleSelect = (id: number) => {
        if (id !== activeDeckId) {
            setActiveDeck(id);
            audio.play('sfx_ui_click');
        }
        setIsExpanded(false);
    };

    // Auto-scroll to active item when expanding
    useEffect(() => {
        if (isExpanded && scrollRef.current) {
            const activeItem = scrollRef.current.querySelector(`[data-deck-id="${activeDeckId}"]`);
            if (activeItem) {
                activeItem.scrollIntoView({ block: 'center', behavior: 'smooth' });
            }
        }
    }, [isExpanded, activeDeckId]);

    return (
        <div className="w-full flex items-end justify-center px-4 pb-3 relative pointer-events-none h-16">

            {/* 1. THE ROLLER OVERLAY (Visible when expanded) */}
            {isExpanded && (
                <>
                    {/* Backdrop to close */}
                    <div 
                        className="fixed inset-0 z-40 bg-black/40 backdrop-blur-sm pointer-events-auto"
                        onClick={() => setIsExpanded(false)}
                    />

                    {/* Floating Vertical Roller */}
                    <div className="absolute bottom-16 left-1/2 -translate-x-1/2 w-[85%] max-w-[18rem] z-50 pointer-events-auto animate-pop origin-bottom">
                        <div className="bg-slate-900/95 border-2 border-indigo-500/50 rounded-2xl shadow-[0_20px_50px_rgba(0,0,0,0.8),0_0_20px_rgba(79,70,229,0.2)] overflow-hidden flex flex-col">

                            {/* Header */}
                            <div className="p-3 border-b border-indigo-500/20 bg-indigo-950/30 flex items-center justify-between">
                                <span className="text-[0.6rem] font-black text-indigo-300 uppercase tracking-widest">Select Deck Configuration</span>
                                <div className="w-1.5 h-1.5 rounded-full bg-indigo-400 animate-pulse" />
                            </div>

                            {/* Scrollable Area */}
                            <div 
                                ref={scrollRef}
                                className="max-h-[16rem] overflow-y-auto py-2 px-2 space-y-1.5 scrollbar-hide"
                            >
                                {deckIds.map(id => {
                                    const isSelected = activeDeckId === id;
                                    const name = user.deckNames[id] || 'UNTITLED';

                                    return (
                                        <button
                                            key={id}
                                            data-deck-id={id}
                                            onClick={() => handleSelect(id)}
                                            className={`
                                                w-full flex items-center gap-3 p-3 rounded-xl transition-all duration-200 text-left relative overflow-hidden group
                                                ${isSelected 
                                                    ? 'bg-indigo-600 shadow-[0_0_15px_rgba(79,70,229,0.4)] border border-indigo-400/50' 
                                                    : 'bg-slate-800/50 border border-slate-700/50 hover:bg-slate-700/80'}
                                            `}
                                        >
                                            {/* Selection Glow */}
                                            {isSelected && (
                                                <div className="absolute inset-0 bg-gradient-to-r from-white/10 to-transparent pointer-events-none animate-shimmer" />
                                            )}

                                            <div className={`
                                                w-8 h-8 rounded-lg flex items-center justify-center font-black text-xs shrink-0
                                                ${isSelected ? 'bg-white text-indigo-600' : 'bg-slate-700 text-slate-400'}
                                            `}>
                                                {id}
                                            </div>

                                            <div className="flex-1 min-w-0">
                                                <div className={`text-[0.55rem] font-black uppercase tracking-widest leading-none mb-1 ${isSelected ? 'text-indigo-200' : 'text-slate-500'}`}>
                                                    Module 0{id}
                                                </div>
                                                <div className="h-5 w-full">
                                                    <GameText 
                                                        text={name} 
                                                        baseFontSize={24} 
                                                        className={`${isSelected ? 'text-white' : 'text-slate-300'}`}
                                                        maxLines={1}
                                                    />
                                                </div>
                                            </div>

                                            {isSelected && (
                                                <div className="w-5 h-5 bg-white/20 rounded-full flex items-center justify-center">
                                                    <svg className="w-3 h-3 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={4} d="M5 13l4 4L19 7" />
                                                    </svg>
                                                </div>
                                            )}
                                        </button>
                                    );
                                })}
                            </div>

                            {/* Footer Hint */}
                            <div className="p-2 text-center text-[0.45rem] font-bold text-slate-500 uppercase tracking-widest opacity-60">
                                Global Proxy Connection Active
                            </div>
                        </div>
                    </div>
                </>
            )}

            {/* 2. MAIN INTERACTIVE BUTTON */}
            <div className="w-[85%] max-w-[18rem] pointer-events-auto relative z-50">
                <SlantedButton 
                    variant={isExpanded ? 'primary' : 'secondary'}
                    fullWidth
                    size="lg"
                    className={`!h-13 shadow-xl transition-all duration-300 ${isExpanded ? 'scale-105' : ''}`}
                    onClick={() => { setIsExpanded(!isExpanded); audio.playUiClick(); }}
