                    <div className="flex flex-col items-center justify-center w-full h-full text-center px-2">
                        <div className="flex items-center gap-1.5 opacity-60">
                            <div className="w-1 h-1 rounded-full bg-white animate-pulse" />
                            <div className="h-3 flex items-center">
                                <GameText text="CURRENT DECK" baseFontSize={16} />
                            </div>
                            <div className="w-1 h-1 rounded-full bg-white animate-pulse" />
                        </div>
                        <div className="w-full h-8 -mt-1.5 flex items-center justify-center gap-2">
                            <div className="flex-1 h-full flex items-center justify-center">
                                <GameText 
                                    text={activeDeckName} 
                                    baseFontSize={38} 
                                    maxLines={1} 
                                    className="italic tracking-tighter text-white"
                                />
                            </div>

                            {/* Animated Arrow */}
                            <div className={`transition-transform duration-300 ${isExpanded ? 'rotate-180' : ''}`}>
                                <svg className="w-4 h-4 text-white/60" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 15l7-7 7 7" />
                                </svg>
                            </div>
                        </div>
                    </div>
                </SlantedButton>
            </div>

            <style>{`
                @keyframes shimmer {
                    from { transform: translateX(-100%); }
                    to { transform: translateX(100%); }
                }
                .animate-shimmer {
                    animation: shimmer 2s infinite linear;
                }
            `}</style>
        </div>
    );
};

import React, { useCallback, useMemo, useRef } from 'react';
import { StandardHeader } from '../ui/StandardHeader';
import { CollectionGrid } from '../deck/CollectionGrid';
import { DeckVault } from '../deck/DeckVault';
import { CollectionDragOverlay } from '../CollectionDragOverlay';
import { useUser } from '../../contexts/UserContext';
import { useCollectionDrag } from '../../hooks/useCollectionDrag';
import { CARDS } from '../../constants';
import { CardDefinition } from '../../types';

export const DeckScreen: React.FC = () => {
    const { user, updateDeck, activeDeck } = useUser();
    const scrollRef = useRef<HTMLDivElement>(null);
    const vaultRef = useRef<HTMLDivElement>(null);
    const archiveRef = useRef<HTMLDivElement>(null);

    const handleAddCard = useCallback((cardId: string) => {
        if (activeDeck.length < 12 && !activeDeck.includes(cardId)) {
            updateDeck(user.activeDeckId, [...activeDeck, cardId]);
        }
    }, [activeDeck, user.activeDeckId, updateDeck]);

    const handleRemoveCard = useCallback((cardId: string) => {
        updateDeck(user.activeDeckId, activeDeck.filter(id => id !== cardId));
    }, [activeDeck, user.activeDeckId, updateDeck]);

    const { dragState, handlePointerDown } = useCollectionDrag({
        onAdd: handleAddCard,
        onRemove: handleRemoveCard,
        scrollRef: scrollRef,
        vaultRef: vaultRef,
        archiveRef: archiveRef
    });

    const deckCards = useMemo(() => {
        return activeDeck
            .map(id => CARDS.find(c => c.id === id))
            .filter((c): c is CardDefinition => !!c)
            .sort((a, b) => {
                if (a.baseCost !== b.baseCost) {
                    return a.baseCost - b.baseCost;
                }
                return a.name.localeCompare(b.name);
            });
    }, [activeDeck]);

    return (
        <div className="w-full h-full flex flex-col bg-slate-950 overflow-hidden relative">
            <StandardHeader title="Collection" showCurrency />

            <CollectionDragOverlay dragState={dragState} />

            {/* 1. DECK VAULT ZONE (Dynamic selection moved to Command Bar) */}
            <div 
                ref={vaultRef}
                className={`shrink-0 border-b border-slate-700 z-20 transition-all duration-300 pt-3 ${dragState?.active && dragState.origin === 'archive' ? 'ring-2 ring-inset ring-indigo-500/50' : ''}`}
                data-drop-zone="vault"
            >
                {/* Visual Label for the active module */}
                <div className="px-4 mb-2 flex items-center justify-between opacity-50">
                    <span className="text-[0.5rem] font-black uppercase tracking-[0.2em] text-indigo-300">Active Module Configuration</span>
                    <span className="text-[0.5rem] font-bold text-slate-500 italic">{deckCards.length}/12</span>
                </div>

                <div className="px-3 pb-3">
                    <DeckVault 
                        cards={deckCards} 
                        draggingCardId={dragState?.active && dragState.origin === 'vault' ? dragState.card.id : undefined}
                        onPointerDown={(e, card) => handlePointerDown(e, card, 'vault')}
                    />
                </div>
            </div>

            {/* 2. COLLECTION ARCHIVE */}
            <div 
                ref={archiveRef}
                className={`flex-1 min-h-0 relative transition-all duration-300 ${dragState?.active && dragState.origin === 'vault' ? 'bg-red-500/5' : ''}`}
                data-drop-zone="archive"
            >
                <CollectionGrid 
                    scrollRef={scrollRef}
                    ownedIds={user.collection}
                    activeDeckIds={activeDeck}
                    draggingCardId={dragState?.active && dragState.origin === 'archive' ? dragState.card.id : undefined}
                    onPointerDown={(e, card) => handlePointerDown(e, card, 'archive')}
                />
            </div>
        </div>
    );
};

