    syncStore: () => Promise<void>;
    // Inspector Methods
    inspect: (item: CardInstance | CardDefinition | LocationDefinition | { type: 'gold' | 'credits', amount: number } | null) => void;
    closeInspector: () => void;
    // Derived
    activeDeck: string[];
}

