/**
 * DECK SELECTOR HUB
 * Toggle between 'classic' and '3d' to test user experience.
 */
export const DeckSelector: React.FC<DeckSelectorProps> = (props) => {
    // CHANGE THIS TO 'classic' or '3d'
    const MODE: 'classic' | '3d' = '3d';

    if (MODE === '3d') {
        return <DeckSelector3D {...props} />;
    }

    return <DeckSelectorClassic {...props} />;
};

import React from 'react';
import { useUser } from '../../contexts/UserContext';
import { SlantedButton } from '../ui/SlantedButton';
import { GameText } from '../ui/GameText';

interface DeckSelectorProps {
    activeDeckId: number;
    onSelectDeck: (id: number) => void;
}

/**
 * 3D HOLOGRAPHIC CYLINDER (Option A)
 * A cinematic 3D carousel that rotates decks around a central axis.
 * Tilted for a high-tech HUD appearance.
 */
export const DeckSelector3D: React.FC<DeckSelectorProps> = ({ activeDeckId, onSelectDeck }) => {
    const { user } = useUser();

    const deckIds = Object.keys(user.decks).map(Number).sort((a, b) => a - b);
    const count = deckIds.length;
    const angleStep = 360 / count;

    // Smoothly rotate to the active deck
    const rotationY = -(activeDeckId - 1) * angleStep;

    // Radius of the cylinder
    const radius = 220; 

    return (
        <div className="w-full h-32 flex items-center justify-center perspective-[1200px] overflow-visible select-none touch-none">
            {/* The Main Cylinder Container */}
            <div 
                className="relative w-32 h-14 transition-transform duration-700 ease-[cubic-bezier(0.2,1,0.3,1)] transform-style-3d"
                style={{ 
                    // Tilting the whole cylinder (rotateX) makes the curve visible
                    transform: `rotateX(-15deg) translateZ(-${radius}px) rotateY(${rotationY}deg)` 
                }}
            >
                {/* Holographic Center Glow */}
                <div 
                    className="absolute inset-x-[-20%] inset-y-[-20%] bg-indigo-500/10 blur-2xl rounded-full pointer-events-none transform-style-3d"
                    style={{ transform: `rotateY(${-rotationY}deg) translateZ(${radius}px)` }}
                />

                {deckIds.map((id, i) => {
                    const isSelected = activeDeckId === id;
                    const angle = i * angleStep;

                    // Logic to hide/dim items that are too far back
                    const relativeAngle = (angle + rotationY) % 360;
                    const normalizedAngle = ((relativeAngle + 180) % 360) - 180;
                    const isVisible = Math.abs(normalizedAngle) < 90;
                    const distanceScale = 1 - (Math.abs(normalizedAngle) / 90) * 0.4;
                    const opacity = 1 - (Math.abs(normalizedAngle) / 90);

                    const deckName = user.deckNames[id] || 'UNTITLED';
                    const dCount = (user.decks[id] || []).length;

                    return (
                        <div 
                            key={id}
                            className={`
                                absolute inset-0 backface-hidden transition-all duration-500
                                ${isSelected ? 'z-50' : 'z-10'}
                            `}
                            style={{ 
                                transform: `rotateY(${angle}deg) translateZ(${radius}px) scale(${distanceScale})`,
                                opacity: isVisible ? Math.max(0.1, opacity) : 0,
                                transformStyle: 'preserve-3d',
                                pointerEvents: isVisible ? 'auto' : 'none'
                            }}
                        >
                            <SlantedButton 
                                variant={isSelected ? 'primary' : 'secondary'}
                                fullWidth
                                size="md"
                                className={`!h-full shadow-2xl transition-all duration-500 ${isSelected ? 'shadow-indigo-500/40 ring-2 ring-indigo-400/50' : ''}`}
                                onClick={() => onSelectDeck(id)}
                            >
                                <div className="flex flex-col items-center justify-center w-full h-full pointer-events-none pt-1 pb-0.5">
                                    <div className="flex items-center gap-1">
                                        <span className={`text-[0.45rem] font-black uppercase tracking-widest ${isSelected ? 'text-indigo-200' : 'text-white/40'}`}>
                                            {id < 10 ? `0${id}` : id}
                                        </span>
                                        {dCount < 12 && <div className="w-1.5 h-1.5 rounded-full bg-amber-500 shadow-[0_0_5px_rgba(245,158,11,0.8)]" />}
                                    </div>
                                    <div className="flex-1 w-full min-h-0 flex items-center justify-center">
                                        <GameText 
                                            text={deckName} 
                                            baseFontSize={20} 
                                            maxLines={2}
                                            className="text-white"
                                        />
                                    </div>
                                </div>
                            </SlantedButton>

                            {/* Selection Underglow for the active item */}
                            {isSelected && (
                                <div className="absolute inset-0 bg-indigo-500/20 blur-xl -z-10 animate-pulse rounded-lg" />
                            )}
                        </div>
                    );
                })}
            </div>

            <style>{`
                .transform-style-3d { transform-style: preserve-3d; }
                .backface-hidden { backface-visibility: hidden; }
            `}</style>
        </div>
    );
};

import React, { useState } from 'react';
import { ScreenKey } from '../../types';
