    const handleDeckSelect = (id: number) => {
        if (id !== activeDeckId) {
            setActiveDeck(id);
            audio.play('sfx_ui_click');
        }
        setIsRollerOpen(false);
    };

    const deckIds = Object.keys(user.decks).map(Number).sort((a, b) => a - b);
    const count = deckIds.length;
    const angleStep = 360 / count;
    const rotationY = -(activeDeckId - 1) * angleStep;
    const radius = 200; // Slightly smaller radius for mobile popup

    return (
        <div className="w-full flex items-end justify-between px-2 pb-3 gap-1 pointer-events-none relative overflow-visible h-16">

            {/* DECK ROLLER PORTAL - 3D HOLOGRAPHIC VERSION */}
            {isRollerOpen && (
                <Portal>
                    <div 
                        className="fixed inset-0 z-[600] pointer-events-auto bg-black/70 backdrop-blur-md transition-opacity duration-300 flex flex-col items-center justify-center" 
