                                    const isSelected = activeDeckId === id;
                                    const angle = i * angleStep;
                                    const deckName = user.deckNames[id] || 'UNTITLED';
                                    const dCount = (user.decks[id] || []).length;

                                    const relativeAngle = (angle + rotationY) % 360;
                                    const normalizedAngle = ((relativeAngle + 180) % 360) - 180;
                                    const distanceScale = 1 - (Math.abs(normalizedAngle) / 120) * 0.4;
                                    const opacity = 1 - (Math.abs(normalizedAngle) / 100);

