                                                    <span className={`text-[0.45rem] font-black tracking-widest uppercase ${isSelected ? 'text-indigo-200' : 'text-slate-400'}`}>
                                                        Deck 0{id}
                                                    </span>
                                                    <div className="w-full h-8 px-2">
                                                        <GameText 
                                                            text={deckName} 
                                                            baseFontSize={28} 
                                                            className={isSelected ? 'text-white' : 'text-slate-300'} 
                                                            maxLines={1}
                                                        />
                                                    </div>
                                                    <div className="text-[0.5rem] font-bold opacity-60">
