                                </div>
                                {isIncomplete && <div className="w-1 h-1 rounded-full bg-amber-500 animate-pulse" />}
                            </div>
                            <div className="flex-1 w-full min-h-0">
                                <GameText 
                                    text={activeDeckName} 
                                    baseFontSize={34} 
                                    maxLines={2} 
                                    className="italic tracking-tighter leading-none"
                                />
                            </div>
                        </div>
                    </div>
                </SlantedButton>
            </div>

            {/* 4. PLAY LADDER */}
            <div className="w-[23%] pointer-events-auto">
                <SlantedButton 
                    variant="blue" 
                    fullWidth
                    size="lg"
                    onClick={() => onNavigate('GAME')}
