                            <div className="w-full h-9 -mt-2.5">
                                <GameText 
                                    text="LADDER" 
                                    baseFontSize={38} 
                                    maxLines={1} 
                                    className="italic tracking-tighter"
                                />
                            </div>
                        </div>
                    </div>
                </SlantedButton>
            </div>

            {/* 5. RANK */}
            <div className="w-[13.5%] pointer-events-auto">
                <SlantedButton 
                    variant="blue" 
                    size="md"
                    onClick={() => onNavigate('RANK')}
                    className="w-full !h-10 shadow-blue-900/40 border-blue-400/40"
