            <style>{`
                .transform-style-3d { transform-style: preserve-3d; }
                .backface-hidden { backface-visibility: hidden; }
            `}</style>
        </div>
    );
};

import React from 'react';
import { useUser } from '../../contexts/UserContext';
import { SlantedButton } from '../ui/SlantedButton';
import { GameText } from '../ui/GameText';

interface DeckSelectorProps {
    activeDeckId: number;
    onSelectDeck: (id: number) => void;
}

/**
 * 3D VERTICAL DRUM SELECTOR
 * Rotates on the X-axis like an iPhone calendar/date picker.
 */
export const DeckSelector3D: React.FC<DeckSelectorProps> = ({ activeDeckId, onSelectDeck }) => {
    const { user } = useUser();

    const deckIds = Object.keys(user.decks).map(Number).sort((a, b) => a - b);
    const count = deckIds.length;
    const angleStep = 360 / count;

    // Smoothly rotate the cylinder on the X-axis
    // (activeDeckId - 1) centers the active deck at 0 degrees
    const rotationX = (activeDeckId - 1) * angleStep;

    // Radius of the vertical drum
    const radius = 140; 

    return (
        <div className="w-full h-40 flex items-center justify-center perspective-[1000px] overflow-hidden select-none touch-none bg-slate-950/40 border-y border-slate-800/50">
            {/* The Main Drum Container */}
            <div 
                className="relative w-44 h-14 transition-transform duration-700 ease-[cubic-bezier(0.15,1,0.3,1)] transform-style-3d"
                style={{ 
                    transform: `translateZ(-${radius}px) rotateX(${rotationX}deg)` 
                }}
            >
                {deckIds.map((id, i) => {
                    const isSelected = activeDeckId === id;
                    // Individual item angles around the X axis
                    const angle = -i * angleStep;

                    // Logic to dim/scale based on vertical position
                    const relativeAngle = (angle + rotationX) % 360;
                    const normalizedAngle = ((relativeAngle + 180) % 360) - 180;
                    const isVisible = Math.abs(normalizedAngle) < 90;

                    // Progressive scaling and fading as it rolls away
                    const distanceScale = 1 - (Math.abs(normalizedAngle) / 90) * 0.3;
                    const opacity = 1 - (Math.abs(normalizedAngle) / 80);

                    const deckName = user.deckNames[id] || 'UNTITLED';
                    const dCount = (user.decks[id] || []).length;

                    return (
                        <div 
                            key={id}
                            className={`absolute inset-0 backface-hidden transition-opacity duration-300 ${isSelected ? 'z-50' : 'z-10'}`}
                            style={{ 
                                transform: `rotateX(${angle}deg) translateZ(${radius}px) scale(${distanceScale})`,
                                opacity: isVisible ? Math.max(0.05, opacity) : 0,
                                transformStyle: 'preserve-3d',
                                pointerEvents: isVisible ? 'auto' : 'none'
                            }}
                        >
                            <SlantedButton 
                                variant={isSelected ? 'primary' : 'secondary'}
                                fullWidth
                                size="md"
                                className={`!h-full shadow-2xl transition-all duration-500 ${isSelected ? 'shadow-indigo-500/50 ring-2 ring-indigo-400' : 'opacity-60'}`}
                                onClick={() => onSelectDeck(id)}
                            >
                                <div className="flex flex-col items-center justify-center w-full h-full pointer-events-none pt-1 pb-0.5">
                                    <div className="flex items-center gap-1">
                                        <span className={`text-[0.45rem] font-black uppercase tracking-widest ${isSelected ? 'text-indigo-200' : 'text-white/30'}`}>
                                            Deck 0{id}
                                        </span>
                                        {dCount < 12 && <div className="w-1.5 h-1.5 rounded-full bg-amber-500 shadow-[0_0_5px_rgba(245,158,11,0.8)]" />}
                                    </div>
                                    <div className="flex-1 w-full min-h-0 flex items-center justify-center">
                                        <GameText 
                                            text={deckName} 
                                            baseFontSize={20} 
                                            maxLines={1}
                                            className="text-white"
                                        />
                                    </div>
                                </div>
                            </SlantedButton>

                            {/* Active Glow for the centered item */}
                            {isSelected && (
                                <div className="absolute inset-0 -z-10 bg-indigo-500/20 blur-xl rounded-lg animate-pulse" />
                            )}
                        </div>
                    );
                })}
            </div>

            {/* Selection Guides (Visual cues for the "Slot" center) */}
            <div className="absolute left-0 right-0 h-16 border-y border-white/5 pointer-events-none z-0" />

            <style>{`
                .transform-style-3d { transform-style: preserve-3d; }
                .backface-hidden { backface-visibility: hidden; }
            `}</style>
        </div>
    );
};

