import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useUser } from '../../contexts/UserContext';
import { SlantedButton } from '../ui/SlantedButton';
import { GameText } from '../ui/GameText';

interface DeckSelectorProps {
    activeDeckId: number;
    onSelectDeck: (id: number) => void;
}

/**
 * UTILITY: CONVERT DATE TO RELATIVE STRING
 */
const getRelativeTimeString = (isoString: string) => {
    const date = new Date(isoString);
    const now = new Date();
    const diffInMs = now.getTime() - date.getTime();
    const diffInDays = Math.floor(diffInMs / (1000 * 60 * 60 * 24));

    if (diffInDays <= 0) return 'today';
    if (diffInDays === 1) return 'yesterday';
    if (diffInDays < 7) return `${diffInDays} days ago`;

    const diffInWeeks = Math.floor(diffInDays / 7);
    if (diffInWeeks === 1) return 'a week ago';
    if (diffInWeeks < 4) return `${diffInWeeks} weeks ago`;

    const diffInMonths = Math.floor(diffInDays / 30);
    if (diffInMonths === 1) return 'a month ago';
    if (diffInMonths < 12) return `${diffInMonths} months ago`;

    return 'a long time ago';
};

/**
 * 3D KINETIC DRUM SELECTOR
 * Optimized for 5-item visibility and robust wrapping logic.
 */
export const DeckSelector3D: React.FC<DeckSelectorProps> = ({ activeDeckId, onSelectDeck }) => {
    const { user } = useUser();
    const deckIds = Object.keys(user.decks).map(Number).sort((a, b) => a - b);
    const count = deckIds.length;
    const angleStep = 360 / count;

    // --- Physics State ---
    const [visualRotation, setVisualRotation] = useState((activeDeckId - 1) * angleStep);
    const rotationRef = useRef((activeDeckId - 1) * angleStep);
    const velocityRef = useRef(0);
    const isDraggingRef = useRef(false);
    const lastPointerY = useRef(0);
    const lastTime = useRef(0);
    const requestRef = useRef<number | null>(null);

    useEffect(() => {
        if (!isDraggingRef.current && velocityRef.current === 0) {
            const target = (activeDeckId - 1) * angleStep;
            rotationRef.current = target;
            setVisualRotation(target);
        }
    }, [activeDeckId, angleStep]);

    const stopSpin = useCallback(() => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
        velocityRef.current = 0;
    }, []);

    const animate = useCallback(() => {
        if (isDraggingRef.current) return;
        velocityRef.current *= 0.95;
        rotationRef.current += velocityRef.current;
        setVisualRotation(rotationRef.current);

        if (Math.abs(velocityRef.current) < 0.2) {
            const targetIndex = Math.round(rotationRef.current / angleStep);
            const targetRotation = targetIndex * angleStep;
            const diff = targetRotation - rotationRef.current;
            rotationRef.current += diff * 0.2;
            setVisualRotation(rotationRef.current);

            if (Math.abs(diff) < 0.1) {
                rotationRef.current = targetRotation;
                setVisualRotation(targetRotation);
                velocityRef.current = 0;
                const finalId = ((targetIndex % count + count) % count) + 1;
                if (finalId !== activeDeckId) {
                    onSelectDeck(finalId);
                }
                return;
            }
        }
        requestRef.current = requestAnimationFrame(animate);
    }, [angleStep, count, activeDeckId, onSelectDeck]);

    const handlePointerDown = (e: React.PointerEvent) => {
        stopSpin();
        isDraggingRef.current = true;
        lastPointerY.current = e.clientY;
        lastTime.current = performance.now();
    };

    const handlePointerMove = (e: React.PointerEvent) => {
        if (!isDraggingRef.current) return;
        const now = performance.now();
        const deltaY = e.clientY - lastPointerY.current;
        const deltaTime = now - lastTime.current;
        const rotationDelta = -(deltaY / 150) * angleStep;
        rotationRef.current += rotationDelta;
        setVisualRotation(rotationRef.current);
        if (deltaTime > 0) velocityRef.current = rotationDelta / (deltaTime / 16.67);
        lastPointerY.current = e.clientY;
        lastTime.current = now;
    };

    const handlePointerUp = () => {
        if (!isDraggingRef.current) return;
        isDraggingRef.current = false;
        requestRef.current = requestAnimationFrame(animate);
    };

    // Radius tuned for separation on a 36-degree step
    const radius = 135; 

    return (
        <div 
            className="w-full h-80 flex items-center justify-center perspective-[1200px] overflow-hidden select-none touch-none bg-slate-950/40 border-y border-slate-800/50"
            onPointerDown={handlePointerDown}
            onPointerMove={handlePointerMove}
            onPointerUp={handlePointerUp}
            onPointerLeave={handlePointerUp}
        >
            <div 
                className="relative w-64 h-24 transform-style-3d pointer-events-none"
                style={{ transform: `translateZ(-${radius}px) rotateX(${visualRotation}deg)` }}
            >
                {deckIds.map((id, i) => {
                    const angle = -i * angleStep;
                    // --- BULLETPROOF ANGLE WRAPPING ---
                    // This ensures items don't vanish during modulo wrap around
                    let normalizedAngle = (angle + visualRotation) % 360;
                    while (normalizedAngle > 180) normalizedAngle -= 360;
                    while (normalizedAngle < -180) normalizedAngle += 360;

                    // Wide visibility to catch all 5 positions (+/- 72 deg)
                    const isVisible = Math.abs(normalizedAngle) < 110; 

                    // Scaling and opacity fallout
                    const distanceScale = 1 - (Math.abs(normalizedAngle) / 100) * 0.35;
                    const opacity = 1 - (Math.abs(normalizedAngle) / 130);
                    const isCenter = Math.abs(normalizedAngle) < (angleStep / 2);

                    const deckName = user.deckNames[id] || 'UNTITLED';
                    const stats = user.deckStats[id];
                    const dateStr = stats ? getRelativeTimeString(stats.lastModified) : 'some time ago';

                    return (
                        <div 
                            key={id}
                            className={`absolute inset-0 backface-hidden transition-opacity duration-300 ${isCenter ? 'z-50' : 'z-10'}`}
                            style={{ 
                                transform: `rotateX(${angle}deg) translateZ(${radius}px) scale(${distanceScale})`,
                                opacity: isVisible ? Math.max(0.05, opacity) : 0,
                                transformStyle: 'preserve-3d'
                            }}
                        >
                            <SlantedButton 
                                variant={isCenter ? 'primary' : 'secondary'}
                                fullWidth
                                size="lg"
                                className={`!h-full shadow-2xl transition-all duration-300 ${isCenter ? 'shadow-indigo-500/20' : 'opacity-70 grayscale-[0.3]'}`}
                            >
                                <div className="flex flex-col items-center justify-center w-full h-full pointer-events-none px-4 py-2">
                                    <div className="w-full h-8 flex items-center justify-center">
                                        <GameText 
                                            text={deckName} 
                                            baseFontSize={30} 
                                            maxLines={1}
                                            className={isCenter ? 'text-white' : 'text-indigo-100'}
                                        />
                                    </div>

                                    <div className="w-full h-4 flex items-center justify-center gap-4 opacity-80">
                                        <div className="flex items-center gap-1 h-full">
                                            <span className={`text-[0.4rem] font-black uppercase tracking-tighter ${isCenter ? 'text-indigo-300' : 'text-indigo-400/60'}`}>CQ</span>
                                            <div className="w-10 h-full"><GameText text={`${stats?.conquestWinRate || 0}%`} baseFontSize={16} className="text-white" /></div>
                                        </div>
                                        <div className="w-px h-2 bg-white/20" />
                                        <div className="flex items-center gap-1 h-full">
                                            <span className={`text-[0.4rem] font-black uppercase tracking-tighter ${isCenter ? 'text-blue-300' : 'text-blue-400/60'}`}>LD</span>
                                            <div className="w-10 h-full"><GameText text={`${stats?.ladderWinRate || 0}%`} baseFontSize={16} className="text-white" /></div>
                                        </div>
                                    </div>

                                    <div className="w-full h-3 mt-1 opacity-50">
                                        <GameText 
                                            text={`Modified ${dateStr}`} 
                                            baseFontSize={14} 
                                            className="text-white lowercase italic"
                                        />
                                    </div>
                                </div>
                            </SlantedButton>
                        </div>
                    );
                })}
            </div>

            {/* Selection Guides */}
            <div className="absolute left-0 right-0 h-28 border-y border-white/10 pointer-events-none z-0 bg-gradient-to-b from-transparent via-indigo-500/5 to-transparent" />

            <style>{`
                .transform-style-3d { transform-style: preserve-3d; }
                .backface-hidden { backface-visibility: hidden; }
            `}</style>
        </div>
    );
};

