interface DeckSelectorProps {
    activeDeckId: number;
    onSelectDeck: (id: number) => void;
}

const getRelativeTimeString = (isoString: string) => {
    const date = new Date(isoString);
    const now = new Date();
    const diffInMs = now.getTime() - date.getTime();
    const diffInDays = Math.floor(diffInMs / (1000 * 60 * 60 * 24));
    if (diffInDays <= 0) return 'today';
    if (diffInDays === 1) return 'yesterday';
    if (diffInDays < 7) return `${diffInDays} days ago`;
    const diffInWeeks = Math.floor(diffInDays / 7);
    if (diffInWeeks === 1) return 'a week ago';
    if (diffInWeeks < 4) return `${diffInWeeks} weeks ago`;
    const diffInMonths = Math.floor(diffInDays / 30);
    if (diffInMonths === 1) return 'a month ago';
    if (diffInMonths < 12) return `${diffInMonths} months ago`;
    return 'a long time ago';
};

export const DeckSelector3D: React.FC<DeckSelectorProps> = ({ activeDeckId, onSelectDeck }) => {
    const { user } = useUser();
    const deckIds = Object.keys(user.decks).map(Number).sort((a, b) => a - b);
    const count = deckIds.length;
    const angleStep = 360 / count;
    const radius = 110;

    // --- High Performance Physics Refs ---
    const drumRef = useRef<HTMLDivElement>(null);
    const itemsRef = useRef<(HTMLDivElement | null)[]>([]);
    const rotationRef = useRef((activeDeckId - 1) * angleStep);
    const velocityRef = useRef(0);
    const isDraggingRef = useRef(false);
    const lastPointerY = useRef(0);
    const lastTime = useRef(0);
    const requestRef = useRef<number | null>(null);

    // --- Kinetic Audio Engine Refs ---
    const lastCenteredIndexRef = useRef<number>(activeDeckId - 1);
    const lastTickStepRef = useRef<number>(Math.round(rotationRef.current / angleStep));
    const lastAudioTimeRef = useRef<number>(0);

    useEffect(() => {
        if (!isDraggingRef.current && velocityRef.current === 0) {
            rotationRef.current = (activeDeckId - 1) * angleStep;
            updateDom(rotationRef.current);
        }
    }, [activeDeckId, angleStep]);

    /**
     * ULTRA-PERFORMANCE DOM ENGINE
     */
    const updateDom = useCallback((rot: number, isFinalSnap: boolean = false) => {
        if (!drumRef.current) return;

        drumRef.current.style.transform = `translate3d(0, 0, -${radius}px) rotateX(${rot}deg)`;

        let currentCenterI = -1;

        // 1. UPDATE VISUALS (Highlighting & Cull)
        for (let i = 0; i < itemsRef.current.length; i++) {
            const item = itemsRef.current[i];
            if (!item) continue;

            const angle = -i * angleStep;
            let normalizedAngle = (angle + rot) % 360;
            while (normalizedAngle > 180) normalizedAngle -= 360;
            while (normalizedAngle < -180) normalizedAngle += 360;

            const absAngle = Math.abs(normalizedAngle);

            if (absAngle < 110) {
                const distanceScale = 1 - (absAngle / 100) * 0.35;
                const opacity = 1 - (absAngle / 130);

                item.style.transform = `rotateX(${angle}deg) translate3d(0, 0, ${radius}px) scale(${distanceScale})`;
                item.style.opacity = Math.max(0.05, opacity).toString();
                item.style.visibility = 'visible';

                // Determine if this is the focal item
                if (absAngle < (angleStep / 2)) {
                    currentCenterI = i;
                }
            } else {
                item.style.visibility = 'hidden';
                item.style.opacity = '0';
            }
        }

        // 2. DIFFERENTIAL VISUAL SWAP (Purple Highlight)
        if (currentCenterI !== -1 && currentCenterI !== lastCenteredIndexRef.current) {
            const prevItem = itemsRef.current[lastCenteredIndexRef.current];
            const nextItem = itemsRef.current[currentCenterI];
            if (prevItem) { prevItem.classList.remove('is-visually-center'); prevItem.style.zIndex = '10'; }
            if (nextItem) { nextItem.classList.add('is-visually-center'); nextItem.style.zIndex = '50'; }
            lastCenteredIndexRef.current = currentCenterI;
        }

        // 3. ROBUST KINETIC AUDIO (Boundary Crossing Detection)
        // Instead of visual collision, we track the wheel's absolute step progression.
        // This ensures sound triggers even if a deck passes the center between frames.
        const currentStep = Math.round(rot / angleStep);
        if (currentStep !== lastTickStepRef.current) {
            const now = performance.now();
            // 10ms lockout is the human threshold for distinct "ticks"
            if (now - lastAudioTimeRef.current > 10) {
                // Use a sharp, crisp click for the tactile "purple turn" moment
                audio.play('sfx_ui_click', 0.35); 
                lastAudioTimeRef.current = now;
            }
            lastTickStepRef.current = currentStep;
        }

        // Heavy confirmation sound for final snap
        if (isFinalSnap) {
            audio.play('sfx_ui_click', 0.85);
        }
    }, [angleStep, radius]);

    const animate = useCallback(() => {
        if (isDraggingRef.current) return;

        // Increase friction (lower number) to bring wheel to rest sooner
        velocityRef.current *= 0.972; 
        rotationRef.current += velocityRef.current;

        // Increase entry threshold (0.2) to start magnetic pull earlier
        if (Math.abs(velocityRef.current) < 0.22) {
            const targetIndex = Math.round(rotationRef.current / angleStep);
            const targetRotation = targetIndex * angleStep;
            const diff = targetRotation - rotationRef.current;

            // SIGNIFICANTLY increase snap speed (0.2 -> 0.42) for immediate magnetic reaction
            rotationRef.current += diff * 0.42;

            // Increase lock threshold (0.1) for a decisive finish
            if (Math.abs(diff) < 0.1) {
                rotationRef.current = targetRotation;
                velocityRef.current = 0;
                updateDom(rotationRef.current, true); 
                const finalId = ((targetIndex % count + count) % count) + 1;
                if (finalId !== activeDeckId) onSelectDeck(finalId);
                return;
            }
        }

        updateDom(rotationRef.current);
        requestRef.current = requestAnimationFrame(animate);
    }, [angleStep, count, activeDeckId, onSelectDeck, updateDom]);

    const handlePointerDown = (e: React.PointerEvent) => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
        isDraggingRef.current = true;
        lastPointerY.current = e.clientY;
        lastTime.current = performance.now();
    };

    const handlePointerMove = (e: React.PointerEvent) => {
        if (!isDraggingRef.current) return;
        const now = performance.now();
        const deltaY = e.clientY - lastPointerY.current;
        const deltaTime = now - lastTime.current;

        const rotationDelta = -(deltaY / 100) * angleStep;

        rotationRef.current += rotationDelta;
        updateDom(rotationRef.current);

        if (deltaTime > 0) {
            const instantVelocity = rotationDelta / (deltaTime / 16.67);
            velocityRef.current = velocityRef.current * 0.2 + instantVelocity * 0.8;
        }

        lastPointerY.current = e.clientY;
        lastTime.current = now;
    };

    const handlePointerUp = () => {
        if (!isDraggingRef.current) return;
        isDraggingRef.current = false;
        requestRef.current = requestAnimationFrame(animate);
    };

    return (
        <div 
            className="w-full h-64 flex items-center justify-center perspective-[1200px] overflow-hidden select-none touch-none bg-slate-950/40 border-y border-slate-800/50"
            onPointerDown={handlePointerDown}
            onPointerMove={handlePointerMove}
            onPointerUp={handlePointerUp}
            onPointerLeave={handlePointerUp}
        >
            <div 
                ref={drumRef}
                className="relative w-64 h-24 transform-style-3d pointer-events-none will-change-transform"
                style={{ transform: `translate3d(0, 0, -${radius}px) rotateX(${rotationRef.current}deg)` }}
            >
                {deckIds.map((id, i) => {
                    const deckName = user.deckNames[id] || 'UNTITLED';
                    const stats = user.deckStats[id];
                    const dateStr = stats ? getRelativeTimeString(stats.lastModified) : 'some time ago';
                    const isInitialCenter = activeDeckId === id;

                    return (
                        <div 
                            key={id}
                            ref={el => itemsRef.current[i] = el}
                            className={`absolute inset-0 backface-hidden transition-opacity duration-300 transform-style-3d will-change-transform ${isInitialCenter ? 'is-visually-center' : ''}`}
                            style={{ 
                                transform: `rotateX(${-i * angleStep}deg) translate3d(0, 0, ${radius}px)`,
                                opacity: isInitialCenter ? 1 : 0.5,
                                zIndex: isInitialCenter ? 50 : 10
                            }}
                        >
                            <SlantedButton 
                                variant="secondary" 
                                fullWidth
                                size="lg"
                                className="!h-full shadow-2xl drum-item-button"
                            >
                                <div className="flex flex-col items-center justify-center w-full h-full pointer-events-none px-4 py-2">
                                    <div className="w-full h-8 flex items-center justify-center">
                                        <GameText text={deckName} baseFontSize={30} maxLines={1} className="text-white" />
                                    </div>
                                    <div className="w-full h-4 flex items-center justify-center gap-4 opacity-80">
                                        <div className="flex items-center gap-1 h-full stats-cq">
                                            <span className="text-[0.4rem] font-black uppercase tracking-tighter label-cq">CQ</span>
                                            <div className="w-10 h-full"><GameText text={`${stats?.conquestWinRate || 0}%`} baseFontSize={16} className="text-white" /></div>
                                        </div>
                                        <div className="w-px h-2 bg-white/20" />
                                        <div className="flex items-center gap-1 h-full stats-ld">
                                            <span className="text-[0.4rem] font-black uppercase tracking-tighter label-ld">LD</span>
                                            <div className="w-10 h-full"><GameText text={`${stats?.ladderWinRate || 0}%`} baseFontSize={16} className="text-white" /></div>
                                        </div>
                                    </div>
                                    <div className="w-full h-3 mt-1 opacity-50">
                                        <GameText text={`Modified ${dateStr}`} baseFontSize={14} className="text-white lowercase italic" />
                                    </div>
                                </div>
                            </SlantedButton>
                        </div>
                    );
                })}
            </div>
            <div className="absolute left-0 right-0 h-24 border-y border-white/10 pointer-events-none z-0 bg-gradient-to-b from-transparent via-indigo-500/5 to-transparent" />
            <style>{`
                .transform-style-3d { transform-style: preserve-3d; }
                .backface-hidden { backface-visibility: hidden; }
                .is-visually-center .drum-item-button > div:first-child {
                    background: linear-gradient(to bottom, #9333ea, #581c87) !important;
                    border-color: #c084fc !important;
                    box-shadow: 0 0.2rem 0 #581c87, 0 0 20px rgba(168, 85, 247, 0.3) !important;
                }
                .is-visually-center .label-cq { color: #a5b4fc !important; }
                .is-visually-center .label-ld { color: #93c5fd !important; }
                .is-visually-center { filter: grayscale(0) !important; }
                div:not(.is-visually-center) { filter: grayscale(0.3); }
            `}</style>
        </div>
    );
