import { GameText } from '../ui/GameText';
import { audio } from '../../services/audio';
import { Portal } from '../ui/Portal';

interface HomeCommandBarProps {
    onNavigate: (s: ScreenKey) => void;
}

const getRelativeTimeString = (isoString: string) => {
    const date = new Date(isoString);
    const now = new Date();
    const diffInMs = now.getTime() - date.getTime();
    const diffInDays = Math.floor(diffInMs / (1000 * 60 * 60 * 24));
    if (diffInDays <= 0) return 'today';
    if (diffInDays === 1) return 'yesterday';
    if (diffInDays < 7) return `${diffInDays} days ago`;
    const diffInWeeks = Math.floor(diffInDays / 7);
    if (diffInWeeks === 1) return 'a week ago';
    if (diffInWeeks < 4) return `${diffInWeeks} weeks ago`;
    const diffInMonths = Math.floor(diffInDays / 30);
    if (diffInMonths === 1) return 'a month ago';
    if (diffInMonths < 12) return `${diffInMonths} months ago`;
    return 'a long time ago';
};

export const HomeCommandBar: React.FC<HomeCommandBarProps> = ({ onNavigate }) => {
    const { user, activeDeck, setActiveDeck } = useUser();
    const [isRollerOpen, setIsRollerOpen] = useState(false);

    const activeDeckId = user.activeDeckId;
    const activeDeckName = user.deckNames[activeDeckId] || 'UNTITLED';
    const isIncomplete = activeDeck.length < 12;

    const deckIds = Object.keys(user.decks).map(Number).sort((a, b) => a - b);
    const count = deckIds.length;
    const angleStep = 360 / count;
    const radius = 130;

    // --- Performance Physics Refs ---
    const drumRef = useRef<HTMLDivElement>(null);
    const itemsRef = useRef<(HTMLDivElement | null)[]>([]);
    const rotationRef = useRef((activeDeckId - 1) * angleStep);
    const velocityRef = useRef(0);
    const isDraggingRef = useRef(false);
    const lastPointerY = useRef(0);
    const lastTime = useRef(0);
    const requestRef = useRef<number | null>(null);

    // --- Kinetic Audio Refs ---
    const lastCenteredIndexRef = useRef<number>(activeDeckId - 1);
    const lastTickStepRef = useRef<number>(Math.round(rotationRef.current / angleStep));
    const lastAudioTimeRef = useRef<number>(0);

    /**
     * GPU-ACCELERATED DOM ENGINE
     */
    const updateDom = useCallback((rot: number, isFinalSnap: boolean = false) => {
        if (!drumRef.current) return;
        drumRef.current.style.transform = `translate3d(0, 0, -${radius}px) rotateX(${rot}deg)`;

        let currentCenterI = -1;

        for (let i = 0; i < itemsRef.current.length; i++) {
            const item = itemsRef.current[i];
            if (!item) continue;

            const angle = -i * angleStep;
            let normalizedAngle = (angle + rot) % 360;
            while (normalizedAngle > 180) normalizedAngle -= 360;
            while (normalizedAngle < -180) normalizedAngle += 360;

            const absAngle = Math.abs(normalizedAngle);

            if (absAngle < 110) {
                const distanceScale = 1 - (absAngle / 100) * 0.35;
                const opacity = 1 - (absAngle / 130);

                item.style.transform = `rotateX(${angle}deg) translate3d(0, 0, ${radius}px) scale(${distanceScale})`;
                item.style.opacity = Math.max(0.1, opacity).toString();
                item.style.visibility = 'visible';

                if (absAngle < (angleStep / 2)) currentCenterI = i;
            } else {
                item.style.visibility = 'hidden';
                item.style.opacity = '0';
            }
        }

        // Visual Swap
        if (currentCenterI !== -1 && currentCenterI !== lastCenteredIndexRef.current) {
            const prevItem = itemsRef.current[lastCenteredIndexRef.current];
            const nextItem = itemsRef.current[currentCenterI];
            if (prevItem) prevItem.classList.remove('is-visually-center');
            if (nextItem) nextItem.classList.add('is-visually-center');
            lastCenteredIndexRef.current = currentCenterI;
        }

        // High Fidelity Audio Tick
        const currentStep = Math.round(rot / angleStep);
        if (currentStep !== lastTickStepRef.current) {
            const now = performance.now();
            if (now - lastAudioTimeRef.current > 10) {
                audio.play('sfx_ui_click', 0.3);
                lastAudioTimeRef.current = now;
            }
            lastTickStepRef.current = currentStep;
        }

        if (isFinalSnap) {
            audio.play('sfx_ui_click', 0.85);
        }
    }, [angleStep, radius]);

    const animate = useCallback(() => {
        if (isDraggingRef.current) return;

        // Sharper friction (0.985 -> 0.972)
        velocityRef.current *= 0.972;
        rotationRef.current += velocityRef.current;

        // Snappier pull threshold (0.15 -> 0.22)
        if (Math.abs(velocityRef.current) < 0.22) {
            const targetIndex = Math.round(rotationRef.current / angleStep);
            const targetRotation = targetIndex * angleStep;
            const diff = targetRotation - rotationRef.current;

            // SIGNIFICANTLY faster pull-in (0.22 -> 0.45)
            rotationRef.current += diff * 0.45;

            // Decisive lock-in threshold (0.1)
            if (Math.abs(diff) < 0.1) {
                rotationRef.current = targetRotation;
                velocityRef.current = 0;
                updateDom(rotationRef.current, true);
                const finalId = ((targetIndex % count + count) % count) + 1;
                if (finalId !== user.activeDeckId) setActiveDeck(finalId);
                return;
            }
        }
        updateDom(rotationRef.current);
        requestRef.current = requestAnimationFrame(animate);
    }, [angleStep, count, user.activeDeckId, setActiveDeck, updateDom]);

    const handlePointerDown = (e: React.PointerEvent) => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
        isDraggingRef.current = true;
        lastPointerY.current = e.clientY;
        lastTime.current = performance.now();
    };

    const handlePointerMove = (e: React.PointerEvent) => {
        if (!isDraggingRef.current) return;
        const now = performance.now();
        const deltaY = e.clientY - lastPointerY.current;
        const deltaTime = now - lastTime.current;

        const rotationDelta = -(deltaY / 100) * angleStep;

        rotationRef.current += rotationDelta;
        updateDom(rotationRef.current);

        if (deltaTime > 0) {
            const instantVelocity = rotationDelta / (deltaTime / 16.67);
            velocityRef.current = velocityRef.current * 0.3 + instantVelocity * 0.7;
        }
        lastPointerY.current = e.clientY;
        lastTime.current = now;
    };

    const handlePointerUp = () => {
        if (!isDraggingRef.current) return;
        isDraggingRef.current = false;
        requestRef.current = requestAnimationFrame(animate);
    };

    useEffect(() => {
        if (isRollerOpen) {
            const t = setTimeout(() => updateDom(rotationRef.current), 50);
            return () => clearTimeout(t);
        }
    }, [isRollerOpen, updateDom]);

    return (
        <div className="w-full flex items-end justify-between px-2 pb-3 gap-1 pointer-events-none relative h-16">
            {isRollerOpen && (
                <Portal>
                    <div 
                        className="fixed inset-0 z-[600] pointer-events-auto bg-black/40 backdrop-blur-md flex flex-col items-center justify-center" 
                        onClick={() => setIsRollerOpen(false)}
                        onPointerDown={handlePointerDown}
                        onPointerMove={handlePointerMove}
                        onPointerUp={handlePointerUp}
                        onPointerLeave={handlePointerUp}
                    >
                        <div className="w-full h-[32rem] perspective-[1500px] flex items-center justify-center select-none touch-none animate-pop overflow-visible">
                            <div 
                                ref={drumRef}
                                className="relative w-64 h-24 transform-style-3d pointer-events-none will-change-transform"
                                style={{ transform: `translate3d(0, 0, -${radius}px) rotateX(${rotationRef.current}deg)` }}
                            >
                                {deckIds.map((id, i) => {
                                    const stats = user.deckStats[id];
                                    const dateStr = stats ? getRelativeTimeString(stats.lastModified) : 'some time ago';
                                    const isInitialCenter = user.activeDeckId === id;
                                    return (
                                        <div 
                                            key={id}
                                            ref={el => itemsRef.current[i] = el}
                                            className={`absolute inset-0 backface-hidden transform-style-3d will-change-transform ${isInitialCenter ? 'is-visually-center' : ''}`}
                                            style={{ 
                                                transform: `rotateX(${-i * angleStep}deg) translate3d(0, 0, ${radius}px)`,
                                                opacity: isInitialCenter ? 1 : 0.4,
                                                zIndex: i === lastCenteredIndexRef.current ? 50 : 10
                                            }}
                                        >
                                            <SlantedButton
                                                variant="secondary"
                                                fullWidth
                                                size="lg"
                                                className="!h-full shadow-2xl drum-item-button"
                                            >
                                                <div className="flex flex-col items-center justify-center w-full h-full pointer-events-none px-4">
                                                    <div className="w-full h-8"><GameText text={user.deckNames[id] || 'UNTITLED'} baseFontSize={30} className="text-white" maxLines={1} /></div>
                                                    <div className="flex items-center gap-3 opacity-90 h-4">
                                                        <div className="flex items-center gap-1 h-full stats-cq">
                                                            <span className="text-[0.4rem] font-black text-indigo-300 uppercase label-cq">CQ</span>
                                                            <div className="w-10 h-full"><GameText text={`${stats?.conquestWinRate || 0}%`} baseFontSize={16} /></div>
                                                        </div>
                                                        <div className="flex items-center gap-1 h-full stats-ld">
                                                            <span className="text-[0.4rem] font-black text-blue-300 uppercase label-ld">LD</span>
                                                            <div className="w-10 h-full"><GameText text={`${stats?.ladderWinRate || 0}%`} baseFontSize={16} /></div>
                                                        </div>
                                                    </div>
                                                    <div className="w-full h-3 mt-1 opacity-50"><GameText text={`Changed ${dateStr}`} baseFontSize={14} className="lowercase italic" /></div>
                                                </div>
                                            </SlantedButton>
                                        </div>
                                    );
                                })}
                            </div>
                        </div>
                    </div>
                </Portal>
            )}

            <div className="w-[13.5%] pointer-events-auto">
                <SlantedButton variant="secondary" size="md" onClick={() => onNavigate('HISTORY')} className="w-full !h-10 shadow-slate-900/50" icon={
                    <div className="flex items-center justify-center w-full h-full scale-75">
                        <svg className="w-6 h-6 text-slate-200" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
                        </svg>
                    </div>
                } />
            </div>

            <div className="w-[23%] pointer-events-auto">
                <SlantedButton variant="warning" fullWidth size="lg" onClick={() => onNavigate('GAME')} className="!h-13 shadow-amber-900/50">
                    <div className="flex flex-col items-center justify-center w-full h-full text-center px-0.5">
                        <div className="w-full h-3.5 opacity-60"><GameText text="PLAY" baseFontSize={18} /></div>
                        <div className="w-full h-9 -mt-2.5"><GameText text="CONQUEST" baseFontSize={38} maxLines={1} className="italic tracking-tighter" /></div>
                    </div>
                </SlantedButton>
            </div>

            <div className="w-[23%] pointer-events-auto">
                <SlantedButton 
                    variant={isRollerOpen ? 'primary' : 'secondary'} 
                    fullWidth
                    size="lg"
                    onClick={() => { setIsRollerOpen(!isRollerOpen); audio.playUiClick(); }}
                    className={`!h-13 shadow-slate-900/40 relative z-[70] transition-transform ${isRollerOpen ? 'scale-105' : ''}`}
                >
                    <div className="flex flex-col items-center justify-center w-full h-full text-center px-0.5 py-1">
                        <div className="flex items-center justify-center gap-1 w-full h-3 opacity-60">
                            <div className="w-max h-full"><GameText text="DECK" baseFontSize={16} /></div>
                            {isIncomplete && <div className="w-1 h-1 rounded-full bg-amber-500 animate-pulse" />}
                        </div>
                        <div className="flex-1 w-full min-h-0"><GameText text={activeDeckName} baseFontSize={34} maxLines={2} className="italic tracking-tighter leading-none" /></div>
                    </div>
                </SlantedButton>
            </div>

            <div className="w-[23%] pointer-events-auto">
                <SlantedButton variant="blue" fullWidth size="lg" onClick={() => onNavigate('GAME')} className="!h-13 shadow-blue-900/50">
                    <div className="flex flex-col items-center justify-center w-full h-full text-center px-0.5">
                        <div className="w-full h-3.5 opacity-60"><GameText text="PLAY" baseFontSize={18} /></div>
                        <div className="w-full h-9 -mt-2.5"><GameText text="LADDER" baseFontSize={38} maxLines={1} className="italic tracking-tighter" /></div>
                    </div>
                </SlantedButton>
            </div>

            <div className="w-[13.5%] pointer-events-auto">
                <SlantedButton variant="blue" size="md" onClick={() => onNavigate('RANK')} className="w-full !h-10 shadow-blue-900/40 border-blue-400/40">
                    <div className="flex flex-col items-center justify-center w-full h-full text-center px-0.5">
                        <div className="w-full h-3 opacity-80 text-blue-100"><GameText text="RANK" baseFontSize={18} /></div>
                        <div className="w-full h-7 -mt-2"><GameText text={user.rank.toString()} baseFontSize={38} className="text-white drop-shadow-[0_1px_2px_rgba(0,0,0,0.6)]" /></div>
                    </div>
                </SlantedButton>
            </div>

            <style>{`
                .transform-style-3d { transform-style: preserve-3d; }
                .backface-hidden { backface-visibility: hidden; }
                .is-visually-center .drum-item-button > div:first-child {
                    background: linear-gradient(to bottom, #9333ea, #581c87) !important;
                    border-color: #c084fc !important;
                    box-shadow: 0 0.2rem 0 #581c87, 0 0 20px rgba(168, 85, 247, 0.3) !important;
                }
                .is-visually-center .label-cq { color: #a5b4fc !important; }
                .is-visually-center .label-ld { color: #93c5fd !important; }
                .is-visually-center { filter: grayscale(0) !important; }
            `}</style>
        </div>
    );
};

import React, { useEffect, useRef, useCallback } from 'react';
import { useUser } from '../../contexts/UserContext';
import { SlantedButton } from '../ui/SlantedButton';
import { GameText } from '../ui/GameText';
import { audio } from '../../services/audio';

interface DeckSelectorProps {
    activeDeckId: number;
    onSelectDeck: (id: number) => void;
}

const getRelativeTimeString = (isoString: string) => {
    const date = new Date(isoString);
    const now = new Date();
    const diffInMs = now.getTime() - date.getTime();
    const diffInDays = Math.floor(diffInMs / (1000 * 60 * 60 * 24));
    if (diffInDays <= 0) return 'today';
    if (diffInDays === 1) return 'yesterday';
    if (diffInDays < 7) return `${diffInDays} days ago`;
    const diffInWeeks = Math.floor(diffInDays / 7);
    if (diffInWeeks === 1) return 'a week ago';
    if (diffInWeeks < 4) return `${diffInWeeks} weeks ago`;
    const diffInMonths = Math.floor(diffInDays / 30);
    if (diffInMonths === 1) return 'a month ago';
    if (diffInMonths < 12) return `${diffInMonths} months ago`;
    return 'a long time ago';
};

export const DeckSelector3D: React.FC<DeckSelectorProps> = ({ activeDeckId, onSelectDeck }) => {
    const { user } = useUser();
    const deckIds = Object.keys(user.decks).map(Number).sort((a, b) => a - b);
    const count = deckIds.length;
    const angleStep = 360 / count;
    const radius = 110;

    // --- High Performance Physics Refs ---
    const drumRef = useRef<HTMLDivElement>(null);
    const itemsRef = useRef<(HTMLDivElement | null)[]>([]);
    const rotationRef = useRef((activeDeckId - 1) * angleStep);
    const velocityRef = useRef(0);
    const isDraggingRef = useRef(false);
    const lastPointerY = useRef(0);
    const lastTime = useRef(0);
    const requestRef = useRef<number | null>(null);

    // Tracking refs for synced feedback
    const lastCenteredIndexRef = useRef<number>(activeDeckId - 1);
    const snapPlayedRef = useRef<boolean>(false);
    const lastAudioTimeRef = useRef<number>(0);

    useEffect(() => {
        if (!isDraggingRef.current && velocityRef.current === 0) {
            rotationRef.current = (activeDeckId - 1) * angleStep;
            updateDom(rotationRef.current);
        }
    }, [activeDeckId, angleStep]);

    /**
     * PERFORMANCE DOM ENGINE with Synced Audio
     */
    const updateDom = useCallback((rot: number) => {
        if (!drumRef.current) return;

        drumRef.current.style.transform = `translate3d(0, 0, -${radius}px) rotateX(${rot}deg)`;

        let currentCenterI = -1;

        for (let i = 0; i < itemsRef.current.length; i++) {
            const item = itemsRef.current[i];
            if (!item) continue;

            const angle = -i * angleStep;
            let normalizedAngle = (angle + rot) % 360;
            while (normalizedAngle > 180) normalizedAngle -= 360;
            while (normalizedAngle < -180) normalizedAngle += 360;

            const absAngle = Math.abs(normalizedAngle);

            if (absAngle < 110) {
                const distanceScale = 1 - (absAngle / 100) * 0.35;
                const opacity = 1 - (absAngle / 130);

                item.style.transform = `rotateX(${angle}deg) translate3d(0, 0, ${radius}px) scale(${distanceScale})`;
                item.style.opacity = Math.max(0.05, opacity).toString();
                item.style.visibility = 'visible';

                if (absAngle < (angleStep / 2)) currentCenterI = i;
            } else {
                item.style.visibility = 'hidden';
                item.style.opacity = '0';
            }
        }

        // SYNCED TICK: Trigger audio when the visual "Focus" card swaps
        if (currentCenterI !== -1 && currentCenterI !== lastCenteredIndexRef.current) {
            const prevItem = itemsRef.current[lastCenteredIndexRef.current];
            const nextItem = itemsRef.current[currentCenterI];

            // Visual Swap
            if (prevItem) { prevItem.classList.remove('is-visually-center'); prevItem.style.zIndex = '10'; }
            if (nextItem) { nextItem.classList.add('is-visually-center'); nextItem.style.zIndex = '50'; }

            // Audio Tick (Mid-Spin)
            const now = performance.now();
            if (now - lastAudioTimeRef.current > 12) {
                // Sharper tick volume for mid-spin
                audio.play('sfx_ui_hover', 0.6); 
                lastAudioTimeRef.current = now;
            }

            lastCenteredIndexRef.current = currentCenterI;
        }
    }, [angleStep, radius]);

    const animate = useCallback(() => {
        if (isDraggingRef.current) return;

        velocityRef.current *= 0.972; 
        rotationRef.current += velocityRef.current;

        // MAGNETIC SNAP PHASE
        if (Math.abs(velocityRef.current) < 0.22) {
            const targetIndex = Math.round(rotationRef.current / angleStep);
            const targetRotation = targetIndex * angleStep;
            const diff = targetRotation - rotationRef.current;

            // CRITICAL FIX: Trigger "Lock" sound the instant magnetic pull begins
            if (!snapPlayedRef.current && Math.abs(diff) > 0.1) {
                audio.play('sfx_ui_click', 1.0); // Heavy final click
                snapPlayedRef.current = true;
            }

            rotationRef.current += diff * 0.42;

            if (Math.abs(diff) < 0.05) {
                rotationRef.current = targetRotation;
                velocityRef.current = 0;
                updateDom(rotationRef.current);

                const finalId = ((targetIndex % count + count) % count) + 1;
                if (finalId !== activeDeckId) onSelectDeck(finalId);
                return;
            }
        }

        updateDom(rotationRef.current);
        requestRef.current = requestAnimationFrame(animate);
    }, [angleStep, count, activeDeckId, onSelectDeck, updateDom]);

    const handlePointerDown = (e: React.PointerEvent) => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
        isDraggingRef.current = true;
        snapPlayedRef.current = false; // Reset for next interaction
        lastPointerY.current = e.clientY;
        lastTime.current = performance.now();
    };

    const handlePointerMove = (e: React.PointerEvent) => {
        if (!isDraggingRef.current) return;
        const now = performance.now();
        const deltaY = e.clientY - lastPointerY.current;
        const deltaTime = now - lastTime.current;

        const rotationDelta = -(deltaY / 100) * angleStep;

        rotationRef.current += rotationDelta;
        updateDom(rotationRef.current);

        if (deltaTime > 0) {
            const instantVelocity = rotationDelta / (deltaTime / 16.67);
            velocityRef.current = velocityRef.current * 0.2 + instantVelocity * 0.8;
        }

        lastPointerY.current = e.clientY;
        lastTime.current = now;
    };

    const handlePointerUp = () => {
        if (!isDraggingRef.current) return;
        isDraggingRef.current = false;
        requestRef.current = requestAnimationFrame(animate);
    };

    return (
        <div 
            className="w-full h-64 flex items-center justify-center perspective-[1200px] overflow-hidden select-none touch-none bg-slate-950/40 border-y border-slate-800/50"
            onPointerDown={handlePointerDown}
            onPointerMove={handlePointerMove}
            onPointerUp={handlePointerUp}
            onPointerLeave={handlePointerUp}
        >
            <div 
                ref={drumRef}
                className="relative w-64 h-24 transform-style-3d pointer-events-none will-change-transform"
                style={{ transform: `translate3d(0, 0, -${radius}px) rotateX(${rotationRef.current}deg)` }}
            >
                {deckIds.map((id, i) => {
                    const deckName = user.deckNames[id] || 'UNTITLED';
                    const stats = user.deckStats[id];
                    const dateStr = stats ? getRelativeTimeString(stats.lastModified) : 'some time ago';
                    const isInitialCenter = activeDeckId === id;

                    return (
                        <div 
                            key={id}
                            ref={el => itemsRef.current[i] = el}
                            className={`absolute inset-0 backface-hidden transition-opacity duration-300 transform-style-3d will-change-transform ${isInitialCenter ? 'is-visually-center' : ''}`}
                            style={{ 
                                transform: `rotateX(${-i * angleStep}deg) translate3d(0, 0, ${radius}px)`,
                                opacity: isInitialCenter ? 1 : 0.5,
                                zIndex: isInitialCenter ? 50 : 10
                            }}
                        >
                            <SlantedButton 
                                variant="secondary" 
                                fullWidth
                                size="lg"
                                className="!h-full shadow-2xl drum-item-button"
                            >
                                <div className="flex flex-col items-center justify-center w-full h-full pointer-events-none px-4 py-2">
                                    <div className="w-full h-8 flex items-center justify-center">
                                        <GameText text={deckName} baseFontSize={30} maxLines={1} className="text-white" />
                                    </div>
                                    <div className="w-full h-4 flex items-center justify-center gap-4 opacity-80">
                                        <div className="flex items-center gap-1 h-full stats-cq">
                                            <span className="text-[0.4rem] font-black uppercase tracking-tighter label-cq">CQ</span>
                                            <div className="w-10 h-full"><GameText text={`${stats?.conquestWinRate || 0}%`} baseFontSize={16} className="text-white" /></div>
                                        </div>
                                        <div className="w-px h-2 bg-white/20" />
                                        <div className="flex items-center gap-1 h-full stats-ld">
                                            <span className="text-[0.4rem] font-black uppercase tracking-tighter label-ld">LD</span>
                                            <div className="w-10 h-full"><GameText text={`${stats?.ladderWinRate || 0}%`} baseFontSize={16} className="text-white" /></div>
                                        </div>
                                    </div>
                                    <div className="w-full h-3 mt-1 opacity-50">
                                        <GameText text={`Modified ${dateStr}`} baseFontSize={14} className="text-white lowercase italic" />
                                    </div>
                                </div>
                            </SlantedButton>
                        </div>
                    );
                })}
            </div>
            <div className="absolute left-0 right-0 h-24 border-y border-white/10 pointer-events-none z-0 bg-gradient-to-b from-transparent via-indigo-500/5 to-transparent" />
            <style>{`
                .transform-style-3d { transform-style: preserve-3d; }
                .backface-hidden { backface-visibility: hidden; }
                .is-visually-center .drum-item-button > div:first-child {
                    background: linear-gradient(to bottom, #9333ea, #581c87) !important;
                    border-color: #c084fc !important;
                    box-shadow: 0 0.2rem 0 #581c87, 0 0 20px rgba(168, 85, 247, 0.3) !important;
                }
                .is-visually-center .label-cq { color: #a5b4fc !important; }
                .is-visually-center .label-ld { color: #93c5fd !important; }
                .is-visually-center { filter: grayscale(0) !important; }
                div:not(.is-visually-center) { filter: grayscale(0.3); }
            `}</style>
        </div>
    );
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { ScreenKey } from '../../types';
import { useUser } from '../../contexts/UserContext';
import { SlantedButton } from '../ui/SlantedButton';
import { GameText } from '../ui/GameText';
import { audio } from '../../services/audio';
import { Portal } from '../ui/Portal';

interface HomeCommandBarProps {
    onNavigate: (s: ScreenKey) => void;
}

const getRelativeTimeString = (isoString: string) => {
    const date = new Date(isoString);
    const now = new Date();
    const diffInMs = now.getTime() - date.getTime();
    const diffInDays = Math.floor(diffInMs / (1000 * 60 * 60 * 24));
    if (diffInDays <= 0) return 'today';
    if (diffInDays === 1) return 'yesterday';
    if (diffInDays < 7) return `${diffInDays} days ago`;
    const diffInWeeks = Math.floor(diffInDays / 7);
    if (diffInWeeks === 1) return 'a week ago';
    if (diffInWeeks < 4) return `${diffInWeeks} weeks ago`;
    const diffInMonths = Math.floor(diffInDays / 30);
    if (diffInMonths === 1) return 'a month ago';
    if (diffInMonths < 12) return `${diffInMonths} months ago`;
    return 'a long time ago';
};

export const HomeCommandBar: React.FC<HomeCommandBarProps> = ({ onNavigate }) => {
    const { user, activeDeck, setActiveDeck } = useUser();
    const [isRollerOpen, setIsRollerOpen] = useState(false);

    const activeDeckId = user.activeDeckId;
    const activeDeckName = user.deckNames[activeDeckId] || 'UNTITLED';
    const isIncomplete = activeDeck.length < 12;

    const deckIds = Object.keys(user.decks).map(Number).sort((a, b) => a - b);
    const count = deckIds.length;
    const angleStep = 360 / count;
    const radius = 130;

    // --- Performance Physics Refs ---
    const drumRef = useRef<HTMLDivElement>(null);
    const itemsRef = useRef<(HTMLDivElement | null)[]>([]);
    const rotationRef = useRef((activeDeckId - 1) * angleStep);
    const velocityRef = useRef(0);
    const isDraggingRef = useRef(false);
    const lastPointerY = useRef(0);
    const lastTime = useRef(0);
    const requestRef = useRef<number | null>(null);

    // Tracking for audio-visual sync
    const lastCenteredIndexRef = useRef<number>(activeDeckId - 1);
    const snapPlayedRef = useRef<boolean>(false);
    const lastAudioTimeRef = useRef<number>(0);

    /**
     * GPU-ACCELERATED DOM ENGINE
     */
    const updateDom = useCallback((rot: number) => {
        if (!drumRef.current) return;
        drumRef.current.style.transform = `translate3d(0, 0, -${radius}px) rotateX(${rot}deg)`;

        let currentCenterI = -1;

        for (let i = 0; i < itemsRef.current.length; i++) {
            const item = itemsRef.current[i];
            if (!item) continue;

            const angle = -i * angleStep;
            let normalizedAngle = (angle + rot) % 360;
            while (normalizedAngle > 180) normalizedAngle -= 360;
            while (normalizedAngle < -180) normalizedAngle += 360;

            const absAngle = Math.abs(normalizedAngle);

            if (absAngle < 110) {
                const distanceScale = 1 - (absAngle / 100) * 0.35;
                const opacity = 1 - (absAngle / 130);

                item.style.transform = `rotateX(${angle}deg) translate3d(0, 0, ${radius}px) scale(${distanceScale})`;
                item.style.opacity = Math.max(0.1, opacity).toString();
                item.style.visibility = 'visible';

                if (absAngle < (angleStep / 2)) currentCenterI = i;
            } else {
                item.style.visibility = 'hidden';
                item.style.opacity = '0';
            }
        }

        // SYNCED AUDIO-VISUAL SWAP
        if (currentCenterI !== -1 && currentCenterI !== lastCenteredIndexRef.current) {
            const prevItem = itemsRef.current[lastCenteredIndexRef.current];
            const nextItem = itemsRef.current[currentCenterI];
            if (prevItem) prevItem.classList.remove('is-visually-center');
            if (nextItem) nextItem.classList.add('is-visually-center');

            const now = performance.now();
            if (now - lastAudioTimeRef.current > 12) {
                audio.play('sfx_ui_hover', 0.5); // Tactile mid-spin tick
                lastAudioTimeRef.current = now;
            }

            lastCenteredIndexRef.current = currentCenterI;
        }
    }, [angleStep, radius]);

    const animate = useCallback(() => {
        if (isDraggingRef.current) return;

        velocityRef.current *= 0.972;
        rotationRef.current += velocityRef.current;

        // MAGNETIC SNAP PHASE
        if (Math.abs(velocityRef.current) < 0.22) {
            const targetIndex = Math.round(rotationRef.current / angleStep);
            const targetRotation = targetIndex * angleStep;
            const diff = targetRotation - rotationRef.current;

            // Trigger sound at start of snap pull for perfect sensory timing
            if (!snapPlayedRef.current && Math.abs(diff) > 0.1) {
                audio.play('sfx_ui_click', 0.9);
                snapPlayedRef.current = true;
            }

            rotationRef.current += diff * 0.45;

            if (Math.abs(diff) < 0.1) {
                rotationRef.current = targetRotation;
                velocityRef.current = 0;
                updateDom(rotationRef.current);
                const finalId = ((targetIndex % count + count) % count) + 1;
                if (finalId !== user.activeDeckId) setActiveDeck(finalId);
                return;
            }
        }
        updateDom(rotationRef.current);
        requestRef.current = requestAnimationFrame(animate);
    }, [angleStep, count, user.activeDeckId, setActiveDeck, updateDom]);

    const handlePointerDown = (e: React.PointerEvent) => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
        isDraggingRef.current = true;
        snapPlayedRef.current = false;
        lastPointerY.current = e.clientY;
        lastTime.current = performance.now();
    };

    const handlePointerMove = (e: React.PointerEvent) => {
        if (!isDraggingRef.current) return;
        const now = performance.now();
        const deltaY = e.clientY - lastPointerY.current;
        const deltaTime = now - lastTime.current;

        const rotationDelta = -(deltaY / 100) * angleStep;

        rotationRef.current += rotationDelta;
        updateDom(rotationRef.current);

        if (deltaTime > 0) {
            const instantVelocity = rotationDelta / (deltaTime / 16.67);
            velocityRef.current = velocityRef.current * 0.3 + instantVelocity * 0.7;
        }
        lastPointerY.current = e.clientY;
        lastTime.current = now;
    };

    const handlePointerUp = () => {
        if (!isDraggingRef.current) return;
        isDraggingRef.current = false;
        requestRef.current = requestAnimationFrame(animate);
    };

    useEffect(() => {
        if (isRollerOpen) {
            const t = setTimeout(() => updateDom(rotationRef.current), 50);
            return () => clearTimeout(t);
        }
    }, [isRollerOpen, updateDom]);

    return (
        <div className="w-full flex items-end justify-between px-2 pb-3 gap-1 pointer-events-none relative h-16">
            {isRollerOpen && (
                <Portal>
                    <div 
                        className="fixed inset-0 z-[600] pointer-events-auto bg-black/40 backdrop-blur-md flex flex-col items-center justify-center" 
                        onClick={() => setIsRollerOpen(false)}
                        onPointerDown={handlePointerDown}
                        onPointerMove={handlePointerMove}
                        onPointerUp={handlePointerUp}
                        onPointerLeave={handlePointerUp}
                    >
                        <div className="w-full h-[32rem] perspective-[1500px] flex items-center justify-center select-none touch-none animate-pop overflow-visible">
                            <div 
                                ref={drumRef}
                                className="relative w-64 h-24 transform-style-3d pointer-events-none will-change-transform"
                                style={{ transform: `translate3d(0, 0, -${radius}px) rotateX(${rotationRef.current}deg)` }}
                            >
                                {deckIds.map((id, i) => {
                                    const stats = user.deckStats[id];
                                    const dateStr = stats ? getRelativeTimeString(stats.lastModified) : 'some time ago';
                                    const isInitialCenter = user.activeDeckId === id;
                                    return (
                                        <div 
                                            key={id}
                                            ref={el => itemsRef.current[i] = el}
                                            className={`absolute inset-0 backface-hidden transform-style-3d will-change-transform ${isInitialCenter ? 'is-visually-center' : ''}`}
                                            style={{ 
                                                transform: `rotateX(${-i * angleStep}deg) translate3d(0, 0, ${radius}px)`,
                                                opacity: isInitialCenter ? 1 : 0.4,
                                                zIndex: i === lastCenteredIndexRef.current ? 50 : 10
                                            }}
                                        >
                                            <SlantedButton
                                                variant="secondary"
                                                fullWidth
                                                size="lg"
                                                className="!h-full shadow-2xl drum-item-button"
                                            >
                                                <div className="flex flex-col items-center justify-center w-full h-full pointer-events-none px-4">
                                                    <div className="w-full h-8"><GameText text={user.deckNames[id] || 'UNTITLED'} baseFontSize={30} className="text-white" maxLines={1} /></div>
                                                    <div className="flex items-center gap-3 opacity-90 h-4">
                                                        <div className="flex items-center gap-1 h-full stats-cq">
                                                            <span className="text-[0.4rem] font-black text-indigo-300 uppercase label-cq">CQ</span>
                                                            <div className="w-10 h-full"><GameText text={`${stats?.conquestWinRate || 0}%`} baseFontSize={16} /></div>
                                                        </div>
                                                        <div className="flex items-center gap-1 h-full stats-ld">
                                                            <span className="text-[0.4rem] font-black text-blue-300 uppercase label-ld">LD</span>
                                                            <div className="w-10 h-full"><GameText text={`${stats?.ladderWinRate || 0}%`} baseFontSize={16} /></div>
                                                        </div>
                                                    </div>
                                                    <div className="w-full h-3 mt-1 opacity-50"><GameText text={`Changed ${dateStr}`} baseFontSize={14} className="lowercase italic" /></div>
                                                </div>
                                            </SlantedButton>
                                        </div>
                                    );
                                })}
                            </div>
                        </div>
                    </div>
                </Portal>
            )}

            <div className="w-[13.5%] pointer-events-auto">
                <SlantedButton variant="secondary" size="md" onClick={() => onNavigate('HISTORY')} className="w-full !h-10 shadow-slate-900/50" icon={
                    <div className="flex items-center justify-center w-full h-full scale-75">
                        <svg className="w-6 h-6 text-slate-200" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
                        </svg>
                    </div>
                } />
            </div>

            <div className="w-[23%] pointer-events-auto">
                <SlantedButton variant="warning" fullWidth size="lg" onClick={() => onNavigate('GAME')} className="!h-13 shadow-amber-900/50">
                    <div className="flex flex-col items-center justify-center w-full h-full text-center px-0.5">
                        <div className="w-full h-3.5 opacity-60"><GameText text="PLAY" baseFontSize={18} /></div>
                        <div className="w-full h-9 -mt-2.5"><GameText text="CONQUEST" baseFontSize={38} maxLines={1} className="italic tracking-tighter" /></div>
                    </div>
                </SlantedButton>
            </div>

            <div className="w-[23%] pointer-events-auto">
                <SlantedButton 
                    variant={isRollerOpen ? 'primary' : 'secondary'} 
                    fullWidth
                    size="lg"
                    onClick={() => { setIsRollerOpen(!isRollerOpen); audio.playUiClick(); }}
                    className={`!h-13 shadow-slate-900/40 relative z-[70] transition-transform ${isRollerOpen ? 'scale-105' : ''}`}
                >
                    <div className="flex flex-col items-center justify-center w-full h-full text-center px-0.5 py-1">
                        <div className="flex items-center justify-center gap-1 w-full h-3 opacity-60">
                            <div className="w-max h-full"><GameText text="DECK" baseFontSize={16} /></div>
                            {isIncomplete && <div className="w-1 h-1 rounded-full bg-amber-500 animate-pulse" />}
                        </div>
                        <div className="flex-1 w-full min-h-0"><GameText text={activeDeckName} baseFontSize={34} maxLines={2} className="italic tracking-tighter leading-none" /></div>
                    </div>
                </SlantedButton>
            </div>

            <div className="w-[23%] pointer-events-auto">
                <SlantedButton variant="blue" fullWidth size="lg" onClick={() => onNavigate('GAME')} className="!h-13 shadow-blue-900/50">
                    <div className="flex flex-col items-center justify-center w-full h-full text-center px-0.5">
                        <div className="w-full h-3.5 opacity-60"><GameText text="PLAY" baseFontSize={18} /></div>
                        <div className="w-full h-9 -mt-2.5"><GameText text="LADDER" baseFontSize={38} maxLines={1} className="italic tracking-tighter" /></div>
                    </div>
                </SlantedButton>
            </div>

            <div className="w-[13.5%] pointer-events-auto">
                <SlantedButton variant="blue" size="md" onClick={() => onNavigate('RANK')} className="w-full !h-10 shadow-blue-900/40 border-blue-400/40">
                    <div className="flex flex-col items-center justify-center w-full h-full text-center px-0.5">
                        <div className="w-full h-3 opacity-80 text-blue-100"><GameText text="RANK" baseFontSize={18} /></div>
                        <div className="w-full h-7 -mt-2"><GameText text={user.rank.toString()} baseFontSize={38} className="text-white drop-shadow-[0_1px_2px_rgba(0,0,0,0.6)]" /></div>
                    </div>
                </SlantedButton>
            </div>

            <style>{`
                .transform-style-3d { transform-style: preserve-3d; }
                .backface-hidden { backface-visibility: hidden; }
                .is-visually-center .drum-item-button > div:first-child {
                    background: linear-gradient(to bottom, #9333ea, #581c87) !important;
                    border-color: #c084fc !important;
                    box-shadow: 0 0.2rem 0 #581c87, 0 0 20px rgba(168, 85, 247, 0.3) !important;
                }
                .is-visually-center .label-cq { color: #a5b4fc !important; }
                .is-visually-center .label-ld { color: #93c5fd !important; }
                .is-visually-center { filter: grayscale(0) !important; }
            `}</style>
        </div>
    );
};

import React, { useEffect, useRef, useCallback } from 'react';
import { useUser } from '../../contexts/UserContext';
import { SlantedButton } from '../ui/SlantedButton';
import { GameText } from '../ui/GameText';
import { audio } from '../../services/audio';

interface DeckSelectorProps {
    activeDeckId: number;
    onSelectDeck: (id: number) => void;
}

const getRelativeTimeString = (isoString: string) => {
    const date = new Date(isoString);
    const now = new Date();
    const diffInMs = now.getTime() - date.getTime();
    const diffInDays = Math.floor(diffInMs / (1000 * 60 * 60 * 24));
    if (diffInDays <= 0) return 'today';
    if (diffInDays === 1) return 'yesterday';
    if (diffInDays < 7) return `${diffInDays} days ago`;
    const diffInWeeks = Math.floor(diffInDays / 7);
    if (diffInWeeks === 1) return 'a week ago';
    if (diffInWeeks < 4) return `${diffInWeeks} weeks ago`;
    const diffInMonths = Math.floor(diffInDays / 30);
    if (diffInMonths === 1) return 'a month ago';
    if (diffInMonths < 12) return `${diffInMonths} months ago`;
    return 'a long time ago';
};

export const DeckSelector3D: React.FC<DeckSelectorProps> = ({ activeDeckId, onSelectDeck }) => {
    const { user } = useUser();
    const deckIds = Object.keys(user.decks).map(Number).sort((a, b) => a - b);
    const count = deckIds.length;
    const angleStep = 360 / count;
    const radius = 110;

    // --- High Performance Physics Refs ---
    const drumRef = useRef<HTMLDivElement>(null);
    const itemsRef = useRef<(HTMLDivElement | null)[]>([]);
    const rotationRef = useRef((activeDeckId - 1) * angleStep);
    const velocityRef = useRef(0);
    const isDraggingRef = useRef(false);
    const lastPointerY = useRef(0);
    const lastTime = useRef(0);
    const requestRef = useRef<number | null>(null);

    // --- Kinetic Audio Engine Refs ---
    const lastCenteredIndexRef = useRef<number>(activeDeckId - 1);
    const lastTickStepRef = useRef<number>(Math.round(rotationRef.current / angleStep));
    const lastAudioTimeRef = useRef<number>(0);

    useEffect(() => {
        if (!isDraggingRef.current && velocityRef.current === 0) {
            rotationRef.current = (activeDeckId - 1) * angleStep;
            updateDom(rotationRef.current);
        }
    }, [activeDeckId, angleStep]);

    /**
     * GPU-ACCELERATED RENDERING & KINETIC AUDIO
     */
    const updateDom = useCallback((rot: number) => {
        if (!drumRef.current) return;

        drumRef.current.style.transform = `translate3d(0, 0, -${radius}px) rotateX(${rot}deg)`;

        let currentCenterI = -1;

        for (let i = 0; i < itemsRef.current.length; i++) {
            const item = itemsRef.current[i];
            if (!item) continue;

            const angle = -i * angleStep;
            let normalizedAngle = (angle + rot) % 360;
            while (normalizedAngle > 180) normalizedAngle -= 360;
            while (normalizedAngle < -180) normalizedAngle += 360;

            const absAngle = Math.abs(normalizedAngle);

            if (absAngle < 110) {
                const distanceScale = 1 - (absAngle / 100) * 0.35;
                const opacity = 1 - (absAngle / 130);

                item.style.transform = `rotateX(${angle}deg) translate3d(0, 0, ${radius}px) scale(${distanceScale})`;
                item.style.opacity = Math.max(0.05, opacity).toString();
                item.style.visibility = 'visible';

                if (absAngle < (angleStep / 2)) currentCenterI = i;
            } else {
                item.style.visibility = 'hidden';
                item.style.opacity = '0';
            }
        }

        // 1. VISUAL SWAP (Purple Highlight)
        if (currentCenterI !== -1 && currentCenterI !== lastCenteredIndexRef.current) {
            const prevItem = itemsRef.current[lastCenteredIndexRef.current];
            const nextItem = itemsRef.current[currentCenterI];
            if (prevItem) { prevItem.classList.remove('is-visually-center'); prevItem.style.zIndex = '10'; }
            if (nextItem) { nextItem.classList.add('is-visually-center'); nextItem.style.zIndex = '50'; }
            lastCenteredIndexRef.current = currentCenterI;
        }

        // 2. MATHEMATICAL TICK DETECTION (Swipe-Speed Resistant)
        // We use Math.round of the fractional step count. If this changes, a boundary was crossed.
        const currentStep = Math.round(rot / angleStep);
        if (currentStep !== lastTickStepRef.current) {
            const now = performance.now();
            // Prevent audio clipping/machine-gunning at ultra-high speeds
            if (now - lastAudioTimeRef.current > 12) {
                audio.play('sfx_ui_click', 0.4); // CRISP TICK
                lastAudioTimeRef.current = now;
            }
            lastTickStepRef.current = currentStep;
        }
    }, [angleStep, radius]);

    const animate = useCallback(() => {
        if (isDraggingRef.current) return;

        velocityRef.current *= 0.972; 
        rotationRef.current += velocityRef.current;

        // MAGNETIC SNAP PHASE
        if (Math.abs(velocityRef.current) < 0.22) {
            const targetIndex = Math.round(rotationRef.current / angleStep);
            const targetRotation = targetIndex * angleStep;
            const diff = targetRotation - rotationRef.current;

            rotationRef.current += diff * 0.42;

            // ABSOLUTE REST POINT
            if (Math.abs(diff) < 0.05) {
                rotationRef.current = targetRotation;
                velocityRef.current = 0;
                updateDom(rotationRef.current);

                // TRIGGER LOCK SOUND AT EXACT MOMENT OF PHYSICAL REST
                audio.play('sfx_ui_click', 0.95); 

                const finalId = ((targetIndex % count + count) % count) + 1;
                if (finalId !== activeDeckId) onSelectDeck(finalId);
                return;
            }
        }

        updateDom(rotationRef.current);
        requestRef.current = requestAnimationFrame(animate);
    }, [angleStep, count, activeDeckId, onSelectDeck, updateDom]);

    const handlePointerDown = (e: React.PointerEvent) => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
        isDraggingRef.current = true;
        lastPointerY.current = e.clientY;
        lastTime.current = performance.now();
    };

    const handlePointerMove = (e: React.PointerEvent) => {
        if (!isDraggingRef.current) return;
        const now = performance.now();
        const deltaY = e.clientY - lastPointerY.current;
        const deltaTime = now - lastTime.current;

        const rotationDelta = -(deltaY / 100) * angleStep;

        rotationRef.current += rotationDelta;
        updateDom(rotationRef.current);

        if (deltaTime > 0) {
            const instantVelocity = rotationDelta / (deltaTime / 16.67);
            velocityRef.current = velocityRef.current * 0.2 + instantVelocity * 0.8;
        }

        lastPointerY.current = e.clientY;
        lastTime.current = now;
    };

    const handlePointerUp = () => {
        if (!isDraggingRef.current) return;
        isDraggingRef.current = false;
        requestRef.current = requestAnimationFrame(animate);
    };

    return (
        <div 
            className="w-full h-64 flex items-center justify-center perspective-[1200px] overflow-hidden select-none touch-none bg-slate-950/40 border-y border-slate-800/50"
            onPointerDown={handlePointerDown}
            onPointerMove={handlePointerMove}
            onPointerUp={handlePointerUp}
            onPointerLeave={handlePointerUp}
        >
            <div 
                ref={drumRef}
                className="relative w-64 h-24 transform-style-3d pointer-events-none will-change-transform"
                style={{ transform: `translate3d(0, 0, -${radius}px) rotateX(${rotationRef.current}deg)` }}
            >
                {deckIds.map((id, i) => {
                    const deckName = user.deckNames[id] || 'UNTITLED';
                    const stats = user.deckStats[id];
                    const dateStr = stats ? getRelativeTimeString(stats.lastModified) : 'some time ago';
                    const isInitialCenter = activeDeckId === id;

                    return (
                        <div 
                            key={id}
                            ref={el => itemsRef.current[i] = el}
                            className={`absolute inset-0 backface-hidden transition-opacity duration-300 transform-style-3d will-change-transform ${isInitialCenter ? 'is-visually-center' : ''}`}
                            style={{ 
                                transform: `rotateX(${-i * angleStep}deg) translate3d(0, 0, ${radius}px)`,
                                opacity: isInitialCenter ? 1 : 0.5,
                                zIndex: isInitialCenter ? 50 : 10
                            }}
                        >
                            <SlantedButton 
                                variant="secondary" 
                                fullWidth
                                size="lg"
                                className="!h-full shadow-2xl drum-item-button"
                            >
                                <div className="flex flex-col items-center justify-center w-full h-full pointer-events-none px-4 py-2">
                                    <div className="w-full h-8 flex items-center justify-center">
                                        <GameText text={deckName} baseFontSize={30} maxLines={1} className="text-white" />
                                    </div>
                                    <div className="w-full h-4 flex items-center justify-center gap-4 opacity-80">
                                        <div className="flex items-center gap-1 h-full stats-cq">
                                            <span className="text-[0.4rem] font-black uppercase tracking-tighter label-cq">CQ</span>
                                            <div className="w-10 h-full"><GameText text={`${stats?.conquestWinRate || 0}%`} baseFontSize={16} className="text-white" /></div>
                                        </div>
                                        <div className="w-px h-2 bg-white/20" />
                                        <div className="flex items-center gap-1 h-full stats-ld">
                                            <span className="text-[0.4rem] font-black uppercase tracking-tighter label-ld">LD</span>
                                            <div className="w-10 h-full"><GameText text={`${stats?.ladderWinRate || 0}%`} baseFontSize={16} className="text-white" /></div>
                                        </div>
                                    </div>
                                    <div className="w-full h-3 mt-1 opacity-50">
                                        <GameText text={`Modified ${dateStr}`} baseFontSize={14} className="text-white lowercase italic" />
                                    </div>
                                </div>
                            </SlantedButton>
                        </div>
                    );
                })}
            </div>
            <div className="absolute left-0 right-0 h-24 border-y border-white/10 pointer-events-none z-0 bg-gradient-to-b from-transparent via-indigo-500/5 to-transparent" />
            <style>{`
                .transform-style-3d { transform-style: preserve-3d; }
                .backface-hidden { backface-visibility: hidden; }
                .is-visually-center .drum-item-button > div:first-child {
                    background: linear-gradient(to bottom, #9333ea, #581c87) !important;
                    border-color: #c084fc !important;
                    box-shadow: 0 0.2rem 0 #581c87, 0 0 20px rgba(168, 85, 247, 0.3) !important;
                }
                .is-visually-center .label-cq { color: #a5b4fc !important; }
                .is-visually-center .label-ld { color: #93c5fd !important; }
                .is-visually-center { filter: grayscale(0) !important; }
                div:not(.is-visually-center) { filter: grayscale(0.3); }
            `}</style>
        </div>
    );
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { ScreenKey } from '../../types';
import { useUser } from '../../contexts/UserContext';
import { SlantedButton } from '../ui/SlantedButton';
import { GameText } from '../ui/GameText';
import { audio } from '../../services/audio';
import { Portal } from '../ui/Portal';

interface HomeCommandBarProps {
    onNavigate: (s: ScreenKey) => void;
}

const getRelativeTimeString = (isoString: string) => {
    const date = new Date(isoString);
    const now = new Date();
    const diffInMs = now.getTime() - date.getTime();
    const diffInDays = Math.floor(diffInMs / (1000 * 60 * 60 * 24));
    if (diffInDays <= 0) return 'today';
    if (diffInDays === 1) return 'yesterday';
    if (diffInDays < 7) return `${diffInDays} days ago`;
    const diffInWeeks = Math.floor(diffInDays / 7);
    if (diffInWeeks === 1) return 'a week ago';
    if (diffInWeeks < 4) return `${diffInWeeks} weeks ago`;
    const diffInMonths = Math.floor(diffInDays / 30);
    if (diffInMonths === 1) return 'a month ago';
    if (diffInMonths < 12) return `${diffInMonths} months ago`;
    return 'a long time ago';
};

export const HomeCommandBar: React.FC<HomeCommandBarProps> = ({ onNavigate }) => {
    const { user, activeDeck, setActiveDeck } = useUser();
    const [isRollerOpen, setIsRollerOpen] = useState(false);

    const activeDeckId = user.activeDeckId;
    const activeDeckName = user.deckNames[activeDeckId] || 'UNTITLED';
    const isIncomplete = activeDeck.length < 12;

    const deckIds = Object.keys(user.decks).map(Number).sort((a, b) => a - b);
    const count = deckIds.length;
    const angleStep = 360 / count;
    const radius = 130;

    // --- Performance Physics Refs ---
    const drumRef = useRef<HTMLDivElement>(null);
    const itemsRef = useRef<(HTMLDivElement | null)[]>([]);
    const rotationRef = useRef((activeDeckId - 1) * angleStep);
    const velocityRef = useRef(0);
    const isDraggingRef = useRef(false);
    const lastPointerY = useRef(0);
    const lastTime = useRef(0);
    const requestRef = useRef<number | null>(null);

    // Tracking for audio-visual sync
    const lastCenteredIndexRef = useRef<number>(activeDeckId - 1);
    const lastTickStepRef = useRef<number>(Math.round(rotationRef.current / angleStep));
    const lastAudioTimeRef = useRef<number>(0);

    /**
     * GPU-ACCELERATED DOM ENGINE with KINETIC TICKING
     */
    const updateDom = useCallback((rot: number) => {
        if (!drumRef.current) return;
        drumRef.current.style.transform = `translate3d(0, 0, -${radius}px) rotateX(${rot}deg)`;

        let currentCenterI = -1;

        for (let i = 0; i < itemsRef.current.length; i++) {
            const item = itemsRef.current[i];
            if (!item) continue;

            const angle = -i * angleStep;
            let normalizedAngle = (angle + rot) % 360;
            while (normalizedAngle > 180) normalizedAngle -= 360;
            while (normalizedAngle < -180) normalizedAngle += 360;

            const absAngle = Math.abs(normalizedAngle);

            if (absAngle < 110) {
                const distanceScale = 1 - (absAngle / 100) * 0.35;
                const opacity = 1 - (absAngle / 130);

                item.style.transform = `rotateX(${angle}deg) translate3d(0, 0, ${radius}px) scale(${distanceScale})`;
                item.style.opacity = Math.max(0.1, opacity).toString();
                item.style.visibility = 'visible';

                if (absAngle < (angleStep / 2)) currentCenterI = i;
            } else {
                item.style.visibility = 'hidden';
                item.style.opacity = '0';
            }
        }

        // 1. VISUAL SWAP
        if (currentCenterI !== -1 && currentCenterI !== lastCenteredIndexRef.current) {
            const prevItem = itemsRef.current[lastCenteredIndexRef.current];
            const nextItem = itemsRef.current[currentCenterI];
            if (prevItem) prevItem.classList.remove('is-visually-center');
            if (nextItem) nextItem.classList.add('is-visually-center');
            lastCenteredIndexRef.current = currentCenterI;
        }

        // 2. KINETIC TICK (Angular Step Tracking)
        const currentStep = Math.round(rot / angleStep);
        if (currentStep !== lastTickStepRef.current) {
            const now = performance.now();
            if (now - lastAudioTimeRef.current > 12) {
                audio.play('sfx_ui_click', 0.3); // Tactile mid-spin tick
                lastAudioTimeRef.current = now;
            }
            lastTickStepRef.current = currentStep;
        }
    }, [angleStep, radius]);

    const animate = useCallback(() => {
        if (isDraggingRef.current) return;

        velocityRef.current *= 0.972;
        rotationRef.current += velocityRef.current;

        // MAGNETIC SNAP PHASE
        if (Math.abs(velocityRef.current) < 0.22) {
            const targetIndex = Math.round(rotationRef.current / angleStep);
            const targetRotation = targetIndex * angleStep;
            const diff = targetRotation - rotationRef.current;

            rotationRef.current += diff * 0.45;

            if (Math.abs(diff) < 0.1) {
                rotationRef.current = targetRotation;
                velocityRef.current = 0;
                updateDom(rotationRef.current);

                // FINAL REST SOUND
                audio.play('sfx_ui_click', 0.9);

                const finalId = ((targetIndex % count + count) % count) + 1;
                if (finalId !== user.activeDeckId) setActiveDeck(finalId);
                return;
            }
        }
        updateDom(rotationRef.current);
        requestRef.current = requestAnimationFrame(animate);
    }, [angleStep, count, user.activeDeckId, setActiveDeck, updateDom]);

    const handlePointerDown = (e: React.PointerEvent) => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
        isDraggingRef.current = true;
        lastPointerY.current = e.clientY;
        lastTime.current = performance.now();
    };

    const handlePointerMove = (e: React.PointerEvent) => {
        if (!isDraggingRef.current) return;
        const now = performance.now();
        const deltaY = e.clientY - lastPointerY.current;
        const deltaTime = now - lastTime.current;

        const rotationDelta = -(deltaY / 100) * angleStep;

        rotationRef.current += rotationDelta;
        updateDom(rotationRef.current);

        if (deltaTime > 0) {
            const instantVelocity = rotationDelta / (deltaTime / 16.67);
            velocityRef.current = velocityRef.current * 0.3 + instantVelocity * 0.7;
        }
        lastPointerY.current = e.clientY;
        lastTime.current = now;
    };

    const handlePointerUp = () => {
        if (!isDraggingRef.current) return;
        isDraggingRef.current = false;
        requestRef.current = requestAnimationFrame(animate);
    };

    useEffect(() => {
        if (isRollerOpen) {
            const t = setTimeout(() => updateDom(rotationRef.current), 50);
            return () => clearTimeout(t);
        }
    }, [isRollerOpen, updateDom]);

    return (
        <div className="w-full flex items-end justify-between px-2 pb-3 gap-1 pointer-events-none relative h-16">
            {isRollerOpen && (
                <Portal>
                    <div 
                        className="fixed inset-0 z-[600] pointer-events-auto bg-black/40 backdrop-blur-md flex flex-col items-center justify-center" 
                        onClick={() => setIsRollerOpen(false)}
                        onPointerDown={handlePointerDown}
                        onPointerMove={handlePointerMove}
                        onPointerUp={handlePointerUp}
                        onPointerLeave={handlePointerUp}
                    >
                        <div className="w-full h-[32rem] perspective-[1500px] flex items-center justify-center select-none touch-none animate-pop overflow-visible">
                            <div 
                                ref={drumRef}
                                className="relative w-64 h-24 transform-style-3d pointer-events-none will-change-transform"
                                style={{ transform: `translate3d(0, 0, -${radius}px) rotateX(${rotationRef.current}deg)` }}
                            >
                                {deckIds.map((id, i) => {
                                    const stats = user.deckStats[id];
                                    const dateStr = stats ? getRelativeTimeString(stats.lastModified) : 'some time ago';
                                    const isInitialCenter = user.activeDeckId === id;
                                    return (
                                        <div 
                                            key={id}
                                            ref={el => itemsRef.current[i] = el}
                                            className={`absolute inset-0 backface-hidden transform-style-3d will-change-transform ${isInitialCenter ? 'is-visually-center' : ''}`}
                                            style={{ 
                                                transform: `rotateX(${-i * angleStep}deg) translate3d(0, 0, ${radius}px)`,
                                                opacity: isInitialCenter ? 1 : 0.4,
                                                zIndex: i === lastCenteredIndexRef.current ? 50 : 10
                                            }}
                                        >
                                            <SlantedButton
                                                variant="secondary"
                                                fullWidth
                                                size="lg"
                                                className="!h-full shadow-2xl drum-item-button"
                                            >
                                                <div className="flex flex-col items-center justify-center w-full h-full pointer-events-none px-4">
                                                    <div className="w-full h-8"><GameText text={user.deckNames[id] || 'UNTITLED'} baseFontSize={30} className="text-white" maxLines={1} /></div>
                                                    <div className="flex items-center gap-3 opacity-90 h-4">
                                                        <div className="flex items-center gap-1 h-full stats-cq">
                                                            <span className="text-[0.4rem] font-black text-indigo-300 uppercase label-cq">CQ</span>
                                                            <div className="w-10 h-full"><GameText text={`${stats?.conquestWinRate || 0}%`} baseFontSize={16} /></div>
                                                        </div>
                                                        <div className="flex items-center gap-1 h-full stats-ld">
                                                            <span className="text-[0.4rem] font-black text-blue-300 uppercase label-ld">LD</span>
                                                            <div className="w-10 h-full"><GameText text={`${stats?.ladderWinRate || 0}%`} baseFontSize={16} /></div>
                                                        </div>
                                                    </div>
                                                    <div className="w-full h-3 mt-1 opacity-50"><GameText text={`Changed ${dateStr}`} baseFontSize={14} className="lowercase italic" /></div>
                                                </div>
                                            </SlantedButton>
                                        </div>
                                    );
                                })}
                            </div>
                        </div>
                    </div>
                </Portal>
            )}

            <div className="w-[13.5%] pointer-events-auto">
                <SlantedButton variant="secondary" size="md" onClick={() => onNavigate('HISTORY')} className="w-full !h-10 shadow-slate-900/50" icon={
                    <div className="flex items-center justify-center w-full h-full scale-75">
                        <svg className="w-6 h-6 text-slate-200" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
                        </svg>
                    </div>
                } />
            </div>

            <div className="w-[23%] pointer-events-auto">
                <SlantedButton variant="warning" fullWidth size="lg" onClick={() => onNavigate('GAME')} className="!h-13 shadow-amber-900/50">
                    <div className="flex flex-col items-center justify-center w-full h-full text-center px-0.5">
                        <div className="w-full h-3.5 opacity-60"><GameText text="PLAY" baseFontSize={18} /></div>
                        <div className="w-full h-9 -mt-2.5"><GameText text="CONQUEST" baseFontSize={38} maxLines={1} className="italic tracking-tighter" /></div>
                    </div>
                </SlantedButton>
            </div>

            <div className="w-[23%] pointer-events-auto">
                <SlantedButton 
                    variant={isRollerOpen ? 'primary' : 'secondary'} 
                    fullWidth
                    size="lg"
                    onClick={() => { setIsRollerOpen(!isRollerOpen); audio.playUiClick(); }}
                    className={`!h-13 shadow-slate-900/40 relative z-[70] transition-transform ${isRollerOpen ? 'scale-105' : ''}`}
                >
                    <div className="flex flex-col items-center justify-center w-full h-full text-center px-0.5 py-1">
                        <div className="flex items-center justify-center gap-1 w-full h-3 opacity-60">
                            <div className="w-max h-full"><GameText text="DECK" baseFontSize={16} /></div>
                            {isIncomplete && <div className="w-1 h-1 rounded-full bg-amber-500 animate-pulse" />}
                        </div>
                        <div className="flex-1 w-full min-h-0"><GameText text={activeDeckName} baseFontSize={34} maxLines={2} className="italic tracking-tighter leading-none" /></div>
                    </div>
                </SlantedButton>
            </div>

            <div className="w-[23%] pointer-events-auto">
                <SlantedButton variant="blue" fullWidth size="lg" onClick={() => onNavigate('GAME')} className="!h-13 shadow-blue-900/50">
                    <div className="flex flex-col items-center justify-center w-full h-full text-center px-0.5">
                        <div className="w-full h-3.5 opacity-60"><GameText text="PLAY" baseFontSize={18} /></div>
                        <div className="w-full h-9 -mt-2.5"><GameText text="LADDER" baseFontSize={38} maxLines={1} className="italic tracking-tighter" /></div>
                    </div>
                </SlantedButton>
            </div>

            <div className="w-[13.5%] pointer-events-auto">
                <SlantedButton variant="blue" size="md" onClick={() => onNavigate('RANK')} className="w-full !h-10 shadow-blue-900/40 border-blue-400/40">
                    <div className="flex flex-col items-center justify-center w-full h-full text-center px-0.5">
                        <div className="w-full h-3 opacity-80 text-blue-100"><GameText text="RANK" baseFontSize={18} /></div>
                        <div className="w-full h-7 -mt-2"><GameText text={user.rank.toString()} baseFontSize={38} className="text-white drop-shadow-[0_1px_2px_rgba(0,0,0,0.6)]" /></div>
                    </div>
                </SlantedButton>
            </div>

            <style>{`
                .transform-style-3d { transform-style: preserve-3d; }
                .backface-hidden { backface-visibility: hidden; }
                .is-visually-center .drum-item-button > div:first-child {
                    background: linear-gradient(to bottom, #9333ea, #581c87) !important;
                    border-color: #c084fc !important;
                    box-shadow: 0 0.2rem 0 #581c87, 0 0 20px rgba(168, 85, 247, 0.3) !important;
                }
                .is-visually-center .label-cq { color: #a5b4fc !important; }
                .is-visually-center .label-ld { color: #93c5fd !important; }
                .is-visually-center { filter: grayscale(0) !important; }
            `}</style>
        </div>
    );
};

import React, { useEffect, useRef, useCallback } from 'react';
import { useUser } from '../../contexts/UserContext';
import { SlantedButton } from '../ui/SlantedButton';
import { GameText } from '../ui/GameText';
import { audio } from '../../services/audio';

interface DeckSelectorProps {
    activeDeckId: number;
    onSelectDeck: (id: number) => void;
}

const getRelativeTimeString = (isoString: string) => {
    const date = new Date(isoString);
    const now = new Date();
    const diffInMs = now.getTime() - date.getTime();
    const diffInDays = Math.floor(diffInMs / (1000 * 60 * 60 * 24));
    if (diffInDays <= 0) return 'today';
    if (diffInDays === 1) return 'yesterday';
    if (diffInDays < 7) return `${diffInDays} days ago`;
    const diffInWeeks = Math.floor(diffInDays / 7);
    if (diffInWeeks === 1) return 'a week ago';
    if (diffInWeeks < 4) return `${diffInWeeks} weeks ago`;
    const diffInMonths = Math.floor(diffInDays / 30);
    if (diffInMonths === 1) return 'a month ago';
    if (diffInMonths < 12) return `${diffInMonths} months ago`;
    return 'a long time ago';
};

export const DeckSelector3D: React.FC<DeckSelectorProps> = ({ activeDeckId, onSelectDeck }) => {
    const { user } = useUser();
    const deckIds = Object.keys(user.decks).map(Number).sort((a, b) => a - b);
    const count = deckIds.length;
    const angleStep = 360 / count;
    const radius = 110;

    // --- High Performance Physics Refs ---
    const drumRef = useRef<HTMLDivElement>(null);
    const itemsRef = useRef<(HTMLDivElement | null)[]>([]);
    const rotationRef = useRef((activeDeckId - 1) * angleStep);
    const velocityRef = useRef(0);
    const isDraggingRef = useRef(false);
    const lastPointerY = useRef(0);
    const lastTime = useRef(0);
    const requestRef = useRef<number | null>(null);

    // --- Kinetic Audio Engine Refs ---
    const lastCenteredIndexRef = useRef<number>(activeDeckId - 1);
    const lastTickStepRef = useRef<number>(Math.round(rotationRef.current / angleStep));
    const lastAudioTimeRef = useRef<number>(0);

    useEffect(() => {
        if (!isDraggingRef.current && velocityRef.current === 0) {
            rotationRef.current = (activeDeckId - 1) * angleStep;
            updateDom(rotationRef.current);
        }
    }, [activeDeckId, angleStep]);

    /**
     * GPU-ACCELERATED RENDERING & KINETIC AUDIO
     */
    const updateDom = useCallback((rot: number) => {
        if (!drumRef.current) return;

        drumRef.current.style.transform = `translate3d(0, 0, -${radius}px) rotateX(${rot}deg)`;

        let currentCenterI = -1;

        for (let i = 0; i < itemsRef.current.length; i++) {
            const item = itemsRef.current[i];
            if (!item) continue;

            const angle = -i * angleStep;
            let normalizedAngle = (angle + rot) % 360;
            while (normalizedAngle > 180) normalizedAngle -= 360;
            while (normalizedAngle < -180) normalizedAngle += 360;

            const absAngle = Math.abs(normalizedAngle);

            if (absAngle < 110) {
                const distanceScale = 1 - (absAngle / 100) * 0.35;
                const opacity = 1 - (absAngle / 130);

                item.style.transform = `rotateX(${angle}deg) translate3d(0, 0, ${radius}px) scale(${distanceScale})`;
                item.style.opacity = Math.max(0.05, opacity).toString();
                item.style.visibility = 'visible';

                if (absAngle < (angleStep / 2)) currentCenterI = i;
            } else {
                item.style.visibility = 'hidden';
                item.style.opacity = '0';
            }
        }

        // 1. VISUAL SWAP (Purple Highlight)
        if (currentCenterI !== -1 && currentCenterI !== lastCenteredIndexRef.current) {
            const prevItem = itemsRef.current[lastCenteredIndexRef.current];
            const nextItem = itemsRef.current[currentCenterI];
            if (prevItem) { prevItem.classList.remove('is-visually-center'); prevItem.style.zIndex = '10'; }
            if (nextItem) { nextItem.classList.add('is-visually-center'); nextItem.style.zIndex = '50'; }
            lastCenteredIndexRef.current = currentCenterI;
        }

        // 2. MATHEMATICAL TICK DETECTION (Swipe-Speed Resistant)
        const currentStep = Math.round(rot / angleStep);
        if (currentStep !== lastTickStepRef.current) {
            const now = performance.now();
            if (now - lastAudioTimeRef.current > 12) {
                audio.play('sfx_ui_click', 0.45); // Consistently weighted click
                lastAudioTimeRef.current = now;
            }
            lastTickStepRef.current = currentStep;
        }
    }, [angleStep, radius]);

    const animate = useCallback(() => {
        if (isDraggingRef.current) return;

        velocityRef.current *= 0.972; 
        rotationRef.current += velocityRef.current;

        // MAGNETIC SNAP PHASE
        if (Math.abs(velocityRef.current) < 0.22) {
            const targetIndex = Math.round(rotationRef.current / angleStep);
            const targetRotation = targetIndex * angleStep;
            const diff = targetRotation - rotationRef.current;

            rotationRef.current += diff * 0.42;

            // ABSOLUTE REST POINT
            if (Math.abs(diff) < 0.05) {
                rotationRef.current = targetRotation;
                velocityRef.current = 0;
                updateDom(rotationRef.current);

                // TRIGGER LOCK SOUND (Same volume as ticks for a natural feel)
                audio.play('sfx_ui_click', 0.45); 

                const finalId = ((targetIndex % count + count) % count) + 1;
                if (finalId !== activeDeckId) onSelectDeck(finalId);
                return;
            }
        }

        updateDom(rotationRef.current);
        requestRef.current = requestAnimationFrame(animate);
    }, [angleStep, count, activeDeckId, onSelectDeck, updateDom]);

    const handlePointerDown = (e: React.PointerEvent) => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
        isDraggingRef.current = true;
        lastPointerY.current = e.clientY;
        lastTime.current = performance.now();
    };

    const handlePointerMove = (e: React.PointerEvent) => {
        if (!isDraggingRef.current) return;
        const now = performance.now();
        const deltaY = e.clientY - lastPointerY.current;
        const deltaTime = now - lastTime.current;

        const rotationDelta = -(deltaY / 100) * angleStep;

        rotationRef.current += rotationDelta;
        updateDom(rotationRef.current);

        if (deltaTime > 0) {
            const instantVelocity = rotationDelta / (deltaTime / 16.67);
            velocityRef.current = velocityRef.current * 0.2 + instantVelocity * 0.8;
        }

        lastPointerY.current = e.clientY;
        lastTime.current = now;
    };

    const handlePointerUp = () => {
        if (!isDraggingRef.current) return;
        isDraggingRef.current = false;
        requestRef.current = requestAnimationFrame(animate);
    };

    return (
        <div 
            className="w-full h-64 flex items-center justify-center perspective-[1200px] overflow-hidden select-none touch-none bg-slate-950/40 border-y border-slate-800/50"
            onPointerDown={handlePointerDown}
            onPointerMove={handlePointerMove}
            onPointerUp={handlePointerUp}
            onPointerLeave={handlePointerUp}
        >
            <div 
                ref={drumRef}
                className="relative w-64 h-24 transform-style-3d pointer-events-none will-change-transform"
                style={{ transform: `translate3d(0, 0, -${radius}px) rotateX(${rotationRef.current}deg)` }}
            >
                {deckIds.map((id, i) => {
                    const deckName = user.deckNames[id] || 'UNTITLED';
                    const stats = user.deckStats[id];
                    const dateStr = stats ? getRelativeTimeString(stats.lastModified) : 'some time ago';
                    const isInitialCenter = activeDeckId === id;

                    return (
                        <div 
                            key={id}
                            ref={el => itemsRef.current[i] = el}
                            className={`absolute inset-0 backface-hidden transition-opacity duration-300 transform-style-3d will-change-transform ${isInitialCenter ? 'is-visually-center' : ''}`}
                            style={{ 
                                transform: `rotateX(${-i * angleStep}deg) translate3d(0, 0, ${radius}px)`,
                                opacity: isInitialCenter ? 1 : 0.5,
                                zIndex: isInitialCenter ? 50 : 10
                            }}
                        >
                            <SlantedButton 
                                variant="secondary" 
                                fullWidth
                                size="lg"
                                className="!h-full shadow-2xl drum-item-button"
                            >
                                <div className="flex flex-col items-center justify-center w-full h-full pointer-events-none px-4 py-2">
                                    <div className="w-full h-8 flex items-center justify-center">
                                        <GameText text={deckName} baseFontSize={30} maxLines={1} className="text-white" />
                                    </div>
                                    <div className="w-full h-4 flex items-center justify-center gap-4 opacity-80">
                                        <div className="flex items-center gap-1 h-full stats-cq">
                                            <span className="text-[0.4rem] font-black uppercase tracking-tighter label-cq">CQ</span>
                                            <div className="w-10 h-full"><GameText text={`${stats?.conquestWinRate || 0}%`} baseFontSize={16} className="text-white" /></div>
                                        </div>
                                        <div className="w-px h-2 bg-white/20" />
                                        <div className="flex items-center gap-1 h-full stats-ld">
                                            <span className="text-[0.4rem] font-black uppercase tracking-tighter label-ld">LD</span>
                                            <div className="w-10 h-full"><GameText text={`${stats?.ladderWinRate || 0}%`} baseFontSize={16} className="text-white" /></div>
                                        </div>
                                    </div>
                                    <div className="w-full h-3 mt-1 opacity-50">
                                        <GameText text={`Modified ${dateStr}`} baseFontSize={14} className="text-white lowercase italic" />
                                    </div>
                                </div>
                            </SlantedButton>
                        </div>
                    );
                })}
            </div>
            <div className="absolute left-0 right-0 h-24 border-y border-white/10 pointer-events-none z-0 bg-gradient-to-b from-transparent via-indigo-500/5 to-transparent" />
            <style>{`
                .transform-style-3d { transform-style: preserve-3d; }
                .backface-hidden { backface-visibility: hidden; }
                .is-visually-center .drum-item-button > div:first-child {
                    background: linear-gradient(to bottom, #9333ea, #581c87) !important;
                    border-color: #c084fc !important;
                    box-shadow: 0 0.2rem 0 #581c87, 0 0 20px rgba(168, 85, 247, 0.3) !important;
                }
                .is-visually-center .label-cq { color: #a5b4fc !important; }
                .is-visually-center .label-ld { color: #93c5fd !important; }
                .is-visually-center { filter: grayscale(0) !important; }
                div:not(.is-visually-center) { filter: grayscale(0.3); }
            `}</style>
        </div>
    );
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { ScreenKey } from '../../types';
import { useUser } from '../../contexts/UserContext';
import { SlantedButton } from '../ui/SlantedButton';
import { GameText } from '../ui/GameText';
import { audio } from '../../services/audio';
import { Portal } from '../ui/Portal';

interface HomeCommandBarProps {
    onNavigate: (s: ScreenKey) => void;
}

const getRelativeTimeString = (isoString: string) => {
    const date = new Date(isoString);
    const now = new Date();
    const diffInMs = now.getTime() - date.getTime();
    const diffInDays = Math.floor(diffInMs / (1000 * 60 * 60 * 24));
    if (diffInDays <= 0) return 'today';
    if (diffInDays === 1) return 'yesterday';
    if (diffInDays < 7) return `${diffInDays} days ago`;
    const diffInWeeks = Math.floor(diffInDays / 7);
    if (diffInWeeks === 1) return 'a week ago';
    if (diffInWeeks < 4) return `${diffInWeeks} weeks ago`;
    const diffInMonths = Math.floor(diffInDays / 30);
    if (diffInMonths === 1) return 'a month ago';
    if (diffInMonths < 12) return `${diffInMonths} months ago`;
    return 'a long time ago';
};

export const HomeCommandBar: React.FC<HomeCommandBarProps> = ({ onNavigate }) => {
    const { user, activeDeck, setActiveDeck } = useUser();
    const [isRollerOpen, setIsRollerOpen] = useState(false);

    const activeDeckId = user.activeDeckId;
    const activeDeckName = user.deckNames[activeDeckId] || 'UNTITLED';
    const isIncomplete = activeDeck.length < 12;

    const deckIds = Object.keys(user.decks).map(Number).sort((a, b) => a - b);
    const count = deckIds.length;
    const angleStep = 360 / count;
    const radius = 130;

    // --- Performance Physics Refs ---
    const drumRef = useRef<HTMLDivElement>(null);
    const itemsRef = useRef<(HTMLDivElement | null)[]>([]);
    const rotationRef = useRef((activeDeckId - 1) * angleStep);
    const velocityRef = useRef(0);
    const isDraggingRef = useRef(false);
    const lastPointerY = useRef(0);
    const lastTime = useRef(0);
    const requestRef = useRef<number | null>(null);

    // Tracking for audio-visual sync
    const lastCenteredIndexRef = useRef<number>(activeDeckId - 1);
    const lastTickStepRef = useRef<number>(Math.round(rotationRef.current / angleStep));
    const lastAudioTimeRef = useRef<number>(0);

    /**
     * GPU-ACCELERATED DOM ENGINE with KINETIC TICKING
     */
    const updateDom = useCallback((rot: number) => {
        if (!drumRef.current) return;
        drumRef.current.style.transform = `translate3d(0, 0, -${radius}px) rotateX(${rot}deg)`;

        let currentCenterI = -1;

        for (let i = 0; i < itemsRef.current.length; i++) {
            const item = itemsRef.current[i];
            if (!item) continue;

            const angle = -i * angleStep;
            let normalizedAngle = (angle + rot) % 360;
            while (normalizedAngle > 180) normalizedAngle -= 360;
            while (normalizedAngle < -180) normalizedAngle += 360;

            const absAngle = Math.abs(normalizedAngle);

            if (absAngle < 110) {
                const distanceScale = 1 - (absAngle / 100) * 0.35;
                const opacity = 1 - (absAngle / 130);

                item.style.transform = `rotateX(${angle}deg) translate3d(0, 0, ${radius}px) scale(${distanceScale})`;
                item.style.opacity = Math.max(0.1, opacity).toString();
                item.style.visibility = 'visible';

                if (absAngle < (angleStep / 2)) currentCenterI = i;
            } else {
                item.style.visibility = 'hidden';
                item.style.opacity = '0';
            }
        }

        // 1. VISUAL SWAP
        if (currentCenterI !== -1 && currentCenterI !== lastCenteredIndexRef.current) {
            const prevItem = itemsRef.current[lastCenteredIndexRef.current];
            const nextItem = itemsRef.current[currentCenterI];
            if (prevItem) prevItem.classList.remove('is-visually-center');
            if (nextItem) nextItem.classList.add('is-visually-center');
            lastCenteredIndexRef.current = currentCenterI;
        }

        // 2. KINETIC TICK (Angular Step Tracking)
        const currentStep = Math.round(rot / angleStep);
        if (currentStep !== lastTickStepRef.current) {
            const now = performance.now();
            if (now - lastAudioTimeRef.current > 12) {
                audio.play('sfx_ui_click', 0.4); // Normalized tick volume
                lastAudioTimeRef.current = now;
            }
            lastTickStepRef.current = currentStep;
        }
    }, [angleStep, radius]);

    const animate = useCallback(() => {
        if (isDraggingRef.current) return;

        velocityRef.current *= 0.972;
        rotationRef.current += velocityRef.current;

        // MAGNETIC SNAP PHASE
        if (Math.abs(velocityRef.current) < 0.22) {
            const targetIndex = Math.round(rotationRef.current / angleStep);
            const targetRotation = targetIndex * angleStep;
            const diff = targetRotation - rotationRef.current;

            rotationRef.current += diff * 0.45;

            if (Math.abs(diff) < 0.1) {
                rotationRef.current = targetRotation;
                velocityRef.current = 0;
                updateDom(rotationRef.current);

                // FINAL REST SOUND (Normalized to match transit sounds)
                audio.play('sfx_ui_click', 0.4);

                const finalId = ((targetIndex % count + count) % count) + 1;
                if (finalId !== user.activeDeckId) setActiveDeck(finalId);
                return;
            }
        }
        updateDom(rotationRef.current);
        requestRef.current = requestAnimationFrame(animate);
    }, [angleStep, count, user.activeDeckId, setActiveDeck, updateDom]);

    const handlePointerDown = (e: React.PointerEvent) => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
        isDraggingRef.current = true;
        lastPointerY.current = e.clientY;
        lastTime.current = performance.now();
    };

    const handlePointerMove = (e: React.PointerEvent) => {
        if (!isDraggingRef.current) return;
        const now = performance.now();
        const deltaY = e.clientY - lastPointerY.current;
        const deltaTime = now - lastTime.current;

        const rotationDelta = -(deltaY / 100) * angleStep;

        rotationRef.current += rotationDelta;
        updateDom(rotationRef.current);

        if (deltaTime > 0) {
            const instantVelocity = rotationDelta / (deltaTime / 16.67);
            velocityRef.current = velocityRef.current * 0.3 + instantVelocity * 0.7;
        }
        lastPointerY.current = e.clientY;
        lastTime.current = now;
    };

    const handlePointerUp = () => {
        if (!isDraggingRef.current) return;
        isDraggingRef.current = false;
        requestRef.current = requestAnimationFrame(animate);
    };

    useEffect(() => {
        if (isRollerOpen) {
            const t = setTimeout(() => updateDom(rotationRef.current), 50);
            return () => clearTimeout(t);
        }
    }, [isRollerOpen, updateDom]);

    return (
        <div className="w-full flex items-end justify-between px-2 pb-3 gap-1 pointer-events-none relative h-16">
            {isRollerOpen && (
                <Portal>
                    <div 
                        className="fixed inset-0 z-[600] pointer-events-auto bg-black/40 backdrop-blur-md flex flex-col items-center justify-center" 
                        onClick={() => setIsRollerOpen(false)}
                        onPointerDown={handlePointerDown}
                        onPointerMove={handlePointerMove}
                        onPointerUp={handlePointerUp}
                        onPointerLeave={handlePointerUp}
                    >
                        <div className="w-full h-[32rem] perspective-[1500px] flex items-center justify-center select-none touch-none animate-pop overflow-visible">
                            <div 
                                ref={drumRef}
                                className="relative w-64 h-24 transform-style-3d pointer-events-none will-change-transform"
                                style={{ transform: `translate3d(0, 0, -${radius}px) rotateX(${rotationRef.current}deg)` }}
                            >
                                {deckIds.map((id, i) => {
                                    const stats = user.deckStats[id];
                                    const dateStr = stats ? getRelativeTimeString(stats.lastModified) : 'some time ago';
                                    const isInitialCenter = user.activeDeckId === id;
                                    return (
                                        <div 
                                            key={id}
                                            ref={el => itemsRef.current[i] = el}
                                            className={`absolute inset-0 backface-hidden transform-style-3d will-change-transform ${isInitialCenter ? 'is-visually-center' : ''}`}
                                            style={{ 
                                                transform: `rotateX(${-i * angleStep}deg) translate3d(0, 0, ${radius}px)`,
                                                opacity: isInitialCenter ? 1 : 0.4,
                                                zIndex: i === lastCenteredIndexRef.current ? 50 : 10
                                            }}
                                        >
                                            <SlantedButton
                                                variant="secondary"
                                                fullWidth
                                                size="lg"
                                                className="!h-full shadow-2xl drum-item-button"
                                            >
                                                <div className="flex flex-col items-center justify-center w-full h-full pointer-events-none px-4">
                                                    <div className="w-full h-8"><GameText text={user.deckNames[id] || 'UNTITLED'} baseFontSize={30} className="text-white" maxLines={1} /></div>
                                                    <div className="flex items-center gap-3 opacity-90 h-4">
                                                        <div className="flex items-center gap-1 h-full stats-cq">
                                                            <span className="text-[0.4rem] font-black text-indigo-300 uppercase label-cq">CQ</span>
                                                            <div className="w-10 h-full"><GameText text={`${stats?.conquestWinRate || 0}%`} baseFontSize={16} /></div>
                                                        </div>
                                                        <div className="flex items-center gap-1 h-full stats-ld">
                                                            <span className="text-[0.4rem] font-black text-blue-300 uppercase label-ld">LD</span>
                                                            <div className="w-10 h-full"><GameText text={`${stats?.ladderWinRate || 0}%`} baseFontSize={16} /></div>
                                                        </div>
                                                    </div>
                                                    <div className="w-full h-3 mt-1 opacity-50"><GameText text={`Changed ${dateStr}`} baseFontSize={14} className="lowercase italic" /></div>
                                                </div>
                                            </SlantedButton>
                                        </div>
                                    );
                                })}
                            </div>
                        </div>
                    </div>
                </Portal>
            )}

            <div className="w-[13.5%] pointer-events-auto">
                <SlantedButton variant="secondary" size="md" onClick={() => onNavigate('HISTORY')} className="w-full !h-10 shadow-slate-900/50" icon={
                    <div className="flex items-center justify-center w-full h-full scale-75">
                        <svg className="w-6 h-6 text-slate-200" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
                        </svg>
                    </div>
                } />
            </div>

            <div className="w-[23%] pointer-events-auto">
                <SlantedButton variant="warning" fullWidth size="lg" onClick={() => onNavigate('GAME')} className="!h-13 shadow-amber-900/50">
                    <div className="flex flex-col items-center justify-center w-full h-full text-center px-0.5">
                        <div className="w-full h-3.5 opacity-60"><GameText text="PLAY" baseFontSize={18} /></div>
                        <div className="w-full h-9 -mt-2.5"><GameText text="CONQUEST" baseFontSize={38} maxLines={1} className="italic tracking-tighter" /></div>
                    </div>
                </SlantedButton>
            </div>

            <div className="w-[23%] pointer-events-auto">
                <SlantedButton 
                    variant={isRollerOpen ? 'primary' : 'secondary'} 
                    fullWidth
                    size="lg"
                    onClick={() => { setIsRollerOpen(!isRollerOpen); audio.playUiClick(); }}
                    className={`!h-13 shadow-slate-900/40 relative z-[70] transition-transform ${isRollerOpen ? 'scale-105' : ''}`}
                >
                    <div className="flex flex-col items-center justify-center w-full h-full text-center px-0.5 py-1">
                        <div className="flex items-center justify-center gap-1 w-full h-3 opacity-60">
                            <div className="w-max h-full"><GameText text="DECK" baseFontSize={16} /></div>
                            {isIncomplete && <div className="w-1 h-1 rounded-full bg-amber-500 animate-pulse" />}
                        </div>
                        <div className="flex-1 w-full min-h-0"><GameText text={activeDeckName} baseFontSize={34} maxLines={2} className="italic tracking-tighter leading-none" /></div>
                    </div>
                </SlantedButton>
            </div>

            <div className="w-[23%] pointer-events-auto">
                <SlantedButton variant="blue" fullWidth size="lg" onClick={() => onNavigate('GAME')} className="!h-13 shadow-blue-900/50">
                    <div className="flex flex-col items-center justify-center w-full h-full text-center px-0.5">
                        <div className="w-full h-3.5 opacity-60"><GameText text="PLAY" baseFontSize={18} /></div>
                        <div className="w-full h-9 -mt-2.5"><GameText text="LADDER" baseFontSize={38} maxLines={1} className="italic tracking-tighter" /></div>
                    </div>
                </SlantedButton>
            </div>

            <div className="w-[13.5%] pointer-events-auto">
                <SlantedButton variant="blue" size="md" onClick={() => onNavigate('RANK')} className="w-full !h-10 shadow-blue-900/40 border-blue-400/40">
                    <div className="flex flex-col items-center justify-center w-full h-full text-center px-0.5">
                        <div className="w-full h-3 opacity-80 text-blue-100"><GameText text="RANK" baseFontSize={18} /></div>
                        <div className="w-full h-7 -mt-2"><GameText text={user.rank.toString()} baseFontSize={38} className="text-white drop-shadow-[0_1px_2px_rgba(0,0,0,0.6)]" /></div>
                    </div>
                </SlantedButton>
            </div>

            <style>{`
                .transform-style-3d { transform-style: preserve-3d; }
                .backface-hidden { backface-visibility: hidden; }
                .is-visually-center .drum-item-button > div:first-child {
                    background: linear-gradient(to bottom, #9333ea, #581c87) !important;
                    border-color: #c084fc !important;
                    box-shadow: 0 0.2rem 0 #581c87, 0 0 20px rgba(168, 85, 247, 0.3) !important;
                }
                .is-visually-center .label-cq { color: #a5b4fc !important; }
                .is-visually-center .label-ld { color: #93c5fd !important; }
                .is-visually-center { filter: grayscale(0) !important; }
            `}</style>
        </div>
    );
};

import React, { useEffect, useRef, useCallback } from 'react';
import { useUser } from '../../contexts/UserContext';
import { SlantedButton } from '../ui/SlantedButton';
import { GameText } from '../ui/GameText';
import { audio } from '../../services/audio';

interface DeckSelectorProps {
    activeDeckId: number;
    onSelectDeck: (id: number) => void;
}

const getRelativeTimeString = (isoString: string) => {
    const date = new Date(isoString);
    const now = new Date();
    const diffInMs = now.getTime() - date.getTime();
    const diffInDays = Math.floor(diffInMs / (1000 * 60 * 60 * 24));
    if (diffInDays <= 0) return 'today';
    if (diffInDays === 1) return 'yesterday';
    if (diffInDays < 7) return `${diffInDays} days ago`;
    const diffInWeeks = Math.floor(diffInDays / 7);
    if (diffInWeeks === 1) return 'a week ago';
    if (diffInWeeks < 4) return `${diffInWeeks} weeks ago`;
    const diffInMonths = Math.floor(diffInDays / 30);
    if (diffInMonths === 1) return 'a month ago';
    if (diffInMonths < 12) return `${diffInMonths} months ago`;
    return 'a long time ago';
};

export const DeckSelector3D: React.FC<DeckSelectorProps> = ({ activeDeckId, onSelectDeck }) => {
    const { user } = useUser();
    const deckIds = Object.keys(user.decks).map(Number).sort((a, b) => a - b);
    const count = deckIds.length;
    const angleStep = 360 / count;
    const radius = 110;

    // --- High Performance Physics Refs ---
    const drumRef = useRef<HTMLDivElement>(null);
    const itemsRef = useRef<(HTMLDivElement | null)[]>([]);
    const rotationRef = useRef((activeDeckId - 1) * angleStep);
    const velocityRef = useRef(0);
    const isDraggingRef = useRef(false);
    const lastPointerY = useRef(0);
    const lastTime = useRef(0);
    const requestRef = useRef<number | null>(null);

    // --- Kinetic Audio Engine Refs ---
    const lastCenteredIndexRef = useRef<number>(activeDeckId - 1);
    const lastTickStepRef = useRef<number>(Math.round(rotationRef.current / angleStep));
    const lastAudioTimeRef = useRef<number>(0);
    const canPlayAudioRef = useRef<boolean>(true);

    useEffect(() => {
        if (!isDraggingRef.current && velocityRef.current === 0) {
            rotationRef.current = (activeDeckId - 1) * angleStep;
            updateDom(rotationRef.current);
        }
    }, [activeDeckId, angleStep]);

    /**
     * GPU-ACCELERATED RENDERING & KINETIC AUDIO
     */
    const updateDom = useCallback((rot: number) => {
        if (!drumRef.current) return;

        drumRef.current.style.transform = `translate3d(0, 0, -${radius}px) rotateX(${rot}deg)`;

        let currentCenterI = -1;

        for (let i = 0; i < itemsRef.current.length; i++) {
            const item = itemsRef.current[i];
            if (!item) continue;

            const angle = -i * angleStep;
            let normalizedAngle = (angle + rot) % 360;
            while (normalizedAngle > 180) normalizedAngle -= 360;
            while (normalizedAngle < -180) normalizedAngle += 360;

            const absAngle = Math.abs(normalizedAngle);

            if (absAngle < 110) {
                const distanceScale = 1 - (absAngle / 100) * 0.35;
                const opacity = 1 - (absAngle / 130);

                item.style.transform = `rotateX(${angle}deg) translate3d(0, 0, ${radius}px) scale(${distanceScale})`;
                item.style.opacity = Math.max(0.05, opacity).toString();
                item.style.visibility = 'visible';

                if (absAngle < (angleStep / 2)) currentCenterI = i;
            } else {
                item.style.visibility = 'hidden';
                item.style.opacity = '0';
            }
        }

        // 1. VISUAL SWAP (Purple Highlight)
        if (currentCenterI !== -1 && currentCenterI !== lastCenteredIndexRef.current) {
            const prevItem = itemsRef.current[lastCenteredIndexRef.current];
            const nextItem = itemsRef.current[currentCenterI];
            if (prevItem) { prevItem.classList.remove('is-visually-center'); prevItem.style.zIndex = '10'; }
            if (nextItem) { nextItem.classList.add('is-visually-center'); nextItem.style.zIndex = '50'; }
            lastCenteredIndexRef.current = currentCenterI;
        }

        // 2. MATHEMATICAL TICK DETECTION (Swipe-Speed Resistant)
        const currentStep = Math.round(rot / angleStep);
        if (currentStep !== lastTickStepRef.current) {
            const now = performance.now();
            const elapsedSinceLastClick = now - lastAudioTimeRef.current;

            // Timeout Check: If we are not dragging and it's been 250ms+, silence the session
            if (!isDraggingRef.current && elapsedSinceLastClick > 250) {
                canPlayAudioRef.current = false;
            }

            if (canPlayAudioRef.current && elapsedSinceLastClick > 12) {
                audio.play('sfx_ui_click', 0.45);
                lastAudioTimeRef.current = now;
            }
            lastTickStepRef.current = currentStep;
        }
    }, [angleStep, radius]);

    const animate = useCallback(() => {
        if (isDraggingRef.current) return;

        velocityRef.current *= 0.972; 
        rotationRef.current += velocityRef.current;

        // MAGNETIC SNAP PHASE
        if (Math.abs(velocityRef.current) < 0.22) {
            const targetIndex = Math.round(rotationRef.current / angleStep);
            const targetRotation = targetIndex * angleStep;
            const diff = targetRotation - rotationRef.current;

            rotationRef.current += diff * 0.42;

            // ABSOLUTE REST POINT
            if (Math.abs(diff) < 0.05) {
                rotationRef.current = targetRotation;
                velocityRef.current = 0;
                updateDom(rotationRef.current);

                // Final snap sound respects the timeout logic
                const now = performance.now();
                if (canPlayAudioRef.current && (now - lastAudioTimeRef.current < 250)) {
                    audio.play('sfx_ui_click', 0.45);
                }

                const finalId = ((targetIndex % count + count) % count) + 1;
                if (finalId !== activeDeckId) onSelectDeck(finalId);
                return;
            }
        }

        updateDom(rotationRef.current);
        requestRef.current = requestAnimationFrame(animate);
    }, [angleStep, count, activeDeckId, onSelectDeck, updateDom]);

    const handlePointerDown = (e: React.PointerEvent) => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
        isDraggingRef.current = true;
        // Reset audio session state on interaction
        canPlayAudioRef.current = true;
        lastAudioTimeRef.current = performance.now();
        lastPointerY.current = e.clientY;
        lastTime.current = performance.now();
    };

    const handlePointerMove = (e: React.PointerEvent) => {
        if (!isDraggingRef.current) return;
        const now = performance.now();
        const deltaY = e.clientY - lastPointerY.current;
        const deltaTime = now - lastTime.current;

        const rotationDelta = -(deltaY / 100) * angleStep;

        rotationRef.current += rotationDelta;
        updateDom(rotationRef.current);

        if (deltaTime > 0) {
            const instantVelocity = rotationDelta / (deltaTime / 16.67);
            velocityRef.current = velocityRef.current * 0.2 + instantVelocity * 0.8;
        }

        lastPointerY.current = e.clientY;
        lastTime.current = now;
    };

    const handlePointerUp = () => {
        if (!isDraggingRef.current) return;
        isDraggingRef.current = false;
        requestRef.current = requestAnimationFrame(animate);
    };

    return (
        <div 
            className="w-full h-64 flex items-center justify-center perspective-[1200px] overflow-hidden select-none touch-none bg-slate-950/40 border-y border-slate-800/50"
            onPointerDown={handlePointerDown}
            onPointerMove={handlePointerMove}
            onPointerUp={handlePointerUp}
            onPointerLeave={handlePointerUp}
        >
            <div 
                ref={drumRef}
                className="relative w-64 h-24 transform-style-3d pointer-events-none will-change-transform"
                style={{ transform: `translate3d(0, 0, -${radius}px) rotateX(${rotationRef.current}deg)` }}
            >
                {deckIds.map((id, i) => {
                    const deckName = user.deckNames[id] || 'UNTITLED';
                    const stats = user.deckStats[id];
                    const dateStr = stats ? getRelativeTimeString(stats.lastModified) : 'some time ago';
                    const isInitialCenter = activeDeckId === id;

                    return (
                        <div 
                            key={id}
                            ref={el => itemsRef.current[i] = el}
                            className={`absolute inset-0 backface-hidden transition-opacity duration-300 transform-style-3d will-change-transform ${isInitialCenter ? 'is-visually-center' : ''}`}
                            style={{ 
                                transform: `rotateX(${-i * angleStep}deg) translate3d(0, 0, ${radius}px)`,
                                opacity: isInitialCenter ? 1 : 0.5,
                                zIndex: isInitialCenter ? 50 : 10
                            }}
                        >
                            <SlantedButton 
                                variant="secondary" 
                                fullWidth
                                size="lg"
                                className="!h-full shadow-2xl drum-item-button"
                            >
                                <div className="flex flex-col items-center justify-center w-full h-full pointer-events-none px-4 py-2">
                                    <div className="w-full h-8 flex items-center justify-center">
                                        <GameText text={deckName} baseFontSize={30} maxLines={1} className="text-white" />
                                    </div>
                                    <div className="w-full h-4 flex items-center justify-center gap-4 opacity-80">
                                        <div className="flex items-center gap-1 h-full stats-cq">
                                            <span className="text-[0.4rem] font-black uppercase tracking-tighter label-cq">CQ</span>
                                            <div className="w-10 h-full"><GameText text={`${stats?.conquestWinRate || 0}%`} baseFontSize={16} className="text-white" /></div>
                                        </div>
                                        <div className="w-px h-2 bg-white/20" />
                                        <div className="flex items-center gap-1 h-full stats-ld">
                                            <span className="text-[0.4rem] font-black uppercase tracking-tighter label-ld">LD</span>
                                            <div className="w-10 h-full"><GameText text={`${stats?.ladderWinRate || 0}%`} baseFontSize={16} className="text-white" /></div>
                                        </div>
                                    </div>
                                    <div className="w-full h-3 mt-1 opacity-50">
                                        <GameText text={`Modified ${dateStr}`} baseFontSize={14} className="text-white lowercase italic" />
                                    </div>
                                </div>
                            </SlantedButton>
                        </div>
                    );
                })}
            </div>
            <div className="absolute left-0 right-0 h-24 border-y border-white/10 pointer-events-none z-0 bg-gradient-to-b from-transparent via-indigo-500/5 to-transparent" />
            <style>{`
                .transform-style-3d { transform-style: preserve-3d; }
                .backface-hidden { backface-visibility: hidden; }
                .is-visually-center .drum-item-button > div:first-child {
                    background: linear-gradient(to bottom, #9333ea, #581c87) !important;
                    border-color: #c084fc !important;
                    box-shadow: 0 0.2rem 0 #581c87, 0 0 20px rgba(168, 85, 247, 0.3) !important;
                }
                .is-visually-center .label-cq { color: #a5b4fc !important; }
