            <div className="w-[13.5%] pointer-events-auto">
                <SlantedButton variant="blue" size="md" onClick={() => onNavigate('RANK')} className="w-full !h-10 shadow-blue-900/40 border-blue-400/40">
                    <div className="flex flex-col items-center justify-center w-full h-full text-center px-0.5">
                        <div className="w-full h-3 opacity-80 text-blue-100"><GameText text="RANK" baseFontSize={18} /></div>
                        <div className="w-full h-7 -mt-2"><GameText text={user.rank.toString()} baseFontSize={38} className="text-white drop-shadow-[0_1px_2px_rgba(0,0,0,0.6)]" /></div>
