/**
 * Precision Icon Size Map
 * Uses fixed [px] or [rem] values for consistency across devices.
 * Note: Credit icons are rotated 45deg, so their bounding box is side * sqrt(2).
 */
const sizes = {
  // Navigation / Tiny UI
  xs: { box: 'w-2.5 h-2.5', gold: 'w-2.5 h-1.5', credit: 'w-2 h-2' },

  // Header Buttons (sm)
  // Adjusted credit from w-4 h-4 (1rem) to 0.8rem (~w-3.2) to fit 20px box when rotated
  sm: { box: 'w-5 h-5', gold: 'w-[1.1rem] h-[0.6rem]', credit: 'w-[0.8rem] h-[0.8rem]' },

  // Store Items (md) - Upgraded to fixed PX for stability and 15% better visual weight
  md: { box: 'w-9 h-9', gold: 'w-[36px] h-[22px]', credit: 'w-[30px] h-[30px]' },

  // Inspect / Hero UI (lg)
  lg: { box: 'w-16 h-16', gold: 'w-[3.5rem] h-[2.5rem]', credit: 'w-12 h-12' }
};

export const CreditIcon: React.FC<CurrencyIconProps> = ({ size = 'md', className = '' }) => {
  const s = sizes[size];
  return (
    <div className={`relative flex items-center justify-center ${s.box} ${className}`}>
      <div 
        className={`
          ${s.credit} bg-gradient-to-tr from-blue-400 to-blue-600 rounded-sm 
          shadow-[0_0_8px_rgba(37,99,235,0.4)] border border-white/30 rotate-45
        `}
      />
    </div>
  );
};

export const GoldIcon: React.FC<CurrencyIconProps> = ({ size = 'md', className = '', animate = false }) => {
  const s = sizes[size];
  return (
    <div className={`relative flex items-center justify-center ${s.box} ${className}`}>
      <div 
        className={`
          ${s.gold} bg-gradient-to-br from-amber-300 via-yellow-400 to-amber-600 rounded-[1px]
          shadow-[0_0_8px_rgba(217,119,6,0.4)] border border-white/30 -rotate-12
          ${animate ? 'animate-bounce-subtle' : ''}
