      />
      <style>{`
        @keyframes bounce-subtle {
          0%, 100% { transform: translateY(0) rotate(-12deg); }
          50% { transform: translateY(-0.8px) rotate(-12deg); }
        }
        .animate-bounce-subtle {
          animation: bounce-subtle 2s infinite ease-in-out;
        }
      `}</style>
    </div>
  );
};

