import React, { useState, useLayoutEffect, useRef } from 'react';

interface GameTextProps {
  text: string;
  className?: string;
  /** The "Aspirational" font size. */
  baseFontSize: number;
  /** How much we allow the text to shrink. 0.3 is usually the limit for legibility. */
  minScale?: number;
  /** If > 1, allows the text to wrap and scales based on both width and height. */
  maxLines?: number;
}

/**
 * GameText: Iterative Balanced-Wrap Typography.
 * Now styling-agnostic to support both All-Caps and Mixed-Case HUD elements.
 */
export const GameText: React.FC<GameTextProps> = ({ 
  text, 
  className = '', 
  baseFontSize, 
  minScale = 0.3,
  maxLines = 1
}) => {
  const [layout, setLayout] = useState<{ lines: string[], scale: number }>({ lines: [text], scale: 1 });
  const containerRef = useRef<HTMLDivElement>(null);
  const ghostRef = useRef<HTMLDivElement>(null);

  useLayoutEffect(() => {
    const container = containerRef.current;
    const ghost = ghostRef.current;
    if (!container || !ghost) return;

    const words = text.split(/\s+/);

    const splitIntoLines = (numLines: number): string[] => {
      if (numLines <= 1 || words.length <= 1) return [text];
      const targetCharsPerLine = text.length / numLines;
      const result: string[][] = Array.from({ length: numLines }, () => []);
      let currentLine = 0;
      let currentChars = 0;

      words.forEach((word) => {
        if (currentLine < numLines - 1) {
            const distIfStay = Math.abs((currentChars + word.length) - targetCharsPerLine);
            const distIfMove = Math.abs(currentChars - targetCharsPerLine);
            if (currentChars > 0 && distIfMove < distIfStay) {
                currentLine++;
                currentChars = 0;
            }
        }
        result[currentLine].push(word);
        currentChars += word.length + 1;
      });

      return result.map(l => l.join(' ')).filter(s => s.length > 0);
    };

    const measureLayout = (lines: string[]) => {
      ghost.innerHTML = lines.map(l => `<div>${l}</div>`).join('');
      ghost.style.fontSize = `${baseFontSize}px`;

      const containerWidth = container.offsetWidth;
      const containerHeight = container.offsetHeight;

      if (containerWidth <= 0 || containerHeight <= 0) return 0;

      const ghostWidth = ghost.offsetWidth;
      const ghostHeight = ghost.offsetHeight;

      if (ghostWidth <= 0 || ghostHeight <= 0) return 0;

      const widthRatio = (containerWidth / ghostWidth) * 0.98;
      const heightRatio = (containerHeight / ghostHeight) * 0.98;

      if (lines.length === 1 && ghostHeight <= containerHeight) {
          return Math.min(1, widthRatio);
      }

      return Math.min(1, widthRatio, heightRatio);
    };

    const findBestLayout = () => {
      let bestScale = 0;
      let bestLines: string[] = [text];
      const limit = Math.min(maxLines, 4); 

      for (let i = 1; i <= limit; i++) {
        if (i > words.length) break;
        const candidateLines = splitIntoLines(i);
        const scale = measureLayout(candidateLines);
        const bias = (limit - i) * 0.02; 
        if (scale + bias > bestScale) {
          bestScale = scale;
          bestLines = candidateLines;
        }
        if (i === 1 && scale > 0.95) break;
      }

      setLayout({ 
          lines: bestLines, 
          scale: Math.max(minScale, bestScale) 
      });
    };

    findBestLayout();
    const observer = new ResizeObserver(() => requestAnimationFrame(findBestLayout));
    observer.observe(container);
    return () => observer.disconnect();
  }, [text, baseFontSize, minScale, maxLines]);

  return (
    <div 
      ref={containerRef} 
      className={`w-full h-full flex justify-center items-center relative leading-none overflow-hidden font-sans ${className}`}
    >
      <div
        ref={ghostRef}
        className={`absolute opacity-0 pointer-events-none flex flex-col items-center ${className}`}
        style={{ fontSize: `${baseFontSize}px`, left: -9999, whiteSpace: 'nowrap' }}
      />
      <div
        style={{ 
          transformOrigin: 'center center',
          transform: `scale(${layout.scale})`,
          fontSize: `${baseFontSize}px`,
          width: 'max-content',
          minWidth: '100%'
        }}
        className="flex flex-col items-center justify-center leading-none"
      >
        {layout.lines.map((line, idx) => (
            <div key={idx} className="whitespace-nowrap">
                {line}
            </div>
        ))}
      </div>
    </div>
  );
};

