                    </div>
                </SlantedButton>
            </div>

            <style>{`
                .transform-style-3d { transform-style: preserve-3d; }
                .backface-hidden { backface-visibility: hidden; }

                /* VALID DECK HIGHLIGHT (GREEN) */
                .is-visually-center.deck-valid .drum-item-button > div:first-child {
                    background: linear-gradient(to bottom, #059669, #064e3b) !important;
                    border-color: #34d399 !important;
                    box-shadow: 0 0.2rem 0 #064e3b, 0 0 20px rgba(16, 185, 129, 0.3) !important;
                }

                /* INVALID DECK HIGHLIGHT (RED) */
                .is-visually-center.deck-invalid .drum-item-button > div:first-child {
                    background: linear-gradient(to bottom, #dc2626, #7f1d1d) !important;
                    border-color: #f87171 !important;
                    box-shadow: 0 0.2rem 0 #7f1d1d, 0 0 20px rgba(239, 68, 68, 0.3) !important;
                }

                .is-visually-center .label-cq { color: #ffffffaa !important; }
                .is-visually-center .label-ld { color: #ffffffaa !important; }
                .is-visually-center { filter: grayscale(0) !important; }
            `}</style>
        </div>
    );
};

