                                    const stats = user.deckStats[id];
                                    const dateStr = stats ? getRelativeTimeString(stats.lastModified) : 'some time ago';
                                    const isInitialCenter = user.activeDeckId === id;
                                    const isValid = (user.decks[id]?.length || 0) === 12;

                                    const statsText = `conquest: ${stats?.conquestWins || 0}/${stats?.conquestTotal || 0} (${stats?.conquestWinRate || 0}%) - ladder ${stats?.ladderWins || 0}/${stats?.ladderLosses || 0} (${stats?.ladderWinRate || 0}%)`;

                                    return (
                                        <div 
                                            key={id}
                                            ref={el => itemsRef.current[i] = el}
                                            className={`absolute inset-0 backface-hidden transform-style-3d will-change-transform ${isInitialCenter ? 'is-visually-center' : ''} ${isValid ? 'deck-valid' : 'deck-invalid'}`}
                                            style={{ 
                                                transform: `rotateX(${-i * angleStep}deg) translate3d(0, 0, ${radius}px)`,
                                                opacity: isInitialCenter ? 1 : 0.4,
                                                zIndex: i === lastCenteredIndexRef.current ? 50 : 10
                                            }}
                                        >
                                            <SlantedButton
                                                variant="secondary"
                                                fullWidth
                                                size="lg"
                                                className="!h-full shadow-2xl drum-item-button"
                                            >
                                                <div className="flex flex-col items-center justify-center w-full h-full pointer-events-none px-4">
                                                    <div className="w-full h-8"><GameText text={user.deckNames[id] || 'UNTITLED'} baseFontSize={30} className="text-white font-black italic tracking-tighter uppercase" maxLines={1} /></div>
                                                    <div className="w-full h-4 flex items-center justify-center opacity-90">
                                                        <GameText text={statsText} baseFontSize={16} maxLines={1} className="text-white font-bold font-black italic tracking-tighter uppercase" />
                                                    </div>
                                                    <div className="w-full h-3 mt-1 opacity-50"><GameText text={`Changed ${dateStr}`} baseFontSize={14} className="lowercase italic font-black tracking-tighter" /></div>
                                                </div>
                                            </SlantedButton>
                                        </div>
                                    );
                                })}
                            </div>
                        </div>
                    </div>
                </Portal>
            )}

            <div className="w-[11.5%] pointer-events-auto">
                <SlantedButton variant="blue" size="md" onClick={() => onNavigate('HISTORY')} className="w-full !h-10 shadow-blue-900/40" icon={
                    <div className="flex items-center justify-center w-full h-full scale-75 drop-shadow-[0_2px_3px_rgba(0,0,0,0.8)]">
                        <svg className="w-6 h-6 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
                        </svg>
                    </div>
