import { AUDIO_MANIFEST, getCardImg, getLocationImg } from '../utils/assets';
import { CARDS, LOCATION_DEFS } from '../constants';
import { audio } from './audio';

export const preloadAssets = async (onProgress: (progress: number) => void) => {
  let loaded = 0;

  // 1. Gather all URLs
  const imagesToLoad = [
    ...CARDS.map(c => c.imageUrl),
    ...LOCATION_DEFS.map(l => l.imageUrl),
    // Add any UI assets here
  ];

  // Audio is handled by Howler's internal preloader, but we should init the service
  const audioKeys = Object.keys(AUDIO_MANIFEST);

  // We treat font loading as a critical asset step (Weight of 5 units)
  const totalAssets = imagesToLoad.length + audioKeys.length + 5;

  const updateProgress = () => {
    loaded++;
    const percentage = Math.min(100, Math.floor((loaded / totalAssets) * 100));
    onProgress(percentage);
  };

  // 2. Preload Images
  const imagePromises = imagesToLoad.map(src => {
    return new Promise<void>((resolve) => {
      const img = new Image();
      img.src = src;
      img.onload = () => {
        updateProgress();
        resolve();
      };
      img.onerror = () => {
        console.warn(`Failed to load image: ${src}`);
        updateProgress(); // Resolve anyway to not block game
        resolve();
      };
    });
  });

  // 3. Initialize Audio
  audio.init();
  audioKeys.forEach(() => updateProgress());

  // 4. Critical Font Synchronization
  // This prevents GameText from measuring system fonts before custom fonts arrive
  if ('fonts' in document) {
    try {
        await (document as any).fonts.ready;
        for(let i=0; i<5; i++) updateProgress();
    } catch (e) {
        console.warn("Font loading wait failed, proceeding with system fonts.");
    }
  }

  await Promise.all([...imagePromises]);
};

