import { LoginScreen } from './components/screens/LoginScreen';
import { NavigationBar } from './components/ui/NavigationBar';
import { InspectorOverlay } from './components/InspectorOverlay';
import { preloadAssets } from './services/assetLoader';
import { audio } from './services/audio';
import { useSpatialNavigation } from './hooks/useSpatialNavigation';
import { ScreenKey } from './types';
import { UserProvider } from './contexts/UserContext';

export default function App() {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [loadingProgress, setLoadingProgress] = useState(0);
  const [isLoading, setIsLoading] = useState(true);

  const { 
      activeScreen, 
      prevScreen, 
      isTransitioning, 
      containerStyle, 
      navigateTo, 
      resetToMenu, 
      WORLDS 
  } = useSpatialNavigation();

  // 1. BOOT SEQUENCE: Start preloading assets immediately on mount
  useEffect(() => {
    const initApp = async () => {
      await preloadAssets((progress) => setLoadingProgress(progress));
      // Small buffer to let the user see the 100% state for a beat
      setTimeout(() => setIsLoading(false), 400);
    };
    initApp();
  }, []);

  const handleLogin = () => {
      audio.playUiClick();
      setIsLoggedIn(true);
  };

  const handleLogout = () => {
      audio.playUiClick();
      setIsLoggedIn(false);
      resetToMenu();
  };

  const handleStartGame = () => navigateTo('GAME');

  // --- STATE MACHINE GATES ---

  // GATE 1: ASSET PRELOADING (Cold Boot)
  if (isLoading) {
      return (
          <AppShell>
              <LoadingScreen progress={loadingProgress} />
          </AppShell>
      );
  }

  // GATE 2: AUTHENTICATION / ENTRY
  if (!isLoggedIn) {
      return (
          <AppShell>
              <LoginScreen onLogin={handleLogin} />
          </AppShell>
      );
  }

  // GATE 3: MAIN APPLICATION (Authenticated)
  return (
    <UserProvider>
        <AppShell>
        <InspectorOverlay />

        {/* 
            SPATIAL NAVIGATION CONTAINER 
            This handles the sliding "World" transitions.
        */}
        <div 
            className="w-full h-full relative transition-transform duration-500 ease-[cubic-bezier(0.22,1,0.36,1)] will-change-transform"
            style={containerStyle}
        >
            {(Object.keys(WORLDS) as ScreenKey[]).map((key) => {
                const shouldRender = key === activeScreen || (isTransitioning && key === prevScreen);
                if (!shouldRender) return null;

                const config = WORLDS[key];
                const ScreenComponent = config.component;

                return (
                    <div 
                        key={key}
                        className="absolute w-full h-full top-0 left-0 overflow-hidden"
                        style={{ 
                            transform: `translate3d(${config.x * 100}%, ${config.y * 100}%, 0)` 
                        }}
                    >
                        <ScreenComponent 
                            onNavigate={navigateTo} 
                            onExit={() => navigateTo('MENU')}
                            onBack={() => navigateTo('MENU')}
                            onStartGame={handleStartGame}
                            onLogout={handleLogout}
                        />
                    </div>
                );
            })}
        </div>

        {/* Persistant Navigation Bar (Context aware) */}
        {activeScreen !== 'GAME' && (
            <NavigationBar activeScreen={activeScreen} onNavigate={navigateTo} />
        )}

        </AppShell>
    </UserProvider>
  );
}

import React, { useState, useLayoutEffect, useRef, useEffect, useCallback } from 'react';

interface GameTextProps {
  text: string;
  className?: string;
  /** The "Aspirational" font size. */
  baseFontSize: number;
  /** How much we allow the text to shrink. 0.3 is usually the limit for legibility. */
  minScale?: number;
  /** If > 1, allows the text to wrap and scales based on both width and height. */
  maxLines?: number;
}

/**
 * GameText: Iterative Balanced-Wrap Typography.
 * Listens for global font loading events to prevent 'snapping' when custom fonts arrive.
 */
export const GameText: React.FC<GameTextProps> = ({ 
  text, 
  className = '', 
  baseFontSize, 
  minScale = 0.3,
  maxLines = 1
}) => {
  const [layout, setLayout] = useState<{ lines: string[], scale: number }>({ lines: [text || ''], scale: 1 });
  const containerRef = useRef<HTMLDivElement>(null);
  const ghostRef = useRef<HTMLDivElement>(null);

  /**
   * THE MEASUREMENT ENGINE
   * Pure logic used for both initial layout and font-sync updates.
   */
  const findBestLayout = useCallback(() => {
    const container = containerRef.current;
    const ghost = ghostRef.current;
    if (!container || !ghost || !text) return;

    const words = text.split(/\s+/);

    const splitIntoLines = (numLines: number): string[] => {
      if (numLines <= 1 || words.length <= 1) return [text];
      const targetCharsPerLine = text.length / numLines;
      const result: string[][] = Array.from({ length: numLines }, () => []);
      let currentLine = 0;
      let currentChars = 0;

      words.forEach((word) => {
        if (currentLine < numLines - 1) {
            const distIfStay = Math.abs((currentChars + word.length) - targetCharsPerLine);
            const distIfMove = Math.abs(currentChars - targetCharsPerLine);
            if (currentChars > 0 && distIfMove < distIfStay) {
                currentLine++;
                currentChars = 0;
            }
        }
        result[currentLine].push(word);
        currentChars += word.length + 1;
      });

      return result.map(l => l.join(' ')).filter(s => s.length > 0);
    };

    const measureLayout = (lines: string[]) => {
      ghost.innerHTML = lines.map(l => `<div>${l}</div>`).join('');
      ghost.style.fontSize = `${baseFontSize}px`;

      const containerWidth = container.offsetWidth;
      const containerHeight = container.offsetHeight;

      if (containerWidth <= 0 || containerHeight <= 0) return 0;

      const ghostWidth = ghost.offsetWidth;
      const ghostHeight = ghost.offsetHeight;

      if (ghostWidth <= 0 || ghostHeight <= 0) return 0;

      const widthRatio = (containerWidth / ghostWidth) * 0.98;
      const heightRatio = (containerHeight / ghostHeight) * 0.98;

      if (lines.length === 1 && ghostHeight <= containerHeight) {
          return Math.min(1, widthRatio);
      }

      return Math.min(1, widthRatio, heightRatio);
    };

    let bestScale = 0;
    let bestLines: string[] = [text];
    const limit = Math.min(maxLines, 4); 

    for (let i = 1; i <= limit; i++) {
      if (i > words.length) break;
      const candidateLines = splitIntoLines(i);
      const scale = measureLayout(candidateLines);
      const bias = (limit - i) * 0.02; 
      if (scale + bias > bestScale) {
        bestScale = scale;
        bestLines = candidateLines;
      }
      if (i === 1 && scale > 0.95) break;
    }

    setLayout({ 
        lines: bestLines, 
        scale: Math.max(minScale, bestScale) 
    });
  }, [text, baseFontSize, minScale, maxLines]);

  // Handle initial mount and property changes
  useLayoutEffect(() => {
    findBestLayout();
    const observer = new ResizeObserver(() => requestAnimationFrame(findBestLayout));
    if (containerRef.current) observer.observe(containerRef.current);
    return () => observer.disconnect();
  }, [findBestLayout]);

  /**
   * GLOBAL FONT SYNCHRONIZATION
   * Re-measure when the browser finishes loading any font.
   * This is the definitive fix for "Font Snapping".
   */
  useEffect(() => {
    if (!('fonts' in document)) return;

    const handleFontLoad = () => {
        // Debounce slightly to allow the layout engine to ingest the metrics
        requestAnimationFrame(() => findBestLayout());
    };

    document.fonts.addEventListener('loadingdone', handleFontLoad);
    return () => document.fonts.removeEventListener('loadingdone', handleFontLoad);
  }, [findBestLayout]);

  if (!text) return null;

  return (
    <div 
      ref={containerRef} 
      className={`w-full h-full flex justify-center items-center relative leading-none overflow-hidden font-sans ${className}`}
    >
      <div
        ref={ghostRef}
        className={`absolute opacity-0 pointer-events-none flex flex-col items-center ${className}`}
        style={{ fontSize: `${baseFontSize}px`, left: -9999, whiteSpace: 'nowrap' }}
      />
      <div
        style={{ 
          transformOrigin: 'center center',
          transform: `scale(${layout.scale})`,
          fontSize: `${baseFontSize}px`,
          width: 'max-content',
          minWidth: '100%'
        }}
        className="flex flex-col items-center justify-center leading-none"
      >
        {layout.lines.map((line, idx) => (
            <div key={idx} className="whitespace-nowrap">
                {line}
            </div>
        ))}
      </div>
    </div>
  );
};

import React from 'react';

interface KeywordTextProps {
    text: string;
    className?: string;
}

export const KeywordText: React.FC<KeywordTextProps> = ({ text, className = '' }) => {
    if (!text) return null;

    // Basic parser for keywords
    // Looks for specific prefixes like "On Reveal:"

    const parts = text.split(':');
    const keywords = ['On Reveal', 'On Going', 'On Destroy', 'On Move', 'On Discard'];

    // Check if the first part matches a keyword
    const hasKeyword = parts.length > 1 && keywords.some(k => parts[0].trim().includes(k));

    if (hasKeyword) {
        return (
            <span className={className}>
               <span className="text-yellow-400 font-black uppercase tracking-wider mr-1">{parts[0]}:</span>
               <span className="font-medium text-white/90 shadow-black drop-shadow-sm">{parts.slice(1).join(':')}</span>
            </span>
        );
    }

    return (
        <span className={`font-bold text-white/90 shadow-black drop-shadow-sm ${className}`}>
            {text}
        </span>
    );
};

