import React, { useMemo } from 'react';
import { CARDS } from '../../constants';
import { Card } from '../Card';
import { CardDefinition } from '../../types';
import { useUser } from '../../contexts/UserContext';

interface CollectionGridProps {
    scrollRef: React.RefObject<HTMLDivElement>;
    ownedIds: string[];
    activeDeckIds: string[];
    draggingCardId?: string;
    onPointerDown: (e: React.PointerEvent, card: CardDefinition | null) => void;
}

export const CollectionGrid: React.FC<CollectionGridProps> = ({ 
    scrollRef, ownedIds, activeDeckIds, draggingCardId, onPointerDown 
}) => {
    const { collectionSort, collectionFilterSearch, collectionFilterTags } = useUser();

    const filteredAndSortedCards = useMemo(() => {
        let results = [...CARDS];

        if (collectionFilterSearch) {
            const query = collectionFilterSearch.toLowerCase();
            results = results.filter(c => 
                c.name.toLowerCase().includes(query) || 
                c.baseText.toLowerCase().includes(query)
            );
        }

        if (collectionFilterTags.length > 0) {
            results = results.filter(c => {
                return collectionFilterTags.some(tag => {
                    if (tag === 'None') return c.tags.length === 0;
                    return c.tags.includes(tag);
                });
            });
        }

        return results.sort((a, b) => {
            const aOwned = ownedIds.includes(a.id);
            const bOwned = ownedIds.includes(b.id);
            if (aOwned !== bOwned) return aOwned ? -1 : 1;

            if (collectionSort === 'Cost') return a.baseCost - b.baseCost;
            if (collectionSort === 'Power') return b.basePower - a.basePower;
            if (collectionSort === 'Newest') {
                const aIdx = CARDS.findIndex(c => c.id === a.id);
                const bIdx = CARDS.findIndex(c => c.id === b.id);
                return bIdx - aIdx;
            }
            return a.name.localeCompare(b.name);
        });
    }, [ownedIds, collectionSort, collectionFilterSearch, collectionFilterTags]);

    return (
        <div className="w-full h-full flex flex-col">
            {/* Using overflow-hidden to fully disable browser scroll logic. 
                Programmatic scroll is handled in useCollectionDrag hook. */}
            <div 
                ref={scrollRef} 
                className="flex-1 overflow-hidden px-4 pt-1.5 pb-52 touch-none select-none"
                onPointerDown={(e) => onPointerDown(e, null)} 
            >
                 {filteredAndSortedCards.length === 0 ? (
                     <div className="w-full py-20 flex flex-col items-center justify-center text-slate-700 pointer-events-none">
                         <svg className="w-12 h-12 mb-2 opacity-20" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                         <span className="text-[0.6rem] font-black uppercase tracking-widest">No matching cards</span>
                     </div>
                 ) : (
                     <div className="grid grid-cols-4 gap-x-2 gap-y-3">
                         {filteredAndSortedCards.map((def) => {
                             const isOwned = ownedIds.includes(def.id);
                             const inDeck = activeDeckIds.includes(def.id);
                             const isDragging = draggingCardId === def.id;

                             let stateClasses = '';
                             if (isDragging) {
                                 stateClasses = 'opacity-0';
                             } else if (!isOwned) {
                                 /* Removed pointer-events-none to allow inspection of unowned cards */
                                 stateClasses = 'opacity-40 grayscale scale-90';
                             } else if (inDeck) {
                                 stateClasses = 'opacity-50 grayscale'; 
                             } else {
                                 stateClasses = 'hover:scale-105'; 
                             }

                             return (
                                 <div 
                                    key={def.id} 
                                    className={`relative transition-all duration-300 rounded-md ${stateClasses}`}
                                    onPointerDown={(e) => {
                                        /* 
                                           Always stop propagation and call handler.
                                           The hook determines if it's a drag (invalid for unowned) 
                                           or a tap (valid for inspection).
                                        */
                                        e.stopPropagation(); 
                                        onPointerDown(e, def);
                                    }}
                                    onContextMenu={(e) => e.preventDefault()}
                                 >
                                     <div className="aspect-[5/7] rounded-md transition-all duration-300 cursor-grab active:cursor-grabbing">
                                         <Card 
                                            card={def} 
                                            size="xs" 
                                            variant="default" 
                                         />
                                     </div>
                                 </div>
                             );
                         })}
                     </div>
                 )}

                 <div className="h-12 w-full flex items-center justify-center mt-12 mb-8 pointer-events-none">
                     <div className="text-[0.55rem] text-slate-800 font-black uppercase tracking-[0.5em]">Terminal Archive End</div>
                 </div>
            </div>
        </div>
    );
}

import React, { useState, useEffect, useMemo } from 'react';
import { AppShell } from './components/ui/AppShell';
import { LoadingScreen } from './components/screens/LoadingScreen';
import { LoginScreen } from './components/screens/LoginScreen';
import { NavigationBar } from './components/ui/NavigationBar';
import { InspectorOverlay } from './components/InspectorOverlay';
import { preloadAssets } from './services/assetLoader';
import { audio } from './services/audio';
import { useSpatialNavigation } from './hooks/useSpatialNavigation';
import { ScreenKey } from './types';
import { UserProvider } from './contexts/UserContext';

export default function App() {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [loadingProgress, setLoadingProgress] = useState(0);
  const [isLoading, setIsLoading] = useState(true);

  // Track which screens have been visited to keep them mounted
  const [visitedScreens, setVisitedScreens] = useState<Set<ScreenKey>>(new Set(['MENU']));

  const { 
      activeScreen, 
      prevScreen, 
      isTransitioning, 
      containerStyle, 
      navigateTo, 
      resetToMenu, 
      WORLDS 
  } = useSpatialNavigation();

  // 1. BOOT SEQUENCE
  useEffect(() => {
    const initApp = async () => {
      await preloadAssets((progress) => setLoadingProgress(progress));
      setTimeout(() => setIsLoading(false), 400);
    };
    initApp();
  }, []);

  // Update visited screens whenever navigation occurs
  useEffect(() => {
    if (isLoggedIn && !visitedScreens.has(activeScreen)) {
        setVisitedScreens(prev => new Set(prev).add(activeScreen));
    }
  }, [activeScreen, isLoggedIn, visitedScreens]);

  const handleLogin = () => {
      audio.playUiClick();
      setIsLoggedIn(true);
  };

  const handleLogout = () => {
      audio.playUiClick();
      setIsLoggedIn(false);
      setVisitedScreens(new Set(['MENU'])); // Reset persistence on logout
      resetToMenu();
  };

  const handleStartGame = () => navigateTo('GAME');

  // --- STATE MACHINE GATES ---

  if (isLoading) {
      return (
          <AppShell>
              <LoadingScreen progress={loadingProgress} />
          </AppShell>
      );
  }

  if (!isLoggedIn) {
      return (
          <AppShell>
              <LoginScreen onLogin={handleLogin} />
          </AppShell>
      );
  }

  return (
    <UserProvider>
        <AppShell>
        <InspectorOverlay />

        <div 
            className="w-full h-full relative transition-transform duration-500 ease-[cubic-bezier(0.22,1,0.36,1)] will-change-transform"
            style={containerStyle}
        >
            {(Object.keys(WORLDS) as ScreenKey[]).map((key) => {
                // PERSISTENCE LOGIC:
                // 1. We only render if it's currently active, transitioning, OR has been visited before.
                const hasBeenVisited = visitedScreens.has(key);
                const isActive = key === activeScreen;
                const isPrev = key === prevScreen;
                const isParticipatingInTransition = isActive || (isTransitioning && isPrev);

                if (!hasBeenVisited && !isParticipatingInTransition) return null;

                const config = WORLDS[key];
                const ScreenComponent = config.component;

                return (
                    <div 
                        key={key}
                        className={`absolute w-full h-full top-0 left-0 overflow-hidden transition-opacity duration-300 ${!isParticipatingInTransition ? 'pointer-events-none invisible opacity-0' : 'pointer-events-auto visible opacity-100'}`}
                        style={{ 
                            transform: `translate3d(${config.x * 100}%, ${config.y * 100}%, 0)`,
                            // visibility: hidden is key here - it removes the element from the render tree 
                            // for performance while keeping the React component instance alive.
                        }}
                    >
                        <ScreenComponent 
                            onNavigate={navigateTo} 
                            onExit={() => navigateTo('MENU')}
                            onBack={() => navigateTo('MENU')}
                            onStartGame={handleStartGame}
                            onLogout={handleLogout}
                        />
                    </div>
                );
            })}
        </div>

        {activeScreen !== 'GAME' && (
            <NavigationBar activeScreen={activeScreen} onNavigate={navigateTo} />
        )}

        </AppShell>
    </UserProvider>
  );
}

import { Howl, Howler } from 'howler';
import { AUDIO_MANIFEST, SfxKey } from '../utils/assets';

// Global settings
Howler.autoUnlock = true; // Unlocks audio on first user interaction (mobile)
Howler.volume(0.5);

export type { SfxKey };

class AudioService {
    private sounds: Record<string, Howl> = {};
    private initialized = false;

    // Preload all sounds (Call this when app mounts)
    public init() {
        if (this.initialized) return;

        Object.entries(AUDIO_MANIFEST).forEach(([key, src]) => {
            this.sounds[key] = new Howl({
                src: [src],
                preload: true,
                volume: 0.5,
                // Ensure sounds play to completion even if component unmounts
                onplayerror: (id, err) => {
                    console.warn(`Playback error for ${key}:`, err);
                    this.sounds[key].once('unlock', () => this.sounds[key].play());
                }
            });
        });

        this.initialized = true;
        console.log('Audio System Initialized');
    }

    /**
     * Plays a sound effect. By default, Howler allows multiple instances of the 
     * same Howl to overlap, which is the desired "payout" behavior.
     */
    public play(key: SfxKey | undefined, volumeScale = 1.0) {
        if (!key || !this.sounds[key]) return;

        const sound = this.sounds[key];
        // We set the volume per-play instance if needed, but Howler global is better
        sound.volume(0.5 * volumeScale);
        sound.play();
    }

    /**
     * Gracefully fades out a specific sound.
     */
    public fadeOut(key: SfxKey, duration = 500) {
        const sound = this.sounds[key];
        if (sound && sound.playing()) {
            sound.fade(sound.volume(), 0, duration);
            setTimeout(() => sound.stop(), duration);
        }
    }

    public playUiClick() {
        this.play('sfx_ui_click', 0.8);
    }

    public playUiHover() {
        this.play('sfx_ui_hover', 0.2);
    }
}

