import { useState, useCallback } from 'react';
import { audio } from '../services/audio';

export type PurchaseStatus = 'idle' | 'processing' | 'success' | 'error';

interface UsePurchaseOfferProps {
    onPurchase: () => Promise<boolean>;
    successDelay?: number;
    resetDelay?: number;
}

export const usePurchaseOffer = ({ 
    onPurchase, 
    successDelay = 800, 
    resetDelay = 4000 // Increased to 4s to match natural audio decay
}: UsePurchaseOfferProps) => {
    const [status, setStatus] = useState<PurchaseStatus>('idle');
    const [holdProgress, setHoldProgress] = useState(0);
    const [isHolding, setIsHolding] = useState(false);

    const executePurchase = useCallback(async () => {
        if (status !== 'idle') return;

        setStatus('processing');

        const success = await onPurchase();

        if (success) {
            // Slight delay to feel the "processing" state
            setTimeout(() => {
                setStatus('success');
                audio.play('sfx_victory', 0.5);
                // Reset to idle after user sees success message
                setTimeout(() => {
                    setStatus('idle');
                    setHoldProgress(0);
                }, resetDelay);
            }, successDelay);
        } else {
            setStatus('idle');
            setHoldProgress(0);
        }
    }, [onPurchase, status, successDelay, resetDelay]);

    return {
        status,
        holdProgress,
        isHolding,
        setHoldProgress,
        setIsHolding,
        executePurchase
    };
};

import React, { useState } from 'react';
