interface StoreOfferDetailOverlayProps {
    offer: StoreOffer;
    onClose: () => void;
}

export const StoreOfferDetailOverlay: React.FC<StoreOfferDetailOverlayProps> = ({ offer, onClose }) => {
    const { processPurchase } = useUser();
    const [isPurchasing, setIsPurchasing] = useState(false);
    const [holdProgress, setHoldProgress] = useState(0);
    const [isHolding, setIsHolding] = useState(false);
    const [status, setStatus] = useState<'idle' | 'success'>('idle');

    const handlePurchase = async (e: React.MouseEvent) => {
        e.stopPropagation();
        if (status !== 'idle') return;

        setIsPurchasing(true);
        const success = await processPurchase(offer.id);

        if (success) {
            setStatus('success');
            // Play reward audio - it will play to completion even after modal closes
            audio.play('sfx_victory', 0.6);

            // Pacing: We wait 4.0s before auto-closing. 
            // This aligns with the natural duration of the victory fanfare.
            setTimeout(() => {
                onClose();
            }, 4000);
        } else {
            setIsPurchasing(false);
            // Error handling (User already has info via UI state usually)
        }
