import React, { useEffect, useState } from 'react';
import { SlantedButton } from '../ui/SlantedButton';
import { GameText } from '../ui/GameText';
import { useUser } from '../../contexts/UserContext';
import { usePurchaseOffer } from '../../hooks/usePurchaseOffer';
import { CreditIcon, GoldIcon } from '../ui/CurrencyIcons';

interface StoreResourceItemProps {
    type: 'gold' | 'credits';
    amount: number;
    costLabel: string;
    costAmount?: number;
    costType: 'gold' | 'real' | 'free';
    offerId?: string;
    availableAt?: string;
}

export const StoreResourceItem: React.FC<StoreResourceItemProps> = ({ 
    type, amount, costLabel, costAmount, costType, offerId, availableAt 
}) => {
    const { user, spendGold, addCredits, addGold, processPurchase, syncStore } = useUser();
    const [timeLeft, setTimeLeft] = useState<number>(0);

    const isFree = costType === 'free';
    const hasEnoughCurrency = isFree || costType === 'real' || (costType === 'gold' && user.gold >= (costAmount || 0));

    // Time-based locking (Daily rewards)
    useEffect(() => {
        if (!availableAt) return;
        const updateTimer = () => {
            const now = Date.now();
            const target = new Date(availableAt).getTime();
            const diff = Math.max(0, Math.floor((target - now) / 1000));
            setTimeLeft(diff);
        };
        updateTimer();
        const interval = setInterval(updateTimer, 1000);
        return () => clearInterval(interval);
    }, [availableAt]);

    const handleAction = async () => {
        if (!hasEnoughCurrency) {
            syncStore();
            return false;
        }

        if (isFree && offerId) {
            return await processPurchase(offerId);
        } else if (costType === 'gold' && costAmount) {
            if (spendGold(costAmount)) {
                if (type === 'credits') addCredits(amount);
                else addGold(amount);
                return true;
            }
        } else if (costType === 'real') {
            // Mock IAP
            if (type === 'gold') addGold(amount);
            else addCredits(amount);
            return true;
        }
        return false;
    };

    const { status, holdProgress, isHolding, setHoldProgress, setIsHolding, executePurchase } = usePurchaseOffer({
        onPurchase: handleAction
    });

    const isLocked = timeLeft > 0;
    const isSuccess = status === 'success';
    const isProcessing = status === 'processing';

    return (
        <div className={`
            bg-gradient-to-b from-slate-800 via-slate-900 to-black border-2 transition-all duration-300 rounded p-2 flex flex-col items-center justify-between h-[10.5rem] relative overflow-hidden shadow-2xl
            ${isSuccess ? 'border-emerald-400 ring-2 ring-emerald-500/50 bg-emerald-950' : 'border-slate-700'}
        `}>
            {/* Success Flash */}
            {isSuccess && <div className="absolute inset-0 bg-white/20 animate-pulse z-40 pointer-events-none" />}

            {/* Hold Progress Bar Overlay */}
            {holdProgress > 0 && status === 'idle' && !isLocked && (
                <div 
                    className={`absolute inset-y-0 left-0 z-0 pointer-events-none ${type === 'gold' ? 'bg-amber-400/30' : 'bg-blue-400/30'}`}
                    style={{ width: `${holdProgress}%` }}
                />
            )}

            {/* Amount & Label */}
            <div className="relative z-10 text-center w-full px-1">
                <div className="h-6 w-full mb-0.5">
                    <GameText 
                        text={amount.toLocaleString()} 
                        baseFontSize={24} 
                        className="text-white drop-shadow-md"
                    />
                </div>
                <div className={`text-[0.45rem] font-black uppercase tracking-[0.2em] leading-none ${type === 'gold' ? 'text-amber-500' : 'text-blue-400'}`}>
                    {type}
                </div>
            </div>

            {/* Resource Icon Visual */}
            <div className="relative z-10 flex-1 flex items-center justify-center">
                <div className={`
                    w-12 h-12 rounded-full flex items-center justify-center border-2 transition-all duration-500
                    ${isSuccess ? 'bg-emerald-500 border-emerald-300 scale-110 shadow-[0_0_20px_rgba(16,185,129,0.8)]' : 'bg-slate-900 border-slate-700'}
                `}>
                    {isSuccess ? (
                        <svg className="w-7 h-7 text-white animate-pop" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={4} d="M5 13l4 4L19 7" /></svg>
                    ) : (
                        type === 'gold' ? <GoldIcon size="md" /> : <CreditIcon size="md" />
                    )}
                </div>
            </div>

            {/* Bottom Status / Timer / Button */}
            <div className="w-full relative z-10">
                <div className="h-3 flex items-center justify-center mb-0.5 overflow-visible">
                    {isHolding && status === 'idle' && !isLocked && (
                        <span className="text-[0.45rem] font-black text-white uppercase tracking-wider animate-pulse drop-shadow-[0_2px_2px_rgba(0,0,0,1)] whitespace-nowrap">Hold to acquire</span>
                    )}
                    {isProcessing && (
                        <span className="text-[0.45rem] font-black text-white animate-pulse uppercase tracking-wider drop-shadow-[0_2px_2px_rgba(0,0,0,1)] whitespace-nowrap">Processing...</span>
                    )}
                    {isSuccess && (
                        <span className="text-[0.45rem] font-black text-white animate-bounce uppercase tracking-wider drop-shadow-[0_2px_2px_rgba(0,0,0,1)] whitespace-nowrap">Purchased!</span>
                    )}
                </div>

                {isLocked ? (
                    <div className="h-8 w-full bg-slate-900 border border-slate-700 rounded flex items-center justify-center gap-1.5 grayscale opacity-60">
                         <svg className="w-2.5 h-2.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                         <span className="text-[0.6rem] font-black tabular-nums">{Math.floor(timeLeft / 60)}:{(timeLeft % 60).toString().padStart(2, '0')}</span>
                    </div>
                ) : (
                    <SlantedButton 
                        variant={isSuccess ? 'success' : (type === 'gold' ? 'primary' : 'blue')} 
                        size="sm" 
                        fullWidth
                        holdDuration={isFree ? 0 : 800}
                        onHoldChange={setIsHolding}
                        onProgressChange={setHoldProgress}
                        onClick={executePurchase}
                        disabled={isProcessing || isSuccess}
                    >
                        {isSuccess ? 'READY' : costLabel}
                    </SlantedButton>
                )}
            </div>
        </div>
    );
};

import React, { useState, useEffect, useRef } from 'react';
import { useUser } from '../../contexts/UserContext';
import { CARDS } from '../../constants';
import { SlantedButton } from '../ui/SlantedButton';
import { GameText } from '../ui/GameText';

interface DeckSelectorProps {
    activeDeckId: number;
    onSelectDeck: (id: number) => void;
}

/**
 * CLASSIC DECK SELECTOR
 * High-performance horizontal scroll with 3D flip stats.
 */
export const DeckSelectorClassic: React.FC<DeckSelectorProps> = ({ activeDeckId, onSelectDeck }) => {
    const { user } = useUser();
    const [flippedId, setFlippedId] = useState<number | null>(null);
    const containerRef = useRef<HTMLDivElement>(null);

    /**
     * MANUAL CENTERING ENGINE
     * We avoid scrollIntoView because it causes parent layout shifts in transformed containers.
     */
    useEffect(() => {
        if (containerRef.current) {
            const container = containerRef.current;
            const activeElement = container.querySelector(`[data-active="true"]`) as HTMLElement;

            if (activeElement) {
                const elementOffset = activeElement.offsetLeft;
                const elementWidth = activeElement.offsetWidth;
                const containerWidth = container.offsetWidth;

                // Calculate the exact left scroll required to center this specific element
                const targetScroll = elementOffset - (containerWidth / 2) + (elementWidth / 2);

                container.scrollTo({
                    left: targetScroll,
                    behavior: 'smooth'
                });
            }
        }
    }, [activeDeckId]);

    const handleDeckClick = (id: number) => {
        if (activeDeckId === id) {
            setFlippedId(flippedId === id ? null : id);
        } else {
            onSelectDeck(id);
            setFlippedId(null);
        }
    };

    const getStats = (deckId: number) => {
        const cardIds = user.decks[deckId] || [];
        if (cardIds.length === 0) return { avgCost: 0, avgPower: 0, count: 0 };

        const deckCards = cardIds.map(id => CARDS.find(c => c.id === id)).filter(Boolean);
        const totalCost = deckCards.reduce((acc, c) => acc + (c?.baseCost || 0), 0);
        const totalPower = deckCards.reduce((acc, c) => acc + (c?.basePower || 0), 0);

        return {
            avgCost: (totalCost / deckCards.length).toFixed(1),
            avgPower: (totalPower / deckCards.length).toFixed(1),
            count: deckCards.length
        };
    };

    const deckIds = Object.keys(user.decks).map(Number).sort((a, b) => a - b);

    return (
        <div 
            ref={containerRef}
            className="w-full flex overflow-x-auto pt-2 pb-0.5 px-3 gap-2 shrink-0 scrollbar-hide perspective-1000"
        >
            {deckIds.map(i => {
                const isSelected = activeDeckId === i;
                const isFlipped = flippedId === i && isSelected;
                const stats = getStats(i);
                const deckName = user.deckNames[i] || 'UNTITLED';
                const isValid = stats.count === 12;

                const selectedVariant = isValid ? 'success' : 'danger';

                return (
                    <div 
                        key={i} 
                        data-active={isSelected}
                        className="min-w-[7.5rem] h-14 relative shrink-0"
                    >
                        <div className={`
                            w-full h-full relative transition-transform duration-500 transform-style-3d
                            ${isFlipped ? 'rotate-y-180' : ''}
                        `}>
                            {/* FRONT SIDE */}
                            <div className="absolute inset-0 backface-hidden">
                                <SlantedButton 
                                    variant={isSelected ? selectedVariant : 'secondary'}
                                    fullWidth
                                    size="md"
                                    className="!h-full"
                                    onClick={() => handleDeckClick(i)}
                                >
                                    <div className="flex flex-col items-center justify-center w-full h-full pointer-events-none pt-1 pb-0.5">
                                        <div className="flex items-center gap-1">
                                            <span className="text-[0.45rem] font-black text-white/40 uppercase tracking-widest">Deck {i < 10 ? `0${i}` : i}</span>
                                            {!isValid && <div className="w-1.5 h-1.5 rounded-full bg-amber-500 animate-pulse shadow-[0_0_5px_rgba(245,158,11,0.8)]" />}
                                        </div>
                                        <div className="flex-1 w-full min-h-0 flex items-center justify-center">
                                            <GameText 
                                                text={deckName} 
                                                baseFontSize={22} 
                                                maxLines={2}
                                                className="text-white drop-shadow-md"
                                            />
                                        </div>
                                    </div>
                                </SlantedButton>
                            </div>

                            {/* BACK SIDE (STATS) */}
                            <div className="absolute inset-0 backface-hidden rotate-y-180">
                                <SlantedButton
                                    variant={isValid ? 'success' : 'danger'}
                                    fullWidth
                                    size="md"
                                    className="!h-full"
                                    onClick={() => handleDeckClick(i)}
                                >
                                    <div className="flex items-center justify-around w-full h-full px-1">
                                        <div className="flex flex-col items-center">
                                            <span className="text-[0.4rem] font-black uppercase text-white/60 leading-none mb-1">Cost</span>
                                            <span className="text-sm font-black text-white italic">{stats.avgCost}</span>
                                        </div>
                                        <div className="w-px h-8 bg-white/20" />
                                        <div className="flex flex-col items-center">
                                            <span className="text-[0.4rem] font-black uppercase text-white/60 leading-none mb-1">Power</span>
                                            <span className="text-sm font-black text-white italic">{stats.avgPower}</span>
                                        </div>
                                    </div>
                                </SlantedButton>
                            </div>
                        </div>
                    </div>
                );
            })}

            <style>{`
                .perspective-1000 { perspective: 1000px; }
                .transform-style-3d { transform-style: preserve-3d; }
                .backface-hidden { backface-visibility: hidden; }
                .rotate-y-180 { transform: rotateY(180deg); }
            `}</style>
        </div>
    );
};

