    username: string;
    level: number;
    rank: number; 
    credits: number;
    gold: number;
    activeDeckId: number;
    avatarId: string;
    purchasedOfferIds: string[]; 
    lastClaimedDates: Record<string, string>;
    collection: string[]; 
    decks: Record<number, string[]>; 
    deckNames: Record<number, string>;
    // Updated: Detailed Stats for UI
    deckStats: Record<number, {
        conquestWinRate: number;
        ladderWinRate: number;
        conquestWins: number;
        conquestTotal: number;
        ladderWins: number;
        ladderLosses: number;
        lastModified: string; // ISO String
    }>;
    cardRarities: Record<string, CardRarity>; 
}

export type CardRarity = "Common" | "Rare" | "Epic" | "Legendary";

// --- Store Types ---
export type OfferItem = 
  | { type: 'card'; definitionId: string }
  | { type: 'currency'; currencyType: 'gold' | 'credits'; amount: number };

export interface StoreOffer {
    id: string;
    title: string;
    description: string;
    price: string; 
    priceAmount?: number; 
    priceType: 'real' | 'gold' | 'credits' | 'free';
    imageUrl: string;
    discountLabel?: string;
    category?: 'featured' | 'monthly' | 'daily';
    isOneTime: boolean;
    purchaseLimit?: number; 
    contents: OfferItem[];
    expiryDate?: string; 
    cooldownSeconds?: number; 
    availableAt?: string; 
}

export interface StoreData {
    offers: StoreOffer[];
    lastUpdated: number;
    refreshHintSeconds: number;
}

export type StoreErrorCode = 
    | 'ERR_OFFER_NOT_FOUND' 
    | 'ERR_INSUFFICIENT_FUNDS' 
    | 'ERR_STALE_OFFER' 
    | 'ERR_DUPLICATE_TRANSACTION' 
    | 'ERR_BALANCE_DESYNC'
    | 'ERR_COOLDOWN_ACTIVE';

export interface PurchaseResponse {
    success: boolean;
    errorCode?: StoreErrorCode;
    transactionId: string;
    updatedProfile?: UserProfile; 
}

export type VfxKey = 
    | 'vfx_explosion_small' 
    | 'vfx_warp_trail' 
    | 'vfx_dust_motes' 
    | 'vfx_electric_arcs' 
    | 'vfx_nebula_fog';

export interface CardDefinition {
  id: string;
  name: string;
  rarity: CardRarity;
  baseCost: number;
  basePower: number;
  tags: string[]; 
  baseText: string;
  effect: string; 
  imageUrl: string;
  flavorText?: string;

  sfxOnPlay?: SfxKey;   
  sfxOnReveal?: SfxKey; 
  vfxOnReveal?: VfxKey; 
}

export interface StatModifier {
  source: string; 
  value: number;
  type: "BASE" | "PERMANENT" | "CONTINUOUS";
}

export interface CardInstance {
  instanceId: string;
  definitionId: string;
  owner: PlayerID;

  zone: Zone;
  laneIndex: number | null;
  slotIndex: number | null;
  faceUp: boolean;
  turnPlayed: number | null;
  playOrder: number | null;

  baseCost: number;
  currentCost: number;
  totalCost: number;
  costModifiers: StatModifier[];

  basePower: number;
  currentPower: number;
  totalPower: number;
  powerModifiers: StatModifier[];

  baseText: string;
  currentText: string;
  abilityEnabled: boolean;
  hasResolvedOnReveal: boolean;

  startedInDeck: boolean;
  created: boolean;
  createdInZone: Zone;

  def: CardDefinition;

  // State Flags
  pendingDiscard?: boolean;
  pendingDestroy?: boolean;
  destroyDestinationOverride?: 'hand' | 'board';
}

export interface LocationDefinition {
  id: string;
  name: string;
  description: string;
  effect: string;
  imageUrl: string;
  sfxOnReveal?: SfxKey;
  vfxAmbient?: VfxKey;
}

export interface LocationInstance {
  id: string;
  def: LocationDefinition;
  revealed: boolean;
}

export type LaneSlots = [CardInstance | null, CardInstance | null, CardInstance | null, CardInstance | null];

export interface Lane {
  location: LocationInstance;
  p1Slots: LaneSlots;
  p2Slots: LaneSlots;
}

export type GameEvent = 
    | { type: 'SFPlay', id: string, sfxId: SfxKey }
    | { type: 'SFX_PLAY', id: string, sfxId: SfxKey }
    | { type: 'VFX_PLAY', id: string, vfxId: VfxKey, laneIdx?: number, slotIdx?: number, playerId?: PlayerID };

export type ExecutionTask =
  | { type: 'TRIGGER_ABILITY', sourceId: string, triggerTag: string }
  | { type: 'EXECUTE_DISCARD', sourceId: string }
  | { type: 'RUN_EFFECT', effectId: string, sourceId: string, params?: any }
  | { type: 'REVEAL_CARD', sourceId: string };

export interface PlayerStats {
    destroyedCount: number;
    destroyedPower: number;
}

export interface PlayerState {
    energy: number;
    stats: PlayerStats;
    hand: CardInstance[];
    deck: CardInstance[];
    discardPile: CardInstance[];
    destroyedPile: CardInstance[];
    banishedPile: CardInstance[];
}

export interface GameState {
  turn: number;
  maxTurns: number;
  nextPlayOrder: number;
  priority: PlayerID;

  players: {
      p1: PlayerState;
      p2: PlayerState;
  };

  lanes: [Lane, Lane, Lane];

  winner: PlayerID | 'draw' | null;
  phase: 'planning' | 'resolving' | 'gameover';
  history: string[];
  eventQueue: GameEvent[];
  executionQueue: ExecutionTask[];
}

export interface OnRevealEffect {
  (state: GameState, source: CardInstance, context: EffectContext): GameState;
}

export interface OngoingEffectFunction {
  (state: GameState, laneIdx: number, slotIdx: number, source: CardInstance): void;
}

export interface ActionSet {
    destroyCard: (state: GameState, id: string) => GameState;
    addCardToHand: (state: GameState, card: CardInstance) => GameState;
    moveCard: (state: GameState, id: string, targetLane: number) => GameState;
    addCardToLane: (state: GameState, card: CardInstance, laneIdx: number) => GameState;
    modifyPower: (state: GameState, id: string, delta: number, source: string) => GameState;
    recalcState: (state: GameState) => GameState;
    playSfx: (state: GameState, sfxId: SfxKey) => GameState;
}

export interface EffectContext {
  player: PlayerID;
  laneIndex: number;
  slotIndex: number;
  gameRegistry: CardDefinition[];
  actions: ActionSet;
  params?: any; 
}

