import { useCollectionDrag } from '../../hooks/useCollectionDrag';
import { CARDS } from '../../constants';
import { CardDefinition, CollectionTab } from '../../types';

export const DeckScreen: React.FC = () => {
    const { user, updateDeck, activeDeck, setActiveDeck } = useUser();
    const [activeTab, setActiveTab] = useState<CollectionTab>('CARDS');

    const scrollRef = useRef<HTMLDivElement>(null);
    const vaultRef = useRef<HTMLDivElement>(null);
    const archiveRef = useRef<HTMLDivElement>(null);

    const handleAddCard = useCallback((cardId: string) => {
        if (activeDeck.length < 12 && !activeDeck.includes(cardId)) {
            updateDeck(user.activeDeckId, [...activeDeck, cardId]);
        }
    }, [activeDeck, user.activeDeckId, updateDeck]);

    const handleRemoveCard = useCallback((cardId: string) => {
        updateDeck(user.activeDeckId, activeDeck.filter(id => id !== cardId));
    }, [activeDeck, user.activeDeckId, updateDeck]);

    const { dragState, handlePointerDown } = useCollectionDrag({
        onAdd: handleAddCard,
        onRemove: handleRemoveCard,
        scrollRef: scrollRef,
        vaultRef: vaultRef,
        archiveRef: archiveRef
    });

    const deckCards = useMemo(() => {
        return activeDeck
            .map(id => CARDS.find(c => c.id === id))
            .filter((c): c is CardDefinition => !!c)
            .sort((a, b) => {
                if (a.baseCost !== b.baseCost) {
                    return a.baseCost - b.baseCost;
                }
                return a.name.localeCompare(b.name);
            });
    }, [activeDeck]);

    const renderContent = () => {
        switch(activeTab) {
            case 'COMICS': return <ComicArchive />;
            case 'INVENTORY': return <InventoryStash />;
            default:
                return (
                    <>
                        {/* 1. DECK SELECTION & VAULT ZONE */}
                        <div 
                            ref={vaultRef}
                            className={`shrink-0 border-b border-slate-700 z-20 transition-all duration-300 ${dragState?.active && dragState.origin === 'archive' ? 'ring-2 ring-inset ring-indigo-500/50' : ''}`}
                            data-drop-zone="vault"
                        >
                            <DeckSelector 
                                activeDeckId={user.activeDeckId} 
                                onSelectDeck={setActiveDeck}
                            />

                            <div className="px-3 pb-2">
                                <DeckVault 
                                    cards={deckCards} 
                                    draggingCardId={dragState?.active && dragState.origin === 'vault' ? dragState.card.id : undefined}
                                    onPointerDown={(e, card) => handlePointerDown(e, card, 'vault')}
                                />
                            </div>
                        </div>

                        {/* 2. COLLECTION ARCHIVE */}
                        <div 
                            ref={archiveRef}
                            className={`flex-1 min-h-0 relative transition-all duration-300 ${dragState?.active && dragState.origin === 'vault' ? 'bg-red-500/5' : ''}`}
                            data-drop-zone="archive"
                        >
                            <CollectionGrid 
                                scrollRef={scrollRef}
                                ownedIds={user.collection}
                                activeDeckIds={activeDeck}
                                draggingCardId={dragState?.active && dragState.origin === 'archive' ? dragState.card.id : undefined}
                                onPointerDown={(e, card) => handlePointerDown(e, card, 'archive')}
                            />
                        </div>
                    </>
                );
        }
    };

    return (
        <div className="w-full h-full flex flex-col bg-slate-950 overflow-hidden relative">
            <StandardHeader 
                title="COLLECTION" 
                leftContent={
                    <div className="flex items-center gap-1 bg-slate-800 border border-indigo-500/30 px-2 py-0.5 rounded-full shadow-lg ml-1">
                        <span className="text-[0.5rem] font-black text-indigo-400">CL</span>
                        <span className="text-[0.65rem] font-black text-white italic tracking-tighter">1,402</span>
                    </div>
                }
                rightContent={
                    <div className="flex items-center gap-1.5 mr-1">
                        <TabButton 
                            active={activeTab === 'CARDS'} 
                            onClick={() => setActiveTab('CARDS')}
                            icon={<svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" /></svg>}
                        />
                        <TabButton 
                            active={activeTab === 'COMICS'} 
                            onClick={() => setActiveTab('COMICS')}
                            icon={<svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" /></svg>}
                        />
                        <TabButton 
                            active={activeTab === 'INVENTORY'} 
                            onClick={() => setActiveTab('INVENTORY')}
                            icon={<svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4" /></svg>}
                        />
                    </div>
                }
            />

            <CollectionDragOverlay dragState={dragState} />

            {renderContent()}
        </div>
    );
};

const TabButton: React.FC<{ active: boolean; onClick: () => void; icon: React.ReactNode }> = ({ active, onClick, icon }) => (
    <button 
        onClick={onClick}
        className={`w-8 h-7 flex items-center justify-center rounded skew-x-[-15deg] transition-all duration-300 border-b-2 ${active ? 'bg-indigo-600 border-indigo-400 text-white shadow-[0_0_10px_rgba(79,70,229,0.5)] scale-110' : 'bg-slate-800 border-slate-700 text-slate-500 active:scale-95'}`}
    >
        <div className="skew-x-[15deg]">{icon}</div>
    </button>
);

