                    <div className="flex items-center gap-1.5 bg-indigo-600/30 border border-indigo-500/50 px-2.5 py-0.5 rounded-sm shadow-[0_0_10px_rgba(79,70,229,0.2)]">
                        <div className="w-1.5 h-1.5 rounded-full bg-indigo-400 animate-pulse" />
                        <span className="text-[0.65rem] font-black text-white italic tracking-tighter">PREMIUM</span>
                    </div>
                </div>

                <div className="flex items-center justify-between mt-1.5 px-0.5">
                    <div className="flex items-center gap-1.5">
                         <span className="text-[0.6rem] font-black text-slate-400 uppercase tracking-widest leading-none">
                            Dec 1 - Dec 31
                        </span>
                    </div>
                    <div className="flex items-center gap-1.5">
                        <span className="text-[0.5rem] font-black text-indigo-400 uppercase leading-none mr-0.5">ENDS IN:</span>
                        <span className="text-xs font-black text-white italic tabular-nums leading-none tracking-tight">
                            {timeLeft.dd}:{timeLeft.hh}:{timeLeft.mm}:{timeLeft.ss}
                        </span>
                    </div>
                </div>
            </div>

            {/* 2. PROGRESS BAR HEADER SECTION */}
            <div className="shrink-0 bg-slate-950/80 border-b border-slate-800/60 p-3 z-30 shadow-md">
                <div className="flex justify-between items-end mb-1.5 px-1">
                    <span className="text-[0.6rem] font-black text-indigo-400 uppercase tracking-[0.2em] leading-none">Season Mastery</span>
                    <span className="text-[0.65rem] font-black text-white italic leading-none">{progressPercent}% TO LVL {currentLevel + 1}</span>
                </div>
                <div className="h-3 w-full bg-slate-900 rounded-full overflow-hidden border border-slate-800 shadow-inner p-[1px]">
                    <div 
                        className="h-full bg-gradient-to-r from-indigo-600 via-indigo-500 to-purple-500 rounded-full relative transition-all duration-1000 ease-out shadow-[0_0_15px_rgba(99,102,241,0.4)]"
                        style={{ width: `${progressPercent}%` }}
                    >
                        <div className="absolute inset-0 bg-white/10 animate-[pulse_2s_infinite]"></div>
                    </div>
                </div>
            </div>

            {/* MAIN CONTENT AREA */}
            <div className="flex-1 flex flex-row overflow-hidden min-h-0 px-2 gap-x-5">

                {/* LEFT COLUMN: HERO CARD & CTA */}
                <div className="w-[36%] flex flex-col items-center justify-center p-1 bg-gradient-to-r from-indigo-900/10 to-transparent border-r border-slate-900/50">
                    <div className="flex-1 flex flex-col items-center justify-center w-full">
                        {/* Label ABOVE the card container */}
                        <div className="text-[0.45rem] font-black text-indigo-400 uppercase tracking-[0.4em] mb-3 drop-shadow-sm">Season Exclusive</div>

                        <div 
                            className="relative animate-pulse-slow cursor-pointer"
