                        >
                            <div className="absolute -inset-6 bg-indigo-600/15 blur-3xl rounded-full" />

                            <div className="relative z-10 drop-shadow-[0_0_1.5rem_rgba(79,70,229,0.35)] scale-90 active:scale-95 transition-transform">
                                <Card card={seasonCard} size="md" />
                            </div>
                        </div>

                        <div className="mt-3 text-center px-1 w-full">
                            <div className="h-6 w-full mb-1">
                                <GameText text={seasonCard.name} baseFontSize={20} className="text-white font-black italic tracking-tighter uppercase" />
                            </div>
                            <div className="h-0.5 w-8 bg-indigo-600/60 mx-auto rounded-full mb-5" />

                            {/* COMPACT UPGRADE BUTTON */}
                            <div className="w-full max-w-[6rem] mx-auto animate-bounce-slow">
                                <SlantedButton variant="warning" size="sm" fullWidth className="!h-7 shadow-[0_4px_10px_rgba(180,83,9,0.3)]">
                                    <span className="text-[0.5rem] font-black italic">UPGRADE</span>
                                </SlantedButton>
                            </div>
                        </div>
                    </div>
                </div>

                {/* RIGHT COLUMN: REWARD TRACK */}
                <div className="flex-1 flex flex-col bg-slate-900/20">
                    <div className="flex-1 overflow-y-auto px-1 py-4 space-y-2.5 scrollbar-hide pb-24">
                        {rewardList.map((reward) => (
                            <div key={reward.level} className="h-11 w-full relative group">
                                <SlantedButton 
                                    variant={reward.isClaimed ? 'secondary' : reward.variant}
                                    fullWidth 
                                    size="md"
                                    className={`!h-full transition-all duration-300 ${reward.isClaimed ? 'opacity-30 grayscale' : ''} ${reward.isActive ? 'scale-[1.02] z-10' : ''}`}
