                                >
                                    <div className="flex items-center w-full h-full">
                                        {/* Subcolumn 1: Level (Left) */}
                                        <div className="w-9 h-full flex flex-col items-center justify-center border-r border-white/5 shrink-0 bg-black/10">
                                            <span className="text-[0.3rem] font-black opacity-60 uppercase leading-none">LVL</span>
                                            <span className="text-xs font-black italic tabular-nums leading-none">{reward.level}</span>
                                        </div>

                                        {/* Subcolumn 2: Reward (Right) */}
                                        <div className="flex-1 px-2 text-left overflow-hidden">
                                            <span className="text-[0.6rem] font-black italic uppercase tracking-tight truncate block">
