import React from 'react';

type BadgeVariant = 'primary' | 'secondary' | 'success' | 'danger' | 'warning' | 'blue';

interface HexBadgeProps {
    children: React.ReactNode;
    variant?: BadgeVariant;
    size?: 'xs' | 'sm' | 'md' | 'lg' | 'xl';
    className?: string;
    glow?: boolean;
}

export const HexBadge: React.FC<HexBadgeProps> = ({ 
    children, 
    variant = 'primary', 
    size = 'md',
    className = '',
    glow = false
}) => {
    const variants = {
        primary: {
            fill: 'fill-purple-900',
            stroke: 'stroke-purple-400',
            text: 'text-white',
            glow: 'shadow-[0_0_15px_rgba(168,85,247,0.5)]'
        },
        secondary: {
            fill: 'fill-slate-900',
            stroke: 'stroke-slate-500',
            text: 'text-slate-300',
            glow: 'shadow-[0_0_15px_rgba(71,85,105,0.3)]'
        },
        success: {
            fill: 'fill-emerald-950',
            stroke: 'stroke-emerald-400',
            text: 'text-emerald-400',
            glow: 'shadow-[0_0_15px_rgba(52,211,153,0.4)]'
        },
        danger: {
            fill: 'fill-red-950',
            stroke: 'stroke-red-500',
            text: 'text-red-400',
            glow: 'shadow-[0_0_15px_rgba(248,113,113,0.4)]'
        },
        warning: {
            fill: 'fill-amber-950',
            stroke: 'stroke-amber-400',
            text: 'text-amber-400',
            glow: 'shadow-[0_0_15px_rgba(251,191,36,0.4)]'
        },
        blue: {
            fill: 'fill-blue-950',
            stroke: 'stroke-blue-400',
            text: 'text-blue-400',
            glow: 'shadow-[0_0_15px_rgba(96,165,250,0.4)]'
        }
    };

    const sizeClasses = {
        xs: 'w-6 h-6 text-[0.5rem]',
        sm: 'w-8 h-8 text-[0.6rem]',
        md: 'w-10 h-10 text-[0.75rem]',
        lg: 'w-14 h-14 text-[1rem]',
        xl: 'w-20 h-20 text-[1.5rem]'
    };

    const config = variants[variant];
    const baseSize = sizeClasses[size];

    return (
        <div className={`relative ${baseSize} flex items-center justify-center ${className}`}>
            {/* THE HEXAGON SVG BACKGROUND */}
            <svg 
                viewBox="0 0 100 100" 
                className={`absolute inset-0 w-full h-full drop-shadow-lg ${glow ? config.glow : ''}`}
            >
                {/* 
                  A true hexagon path (points top/bottom).
                  Vertices: (50,0), (93.3,25), (93.3,75), (50,100), (6.7,75), (6.7,25)
                */}
                <path 
                    d="M50 2 L94 26 L94 74 L50 98 L6 74 L6 26 Z" 
                    className={`${config.fill} ${config.stroke} stroke-[4]`}
                />

                {/* Inner Bezel for "Premium" look */}
                <path 
                    d="M50 8 L88 30 L88 70 L50 92 L12 70 L12 30 Z" 
                    fill="white" 
                    fillOpacity="0.05"
                />
            </svg>

            {/* CONTENT LAYER */}
            <div className={`relative z-10 font-black italic tracking-tighter uppercase ${config.text} flex items-center justify-center text-center leading-none px-1`}>
                {children}
            </div>
        </div>
    );
};

import React, { useState, useCallback, useMemo, useRef, useEffect } from 'react';
import { StandardHeader } from '../ui/StandardHeader';
import { DeckSelector } from '../game/DeckSelector';
import { CollectionGrid } from '../deck/CollectionGrid';
import { DeckVault } from '../deck/DeckVault';
import { ComicArchive } from '../deck/ComicArchive';
import { InventoryStash } from '../deck/InventoryStash';
import { CollectionDragOverlay } from '../CollectionDragOverlay';
import { useUser } from '../../contexts/UserContext';
import { useCollectionDrag } from '../../hooks/useCollectionDrag';
import { CARDS } from '../../constants';
import { CardDefinition, CollectionTab, ScreenKey } from '../../types';
import { HexBadge } from '../ui/HexBadge';

interface DeckScreenProps {
    onNavigate: (s: ScreenKey) => void;
    // We expect the parent to pass the current active screen so we can reset tabs on entry
    activeScreen?: ScreenKey; 
}

export const DeckScreen: React.FC<DeckScreenProps> = ({ activeScreen }) => {
    const { user, updateDeck, activeDeck, setActiveDeck } = useUser();
    const [activeTab, setActiveTab] = useState<CollectionTab>('CARDS');

    // EFFECT: Always default to CARDS when the player "arrives" at this world
    useEffect(() => {
        if (activeScreen === 'DECK') {
            setActiveTab('CARDS');
        }
    }, [activeScreen]);

    const scrollRef = useRef<HTMLDivElement>(null);
    const vaultRef = useRef<HTMLDivElement>(null);
    const archiveRef = useRef<HTMLDivElement>(null);

    const handleAddCard = useCallback((cardId: string) => {
        if (activeDeck.length < 12 && !activeDeck.includes(cardId)) {
            updateDeck(user.activeDeckId, [...activeDeck, cardId]);
        }
    }, [activeDeck, user.activeDeckId, updateDeck]);

    const handleRemoveCard = useCallback((cardId: string) => {
        updateDeck(user.activeDeckId, activeDeck.filter(id => id !== cardId));
    }, [activeDeck, user.activeDeckId, updateDeck]);

    const { dragState, handlePointerDown } = useCollectionDrag({
        onAdd: handleAddCard,
        onRemove: handleRemoveCard,
        scrollRef: scrollRef,
        vaultRef: vaultRef,
        archiveRef: archiveRef
    });

    const deckCards = useMemo(() => {
        return activeDeck
            .map(id => CARDS.find(c => c.id === id))
            .filter((c): c is CardDefinition => !!c)
            .sort((a, b) => {
                if (a.baseCost !== b.baseCost) {
                    return a.baseCost - b.baseCost;
                }
                return a.name.localeCompare(b.name);
            });
    }, [activeDeck]);

    const renderContent = () => {
        switch(activeTab) {
            case 'COMICS': return <ComicArchive />;
            case 'INVENTORY': return <InventoryStash />;
            default:
                return (
                    <div className="flex flex-col h-full overflow-hidden">
                        {/* 1. DECK SELECTION & VAULT ZONE */}
                        <div 
                            ref={vaultRef}
                            className={`shrink-0 border-b border-slate-700/50 z-20 transition-all duration-300 ${dragState?.active && dragState.origin === 'archive' ? 'ring-2 ring-inset ring-indigo-500/50' : ''}`}
                            data-drop-zone="vault"
                        >
                            <DeckSelector 
                                activeDeckId={user.activeDeckId} 
                                onSelectDeck={setActiveDeck}
                            />

                            <div className="px-3 pb-2">
                                <DeckVault 
                                    cards={deckCards} 
                                    draggingCardId={dragState?.active && dragState.origin === 'vault' ? dragState.card.id : undefined}
                                    onPointerDown={(e, card) => handlePointerDown(e, card, 'vault')}
                                />
                            </div>
                        </div>

                        {/* 2. COLLECTION ARCHIVE */}
                        <div 
                            ref={archiveRef}
                            className={`flex-1 min-h-0 relative transition-all duration-300 ${dragState?.active && dragState.origin === 'vault' ? 'bg-indigo-500/5' : ''}`}
                            data-drop-zone="archive"
                        >
                            <CollectionGrid 
                                scrollRef={scrollRef}
                                ownedIds={user.collection}
                                activeDeckIds={activeDeck}
                                draggingCardId={dragState?.active && dragState.origin === 'archive' ? dragState.card.id : undefined}
                                onPointerDown={(e, card) => handlePointerDown(e, card, 'archive')}
                            />
                        </div>
                    </div>
                );
        }
    };

    return (
        <div className="w-full h-full flex flex-col bg-slate-950 overflow-hidden relative">
            <StandardHeader 
                title="COLLECTION" 
                className="!py-1.5"
                leftContent={
                    /* MASTERY HUD: Using the new HexBadge component */
                    <div className="flex items-center gap-2 ml-1 cursor-pointer group active:scale-95 transition-transform">
                        <HexBadge variant="primary" size="sm" glow className="group-hover:scale-110 transition-transform">
                            <span className="text-[0.6rem] mb-0.5">42</span>
                        </HexBadge>
                        <div className="flex flex-col">
                            <span className="text-[0.45rem] font-black text-indigo-400 uppercase leading-none tracking-widest">Mastery</span>
                            <span className="text-[0.6rem] font-black text-white italic tracking-tighter leading-none mt-0.5">RANK 1,402</span>
                        </div>
                    </div>
                }
                rightContent={
                    /* TAB SYSTEM: Far-right compact buttons */
                    <div className="flex items-center gap-1 mr-1">
                        <TabButton 
                            active={activeTab === 'CARDS'} 
                            onClick={() => setActiveTab('CARDS')}
                            icon={<svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" /></svg>}
                        />
                        <TabButton 
                            active={activeTab === 'COMICS'} 
                            onClick={() => setActiveTab('COMICS')}
                            icon={<svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" /></svg>}
                        />
                        <TabButton 
                            active={activeTab === 'INVENTORY'} 
                            onClick={() => setActiveTab('INVENTORY')}
                            icon={<svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4" /></svg>}
                        />
                    </div>
                }
            />

            <CollectionDragOverlay dragState={dragState} />

            <div className="flex-1 overflow-hidden">
                {renderContent()}
            </div>
        </div>
    );
};

const TabButton: React.FC<{ active: boolean; onClick: () => void; icon: React.ReactNode }> = ({ active, onClick, icon }) => (
    <button 
        onClick={onClick}
        className={`w-9 h-8 flex items-center justify-center rounded skew-x-[-12deg] transition-all duration-300 border-b-2 ${active ? 'bg-indigo-600 border-indigo-300 text-white shadow-[0_0_12px_rgba(79,70,229,0.4)] scale-105 z-10' : 'bg-slate-800 border-slate-700 text-slate-500 active:scale-95'}`}
    >
        <div className="skew-x-[12deg] flex items-center justify-center drop-shadow-md">
            {icon}
        </div>
    </button>
);

import React, { useMemo, useState, useEffect, useRef } from 'react';
