import React from 'react';
import { GameText } from './GameText';

type BadgeVariant = 'primary' | 'secondary' | 'success' | 'danger' | 'warning' | 'blue';

interface HexBadgeProps {
    children: React.ReactNode;
    variant?: BadgeVariant;
    size?: 'xs' | 'sm' | 'md' | 'lg' | 'xl';
    className?: string;
    glow?: boolean;
}

export const HexBadge: React.FC<HexBadgeProps> = ({ 
    children, 
    variant = 'primary', 
    size = 'md',
    className = '',
    glow = false
}) => {
    const variants = {
        primary: {
            fill: 'url(#badgeGradient)',
            stroke: 'stroke-indigo-300',
            text: 'text-white',
            glow: 'shadow-[0_0_15px_rgba(99,102,241,0.5)]'
        },
        secondary: {
            fill: 'fill-slate-900',
            stroke: 'stroke-slate-500',
            text: 'text-slate-300',
            glow: 'shadow-[0_0_15px_rgba(71,85,105,0.3)]'
        },
        success: {
            fill: 'fill-emerald-950',
            stroke: 'stroke-emerald-400',
            text: 'text-emerald-400',
            glow: 'shadow-[0_0_15px_rgba(52,211,153,0.4)]'
        },
        danger: {
            fill: 'fill-red-950',
            stroke: 'stroke-red-500',
            text: 'text-red-400',
            glow: 'shadow-[0_0_15px_rgba(248,113,113,0.4)]'
        },
        warning: {
            fill: 'fill-amber-950',
            stroke: 'stroke-amber-400',
            text: 'text-amber-400',
            glow: 'shadow-[0_0_15px_rgba(251,191,36,0.4)]'
        },
        blue: {
            fill: 'fill-blue-950',
            stroke: 'stroke-blue-400',
            text: 'text-blue-400',
            glow: 'shadow-[0_0_15px_rgba(96,165,250,0.4)]'
        }
    };

    const sizeConfigs = {
        xs: { box: 'w-5 h-5', fontSize: 12 },
        sm: { box: 'w-7 h-7', fontSize: 15 },
        md: { box: 'w-8 h-8', fontSize: 18 },
        lg: { box: 'w-11 h-11', fontSize: 26 },
        xl: { box: 'w-15 h-15', fontSize: 38 }
    };

    const config = variants[variant];
    const sizeConfig = sizeConfigs[size];

    return (
        <div className={`relative ${sizeConfig.box} flex items-center justify-center shrink-0 ${className}`}>
            {/* THE HEXAGON SVG BACKGROUND */}
            <svg 
                viewBox="0 0 100 100" 
                className={`absolute inset-0 w-full h-full drop-shadow-lg ${glow ? config.glow : ''}`}
            >
                <defs>
                    <linearGradient id="badgeGradient" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="0%" stopColor="#4f46e5" /> {/* indigo-600 */}
                        <stop offset="50%" stopColor="#6366f1" /> {/* indigo-500 */}
                        <stop offset="100%" stopColor="#a855f7" /> {/* purple-500 */}
                    </linearGradient>
                </defs>
                <path 
                    d="M50 2 L94 26 L94 74 L50 98 L6 74 L6 26 Z" 
                    fill={config.fill.startsWith('url') ? config.fill : undefined}
                    className={!config.fill.startsWith('url') ? `${config.fill} ${config.stroke} stroke-[4]` : `${config.stroke} stroke-[4]`}
                />

                <path 
                    d="M50 8 L88 30 L88 70 L50 92 L12 70 L12 30 Z" 
                    fill="white" 
                    fillOpacity="0.1"
                />
            </svg>

            {/* CONTENT LAYER */}
            <div className={`relative z-10 w-full h-full flex items-center justify-center pointer-events-none`}>
                <div className={`w-[70%] h-[70%] flex items-center justify-center`}>
                    {typeof children === 'string' || typeof children === 'number' ? (
                        <GameText 
                            text={children.toString()} 
                            baseFontSize={sizeConfig.fontSize}
                            className={`${config.text} font-black italic tracking-tighter uppercase drop-shadow-md`}
                        />
                    ) : (
                        <div className={`w-full h-full flex items-center justify-center ${config.text}`}>
                            {children}
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

import React, { useMemo, useState, useEffect, useRef } from 'react';
import { GameText } from '../ui/GameText';
import { SlantedButton } from '../ui/SlantedButton';
import { Card } from '../Card';
import { CARDS } from '../../constants';
import { useUser } from '../../contexts/UserContext';
import { HexBadge } from '../ui/HexBadge';

export const SeasonScreen: React.FC = () => {
    const { inspect } = useUser();
    const scrollContainerRef = useRef<HTMLDivElement>(null);
    const activeLevelRef = useRef<HTMLDivElement>(null);

    // Current user level for demo purposes
    const currentLevel = 24;
    const progressPercent = 80;
    const currentXP = 800;
    const targetXP = 1000;

    // Countdown Timer Logic
    const [timeLeft, setTimeLeft] = useState({ dd: '00', hh: '00', mm: '00', ss: '00' });

    useEffect(() => {
        const targetDate = new Date('2025-12-31T23:59:59').getTime();

        const updateTimer = () => {
            const now = new Date().getTime();
            const distance = targetDate - now;

            if (distance < 0) {
                setTimeLeft({ dd: '00', hh: '00', mm: '00', ss: '00' });
                return;
            }

            const days = Math.floor(distance / (1000 * 60 * 60 * 24));
            const hours = Math.floor((distance % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
            const minutes = Math.floor((distance % (1000 * 60 * 60)) / (1000 * 60));
            const seconds = Math.floor((distance % (1000 * 60)) / 1000);

            setTimeLeft({
                dd: String(days).padStart(2, '0'),
                hh: String(hours).padStart(2, '0'),
                mm: String(minutes).padStart(2, '0'),
                ss: String(seconds).padStart(2, '0')
            });
        };

        const interval = setInterval(updateTimer, 1000);
        updateTimer();
        return () => clearInterval(interval);
    }, []);

    // Auto-scroll logic: Center the active reward level on mount
    useEffect(() => {
        const timer = setTimeout(() => {
            if (activeLevelRef.current && scrollContainerRef.current) {
                const container = scrollContainerRef.current;
                const activeItem = activeLevelRef.current;
                const targetScroll = activeItem.offsetTop - (container.offsetHeight / 2) + (activeItem.offsetHeight / 2);
                container.scrollTo({ top: targetScroll, behavior: 'smooth' });
            }
        }, 600); // Wait for transition
        return () => clearTimeout(timer);
    }, [currentLevel]);

    const rewardList = useMemo(() => {
        return Array.from({ length: 100 }, (_, i) => {
            const level = i + 1;
            let title = '';
            let variant: 'blue' | 'warning' | 'primary' = 'blue';

            if (level % 10 === 0) {
                title = 'MEGA BOX';
                variant = 'primary';
            } else if (level % 5 === 0) {
                title = 'MYSTERY';
                variant = 'primary';
            } else if (level % 2 === 0) {
                title = '50 GOLD';
                variant = 'warning';
            } else {
                title = '100 CREDITS';
                variant = 'blue';
            }

            return {
                level,
                title,
                variant,
                isClaimed: level < currentLevel,
                isActive: level === currentLevel,
                isLocked: level > currentLevel
            };
        });
    }, [currentLevel]);

    const seasonCard = CARDS.find(c => c.id === 'c14') || CARDS[0];

    return (
        <div className="w-full h-full flex flex-col bg-slate-950 overflow-hidden relative font-sans">

            {/* 1. PRIMARY THEME HEADER */}
            <div className="shrink-0 flex flex-col bg-gradient-to-b from-slate-800 via-slate-900 to-slate-950 border-b border-slate-800 pt-1 pb-2 px-4 shadow-2xl z-40 relative">
                <div className="flex items-center justify-between">
                    <h1 className="text-[1rem] font-black text-white italic tracking-tighter uppercase drop-shadow-lg leading-none">
                        Space Pirates
                    </h1>
                    <div className="flex items-center gap-1.5 bg-indigo-600/30 border border-indigo-500/50 px-2.5 py-0.5 rounded-sm shadow-[0_0_10px_rgba(79,70,229,0.2)]">
                        <div className="w-1.5 h-1.5 rounded-full bg-indigo-400 animate-pulse" />
                        <span className="text-[0.6rem] font-black text-white italic tracking-tighter">PREMIUM</span>
                    </div>
                </div>

                <div className="flex items-center justify-between mt-1.5 px-0.5">
                    <div className="flex items-center gap-1.5">
                         <span className="text-[0.55rem] font-black text-slate-400 uppercase tracking-widest leading-none">
                            Dec 1 - Dec 31
                        </span>
                    </div>
                    <div className="flex items-center gap-1.5">
                        <span className="text-[0.45rem] font-black text-indigo-400 uppercase leading-none mr-0.5">ENDS IN:</span>
                        <span className="text-[0.65rem] font-black text-white italic tabular-nums leading-none tracking-tight">
                            {timeLeft.dd}:{timeLeft.hh}:{timeLeft.mm}:{timeLeft.ss}
                        </span>
                    </div>
                </div>
            </div>

            {/* 2. PROGRESS BAR SECTION */}
            <div className="shrink-0 bg-slate-950/80 border-b border-slate-800/60 px-8 py-3 z-30 shadow-md">
                <div className="flex justify-center items-end mb-2 px-1">
                    <span className="text-[0.6rem] font-black text-indigo-400 uppercase tracking-[0.2em] leading-none">Season Mastery</span>
                </div>

                <div className="relative w-full px-2">
                    {/* LEVEL BADGE: Overlapping the left edge - Size bumped to LG for bigger font */}
                    <div className="absolute left-[-1.1rem] top-1/2 -translate-y-1/2 z-20 scale-90">
                        <HexBadge variant="primary" size="lg" glow>
                            {currentLevel}
                        </HexBadge>
                    </div>

                    <div className="h-6 w-full bg-slate-900 rounded-full overflow-hidden border border-slate-800 shadow-inner p-[1px] relative">
                        <div 
                            className="h-full bg-gradient-to-r from-indigo-600 via-indigo-500 to-purple-500 rounded-full relative transition-all duration-1000 ease-out shadow-[0_0_15px_rgba(99,102,241,0.4)]"
                            style={{ width: `${progressPercent}%` }}
                        >
                            <div className="absolute inset-0 bg-white/10 animate-[pulse_2s_infinite]"></div>
                        </div>

                        <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                            <span className="text-[0.6rem] font-black text-white uppercase italic tracking-wider drop-shadow-[0_1px_2px_rgba(0,0,0,0.8)] ml-4">
                                {currentXP} / {targetXP} TO LEVEL {currentLevel + 1}
                            </span>
                        </div>
                    </div>
                </div>
            </div>

            {/* MAIN CONTENT AREA */}
            <div className="flex-1 flex flex-row overflow-hidden min-h-0 px-2 gap-x-5">

                {/* LEFT COLUMN: HERO CARD & CTA */}
                <div className="flex-1 flex flex-col items-center justify-center p-1 bg-gradient-to-r from-indigo-900/10 to-transparent border-r border-slate-900/50">

                    {/* CENTERED HERO WRAPPER - Raised by total 4rem (-mt-16) */}
                    <div className="flex flex-col items-center justify-center w-full max-w-[12rem] gap-y-4 -mt-16">
                        {/* 1. Centered Label - Switched to black shadow for pure white look */}
                        <div className="text-[0.7rem] font-black text-white uppercase tracking-[0.4em] drop-shadow-[0_2px_4px_rgba(0,0,0,0.9)] text-center leading-tight">
                            SEASON<br/>EXCLUSIVE
                        </div>

                        {/* 2. Hero Card Container */}
                        <div 
                            className="relative cursor-pointer scale-[0.65] origin-center my-[-2rem]"
                            onClick={() => inspect(seasonCard)}
                        >
                            {/* SUBTLE DARK BACKLIGHT GLOW */}
                            <div className="absolute inset-0 -inset-x-32 -inset-y-48 bg-indigo-500/20 blur-[100px] rounded-full pointer-events-none" />
                            <div className="absolute inset-0 -inset-x-24 -inset-y-36 bg-purple-600/15 blur-[70px] rounded-full pointer-events-none" />
                            <div className="absolute inset-0 -inset-x-12 -inset-y-20 bg-white/5 blur-[40px] rounded-full pointer-events-none" />

                            <div className="relative z-10 drop-shadow-[0_0_2rem_rgba(79,70,229,0.4)] active:scale-95 transition-transform">
                                {/* CUSTOM WHITE BORDER OVERLAY - Applied directly to match MD size rounded-md */}
                                <div className="absolute inset-0 border-2 border-white rounded-md z-20 pointer-events-none shadow-[0_0_10px_rgba(255,255,255,0.5)]"></div>
                                <Card card={seasonCard} size="md" />
                            </div>
                        </div>

                        {/* 3. Centered GO PREMIUM Button - Increased font size further */}
                        <div className="w-full flex justify-center">
                            <SlantedButton variant="warning" size="sm" className="w-20 !h-6 shadow-[0_3px_8px_rgba(180,83,9,0.3)] !px-0">
                                <span className="text-[0.75rem] font-black tracking-tight">GO PREMIUM</span>
                            </SlantedButton>
                        </div>
                    </div>

                </div>

                {/* RIGHT COLUMN: REWARD TRACK (Constrained to 40% width) */}
                <div className="w-[40%] flex flex-col bg-slate-900/20">
                    <div 
                        ref={scrollContainerRef}
                        className="flex-1 overflow-y-auto px-1 py-4 space-y-3 scrollbar-hide pb-24"
                    >
                        {rewardList.map((reward) => (
                            <div 
                                key={reward.level} 
                                ref={reward.isActive ? activeLevelRef : null}
                                className="h-12 w-full relative group"
                            >
                                <SlantedButton 
                                    variant={reward.isClaimed ? 'secondary' : reward.variant}
                                    fullWidth 
                                    size="md"
                                    className={`!h-full transition-all duration-300 ${reward.isClaimed ? 'opacity-30 grayscale' : ''} ${reward.isActive ? 'scale-[1.02] z-10 shadow-[0_0_15px_rgba(99,102,241,0.3)]' : ''}`}
                                    disabled={reward.isLocked || reward.isClaimed}
                                >
                                    <div className="flex items-center w-full h-full">
                                        <div className="w-10 h-full flex flex-col items-center justify-center border-r border-white/5 shrink-0 bg-black/10">
                                            <span className="text-[0.4rem] font-black opacity-60 uppercase leading-none">LVL</span>
                                            <span className="text-sm font-black italic tabular-nums leading-none">{reward.level}</span>
                                        </div>

                                        <div className="flex-1 px-2.5 text-left overflow-hidden">
                                            <span className="text-[0.7rem] font-black italic uppercase tracking-tight truncate block">
                                                {reward.title}
                                            </span>
                                        </div>
                                    </div>
                                </SlantedButton>

                                {reward.isClaimed && (
                                    <div className="absolute inset-0 flex items-center justify-center pointer-events-none overflow-hidden rounded z-20">
                                        {/* Updated: Colorful Gradient 'CLAIMED' banner */}
                                        <div className="bg-gradient-to-r from-emerald-500 via-teal-400 to-cyan-500 text-white text-[0.6rem] font-black uppercase tracking-[0.2em] px-12 py-1.5 rotate-[-12deg] border-y-2 border-white/30 shadow-2xl backdrop-blur-sm drop-shadow-lg">
                                            CLAIMED
                                        </div>
                                    </div>
                                )}

                                {reward.isLocked && (
                                    <div className="absolute right-2 top-1/2 -translate-y-1/2 opacity-20 pointer-events-none z-20">
                                        <svg className="w-3 h-3 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" />
                                        </svg>
                                    </div>
                                )}
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        </div>
    );
};

