                                        <div className="bg-gradient-to-r from-emerald-300/90 via-cyan-200/90 to-blue-300/90 text-slate-900 text-[0.45rem] font-black uppercase tracking-[0.25em] px-10 py-0 rotate-[-12deg] border-y border-white/60 shadow-xl backdrop-blur-[2px] drop-shadow-md">
                                            CLAIMED
                                        </div>
                                    </div>
