import React from 'react';
import { CardInstance, CardDefinition } from '../types';
import { CardBoardView } from './card/CardBoardView';
import { CardFullArtView } from './card/CardFullArtView';
import { CardStandardView } from './card/CardStandardView';
import { CardThumbnailView } from './card/CardThumbnailView';
import { useCardStats } from '../hooks/useCardStats';

interface CardProps {
  card: CardInstance | CardDefinition;
  onClick?: () => void;
  isPlayable?: boolean;
  isSelected?: boolean;
  size?: 'xs' | 'sm' | 'md' | 'lg';
  variant?: 'default' | 'board' | 'thumbnail';
  hidden?: boolean;
  onPointerDown?: (e: React.PointerEvent) => void;
  isDragging?: boolean;
  borderColor?: string;
}

const CardComponent: React.FC<CardProps> = ({ 
  card, 
  onClick, 
  size = 'md', 
  variant = 'default', 
  hidden, 
  onPointerDown,
  isDragging,
  borderColor: borderColorOverride
}) => {
  const sizeClasses = {
    xs: 'w-full aspect-[5/7] text-[0.45rem] rounded-md border overflow-hidden', 
    sm: 'w-24 aspect-[5/7] text-[0.55rem] rounded-md border-2 overflow-hidden',
    md: 'w-32 aspect-[5/7] text-[0.65rem] rounded-md border-2 overflow-hidden',
    lg: 'w-52 aspect-[5/7] text-lg rounded-xl border-4 overflow-hidden', 
  };
  const currentSizeClass = sizeClasses[size];

  if (hidden) {
    return (
      <div 
          role="presentation"
          className={`${currentSizeClass} bg-indigo-900 border-indigo-400 shadow-md flex items-center justify-center relative pointer-events-auto`}
          onClick={onClick}
          onPointerDown={onPointerDown}
      >
          <div className="w-1/3 h-1/3 rounded-full bg-indigo-500 animate-pulse"></div>
      </div>
    );
  }

  const { 
    currentDisplayPower, currentDisplayCost, 
    powerColor, costColor, def, borderColor: hookBorderColor 
  } = useCardStats(card);

  const borderColor = borderColorOverride || hookBorderColor;
  const opacityClass = isDragging ? 'opacity-0 pointer-events-none' : 'opacity-100';
  const cursorClass = onPointerDown || onClick ? 'cursor-grab active:cursor-grabbing' : '';
  const borderClass = size === 'xs' ? 'border' : (size === 'lg' ? 'border-4' : 'border-2');

  const sharedProps = {
    def, borderColor, borderClass, opacityClass, cursorClass, size,
    currentDisplayCost, currentDisplayPower, costColor, powerColor,
    onPointerDown, onClick
  };

  if (variant === 'thumbnail') {
    return <CardThumbnailView {...sharedProps} />;
  }

  if (variant === 'board') {
    return <CardBoardView {...sharedProps} />;
  }

  if (size === 'lg') {
    return <CardFullArtView
      def={def}
      borderColor={borderColor}
      opacityClass={opacityClass}
      size={size}
      currentDisplayCost={currentDisplayCost}
      currentDisplayPower={currentDisplayPower}
      costColor={costColor}
      powerColor={powerColor}
      currentSizeClass={currentSizeClass}
    />;
  }

  return <CardStandardView {...sharedProps} currentSizeClass={currentSizeClass} />;
};

export const Card = React.memo(CardComponent, (prev, next) => {
    if (prev.size !== next.size || prev.variant !== next.variant || prev.isDragging !== next.isDragging || prev.hidden !== next.hidden || prev.borderColor !== next.borderColor) return false;
    const isInstance = (c: any): c is CardInstance => c && 'instanceId' in c;
    if (isInstance(prev.card) && isInstance(next.card)) {
        return prev.card.instanceId === next.card.instanceId && 
               prev.card.totalPower === next.card.totalPower && 
               prev.card.totalCost === next.card.totalCost &&
               prev.card.faceUp === next.card.faceUp;
    }

    const getDefinitionId = (card: CardInstance | CardDefinition) => 
        isInstance(card) ? card.definitionId : card.id;

    return getDefinitionId(prev.card) === getDefinitionId(next.card);
});

