import React, { useState, useEffect } from 'react';
import { useUser } from '../contexts/UserContext';
import { CardInstance, CardDefinition, CardRarity } from '../types';
import { Card } from './Card';
import { LocationCard } from './LocationCard';
import { StatHistory } from './inspector/StatHistory';
import { KeywordText } from './ui/KeywordText';
import { SlantedButton } from './ui/SlantedButton';
import { CreditIcon, GoldIcon } from './ui/CurrencyIcons';

export const InspectorOverlay: React.FC = () => {
    const { 
        user,
        inspectingCard, 
        inspectingLocation, 
        inspectingCurrency,
        inspectingBox,
        upgradeCard,
        closeInspector 
    } = useUser();

    /**
     * CRITICAL BUG PREVENTION: This 150ms interaction lockout is mandatory for 100% tap reliability.
     */
    const [isInteractionEnabled, setIsInteractionEnabled] = useState(false);

    useEffect(() => {
        if (inspectingCard || inspectingLocation || inspectingCurrency || inspectingBox) {
            const timer = setTimeout(() => setIsInteractionEnabled(true), 150);
            return () => clearTimeout(timer);
        } else {
            setIsInteractionEnabled(false);
        }
    }, [inspectingCard, inspectingLocation, inspectingCurrency, inspectingBox]);

    if (!inspectingCard && !inspectingLocation && !inspectingCurrency && !inspectingBox) return null;

    const isInstance = (c: any): c is CardInstance => c && 'instanceId' in c;

    const getDef = (): CardDefinition | null => {
        if (!inspectingCard) return null;
        return isInstance(inspectingCard) ? inspectingCard.def : inspectingCard as CardDefinition;
    };

    const def = getDef();

    const isOwned = def ? user.collection.includes(def.id) : false;
    const currentRarity = def ? (user.cardRarities[def.id] || def.rarity) : "Common";
    const rarityPath: CardRarity[] = ["Common", "Rare", "Epic", "Legendary"];
    const nextRarity = rarityPath[rarityPath.indexOf(currentRarity) + 1];
    const costMap: Record<string, number> = { "Rare": 100, "Epic": 400, "Legendary": 1000 };
    const upgradeCost = nextRarity ? costMap[nextRarity] : null;

    const handleBackgroundClick = (e: React.MouseEvent) => {
        if (isInteractionEnabled) {
            closeInspector();
        }
    };

    return (
        <div 
            className="fixed inset-0 z-[500] bg-black/40 backdrop-blur-sm flex flex-col items-center justify-center p-6 animate-pop overflow-y-auto"
            onClick={handleBackgroundClick}
        >
            {/* BOX INSPECTOR */}
            {inspectingBox && (
                <div 
                    className="flex flex-col items-center animate-pop max-w-[18rem]"
                    onClick={(e) => e.stopPropagation()}
                >
                    <div className="relative mb-8 group">
                         {/* Ambient Glow */}
                         <div className={`absolute inset-0 blur-[50px] opacity-40 rounded-full ${inspectingBox.boxType === 'MEGA' ? 'bg-amber-400' : 'bg-indigo-400'}`} />

                         {/* 3D Box Visual */}
                         <div className={`w-32 h-32 relative preserve-3d transition-transform duration-1000 animate-[spin_10s_linear_infinite]`}>
                            <div className={`absolute inset-0 border-4 rounded-xl flex items-center justify-center shadow-2xl backdrop-blur-md ${inspectingBox.boxType === 'MEGA' ? 'bg-gradient-to-br from-amber-600 to-amber-900 border-amber-400 shadow-amber-500/20' : 'bg-gradient-to-br from-indigo-600 to-indigo-900 border-indigo-400 shadow-indigo-500/20'}`}>
                                <span className="text-4xl font-black text-white italic drop-shadow-lg">?</span>
                            </div>
                         </div>
                    </div>

                    <div className="text-center">
                        <h2 className="text-3xl font-black text-white italic tracking-tighter mb-2 uppercase leading-none">
                            {inspectingBox.title}
                        </h2>
                        <div className="w-full h-px bg-white/10 mb-3 mx-auto max-w-[10rem]" />
                        <p className="text-indigo-200/80 font-medium text-xs leading-relaxed px-4">
                            {inspectingBox.description}
                        </p>
                    </div>
                </div>
            )}

            {/* CARD INSPECTOR */}
            {inspectingCard && def && (
                <div 
                    className="flex flex-col items-center w-full max-w-[13rem]"
                    onClick={(e) => e.stopPropagation()} 
                > 
                    <div className="relative z-40 mb-5 shadow-[0_0_3rem_rgba(0,0,0,0.8)]">
                        {isInstance(inspectingCard) && (
                            <>
                                <StatHistory modifiers={inspectingCard.costModifiers} type="cost" side="left" />
                                <StatHistory modifiers={inspectingCard.powerModifiers} type="power" side="right" />
                            </>
                        )}
                        <Card 
                            card={{ ...def, rarity: currentRarity }} 
                            size="lg" 
                            borderColor={!isOwned ? 'border-white' : undefined}
                        />
                    </div>

                    <div className="w-full text-center mb-4 px-1">
                         <KeywordText className="text-[0.7rem]" text={isInstance(inspectingCard) ? inspectingCard.currentText : def.baseText} />
                    </div>

                    {!isInstance(inspectingCard) && nextRarity && (
                        <div className="w-full mb-4">
                            <SlantedButton 
                                variant="success" 
                                fullWidth 
                                size="sm"
                                onClick={() => upgradeCard(def.id)}
                                disabled={user.credits < (upgradeCost || 0)}
                            >
                                <div className="flex items-center justify-center gap-2">
                                    <div className="flex flex-col items-start leading-none">
                                        <span className="text-[0.45rem] opacity-70">UPGRADE TO</span>
                                        <span className="text-[0.6rem]">{nextRarity.toUpperCase()}</span>
                                    </div>
                                    <div className="h-4 w-px bg-white/20"></div>
                                    <span className="text-xs">{upgradeCost} CREDITS</span>
                                </div>
                            </SlantedButton>
                        </div>
                    )}

                    {def.flavorText && (
                        <div className="w-full bg-slate-900/60 border border-slate-800 rounded-lg p-2 min-h-[2.5rem] flex flex-col items-center justify-center relative group overflow-hidden">
                            <p className="text-[0.55rem] text-indigo-200/70 italic leading-tight font-mono text-center px-1">
                                "{def.flavorText}"
                            </p>
                        </div>
                    )}
                </div>
            )}

            {/* LOCATION INSPECTOR */}
            {inspectingLocation && (
                <div 
                    className="relative z-40 animate-pop drop-shadow-2xl max-w-[20rem]"
                    onClick={(e) => e.stopPropagation()}
                >
                    <LocationCard location={inspectingLocation} size="lg" />
                </div>
            )}

            {/* CURRENCY INSPECTOR */}
            {inspectingCurrency && (
                <div 
                    className="flex flex-col items-center animate-pop"
                    onClick={(e) => e.stopPropagation()}
                >
                    <div className={`w-24 h-24 rounded-full flex items-center justify-center border-4 shadow-[0_0_3rem_rgba(0,0,0,0.5)] mb-8 ${inspectingCurrency.type === 'gold' ? 'bg-amber-500/10 border-amber-500/40' : 'bg-blue-500/10 border-blue-500/40'}`}>
                        {inspectingCurrency.type === 'gold' ? (
                            <GoldIcon size="lg" animate />
                        ) : (
                            <CreditIcon size="lg" />
                        )}
                    </div>
                    <div className="text-center">
                        <h2 className="text-4xl font-black text-white italic tracking-tighter mb-2 uppercase leading-none">
                            {inspectingCurrency.amount.toLocaleString()} {inspectingCurrency.type}
                        </h2>
                        <div className="w-full h-px bg-white/10 mb-3 mx-auto max-w-[10rem]" />
                        <p className="text-slate-400 font-bold text-[0.6rem] uppercase tracking-[0.2em]">
                            Available Balance
                        </p>
                    </div>
                </div>
            )}

            <div className="fixed bottom-8 text-slate-400 font-black text-[0.5rem] uppercase tracking-[0.4em] animate-pulse drop-shadow-[0_2px_4px_rgba(0,0,0,1)]">
                Tap anywhere to close
            </div>

            <style>{`
                .preserve-3d { transform-style: preserve-3d; }
            `}</style>
        </div>
    );
};

import React from 'react';
