import React from 'react';
import { GameText } from './GameText';

type BadgeVariant = 'primary' | 'secondary' | 'success' | 'danger' | 'warning' | 'blue';

interface HexBadgeProps {
    children: React.ReactNode;
    variant?: BadgeVariant;
    size?: 'xs' | 'sm' | 'md' | 'lg' | 'xl';
    className?: string;
    glow?: boolean;
}

export const HexBadge: React.FC<HexBadgeProps> = ({ 
    children, 
    variant = 'primary', 
    size = 'md',
    className = '',
    glow = false
}) => {
    const variants = {
        primary: {
            fill: 'url(#bg_primary)',
            stroke: '#6366f1', // indigo-500
            innerStroke: '#a5b4fc', // indigo-300
            text: 'text-white',
            glowColor: 'rgba(99, 102, 241, 0.7)'
        },
        secondary: {
            fill: 'url(#bg_secondary)',
            stroke: '#475569', // slate-600
            innerStroke: '#94a3b8', // slate-400
            text: 'text-slate-200',
            glowColor: 'rgba(148, 163, 184, 0.35)'
        },
        success: {
            fill: 'url(#bg_success)',
            stroke: '#10b981', // emerald-500
            innerStroke: '#6ee7b7', // emerald-300
            text: 'text-white',
            glowColor: 'rgba(16, 185, 129, 0.6)'
        },
        danger: {
            fill: 'url(#bg_danger)',
            stroke: '#ef4444', // red-500
            innerStroke: '#fca5a5', // red-300
            text: 'text-white',
            glowColor: 'rgba(239, 68, 68, 0.6)'
        },
        warning: {
            fill: 'url(#bg_warning)',
            stroke: '#f59e0b', // amber-500
            innerStroke: '#fcd34d', // amber-300
            text: 'text-white',
            glowColor: 'rgba(245, 158, 11, 0.7)'
        },
        blue: {
            fill: 'url(#bg_blue)',
            stroke: '#3b82f6', // blue-500
            innerStroke: '#93c5fd', // blue-300
            text: 'text-white',
            glowColor: 'rgba(59, 130, 246, 0.6)'
        }
    };

    const sizeConfigs = {
        xs: { box: 'w-5 h-5', fontSize: 13, strokeWidth: 10 },
        sm: { box: 'w-7.5 h-7.5', fontSize: 17, strokeWidth: 9 },
        md: { box: 'w-10 h-10', fontSize: 22, strokeWidth: 8 },
        lg: { box: 'w-13 h-13', fontSize: 30, strokeWidth: 7 },
        xl: { box: 'w-18 h-18', fontSize: 44, strokeWidth: 5 }
    };

    const v = variants[variant];
    const s = sizeConfigs[size];

    return (
        <div className={`relative ${s.box} flex items-center justify-center shrink-0 drop-shadow-[0_3px_6px_rgba(0,0,0,0.6)] ${className}`}>
            <svg 
                viewBox="0 0 100 100" 
                className="absolute inset-0 w-full h-full overflow-visible"
                style={glow ? { filter: `drop-shadow(0 0 10px ${v.glowColor})` } : {}}
            >
                <defs>
                    <linearGradient id="bg_primary" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="0%" stopColor="#4338ca" /><stop offset="100%" stopColor="#1e1b4b" />
                    </linearGradient>
                    <linearGradient id="bg_secondary" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="0%" stopColor="#334155" /><stop offset="100%" stopColor="#0f172a" />
                    </linearGradient>
                    <linearGradient id="bg_success" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="0%" stopColor="#059669" /><stop offset="100%" stopColor="#064e3b" />
                    </linearGradient>
                    <linearGradient id="bg_danger" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="0%" stopColor="#dc2626" /><stop offset="100%" stopColor="#7f1d1d" />
                    </linearGradient>
                    <linearGradient id="bg_warning" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="0%" stopColor="#d97706" /><stop offset="100%" stopColor="#78350f" />
                    </linearGradient>
                    <linearGradient id="bg_blue" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="0%" stopColor="#2563eb" /><stop offset="100%" stopColor="#1e3a8a" />
                    </linearGradient>

                    <clipPath id="hexClip">
                        <path d="M50 2 L95 25 L95 75 L50 98 L5 75 L5 25 Z" />
                    </clipPath>

                    <filter id="innerShadow">
                        <feComponentTransfer in="SourceAlpha">
                            <feFuncA type="table" tableValues="1 0" />
                        </feComponentTransfer>
                        <feGaussianBlur stdDeviation="2.5" />
                        <feOffset dx="0" dy="1.5" result="offsetblur" />
                        <feFlood floodColor="black" floodOpacity="0.7" />
                        <feComposite in2="offsetblur" operator="in" />
                        <feComposite in2="SourceAlpha" operator="in" />
                        <feMerge>
                            <feMergeNode />
                            <feMergeNode in="SourceGraphic" />
                        </feMerge>
                    </filter>
                </defs>

                {/* 1. Base Drop Shadow */}
                <path 
                    d="M50 2 L95 25 L95 75 L50 98 L5 75 L5 25 Z" 
                    fill="black" 
                    fillOpacity="0.25" 
                    transform="translate(0, 2.5)"
                />

                {/* 2. Main Background Fill with Inner Shadow */}
                <path 
                    d="M50 2 L95 25 L95 75 L50 98 L5 75 L5 25 Z" 
                    fill={v.fill}
                    filter="url(#innerShadow)"
                />

                {/* 3. Balanced Outer Bezel */}
                <path 
                    d="M50 2 L95 25 L95 75 L50 98 L5 75 L5 25 Z" 
                    fill="none" 
                    stroke={v.stroke} 
                    strokeWidth={s.strokeWidth} 
                    strokeLinejoin="round"
                />

                {/* 4. Specular Inner Edge */}
                <path 
                    d="M50 5 L91 26 L91 74 L50 95 L9 74 L9 26 Z" 
                    fill="none" 
                    stroke={v.innerStroke} 
                    strokeWidth="1.8" 
                    opacity="0.5"
                    strokeLinejoin="round"
                />

                {/* 5. Glass Gloss Overlay */}
                <path 
                    d="M-20 42 L120 -18 L120 42 L-20 102 Z" 
                    fill="white" 
                    fillOpacity="0.1" 
                    clipPath="url(#hexClip)"
                    pointerEvents="none"
                />
            </svg>

            {/* CONTENT LAYER */}
            <div className="relative z-10 w-full h-full flex items-center justify-center pointer-events-none">
                <div className="w-[82%] h-[82%] flex items-center justify-center">
                    {typeof children === 'string' || typeof children === 'number' ? (
                        <GameText 
                            text={children.toString()} 
                            baseFontSize={s.fontSize}
                            className={`${v.text} font-black italic tracking-tighter uppercase drop-shadow-[0_2px_3px_rgba(0,0,0,0.85)]`}
                        />
                    ) : (
                        <div className={`w-full h-full flex items-center justify-center ${v.text}`}>
                            {children}
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

import React, { useMemo, useState, useEffect, useRef } from 'react';
import { GameText } from '../ui/GameText';
import { SlantedButton } from '../ui/SlantedButton';
import { Card } from '../Card';
import { CARDS } from '../../constants';
import { useUser } from '../../contexts/UserContext';
import { HexBadge } from '../ui/HexBadge';
import { Portal } from '../ui/Portal';

export const SeasonScreen: React.FC = () => {
    const { inspect } = useUser();
    const scrollContainerRef = useRef<HTMLDivElement>(null);
    const activeLevelRef = useRef<HTMLDivElement>(null);

    // UI State for the Premium Modal
    const [showPremiumModal, setShowPremiumModal] = useState(false);

    // Current user level for demo purposes
    const currentLevel = 24;
    const progressPercent = 80;
    const currentXP = 800;
    const targetXP = 1000;

    // Countdown Timer Logic
    const [timeLeft, setTimeLeft] = useState({ dd: '00', hh: '00', mm: '00', ss: '00' });

    useEffect(() => {
        const targetDate = new Date('2025-12-31T23:59:59').getTime();

        const updateTimer = () => {
            const now = new Date().getTime();
            const distance = targetDate - now;

            if (distance < 0) {
                setTimeLeft({ dd: '00', hh: '00', mm: '00', ss: '00' });
                return;
            }

            const days = Math.floor(distance / (1000 * 60 * 60 * 24));
            const hours = Math.floor((distance % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
            const minutes = Math.floor((distance % (1000 * 60 * 60)) / (1000 * 60));
            const seconds = Math.floor((distance % (1000 * 60)) / 1000);

            setTimeLeft({
                dd: String(days).padStart(2, '0'),
                hh: String(hours).padStart(2, '0'),
                mm: String(minutes).padStart(2, '0'),
                ss: String(seconds).padStart(2, '0')
            });
        };

        const interval = setInterval(updateTimer, 1000);
        updateTimer();
        return () => clearInterval(interval);
    }, []);

    // Auto-scroll logic: Center the active reward level on mount
    useEffect(() => {
        const timer = setTimeout(() => {
            if (activeLevelRef.current && scrollContainerRef.current) {
                const container = scrollContainerRef.current;
                const activeItem = activeLevelRef.current;
                const targetScroll = activeItem.offsetTop - (container.offsetHeight / 2) + (activeItem.offsetHeight / 2);
                container.scrollTo({ top: targetScroll, behavior: 'smooth' });
            }
        }, 600); // Wait for transition
        return () => clearTimeout(timer);
    }, [currentLevel]);

    const rewardList = useMemo(() => {
        return Array.from({ length: 100 }, (_, i) => {
            const level = i + 1;
            let title = '';
            let variant: 'blue' | 'warning' | 'primary' = 'blue';
            let data: any = null;

            if (level % 10 === 0) {
                title = 'MEGA BOX';
                variant = 'primary';
                data = { type: 'box', boxType: 'MEGA', title: 'MEGA BOX', description: 'Contains a guaranteed Legendary card variant and 1000 Credits.' };
            } else if (level % 5 === 0) {
                title = 'MYSTERY';
                variant = 'primary';
                data = { type: 'box', boxType: 'MYSTERY', title: 'MYSTERY BOX', description: 'Contains a random Rare card or 500 Credits.' };
            } else if (level % 2 === 0) {
                title = '50 GOLD';
                variant = 'warning';
                data = { type: 'gold', amount: 50 };
            } else {
                title = '100 CREDITS';
                variant = 'blue';
                data = { type: 'credits', amount: 100 };
            }

            return {
                level,
                title,
                variant,
                data,
                isClaimed: level < currentLevel,
                isActive: level === currentLevel,
                isLocked: level > currentLevel
            };
        });
    }, [currentLevel]);

    const seasonCard = CARDS.find(c => c.id === 'c14') || CARDS[0];

    return (
        <div className="w-full h-full flex flex-col bg-transparent overflow-hidden relative font-sans">

            {/* 1. SEMI-TRANSPARENT THEME HEADER */}
            <div className="shrink-0 flex flex-col bg-slate-900/40 backdrop-blur-md border-b border-slate-800/50 pt-1 pb-2 px-4 shadow-2xl z-40 relative">
                <div className="flex items-center justify-between">
                    <h1 className="text-[1rem] font-black text-white italic tracking-tighter uppercase drop-shadow-lg leading-none">
                        Space Pirates
                    </h1>
                    <div className="flex items-center gap-1.5 bg-indigo-600/40 border border-indigo-500/50 px-2.5 py-0.5 rounded-sm shadow-[0_0_10px_rgba(79,70,229,0.2)]">
                        <div className="w-1.5 h-1.5 rounded-full bg-indigo-400 animate-pulse" />
                        <span className="text-[0.6rem] font-black text-white italic tracking-tighter">PREMIUM</span>
                    </div>
                </div>

                <div className="flex items-center justify-between mt-1.5 px-0.5">
                    <div className="flex items-center gap-1.5">
                         <span className="text-[0.55rem] font-black text-slate-400 uppercase tracking-widest leading-none">
                            Dec 1 - Dec 31
                        </span>
                    </div>
                    <div className="flex items-center gap-1.5">
                        <span className="text-[0.45rem] font-black text-indigo-400 uppercase leading-none mr-0.5">ENDS IN:</span>
                        <span className="text-[0.65rem] font-black text-white italic tabular-nums leading-none tracking-tight">
                            {timeLeft.dd}:{timeLeft.hh}:{timeLeft.mm}:{timeLeft.ss}
                        </span>
                    </div>
                </div>
            </div>

            {/* 2. PROGRESS BAR SECTION */}
            <div className="shrink-0 bg-slate-950/20 backdrop-blur-sm border-b border-slate-800/30 px-8 py-3 z-30 shadow-md">
                <div className="flex justify-center items-end mb-2 px-1">
                    <span className="text-[0.6rem] font-black text-indigo-200 uppercase tracking-[0.2em] leading-none drop-shadow-[0_0_5px_rgba(165,180,252,0.4)]">Season Mastery</span>
                </div>

                <div className="relative w-full px-2">
                    {/* LEVEL BADGE - Reduced from md to sm and adjusted left position */}
                    <div className="absolute left-[-0.75rem] top-1/2 -translate-y-1/2 z-20">
                        <HexBadge variant="primary" size="sm" glow>
                            {currentLevel}
                        </HexBadge>
                    </div>

                    <div className="h-6 w-full bg-slate-900/60 rounded-full overflow-hidden border border-slate-800/80 shadow-inner p-[1px] relative">
                        <div 
                            className="h-full bg-gradient-to-r from-indigo-600 via-indigo-500 to-purple-500 rounded-full relative transition-all duration-1000 ease-out shadow-[0_0_15px_rgba(99,102,241,0.4)]"
                            style={{ width: `${progressPercent}%` }}
                        >
                            <div className="absolute inset-0 bg-white/10 animate-[pulse_2s_infinite]"></div>
                        </div>

                        <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                            <span className="text-[0.6rem] font-black text-white uppercase italic tracking-wider drop-shadow-[0_1px_2px_rgba(0,0,0,0.8)] ml-2">
                                {currentXP} / {targetXP} TO LEVEL {currentLevel + 1}
                            </span>
                        </div>
                    </div>
                </div>
            </div>

            {/* MAIN CONTENT AREA */}
            <div className="flex-1 flex-row overflow-hidden min-h-0 px-2 flex gap-x-5">

                {/* LEFT COLUMN: HERO CARD & CTA */}
                <div className="flex-1 flex flex-col items-center justify-center p-1 border-r border-slate-900/20">

                    {/* CENTERED HERO WRAPPER */}
                    <div className="flex flex-col items-center justify-center w-full max-w-[12rem] gap-y-4 -mt-16">
                        {/* 1. Centered Super-White Radiant Label */}
                        <div className="h-10 w-full opacity-100">
                            <GameText 
