    const sizeConfigs = {
        // Recalibrated: "Refined Standard" sizes (Restored from the double-shrink)
        xs: { box: 'w-[1.25rem] h-[1.25rem]', fontSize: 13, strokeWidth: 11 },
        sm: { box: 'w-[1.8rem] h-[1.8rem]', fontSize: 18, strokeWidth: 9 },
