type BadgeVariant = 'primary' | 'secondary' | 'success' | 'danger' | 'warning' | 'blue';

interface HexBadgeProps {
    children: React.ReactNode;
    variant?: BadgeVariant;
    size?: 'xs' | 'sm' | 'md' | 'lg' | 'xl';
    className?: string;
    glow?: boolean;
}

export const HexBadge: React.FC<HexBadgeProps> = ({ 
    children, 
    variant = 'primary', 
    size = 'md',
    className = '',
    glow = false
}) => {
    const variants = {
        primary: {
            fill: 'url(#bg_primary)',
            stroke: '#6366f1', // indigo-500
            innerStroke: '#a5b4fc', // indigo-300
            text: 'text-white',
            glowColor: 'rgba(99, 102, 241, 0.7)'
        },
        secondary: {
            fill: 'url(#bg_secondary)',
            stroke: '#475569', // slate-600
            innerStroke: '#94a3b8', // slate-400
            text: 'text-slate-200',
            glowColor: 'rgba(148, 163, 184, 0.35)'
        },
        success: {
            fill: 'url(#bg_success)',
            stroke: '#10b981', // emerald-500
            innerStroke: '#6ee7b7', // emerald-300
            text: 'text-white',
            glowColor: 'rgba(16, 185, 129, 0.6)'
        },
        danger: {
            fill: 'url(#bg_danger)',
            stroke: '#ef4444', // red-500
            innerStroke: '#fca5a5', // red-300
            text: 'text-white',
            glowColor: 'rgba(239, 68, 68, 0.6)'
        },
        warning: {
            fill: 'url(#bg_warning)',
            stroke: '#f59e0b', // amber-500
            innerStroke: '#fcd34d', // amber-300
            text: 'text-white',
            glowColor: 'rgba(245, 158, 11, 0.7)'
        },
        blue: {
            fill: 'url(#bg_blue)',
            stroke: '#3b82f6', // blue-500
            innerStroke: '#93c5fd', // blue-300
            text: 'text-white',
            glowColor: 'rgba(59, 130, 246, 0.6)'
        }
    };

    const sizeConfigs = {
        // Recalibrated: "Refined Standard" sizes
        xs: { box: 'w-[1.25rem] h-[1.25rem]', fontSize: 13, strokeWidth: 11 },
        sm: { box: 'w-[2.0rem] h-[2.0rem]', fontSize: 20, strokeWidth: 9 }, // Increased by ~10% from 1.8rem
        md: { box: 'w-[2.4rem] h-[2.4rem]', fontSize: 24, strokeWidth: 8 },
        lg: { box: 'w-[3.2rem] h-[3.2rem]', fontSize: 32, strokeWidth: 7 },
        xl: { box: 'w-[4.8rem] h-[4.8rem]', fontSize: 46, strokeWidth: 5 }
    };

    const v = variants[variant];
    const s = sizeConfigs[size];

    return (
        <div className={`relative ${s.box} flex items-center justify-center shrink-0 drop-shadow-[0_2px_4px_rgba(0,0,0,0.6)] ${className}`}>
            <svg 
                viewBox="0 0 100 100" 
                className="absolute inset-0 w-full h-full overflow-visible"
                style={glow ? { filter: `drop-shadow(0 0 10px ${v.glowColor})` } : {}}
            >
                <defs>
                    <linearGradient id="bg_primary" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="0%" stopColor="#4338ca" /><stop offset="100%" stopColor="#1e1b4b" />
                    </linearGradient>
                    <linearGradient id="bg_secondary" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="0%" stopColor="#334155" /><stop offset="100%" stopColor="#0f172a" />
                    </linearGradient>
                    <linearGradient id="bg_success" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="0%" stopColor="#059669" /><stop offset="100%" stopColor="#064e3b" />
                    </linearGradient>
                    <linearGradient id="bg_danger" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="0%" stopColor="#dc2626" /><stop offset="100%" stopColor="#7f1d1d" />
                    </linearGradient>
                    <linearGradient id="bg_warning" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="0%" stopColor="#d97706" /><stop offset="100%" stopColor="#78350f" />
                    </linearGradient>
                    <linearGradient id="bg_blue" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="0%" stopColor="#2563eb" /><stop offset="100%" stopColor="#1e3a8a" />
                    </linearGradient>

                    <clipPath id="hexClip">
                        <path d="M50 2 L95 25 L95 75 L50 98 L5 75 L5 25 Z" />
                    </clipPath>

                    <filter id="innerShadow">
                        <feComponentTransfer in="SourceAlpha">
                            <feFuncA type="table" tableValues="1 0" />
                        </feComponentTransfer>
                        <feGaussianBlur stdDeviation="2.5" />
                        <feOffset dx="0" dy="1.5" result="offsetblur" />
                        <feFlood floodColor="black" floodOpacity="0.7" />
                        <feComposite in2="offsetblur" operator="in" />
                        <feComposite in2="SourceAlpha" operator="in" />
                        <feMerge>
                            <feMergeNode />
                            <feMergeNode in="SourceGraphic" />
                        </feMerge>
                    </filter>
                </defs>

                <path 
                    d="M50 2 L95 25 L95 75 L50 98 L5 75 L5 25 Z" 
                    fill="black" 
                    fillOpacity="0.25" 
                    transform="translate(0, 2.5)"
                />

                <path 
                    d="M50 2 L95 25 L95 75 L50 98 L5 75 L5 25 Z" 
                    fill={v.fill}
                    filter="url(#innerShadow)"
                />

                <path 
                    d="M50 2 L95 25 L95 75 L50 98 L5 75 L5 25 Z" 
                    fill="none" 
                    stroke={v.stroke} 
                    strokeWidth={s.strokeWidth} 
                    strokeLinejoin="round"
                />

                <path 
                    d="M50 5 L91 26 L91 74 L50 95 L9 74 L9 26 Z" 
                    fill="none" 
                    stroke={v.innerStroke} 
                    strokeWidth="1.8" 
                    opacity="0.5"
                    strokeLinejoin="round"
                />

                <path 
                    d="M-20 42 L120 -18 L120 42 L-20 102 Z" 
                    fill="white" 
                    fillOpacity="0.1" 
                    clipPath="url(#hexClip)"
                    pointerEvents="none"
                />
            </svg>

            <div className="relative z-10 w-full h-full flex items-center justify-center pointer-events-none">
                <div className="w-[82%] h-[82%] flex items-center justify-center">
                    {typeof children === 'string' || typeof children === 'number' ? (
                        <GameText 
                            text={children.toString()} 
                            baseFontSize={s.fontSize}
                            className={`${v.text} font-black italic tracking-tighter uppercase drop-shadow-[0_1px_3px_rgba(0,0,0,0.85)]`}
                        />
                    ) : (
                        <div className={`w-full h-full flex items-center justify-center ${v.text}`}>
                            {children}
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

