import React from 'react';
import { HexBadge } from './HexBadge';
import { CreditIcon, GoldIcon } from './CurrencyIcons';

interface SeasonRewardButtonV2Props {
    level: number;
    rewardValue: string;
    rewardType: 'credits' | 'gold' | 'box';
    rewardLabel: string;
    progressPercent: number; // 0-100
    isClaimed: boolean;
    isActive: boolean;
    isLocked: boolean;
    onClick: () => void;
    className?: string;
}

export const SeasonRewardButtonV2: React.FC<SeasonRewardButtonV2Props> = ({
    level,
    rewardValue,
    rewardType,
    rewardLabel,
    progressPercent,
    isClaimed,
    isActive,
    isLocked,
    onClick,
    className = ""
}) => {
    // Determine the progress bar width based on state
    const barWidth = isClaimed ? 100 : (isActive ? progressPercent : 0);

    // Determine theme colors based on state
    const opacityClass = isLocked ? 'opacity-60' : 'opacity-100';
    const activePulse = isActive ? 'animate-pulse' : '';

    const renderIcon = () => {
        switch (rewardType) {
            case 'gold': return <GoldIcon size="sm" />;
            case 'credits': return <CreditIcon size="sm" />;
            case 'box': return (
                <div className="w-5 h-5 flex items-center justify-center bg-indigo-500 rounded-sm border border-white/20 shadow-[0_0_8px_rgba(99,102,241,0.5)]">
                    <span className="text-[0.5rem] font-black text-white">?</span>
                </div>
            );
            default: return null;
        }
    };

    return (
        <div 
            className={`h-14 w-full relative group cursor-pointer active:scale-95 transition-all ${className} ${opacityClass}`}
            onClick={onClick}
        >
            {/* BASE CONTAINER (SLANTED) */}
            <div className="absolute inset-0 bg-slate-900 border border-slate-700/50 rounded skew-x-[-12deg] overflow-hidden shadow-lg">

                {/* 1. PROGRESS BAR BACKGROUND */}
                <div 
                    className={`absolute inset-y-0 left-0 bg-gradient-to-r from-indigo-900/60 to-indigo-600/40 transition-all duration-700 ease-out ${activePulse}`}
                    style={{ width: `${barWidth}%` }}
                >
                    {isActive && (
                        <div className="absolute inset-0 bg-white/10 animate-[shimmer_2s_infinite]"></div>
                    )}
                </div>

                {/* 2. CONTENT LAYER (UN-SKEWED) */}
                <div className="relative h-full w-full skew-x-[12deg] flex items-center px-2">

                    {/* Level Badge (Left) */}
                    <div className="shrink-0 -ml-3 mr-2">
                        <HexBadge 
                            variant={isActive ? "primary" : (isClaimed ? "success" : "secondary")} 
                            size="sm" 
                            glow={isActive}
                        >
                            {level}
                        </HexBadge>
                    </div>

                    {/* Reward Center Info */}
                    <div className="flex-1 flex flex-col items-center justify-center text-center">
                        <div className="flex items-center gap-1.5">
                            {renderIcon()}
                            <span className="text-[0.9rem] font-black text-white italic tracking-tighter drop-shadow-md">
                                {rewardValue}
                            </span>
                        </div>
                        <span className="text-[0.45rem] font-black text-slate-400 uppercase tracking-[0.2em] leading-none mt-0.5">
                            {rewardLabel}
                        </span>
                    </div>

                    {/* Progress Detail (Right) */}
                    <div className="shrink-0 w-10 text-right pr-1">
                        <span className={`text-[0.55rem] font-black italic tabular-nums ${isActive ? 'text-indigo-300' : 'text-slate-600'}`}>
                            {isActive ? `${progressPercent}%` : (isClaimed ? 'DONE' : 'LOCKED')}
                        </span>
                    </div>

                </div>
            </div>

            {/* Claimed Overlay */}
            {isClaimed && (
                <div className="absolute inset-0 flex items-center justify-center pointer-events-none overflow-hidden rounded z-20">
                    <div className="bg-emerald-400/10 backdrop-blur-[1px] absolute inset-0"></div>
                    <div className="bg-gradient-to-r from-emerald-400 via-white to-emerald-400 text-slate-900 text-[0.45rem] font-black uppercase tracking-[0.3em] px-12 py-0.5 rotate-[-12deg] border-y border-white shadow-2xl drop-shadow-lg">
                        CLAIMED
                    </div>
                </div>
            )}

            <style>{`
                @keyframes shimmer {
                    0% { transform: translateX(-100%); }
                    100% { transform: translateX(100%); }
                }
            `}</style>
        </div>
    );
};

