import React from 'react';
import { HexBadge } from './HexBadge';

interface SeasonRewardButtonV2Props {
    level: number;
    progressPercent: number; // 0-100
    isClaimed: boolean;
    isActive: boolean;
    isLocked: boolean;
    onClick: () => void;
    className?: string;
}

export const SeasonRewardButtonV2: React.FC<SeasonRewardButtonV2Props> = ({
    level,
    progressPercent,
    isClaimed,
    isActive,
    isLocked,
    onClick,
    className = ""
}) => {
    // Fill logic: full if claimed, partial if active, empty if locked
    const barWidth = isClaimed ? 100 : (isActive ? progressPercent : 0);
    const opacityClass = isLocked ? 'opacity-40' : 'opacity-100';

    return (
        <div 
            className={`h-10 w-full relative flex items-center cursor-pointer select-none overflow-visible ${className} ${opacityClass}`}
            onClick={onClick}
        >
            {/* 
                THE TOP BAR MATCHING STRUCTURE 
                HexBadge (with negative right margin) followed by the Flex-1 Track.
            */}
            <div className="flex items-center w-full relative h-full">

                {/* LEVEL BADGE - Using negative margin to overlap the track exactly like top UI */}
                <div className="relative z-20 -mr-4 shrink-0">
                    <HexBadge 
                        variant={isActive ? "primary" : (isClaimed ? "success" : "secondary")} 
                        size="sm" 
                        glow={isActive}
                    >
                        {level}
                    </HexBadge>
                </div>

                {/* PROGRESS TRACK - Fills all available width on the right */}
                <div className="flex-1 h-5 bg-slate-900 border border-slate-700 rounded-full overflow-hidden shadow-lg shadow-black/40 relative z-10">
                    {/* XP BAR FILL */}
                    <div 
                        className="h-full bg-gradient-to-r from-indigo-600 to-purple-500"
                        style={{ width: `${barWidth}%` }}
                    />

                    {/* Progress Percentage Overlay (Inside the track) */}
                    <div className="absolute inset-0 flex items-center justify-end pr-4 pointer-events-none">
                        <span className="text-[0.55rem] font-black italic tabular-nums text-white/90 drop-shadow-[0_1px_2px_rgba(0,0,0,1)]">
                            {isActive ? `${progressPercent}%` : (isClaimed ? '100%' : '0%')}
                        </span>
                    </div>

                    {/* Simple Claimed Overlay Stamp - Centered relative to the track portion */}
                    {isClaimed && (
                        <div className="absolute inset-0 flex items-center justify-center z-20 pointer-events-none">
                            <div className="bg-emerald-500 text-slate-950 text-[0.4rem] font-black uppercase tracking-[0.2em] px-8 py-0.5 rotate-[-12deg] border-y border-white/40 shadow-xl scale-90">
                                CLAIMED
                            </div>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

