import React, { useMemo, useState, useEffect, useRef } from 'react';
import { GameText } from '../ui/GameText';
import { SlantedButton } from '../ui/SlantedButton';
import { Card } from '../Card';
import { CARDS } from '../../constants';
import { useUser } from '../../contexts/UserContext';
import { SeasonProgress } from '../ui/SeasonProgress';
import { SeasonRewardButtonV2, SeasonRewardType } from '../ui/SeasonRewardButtonV2';
import { Portal } from '../ui/Portal';
import { ScreenKey } from '../../types';

interface SeasonScreenProps {
    activeScreen?: ScreenKey;
}

export const SeasonScreen: React.FC<SeasonScreenProps> = ({ activeScreen }) => {
    const { inspect } = useUser();
    const scrollContainerRef = useRef<HTMLDivElement>(null);
    const activeLevelRef = useRef<HTMLDivElement>(null);

    // UI State for the Premium Modal
    const [showPremiumModal, setShowPremiumModal] = useState(false);

    // Current user level for demo purposes
    const currentLevel = 24;
    const progressPercent = 80;
    const currentXP = 800;
    const targetXP = 1000;

    // The definitive season card (e.g. Wolverine)
    const seasonCard = CARDS.find(c => c.id === 'c14') || CARDS[0];

    // Countdown Timer Logic
    const [timeLeft, setTimeLeft] = useState({ dd: '00', hh: '00', mm: '00', ss: '00' });

    useEffect(() => {
        const targetDate = new Date('2025-12-31T23:59:59').getTime();

        const updateTimer = () => {
            const now = new Date().getTime();
            const distance = targetDate - now;

            if (distance < 0) {
                setTimeLeft({ dd: '00', hh: '00', mm: '00', ss: '00' });
                return;
            }

            const days = Math.floor(distance / (1000 * 60 * 60 * 24));
            const hours = Math.floor((distance % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
            const minutes = Math.floor((distance % (1000 * 60 * 60)) / (1000 * 60));
            const seconds = Math.floor((distance % (1000 * 60)) / 1000);

            setTimeLeft({
                dd: String(days).padStart(2, '0'),
                hh: String(hours).padStart(2, '0'),
                mm: String(minutes).padStart(2, '0'),
                ss: String(seconds).padStart(2, '0')
            });
        };

        const interval = setInterval(updateTimer, 1000);
        updateTimer();
        return () => clearInterval(interval);
    }, []);

    // Auto-scroll logic: Center the active reward level whenever the screen becomes active
    useEffect(() => {
        if (activeScreen === 'SEASON') {
            const timer = setTimeout(() => {
                if (activeLevelRef.current && scrollContainerRef.current) {
                    const container = scrollContainerRef.current;
                    const activeItem = activeLevelRef.current;
                    const targetScroll = activeItem.offsetTop - (container.offsetHeight / 2) + (activeItem.offsetHeight / 2);
                    container.scrollTo({ top: targetScroll, behavior: 'smooth' });
                }
            }, 600); // Wait for spatial transition to complete
            return () => clearTimeout(timer);
        }
    }, [activeScreen, currentLevel]);

    const rewardList = useMemo(() => {
        return Array.from({ length: 100 }, (_, i) => {
            const level = i + 1;

            // Define reward distribution pattern
            let type: SeasonRewardType = 'credits';
            let amount: string | number = 50;

            // Level 50 is ALWAYS the Season Pass Card
            if (level === 50) {
                type = 'card';
                amount = 'SEASON EXCLUSIVE';
            } else if (level % 10 === 0) {
                type = 'card';
                amount = 'VARIANT';
            } else if (level % 5 === 0) {
                type = 'gold';
                amount = 100;
            } else if (level % 2 === 0) {
                type = 'booster';
                amount = 10;
            } else {
                type = 'credits';
                amount = 50 + (Math.floor(level / 10) * 10);
            }

            return {
                level,
                rewardType: type,
                rewardAmount: amount,
                rewardImageUrl: level === 50 ? seasonCard.imageUrl : undefined,
                isClaimed: level < currentLevel,
                isActive: level === currentLevel,
                isLocked: level > currentLevel,
                data: level === 50 ? seasonCard : { type: 'level_info', level, rewardType: type, rewardAmount: amount }
            };
        });
    }, [currentLevel, seasonCard]);

    return (
        <div className="w-full h-full flex flex-col bg-transparent overflow-hidden relative font-sans">

            {/* 1. THEME HEADER */}
            <div className="shrink-0 flex flex-col bg-slate-900/40 backdrop-blur-md border-b border-slate-800/50 pt-1 pb-2 px-4 shadow-2xl z-40 relative">
                <div className="flex items-center justify-between">
                    <h1 className="text-[1rem] font-black text-white italic tracking-tighter uppercase drop-shadow-lg leading-none">
                        Space Pirates
                    </h1>
                    <div className="flex items-center gap-1.5 bg-indigo-600/40 border border-indigo-500/50 px-2.5 py-0.5 rounded-sm shadow-[0_0_10px_rgba(79,70,229,0.2)]">
                        <div className="w-1.5 h-1.5 rounded-full bg-indigo-400 animate-pulse" />
                        <span className="text-[0.6rem] font-black text-white italic tracking-tighter">PREMIUM</span>
                    </div>
                </div>

                <div className="flex items-center justify-between mt-1.5 px-0.5">
                    <div className="flex items-center gap-1.5">
                         <span className="text-[0.55rem] font-black text-slate-400 uppercase tracking-widest leading-none">
                            Dec 1 - Dec 31
                        </span>
                    </div>
                    <div className="flex items-center gap-1.5">
                        <span className="text-[0.45rem] font-black text-indigo-400 uppercase leading-none mr-0.5">ENDS IN:</span>
                        <span className="text-[0.65rem] font-black text-white italic tabular-nums leading-none tracking-tight">
                            {timeLeft.dd}:{timeLeft.hh}:{timeLeft.mm}:{timeLeft.ss}
                        </span>
                    </div>
                </div>
            </div>

            {/* 2. PROGRESS BAR SECTION */}
            <div className="shrink-0 py-4 px-2 z-30 flex flex-col items-center w-full">
                <div className="mb-2">
                    <span className="text-[0.6rem] font-black text-indigo-200 uppercase tracking-[0.25em] leading-none drop-shadow-[0_0_8px_rgba(165,180,252,0.4)]">
                        Season Mastery
                    </span>
                </div>

                <SeasonProgress 
                    level={currentLevel}
                    progressPercent={progressPercent}
                    xpText={`${currentXP} / ${targetXP} XP`}
                />
            </div>

            {/* MAIN CONTENT AREA */}
            <div className="flex-1 flex-row overflow-hidden min-h-0 px-2 flex gap-x-5">

                {/* LEFT COLUMN: HERO CARD & CTA */}
                <div className="flex-1 flex flex-col items-center justify-center p-1 border-r border-slate-900/20">

                    <div className="flex flex-col items-center justify-center w-full max-w-[12rem] gap-y-4 -mt-16">
                        <div className="h-10 w-full opacity-100 flex flex-col items-center">
                            <div className="h-6 w-full">
                                <GameText 
                                    text="LEVEL 50 REWARD"
                                    baseFontSize={18}
                                    className="text-indigo-400 font-black tracking-[0.1em] uppercase"
                                />
                            </div>
                            <div className="h-5 w-full">
                                <GameText 
                                    text="SEASON EXCLUSIVE"
                                    baseFontSize={16}
                                    className="text-white font-black italic tracking-[0.2em] uppercase brightness-[1.5] drop-shadow-[0_2px_4px_rgba(0,0,0,0.5)]"
                                    style={{ 
                                        textShadow: '0 0 10px rgba(255,255,255,0.8)' 
                                    } as any}
                                />
                            </div>
                        </div>

                        <div 
                            className="relative cursor-pointer scale-[0.65] origin-center my-[-2rem]"
                            onClick={() => inspect(seasonCard)}
                        >
                            <div className="absolute inset-0 -inset-x-20 -inset-y-28 bg-indigo-500/25 blur-[65px] rounded-full pointer-events-none" />
                            <div className="absolute inset-0 -inset-x-12 -inset-y-16 bg-purple-600/20 blur-[40px] rounded-full pointer-events-none" />
                            <div className="absolute inset-0 -inset-x-6 -inset-y-8 bg-white/10 blur-[20px] rounded-full pointer-events-none" />

                            <div className="relative z-10 drop-shadow-[0_0_2rem_rgba(79,70,229,0.4)] active:scale-95 transition-transform">
                                <div className="absolute inset-0 border-2 border-white rounded-md z-20 pointer-events-none shadow-[0_0_10px_rgba(255,255,255,0.5)]"></div>
                                <Card card={seasonCard} size="md" />
                            </div>
                        </div>

                        <div className="w-full flex justify-center">
                            <SlantedButton 
                                variant="warning" 
                                size="sm" 
                                className="w-20 !h-6 shadow-[0_3px_8px_rgba(180,83,9,0.3)] !px-0"
                                onClick={() => setShowPremiumModal(true)}
                            >
                                <span className="text-[0.75rem] font-black tracking-tight">GO PREMIUM</span>
                            </SlantedButton>
                        </div>
                    </div>

                </div>

                {/* RIGHT COLUMN: REWARD TRACK */}
                <div className="w-[44%] flex flex-col">
                    <div 
                        ref={scrollContainerRef}
                        className="flex-1 overflow-y-auto pl-3 pr-2 py-4 space-y-3 scrollbar-hide pb-24"
                    >
                        {rewardList.map((reward) => (
                            <div 
                                key={reward.level} 
                                ref={reward.isActive ? activeLevelRef : null}
                                className="relative w-full overflow-visible"
                            >
                                <SeasonRewardButtonV2 
                                    level={reward.level}
                                    progressPercent={reward.isActive ? progressPercent : (reward.isClaimed ? 100 : 0)}
                                    isClaimed={reward.isClaimed}
                                    isActive={reward.isActive}
                                    isLocked={reward.isLocked}
                                    rewardType={reward.rewardType}
                                    rewardAmount={reward.rewardAmount}
                                    rewardImageUrl={reward.rewardImageUrl}
                                    onClick={() => inspect(reward.data)}
                                />
                            </div>
                        ))}
                    </div>
                </div>
            </div>

            {/* 3. PREMIUM REWARDS MODAL */}
            {showPremiumModal && (
                <Portal>
                    <div 
                        className="fixed inset-0 z-[600] flex items-center justify-center p-6 bg-black/60 backdrop-blur-md animate-pop"
                        onClick={() => setShowPremiumModal(false)}
                    >
                        <div 
                            className="w-full max-w-sm bg-slate-900 border-2 border-indigo-500/50 rounded-2xl overflow-hidden shadow-[0_0_50px_rgba(79,70,229,0.3)] flex flex-col"
                            onClick={(e) => e.stopPropagation()}
                        >
                            <div className="relative h-40 shrink-0">
                                <img 
                                    src="https://picsum.photos/seed/pirates/600/300" 
                                    className="w-full h-full object-cover opacity-60" 
                                    alt="Season Pass Header" 
                                />
                                <div className="absolute inset-0 bg-gradient-to-t from-slate-950 via-transparent to-transparent" />
                                <div className="absolute bottom-4 left-6">
                                    <h2 className="text-2xl font-black text-white italic uppercase tracking-tighter drop-shadow-lg">
                                        Season Pass Rewards
                                    </h2>
                                    <p className="text-[0.6rem] font-bold text-indigo-300 uppercase tracking-[0.2em]">Available This Month</p>
                                </div>
                                <button 
                                    className="absolute top-4 right-4 w-8 h-8 rounded-full bg-black/50 border border-white/20 flex items-center justify-center text-white"
                                    onClick={() => setShowPremiumModal(false)}
                                >
                                    <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                                </button>
                            </div>

                            <div className="flex-1 overflow-y-auto p-6 space-y-4">
                                <div className="space-y-3">
                                    <RewardItem icon="🎴" title="Exclusive Season Variant" description="A rare Pirate variant for Wolverine." />
                                    <RewardItem icon="💰" title="2,500 Gold" description="Premium currency for variants and emotes." />
                                    <RewardItem icon="💎" title="5,000 Credits" description="Speed up your Collection Level progress." />
                                    <RewardItem icon="📦" title="10 Mega Boxes" description="Guaranteed variants and rare materials." />
                                    <RewardItem icon="🏷️" title="Exclusive Titles" description="'Captain of the Void' and more." />
                                </div>

                                <div className="pt-4">
                                    <SlantedButton variant="warning" fullWidth size="lg">
                                        <div className="flex flex-col items-center py-1">
                                            <span className="text-[0.6rem] opacity-70">UNLOCK ALL NOW</span>
                                            <span className="text-lg">GO PREMIUM</span>
                                        </div>
                                    </SlantedButton>
                                    <p className="text-center text-[0.5rem] text-slate-500 mt-4 uppercase tracking-widest font-black">
                                        Unlock the full track instantly
                                    </p>
                                </div>
                            </div>
                        </div>
                    </div>
                </Portal>
            )}
        </div>
    );
};

