                                />
                            </div>
                        </div>

                        {/* 2. HERO CARD PREVIEW - Using slight negative margins to pull elements even closer if needed */}
                        <div 
                            className="relative cursor-pointer scale-[0.75] origin-center transition-transform active:scale-95 my-[-1rem]"
                            onClick={() => inspect(seasonCard)}
                        >
                            <div className="absolute inset-0 -inset-x-20 -inset-y-28 bg-indigo-500/25 blur-[65px] rounded-full pointer-events-none" />
                            <div className="absolute inset-0 -inset-x-12 -inset-y-16 bg-purple-600/20 blur-[40px] rounded-full pointer-events-none" />
