                            {timeLeft.dd}:{timeLeft.hh}:{timeLeft.mm}:{timeLeft.ss}
                        </span>
                    </div>
                </div>
            </div>

            {/* 2. PROGRESS BAR SECTION */}
            <SeasonMasteryHeader 
                level={currentLevel}
                progressPercent={progressPercent}
                xpText={`${currentXP} / ${targetXP} XP`}
            />

            {/* MAIN CONTENT AREA */}
            <div className="flex-1 flex-row overflow-hidden min-h-0 px-2 flex gap-x-3">

                {/* LEFT COLUMN: HERO SECTION WRAPPER */}
                <div className="w-[44%] shrink-0 flex flex-col items-center justify-center p-1 border-r border-slate-900/20">

                    {/* PARENT DIV FOR ALL HERO ELEMENTS - Reduced gap from 6 to 1 */}
                    <div className="flex flex-col items-center justify-center w-full max-w-[12rem] gap-y-1 -mt-4">

                        {/* 1. SEASON EXCLUSIVE HEADER (Reduced container height from 10 to 8) */}
