                <div className="w-[44%] shrink-0 flex flex-col items-center justify-center p-1 border-r border-slate-900/20">

                    {/* PARENT DIV FOR ALL HERO ELEMENTS */}
                    <div className="flex flex-col items-center justify-center w-full max-w-[12rem] gap-y-1 -mt-4 relative overflow-visible">

