                        <div className="h-8 w-full flex items-center justify-center relative z-30">
                            <h2 className="text-[0.8rem] font-black !text-white tracking-[0.2em] uppercase drop-shadow-[0_2px_3px_rgba(0,0,0,1)] text-center leading-none">
                                SEASON EXCLUSIVE
