import React from 'react';
import { HexBadge } from './HexBadge';
import { CreditIcon, GoldIcon } from './CurrencyIcons';

export type SeasonRewardType = 'gold' | 'credits' | 'card' | 'booster';

interface SeasonRewardButtonV2Props {
    level: number;
    progressPercent: number; // 0-100
    isClaimed: boolean;
    isActive: boolean;
    isLocked: boolean;
    rewardType: SeasonRewardType;
    rewardAmount?: string | number;
    rewardImageUrl?: string; // Optional: for mini card rendering
    onClick: () => void;
    className?: string;
}

export const SeasonRewardButtonV2: React.FC<SeasonRewardButtonV2Props> = ({
    level,
    progressPercent,
    isClaimed,
    isActive,
    isLocked,
    rewardType,
    rewardImageUrl,
    onClick,
    className = ""
}) => {
    // Fill logic: full if claimed, partial if active, empty if locked
    const barWidth = isClaimed ? 100 : (isActive ? progressPercent : 0);

    // Removed conditional opacity reduction for locked items to keep upcoming rewards clear.
    // We only reduce visibility for rewards that have already been claimed.
    const trackOpacity = 'opacity-100';

    return (
        <div 
            className={`h-10 w-full relative flex items-center cursor-pointer select-none overflow-visible ${className}`}
            onClick={onClick}
        >
            <div className="flex items-center w-full relative h-full">

                {/* 
                    1. LEVEL BADGE (z-50) 
                    Only claimed rewards use 'secondary' (gray).
                    Active and Locked rewards use 'primary' (colorful).
                */}
                <div className="relative z-50 -mr-4 shrink-0">
                    <HexBadge 
                        variant={isClaimed ? "secondary" : "primary"} 
                        size="sm" 
                        glow={isActive}
                    >
                        {level}
                    </HexBadge>
                </div>

                {/* 
                    2. PROGRESS TRACK (z-10) 
                */}
                <div className={`flex-1 h-5 bg-slate-900 border border-slate-700 rounded-full overflow-hidden shadow-lg shadow-black/40 relative z-10 transition-opacity duration-300 ${trackOpacity}`}>
                    {/* XP BAR FILL */}
                    <div 
                        className={`h-full transition-all duration-700 ${isClaimed ? 'bg-slate-600/50' : 'bg-gradient-to-r from-indigo-600 to-purple-500'}`}
                        style={{ width: `${barWidth}%` }}
                    />

                    {/* Progress Percentage Overlay */}
                    <div className="absolute inset-0 flex items-center justify-end pr-4 pointer-events-none">
                        <span className="text-[0.55rem] font-black italic tabular-nums text-white/40 drop-shadow-[0_1px_2px_rgba(0,0,0,1)]">
                            {isActive ? `${progressPercent}%` : (isClaimed ? '100%' : '0%')}
                        </span>
                    </div>
                </div>

                {/* 
                    3. REWARD ICON OVERLAY (z-30)
                    Grayscale and reduced opacity if already claimed.
                    No longer reduced for locked items.
                */}
                <div className={`absolute inset-0 flex items-center justify-center pointer-events-none z-30 pl-6 transition-all duration-300 ${trackOpacity} ${isClaimed ? 'grayscale brightness-75 opacity-40' : ''}`}>
                    <div className="scale-125 drop-shadow-[0_2px_4px_rgba(0,0,0,0.8)]">
                        <RewardIconGraphic type={rewardType} imageUrl={rewardImageUrl} level={level} />
                    </div>
                </div>

                {/* 
                    4. CLAIMED BANNER OVERLAY (z-40)
                */}
                {isClaimed && (
                    <div className="absolute inset-0 flex items-center justify-center z-40 pointer-events-none pl-6">
                        <div className="bg-emerald-500 text-slate-950 text-[0.45rem] font-black uppercase tracking-[0.25em] px-3 py-0.5 rotate-[-10deg] border-y border-white shadow-[0_0_15px_rgba(16,185,129,0.4)] scale-100 ring-1 ring-white/20">
                            CLAIMED
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

// Internal icon factory for season rewards
const RewardIconGraphic: React.FC<{ type: SeasonRewardType; imageUrl?: string; level?: number }> = ({ type, imageUrl, level }) => {
    switch (type) {
        case 'gold': return <GoldIcon size="sm" />;
        case 'credits': return <CreditIcon size="sm" />;
        case 'card': 
            // Level 50 special handling for the mini card version
            if (level === 50 && imageUrl) {
                return (
                    <div className="w-6 h-8 bg-indigo-900 border border-white/50 rounded-sm overflow-hidden shadow-lg relative">
                        <img src={imageUrl} className="w-full h-full object-cover" alt="Mini Card Reward" />
                        <div className="absolute inset-0 bg-gradient-to-t from-black/60 to-transparent" />
                        <div className="absolute bottom-0 inset-x-0 h-0.5 bg-yellow-400" />
                    </div>
                );
            }
            return (
                <svg className="w-5 h-5 text-indigo-200" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" />
                </svg>
            );
        case 'booster': return (
            <svg className="w-5 h-5 text-amber-300" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M13 10V3L4 14h7v7l9-11h-7z" />
            </svg>
        );
        default: return null;
    }
};

