export const InspectorOverlay: React.FC = () => {
    const { 
        user,
        inspectingCard, 
        inspectingLocation, 
        inspectingCurrency,
        inspectingBox,
        inspectingReward,
        upgradeCard,
        closeInspector 
    } = useUser();

    const [isInteractionEnabled, setIsInteractionEnabled] = useState(false);

    useEffect(() => {
        const anyActive = inspectingCard || inspectingLocation || inspectingCurrency || inspectingBox || inspectingReward;
        if (anyActive) {
            const timer = setTimeout(() => setIsInteractionEnabled(true), 150);
            return () => clearTimeout(timer);
        } else {
            setIsInteractionEnabled(false);
        }
    }, [inspectingCard, inspectingLocation, inspectingCurrency, inspectingBox, inspectingReward]);

    if (!inspectingCard && !inspectingLocation && !inspectingCurrency && !inspectingBox && !inspectingReward) return null;

    const handleBackgroundClick = (e: React.MouseEvent) => {
        if (isInteractionEnabled) {
            closeInspector();
        }
    };

    return (
        <div 
            className="fixed inset-0 z-[500] bg-black/40 backdrop-blur-sm flex flex-col items-center justify-center p-6 animate-pop overflow-y-auto"
            onClick={handleBackgroundClick}
        >
            {inspectingReward && (
                <SeasonRewardInspector reward={inspectingReward} />
            )}

            {inspectingBox && (
                <BoxInspector 
                    boxType={inspectingBox.boxType} 
                    title={inspectingBox.title} 
                    description={inspectingBox.description} 
                />
            )}

            {inspectingCard && (
                <CardInspector 
                    card={inspectingCard} 
                    user={user} 
                    onUpgrade={upgradeCard} 
                />
            )}

            {inspectingLocation && (
                <LocationInspector location={inspectingLocation} />
            )}

            {inspectingCurrency && (
                <CurrencyInspector 
                    type={inspectingCurrency.type} 
                    amount={inspectingCurrency.amount} 
                />
            )}

            <div className="fixed bottom-8 text-slate-400 font-black text-[0.5rem] uppercase tracking-[0.4em] animate-pulse drop-shadow-[0_2px_4px_rgba(0,0,0,1)]">
                Tap anywhere to close
            </div>
        </div>
    );
};

