    switch (type) {
        case 'gold': return <GoldIcon size={size === 'lg' ? 'md' : 'sm'} />;
        case 'credits': return <CreditIcon size={size === 'lg' ? 'md' : 'sm'} />;
        case 'card': 
            // Level 50 special handling for the mini card version
            if (level === 50 && imageUrl) {
                return (
                    <div className={`${size === 'lg' ? 'w-12 h-16' : 'w-6 h-8'} bg-indigo-900 border border-white/50 rounded-sm overflow-hidden shadow-lg relative`}>
                        <img src={imageUrl} className="w-full h-full object-cover" alt="Mini Card Reward" />
                        <div className="absolute inset-0 bg-gradient-to-t from-black/60 to-transparent" />
                        <div className="absolute bottom-0 inset-x-0 h-0.5 bg-yellow-400" />
                    </div>
                );
            }
            return (
                <svg className={`${iconSize} text-indigo-200`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" />
                </svg>
            );
        case 'booster': return (
            <svg className={`${iconSize} text-amber-300`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M13 10V3L4 14h7v7l9-11h-7z" />
            </svg>
        );
        default: return null;
    }
};

