import React from 'react';
import { HexBadge } from './HexBadge';
import { RewardItemVisual, SeasonRewardType } from './RewardItemVisual';

// Export type for convenience when using the button
export type { SeasonRewardType };

interface SeasonRewardButtonV2Props {
    level: number;
    progressPercent: number; // 0-100
    isClaimed: boolean;
    isActive: boolean;
    isLocked: boolean;
    rewardType: SeasonRewardType;
    rewardAmount?: string | number;
    rewardImageUrl?: string; // Optional: for mini card rendering
    onClick: () => void;
    className?: string;
}

export const SeasonRewardButtonV2: React.FC<SeasonRewardButtonV2Props> = ({
    level,
    progressPercent,
    isClaimed,
    isActive,
    isLocked,
    rewardType,
    rewardAmount,
    rewardImageUrl,
    onClick,
    className = ""
}) => {
    // Fill logic: full if claimed, partial if active, empty if locked
    const barWidth = isClaimed ? 100 : (isActive ? progressPercent : 0);

    return (
        <div 
            className={`h-10 w-full relative flex items-center cursor-pointer select-none overflow-visible ${className}`}
            onClick={onClick}
        >
            <div className="flex items-center w-full relative h-full">

                {/* 
                    1. LEVEL BADGE (z-50) 
                    Only claimed rewards use 'secondary' (gray).
                    Active and Locked rewards use 'primary' (colorful).
                */}
                <div className="relative z-50 -mr-4 shrink-0">
                    <HexBadge 
                        variant={isClaimed ? "secondary" : "primary"} 
                        size="sm" 
                        glow={isActive}
                    >
                        {level}
                    </HexBadge>
                </div>

                {/* 
                    2. PROGRESS TRACK (z-10) 
                */}
                <div className={`flex-1 h-5 bg-slate-900 border border-slate-700 rounded-full overflow-hidden shadow-lg shadow-black/40 relative z-10 transition-opacity duration-300`}>
                    {/* XP BAR FILL */}
                    <div 
                        className={`h-full transition-all duration-700 ${isClaimed ? 'bg-slate-600/50' : 'bg-gradient-to-r from-indigo-600 to-purple-500'}`}
                        style={{ width: `${barWidth}%` }}
                    />

                    {/* Progress Percentage Overlay - Locked levels now show nothing (hiding 0%) */}
                    <div className="absolute inset-0 flex items-center justify-end pr-4 pointer-events-none">
                        <span className="text-[0.55rem] font-black italic tabular-nums text-white/40 drop-shadow-[0_1px_2px_rgba(0,0,0,1)]">
                            {isActive ? `${progressPercent}%` : (isClaimed ? '100%' : '')}
                        </span>
                    </div>
                </div>

                {/* 
                    3. REWARD VISUAL OVERLAY (z-30)
                    Uses the new combined standalone component. 
                    Grayscale and reduced opacity if already claimed.
                */}
                <div className={`absolute inset-0 flex items-center justify-center z-30 pl-6 transition-all duration-300 ${isClaimed ? 'grayscale brightness-75 opacity-40' : ''}`}>
                    <RewardItemVisual 
                        type={rewardType} 
                        amount={rewardAmount} 
                        imageUrl={rewardImageUrl} 
                        level={level} 
                    />
                </div>

                {/* 
                    4. CLAIMED BANNER OVERLAY (z-40)
                */}
                {isClaimed && (
                    <div className="absolute inset-0 flex items-center justify-center z-40 pointer-events-none pl-6">
                        <div className="bg-emerald-500 text-slate-950 text-[0.45rem] font-black uppercase tracking-[0.25em] px-3 py-0.5 rotate-[-10deg] border-y border-white shadow-[0_0_15px_rgba(16,185,129,0.4)] scale-100 ring-1 ring-white/20">
                            CLAIMED
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

import React from 'react';

interface ModalBackdropProps {
    children: React.ReactNode;
    onClose: () => void;
    className?: string;
    showCloseHint?: boolean;
    blurAmount?: 'sm' | 'md' | 'lg';
}

/**
 * ModalBackdrop
 * A reusable container for all overlays (Inspectors, Modals, Details).
 * Provides consistent darkening, blurring, and "tap to close" hint.
 */
export const ModalBackdrop: React.FC<ModalBackdropProps> = ({ 
    children, 
    onClose, 
    className = "",
    showCloseHint = true,
    blurAmount = 'md'
}) => {
    const blurClass = {
        sm: 'backdrop-blur-sm',
        md: 'backdrop-blur-md',
        lg: 'backdrop-blur-xl'
    }[blurAmount];

    return (
        <div 
            className={`fixed inset-0 z-[500] bg-black/60 ${blurClass} flex flex-col items-center justify-center p-6 overflow-y-auto ${className}`}
            onClick={onClose}
        >
            {/* The actual modal content (should usually have e.stopPropagation()) */}
            {children}

            {/* Standardised Close Hint */}
            {showCloseHint && (
                <div className="fixed bottom-8 text-white/30 font-black text-[0.5rem] uppercase tracking-[0.4em] animate-pulse drop-shadow-[0_2px_4px_rgba(0,0,0,1)] pointer-events-none">
                    Tap anywhere to close
                </div>
            )}
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { useUser } from '../contexts/UserContext';
import { CardInspector } from './inspector/CardInspector';
import { LocationInspector } from './inspector/LocationInspector';
import { CurrencyInspector } from './inspector/CurrencyInspector';
import { BoxInspector } from './inspector/BoxInspector';
import { SeasonRewardInspector } from './inspector/SeasonRewardInspector';
import { ModalBackdrop } from './ui/ModalBackdrop';

export const InspectorOverlay: React.FC = () => {
    const { 
        user,
        inspectingCard, 
        inspectingLocation, 
        inspectingCurrency,
        inspectingBox,
        inspectingReward,
        upgradeCard,
        closeInspector 
    } = useUser();

    const [isInteractionEnabled, setIsInteractionEnabled] = useState(false);

    useEffect(() => {
        const anyActive = inspectingCard || inspectingLocation || inspectingCurrency || inspectingBox || inspectingReward;
        if (anyActive) {
            // Safety lockout to prevent accidental double-tap closure
            const timer = setTimeout(() => setIsInteractionEnabled(true), 150);
            return () => clearTimeout(timer);
        } else {
            setIsInteractionEnabled(false);
        }
    }, [inspectingCard, inspectingLocation, inspectingCurrency, inspectingBox, inspectingReward]);

    if (!inspectingCard && !inspectingLocation && !inspectingCurrency && !inspectingBox && !inspectingReward) return null;

    const handleBackgroundClick = () => {
        if (isInteractionEnabled) {
            closeInspector();
        }
    };

    return (
        <ModalBackdrop onClose={handleBackgroundClick}>
            {inspectingReward && (
                <SeasonRewardInspector reward={inspectingReward} />
            )}

            {inspectingBox && (
                <BoxInspector 
                    boxType={inspectingBox.boxType} 
                    title={inspectingBox.title} 
                    description={inspectingBox.description} 
                />
            )}

            {inspectingCard && (
                <CardInspector 
                    card={inspectingCard} 
                    user={user} 
                    onUpgrade={upgradeCard} 
                />
            )}

            {inspectingLocation && (
                <LocationInspector location={inspectingLocation} />
            )}

            {inspectingCurrency && (
                <CurrencyInspector 
                    type={inspectingCurrency.type} 
                    amount={inspectingCurrency.amount} 
                />
            )}
        </ModalBackdrop>
    );
};

import React, { useMemo, useState, useEffect, useRef } from 'react';
