}) => {
    // Fill logic: full if claimed, partial if active, empty if locked
    const barWidth = isClaimed ? 100 : (isActive ? progressPercent : 0);

    return (
        <div 
            className={`h-10 w-full relative flex items-center cursor-pointer select-none overflow-visible ${className}`}
            onClick={onClick}
        >
            <div className="flex items-center w-full relative h-full">

