                */}
                {isActive && (
                    <div className="absolute inset-0 flex items-center justify-center z-20 pointer-events-none pl-6 overflow-visible">
                        <div className="absolute w-32 h-20 bg-indigo-500/30 blur-[35px] rounded-full" />
