                    Grayscale and reduced opacity if already claimed.
                */}
                <div className={`absolute inset-0 flex items-center justify-center z-30 pl-6 transition-all duration-300 ${isClaimed ? 'grayscale brightness-75 opacity-40' : ''}`}>
