import React, { useState, useEffect, useMemo } from 'react';
import { AppShell } from './components/ui/AppShell';
import { LoadingScreen } from './components/screens/LoadingScreen';
import { LoginScreen } from './components/screens/LoginScreen';
import { NavigationBar } from './components/ui/NavigationBar';
import { InspectorOverlay } from './components/InspectorOverlay';
import { LoopingScene } from './components/ui/LoopingScene';
import { preloadAssets } from './services/assetLoader';
import { audio } from './services/audio';
import { useSpatialNavigation } from './hooks/useSpatialNavigation';
import { ScreenKey } from './types';
import { UserProvider } from './contexts/UserContext';

export default function App() {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [loadingProgress, setLoadingProgress] = useState(0);
  const [isLoading, setIsLoading] = useState(true);

  // Track which screens have been visited to keep them mounted
  const [visitedScreens, setVisitedScreens] = useState<Set<ScreenKey>>(new Set(['MENU']));

  const { 
      activeScreen, 
      prevScreen, 
      isTransitioning, 
      containerStyle, 
      navigateTo, 
      resetToMenu, 
      WORLDS 
  } = useSpatialNavigation();

  // 1. BOOT SEQUENCE
  useEffect(() => {
    const initApp = async () => {
      await preloadAssets((progress) => setLoadingProgress(progress));
      setTimeout(() => setIsLoading(false), 400);
    };
    initApp();
  }, []);

  // Update visited screens whenever navigation occurs
  useEffect(() => {
    if (isLoggedIn && !visitedScreens.has(activeScreen)) {
        setVisitedScreens(prev => new Set(prev).add(activeScreen));
    }
  }, [activeScreen, isLoggedIn, visitedScreens]);

  const handleLogin = () => {
      audio.playUiClick();
      setIsLoggedIn(true);
  };

  const handleLogout = () => {
      audio.playUiClick();
      setIsLoggedIn(false);
      setVisitedScreens(new Set(['MENU'])); // Reset persistence on logout
      resetToMenu();
  };

  const handleStartGame = () => navigateTo('GAME');

  // --- STATE MACHINE GATES ---

  if (isLoading) {
      return (
          <AppShell>
              <LoadingScreen progress={loadingProgress} />
          </AppShell>
      );
  }

  if (!isLoggedIn) {
      return (
          <AppShell>
              <LoginScreen onLogin={handleLogin} />
          </AppShell>
      );
  }

  return (
    <UserProvider>
        <AppShell>
        <InspectorOverlay />

        {/* GLOBAL AMBIENT SCENE: Behind UI, above static bg */}
        <LoopingScene activeScreen={activeScreen} />

        <div 
            className="w-full h-full relative transition-transform duration-500 ease-[cubic-bezier(0.22,1,0.36,1)] will-change-transform z-10"
            style={containerStyle}
        >
            {(Object.keys(WORLDS) as ScreenKey[]).map((key) => {
                // PERSISTENCE LOGIC:
                const hasBeenVisited = visitedScreens.has(key);
                const isActive = key === activeScreen;
                const isPrev = key === prevScreen;
                const isParticipatingInTransition = isActive || (isTransitioning && isPrev);

                if (!hasBeenVisited && !isParticipatingInTransition) return null;

                const config = WORLDS[key];
                const ScreenComponent = config.component;

                return (
                    <div 
                        key={key} 
                        className={`absolute w-full h-full top-0 left-0 overflow-hidden transition-opacity duration-300 ${!isParticipatingInTransition ? 'pointer-events-none invisible opacity-0' : 'pointer-events-auto visible opacity-100'}`}
                        style={{ 
                            transform: `translate3d(${config.x * 100}%, ${config.y * 100}%, 0)`,
                        }}
                    >
                        <ScreenComponent 
                            activeScreen={activeScreen} 
                            onNavigate={navigateTo} 
                            onExit={() => navigateTo('MENU')}
                            onBack={() => navigateTo('MENU')}
                            onStartGame={handleStartGame}
                            onLogout={handleLogout}
                        />
                    </div>
                );
            })}
        </div>

        {activeScreen !== 'GAME' && (
            <NavigationBar activeScreen={activeScreen} onNavigate={navigateTo} />
        )}

        </AppShell>
    </UserProvider>
  );
}

