import { Howl, Howler } from 'howler';
import { AUDIO_MANIFEST, SfxKey } from '../utils/assets';

// Global settings
Howler.autoUnlock = true; 
Howler.volume(0.5);

export type { SfxKey };

class AudioService {
    private sounds: Record<string, Howl> = {};
    private initialized = false;
    private currentBgm: Howl | null = null;
    private currentBgmKey: string | null = null;

    public init() {
        if (this.initialized) return;

        Object.entries(AUDIO_MANIFEST).forEach(([key, src]) => {
            const isMusic = key.startsWith('bgm_');
            this.sounds[key] = new Howl({
                src: [src],
                preload: true,
                volume: isMusic ? 0 : 0.5, // Music starts silent for fade-in
                loop: isMusic,
                html5: isMusic, // Use HTML5 audio for long streams (performance)
                onplayerror: (id, err) => {
                    console.warn(`Playback error for ${key}:`, err);
                    this.sounds[id ? id : key].once('unlock', () => this.sounds[key].play());
                }
            });
        });

        this.initialized = true;
    }

    public play(key: SfxKey | undefined, volumeScale = 1.0) {
        if (!key || !this.sounds[key]) return;
        const sound = this.sounds[key];
        const id = sound.play();
        sound.volume(0.5 * volumeScale, id);
    }

    /**
     * Switch background music with a smooth cross-fade.
     */
    public playBgm(key: 'bgm_menu' | 'bgm_game', fadeDuration = 1500) {
        if (this.currentBgmKey === key) return;

        const nextBgm = this.sounds[key];
        if (!nextBgm) return;

        // 1. Fade out old music
        if (this.currentBgm) {
            const oldBgm = this.currentBgm;
            oldBgm.fade(oldBgm.volume(), 0, fadeDuration);
            setTimeout(() => {
                if (this.currentBgm !== oldBgm) oldBgm.stop();
            }, fadeDuration);
        }

        // 2. Fade in new music
        this.currentBgm = nextBgm;
        this.currentBgmKey = key;

        nextBgm.stop(); // Reset to start
        nextBgm.play();
        nextBgm.fade(0, 0.4, fadeDuration); // Target volume 0.4 for BGM
    }

    public fadeOut(key: SfxKey, duration = 500) {
        const sound = this.sounds[key];
        if (sound && sound.playing()) {
            sound.fade(sound.volume(), 0, duration);
            setTimeout(() => sound.stop(), duration);
        }
    }

    public playUiClick() {
        this.play('sfx_ui_click', 0.8);
    }

    public playUiHover() {
        this.play('sfx_ui_hover', 0.2);
    }
}

export const audio = new AudioService();

import React, { useState, useEffect, useMemo } from 'react';
import { AppShell } from './components/ui/AppShell';
import { LoadingScreen } from './components/screens/LoadingScreen';
