import { Howl, Howler } from 'howler';
import { AUDIO_MANIFEST, SfxKey } from '../utils/assets';

// Global settings
Howler.autoUnlock = true; 
Howler.volume(0.6);

export type { SfxKey };

class AudioService {
    private sounds: Record<string, Howl> = {};
    private initialized = false;
    private currentBgm: Howl | null = null;
    private currentBgmKey: string | null = null;

    /**
     * Initialized all sound assets.
     * Must be called during a user interaction (click/touch).
     */
    public async init() {
        if (this.initialized) {
            // Re-resume context just in case browser suspended it
            if (Howler.ctx && Howler.ctx.state === 'suspended') {
                await Howler.ctx.resume();
            }
            return;
        }

        Object.entries(AUDIO_MANIFEST).forEach(([key, src]) => {
            const isMusic = key.startsWith('bgm_');
            this.sounds[key] = new Howl({
                src: [src],
                // Forcing html5: false (Web Audio) for all sounds.
                // This uses more memory but is significantly more reliable for 
                // seamless looping and bypassing mobile autoplay restrictions.
                html5: false, 
                preload: true,
                volume: isMusic ? 0 : 0.5,
                loop: isMusic,
                onloaderror: (id, err) => console.warn(`Audio Load Error [${key}]:`, err),
                onplayerror: (id, err) => {
                    console.warn(`Audio Play Error [${key}]:`, err);
                    this.sounds[key].once('unlock', () => this.sounds[key].play());
                }
            });
        });

        // Final authority: Force resume the context
        if (Howler.ctx && Howler.ctx.state === 'suspended') {
            await Howler.ctx.resume();
        }

        this.initialized = true;
    }

    public play(key: SfxKey | undefined, volumeScale = 1.0) {
        if (!key || !this.sounds[key]) return;
        if (!this.initialized) this.init();

        if (key.startsWith('bgm_')) return; // Music must use playBgm

        const sound = this.sounds[key];
        const id = sound.play();
        sound.volume(0.5 * volumeScale, id);
    }

    /**
     * Comprehensive BGM management with cross-fading and state protection.
     */
    public playBgm(key: 'bgm_menu' | 'bgm_game', fadeDuration = 1000) {
        // Guard 1: Already playing the target track?
        if (this.currentBgmKey === key && this.currentBgm?.playing()) return;

        // Guard 2: Ensure initialization
        if (!this.initialized) this.init();

        const nextBgm = this.sounds[key];
        if (!nextBgm) return;

        console.log(`AudioService: Transitioning to ${key}`);

        // 1. Fade out current track
        if (this.currentBgm && this.currentBgm.playing()) {
            const oldBgm = this.currentBgm;
            const oldKey = this.currentBgmKey;

            oldBgm.fade(oldBgm.volume(), 0, fadeDuration);
            setTimeout(() => {
                // Only stop if we haven't switched back to it during the fade
                if (this.currentBgmKey !== oldKey) {
                    oldBgm.stop();
                }
            }, fadeDuration + 100);
        }

        // 2. Setup next track
        this.currentBgm = nextBgm;
        this.currentBgmKey = key;

        // Ensure state is ready
        if (nextBgm.state() === 'unloaded') {
            nextBgm.load();
        }

        // Start playback
        nextBgm.volume(0);
        const playId = nextBgm.play();
        nextBgm.fade(0, 0.4, fadeDuration, playId);
    }

    public stopBgm() {
        if (this.currentBgm) {
            this.currentBgm.fade(this.currentBgm.volume(), 0, 500);
            setTimeout(() => {
                this.currentBgm?.stop();
                this.currentBgm = null;
                this.currentBgmKey = null;
            }, 600);
        }
    }

    public playUiClick() {
        this.play('sfx_ui_click', 0.8);
    }
}

