import { audio } from './services/audio';
import { useSpatialNavigation } from './hooks/useSpatialNavigation';
import { ScreenKey } from './types';
import { UserProvider } from './contexts/UserContext';

export default function App() {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [loadingProgress, setLoadingProgress] = useState(0);
  const [isLoading, setIsLoading] = useState(true);

  const [visitedScreens, setVisitedScreens] = useState<Set<ScreenKey>>(new Set(['MENU']));
  const musicInitializedRef = useRef(false);

  const { 
      activeScreen, 
      prevScreen, 
      isTransitioning, 
      containerStyle, 
      navigateTo, 
      resetToMenu, 
      WORLDS 
  } = useSpatialNavigation();

  // 1. BOOT SEQUENCE
  useEffect(() => {
    const initApp = async () => {
      await preloadAssets((progress) => setLoadingProgress(progress));
      setTimeout(() => setIsLoading(false), 400);
    };
    initApp();
  }, []);

  // 2. MUSIC ORCHESTRATION
  // This is the single source of truth for BGM based on navigation state
  useEffect(() => {
      if (!isLoggedIn || isLoading) return;

      const targetBgm = activeScreen === 'GAME' ? 'bgm_game' : 'bgm_menu';
      audio.playBgm(targetBgm);
  }, [activeScreen, isLoggedIn, isLoading]);

  useEffect(() => {
    if (isLoggedIn && !visitedScreens.has(activeScreen)) {
        setVisitedScreens(prev => new Set(prev).add(activeScreen));
    }
  }, [activeScreen, isLoggedIn, visitedScreens]);

  const handleLogin = async () => {
      // Direct User Gesture: Critical for unlocking audio
      await audio.init(); 
      audio.playUiClick();

      // Start the music state machine
      setIsLoggedIn(true);
      musicInitializedRef.current = true;
  };

  const handleLogout = () => {
      audio.playUiClick();
      audio.stopBgm();
      setIsLoggedIn(false);
      musicInitializedRef.current = false;
      setVisitedScreens(new Set(['MENU']));
      resetToMenu();
  };

