interface CardInspectorProps {
    card: CardInstance | CardDefinition;
    user: UserProfile;
    onUpgrade: (id: string) => void;
}

export const CardInspector: React.FC<CardInspectorProps> = ({ card, user, onUpgrade }) => {
    const isInstance = (c: any): c is CardInstance => c && 'instanceId' in c;
    const def = isInstance(card) ? card.def : card as CardDefinition;

    const isOwned = user.collection.includes(def.id);
    const currentRarity = user.cardRarities[def.id] || def.rarity;
    const rarityPath: CardRarity[] = ["Common", "Rare", "Epic", "Legendary"];
    const nextRarity = rarityPath[rarityPath.indexOf(currentRarity) + 1];
    const costMap: Record<string, number> = { "Rare": 100, "Epic": 400, "Legendary": 1000 };
    const upgradeCost = nextRarity ? costMap[nextRarity] : null;

    return (
        <div className="flex flex-col items-center w-full max-w-[16rem]">
            {/* CARD CONTAINER - Added w-48 and aspect-[5/7] to fix layout collapse */}
            <div className="relative z-40 mb-5 shadow-[0_0_3rem_rgba(0,0,0,0.8)] w-48 aspect-[5/7]">
                {isInstance(card) && (
                    <>
                        <StatHistory modifiers={card.costModifiers} type="cost" side="left" />
                        <StatHistory modifiers={card.powerModifiers} type="power" side="right" />
                    </>
                )}
                <Card 
                    card={{ ...def, rarity: currentRarity }} 
                    size="lg" 
                    borderColor={!isOwned ? 'border-white' : undefined}
                />
            </div>

            <div className="w-full text-center mb-4 px-1">
                <KeywordText className="text-[0.7rem]" text={isInstance(card) ? card.currentText : def.baseText} />
            </div>

            {!isInstance(card) && nextRarity && (
                <div className="w-full mb-4">
                    <SlantedButton 
                        variant="success" 
                        fullWidth 
                        size="sm"
                        onClick={(e) => { e.stopPropagation(); onUpgrade(def.id); }}
                        disabled={user.credits < (upgradeCost || 0)}
                    >
                        <div className="flex items-center justify-center gap-2">
                            <div className="flex flex-col items-start leading-none">
                                <span className="text-[0.45rem] opacity-70">UPGRADE TO</span>
                                <span className="text-[0.6rem]">{nextRarity.toUpperCase()}</span>
                            </div>
                            <div className="h-4 w-px bg-white/20"></div>
                            <span className="text-xs">{upgradeCost} CREDITS</span>
                        </div>
                    </SlantedButton>
                </div>
            )}

            {def.flavorText && (
                <div className="w-full bg-slate-900/60 border border-slate-800 rounded-lg p-2 min-h-[2.5rem] flex flex-col items-center justify-center relative group overflow-hidden">
                    <p className="text-[0.55rem] text-indigo-200/70 italic leading-tight font-mono text-center px-1">
                        "{def.flavorText}"
                    </p>
                </div>
            )}
        </div>
    );
};

import React from 'react';
import { CardInstance, CardDefinition } from '../types';
import { UnifiedCardView } from './card/UnifiedCardView';

interface CardProps {
  card: CardInstance | CardDefinition;
  onClick?: () => void;
  size?: 'xs' | 'sm' | 'md' | 'lg';
  hidden?: boolean;
  onPointerDown?: (e: React.PointerEvent) => void;
  isDragging?: boolean;
  borderColor?: string; 
}

/**
 * Card Component
 * A high-performance wrapper that delegates all rendering to the UnifiedCardView engine.
 */
const CardComponent: React.FC<CardProps> = ({ 
  card, 
  onClick, 
  size = 'md', 
  hidden, 
  onPointerDown,
  isDragging,
  borderColor
}) => {
  return (
    <UnifiedCardView
        card={card}
        size={size}
        hidden={hidden}
        isDragging={isDragging}
        onPointerDown={onPointerDown}
        onClick={onClick}
        borderColor={borderColor}
    />
  );
};

export const Card = React.memo(CardComponent, (prev, next) => {
    if (prev.size !== next.size || prev.isDragging !== next.isDragging || prev.hidden !== next.hidden || prev.borderColor !== next.borderColor) return false;

    const isInstance = (c: any): c is CardInstance => c && 'instanceId' in c;

    if (isInstance(prev.card) && isInstance(next.card)) {
        return prev.card.instanceId === next.card.instanceId && 
               prev.card.totalPower === next.card.totalPower && 
               prev.card.totalCost === next.card.totalCost &&
               prev.card.faceUp === next.card.faceUp;
    }

    const getDefinitionId = (card: CardInstance | CardDefinition) => 
        isInstance(card) ? card.definitionId : card.id;

    return getDefinitionId(prev.card) === getDefinitionId(next.card);
});

import React from 'react';
import { CardDefinition, CardInstance } from '../../types';
import { getCardVisualState } from '../../utils/cardStyles';
import { CardBadge } from './CardBadge';
import { GameText } from '../ui/GameText';

interface UnifiedCardViewProps {
    card: CardInstance | CardDefinition;
    size: 'xs' | 'sm' | 'md' | 'lg';
    hidden?: boolean;
    isDragging?: boolean;
    onPointerDown?: (e: React.PointerEvent) => void;
    onClick?: () => void;
    borderColor?: string;
}

const SCALE_MAP = {
    xs: 0.48, // Board slots (tiny)
    sm: 0.72, // Hand (compact)
    md: 1.0,  // Deck builder / Rewards (standard)
    lg: 1.7   // Inspector (hero)
};

export const UnifiedCardView: React.FC<UnifiedCardViewProps> = ({
    card, size, hidden, isDragging, onPointerDown, onClick, borderColor
}) => {
    const scale = SCALE_MAP[size];
    const { 
        def, currentPower, currentCost, 
        powerColor, costColor, primaryColor, glowColor 
    } = getCardVisualState(card);

    if (hidden) {
        return (
            <div 
                className="w-full h-full bg-indigo-950 flex items-center justify-center overflow-hidden shadow-inner cursor-pointer"
                style={{ 
                    borderRadius: `${8 * scale}px`,
                    border: `${2 * scale}px solid rgba(129, 140, 248, 0.4)`
                }}
                onPointerDown={onPointerDown}
                onClick={onClick}
            >
                <div className="w-1/2 h-1/2 rounded-full bg-indigo-500/20 animate-pulse blur-xl" />
                <div className="absolute font-black text-indigo-300/30 italic rotate-[-45deg] tracking-tighter" style={{ fontSize: 24 * scale }}>SNAP</div>
            </div>
        );
    }

    const borderRadius = 8 * scale;
    const borderWidth = 2.5 * scale;

    // UI Decisions based on card scale
    const showNameplate = size !== 'xs'; // Too small to read on board
    const badgeScale = size === 'xs' ? scale * 1.3 : scale; // Boost badge size slightly on tiny cards

    // Use the override borderColor if provided, otherwise fall back to rarity-based primaryColor
    const finalBorderColor = borderColor || primaryColor;

    return (
        <div
            onPointerDown={onPointerDown}
            onClick={onClick}
            className={`
                relative w-full h-full select-none touch-none overflow-hidden transition-opacity duration-200 group
                ${isDragging ? 'opacity-0' : 'opacity-100'}
            `}
            style={{ 
                borderRadius: `${borderRadius}px`,
                boxShadow: `0 0 ${12 * scale}px ${glowColor}, inset 0 0 ${8 * scale}px rgba(0,0,0,0.6)`,
                border: `${borderWidth}px solid ${finalBorderColor}`,
                backgroundColor: '#0f172a'
            }}
        >
            {/* 1. Background Art Layer */}
            <div className="absolute inset-0 bg-black">
                <img 
                    src={def.imageUrl} 
                    alt={def.name} 
                    className="w-full h-full object-cover pointer-events-none transition-transform duration-700 [@media(hover:hover)]:group-hover:scale-105 opacity-90" 
                />
            </div>

            {/* 2. Visual Polish Overlays */}
            <div className="absolute inset-0 bg-gradient-to-b from-black/20 via-transparent to-black/70 pointer-events-none" />
            <div className="absolute inset-0 border border-white/10 pointer-events-none rounded-[inherit]" />

            {/* 3. Authoritative Badges */}
            <CardBadge value={currentCost} type="cost" colorClass={costColor} scale={badgeScale} />
            <CardBadge value={currentPower} type="power" colorClass={powerColor} scale={badgeScale} />

            {/* 4. Unified Nameplate */}
            {showNameplate && (
                <div 
                    className="absolute bottom-0 inset-x-0 bg-gradient-to-t from-black via-black/90 to-transparent flex flex-col items-center justify-end"
                    style={{ height: '45%', paddingBottom: 6 * scale, paddingLeft: 8 * scale, paddingRight: 8 * scale }}
                >
                    <div className="w-full h-[28%]">
                        <GameText 
                            text={def.name} 
                            baseFontSize={28 * scale} 
                            className="font-black italic uppercase tracking-tighter text-white drop-shadow-[0_2px_4px_rgba(0,0,0,1)]"
                        />
                    </div>
                </div>
            )}

            {/* 5. Tiny Name Label (Fallthrough for XS) */}
            {!showNameplate && (
                <div className="absolute bottom-0.5 inset-x-0 px-1 pointer-events-none h-[15%]">
                     <GameText 
                        text={def.name} 
                        baseFontSize={20 * scale} 
                        className="font-black italic uppercase tracking-tighter text-white drop-shadow-[0_1px_2px_rgba(0,0,0,1)]"
                    />
                </div>
            )}
        </div>
    );
};

