            updateDeck,
            upgradeCard,
            processPurchase,
            syncStore,
            inspect,
            closeInspector,
            activeDeck
        }}>
            {children}
        </UserContext.Provider>
    );
};

export const useUser = () => {
    const context = useContext(UserContext);
    if (!context) {
        throw new Error('useUser must be used within a UserProvider');
    }
    return context;
};

import React, { useState, useEffect } from 'react';
import { useUser } from '../contexts/UserContext';
import { CardInspector } from './inspector/CardInspector';
import { LocationInspector } from './inspector/LocationInspector';
import { CurrencyInspector } from './inspector/CurrencyInspector';
import { BoxInspector } from './inspector/BoxInspector';
import { SeasonRewardInspector } from './inspector/SeasonRewardInspector';
import { ModalBackdrop } from './ui/ModalBackdrop';

export const InspectorOverlay: React.FC = () => {
    const { 
        user,
        inspectingCard, 
        inspectingLocation, 
        inspectingCurrency,
        inspectingBox,
        inspectingReward,
        upgradeCard,
        closeInspector 
    } = useUser();

    const [isInteractionEnabled, setIsInteractionEnabled] = useState(false);

    useEffect(() => {
        const anyActive = inspectingCard || inspectingLocation || inspectingCurrency || inspectingBox || inspectingReward;
        if (anyActive) {
            // Safety lockout to prevent accidental double-tap closure
            const timer = setTimeout(() => setIsInteractionEnabled(true), 150);
            return () => clearTimeout(timer);
        } else {
            setIsInteractionEnabled(false);
        }
    }, [inspectingCard, inspectingLocation, inspectingCurrency, inspectingBox, inspectingReward]);

    if (!inspectingCard && !inspectingLocation && !inspectingCurrency && !inspectingBox && !inspectingReward) return null;

    const handleBackgroundClick = () => {
        if (isInteractionEnabled) {
            closeInspector();
        }
    };

    return (
        <ModalBackdrop onClose={handleBackgroundClick}>
            {inspectingReward && (
                <SeasonRewardInspector reward={inspectingReward} />
            )}

            {inspectingBox && (
                <BoxInspector 
                    boxType={inspectingBox.boxType} 
                    title={inspectingBox.title} 
                    description={inspectingBox.description} 
                />
            )}

            {inspectingCard && (
                <CardInspector 
                    card={inspectingCard.data} 
                    user={user} 
                    onUpgrade={upgradeCard} 
                    borderOverride={inspectingCard.borderOverride}
                />
            )}

            {inspectingLocation && (
                <LocationInspector location={inspectingLocation} />
            )}

            {inspectingCurrency && (
                <CurrencyInspector 
                    type={inspectingCurrency.type} 
                    amount={inspectingCurrency.amount} 
                />
            )}
        </ModalBackdrop>
    );
};

import React from 'react';
import { CardInstance, CardDefinition, CardRarity, UserProfile } from '../../types';
import { Card } from '../Card';
import { StatHistory } from './StatHistory';
import { KeywordText } from '../ui/KeywordText';
import { SlantedButton } from '../ui/SlantedButton';

interface CardInspectorProps {
    card: CardInstance | CardDefinition;
    user: UserProfile;
    onUpgrade: (id: string) => void;
    borderOverride?: string;
}

export const CardInspector: React.FC<CardInspectorProps> = ({ card, user, onUpgrade, borderOverride }) => {
    const isInstance = (c: any): c is CardInstance => c && 'instanceId' in c;
    const def = isInstance(card) ? card.def : card as CardDefinition;

    const isOwned = user.collection.includes(def.id);
    const currentRarity = user.cardRarities[def.id] || def.rarity;
    const rarityPath: CardRarity[] = ["Common", "Rare", "Epic", "Legendary"];
    const nextRarity = rarityPath[rarityPath.indexOf(currentRarity) + 1];
    const costMap: Record<string, number> = { "Rare": 100, "Epic": 400, "Legendary": 1000 };
    const upgradeCost = nextRarity ? costMap[nextRarity] : null;

    // Authoritative Border selection: 
    // 1. Forced override (e.g. from Season context)
    // 2. Unowned white indicator
    // 3. Natural rarity (undefined fallback in Card)
    const finalBorder = borderOverride || (!isOwned ? 'white' : undefined);

    return (
        <div className="flex flex-col items-center w-full max-w-[16rem]">
            {/* CARD CONTAINER */}
            <div className="relative z-40 mb-5 shadow-[0_0_3rem_rgba(0,0,0,0.8)] w-48 aspect-[5/7]">
                {isInstance(card) && (
                    <>
                        <StatHistory modifiers={card.costModifiers} type="cost" side="left" />
                        <StatHistory modifiers={card.powerModifiers} type="power" side="right" />
                    </>
                )}
                <Card 
                    card={{ ...def, rarity: currentRarity }} 
                    size="lg" 
                    borderOverride={finalBorder}
                />
            </div>

            <div className="w-full text-center mb-4 px-1">
                <KeywordText className="text-[0.7rem]" text={isInstance(card) ? card.currentText : def.baseText} />
            </div>

            {!isInstance(card) && nextRarity && (
                <div className="w-full mb-4">
                    <SlantedButton 
                        variant="success" 
                        fullWidth 
                        size="sm"
                        onClick={(e) => { e.stopPropagation(); onUpgrade(def.id); }}
                        disabled={user.credits < (upgradeCost || 0)}
                    >
                        <div className="flex items-center justify-center gap-2">
                            <div className="flex flex-col items-start leading-none">
                                <span className="text-[0.45rem] opacity-70">UPGRADE TO</span>
                                <span className="text-[0.6rem]">{nextRarity.toUpperCase()}</span>
                            </div>
                            <div className="h-4 w-px bg-white/20"></div>
                            <span className="text-xs">{upgradeCost} CREDITS</span>
                        </div>
                    </SlantedButton>
                </div>
            )}

            {def.flavorText && (
                <div className="w-full bg-slate-900/60 border border-slate-800 rounded-lg p-2 min-h-[2.5rem] flex flex-col items-center justify-center relative group overflow-hidden">
                    <p className="text-[0.55rem] text-indigo-200/70 italic leading-tight font-mono text-center px-1">
                        "{def.flavorText}"
                    </p>
                </div>
            )}
        </div>
    );
};

