// Internal icon factory for season rewards
export const RewardIconGraphic: React.FC<{ 
    type: SeasonRewardType; 
    imageUrl?: string; 
    level?: number;
    size?: 'sm' | 'lg';
    cardDef?: CardDefinition;
}> = ({ type, imageUrl, level, size = 'sm', cardDef }) => {
    const isLarge = size === 'lg';
    const iconSize = isLarge ? 'w-10 h-10' : 'w-5 h-5';

    switch (type) {
        case 'gold': return <GoldIcon size={isLarge ? 'md' : 'sm'} />;
        case 'credits': return <CreditIcon size={isLarge ? 'md' : 'sm'} />;
        case 'card': 
            // Level 50 special handling: Render the actual Card component
            if (level === 50 && cardDef) {
                return (
                    <div className={`${isLarge ? 'w-28' : 'w-10'} aspect-[5/7] drop-shadow-2xl`}>
                        <Card 
                            card={cardDef} 
                            size={isLarge ? 'md' : 'xs'} 
                            borderOverride="white" 
                        />
                    </div>
                );
            }
            return (
                <svg className={`${iconSize} text-indigo-200`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" />
                </svg>
            );
        case 'booster': return (
            <svg className={`${iconSize} text-amber-300`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M13 10V3L4 14h7v7l9-11h-7z" />
            </svg>
        );
        default: return null;
    }
};

