import React, { useMemo, useState, useEffect, useRef } from 'react';
import { GameText } from '../ui/GameText';
import { SlantedButton } from '../ui/SlantedButton';
import { Card } from '../Card';
import { CARDS } from '../../constants';
import { useUser } from '../../contexts/UserContext';
import { SeasonMasteryHeader } from '../ui/SeasonMasteryHeader';
import { SeasonRewardButtonV2, SeasonRewardType } from '../ui/SeasonRewardButtonV2';
import { SeasonHeroSection } from '../season/SeasonHeroSection';
import { Portal } from '../ui/Portal';
import { ScreenKey } from '../../types';
import { ModalBackdrop } from '../ui/ModalBackdrop';

interface SeasonScreenProps {
    activeScreen?: ScreenKey;
}

export const SeasonScreen: React.FC<SeasonScreenProps> = ({ activeScreen }) => {
    const { inspect } = useUser();
    const scrollContainerRef = useRef<HTMLDivElement>(null);
    const activeLevelRef = useRef<HTMLDivElement>(null);

    // UI State for the Premium Modal
    const [showPremiumModal, setShowPremiumModal] = useState(false);

    // Current user level for demo purposes
    const currentLevel = 24;
    const progressPercent = 80;
    const currentXP = 800;
    const targetXP = 1000;

    // The definitive season card (e.g. Wolverine)
    const seasonCard = CARDS.find(c => c.id === 'c14') || CARDS[0];

    // Countdown Timer Logic
    const [timeLeft, setTimeLeft] = useState({ dd: '00', hh: '00', mm: '00', ss: '00' });

    useEffect(() => {
        const targetDate = new Date('2025-12-31T23:59:59').getTime();

        const updateTimer = () => {
            const now = new Date().getTime();
            const distance = targetDate - now;

            if (distance < 0) {
                setTimeLeft({ dd: '00', hh: '00', mm: '00', ss: '00' });
                return;
            }

            const days = Math.floor(distance / (1000 * 60 * 60 * 24));
            const hours = Math.floor((distance % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
            const minutes = Math.floor((distance % (1000 * 60 * 60)) / (1000 * 60));
            const seconds = Math.floor((distance % (1000 * 60)) / 1000);

            setTimeLeft({
                dd: String(days).padStart(2, '0'),
                hh: String(hours).padStart(2, '0'),
                mm: String(minutes).padStart(2, '0'),
                ss: String(seconds).padStart(2, '0')
            });
        };

        const interval = setInterval(updateTimer, 1000);
        updateTimer();
        return () => clearInterval(interval);
    }, []);

    // Auto-scroll logic: Center the active reward level whenever the screen becomes active
    useEffect(() => {
        if (activeScreen === 'SEASON') {
            const timer = setTimeout(() => {
                if (activeLevelRef.current && scrollContainerRef.current) {
                    const container = scrollContainerRef.current;
                    const activeItem = activeLevelRef.current;
                    const targetScroll = activeItem.offsetTop - (container.offsetHeight / 2) + (activeItem.offsetHeight / 2);
                    container.scrollTo({ top: targetScroll, behavior: 'smooth' });
                }
            }, 600); // Wait for spatial transition to complete
            return () => clearTimeout(timer);
        }
    }, [activeScreen, currentLevel]);

    const rewardList = useMemo(() => {
        return Array.from({ length: 100 }, (_, i) => {
            const level = i + 1;

            // Define reward distribution pattern
            let type: SeasonRewardType = 'credits';
            let amount: string | number = 50;

            // Level 50 is ALWAYS the Season Pass Card
            if (level === 50) {
                type = 'card';
                amount = 'SEASON EXCLUSIVE';
            } else if (level % 10 === 0) {
                type = 'card';
                amount = 'VARIANT';
            } else if (level % 5 === 0) {
                type = 'gold';
                amount = 100;
            } else if (level % 2 === 0) {
                type = 'booster';
                amount = 10;
            } else {
                type = 'credits';
                amount = 50 + (Math.floor(level / 10) * 10);
            }

            return {
                level,
                rewardType: type,
                rewardAmount: amount,
                rewardImageUrl: level === 50 ? seasonCard.imageUrl : undefined,
                cardDef: level === 50 ? seasonCard : undefined, // Pass full def for real rendering
                isClaimed: level < currentLevel,
                isActive: level === currentLevel,
                isLocked: level > currentLevel,
                data: level === 50 ? seasonCard : { type: 'level_info', level, rewardType: type, rewardAmount: amount }
            };
        });
    }, [currentLevel, seasonCard]);

    return (
        <div className="w-full h-full flex flex-col bg-transparent overflow-hidden relative font-sans">

            {/* 1. THEME HEADER */}
            <div className="shrink-0 flex flex-col bg-slate-900/40 backdrop-blur-md border-b border-slate-800/50 pt-1 pb-2 px-4 z-40 relative">
                <div className="flex items-center justify-between">
                    <h1 className="text-[1rem] font-black text-white italic tracking-tighter uppercase drop-shadow-lg leading-none">
                        Space Pirates
                    </h1>
                    <div className="flex items-center gap-1.5 bg-indigo-600/40 border border-indigo-500/50 px-2.5 py-0.5 rounded-sm shadow-[0_0_10px_rgba(79,70,229,0.2)]">
                        <div className="w-1.5 h-1.5 rounded-full bg-indigo-400 animate-pulse" />
                        <span className="text-[0.6rem] font-black text-white italic tracking-tighter">PREMIUM</span>
                    </div>
                </div>

                <div className="flex items-center justify-between mt-1.5 px-0.5">
                    <div className="flex items-center gap-1.5">
                         <span className="text-[0.55rem] font-black text-slate-400 uppercase tracking-widest leading-none">
                            Dec 1 - Dec 31
                        </span>
                    </div>
                    <div className="flex items-center gap-1.5">
                        <span className="text-[0.45rem] font-black text-indigo-400 uppercase leading-none mr-0.5">ENDS IN:</span>
                        <span className="text-[0.65rem] font-black text-white italic tabular-nums leading-none tracking-tight">
                            {timeLeft.dd}:{timeLeft.hh}:{timeLeft.mm}:{timeLeft.ss}
                        </span>
                    </div>
                </div>
            </div>

            {/* 2. PROGRESS BAR SECTION */}
            <SeasonMasteryHeader 
                level={currentLevel}
                progressPercent={progressPercent}
                xpText={`${currentXP} / ${targetXP} XP`}
            />

            {/* MAIN CONTENT AREA */}
            <div className="flex-1 flex-row overflow-hidden min-h-0 px-2 flex gap-x-3">

                {/* LEFT COLUMN: HERO SECTION */}
                <SeasonHeroSection 
                    seasonCard={seasonCard}
                    onInspect={inspect}
                    onGoPremium={() => setShowPremiumModal(true)}
                />

                {/* RIGHT COLUMN: REWARD TRACK */}
                <div className="flex-1 flex flex-col min-w-0">
                    <div 
                        ref={scrollContainerRef}
                        className="flex-1 overflow-y-auto pl-3 pr-2 py-4 space-y-3 scrollbar-hide pb-24"
                    >
                        {rewardList.map((reward) => (
                            <div 
                                key={reward.level} 
                                ref={reward.isActive ? activeLevelRef : null}
                                className="relative w-full overflow-visible"
                            >
                                <SeasonRewardButtonV2 
                                    level={reward.level}
                                    progressPercent={reward.isActive ? progressPercent : (reward.isClaimed ? 100 : 0)}
