import React from 'react';
import { CreditIcon, GoldIcon } from './CurrencyIcons';
import { CardDefinition } from '../../types';
import { Card } from '../Card';

export type SeasonRewardType = 'gold' | 'credits' | 'card' | 'booster';

interface RewardItemVisualProps {
    type: SeasonRewardType;
    amount?: string | number;
    imageUrl?: string;
    level?: number;
    className?: string;
    size?: 'sm' | 'lg';
    cardDef?: CardDefinition; // Added to support real card rendering
}

/**
 * RewardItemVisual
 * A standalone component combining a high-impact icon and its identifying text.
 */
export const RewardItemVisual: React.FC<RewardItemVisualProps> = ({ 
    type, 
    amount, 
    imageUrl, 
    level, 
    className = "",
    size = 'sm',
    cardDef
}) => {
    const isLarge = size === 'lg';
    // Hide text specifically for card rewards as the card component provides its own labels
    const shouldHideText = type === 'card';

    return (
        <div className={`flex flex-col items-center justify-center pointer-events-none ${className}`}>
            {/* ICON LAYER - Scaled for impact */}
            <div className={`${isLarge ? '' : 'scale-110'} drop-shadow-[0_2px_4px_rgba(0,0,0,0.8)] transition-transform duration-500`}>
                <RewardIconGraphic type={type} imageUrl={imageUrl} level={level} size={size} cardDef={cardDef} />
            </div>

            {/* TEXT LABEL LAYER */}
            {amount && !shouldHideText && (
                <div className={`${isLarge ? 'mt-12' : 'mt-[0.4rem]'} flex flex-col items-center justify-center leading-none`}>
                    <span className={`${isLarge ? 'text-lg text-white' : 'text-[0.52rem] text-white'} font-black uppercase tracking-tighter drop-shadow-[0_1px_2px_rgba(0,0,0,1)]`}>
                        {amount} {type}
                    </span>
                </div>
            )}
        </div>
    );
};

// Internal icon factory for season rewards
export const RewardIconGraphic: React.FC<{ 
    type: SeasonRewardType; 
    imageUrl?: string; 
    level?: number;
    size?: 'sm' | 'lg';
    cardDef?: CardDefinition;
}> = ({ type, imageUrl, level, size = 'sm', cardDef }) => {
    const isLarge = size === 'lg';
    const iconSize = isLarge ? 'w-10 h-10' : 'w-5 h-5';

    switch (type) {
        case 'gold': return <GoldIcon size={isLarge ? 'md' : 'sm'} />;
        case 'credits': return <CreditIcon size={isLarge ? 'md' : 'sm'} />;
        case 'card': 
            // If we have a card definition, render the card UI
            if (cardDef) {
                return (
                    <div className={`${isLarge ? 'w-28' : 'w-10'} aspect-[5/7] drop-shadow-2xl`}>
                        <Card 
                            card={cardDef} 
                            size={isLarge ? 'md' : 'xs'} 
                            borderOverride="white" 
                        />
                    </div>
                );
            }
            return (
                <svg className={`${iconSize} text-indigo-200`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" />
                </svg>
            );
        case 'booster': return (
