import React from 'react';
import { GameText } from '../ui/GameText';

interface CardBadgeProps {
    value: number;
    type: 'cost' | 'power';
    colorClass: string;
    scale: number;
}

export const CardBadge: React.FC<CardBadgeProps> = ({ value, type, colorClass, scale }) => {
    const isCost = type === 'cost';

    // Geometry based on card scale - converted to REM (base 16)
    // 32px -> 2rem, 22px -> 1.375rem, 2px -> 0.125rem
    const size = 2 * scale; 
    const fontSize = 22 * scale; // GameText handles the px-to-rem measurement internally

    const position = isCost 
        ? { top: `${-0.125 * scale}rem`, left: `${-0.125 * scale}rem` } 
        : { top: `${-0.125 * scale}rem`, right: `${-0.125 * scale}rem` };

    const gradientId = `grad_${type}`;
    const bgColor = isCost ? '#2563eb' : '#dc2626'; // blue-600 : red-600
    const strokeColor = isCost ? '#60a5fa' : '#f87171'; // blue-400 : red-400

    // Dynamic stroke width: Thinner on small scales to prevent "blobbing"
    const strokeWidth = scale < 0.6 ? 3 : 4;

    return (
        <div 
            className="absolute z-30 pointer-events-none"
            style={{ 
                width: `${size}rem`, 
                height: `${size}rem`,
                filter: `drop-shadow(0 ${0.1 * scale}rem ${0.15 * scale}rem rgba(0,0,0,0.6))`,
                ...position
            }}
        >
            <svg viewBox="0 0 100 100" className="w-full h-full">
                <defs>
                    <linearGradient id={gradientId} x1="0" y1="0" x2="0" y2="1">
                        <stop offset="0%" stopColor={strokeColor} />
                        <stop offset="100%" stopColor={bgColor} />
                    </linearGradient>
                </defs>
                {/* Hexagon shape for the badge */}
                <path 
                    d="M50 5 L95 25 L95 75 L50 95 L5 75 L5 25 Z" 
                    fill={bgColor}
                    stroke="rgba(255,255,255,0.5)"
                    strokeWidth={strokeWidth}
                />
            </svg>

            <div className="absolute inset-0 flex items-center justify-center pt-[5%]">
                <div className={`w-[75%] h-[75%] ${colorClass}`}>
                    <GameText 
                        text={value.toString()} 
                        baseFontSize={fontSize} 
                        className="font-black italic" 
                    />
                </div>
            </div>
        </div>
    );
};

import React from 'react';
import { CardDefinition, CardInstance } from '../../types';
import { getCardVisualState } from '../../utils/cardStyles';
