                    height: '35%',
                    paddingBottom: '0.3em',
                    paddingLeft: '0.4em',
                    paddingRight: '0.4em'
                }}
            >
                 <div className="w-full h-[35%]">
                    <GameText 
                        text={def.name} 
                        baseFontSize={18} // Interpreted as px-equivalent at scale 1.0
