import React, { useState, useLayoutEffect, useRef, useEffect, useCallback } from 'react';

interface GameTextProps {
  text: string;
  className?: string;
  /** The "Aspirational" font size in PX (at scale 1.0). */
  baseFontSize: number;
  /** How much we allow the text to shrink. 0.3 is usually the limit for legibility. */
  minScale?: number;
  /** If > 1, allows the text to wrap and scales based on both width and height. */
  maxLines?: number;
}

export const GameText: React.FC<GameTextProps> = ({ 
  text, 
  className = '', 
  baseFontSize, 
  minScale = 0.3,
  maxLines = 1
}) => {
  const [layout, setLayout] = useState<{ lines: string[], scale: number }>({ 
      lines: [text || ''], 
      scale: 1 
  });
  const containerRef = useRef<HTMLDivElement>(null);
  const ghostRef = useRef<HTMLDivElement>(null);

  const findBestLayout = useCallback(() => {
    const container = containerRef.current;
    const ghost = ghostRef.current;
    if (!container || !ghost || !text) return;

    const containerWidth = container.offsetWidth;
    const containerHeight = container.offsetHeight;

    if (containerWidth <= 0 || containerHeight <= 0) return;

    // In the new 'em' system, the container's physical width varies based on scale.
    // We measure relative to that physical container.
    const words = text.split(/\s+/);

    const splitIntoLines = (numLines: number): string[] => {
      if (numLines <= 1 || words.length <= 1) return [text];
      const targetCharsPerLine = text.length / numLines;
      const result: string[][] = Array.from({ length: numLines }, () => []);
      let currentLine = 0;
      let currentChars = 0;

      words.forEach((word) => {
        if (currentLine < numLines - 1) {
            const distIfStay = Math.abs((currentChars + word.length) - targetCharsPerLine);
            const distIfMove = Math.abs(currentChars - targetCharsPerLine);
            if (currentChars > 0 && distIfMove < distIfStay) {
                currentLine++;
                currentChars = 0;
            }
        }
        result[currentLine].push(word);
        currentChars += word.length + 1;
      });

      return result.map(l => l.join(' ')).filter(s => s.length > 0);
    };

    const measureLayout = (lines: string[]) => {
      ghost.innerHTML = lines.map(l => `<div>${l}</div>`).join('');
      // Set ghost font size to the aspirational px value
      ghost.style.fontSize = `${baseFontSize}px`;

      const ghostWidth = ghost.offsetWidth;
      const ghostHeight = ghost.offsetHeight;

      if (ghostWidth <= 0 || ghostHeight <= 0) return 0;

      const widthRatio = (containerWidth / ghostWidth) * 0.98;
      const heightRatio = (containerHeight / ghostHeight) * 0.98;

      return Math.min(1, widthRatio, heightRatio);
    };

    let bestScale = 0;
    let bestLines: string[] = [text];
    const limit = Math.min(maxLines, 4); 

    for (let i = 1; i <= limit; i++) {
      if (i > words.length) break;
      const candidateLines = splitIntoLines(i);
      const scale = measureLayout(candidateLines);
      const bias = (limit - i) * 0.02; 
      if (scale + bias > bestScale) {
        bestScale = scale;
        bestLines = candidateLines;
      }
      if (i === 1 && scale > 0.95) break;
    }

    setLayout({ 
        lines: bestLines, 
        scale: Math.max(minScale, bestScale) 
    });
  }, [text, baseFontSize, minScale, maxLines]);

  useLayoutEffect(() => {
    findBestLayout();
    const observer = new ResizeObserver(() => {
        // Optimization: Use RAF to prevent "ResizeObserver loop limit exceeded"
        requestAnimationFrame(findBestLayout);
    });
    if (containerRef.current) observer.observe(containerRef.current);
    return () => observer.disconnect();
  }, [findBestLayout]);

  useEffect(() => {
    if (!('fonts' in document)) return;
    const handleFontLoad = () => requestAnimationFrame(() => findBestLayout());
    document.fonts.addEventListener('loadingdone', handleFontLoad);
    return () => document.fonts.removeEventListener('loadingdone', handleFontLoad);
  }, [findBestLayout]);

  if (!text) return null;

  return (
    <div 
      ref={containerRef} 
      className={`w-full h-full flex justify-center items-center relative leading-none overflow-hidden font-sans ${className}`}
    >
      {/* Invisible ghost for measurement */}
      <div
        ref={ghostRef}
        className={`absolute opacity-0 pointer-events-none flex flex-col items-center ${className}`}
        style={{ fontSize: `${baseFontSize}px`, left: -9999, whiteSpace: 'nowrap' }}
      />

      {/* Scaled visible text */}
      <div
        style={{ 
          transformOrigin: 'center center',
          transform: `scale(${layout.scale})`,
          fontSize: `${baseFontSize}px`,
          width: 'max-content',
          minWidth: '100%'
        }}
        className="flex flex-col items-center justify-center leading-none"
      >
        {layout.lines.map((line, idx) => (
            <div key={idx} className="whitespace-nowrap">
                {line}
            </div>
        ))}
      </div>
    </div>
  );
};

import React from 'react';
import { useGame } from '../contexts/GameContext';
import { Card } from './Card';

export const PlayerHand: React.FC = () => {
    const { gameState, pendingMoves, dragState, actions } = useGame();

    const visibleCards = gameState.players.p1.hand
        .map((card, index) => ({ card, originalIndex: index }))
        .filter(({ card }) => !pendingMoves.some(m => m.cardInstanceId === card.instanceId));

    const count = visibleCards.length;

    /**
     * HAND SPACING LOGIC
     * Using strict max-widths and small gaps to prevent 'the snap' 
     * when the hand count changes.
     */
    let gapClass = 'gap-1';
    let wrapperWidthClass = 'max-w-[3.4rem]';

    if (count <= 3) {
        gapClass = 'gap-3';
        wrapperWidthClass = 'max-w-[4rem]';
    } else if (count >= 6) {
        gapClass = 'gap-0.5';
        wrapperWidthClass = 'max-w-[2.8rem]';
    }

    return (
        <div 
            className="flex-none flex items-center justify-center px-2 py-0.5 min-h-[4.2rem] overflow-visible"
            data-drop-zone="hand"
        >
            <div className={`flex items-center justify-center w-full max-w-lg h-full transition-all duration-300 ${gapClass}`}>
                {visibleCards.map(({ card, originalIndex }) => {
                    const isDraggingThis = dragState?.active && dragState.card.instanceId === card.instanceId && dragState.origin.type === 'hand';

                    return (
                        <div 
                            key={card.instanceId} 
                            className={`
                                flex-1 min-w-0 ${wrapperWidthClass} transition-all duration-200 
                                ${isDraggingThis ? 'opacity-0' : ''}
                            `}
                        >
                            <div className="w-full aspect-[5/7]">
                                <Card 
                                    card={card} 
                                    size="sm" 
                                    onClick={() => actions.handleCardClick(originalIndex, !!dragState?.active)}
                                    onPointerDown={(e) => actions.handleCardPointerDownHand(e, card, originalIndex)}
                                />
                            </div>
                        </div>
                    );
                })}
            </div>
        </div>
    );
};

import React from 'react';
import { CardInstance, CardDefinition, CardRarity, UserProfile } from '../../types';
import { Card } from '../Card';
import { StatHistory } from './StatHistory';
import { KeywordText } from '../ui/KeywordText';
import { SlantedButton } from '../ui/SlantedButton';

interface CardInspectorProps {
    card: CardInstance | CardDefinition;
    user: UserProfile;
    onUpgrade: (id: string) => void;
    borderOverride?: string;
}

export const CardInspector: React.FC<CardInspectorProps> = ({ card, user, onUpgrade, borderOverride }) => {
    const isInstance = (c: any): c is CardInstance => c && 'instanceId' in c;
    const def = isInstance(card) ? card.def : card as CardDefinition;

    const isOwned = user.collection.includes(def.id);
    const currentRarity = user.cardRarities[def.id] || def.rarity;
    const rarityPath: CardRarity[] = ["Common", "Rare", "Epic", "Legendary"];
    const nextRarity = rarityPath[rarityPath.indexOf(currentRarity) + 1];
    const costMap: Record<string, number> = { "Rare": 100, "Epic": 400, "Legendary": 1000 };
    const upgradeCost = nextRarity ? costMap[nextRarity] : null;

    const finalBorder = borderOverride || (!isOwned ? 'white' : undefined);

    return (
        <div className="flex flex-col items-center w-full max-w-[18rem] animate-pop">
            {/* 
                CARD HERO AREA 
                Uses flex-center to ensure the lg card (which has its own internal width)
                is perfectly aligned regardless of the container's max-width.
            */}
            <div className="relative flex items-center justify-center mb-8 w-full">
                <div className="relative z-40 shadow-[0_0_4rem_rgba(0,0,0,0.9)]">
                    {isInstance(card) && (
                        <>
                            {/* Adjusted StatHistory to sit tighter to the card visual bounds */}
                            <div className="absolute -left-1 top-0 bottom-0 pointer-events-none z-50">
                                <StatHistory modifiers={card.costModifiers} type="cost" side="left" />
                            </div>
                            <div className="absolute -right-1 top-0 bottom-0 pointer-events-none z-50">
                                <StatHistory modifiers={card.powerModifiers} type="power" side="right" />
                            </div>
                        </>
                    )}
                    <Card 
                        card={{ ...def, rarity: currentRarity }} 
                        size="lg" 
                        borderOverride={finalBorder}
                    />
                </div>
            </div>

            {/* EFFECT TEXT */}
            <div className="w-full text-center mb-6 px-4 min-h-[2.5rem] flex items-center justify-center">
                <KeywordText 
                    className="text-[0.75rem] leading-relaxed" 
                    text={isInstance(card) ? card.currentText : def.baseText} 
                />
            </div>

            {/* UPGRADE ACTION */}
            {!isInstance(card) && nextRarity && (
                <div className="w-full mb-6 px-4">
                    <SlantedButton 
                        variant="success" 
                        fullWidth 
                        size="md"
                        onClick={(e) => { e.stopPropagation(); onUpgrade(def.id); }}
                        disabled={user.credits < (upgradeCost || 0)}
                    >
                        <div className="flex items-center justify-center gap-3">
                            <div className="flex flex-col items-start leading-none py-1">
                                <span className="text-[0.5rem] opacity-70 font-black tracking-widest">UPGRADE TO</span>
                                <span className="text-[0.7rem] font-bold">{nextRarity.toUpperCase()}</span>
                            </div>
                            <div className="h-6 w-px bg-white/20"></div>
                            <span className="text-sm font-black italic tabular-nums">{upgradeCost} CREDITS</span>
                        </div>
                    </SlantedButton>
                </div>
            )}

            {/* FLAVOR TEXT */}
            {def.flavorText && (
                <div className="w-full px-6">
                    <div className="bg-slate-900/40 border-y border-white/5 py-3 flex flex-col items-center justify-center">
                        <p className="text-[0.6rem] text-indigo-300/50 italic leading-tight font-sans text-center max-w-[90%]">
                            "{def.flavorText}"
                        </p>
                    </div>
                </div>
            )}
        </div>
    );
};

import React from 'react';
import { StatModifier } from '../../types';

interface StatHistoryProps {
    modifiers: StatModifier[];
    type: 'cost' | 'power';
    side: 'left' | 'right';
}

export const StatHistory: React.FC<StatHistoryProps> = ({ modifiers, type, side }) => {

    const renderStatModifier = (m: StatModifier) => {
        const isBase = m.type === 'BASE';
        let valueColor = 'text-white';
        let sign = '';

        if (!isBase) {
            if (type === 'power') {
                if (m.value > 0) { valueColor = 'text-emerald-400'; sign = '+'; }
                if (m.value < 0) { valueColor = 'text-red-400'; }
            } else {
                if (m.value > 0) { valueColor = 'text-red-400'; sign = '+'; }
                if (m.value < 0) { valueColor = 'text-emerald-400'; }
            }
        }

        return (
            <div className="flex justify-between items-center w-full mb-0.5 last:mb-0 bg-black/60 rounded-[2px] px-1.5 py-1 border border-white/5">
                <span className="text-slate-400 text-[0.45rem] font-bold uppercase tracking-tight truncate max-w-[3.5rem]">
                    {m.source}
                </span>
                <span className={`font-black text-[0.65rem] leading-none italic ${valueColor}`}>
                    {sign}{m.value}
                </span>
            </div>
        );
    };

    // Positioned relative to the card's visual bounds
    const positionClass = side === 'left' 
        ? "right-full mr-1" 
        : "left-full ml-1";

    return (
        <div className={`absolute top-1/2 -translate-y-1/2 ${positionClass} w-24 pointer-events-auto z-[60]`}>
             <div className="bg-slate-900/95 border border-white/10 rounded-lg p-1 shadow-2xl flex flex-col max-h-40 overflow-y-auto">
                <div className="flex flex-col gap-0.5">
                    {modifiers.map((m, i) => (
                        <React.Fragment key={i}>
                            {renderStatModifier(m)}
                        </React.Fragment>
                    ))}
                </div>
             </div>
        </div>
    );
};

