import React, { useState, useLayoutEffect, useRef, useEffect, useCallback } from 'react';

interface GameTextProps {
  text: string;
  className?: string;
  /** 
   * RELATIVE SCALE BASIS
   * Interpreted as 'em'. (e.g. 1.0 = same size as parent font, 1.2 = 20% larger)
   */
  baseFontSize: number;
  /** How much we allow the text to shrink. */
  minScale?: number;
  /** Max lines for wrapping. */
  maxLines?: number;
}

export const GameText: React.FC<GameTextProps> = ({ 
  text, 
  className = '', 
  baseFontSize, 
  minScale = 0.3,
  maxLines = 1
}) => {
  const [layout, setLayout] = useState<{ lines: string[], scale: number, finalPx: number }>({ 
      lines: [text || ''], 
      scale: 1,
      finalPx: 16
  });
  const containerRef = useRef<HTMLDivElement>(null);
  const ghostRef = useRef<HTMLDivElement>(null);

  const findBestLayout = useCallback(() => {
    const container = containerRef.current;
    const ghost = ghostRef.current;
    if (!container || !ghost || !text) return;

    const containerWidth = container.offsetWidth;
    const containerHeight = container.offsetHeight;

    if (containerWidth <= 0 || containerHeight <= 0) return;

    // 1. Calculate the 'Aspirational' Pixel Size
    // We measure the container's font size (which is the card's master scale)
    const parentStyle = window.getComputedStyle(container);
    const parentPx = parseFloat(parentStyle.fontSize) || 16;
    const targetPx = parentPx * baseFontSize;

    const words = text.split(/\s+/);

    const splitIntoLines = (numLines: number): string[] => {
      if (numLines <= 1 || words.length <= 1) return [text];
      const targetCharsPerLine = text.length / numLines;
      const result: string[][] = Array.from({ length: numLines }, () => []);
      let currentLine = 0;
      let currentChars = 0;

      words.forEach((word) => {
        if (currentLine < numLines - 1) {
            const distIfStay = Math.abs((currentChars + word.length) - targetCharsPerLine);
            const distIfMove = Math.abs(currentChars - targetCharsPerLine);
            if (currentChars > 0 && distIfMove < distIfStay) {
                currentLine++;
                currentChars = 0;
            }
        }
        result[currentLine].push(word);
        currentChars += word.length + 1;
      });

      return result.map(l => l.join(' ')).filter(s => s.length > 0);
    };

    const measureLayout = (lines: string[]) => {
      ghost.innerHTML = lines.map(l => `<div>${l}</div>`).join('');
      ghost.style.fontSize = `${targetPx}px`;

      const ghostWidth = ghost.offsetWidth;
      const ghostHeight = ghost.offsetHeight;

      if (ghostWidth <= 0 || ghostHeight <= 0) return 0;

      const widthRatio = (containerWidth / ghostWidth) * 0.98;
      const heightRatio = (containerHeight / ghostHeight) * 0.98;

      // REMOVED: Math.min(1, ...)
      // We want text to fill its allocated space proportionally at any card size.
      return Math.min(widthRatio, heightRatio);
    };

    let bestScale = 0;
    let bestLines: string[] = [text];
    const limit = Math.min(maxLines, 4); 

    for (let i = 1; i <= limit; i++) {
      if (i > words.length) break;
      const candidateLines = splitIntoLines(i);
      const scale = measureLayout(candidateLines);
      const bias = (limit - i) * 0.05; 
      if (scale + bias > bestScale) {
        bestScale = scale;
        bestLines = candidateLines;
      }
      // If we fill the box perfectly on 1 line, stop early
      if (i === 1 && scale > 0.98 && scale < 1.05) break;
    }

    setLayout({ 
        lines: bestLines, 
        scale: Math.max(minScale, bestScale),
        finalPx: targetPx
    });
  }, [text, baseFontSize, minScale, maxLines]);

  useLayoutEffect(() => {
    findBestLayout();
    const observer = new ResizeObserver(() => requestAnimationFrame(findBestLayout));
    if (containerRef.current) observer.observe(containerRef.current);
    return () => observer.disconnect();
  }, [findBestLayout]);

  useEffect(() => {
    if (!('fonts' in document)) return;
    const handleFontLoad = () => requestAnimationFrame(() => findBestLayout());
    document.fonts.addEventListener('loadingdone', handleFontLoad);
    return () => document.fonts.removeEventListener('loadingdone', handleFontLoad);
  }, [findBestLayout]);

  if (!text) return null;

  return (
    <div 
      ref={containerRef} 
      className={`w-full h-full flex justify-center items-center relative leading-none overflow-hidden font-sans ${className}`}
    >
      <div
        ref={ghostRef}
        className={`absolute opacity-0 pointer-events-none flex flex-col items-center ${className}`}
        style={{ fontSize: `${layout.finalPx}px`, left: -9999, whiteSpace: 'nowrap' }}
      />
      <div
        style={{ 
          transformOrigin: 'center center',
          transform: `scale(${layout.scale})`,
          fontSize: `${layout.finalPx}px`,
          width: 'max-content',
          minWidth: '100%'
        }}
        className="flex flex-col items-center justify-center leading-none"
      >
        {layout.lines.map((line, idx) => (
            <div key={idx} className="whitespace-nowrap">
                {line}
            </div>
        ))}
      </div>
    </div>
  );
};

import React from 'react';
import { CardDefinition, CardInstance } from '../../types';
import { getCardVisualState } from '../../utils/cardStyles';
import { CardBadge } from './CardBadge';
import { GameText } from '../ui/GameText';

interface UnifiedCardViewProps {
    card: CardInstance | CardDefinition;
    size: 'xs' | 'sm' | 'md' | 'lg';
    hidden?: boolean;
    isDragging?: boolean;
    onPointerDown?: (e: React.PointerEvent) => void;
    onClick?: () => void;
    borderOverride?: string;
}

/**
 * UNIFIED PROPORTIONAL ENGINE (EM-BASED)
 * 
 * Design Basis:
 * - 1em = The card's current scale.
 * - Internal UI elements are defined in 'em' so they grow/shrink 
 *   perfectly with the container's font-size.
 */
const SCALE_MAP = {
    xs: 0.5,   // Board
    sm: 0.75,  // Hand
    md: 1.0,   // Standard
    lg: 1.8    // Inspector
};

export const UnifiedCardView: React.FC<UnifiedCardViewProps> = ({
    card, size, hidden, isDragging, onPointerDown, onClick, borderOverride
}) => {
    const scale = SCALE_MAP[size];
    const { 
        def, currentPower, currentCost, 
        powerColor, costColor, primaryColor, glowColor 
    } = getCardVisualState(card);

    // Base card width at md scale
    const baseWidth = 5.2; // rem

    if (hidden) {
        return (
            <div 
                className="w-full h-full bg-indigo-950 flex items-center justify-center overflow-hidden shadow-inner cursor-pointer"
                style={{ 
                    fontSize: `${scale}rem`,
                    borderRadius: '0.5em',
                    border: '0.15em solid rgba(129, 140, 248, 0.4)',
                    aspectRatio: '5/7'
                }}
                onPointerDown={onPointerDown}
                onClick={onClick}
            >
                <div className="w-1/2 h-1/2 rounded-full bg-indigo-500/20 animate-pulse blur-xl" />
                <div className="absolute font-black text-indigo-300/30 italic rotate-[-45deg] tracking-tighter" style={{ fontSize: '1.5em' }}>SNAP</div>
            </div>
        );
    }

    const finalBorderColor = borderOverride || primaryColor;

    return (
        <div
            onPointerDown={onPointerDown}
            onClick={onClick}
            className={`
                relative select-none touch-none overflow-hidden transition-opacity duration-200 group
                ${isDragging ? 'opacity-0' : 'opacity-100'}
            `}
            style={{ 
                width: `${baseWidth * scale}rem`,
                fontSize: `${scale}rem`, // Master scale for all 'em' units
                aspectRatio: '5/7',
                borderRadius: '0.45em',
                boxShadow: `0 0 0.6em ${glowColor}, inset 0 0 0.5em rgba(0,0,0,0.6)`,
                border: `0.18em solid ${finalBorderColor}`,
                backgroundColor: '#0f172a'
            }}
        >
            {/* 1. Art Layer */}
            <div className="absolute inset-0 bg-black">
                <img 
                    src={def.imageUrl} 
                    alt={def.name} 
                    className="w-full h-full object-cover pointer-events-none transition-transform duration-700 [@media(hover:hover)]:group-hover:scale-105 opacity-90" 
                />
            </div>

            {/* 2. Polish Overlays */}
            <div className="absolute inset-0 bg-gradient-to-b from-black/20 via-transparent to-black/70 pointer-events-none" />
            <div className="absolute inset-0 border border-white/10 pointer-events-none rounded-[inherit]" />

            {/* 3. Badges */}
            <CardBadge value={currentCost} type="cost" colorClass={costColor} />
            <CardBadge value={currentPower} type="power" colorClass={powerColor} />

            {/* 4. Nameplate Overlay */}
            <div 
                className="absolute inset-x-0 pointer-events-none flex flex-col items-center justify-end bg-gradient-to-t from-black via-black/90 to-transparent"
                style={{ 
                    bottom: 0,
                    height: '35%',
                    paddingBottom: '0.3em',
                    paddingLeft: '0.45em',
                    paddingRight: '0.45em'
                }}
            >
                 <div className="w-full h-[35%]">
                    <GameText 
                        text={def.name} 
                        baseFontSize={1.15} // 1.15em (proportional to card scale)
                        className="font-black italic uppercase tracking-tighter text-white drop-shadow-[0_2px_4px_rgba(0,0,0,1)]"
                    />
                 </div>
            </div>
        </div>
    );
};

