import React from 'react';
import { CardInstance, CardDefinition, CardRarity, UserProfile } from '../../types';
import { Card } from '../Card';
import { StatHistory } from './StatHistory';
import { KeywordText } from '../ui/KeywordText';
import { SlantedButton } from '../ui/SlantedButton';

interface CardInspectorProps {
    card: CardInstance | CardDefinition;
    user: UserProfile;
    onUpgrade: (id: string) => void;
    borderOverride?: string;
}

export const CardInspector: React.FC<CardInspectorProps> = ({ card, user, onUpgrade, borderOverride }) => {
    const isInstance = (c: any): c is CardInstance => c && 'instanceId' in c;
    const def = isInstance(card) ? card.def : card as CardDefinition;

    const isOwned = user.collection.includes(def.id);
    const currentRarity = user.cardRarities[def.id] || def.rarity;
    const rarityPath: CardRarity[] = ["Common", "Rare", "Epic", "Legendary"];
    const nextRarity = rarityPath[rarityPath.indexOf(currentRarity) + 1];
    const costMap: Record<string, number> = { "Rare": 100, "Epic": 400, "Legendary": 1000 };
    const upgradeCost = nextRarity ? costMap[nextRarity] : null;

    const finalBorder = borderOverride || (!isOwned ? 'white' : undefined);

    return (
        <div className="flex flex-col items-center w-full max-w-[18rem] animate-pop">
            {/* 1. HERO AREA */}
            <div className="relative flex items-center justify-center mb-8 w-full">
                <div className="relative z-40 shadow-[0_0_5rem_rgba(0,0,0,1)]">
                    {isInstance(card) && (
                        <>
                            <div className="absolute -left-1 top-0 bottom-0 pointer-events-none z-50">
                                <StatHistory modifiers={card.costModifiers} type="cost" side="left" />
                            </div>
                            <div className="absolute -right-1 top-0 bottom-0 pointer-events-none z-50">
                                <StatHistory modifiers={card.powerModifiers} type="power" side="right" />
                            </div>
                        </>
                    )}
                    <Card 
                        card={{ ...def, rarity: currentRarity }} 
                        size="lg" 
                        borderOverride={finalBorder}
                    />
                </div>
            </div>

            {/* 2. ABILITY BOX */}
            <div className="w-full text-center mb-6 px-4 flex items-center justify-center">
                <KeywordText 
                    className="text-[0.8rem] leading-snug" 
                    text={isInstance(card) ? card.currentText : def.baseText} 
                />
            </div>

            {/* 3. ACTIONS */}
            {!isInstance(card) && nextRarity && (
                <div className="w-full mb-8 px-4">
                    <SlantedButton 
                        variant="success" 
                        fullWidth 
                        size="md"
                        onClick={(e) => { e.stopPropagation(); onUpgrade(def.id); }}
                        disabled={user.credits < (upgradeCost || 0)}
                    >
                        <div className="flex items-center justify-center gap-3">
                            <div className="flex flex-col items-start leading-none py-1">
                                <span className="text-[0.5rem] opacity-70 font-black tracking-widest">UPGRADE TO</span>
                                <span className="text-[0.7rem] font-bold">{nextRarity.toUpperCase()}</span>
                            </div>
                            <div className="h-6 w-px bg-white/20"></div>
                            <span className="text-sm font-black italic tabular-nums">{upgradeCost} CREDITS</span>
                        </div>
                    </SlantedButton>
                </div>
            )}

            {/* 4. FLAVOR SLATE (The fix for "background trash") */}
            {def.flavorText && (
                <div className="w-full px-6">
                    <div className="relative p-[1px] bg-indigo-500/20 rounded-sm">
                        <div className="bg-slate-950/80 p-3 rounded-sm flex flex-col items-center justify-center shadow-inner border border-white/5">
                            <div className="w-6 h-0.5 bg-indigo-500/30 mb-2 rounded-full" />
                            <p className="text-[0.6rem] text-indigo-200/50 italic leading-relaxed font-sans text-center max-w-[90%] tracking-tight">
                                "{def.flavorText}"
                            </p>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

import React, { useState, useRef, useEffect } from 'react';
import { GameText } from './GameText';

type ButtonVariant = 'primary' | 'secondary' | 'success' | 'danger' | 'warning' | 'blue';

interface SlantedButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
    variant?: ButtonVariant;
    fullWidth?: boolean;
    size?: 'sm' | 'md' | 'lg';
    icon?: React.ReactNode;
    holdDuration?: number; 
    onHoldChange?: (isHolding: boolean) => void;
    onProgressChange?: (progress: number) => void;
}

export const SlantedButton: React.FC<SlantedButtonProps> = ({ 
    children, 
    variant = 'primary', 
    fullWidth = false,
    size = 'md',
    icon,
    className = '',
    holdDuration = 0,
    onHoldChange,
    onProgressChange,
    onClick,
    ...props 
}) => {
    const [progress, setProgress] = useState(0);
    const [isHolding, setIsHolding] = useState(false);
    const timerRef = useRef<number | null>(null);
    const startTimeRef = useRef<number>(0);

    const variants = {
        primary: "from-purple-600 to-purple-900 border-purple-400 shadow-[0_0.2rem_0_rgb(88,28,135)]",
        secondary: "from-slate-700 to-slate-900 border-slate-500 shadow-[0_0.2rem_0_rgb(15,23,42)]",
        success: "from-emerald-600 to-emerald-900 border-emerald-400 shadow-[0_0.2rem_0_rgb(6,78,59)]",
        danger: "from-red-600 to-red-900 border-red-400 shadow-[0_0.2rem_0_rgb(127,29,29)]",
        warning: "from-amber-600 to-amber-900 border-amber-400 shadow-[0_0.2rem_0_rgb(120,53,15)]",
        blue: "from-blue-600 to-blue-900 border-blue-400 shadow-[0_0.2rem_0_rgb(30,58,138)]",
    };

    /**
     * RELATIVE UI SCALING
     * baseFontSize is now an 'em' multiplier relative to the 1.3x root font size.
     */
    const sizeConfigs = {
        sm: { height: "h-7", fontSize: 0.85, padding: "px-0.5" },
        md: { height: "h-10", fontSize: 1.0, padding: "px-[3px]" },
        lg: { height: "h-14", fontSize: 1.3, padding: "px-1" }
    };

    const config = sizeConfigs[size];

    const startHold = (e: React.PointerEvent) => {
        if (!holdDuration || props.disabled) return;

        setIsHolding(true);
        onHoldChange?.(true);
        startTimeRef.current = Date.now();

        timerRef.current = window.setInterval(() => {
            const elapsed = Date.now() - startTimeRef.current;
            const p = Math.min((elapsed / holdDuration) * 100, 100);
            setProgress(p);
            onProgressChange?.(p);

            if (p >= 100) {
                if (timerRef.current) clearInterval(timerRef.current);
                timerRef.current = null;

                setProgress(100);
                onProgressChange?.(100);

                setTimeout(() => {
                    if (onClick) {
                        const syntheticEvent = { 
                            clientX: e.clientX,
                            clientY: e.clientY,
                            target: e.target,
                            currentTarget: e.currentTarget,
                            type: 'click',
                            bubbles: true,
                            cancelable: true,
                            nativeEvent: e.nativeEvent,
                        } as unknown as React.MouseEvent<HTMLButtonElement>;
                        onClick(syntheticEvent);
                    }
                    setIsHolding(false);
                    onHoldChange?.(false);
                    setProgress(0);
                    onProgressChange?.(0);
                }, 60);
            }
        }, 16);
    };

    const cancelHold = () => {
        if (timerRef.current) {
            clearInterval(timerRef.current);
            timerRef.current = null;
        }
        setIsHolding(false);
        onHoldChange?.(false);
        setProgress(0);
        onProgressChange?.(0);
    };

    useEffect(() => {
        return () => {
            if (timerRef.current) clearInterval(timerRef.current);
        };
    }, []);

    const widthOverride = className.match(/w-\[?[\w.%]+\]?/)?.[0] || '';
    const widthClass = fullWidth ? 'w-full' : (widthOverride ? widthOverride : 'w-max');
    const textShadowClass = "drop-shadow-[0_2px_3px_rgba(0,0,0,0.8)]";

    return (
        <div className={`relative group ${widthClass} ${config.height} ${props.disabled ? 'opacity-50 pointer-events-none' : ''}`}>
            <button 
                className={`w-full h-full relative z-10 active:translate-y-0.5 transition-all outline-none ${className}`}
                onPointerDown={holdDuration ? startHold : undefined}
                onPointerUp={holdDuration ? cancelHold : undefined}
                onPointerLeave={holdDuration ? cancelHold : undefined}
                onClick={holdDuration ? undefined : onClick}
                role="button"
                aria-busy={isHolding}
                {...props}
            >
                <div className={`
                    absolute inset-0 bg-gradient-to-b border rounded skew-x-[-10deg] 
                    [@media(hover:hover)]:group-hover:brightness-110 transition-all duration-200 overflow-hidden
                    ${variants[variant]}
                `}>
                    {holdDuration > 0 && (
                        <div 
                            className="absolute inset-y-0 left-0 bg-white/20 transition-all duration-75 ease-linear pointer-events-none"
                            style={{ width: `${progress}%` }}
                        />
                    )}
                </div>

                <div className={`relative z-20 skew-x-[-10deg] ${config.padding} flex items-center justify-center h-full pointer-events-none`}>
                    <div className={`flex items-center justify-center h-full transition-opacity ${isHolding ? 'opacity-40' : 'opacity-100'} ${children ? 'w-full gap-1' : ''}`}>
                        {icon && (
                            <div className="shrink-0 flex items-center justify-center">
                                {icon}
                            </div>
                        )}

                        {children && (
                            typeof children === 'string' ? (
                                <div className="flex-1 h-full min-w-0">
                                    <GameText 
                                        text={children} 
                                        baseFontSize={config.fontSize} 
                                        className={`text-white font-black tracking-tighter italic uppercase ${textShadowClass}`}
                                        minScale={0.3} 
                                    />
                                </div>
                            ) : (
                                <div className={`font-black text-white italic tracking-tighter uppercase flex items-center justify-center gap-1 h-full w-full ${textShadowClass}`} style={{ fontSize: `${config.fontSize}em` }}>
                                    {children}
                                </div>
                            )
                        )}
                    </div>
                </div>
            </button>
        </div>
    );
};

import React, { useState, useRef, useEffect } from 'react';
import { GameText } from './GameText';

type ButtonVariant = 'primary' | 'secondary' | 'success' | 'danger' | 'warning' | 'blue';

interface HexButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
    variant?: ButtonVariant;
    fullWidth?: boolean;
    size?: 'sm' | 'md' | 'lg';
    icon?: React.ReactNode;
    holdDuration?: number; 
    onHoldChange?: (isHolding: boolean) => void;
    onProgressChange?: (progress: number) => void;
}

export const HexButton: React.FC<HexButtonProps> = ({ 
    children, 
    variant = 'primary', 
    fullWidth = false,
    size = 'md',
    icon,
    className = '',
    holdDuration = 0,
    onHoldChange,
    onProgressChange,
    onClick,
    ...props 
}) => {
    const [progress, setProgress] = useState(0);
    const [isHolding, setIsHolding] = useState(false);
    const timerRef = useRef<number | null>(null);
    const startTimeRef = useRef<number>(0);

    const variants = {
        primary: "from-purple-600 to-purple-900 border-purple-400 shadow-[0_0.2rem_0_rgb(88,28,135)]",
        secondary: "from-slate-700 to-slate-900 border-slate-500 shadow-[0_0.2rem_0_rgb(15,23,42)]",
        success: "from-emerald-600 to-emerald-900 border-emerald-400 shadow-[0_0.2rem_0_rgb(6,78,59)]",
        danger: "from-red-600 to-red-900 border-red-400 shadow-[0_0.2rem_0_rgb(127,29,29)]",
        warning: "from-amber-600 to-amber-900 border-amber-400 shadow-[0_0.2rem_0_rgb(120,53,15)]",
        blue: "from-blue-600 to-blue-900 border-blue-400 shadow-[0_0.2rem_0_rgb(30,58,138)]",
    };

    const sizeConfigs = {
        sm: { height: "h-7", fontSize: 0.75, padding: "px-3" },
        md: { height: "h-10", fontSize: 1.0, padding: "px-4" },
        lg: { height: "h-14", fontSize: 1.3, padding: "px-6" }
    };

    const config = sizeConfigs[size];

    const startHold = (e: React.PointerEvent) => {
        if (!holdDuration || props.disabled) return;

        setIsHolding(true);
        onHoldChange?.(true);
        startTimeRef.current = Date.now();

        timerRef.current = window.setInterval(() => {
            const elapsed = Date.now() - startTimeRef.current;
            const p = Math.min((elapsed / holdDuration) * 100, 100);
            setProgress(p);
            onProgressChange?.(p);

            if (p >= 100) {
                if (timerRef.current) clearInterval(timerRef.current);
                timerRef.current = null;

                setProgress(100);
                onProgressChange?.(100);

                setTimeout(() => {
                    if (onClick) {
                        const syntheticEvent = { 
                            clientX: e.clientX,
                            clientY: e.clientY,
                            target: e.target,
                            currentTarget: e.currentTarget,
                            type: 'click',
                            bubbles: true,
                            cancelable: true,
                            nativeEvent: e.nativeEvent,
                        } as unknown as React.MouseEvent<HTMLButtonElement>;
                        onClick(syntheticEvent);
                    }
                    setIsHolding(false);
                    onHoldChange?.(false);
                    setProgress(0);
                    onProgressChange?.(0);
                }, 60);
            }
        }, 16);
    };

    const cancelHold = () => {
        if (timerRef.current) {
            clearInterval(timerRef.current);
            timerRef.current = null;
        }
        setIsHolding(false);
        onHoldChange?.(false);
        setProgress(0);
        onProgressChange?.(0);
    };

    useEffect(() => {
        return () => {
            if (timerRef.current) clearInterval(timerRef.current);
        };
    }, []);

    const widthClass = fullWidth ? 'w-full' : 'w-max min-w-[3.5rem]';

    return (
        <div className={`relative group ${widthClass} ${config.height} ${props.disabled ? 'opacity-50 pointer-events-none' : ''}`}>
            <button 
                className={`w-full h-full relative z-10 active:translate-y-0.5 transition-all outline-none ${className}`}
                onPointerDown={holdDuration ? startHold : undefined}
                onPointerUp={holdDuration ? cancelHold : undefined}
                onPointerLeave={holdDuration ? cancelHold : undefined}
                onClick={holdDuration ? undefined : onClick}
                role="button"
                aria-busy={isHolding}
                {...props}
            >
                <div className={`
                    absolute inset-0 bg-gradient-to-b border rounded skew-x-[-10deg] 
                    group-hover:brightness-110 transition-all duration-200 overflow-hidden
                    ${variants[variant]}
                `}>
                    {holdDuration > 0 && (
                        <div 
                            className="absolute inset-y-0 left-0 bg-white/20 transition-all duration-75 ease-linear pointer-events-none"
                            style={{ width: `${progress}%` }}
                        />
                    )}
                </div>

                <div className={`relative z-20 skew-x-[-10deg] ${config.padding} flex items-center justify-center h-full pointer-events-none`}>
                    <div className={`w-full h-full flex items-center justify-center gap-1 transition-opacity ${isHolding ? 'opacity-40' : 'opacity-100'}`}>
                        {icon && (
                            <div className="shrink-0 flex items-center justify-center">
                                {icon}
                            </div>
                        )}

                        {typeof children === 'string' ? (
                            <div className="flex-1 h-full min-w-0">
                                <GameText 
                                    text={children} 
                                    baseFontSize={config.fontSize} 
                                    className="text-white drop-shadow-md"
                                    minScale={0.3} 
                                />
                            </div>
                        ) : (
                            <div className="font-black text-white italic tracking-tight uppercase drop-shadow-md flex items-center gap-1 h-full w-full" style={{ fontSize: `${config.fontSize}em` }}>
                                {children}
                            </div>
                        )}
                    </div>
                </div>
            </button>
        </div>
    );
};

