import React, { useState, useEffect } from 'react';
import { HexButton } from '../ui/HexButton';
import { GameText } from '../ui/GameText';
import { useUser } from '../../contexts/UserContext';
import { audio } from '../../services/audio';
import { CreditIcon, GoldIcon } from '../ui/CurrencyIcons';

interface StoreCreditItemProps {
    amount: number;
    cost: number | 'FREE';
    offerId?: string; 
    availableAt?: string; 
}

export const StoreCreditItem: React.FC<StoreCreditItemProps> = ({ amount, cost, offerId, availableAt }) => {
    const { user, spendGold, addCredits, processPurchase, syncStore } = useUser();
    const [holdProgress, setHoldProgress] = useState(0);
    const [isHolding, setIsHolding] = useState(false);
    const [status, setStatus] = useState<'idle' | 'processing' | 'success'>('idle');
    const isFree = cost === 'FREE';

    const [timeLeft, setTimeLeft] = useState<number>(0);
    const hasEnoughGold = isFree || user.gold >= (cost as number);

    useEffect(() => {
        if (!availableAt) return;
        const updateTimer = () => {
            const now = Date.now();
            const target = new Date(availableAt).getTime();
            const diff = Math.max(0, Math.floor((target - now) / 1000));
            setTimeLeft(diff);
        };
        updateTimer();
        const interval = setInterval(updateTimer, 1000);
        return () => clearInterval(interval);
    }, [availableAt]);

    const handlePurchase = async () => {
        if (timeLeft > 0 || status !== 'idle') return;

        if (!hasEnoughGold) {
            syncStore();
            return;
        }

        setStatus('processing');

        let success = false;
        if (isFree && offerId) {
            success = await processPurchase(offerId);
        } else if (isFree) {
            addCredits(amount);
            success = true;
        } else {
            const hasFunds = spendGold(cost as number);
            if (hasFunds) {
                addCredits(amount);
                success = true;
            } else {
                setStatus('idle');
                syncStore();
                return;
            }
        }

        if (success) {
            setTimeout(() => {
                setStatus('success');
                audio.play('sfx_victory', 0.5);
                setTimeout(() => setStatus('idle'), 2500);
            }, 800);
        } else {
            setStatus('idle');
        }
    };

    const formatTime = (seconds: number) => {
        if (seconds < 60) return `${seconds}s`;
        const m = Math.floor(seconds / 60);
        const s = seconds % 60;
        return `${m}m ${s}s`;
    };

    return (
        <div className={`bg-gradient-to-b from-slate-800 via-slate-900 to-black border-2 transition-all duration-300 rounded p-2 flex flex-col items-center justify-between gap-1 h-[10rem] relative group shadow-[0_4px_15px_rgba(0,0,0,0.8)] overflow-hidden ${status === 'success' ? 'border-emerald-400 ring-2 ring-emerald-500/50 bg-emerald-950' : 'border-slate-700'}`}>
            {status === 'success' && (
                <div className="absolute inset-0 bg-white/40 animate-pulse z-40 pointer-events-none" />
            )}

            {holdProgress > 0 && status === 'idle' && !isFree && hasEnoughGold && (
                <div 
                    className="absolute inset-y-0 left-0 bg-cyan-300 shadow-[0_0_2rem_rgba(34,211,238,1),0_0_4rem_rgba(34,211,238,0.5)] z-0 pointer-events-none"
                    style={{ width: `${holdProgress}%` }}
                />
            )}

            <div className="mt-1 w-full px-1 relative z-10 flex flex-col items-center">
                <div className="h-6 w-full mb-0.5">
                    <GameText 
                        text={amount.toLocaleString()} 
                        baseFontSize={1.15} // Fixed multiplier
                        className="text-white drop-shadow-md"
                    />
                </div>
                <div className="text-[0.45rem] font-black text-blue-400 uppercase tracking-widest leading-none">CREDITS</div>
            </div>

            <div className="w-full flex-1 flex items-center justify-center py-1 min-h-[2.5rem] relative z-10">
                <div className={`w-10 h-10 rounded-full flex items-center justify-center border-2 transition-all duration-500 ${status === 'success' ? 'bg-emerald-500 border-emerald-300 scale-110 shadow-[0_0_25px_rgba(16,185,129,1)]' : 'bg-blue-900 border-blue-400 shadow-[inset_0_0_10px_rgba(0,0,0,0.5)]'}`}>
                    {status === 'success' ? (
                        <svg className="w-6 h-6 text-white animate-pop" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={4} d="M5 13l4 4L19 7" /></svg>
                    ) : (
                        <CreditIcon size="md" />
                    )}
                </div>
            </div>

            <div className="w-full h-1 relative flex items-center justify-center pointer-events-none mb-0.5 z-10 overflow-visible">
                {isHolding && status === 'idle' && !isFree && hasEnoughGold && (
                    <div className="relative font-black text-[0.45rem] uppercase tracking-widest leading-none drop-shadow-[0_1px_2px_rgba(0,0,0,1)]">
                        <span className="text-white/40 whitespace-nowrap">HOLD TO BUY</span>
                        <div 
                            className="absolute inset-0 text-white whitespace-nowrap overflow-hidden"
                            style={{ width: `${holdProgress}%` }}
                        >
                            HOLD TO BUY
                        </div>
                    </div>
                )}
                {status === 'processing' && (
                    <span className="text-[0.45rem] font-black text-cyan-300 uppercase tracking-[0.25em] leading-none animate-pulse drop-shadow-[0_0_5px_rgba(34,211,238,0.8)]">SYNCING...</span>
                )}
                {status === 'success' && (
                    <span className="text-[0.45rem] font-black text-emerald-400 uppercase tracking-[0.25em] leading-none animate-bounce origin-bottom drop-shadow-[0_0_5px_rgba(52,211,153,0.8)]">DEPOSITED</span>
                )}
            </div>

            <div className="w-full mt-auto relative z-10">
                {timeLeft > 0 ? (
                    <div className="h-7 w-full bg-slate-900 border-2 border-slate-700 rounded flex items-center justify-center gap-1.5 overflow-hidden">
                        <svg className="w-2.5 h-2.5 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                        <span className="text-[0.6rem] font-black text-slate-400 uppercase tracking-tighter tabular-nums">
                            {formatTime(timeLeft)}
                        </span>
                    </div>
                ) : (
                    <div className="h-7">
                        <HexButton 
                            variant={status === 'success' ? 'success' : (isFree ? 'success' : 'secondary')} 
                            size="sm" 
                            fullWidth
                            onClick={handlePurchase}
                            disabled={status !== 'idle'}
                            holdDuration={isFree || !hasEnoughGold ? 0 : 1000}
                            onHoldChange={setIsHolding}
                            onProgressChange={setHoldProgress}
                        >
                            {status === 'processing' ? "SYNCING" : (status === 'success' ? "SYNCED" : (isFree ? "FREE" : <div className="flex items-center justify-center gap-1"><GoldIcon size="xs" /> {cost}</div>))}
                        </HexButton>
                    </div>
                )}
            </div>
        </div>
    );
};

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useUser } from '../../contexts/UserContext';
import { CARDS } from '../../constants';
import { SlantedButton } from '../ui/SlantedButton';
import { GameText } from '../ui/GameText';

interface DeckSelectorProps {
    activeDeckId: number;
    onSelectDeck: (id: number) => void;
}

export const DeckSelectorClassic: React.FC<DeckSelectorProps> = ({ activeDeckId, onSelectDeck }) => {
    const { user } = useUser();
    const [flippedId, setFlippedId] = useState<number | null>(null);
    const containerRef = useRef<HTMLDivElement>(null);

    const centerActiveItem = useCallback((smooth: boolean = true) => {
        if (containerRef.current) {
            const container = containerRef.current;
            const activeElement = container.querySelector(`[data-active="true"]`) as HTMLElement;

            if (activeElement) {
                const elementOffset = activeElement.offsetLeft;
                const elementWidth = activeElement.offsetWidth;
                const containerWidth = container.offsetWidth;

                if (containerWidth === 0) return;
                const targetScroll = elementOffset - (containerWidth / 2) + (elementWidth / 2);
                container.scrollTo({ left: targetScroll, behavior: smooth ? 'smooth' : 'auto' });
            }
        }
    }, []);

    useEffect(() => { centerActiveItem(true); }, [activeDeckId, centerActiveItem]);
    useEffect(() => {
        const timer = setTimeout(() => centerActiveItem(true), 550);
        return () => clearTimeout(timer);
    }, [centerActiveItem]);

    const handleDeckClick = (id: number) => {
        if (activeDeckId === id) setFlippedId(flippedId === id ? null : id);
        else { onSelectDeck(id); setFlippedId(null); }
    };

    const getStats = (deckId: number) => {
        const cardIds = user.decks[deckId] || [];
        if (cardIds.length === 0) return { avgCost: 0, avgPower: 0, count: 0 };
        const deckCards = cardIds.map(id => CARDS.find(c => c.id === id)).filter(Boolean);
        const totalCost = deckCards.reduce((acc, c) => acc + (c?.baseCost || 0), 0);
        const totalPower = deckCards.reduce((acc, c) => acc + (c?.basePower || 0), 0);
        return {
            avgCost: (totalCost / deckCards.length).toFixed(1),
            avgPower: (totalPower / deckCards.length).toFixed(1),
            count: deckCards.length
        };
    };

    const deckIds = Object.keys(user.decks).map(Number).sort((a, b) => a - b);

    return (
        <div ref={containerRef} className="w-full flex overflow-x-auto pt-2 pb-0.5 px-3 gap-2 shrink-0 scrollbar-hide perspective-1000">
            {deckIds.map(i => {
                const isSelected = activeDeckId === i;
                const isFlipped = flippedId === i && isSelected;
                const stats = getStats(i);
                const deckName = user.deckNames[i] || 'UNTITLED';
                const isValid = stats.count === 12;
                const selectedVariant = isValid ? 'success' : 'danger';

                return (
                    <div key={i} data-active={isSelected} className="min-w-[7.5rem] h-14 relative shrink-0">
                        <div className={`w-full h-full relative transition-transform duration-500 transform-style-3d ${isFlipped ? 'rotate-y-180' : ''}`}>
                            <div className="absolute inset-0 backface-hidden">
                                <SlantedButton variant={isSelected ? selectedVariant : 'secondary'} fullWidth size="md" className="!h-full" onClick={() => handleDeckClick(i)}>
                                    <div className="flex flex-col items-center justify-center w-full h-full pointer-events-none pt-1 pb-0.5">
                                        <div className="flex items-center gap-1">
                                            <span className="text-[0.45rem] font-black text-white/40 uppercase tracking-widest">Deck {i < 10 ? `0${i}` : i}</span>
                                            {!isValid && <div className="w-1.5 h-1.5 rounded-full bg-amber-500 animate-pulse shadow-[0_0_5px_rgba(245,158,11,0.8)]" />}
                                        </div>
                                        <div className="flex-1 w-full min-h-0 flex items-center justify-center">
                                            <GameText text={deckName} baseFontSize={1.05} maxLines={2} className="text-white drop-shadow-md" />
                                        </div>
                                    </div>
                                </SlantedButton>
                            </div>
                            <div className="absolute inset-0 backface-hidden rotate-y-180">
                                <SlantedButton variant={isValid ? 'success' : 'danger'} fullWidth size="md" className="!h-full" onClick={() => handleDeckClick(i)}>
                                    <div className="flex items-center justify-around w-full h-full px-1">
                                        <div className="flex flex-col items-center">
                                            <span className="text-[0.4rem] font-black uppercase text-white/60 leading-none mb-1">Cost</span>
                                            <span className="text-sm font-black text-white italic">{stats.avgCost}</span>
                                        </div>
                                        <div className="w-px h-8 bg-white/20" />
                                        <div className="flex flex-col items-center">
                                            <span className="text-[0.4rem] font-black uppercase text-white/60 leading-none mb-1">Power</span>
                                            <span className="text-sm font-black text-white italic">{stats.avgPower}</span>
                                        </div>
                                    </div>
                                </SlantedButton>
                            </div>
                        </div>
                    </div>
                );
            })}
            <style>{`.perspective-1000 { perspective: 1000px; } .transform-style-3d { transform-style: preserve-3d; } .backface-hidden { backface-visibility: hidden; } .rotate-y-180 { transform: rotateY(180deg); }`}</style>
        </div>
    );
};

import React, { useEffect, useRef, useCallback } from 'react';
import { useUser } from '../../contexts/UserContext';
import { SlantedButton } from '../ui/SlantedButton';
import { GameText } from '../ui/GameText';
import { audio } from '../../services/audio';

interface DeckSelectorProps {
    activeDeckId: number;
    onSelectDeck: (id: number) => void;
}

const getRelativeTimeString = (isoString: string) => {
    const date = new Date(isoString);
    const now = new Date();
    const diffInMs = now.getTime() - date.getTime();
    const diffInMins = Math.floor(diffInMs / (1000 * 60));
    if (diffInMins < 1) return 'just now';
    if (diffInMins < 60) return `${diffInMins} ${diffInMins === 1 ? 'minute' : 'minutes'} ago`;
    const diffInHours = Math.floor(diffInMs / (1000 * 60 * 60));
    if (diffInHours < 24) return `${diffInHours} ${diffInHours === 1 ? 'hour' : 'hours'} ago`;
    const diffInDays = Math.floor(diffInHours / 24);
    if (diffInDays === 1) return 'yesterday';
    if (diffInDays < 7) return `${diffInDays} days ago`;
    const diffInWeeks = Math.floor(diffInDays / 7);
    if (diffInWeeks === 1) return 'a week ago';
    if (diffInWeeks < 4) return `${diffInWeeks} weeks ago`;
    const diffInMonths = Math.floor(diffInDays / 30);
    if (diffInMonths === 1) return 'a month ago';
    if (diffInMonths < 12) return `${diffInMonths} months ago`;
    return 'a long time ago';
};

export const DeckSelector3D: React.FC<DeckSelectorProps> = ({ activeDeckId, onSelectDeck }) => {
    const { user } = useUser();
    const deckIds = Object.keys(user.decks).map(Number).sort((a, b) => a - b);
    const count = deckIds.length;
    const angleStep = 360 / count;
    const radius = 110;

    const drumRef = useRef<HTMLDivElement>(null);
    const itemsRef = useRef<(HTMLDivElement | null)[]>([]);
    const rotationRef = useRef((activeDeckId - 1) * angleStep);
    const velocityRef = useRef(0);
    const isDraggingRef = useRef(false);
    const lastPointerY = useRef(0);
    const lastTime = useRef(0);
    const requestRef = useRef<number | null>(null);

    const lastCenteredIndexRef = useRef<number>(activeDeckId - 1);
    const lastTickStepRef = useRef<number>(Math.round(rotationRef.current / angleStep));
    const lastAudioTimeRef = useRef<number>(0);
    const canPlayAudioRef = useRef<boolean>(true);

    useEffect(() => {
        if (!isDraggingRef.current && velocityRef.current === 0) {
            rotationRef.current = (activeDeckId - 1) * angleStep;
            updateDom(rotationRef.current);
        }
    }, [activeDeckId, angleStep]);

    const updateDom = useCallback((rot: number) => {
        if (!drumRef.current) return;
        drumRef.current.style.transform = `translate3d(0, 0, -${radius}px) rotateX(${rot}deg)`;
        let currentCenterI = -1;
        for (let i = 0; i < itemsRef.current.length; i++) {
            const item = itemsRef.current[i];
            if (!item) continue;
            const angle = -i * angleStep;
            let normalizedAngle = (angle + rot) % 360;
            if (normalizedAngle > 180) normalizedAngle -= 360;
            else if (normalizedAngle < -180) normalizedAngle += 360;
            const absAngle = Math.abs(normalizedAngle);
            if (absAngle < 110) {
                const distanceScale = 1 - (absAngle / 100) * 0.35;
                const opacity = 1 - (absAngle / 130);
                item.style.transform = `rotateX(${angle}deg) translate3d(0, 0, ${radius}px) scale(${distanceScale})`;
                item.style.opacity = Math.max(0.05, opacity).toString();
                item.style.visibility = 'visible';
                if (absAngle < (angleStep / 2)) currentCenterI = i;
            } else {
                if (item.style.visibility !== 'hidden') {
                    item.style.visibility = 'hidden';
                    item.style.opacity = '0';
                }
            }
        }
        if (currentCenterI !== -1 && currentCenterI !== lastCenteredIndexRef.current) {
            const prevItem = itemsRef.current[lastCenteredIndexRef.current];
            const nextItem = itemsRef.current[currentCenterI];
            if (prevItem) { prevItem.classList.remove('is-visually-center'); prevItem.style.zIndex = '10'; }
            if (nextItem) { nextItem.classList.add('is-visually-center'); nextItem.style.zIndex = '50'; }
            lastCenteredIndexRef.current = currentCenterI;
        }
        const currentStep = Math.round(rot / angleStep);
        if (currentStep !== lastTickStepRef.current) {
            const now = performance.now();
            const elapsed = now - lastAudioTimeRef.current;
            if (!isDraggingRef.current && elapsed > 1000) canPlayAudioRef.current = false;
            if (canPlayAudioRef.current && elapsed > 12) {
                audio.play('sfx_ui_click', 0.45);
                lastAudioTimeRef.current = now;
            }
            lastTickStepRef.current = currentStep;
        }
    }, [angleStep, radius]);

    const animate = useCallback(() => {
        if (isDraggingRef.current) return;
        velocityRef.current *= 0.95;
        rotationRef.current += velocityRef.current;
        if (Math.abs(velocityRef.current) < 0.35) {
            const targetIndex = Math.round(rotationRef.current / angleStep);
            const targetRotation = targetIndex * angleStep;
            const diff = targetRotation - rotationRef.current;
            rotationRef.current += diff * 0.45;
            if (Math.abs(diff) < 0.1) {
                rotationRef.current = targetRotation;
                velocityRef.current = 0;
                updateDom(rotationRef.current);
                const finalId = ((targetIndex % count + count) % count) + 1;
                if (finalId !== activeDeckId) onSelectDeck(finalId);
                return;
            }
        }
        updateDom(rotationRef.current);
        requestRef.current = requestAnimationFrame(animate);
    }, [angleStep, count, activeDeckId, onSelectDeck, updateDom]);

    const handlePointerDown = (e: React.PointerEvent) => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
        isDraggingRef.current = true;
        canPlayAudioRef.current = true;
        lastAudioTimeRef.current = performance.now();
        lastPointerY.current = e.clientY;
        lastTime.current = performance.now();
    };

    const handlePointerMove = (e: React.PointerEvent) => {
        if (!isDraggingRef.current) return;
        const now = performance.now();
        const deltaY = e.clientY - lastPointerY.current;
        const deltaTime = now - lastTime.current;
        const rotationDelta = -(deltaY / 100) * angleStep;
        rotationRef.current += rotationDelta;
        updateDom(rotationRef.current);
        if (deltaTime > 0) {
            const instantVelocity = rotationDelta / (deltaTime / 16.67);
            velocityRef.current = velocityRef.current * 0.2 + instantVelocity * 0.8;
        }
        lastPointerY.current = e.clientY;
        lastTime.current = now;
    };

    const handlePointerUp = () => {
        if (!isDraggingRef.current) return;
        isDraggingRef.current = false;
        requestRef.current = requestAnimationFrame(animate);
    };

    return (
        <div 
            className="w-full h-64 flex items-center justify-center perspective-[1200px] overflow-hidden select-none touch-none bg-slate-950/40 border-y border-slate-800/50"
            onPointerDown={handlePointerDown}
            onPointerMove={handlePointerMove}
            onPointerUp={handlePointerUp}
            onPointerLeave={handlePointerUp}
        >
            <div ref={drumRef} className="relative w-64 h-24 transform-style-3d pointer-events-none will-change-transform">
                {deckIds.map((id, i) => {
                    const deckName = user.deckNames[id] || 'UNTITLED';
                    const stats = user.deckStats[id];
                    const dateStr = stats ? getRelativeTimeString(stats.lastModified) : 'some time ago';
                    const isInitialCenter = activeDeckId === id;
                    const isValid = (user.decks[id]?.length || 0) === 12;
                    const statsText = `conquest: ${stats?.conquestWins || 0}/${stats?.conquestTotal || 0} (${stats?.conquestWinRate || 0}%) - ladder ${stats?.ladderWins || 0}/${stats?.ladderLosses || 0} (${stats?.ladderWinRate || 0}%)`;

                    return (
                        <div key={id} ref={el => itemsRef.current[i] = el} className={`absolute inset-0 backface-hidden transition-opacity duration-300 transform-style-3d will-change-transform ${isInitialCenter ? 'is-visually-center' : ''} ${isValid ? 'deck-valid' : 'deck-invalid'}`} style={{ transform: `rotateX(${-i * angleStep}deg) translate3d(0, 0, ${radius}px)`, opacity: isInitialCenter ? 1 : 0.5, zIndex: isInitialCenter ? 50 : 10 }}>
                            <SlantedButton variant="secondary" fullWidth size="lg" className="!h-full shadow-2xl drum-item-button">
                                <div className="flex flex-col items-center justify-center w-full h-full pointer-events-none px-4 py-2">
                                    <div className="w-full h-8 flex items-center justify-center">
                                        <GameText text={deckName} baseFontSize={1.4} maxLines={1} className="text-white" />
                                    </div>
                                    <div className="w-full h-5 flex items-center justify-center opacity-80">
                                        <GameText text={statsText} baseFontSize={0.75} maxLines={1} className="text-white font-bold" />
                                    </div>
                                    <div className="w-full h-3 mt-0.5 opacity-50">
                                        <GameText text={`Changed ${dateStr}`} baseFontSize={0.65} className="text-white lowercase italic" />
                                    </div>
                                </div>
                            </SlantedButton>
                        </div>
                    );
                })}
            </div>
            <div className="absolute left-0 right-0 h-24 border-y border-white/10 pointer-events-none z-0 bg-gradient-to-b from-transparent via-indigo-500/5 to-transparent" />
            <style>{`.transform-style-3d { transform-style: preserve-3d; } .backface-hidden { backface-visibility: hidden; } .is-visually-center.deck-valid .drum-item-button > div:first-child { background: linear-gradient(to bottom, #059669, #064e3b) !important; border-color: #34d399 !important; box-shadow: 0 0.2rem 0 #064e3b, 0 0 20px rgba(16, 185, 129, 0.3) !important; } .is-visually-center.deck-invalid .drum-item-button > div:first-child { background: linear-gradient(to bottom, #dc2626, #7f1d1d) !important; border-color: #f87171 !important; box-shadow: 0 0.2rem 0 #7f1d1d, 0 0 20px rgba(239, 68, 68, 0.3) !important; } .is-visually-center { filter: grayscale(0) !important; } div:not(.is-visually-center) { filter: grayscale(0.3); }`}</style>
        </div>
    );
};

import React, { useState, useLayoutEffect, useRef, useEffect, useCallback } from 'react';

interface GameTextProps {
  text: string;
  className?: string;
  /** 
   * RELATIVE SCALE BASIS
   * Interpreted as 'em' relative to container font-size.
   */
  baseFontSize: number;
  /** How much we allow the text to shrink. */
  minScale?: number;
  /** How much we allow the text to grow beyond its base size. Default 1.0 (no growth). */
  maxScale?: number;
  /** Max lines for wrapping. */
  maxLines?: number;
}

export const GameText: React.FC<GameTextProps> = ({ 
  text, 
  className = '', 
  baseFontSize, 
  minScale = 0.3,
  maxScale = 1.0,
  maxLines = 1
}) => {
  const [layout, setLayout] = useState<{ lines: string[], scale: number, finalPx: number }>({ 
      lines: [text || ''], 
      scale: 1,
      finalPx: 16
  });
  const containerRef = useRef<HTMLDivElement>(null);
  const ghostRef = useRef<HTMLDivElement>(null);

  const findBestLayout = useCallback(() => {
    const container = containerRef.current;
    const ghost = ghostRef.current;
    if (!container || !ghost || !text) return;

    const containerWidth = container.clientWidth;
    const containerHeight = container.clientHeight;

    // If container hasn't layouted yet, don't update scale (keep at 1.0)
    if (containerWidth <= 0 || containerHeight <= 0) return;

    // 1. Calculate the 'Aspirational' Pixel Size
    const parentStyle = window.getComputedStyle(container);
    const parentPx = parseFloat(parentStyle.fontSize) || 16;
    const targetPx = parentPx * baseFontSize;

    const words = text.split(/\s+/);

    const splitIntoLines = (numLines: number): string[] => {
      if (numLines <= 1 || words.length <= 1) return [text];
      const targetCharsPerLine = text.length / numLines;
      const result: string[][] = Array.from({ length: numLines }, () => []);
      let currentLine = 0;
      let currentChars = 0;

      words.forEach((word) => {
        if (currentLine < numLines - 1) {
            const distIfStay = Math.abs((currentChars + word.length) - targetCharsPerLine);
            const distIfMove = Math.abs(currentChars - targetCharsPerLine);
            if (currentChars > 0 && distIfMove < distIfStay) {
                currentLine++;
                currentChars = 0;
            }
        }
        result[currentLine].push(word);
        currentChars += word.length + 1;
      });

      return result.map(l => l.join(' ')).filter(s => s.length > 0);
    };

    const measureLayout = (lines: string[]) => {
      ghost.innerHTML = lines.map(l => `<div>${l}</div>`).join('');
      ghost.style.fontSize = `${targetPx}px`;

      const ghostWidth = ghost.offsetWidth;
      const ghostHeight = ghost.offsetHeight;

      if (ghostWidth <= 0 || ghostHeight <= 0) return 1;

      const widthRatio = (containerWidth / ghostWidth) * 0.98;
      const heightRatio = (containerHeight / ghostHeight) * 0.98;

      return Math.min(widthRatio, heightRatio);
    };

    let bestScale = 0;
    let bestLines: string[] = [text];
    const limit = Math.min(maxLines, 4); 

    for (let i = 1; i <= limit; i++) {
      if (i > words.length) break;
      const candidateLines = splitIntoLines(i);
      const scale = measureLayout(candidateLines);
      const bias = (limit - i) * 0.05; 
      if (scale + bias > bestScale) {
        bestScale = scale;
        bestLines = candidateLines;
      }
      if (i === 1 && scale > 0.98 && scale < 1.05) break;
    }

    setLayout({ 
        lines: bestLines, 
        // Ensure scale is never zero; clamp to minScale or valid range
        scale: Math.max(minScale, Math.min(maxScale, bestScale || 1)),
        finalPx: targetPx
    });
  }, [text, baseFontSize, minScale, maxScale, maxLines]);

  useLayoutEffect(() => {
    findBestLayout();
    const observer = new ResizeObserver(() => {
        requestAnimationFrame(findBestLayout);
    });
    if (containerRef.current) observer.observe(containerRef.current);
    return () => observer.disconnect();
  }, [findBestLayout]);

  useEffect(() => {
    if (!('fonts' in document)) return;
    const handleFontLoad = () => requestAnimationFrame(() => findBestLayout());
    document.fonts.addEventListener('loadingdone', handleFontLoad);
    return () => document.fonts.removeEventListener('loadingdone', handleFontLoad);
  }, [findBestLayout]);

  if (!text) return null;

  return (
    <div 
      ref={containerRef} 
      className={`w-full h-full flex justify-center items-center relative leading-none overflow-hidden font-sans ${className}`}
    >
      {/* Hidden Ghost for Measurement */}
      <div
        ref={ghostRef}
        className={`absolute invisible pointer-events-none flex flex-col items-center ${className}`}
        style={{ fontSize: `${layout.finalPx}px`, left: -9999, whiteSpace: 'nowrap' }}
      />

      {/* Visible Scaled Text */}
      <div
        style={{ 
          transformOrigin: 'center center',
          transform: `scale(${layout.scale})`,
          fontSize: `${layout.finalPx}px`,
          width: 'max-content',
          minWidth: 'max-content'
        }}
        className="flex flex-col items-center justify-center leading-none"
      >
        {layout.lines.map((line, idx) => (
            <div key={idx} className="whitespace-nowrap">
                {line}
            </div>
        ))}
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { GameText } from './GameText';

type ButtonVariant = 'primary' | 'secondary' | 'success' | 'danger' | 'warning' | 'blue';

interface SlantedButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
    variant?: ButtonVariant;
    fullWidth?: boolean;
    size?: 'sm' | 'md' | 'lg';
    icon?: React.ReactNode;
    holdDuration?: number; 
    onHoldChange?: (isHolding: boolean) => void;
    onProgressChange?: (progress: number) => void;
}

export const SlantedButton: React.FC<SlantedButtonProps> = ({ 
    children, 
    variant = 'primary', 
    fullWidth = false,
    size = 'md',
    icon,
    className = '',
    holdDuration = 0,
    onHoldChange,
    onProgressChange,
    onClick,
    ...props 
}) => {
    const [progress, setProgress] = useState(0);
    const [isHolding, setIsHolding] = useState(false);
    const timerRef = useRef<number | null>(null);
    const startTimeRef = useRef<number>(0);

    const variants = {
        primary: "from-purple-600 to-purple-900 border-purple-400 shadow-[0_0.2rem_0_rgb(88,28,135)]",
        secondary: "from-slate-700 to-slate-900 border-slate-500 shadow-[0_0.2rem_0_rgb(15,23,42)]",
        success: "from-emerald-600 to-emerald-900 border-emerald-400 shadow-[0_0.2rem_0_rgb(6,78,59)]",
        danger: "from-red-600 to-red-900 border-red-400 shadow-[0_0.2rem_0_rgb(127,29,29)]",
        warning: "from-amber-600 to-amber-900 border-amber-400 shadow-[0_0.2rem_0_rgb(120,53,15)]",
        blue: "from-blue-600 to-blue-900 border-blue-400 shadow-[0_0.2rem_0_rgb(30,58,138)]",
    };

    const sizeConfigs = {
        sm: { height: "h-7", fontSize: 0.65, padding: "px-3" },
        md: { height: "h-10", fontSize: 0.88, padding: "px-6" },
        lg: { height: "h-14", fontSize: 1.15, padding: "px-8" }
    };

    const config = sizeConfigs[size];

    const startHold = (e: React.PointerEvent) => {
        if (!holdDuration || props.disabled) return;

        setIsHolding(true);
        onHoldChange?.(true);
        startTimeRef.current = Date.now();

        timerRef.current = window.setInterval(() => {
            const elapsed = Date.now() - startTimeRef.current;
            const p = Math.min((elapsed / holdDuration) * 100, 100);
            setProgress(p);
            onProgressChange?.(p);

            if (p >= 100) {
                if (timerRef.current) clearInterval(timerRef.current);
                timerRef.current = null;

                setProgress(100);
                onProgressChange?.(100);

                setTimeout(() => {
                    if (onClick) {
                        const syntheticEvent = { 
                            clientX: e.clientX,
                            clientY: e.clientY,
                            target: e.target,
                            currentTarget: e.currentTarget,
                            type: 'click',
                            bubbles: true,
                            cancelable: true,
                            nativeEvent: e.nativeEvent,
                        } as unknown as React.MouseEvent<HTMLButtonElement>;
                        onClick(syntheticEvent);
                    }
                    setIsHolding(false);
                    onHoldChange?.(false);
                    setProgress(0);
                    onProgressChange?.(0);
                }, 60);
            }
        }, 16);
    };

    const cancelHold = () => {
        if (timerRef.current) {
            clearInterval(timerRef.current);
            timerRef.current = null;
        }
        setIsHolding(false);
        onHoldChange?.(false);
        setProgress(0);
        onProgressChange?.(0);
    };

    useEffect(() => {
        return () => {
            if (timerRef.current) clearInterval(timerRef.current);
        };
    }, []);

    const widthOverride = className.match(/w-\[?[\w.%]+\]?/)?.[0] || '';
    const widthClass = fullWidth ? 'w-full' : (widthOverride ? widthOverride : 'w-max');
    const textShadowClass = "drop-shadow-[0_2px_3px_rgba(0,0,0,0.8)]";

    return (
        <div className={`relative group ${widthClass} ${config.height} ${props.disabled ? 'opacity-50 pointer-events-none' : ''}`}>
            <button 
                className={`w-full h-full relative z-10 active:translate-y-0.5 transition-all outline-none ${className}`}
                onPointerDown={holdDuration ? startHold : undefined}
                onPointerUp={holdDuration ? cancelHold : undefined}
                onPointerLeave={holdDuration ? cancelHold : undefined}
                onClick={holdDuration ? undefined : onClick}
                role="button"
                aria-busy={isHolding}
                {...props}
            >
                <div className={`
                    absolute inset-0 bg-gradient-to-b border rounded skew-x-[-10deg] 
                    [@media(hover:hover)]:group-hover:brightness-110 transition-all duration-200 overflow-hidden
                    ${variants[variant]}
                `}>
                    {holdDuration > 0 && (
                        <div 
                            className="absolute inset-y-0 left-0 bg-white/20 transition-all duration-75 ease-linear pointer-events-none"
                            style={{ width: `${progress}%` }}
                        />
                    )}
                </div>

                <div className={`relative z-20 skew-x-[-10deg] h-full pointer-events-none flex items-center justify-center ${config.padding}`}>
                    <div className={`flex items-center justify-center w-full h-full transition-opacity ${isHolding ? 'opacity-40' : 'opacity-100'}`}>
                        {icon && (
                            <div className="shrink-0 flex items-center justify-center mr-1">
                                {icon}
                            </div>
                        )}

                        {children && (
                            typeof children === 'string' ? (
                                <div className="flex-1 h-full min-w-0">
                                    <GameText 
                                        text={children} 
                                        baseFontSize={config.fontSize} 
                                        maxScale={1.0}
                                        className={`text-white font-black tracking-tighter italic uppercase ${textShadowClass}`}
                                        minScale={0.3} 
                                    />
                                </div>
                            ) : (
                                <div className={`h-full w-full ${textShadowClass}`} style={{ fontSize: `${config.fontSize}em` }}>
                                    {children}
                                </div>
                            )
                        )}
                    </div>
                </div>
            </button>
        </div>
    );
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
