import React, { useState, useEffect, useRef } from 'react';
import { useUser } from '../../contexts/UserContext';
import { SeasonMasteryHeader } from '../ui/SeasonMasteryHeader';
import { SeasonRewardButtonV2 } from '../ui/SeasonRewardButtonV2';
import { SeasonHeroSection } from '../season/SeasonHeroSection';
import { Portal } from '../ui/Portal';
import { ScreenKey, CardDefinition } from '../../types';
import { ModalBackdrop } from '../ui/ModalBackdrop';
import { CARDS } from '../../constants';
import { SlantedButton } from '../ui/SlantedButton';

interface SeasonScreenProps {
    activeScreen?: ScreenKey;
}

export const SeasonScreen: React.FC<SeasonScreenProps> = ({ activeScreen }) => {
    const { user, inspect, seasonPassData, isSeasonLoading, debugSwitchSeason } = useUser();
    const scrollContainerRef = useRef<HTMLDivElement>(null);
    const activeLevelRef = useRef<HTMLDivElement>(null);

    const [showPremiumModal, setShowPremiumModal] = useState(false);
    const [timeLeft, setTimeLeft] = useState({ dd: '00', hh: '00', mm: '00', ss: '00' });

    // Autorun timer logic
    useEffect(() => {
        if (!seasonPassData?.endDate) return;

        const updateTimer = () => {
            const now = new Date().getTime();
            const distance = new Date(seasonPassData.endDate).getTime() - now;

            if (distance < 0) {
                setTimeLeft({ dd: '00', hh: '00', mm: '00', ss: '00' });
                return;
            }

            setTimeLeft({
                dd: String(Math.floor(distance / (1000 * 60 * 60 * 24))).padStart(2, '0'),
                hh: String(Math.floor((distance % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60))).padStart(2, '0'),
                mm: String(Math.floor((distance % (1000 * 60 * 60)) / (1000 * 60))).padStart(2, '0'),
                ss: String(Math.floor((distance % (1000 * 60)) / 1000)).padStart(2, '0')
            });
        };

        const interval = setInterval(updateTimer, 1000);
        updateTimer();
        return () => clearInterval(interval);
    }, [seasonPassData]);

    // Auto-scroll logic
    useEffect(() => {
        if (activeScreen === 'SEASON' && !isSeasonLoading) {
            const timer = setTimeout(() => {
                if (activeLevelRef.current && scrollContainerRef.current) {
                    const container = scrollContainerRef.current;
                    const activeItem = activeLevelRef.current;
                    const targetScroll = activeItem.offsetTop - (container.offsetHeight / 2) + (activeItem.offsetHeight / 2);
                    container.scrollTo({ top: targetScroll, behavior: 'smooth' });
                }
            }, 600);
            return () => clearTimeout(timer);
        }
    }, [activeScreen, isSeasonLoading]);

    if (isSeasonLoading || !seasonPassData) {
        return (
            <div className="w-full h-full flex flex-col items-center justify-center bg-slate-950/20 backdrop-blur-md">
                <div className="w-8 h-8 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin mb-4" />
                <span className="text-[0.6rem] font-black text-indigo-400 uppercase tracking-[0.3em] animate-pulse">Syncing Sector Data...</span>
            </div>
        );
    }

    const seasonCard = CARDS.find(c => c.id === seasonPassData.heroCardId) || CARDS[0];
    const currentXP = 800; // Mock current XP
    const targetXP = 1000;
    const progressPercent = (currentXP / targetXP) * 100;

    return (
        <div className="w-full h-full flex flex-col bg-transparent overflow-hidden relative font-sans">

            {/* 1. THEME HEADER */}
            <div className="shrink-0 flex flex-col bg-slate-900/40 backdrop-blur-md border-b border-slate-800/50 pt-1 pb-2 px-4 z-40 relative">
                <div className="flex items-center justify-between">
                    <div className="flex items-center gap-3">
                        <h1 className="text-[1rem] font-black text-white italic tracking-tighter uppercase drop-shadow-lg leading-none">
                            {seasonPassData.themeName}
                        </h1>
                        {/* DEBUG TOGGLE */}
                        <button 
                            onClick={debugSwitchSeason}
                            className="bg-white/5 border border-white/10 px-1.5 py-0.5 rounded text-[0.4rem] font-black text-slate-500 hover:text-white hover:bg-white/10 transition-colors uppercase tracking-widest"
                        >
                            Debug: Next Season
                        </button>
                    </div>
                    {seasonPassData.premiumActive && (
                        <div className="flex items-center gap-1.5 bg-indigo-600/40 border border-indigo-500/50 px-2.5 py-0.5 rounded-sm shadow-[0_0_10px_rgba(79,70,229,0.2)]">
                            <div className="w-1.5 h-1.5 rounded-full bg-indigo-400 animate-pulse" />
                            <span className="text-[0.6rem] font-black text-white italic tracking-tighter">PREMIUM</span>
                        </div>
                    )}
                </div>

                <div className="flex items-center justify-between mt-1.5 px-0.5">
                    <div className="flex items-center gap-1.5">
                         <span className="text-[0.55rem] font-black text-slate-400 uppercase tracking-widest leading-none">
                            Dec 1 - Dec 31
                        </span>
                    </div>
                    <div className="flex items-center gap-1.5">
                        <span className="text-[0.45rem] font-black text-indigo-400 uppercase leading-none mr-0.5">ENDS IN:</span>
                        <span className="text-[0.65rem] font-black text-white italic tabular-nums leading-none tracking-tight">
                            {timeLeft.dd}:{timeLeft.hh}:{timeLeft.mm}:{timeLeft.ss}
                        </span>
                    </div>
                </div>
            </div>

            {/* 2. PROGRESS BAR SECTION */}
            <SeasonMasteryHeader 
                level={user.level}
                progressPercent={progressPercent}
                xpText={`${currentXP} / ${targetXP} XP`}
            />

            {/* MAIN CONTENT AREA */}
            <div className="flex-1 flex-row overflow-hidden min-h-0 px-2 flex gap-x-3">

                {/* LEFT COLUMN: HERO SECTION */}
                <SeasonHeroSection 
                    seasonCard={seasonCard}
                    variantName={seasonPassData.heroVariantName}
                    onInspect={inspect}
                    onGoPremium={() => setShowPremiumModal(true)}
                />

                {/* RIGHT COLUMN: REWARD TRACK */}
                <div className="flex-1 flex flex-col min-w-0">
                    <div 
                        ref={scrollContainerRef}
                        className="flex-1 overflow-y-auto pl-3 pr-2 py-4 space-y-3 scrollbar-hide pb-24"
                    >
                        {seasonPassData.rewards.map((reward) => (
                            <div 
                                key={reward.level} 
                                ref={reward.isActive ? activeLevelRef : null}
                                className="relative w-full overflow-visible"
                            >
                                <SeasonRewardButtonV2 
                                    level={reward.level}
                                    progressPercent={reward.isActive ? progressPercent : (reward.isClaimed ? 100 : 0)}
                                    isClaimed={reward.isClaimed}
                                    isActive={reward.isActive}
                                    isLocked={reward.isLocked}
                                    rewardType={reward.type}
                                    rewardAmount={reward.amount}
                                    cardDef={reward.cardDef}
                                    onClick={() => inspect({
                                        type: 'level_info',
                                        level: reward.level,
                                        rewardType: reward.type,
                                        rewardAmount: reward.amount,
                                        isClaimed: reward.isClaimed,
                                        cardDef: reward.cardDef
                                    })}
                                />
                            </div>
                        ))}
                    </div>
                </div>
            </div>

            {/* 3. PREMIUM REWARDS MODAL */}
            {showPremiumModal && (
                <Portal>
                    <ModalBackdrop onClose={() => setShowPremiumModal(false)} blurAmount="md">
                        <div 
                            className="w-full max-w-sm bg-slate-900 border-2 border-indigo-500/50 rounded-2xl overflow-hidden shadow-[0_0_50px_rgba(79,70,229,0.3)] flex flex-col animate-pop"
                            onClick={(e) => e.stopPropagation()}
                        >
                            <div className="relative h-40 shrink-0">
                                <img src="https://picsum.photos/seed/pirates/600/300" className="w-full h-full object-cover opacity-60" alt="" />
                                <div className="absolute inset-0 bg-gradient-to-t from-slate-950 via-slate-950/20 to-transparent" />
                                <div className="absolute bottom-4 left-6">
                                    <h2 className="text-2xl font-black text-white italic uppercase tracking-tighter drop-shadow-lg">Season Pass Rewards</h2>
                                    <p className="text-[0.6rem] font-bold text-indigo-300 uppercase tracking-[0.2em]">Available This Month</p>
                                </div>
                                <button className="absolute top-4 right-4 w-8 h-8 rounded-full bg-black/50 border border-white/20 flex items-center justify-center text-white" onClick={() => setShowPremiumModal(false)}>
                                    <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                                </button>
                            </div>
                            <div className="flex-1 overflow-y-auto p-6 space-y-4">
                                <div className="space-y-3">
                                    <RewardItem icon="🎴" title="Exclusive Season Variant" description="A rare Pirate variant for Wolverine." />
                                    <RewardItem icon="💰" title="2,500 Gold" description="Premium currency for variants and emotes." />
                                    <RewardItem icon="💎" title="5,000 Credits" description="Speed up your Collection Level progress." />
                                    <RewardItem icon="📦" title="10 Mega Boxes" description="Guaranteed variants and rare materials." />
                                    <RewardItem icon="🏷️" title="Exclusive Titles" description="'Captain of the Void' and more." />
                                </div>
                                <div className="pt-4">
                                    <SlantedButton variant="warning" fullWidth size="lg">
                                        <div className="flex flex-col items-center py-1">
                                            <span className="text-[0.60rem] opacity-70">UNLOCK ALL NOW</span>
                                            <span className="text-lg">GO PREMIUM</span>
                                        </div>
                                    </SlantedButton>
                                </div>
                            </div>
                        </div>
                    </ModalBackdrop>
                </Portal>
            )}
        </div>
    );
};

const RewardItem: React.FC<{ icon: string, title: string, description: string }> = ({ icon, title, description }) => (
    <div className="flex items-center gap-4 p-3 bg-slate-800/50 border border-white/5 rounded-xl hover:bg-slate-800 transition-colors">
        <div className="w-10 h-10 rounded-lg bg-indigo-500/10 flex items-center justify-center text-xl shadow-inner border border-white/5">{icon}</div>
        <div className="flex-1">
            <h4 className="text-[0.7rem] font-black text-white uppercase tracking-tight">{title}</h4>
