                        imageUrl={rewardImageUrl} 
                        level={level} 
                        cardDef={cardDef}
                    />
                </div>

                {/* 
                    4. CLAIMED BANNER OVERLAY (z-40)
                */}
                {isClaimed && (
                    <div className="absolute inset-0 flex items-center justify-center z-40 pointer-events-none pl-6">
                        <div className="bg-emerald-500 text-slate-950 text-[0.45rem] font-black uppercase tracking-[0.25em] px-3 py-0.5 rotate-[-10deg] border-y border-white shadow-[0_0_15px_rgba(16,185,129,0.4)] scale-100 ring-1 ring-white/20">
                            CLAIMED
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

