import React, { useEffect, useState } from 'react';
import { SlantedButton } from '../ui/SlantedButton';
import { GameText } from '../ui/GameText';
import { useUser } from '../../contexts/UserContext';
import { usePurchaseOffer } from '../../hooks/usePurchaseOffer';
import { CreditIcon, GoldIcon } from '../ui/CurrencyIcons';

interface StoreResourceItemProps {
    type: 'gold' | 'credits';
    amount: number;
    costLabel: string;
    costAmount?: number;
    costType: 'gold' | 'real' | 'free';
    offerId?: string;
    availableAt?: string;
}

export const StoreResourceItem: React.FC<StoreResourceItemProps> = ({ 
    type, amount, costLabel, costAmount, costType, offerId, availableAt 
}) => {
    const { user, spendGold, addCredits, addGold, processPurchase, syncStore } = useUser();
    const [timeLeft, setTimeLeft] = useState<number>(0);

    const isFree = costType === 'free';
    const hasEnoughCurrency = user ? (isFree || costType === 'real' || (costType === 'gold' && user.gold >= (costAmount || 0))) : false;

    // Time-based locking (Daily rewards)
    useEffect(() => {
        if (!availableAt) return;
        const updateTimer = () => {
            const now = Date.now();
            const target = new Date(availableAt).getTime();
            const diff = Math.max(0, Math.floor((target - now) / 1000));
            setTimeLeft(diff);
        };
        updateTimer();
        const interval = setInterval(updateTimer, 1000);
        return () => clearInterval(interval);
    }, [availableAt]);

    const handleAction = async () => {
        if (!user || !hasEnoughCurrency) {
            syncStore();
            return false;
        }

        if (isFree && offerId) {
            return await processPurchase(offerId);
        } else if (costType === 'gold' && costAmount) {
            if (spendGold(costAmount)) {
                if (type === 'credits') addCredits(amount);
                else addGold(amount);
                return true;
            }
        } else if (costType === 'real') {
            // Mock IAP
            if (type === 'gold') addGold(amount);
            else addCredits(amount);
            return true;
        }
        return false;
    };

    const { status, holdProgress, isHolding, setHoldProgress, setIsHolding, executePurchase } = usePurchaseOffer({
        onPurchase: handleAction
    });

    const isLocked = timeLeft > 0;
    const isSuccess = status === 'success';
    const isProcessing = status === 'processing';

    return (
        <div className={`
            bg-gradient-to-b from-slate-800 via-slate-900 to-black border-2 transition-all duration-300 rounded p-2 flex flex-col items-center justify-between h-[10.5rem] relative overflow-hidden shadow-2xl
            ${isSuccess ? 'border-emerald-400 ring-2 ring-emerald-500/50 bg-emerald-950' : 'border-slate-700'}
        `}>
            {/* Success Flash */}
            {isSuccess && <div className="absolute inset-0 bg-white/20 animate-pulse z-40 pointer-events-none" />}

            {/* Hold Progress Bar Overlay */}
            {holdProgress > 0 && status === 'idle' && !isLocked && (
                <div 
                    className={`absolute inset-y-0 left-0 z-0 pointer-events-none ${type === 'gold' ? 'bg-amber-400/30' : 'bg-blue-400/30'}`}
                    style={{ width: `${holdProgress}%` }}
                />
            )}

            {/* Amount & Label */}
            <div className="relative z-10 text-center w-full px-1">
                <div className="h-6 w-full mb-0.5">
                    <GameText 
                        text={amount.toLocaleString()} 
                        baseFontSize={1.1} 
                        className="text-white drop-shadow-md"
                    />
                </div>
                <div className={`text-[0.45rem] font-black uppercase tracking-[0.2em] leading-none ${type === 'gold' ? 'text-amber-500' : 'text-blue-400'}`}>
                    {type}
                </div>
            </div>

            {/* Resource Icon Visual */}
            <div className="relative z-10 flex-1 flex items-center justify-center">
                <div className={`
                    w-12 h-12 rounded-full flex items-center justify-center border-2 transition-all duration-500
                    ${isSuccess ? 'bg-emerald-500 border-emerald-300 scale-110 shadow-[0_0_20px_rgba(16,185,129,0.8)]' : 'bg-slate-900 border-slate-700'}
                `}>
                    {isSuccess ? (
                        <svg className="w-7 h-7 text-white animate-pop" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={4} d="M5 13l4 4L19 7" /></svg>
                    ) : (
                        type === 'gold' ? <GoldIcon size="md" /> : <CreditIcon size="md" />
                    )}
                </div>
            </div>

            {/* Bottom Status / Timer / Button */}
            <div className="w-full relative z-10">
                <div className="h-3 flex items-center justify-center mb-0.5 overflow-visible">
                    {isHolding && status === 'idle' && !isLocked && (
                        <span className="text-[0.45rem] font-black text-white uppercase tracking-wider animate-pulse drop-shadow-[0_2px_2px_rgba(0,0,0,1)] whitespace-nowrap">Hold to acquire</span>
                    )}
                    {isProcessing && (
                        <span className="text-[0.45rem] font-black text-white animate-pulse uppercase tracking-wider drop-shadow-[0_2px_2px_rgba(0,0,0,1)] whitespace-nowrap">Processing...</span>
                    )}
                    {isSuccess && (
                        <span className="text-[0.45rem] font-black text-white animate-bounce uppercase tracking-wider drop-shadow-[0_2px_2px_rgba(0,0,0,1)] whitespace-nowrap">Purchased!</span>
                    )}
                </div>

                {isLocked ? (
                    <div className="h-8 w-full bg-slate-900 border border-slate-700 rounded flex items-center justify-center gap-1.5 grayscale opacity-60">
                         <svg className="w-2.5 h-2.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                         <span className="text-[0.6rem] font-black tabular-nums">{Math.floor(timeLeft / 60)}:{(timeLeft % 60).toString().padStart(2, '0')}</span>
                    </div>
                ) : (
                    <SlantedButton 
                        variant={isSuccess ? 'success' : (type === 'gold' ? 'primary' : 'blue')} 
                        size="sm" 
                        fullWidth
                        holdDuration={isFree ? 0 : 800}
                        onHoldChange={setIsHolding}
                        onProgressChange={setHoldProgress}
                        onClick={executePurchase}
                        disabled={isProcessing || isSuccess}
                    >
                        {isSuccess ? 'READY' : costLabel}
                    </SlantedButton>
                )}
            </div>
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { HexButton } from '../ui/HexButton';
import { GameText } from '../ui/GameText';
import { useUser } from '../../contexts/UserContext';
import { audio } from '../../services/audio';
import { CreditIcon, GoldIcon } from '../ui/CurrencyIcons';

interface StoreCreditItemProps {
    amount: number;
    cost: number | 'FREE';
    offerId?: string; 
    availableAt?: string; 
}

export const StoreCreditItem: React.FC<StoreCreditItemProps> = ({ amount, cost, offerId, availableAt }) => {
    const { user, spendGold, addCredits, processPurchase, syncStore } = useUser();
    const [holdProgress, setHoldProgress] = useState(0);
    const [isHolding, setIsHolding] = useState(false);
    const [status, setStatus] = useState<'idle' | 'processing' | 'success'>('idle');
    const isFree = cost === 'FREE';

    const [timeLeft, setTimeLeft] = useState<number>(0);
    const hasEnoughGold = user ? (isFree || user.gold >= (cost as number)) : false;

    useEffect(() => {
        if (!availableAt) return;
        const updateTimer = () => {
            const now = Date.now();
            const target = new Date(availableAt).getTime();
            const diff = Math.max(0, Math.floor((target - now) / 1000));
            setTimeLeft(diff);
        };
        updateTimer();
        const interval = setInterval(updateTimer, 1000);
        return () => clearInterval(interval);
    }, [availableAt]);

    const handlePurchase = async () => {
        if (!user || timeLeft > 0 || status !== 'idle') return;

        if (!hasEnoughGold) {
            syncStore();
            return;
        }

        setStatus('processing');

        let success = false;
        if (isFree && offerId) {
            success = await processPurchase(offerId);
        } else if (isFree) {
            addCredits(amount);
            success = true;
        } else {
            const hasFunds = spendGold(cost as number);
            if (hasFunds) {
                addCredits(amount);
                success = true;
            } else {
                setStatus('idle');
                syncStore();
                return;
            }
        }

        if (success) {
            setTimeout(() => {
                setStatus('success');
                audio.play('sfx_victory', 0.5);
                setTimeout(() => setStatus('idle'), 2500);
            }, 800);
        } else {
            setStatus('idle');
        }
    };

    const formatTime = (seconds: number) => {
        if (seconds < 60) return `${seconds}s`;
        const m = Math.floor(seconds / 60);
        const s = seconds % 60;
        return `${m}m ${s}s`;
    };

    return (
        <div className={`bg-gradient-to-b from-slate-800 via-slate-900 to-black border-2 transition-all duration-300 rounded p-2 flex flex-col items-center justify-between gap-1 h-[10rem] relative group shadow-[0_4px_15px_rgba(0,0,0,0.8)] overflow-hidden ${status === 'success' ? 'border-emerald-400 ring-2 ring-emerald-500/50 bg-emerald-950' : 'border-slate-700'}`}>
            {status === 'success' && (
                <div className="absolute inset-0 bg-white/40 animate-pulse z-40 pointer-events-none" />
            )}

            {holdProgress > 0 && status === 'idle' && !isFree && hasEnoughGold && (
                <div 
                    className="absolute inset-y-0 left-0 bg-cyan-300 shadow-[0_0_2rem_rgba(34,211,238,1),0_0_4rem_rgba(34,211,238,0.5)] z-0 pointer-events-none"
                    style={{ width: `${holdProgress}%` }}
                />
            )}

            <div className="mt-1 w-full px-1 relative z-10 flex flex-col items-center">
                <div className="h-6 w-full mb-0.5">
                    <GameText 
                        text={amount.toLocaleString()} 
                        baseFontSize={1.15} // Fixed multiplier
                        className="text-white drop-shadow-md"
                    />
                </div>
                <div className="text-[0.45rem] font-black text-blue-400 uppercase tracking-widest leading-none">CREDITS</div>
            </div>

            <div className="w-full flex-1 flex items-center justify-center py-1 min-h-[2.5rem] relative z-10">
                <div className={`w-10 h-10 rounded-full flex items-center justify-center border-2 transition-all duration-500 ${status === 'success' ? 'bg-emerald-500 border-emerald-300 scale-110 shadow-[0_0_25px_rgba(16,185,129,1)]' : 'bg-blue-900 border-blue-400 shadow-[inset_0_0_10px_rgba(0,0,0,0.5)]'}`}>
                    {status === 'success' ? (
                        <svg className="w-6 h-6 text-white animate-pop" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={4} d="M5 13l4 4L19 7" /></svg>
                    ) : (
                        <CreditIcon size="md" />
                    )}
                </div>
            </div>

            <div className="w-full h-1 relative flex items-center justify-center pointer-events-none mb-0.5 z-10 overflow-visible">
                {isHolding && status === 'idle' && !isFree && hasEnoughGold && (
                    <div className="relative font-black text-[0.45rem] uppercase tracking-widest leading-none drop-shadow-[0_1px_2px_rgba(0,0,0,1)]">
                        <span className="text-white/40 whitespace-nowrap">HOLD TO BUY</span>
                        <div 
                            className="absolute inset-0 text-white whitespace-nowrap overflow-hidden"
                            style={{ width: `${holdProgress}%` }}
                        >
                            HOLD TO BUY
                        </div>
                    </div>
                )}
                {status === 'processing' && (
                    <span className="text-[0.45rem] font-black text-cyan-300 uppercase tracking-[0.25em] leading-none animate-pulse drop-shadow-[0_0_5px_rgba(34,211,238,0.8)]">SYNCING...</span>
                )}
                {status === 'success' && (
                    <span className="text-[0.45rem] font-black text-emerald-400 uppercase tracking-[0.25em] leading-none animate-bounce origin-bottom drop-shadow-[0_0_5px_rgba(52,211,153,0.8)]">DEPOSITED</span>
                )}
            </div>

            <div className="w-full mt-auto relative z-10">
                {timeLeft > 0 ? (
                    <div className="h-7 w-full bg-slate-900 border-2 border-slate-700 rounded flex items-center justify-center gap-1.5 overflow-hidden">
                        <svg className="w-2.5 h-2.5 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                        <span className="text-[0.6rem] font-black text-slate-400 uppercase tracking-tighter tabular-nums">
                            {formatTime(timeLeft)}
                        </span>
                    </div>
                ) : (
                    <div className="h-7">
                        <HexButton 
                            variant={status === 'success' ? 'success' : (isFree ? 'success' : 'secondary')} 
                            size="sm" 
                            fullWidth
                            onClick={handlePurchase}
                            disabled={status !== 'idle'}
                            holdDuration={isFree || !hasEnoughGold ? 0 : 1000}
                            onHoldChange={setIsHolding}
                            onProgressChange={setHoldProgress}
                        >
                            {status === 'processing' ? "SYNCING" : (status === 'success' ? "SYNCED" : (isFree ? "FREE" : <div className="flex items-center justify-center gap-1"><GoldIcon size="xs" /> {cost}</div>))}
                        </HexButton>
                    </div>
                )}
            </div>
        </div>
    );
};

import { useState, useEffect, useMemo } from 'react';
import { useUser } from '../contexts/UserContext';

export const useSeasonPass = () => {
    const { user, seasonPassData, isSeasonLoading, syncSeasonPass, debugSwitchSeason } = useUser();
    const [timeLeft, setTimeLeft] = useState({ dd: '00', hh: '00', mm: '00', ss: '00' });

    // 1. Timer Logic
    useEffect(() => {
        if (!seasonPassData?.endDate) return;

        const updateTimer = () => {
            const now = new Date().getTime();
            const distance = new Date(seasonPassData.endDate).getTime() - now;

            if (distance < 0) {
                setTimeLeft({ dd: '00', hh: '00', mm: '00', ss: '00' });
                return;
            }

            setTimeLeft({
                dd: String(Math.floor(distance / (1000 * 60 * 60 * 24))).padStart(2, '0'),
                hh: String(Math.floor((distance % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60))).padStart(2, '0'),
                mm: String(Math.floor((distance % (1000 * 60 * 60)) / (1000 * 60))).padStart(2, '0'),
                ss: String(Math.floor((distance % (1000 * 60)) / 1000)).padStart(2, '0')
            });
        };

        const interval = setInterval(updateTimer, 1000);
        updateTimer();
        return () => clearInterval(interval);
    }, [seasonPassData]);

    // 2. High-Precision Progress Logic - Fully Synced with User context
    const progress = useMemo(() => {
        if (!user) {
            return { currentLevel: 0, currentXP: 0, targetXP: 1000, percent: 0 };
        }
        const currentXP = user.seasonXp; 
        const targetXP = 1000;
        const percent = Math.min(100, (currentXP / targetXP) * 100);

        return {
            currentLevel: user.level,
            currentXP,
            targetXP,
            percent
        };
    }, [user?.level, user?.seasonXp]);

    return {
        user,
        seasonPassData,
        isSeasonLoading,
        timeLeft,
        progress,
        actions: {
            syncSeasonPass,
            debugSwitchSeason
        }
    };
};

import React, { useState, useCallback, useMemo, useRef, useEffect } from 'react';
import { StandardHeader } from '../ui/StandardHeader';
import { DeckSelector } from '../game/DeckSelector';
import { CollectionGrid } from '../deck/CollectionGrid';
import { DeckVault } from '../deck/DeckVault';
import { ComicArchive } from '../deck/ComicArchive';
import { InventoryStash } from '../deck/InventoryStash';
import { CollectionDragOverlay } from '../CollectionDragOverlay';
import { useUser } from '../../contexts/UserContext';
import { useCollectionDrag } from '../../hooks/useCollectionDrag';
import { CARDS } from '../../constants';
import { CardDefinition, CollectionTab, ScreenKey } from '../../types';
import { HexBadge } from '../ui/HexBadge';

interface DeckScreenProps {
    onNavigate: (s: ScreenKey) => void;
    // We expect the parent to pass the current active screen so we can reset tabs on entry
    activeScreen?: ScreenKey; 
}

export const DeckScreen: React.FC<DeckScreenProps> = ({ activeScreen }) => {
    const { user, updateDeck, activeDeck, setActiveDeck } = useUser();
    const [activeTab, setActiveTab] = useState<CollectionTab>('CARDS');

    // EFFECT: Always default to CARDS when the player "arrives" at this world
    useEffect(() => {
        if (activeScreen === 'DECK') {
            setActiveTab('CARDS');
        }
    }, [activeScreen]);

    const scrollRef = useRef<HTMLDivElement>(null);
    const vaultRef = useRef<HTMLDivElement>(null);
    const archiveRef = useRef<HTMLDivElement>(null);

    const handleAddCard = useCallback((cardId: string) => {
        if (user && activeDeck.length < 12 && !activeDeck.includes(cardId)) {
            updateDeck(user.activeDeckId, [...activeDeck, cardId]);
        }
    }, [activeDeck, user?.activeDeckId, updateDeck, user]);

    const handleRemoveCard = useCallback((cardId: string) => {
        if (user) {
            updateDeck(user.activeDeckId, activeDeck.filter(id => id !== cardId));
        }
    }, [activeDeck, user?.activeDeckId, updateDeck, user]);

    const { dragState, handlePointerDown } = useCollectionDrag({
        onAdd: handleAddCard,
        onRemove: handleRemoveCard,
        scrollRef: scrollRef,
        vaultRef: vaultRef,
        archiveRef: archiveRef
    });

    const deckCards = useMemo(() => {
        return activeDeck
            .map(id => CARDS.find(c => c.id === id))
            .filter((c): c is CardDefinition => !!c)
            .sort((a, b) => {
                if (a.baseCost !== b.baseCost) {
                    return a.baseCost - b.baseCost;
                }
                return a.name.localeCompare(b.name);
            });
    }, [activeDeck]);

    if (!user) {
        return (
            <div className="w-full h-full flex flex-col items-center justify-center bg-slate-950/20 backdrop-blur-md">
                <div className="w-8 h-8 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin mb-4" />
                <span className="text-[0.6rem] font-black text-indigo-400 uppercase tracking-[0.3em] animate-pulse">Syncing Inventory...</span>
            </div>
        );
    }

    const renderContent = () => {
        switch(activeTab) {
            case 'COMICS': return <ComicArchive />;
            case 'INVENTORY': return <InventoryStash />;
            default:
                return (
                    <div className="flex flex-col h-full overflow-hidden">
                        {/* 1. DECK SELECTION & VAULT ZONE */}
                        <div 
                            ref={vaultRef}
                            className={`shrink-0 border-b border-slate-700/50 z-20 transition-all duration-300 ${dragState?.active && dragState.origin === 'archive' ? 'ring-2 ring-inset ring-indigo-500/50' : ''}`}
                            data-drop-zone="vault"
                        >
                            <DeckSelector 
                                activeDeckId={user.activeDeckId} 
                                onSelectDeck={setActiveDeck}
                            />

                            <div className="px-3 pb-2">
                                <DeckVault 
                                    cards={deckCards} 
                                    draggingCardId={dragState?.active && dragState.origin === 'vault' ? dragState.card.id : undefined}
                                    onPointerDown={(e, card) => handlePointerDown(e, card, 'vault')}
                                />
                            </div>
