                    border-color: #f87171 !important;
                    box-shadow: 0 0.2rem 0 #7f1d1d, 0 0 20px rgba(239, 68, 68, 0.3) !important;
                }

                .is-visually-center .label-cq { color: #ffffffaa !important; }
                .is-visually-center .label-ld { color: #ffffffaa !important; }
                .is-visually-center { filter: grayscale(0) !important; }
            `}</style>
        </div>
    );
