    async getSeasonPass(user: UserProfile): Promise<SeasonPassData> {
        await new Promise(resolve => setTimeout(resolve, 500));

        const season = SEASONS[currentSeasonIndex];
        const seasonId = season.id;

        // Lookup User Progress for THIS specific season
        const userProgress = user.seasonProgress[seasonId] || { level: 1, xp: 0 };

        const endDate = "2025-12-31T23:59:59Z";
        const endsInSeconds = Math.floor((new Date(endDate).getTime() - Date.now()) / 1000);

        const heroCard = CARDS.find(c => c.id === season.heroCardId)!;

        const rewards: SeasonPassReward[] = Array.from({ length: 100 }, (_, i) => {
            const level = i + 1;
            let type: SeasonRewardType = 'credits';
            let amount: string | number = 50;
            let specificCardDef = undefined;

            if (level === 50) {
                type = 'card';
                amount = 'SEASON EXCLUSIVE';
                specificCardDef = heroCard;
            } else if (level % 10 === 0) {
                type = 'card';
                amount = 'VARIANT';
                specificCardDef = CARDS[Math.floor((level / 10) % CARDS.length)];
            } else if (level % 5 === 0) {
                type = 'gold';
                amount = 100;
            } else if (level % 2 === 0) {
                type = 'booster';
                amount = 10;
            } else {
                type = 'credits';
                amount = 50 + (Math.floor(level / 10) * 10);
            }

            return {
                level,
                type,
                amount,
                cardDef: specificCardDef,
                isClaimed: level < userProgress.level,
                isActive: level === userProgress.level,
                isLocked: level > userProgress.level
            };
        });

        return {
            id: seasonId,
            themeName: season.name,
            startDate: "2025-01-01T00:00:00Z",
            endDate,
            endsInSeconds,
            premiumActive: true,
            heroCardId: season.heroCardId,
            heroVariantName: season.heroVariant,
            rewards
        };
    },

    async getStoreOffers(user: UserProfile): Promise<StoreData> {
        await new Promise(resolve => setTimeout(resolve, 600)); 
        const filteredOffers = MOCK_STORE_OFFERS.filter(offer => {
            if (offer.isOneTime && user.purchasedOfferIds.includes(offer.id)) return false;
            if (offer.purchaseLimit) {
                const count = user.purchasedOfferIds.filter(id => id === offer.id).length;
                if (count >= offer.purchaseLimit) return false;
            }
            if (offer.expiryDate && new Date(offer.expiryDate) < new Date()) return false;
            return true;
        }).map(offer => {
            if (offer.cooldownSeconds && user.lastClaimedDates[offer.id]) {
                const lastClaimed = new Date(user.lastClaimedDates[offer.id]).getTime();
                const availableAt = new Date(lastClaimed + (offer.cooldownSeconds * 1000));
                return { ...offer, availableAt: availableAt.toISOString() };
            }
            return offer;
        });

        return {
            offers: filteredOffers,
            lastUpdated: Date.now(),
            refreshHintSeconds: 60
        };
    },

    async purchaseOffer(user: UserProfile, offerId: string, transactionId: string): Promise<PurchaseResponse> {
        await new Promise(resolve => setTimeout(resolve, 800 + Math.random() * 400));
        if (processedTransactions.has(transactionId)) return { success: false, errorCode: 'ERR_DUPLICATE_TRANSACTION', transactionId };
        const offer = MOCK_STORE_OFFERS.find(o => o.id === offerId);
        if (!offer) return { success: false, errorCode: 'ERR_OFFER_NOT_FOUND', transactionId };
        if (offer.cooldownSeconds && user.lastClaimedDates[offer.id]) {
            const lastClaimed = new Date(user.lastClaimedDates[offer.id]).getTime();
            if (Date.now() < lastClaimed + (offer.cooldownSeconds * 1000)) return { success: false, errorCode: 'ERR_COOLDOWN_ACTIVE', transactionId };
        }
        if (offer.priceType === 'gold' && user.gold < (offer.priceAmount || 0)) return { success: false, errorCode: 'ERR_INSUFFICIENT_FUNDS', transactionId };
        if (offer.priceType === 'credits' && user.credits < (offer.priceAmount || 0)) return { success: false, errorCode: 'ERR_INSUFFICIENT_FUNDS', transactionId };
        processedTransactions.add(transactionId);
        const updatedProfile: UserProfile = { ...user };
        if (offer.priceType === 'gold') updatedProfile.gold -= (offer.priceAmount || 0);
        if (offer.priceType === 'credits') updatedProfile.credits -= (offer.priceAmount || 0);
        offer.contents.forEach(item => {
            if (item.type === 'currency') {
                if (item.currencyType === 'gold') updatedProfile.gold += item.amount;
                if (item.currencyType === 'credits') updatedProfile.credits += item.amount;
            } else if (item.type === 'card' && !updatedProfile.collection.includes(item.definitionId)) {
                updatedProfile.collection = [...updatedProfile.collection, item.definitionId];
            }
        });
        updatedProfile.purchasedOfferIds = [...updatedProfile.purchasedOfferIds, offerId];
        updatedProfile.lastClaimedDates = { ...updatedProfile.lastClaimedDates, [offerId]: new Date().toISOString() };
        return { success: true, transactionId, updatedProfile };
    }
};

import { useState, useEffect, useMemo } from 'react';
import { useUser } from '../contexts/UserContext';

export const useSeasonPass = () => {
    const { user, seasonPassData, isSeasonLoading, syncSeasonPass, debugSwitchSeason } = useUser();
    const [timeLeft, setTimeLeft] = useState({ dd: '00', hh: '00', mm: '00', ss: '00' });

    // 1. Timer Logic
    useEffect(() => {
        if (!seasonPassData?.endDate) return;

        const updateTimer = () => {
            const now = new Date().getTime();
            const distance = new Date(seasonPassData.endDate).getTime() - now;

            if (distance < 0) {
                setTimeLeft({ dd: '00', hh: '00', mm: '00', ss: '00' });
                return;
            }

            setTimeLeft({
                dd: String(Math.floor(distance / (1000 * 60 * 60 * 24))).padStart(2, '0'),
                hh: String(Math.floor((distance % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60))).padStart(2, '0'),
                mm: String(Math.floor((distance % (1000 * 60 * 60)) / (1000 * 60))).padStart(2, '0'),
                ss: String(Math.floor((distance % (1000 * 60)) / 1000)).padStart(2, '0')
            });
        };

        const interval = setInterval(updateTimer, 1000);
        updateTimer();
        return () => clearInterval(interval);
    }, [seasonPassData]);

    // 2. High-Precision Progress Logic - Fully Synced with specific season ID
    const progress = useMemo(() => {
        if (!user || !seasonPassData) {
            return { currentLevel: 1, currentXP: 0, targetXP: 1000, percent: 0 };
        }

        // Determine user level for THIS specific season
        const seasonId = seasonPassData.id;
        const seasonData = user.seasonProgress[seasonId] || { level: 1, xp: 0 };

        const currentXP = seasonData.xp; 
        const targetXP = 1000;
        const percent = Math.min(100, (currentXP / targetXP) * 100);

        return {
            currentLevel: seasonData.level,
            currentXP,
            targetXP,
            percent
        };
    }, [user?.seasonProgress, seasonPassData?.id]);

    return {
        user,
        seasonPassData,
        isSeasonLoading,
        timeLeft,
        progress,
        actions: {
            syncSeasonPass,
            debugSwitchSeason
        }
    };
};

import React, { useState, useEffect, useRef } from 'react';
import { AppShell } from './components/ui/AppShell';
import { LoadingScreen } from './components/screens/LoadingScreen';
import { LoginScreen } from './components/screens/LoginScreen';
import { NavigationBar } from './components/ui/NavigationBar';
import { InspectorOverlay } from './components/InspectorOverlay';
import { preloadAssets } from './services/assetLoader';
import { audio } from './services/audio';
import { api } from './services/api';
import { useSpatialNavigation } from './hooks/useSpatialNavigation';
import { ScreenKey, UserProfile } from './types';
import { UserProvider } from './contexts/UserContext';

export default function App() {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [loadingProgress, setLoadingProgress] = useState(0);
  const [isAppReady, setIsAppReady] = useState(false); // Controls the final curtain lift
  const [userProfile, setUserProfile] = useState<UserProfile | null>(null);

  // Initialize with all screens "visited" during boot to force layout warm-up
  const [visitedScreens, setVisitedScreens] = useState<Set<ScreenKey>>(new Set());
  const musicInitializedRef = useRef(false);

  const { 
      activeScreen, 
      prevScreen, 
      isTransitioning, 
      containerStyle, 
      navigateTo, 
      resetToMenu, 
      WORLDS 
  } = useSpatialNavigation();

  // 1. DUAL-PHASE BOOT SEQUENCE
  useEffect(() => {
    const initApp = async () => {
      // Phase A: Fetch Profile (Prerequisite for mounting UserProvider)
      try {
          const profile = await api.getProfile('u1');
          setUserProfile(profile);
          // Once profile is set, the UserProvider branch below mounts.
          // We start the asset/font preload immediately after.

          await preloadAssets((progress) => setLoadingProgress(progress));

          // Phase B: Layout Warm-up
          // We mark all screens as "visited" so they render and calculate ResizeObservers
          setVisitedScreens(new Set(Object.keys(WORLDS) as ScreenKey[]));

          // Small buffer to let the layout engine actually paint the hidden screens
          setTimeout(() => {
              setIsAppReady(true);
          }, 800);
      } catch (err) {
          console.error("FATAL ERROR: Could not initialize Galactic Snap.", err);
      }
    };
    initApp();
  }, []);

  // 2. MUSIC ORCHESTRATION
  useEffect(() => {
      if (!isLoggedIn || !isAppReady) return;
      const targetBgm = activeScreen === 'GAME' ? 'bgm_game' : 'bgm_menu';
      audio.playBgm(targetBgm);
  }, [activeScreen, isLoggedIn, isAppReady]);

  const handleLogin = async () => {
      await audio.init(); 
      audio.playUiClick();
      setIsLoggedIn(true);
      musicInitializedRef.current = true;
  };

  const handleLogout = () => {
      audio.playUiClick();
      audio.stopBgm();
      setIsLoggedIn(false);
      musicInitializedRef.current = false;
      resetToMenu();
  };

  const handleStartGame = () => navigateTo('GAME');

  // Initial gate: We need the profile to even start the warming process
  if (!userProfile) {
      return (
          <AppShell>
              <LoadingScreen progress={loadingProgress} isVisible={true} />
          </AppShell>
      );
  }

  return (
    <UserProvider initialUser={userProfile}>
        <AppShell>
            {/* 
                THE LOADING CURTAIN
                It stays mounted on top until isAppReady is true.
                The rest of the app mounts underneath it immediately.
            */}
            <LoadingScreen 
                progress={loadingProgress} 
                isVisible={!isAppReady} 
            />

            {/* THE APP CONTENT (Always Mounted behind the curtain once profile exists) */}
            <div className={`w-full h-full relative transition-opacity duration-700 ${isAppReady ? 'opacity-100' : 'opacity-0'}`}>

                {/* LOGIN LAYER (Only shown if not logged in) */}
                {!isLoggedIn && (
                    <div className="absolute inset-0 z-[100] bg-slate-950">
                        <LoginScreen onLogin={handleLogin} />
                    </div>
                )}

                <InspectorOverlay />

                {/* THE SPATIAL GRID */}
                <div 
                    className="w-full h-full relative transition-transform duration-500 ease-[cubic-bezier(0.22,1,0.36,1)] will-change-transform"
                    style={containerStyle}
                >
                    {(Object.keys(WORLDS) as ScreenKey[]).map((key) => {
                        const hasBeenVisited = visitedScreens.has(key);
                        const isActive = key === activeScreen;
                        const isPrev = key === prevScreen;
                        const isParticipatingInTransition = isActive || (isTransitioning && isPrev);

                        // Optimization: During warm-up we render everything. 
                        // After boot, we only render visited/active screens.
                        if (!isAppReady) {
                             // Force all screens to exist for layout measurement
                        } else if (!hasBeenVisited && !isParticipatingInTransition) {
                             return null;
                        }

                        const config = WORLDS[key];
                        const ScreenComponent = config.component;

                        return (
                            <div 
                                key={key} 
                                className={`absolute w-full h-full top-0 left-0 overflow-hidden transition-opacity duration-300 ${!isParticipatingInTransition ? 'pointer-events-none invisible opacity-0' : 'pointer-events-auto visible opacity-100'}`}
                                style={{ 
                                    transform: `translate3d(${config.x * 100}%, ${config.y * 100}%, 0)`,
                                }}
                            >
                                <ScreenComponent 
                                    activeScreen={activeScreen} 
                                    onNavigate={navigateTo} 
                                    onExit={() => navigateTo('MENU')}
                                    onBack={() => navigateTo('MENU')}
                                    onStartGame={handleStartGame}
                                    onLogout={handleLogout}
                                />
                            </div>
                        );
                    })}
                </div>

                {isLoggedIn && activeScreen !== 'GAME' && (
                    <NavigationBar activeScreen={activeScreen} onNavigate={navigateTo} />
                )}
            </div>

        </AppShell>
    </UserProvider>
  );
}

