import { AUDIO_MANIFEST } from '../utils/assets';
import { CARDS, LOCATION_DEFS } from '../constants';
import { audio } from './audio';

/**
 * Ensures all external assets and critical fonts are ready for high-precision measurement.
 */
export const preloadAssets = async (onProgress: (progress: number) => void) => {
  let loaded = 0;

  // 1. Gather all URLs
  const imagesToLoad = [
    ...CARDS.map(c => c.imageUrl),
    ...LOCATION_DEFS.map(l => l.imageUrl),
  ];

  const audioKeys = Object.keys(AUDIO_MANIFEST);

  // Weights: Images (1 each), Audio (1 each), Font Sync (20 total steps)
  const totalAssets = imagesToLoad.length + audioKeys.length + 20;

  const updateProgress = () => {
    loaded++;
    const percentage = Math.min(100, Math.floor((loaded / totalAssets) * 100));
    onProgress(percentage);
  };

  // 2. Preload Images
  const imagePromises = imagesToLoad.map(src => {
    return new Promise<void>((resolve) => {
      const img = new Image();
      img.src = src;
      img.onload = () => {
        updateProgress();
        resolve();
      };
      img.onerror = () => {
        console.warn(`Failed to load image: ${src}`);
        updateProgress();
        resolve();
      };
    });
  });

  // 3. Initialize Audio
  audio.init();
  audioKeys.forEach(() => updateProgress());

  // 4. Strict Typographic Synchronization
  if ('fonts' in document) {
    try {
        // Wait for preloads and the browser to settle
        await (document as any).fonts.ready;
        updateProgress();

        const fontVariants = [
            '400 16px "IBM Plex Sans"',
            '700 16px "IBM Plex Sans"',
            'italic 700 16px "IBM Plex Sans"',
            '400 16px "IBM Plex Sans Condensed"',
            '700 16px "IBM Plex Sans Condensed"'
        ];

        // Ensure each critical variant is actually in the cache
        for (const variant of fontVariants) {
            try {
                await (document as any).fonts.load(variant);
            } catch (e) {}
            updateProgress();
        }

        // Fill remaining progress steps to allow progress bar to feel smooth
        for(let i=0; i<14; i++) updateProgress();

        // CRITICAL: Safety buffer for the font engine to update layout metrics
        // We wait for two frames + a small timeout to ensure ResizeObservers trigger.
        await new Promise(resolve => requestAnimationFrame(() => 
            requestAnimationFrame(() => setTimeout(resolve, 200))
        ));
    } catch (e) {
        console.warn("Font preloading failed, falling back to system metrics.", e);
    }
  }

  await Promise.all([...imagePromises]);
};

import { AUDIO_MANIFEST } from '../utils/assets';
import { CARDS, LOCATION_DEFS } from '../constants';
import { audio } from './audio';

/**
 * PRODUCTION-GRADE ASSET PIPELINE
 * Ensures images, audio, and CRITICAL typographic metrics are settled.
 */
export const preloadAssets = async (onProgress: (progress: number) => void) => {
  let loaded = 0;

  const imagesToLoad = [
    ...CARDS.map(c => c.imageUrl),
    ...LOCATION_DEFS.map(l => l.imageUrl),
  ];

  const audioKeys = Object.keys(AUDIO_MANIFEST);
  const totalAssets = imagesToLoad.length + audioKeys.length + 30; // +30 for metric verification steps

  const updateProgress = (steps = 1) => {
    loaded += steps;
    const percentage = Math.min(100, Math.floor((loaded / totalAssets) * 100));
    onProgress(percentage);
  };

  // 1. Parallel Image Loading
  const imagePromises = imagesToLoad.map(src => {
    return new Promise<void>((resolve) => {
      const img = new Image();
      img.src = src;
      img.onload = () => { updateProgress(); resolve(); };
      img.onerror = () => { updateProgress(); resolve(); };
    });
  });

  // 2. Audio Init
  audio.init();
  updateProgress(audioKeys.length);

  // 3. TYPOGRAPHIC VERIFICATION (The Robustness Fix)
  if ('fonts' in document) {
    try {
        await (document as any).fonts.ready;
        updateProgress(5);

        // We create a ghost element to detect "Font Snap"
        const tester = document.createElement('div');
        tester.style.cssText = 'position:fixed;top:-999px;font-family:"IBM Plex Sans";font-weight:700;font-style:italic;font-size:100px;visibility:hidden;';
        tester.innerText = 'THE_QUICK_BROWN_FOX';
        document.body.appendChild(tester);

        let stableFrames = 0;
        let lastWidth = 0;

        // Poll metrics for up to 2 seconds or until 3 frames of stability
        for (let i = 0; i < 20; i++) {
            const currentWidth = tester.offsetWidth;
            if (currentWidth > 0 && currentWidth === lastWidth) {
                stableFrames++;
            } else {
                stableFrames = 0;
            }

            lastWidth = currentWidth;
            updateProgress(1);

            if (stableFrames >= 3) break;
            await new Promise(r => requestAnimationFrame(r));
        }

        document.body.removeChild(tester);
        updateProgress(5);
    } catch (e) {
        console.warn("Typography check failed:", e);
    }
  }

  await Promise.all([...imagePromises]);
  onProgress(100);
};

