import React, { useState, useLayoutEffect, useRef, useEffect, useCallback } from 'react';

interface GameTextProps {
  text: string;
  className?: string;
  /** 
   * RELATIVE SCALE BASIS
   * Interpreted as 'em' relative to container font-size.
   */
  baseFontSize: number;
  /** How much we allow the text to shrink. */
  minScale?: number;
  /** How much we allow the text to grow beyond its base size. Default 1.0 (no growth). */
  maxScale?: number;
  /** Max lines for wrapping. */
  maxLines?: number;
}

export const GameText: React.FC<GameTextProps> = ({ 
  text, 
  className = '', 
  baseFontSize, 
  minScale = 0.2,
  maxScale = 1.0,
  maxLines = 1
}) => {
  const [layout, setLayout] = useState<{ lines: string[], scale: number, finalPx: number }>({ 
      lines: [text || ''], 
      scale: 1,
      finalPx: 16
  });
  const containerRef = useRef<HTMLDivElement>(null);
  const ghostRef = useRef<HTMLDivElement>(null);

  const findBestLayout = useCallback(() => {
    const container = containerRef.current;
    const ghost = ghostRef.current;
    if (!container || !ghost || !text) return;

    const containerWidth = container.clientWidth;
    const containerHeight = container.clientHeight;

    // Safety: If the app is in 'Warm-Up' and container metrics are 0, wait.
    if (containerWidth <= 0 || containerHeight <= 0) return;

    const parentStyle = window.getComputedStyle(container);
    const parentPx = parseFloat(parentStyle.fontSize) || 16;

    // Safety: Prevent 0px text
    if (parentPx <= 0) return;

    const targetPx = parentPx * baseFontSize;
    const words = text.split(/\s+/);

    const splitIntoLines = (numLines: number): string[] => {
      if (numLines <= 1 || words.length <= 1) return [text];
      const targetCharsPerLine = text.length / numLines;
      const result: string[][] = Array.from({ length: numLines }, () => []);
      let currentLine = 0;
      let currentChars = 0;

      words.forEach((word) => {
        if (currentLine < numLines - 1) {
            const distIfStay = Math.abs((currentChars + word.length) - targetCharsPerLine);
            const distIfMove = Math.abs(currentChars - targetCharsPerLine);
            if (currentChars > 0 && distIfMove < distIfStay) {
                currentLine++;
                currentChars = 0;
            }
        }
        result[currentLine].push(word);
        currentChars += word.length + 1;
      });

      return result.map(l => l.join(' ')).filter(s => s.length > 0);
    };

    const measureLayout = (lines: string[]) => {
      ghost.innerHTML = lines.map(l => `<div>${l}</div>`).join('');
      ghost.style.fontSize = `${targetPx}px`;

      const ghostWidth = ghost.offsetWidth;
      const ghostHeight = ghost.offsetHeight;

      if (ghostWidth <= 0 || ghostHeight <= 0) return 1;

      const widthRatio = (containerWidth / ghostWidth) * 0.99;
      const heightRatio = (containerHeight / ghostHeight) * 0.99;

      return Math.min(widthRatio, heightRatio);
    };

    let bestScale = 0;
    let bestLines: string[] = [text];
    const limit = Math.min(maxLines, 4); 

    for (let i = 1; i <= limit; i++) {
      if (i > words.length) break;
      const candidateLines = splitIntoLines(i);
      const scale = measureLayout(candidateLines);

      // Heuristic bias to prefer fewer lines if scales are similar
      const bias = (limit - i) * 0.02; 
      if (scale + bias > bestScale) {
        bestScale = scale;
        bestLines = candidateLines;
      }

      // If single line already fits perfectly, we stop searching
      if (i === 1 && scale >= 0.98 && scale <= 1.02) break;
    }

    setLayout({ 
        lines: bestLines, 
        scale: Math.max(minScale, Math.min(maxScale, bestScale || 1)),
        finalPx: targetPx
    });
  }, [text, baseFontSize, minScale, maxScale, maxLines]);

  useLayoutEffect(() => {
    findBestLayout();
    const observer = new ResizeObserver((entries) => {
        // Only trigger if dimensions are valid
        if (entries[0].contentRect.width > 0) {
            requestAnimationFrame(findBestLayout);
        }
    });
    if (containerRef.current) observer.observe(containerRef.current);
    return () => observer.disconnect();
  }, [findBestLayout]);

  // Recalculate if fonts finish loading later
  useEffect(() => {
    if (!('fonts' in document)) return;
    const handleFontLoad = () => requestAnimationFrame(() => findBestLayout());
    document.fonts.addEventListener('loadingdone', handleFontLoad);
    return () => document.fonts.removeEventListener('loadingdone', handleFontLoad);
  }, [findBestLayout]);

  if (!text) return null;

  return (
    <div 
      ref={containerRef} 
      className={`w-full h-full flex justify-center items-center relative leading-none overflow-hidden ${className}`}
    >
      {/* Ghost measuring element */}
      <div
        ref={ghostRef}
        className={`absolute invisible pointer-events-none flex flex-col items-center text-center ${className}`}
        style={{ fontSize: `${layout.finalPx}px`, left: -9999, top: 0, whiteSpace: 'nowrap' }}
      />

      <div
        style={{ 
          transformOrigin: 'center center',
          transform: `scale(${layout.scale})`,
          fontSize: `${layout.finalPx}px`,
          width: 'max-content',
          minWidth: 'max-content'
        }}
        className="flex flex-col items-center justify-center leading-[0.9] text-center"
      >
        {layout.lines.map((line, idx) => (
            <div key={idx} className="whitespace-nowrap">
                {line}
            </div>
        ))}
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { ScreenKey } from '../../types';
import { useUser } from '../../contexts/UserContext';
import { SlantedButton } from '../ui/SlantedButton';
import { GameText } from '../ui/GameText';
import { audio } from '../../services/audio';
import { Portal } from '../ui/Portal';

interface HomeCommandBarProps {
    onNavigate: (s: ScreenKey) => void;
}

const getRelativeTimeString = (isoString: string) => {
    const date = new Date(isoString);
    const now = new Date();
    const diffInMs = now.getTime() - date.getTime();
    const diffInDays = Math.floor(diffInMs / (1000 * 60 * 60 * 24));
    if (diffInDays <= 0) return 'today';
    if (diffInDays === 1) return 'yesterday';
    if (diffInDays < 7) return `${diffInDays} days ago`;
    const diffInWeeks = Math.floor(diffInDays / 7);
    if (diffInWeeks === 1) return 'a week ago';
    if (diffInWeeks < 4) return `${diffInWeeks} weeks ago`;
    const diffInMonths = Math.floor(diffInDays / 30);
    if (diffInMonths === 1) return 'a month ago';
    if (diffInMonths < 12) return `${diffInMonths} months ago`;
    return 'a long time ago';
};

export const HomeCommandBar: React.FC<HomeCommandBarProps> = ({ onNavigate }) => {
    const { user, activeDeck, setActiveDeck } = useUser();
    const [isRollerOpen, setIsRollerOpen] = useState(false);

    const activeDeckId = user.activeDeckId;
    const activeDeckName = user.deckNames[activeDeckId] || 'UNTITLED';
    const isMainDeckValid = activeDeck.length === 12;

    const deckIds = Object.keys(user.decks).map(Number).sort((a, b) => a - b);
    const count = deckIds.length;
    const angleStep = 360 / count;
    const radius = 130;

    const drumRef = useRef<HTMLDivElement>(null);
    const itemsRef = useRef<(HTMLDivElement | null)[]>([]);
    const rotationRef = useRef((activeDeckId - 1) * angleStep);
    const velocityRef = useRef(0);
    const isDraggingRef = useRef(false);
    const lastPointerY = useRef(0);
    const lastTime = useRef(0);
    const requestRef = useRef<number | null>(null);

    const lastCenteredIndexRef = useRef<number>(activeDeckId - 1);
    const lastTickStepRef = useRef<number>(Math.round(rotationRef.current / angleStep));
    const lastAudioTimeRef = useRef<number>(0);
    const canPlayAudioRef = useRef<boolean>(true);

    const updateDom = useCallback((rot: number) => {
        if (!drumRef.current) return;

        drumRef.current.style.transform = `translate3d(0, 0, -${radius}px) rotateX(${rot}deg)`;

        let currentCenterI = -1;

        for (let i = 0; i < itemsRef.current.length; i++) {
            const item = itemsRef.current[i];
            if (!item) continue;

            const angle = -i * angleStep;
            let normalizedAngle = (angle + rot) % 360;
            if (normalizedAngle > 180) normalizedAngle -= 360;
            else if (normalizedAngle < -180) normalizedAngle += 360;

            const absAngle = Math.abs(normalizedAngle);

            if (absAngle < 110) {
                const distanceScale = 1 - (absAngle / 100) * 0.35;
                const opacity = 1 - (absAngle / 130);

                item.style.transform = `rotateX(${angle}deg) translate3d(0, 0, ${radius}px) scale(${distanceScale})`;
                item.style.opacity = Math.max(0.1, opacity).toString();
                item.style.visibility = 'visible';

                if (absAngle < (angleStep / 2)) currentCenterI = i;
            } else {
                if (item.style.visibility !== 'hidden') {
                    item.style.visibility = 'hidden';
                    item.style.opacity = '0';
                }
            }
        }

        if (currentCenterI !== -1 && currentCenterI !== lastCenteredIndexRef.current) {
            const prevItem = itemsRef.current[lastCenteredIndexRef.current];
            const nextItem = itemsRef.current[currentCenterI];
            if (prevItem) prevItem.classList.remove('is-visually-center');
            if (nextItem) nextItem.classList.add('is-visually-center');
            lastCenteredIndexRef.current = currentCenterI;
        }

        const currentStep = Math.round(rot / angleStep);
        if (currentStep !== lastTickStepRef.current) {
            const now = performance.now();
            const elapsed = now - lastAudioTimeRef.current;

            if (!isDraggingRef.current && elapsed > 1000) {
                canPlayAudioRef.current = false;
            }

            if (canPlayAudioRef.current && elapsed > 15) {
                audio.play('sfx_ui_click', 0.4);
                lastAudioTimeRef.current = now;
            }
            lastTickStepRef.current = currentStep;
        }
    }, [angleStep, radius]);

    const animate = useCallback(() => {
        if (isDraggingRef.current) return;

        velocityRef.current *= 0.96;
        rotationRef.current += velocityRef.current;

        if (Math.abs(velocityRef.current) < 0.4) {
            const targetIndex = Math.round(rotationRef.current / angleStep);
            const targetRotation = targetIndex * angleStep;
            const diff = targetRotation - rotationRef.current;

            rotationRef.current += diff * 0.5;

            if (Math.abs(diff) < 0.15) {
                rotationRef.current = targetRotation;
                velocityRef.current = 0;
                updateDom(rotationRef.current);

                const finalId = ((targetIndex % count + count) % count) + 1;
                if (finalId !== user.activeDeckId) setActiveDeck(finalId);
                return;
            }
        }
        updateDom(rotationRef.current);
        requestRef.current = requestAnimationFrame(animate);
    }, [angleStep, count, user.activeDeckId, setActiveDeck, updateDom]);

    const handlePointerDown = (e: React.PointerEvent) => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
        isDraggingRef.current = true;
        canPlayAudioRef.current = true;
        lastAudioTimeRef.current = performance.now();
        lastPointerY.current = e.clientY;
        lastTime.current = performance.now();
    };

    const handlePointerMove = (e: React.PointerEvent) => {
        if (!isDraggingRef.current) return;
        const now = performance.now();
        const deltaY = e.clientY - lastPointerY.current;
        const deltaTime = now - lastTime.current;
        const rotationDelta = -(deltaY / 100) * angleStep;
        rotationRef.current += rotationDelta;
        updateDom(rotationRef.current);
        if (deltaTime > 0) {
            const instantVelocity = rotationDelta / (deltaTime / 16.67);
            velocityRef.current = velocityRef.current * 0.25 + instantVelocity * 0.75;
        }
        lastPointerY.current = e.clientY;
        lastTime.current = now;
    };

    const handlePointerUp = () => {
        if (!isDraggingRef.current) return;
        isDraggingRef.current = false;
        requestRef.current = requestAnimationFrame(animate);
    };

    useEffect(() => {
        if (isRollerOpen) {
            const t = setTimeout(() => updateDom(rotationRef.current), 50);
            return () => clearTimeout(t);
        }
    }, [isRollerOpen, updateDom]);

    return (
        <div className="w-full flex items-end justify-center px-2 pb-3 gap-2 pointer-events-none relative h-16 overflow-visible">
            {isRollerOpen && (
                <Portal>
                    <div 
                        className="fixed inset-0 z-[600] pointer-events-auto bg-black/40 backdrop-blur-md flex flex-col items-center justify-center" 
                        onClick={() => setIsRollerOpen(false)}
                        onPointerDown={handlePointerDown}
                        onPointerMove={handlePointerMove}
                        onPointerUp={handlePointerUp}
                        onPointerLeave={handlePointerUp}
                    >
                        <div className="w-full h-[32rem] perspective-[1500px] flex items-center justify-center select-none touch-none animate-pop overflow-visible">
                            <div 
                                ref={drumRef}
                                className="relative w-64 h-24 transform-style-3d pointer-events-none will-change-transform"
                                style={{ transform: `translate3d(0, 0, -${radius}px) rotateX(${rotationRef.current}deg)` }}
                            >
                                {deckIds.map((id, i) => {
                                    const stats = user.deckStats[id];
                                    const dateStr = stats ? getRelativeTimeString(stats.lastModified) : 'some time ago';
                                    const isInitialCenter = user.activeDeckId === id;
                                    const isValid = (user.decks[id]?.length || 0) === 12;
                                    const statsText = `cq: ${stats?.conquestWins || 0}/${stats?.conquestTotal || 0} (${stats?.conquestWinRate || 0}%) - ld ${stats?.ladderWins || 0}/${stats?.ladderLosses || 0} (${stats?.ladderWinRate || 0}%)`;

                                    return (
                                        <div 
                                            key={id}
                                            ref={el => itemsRef.current[i] = el}
                                            className={`absolute inset-0 backface-hidden transform-style-3d will-change-transform ${isInitialCenter ? 'is-visually-center' : ''} ${isValid ? 'deck-valid' : 'deck-invalid'}`}
                                            style={{ 
                                                transform: `rotateX(${-i * angleStep}deg) translate3d(0, 0, ${radius}px)`,
                                                opacity: isInitialCenter ? 1 : 0.4,
                                                zIndex: i === lastCenteredIndexRef.current ? 50 : 10
                                            }}
                                        >
                                            <SlantedButton variant="secondary" fullWidth size="lg" className="!h-full shadow-2xl drum-item-button">
                                                <div className="flex flex-col items-center justify-center w-full h-full pointer-events-none px-4">
                                                    <div className="w-full h-8"><GameText text={user.deckNames[id] || 'UNTITLED'} baseFontSize={1.4} className="text-white font-black italic tracking-tighter uppercase" maxLines={1} /></div>
                                                    <div className="w-full h-4 flex items-center justify-center opacity-90">
                                                        <GameText text={statsText} baseFontSize={0.7} maxLines={1} className="text-white font-bold font-black italic tracking-tighter uppercase" />
                                                    </div>
                                                    <div className="w-full h-3 mt-1 opacity-50"><GameText text={`Changed ${dateStr}`} baseFontSize={0.65} className="lowercase italic font-black tracking-tighter" /></div>
                                                </div>
                                            </SlantedButton>
                                        </div>
                                    );
                                })}
                            </div>
                        </div>
                    </div>
                </Portal>
            )}

            <div className="w-[11.5%] pointer-events-auto">
                <SlantedButton variant="blue" size="md" onClick={() => onNavigate('HISTORY')} className="w-full !h-10 shadow-blue-900/40" icon={
                    <div className="flex items-center justify-center scale-75 drop-shadow-[0_2px_3px_rgba(0,0,0,0.8)] translate-x-[0.05rem]">
                        <svg className="w-6 h-6 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
                        </svg>
                    </div>
                } />
            </div>

            <div className="w-[20.5%] pointer-events-auto">
                <SlantedButton variant="blue" fullWidth size="lg" onClick={() => onNavigate('GAME')} className="!h-13 shadow-blue-900/50">
                    <div className="flex flex-col items-center justify-center w-full h-full text-center px-0.5 pt-1">
                        <div className="w-full h-3 opacity-60"><GameText text="PLAY" baseFontSize={0.75} className="font-black italic tracking-tighter uppercase" /></div>
                        <div className="w-full h-8"><GameText text="CONQUEST" baseFontSize={1.3} maxLines={1} className="italic tracking-tighter font-black uppercase" /></div>
                    </div>
                </SlantedButton>
            </div>

            <div className="w-[20.5%] pointer-events-auto">
                <SlantedButton 
                    variant={isMainDeckValid ? 'success' : 'danger'} 
                    fullWidth
                    size="lg"
                    onClick={() => { setIsRollerOpen(!isRollerOpen); audio.playUiClick(); }}
                    className={`!h-13 shadow-slate-900/40 relative z-[70] transition-transform ${isRollerOpen ? 'scale-105' : ''}`}
                >
                    <div className="flex flex-col items-center justify-center w-full h-full text-center px-0.5 pt-1">
                        <div className="flex items-center justify-center gap-1 w-full h-3 opacity-60">
                            <div className="w-max h-full"><GameText text="DECK" baseFontSize={0.75} className="font-black italic tracking-tighter uppercase" /></div>
                            {!isMainDeckValid && <div className="w-1.5 h-1.5 rounded-full bg-amber-500 animate-pulse" />}
                        </div>
                        <div className="w-full h-8"><GameText text={activeDeckName} baseFontSize={1.15} maxLines={2} className="italic tracking-tighter leading-none font-black uppercase" /></div>
                    </div>
                </SlantedButton>
            </div>

            <div className="w-[20.5%] pointer-events-auto">
                <SlantedButton variant="blue" fullWidth size="lg" onClick={() => onNavigate('GAME')} className="!h-13 shadow-blue-900/50">
                    <div className="flex flex-col items-center justify-center w-full h-full text-center px-0.5 pt-1">
                        <div className="w-full h-3 opacity-60"><GameText text="PLAY" baseFontSize={0.75} className="font-black italic tracking-tighter uppercase" /></div>
                        <div className="w-full h-8"><GameText text="LADDER" baseFontSize={1.3} maxLines={1} className="italic tracking-tighter font-black uppercase" /></div>
                    </div>
                </SlantedButton>
            </div>

            <div className="w-[11.5%] pointer-events-auto">
                <SlantedButton variant="blue" size="md" onClick={() => onNavigate('RANK')} className="w-full !h-10 shadow-blue-900/40">
                    <div className="flex flex-col items-center justify-center w-full h-full text-center px-0.5 pt-1">
                        <div className="w-full h-3 opacity-60"><GameText text="RANK" baseFontSize={0.75} className="font-black italic tracking-tighter uppercase text-white" /></div>
                        <div className="w-full h-6"><GameText text={user.rank.toString()} baseFontSize={1.4} className="text-white font-black italic tracking-tighter" /></div>
                    </div>
                </SlantedButton>
            </div>

            <style>{`
                .transform-style-3d { transform-style: preserve-3d; }
                .backface-hidden { backface-visibility: hidden; }
                .is-visually-center.deck-valid .drum-item-button > div:first-child { background: linear-gradient(to bottom, #059669, #064e3b) !important; border-color: #34d399 !important; box-shadow: 0 0.2rem 0 #064e3b, 0 0 20px rgba(16, 185, 129, 0.3) !important; }
                .is-visually-center.deck-invalid .drum-item-button > div:first-child { background: linear-gradient(to bottom, #dc2626, #7f1d1d) !important; border-color: #f87171 !important; box-shadow: 0 0.2rem 0 #7f1d1d, 0 0 20px rgba(239, 68, 68, 0.3) !important; }
                .is-visually-center { filter: grayscale(0) !important; }
            `}</style>
        </div>
    );
};

import React, { useState, useLayoutEffect, useRef, useEffect, useCallback } from 'react';

interface GameTextProps {
  text: string;
  className?: string;
  /** 
   * RELATIVE SCALE BASIS
   * Interpreted as 'em' relative to container font-size.
   */
  baseFontSize: number;
  /** How much we allow the text to shrink. Default 0.2 */
  minScale?: number;
  /** How much we allow the text to grow beyond its base size. Default 1.0 */
  maxScale?: number;
  /** Max lines for wrapping. Default 1 */
  maxLines?: number;
}

/**
 * GAMETEXT ENGINE
 * A high-performance typographic scaler that prevents text overflow 
 * and provides intelligent multi-line wrapping for UI labels.
 */
export const GameText: React.FC<GameTextProps> = ({ 
  text, 
  className = '', 
  baseFontSize, 
  minScale = 0.2,
  maxScale = 1.0,
  maxLines = 1
}) => {
  const [layout, setLayout] = useState<{ lines: string[], scale: number, finalPx: number }>({ 
      lines: [text || ''], 
      scale: 1,
      finalPx: 16
  });
  const containerRef = useRef<HTMLDivElement>(null);
  const ghostRef = useRef<HTMLDivElement>(null);

  const calculateLayout = useCallback(() => {
    const container = containerRef.current;
    const ghost = ghostRef.current;
    if (!container || !ghost || !text) return;

    const cw = container.clientWidth;
    const ch = container.clientHeight;

    // If container isn't ready, we render at scale 1.0 and wait for ResizeObserver
    if (cw <= 0 || ch <= 0) return;

    const parentStyle = window.getComputedStyle(container);
    const parentPx = parseFloat(parentStyle.fontSize) || 16;
    const targetPx = parentPx * baseFontSize;

    const words = text.split(/\s+/);

    const splitIntoLines = (num: number): string[] => {
      if (num <= 1 || words.length <= 1) return [text];
      const targetLen = text.length / num;
      const res: string[][] = Array.from({ length: num }, () => []);
      let curLine = 0;
      let curChars = 0;

      words.forEach((word) => {
        if (curLine < num - 1) {
            const dStay = Math.abs((curChars + word.length) - targetLen);
            const dMove = Math.abs(curChars - targetLen);
            if (curChars > 0 && dMove < dStay) {
                curLine++;
                curChars = 0;
            }
        }
        res[curLine].push(word);
        curChars += word.length + 1;
      });
      return res.map(l => l.join(' ')).filter(s => s.length > 0);
    };

    const measure = (lines: string[]) => {
      // Use visibility:hidden instead of absolute hidden to ensure metrics are calculated
      ghost.innerHTML = lines.map(l => `<div>${l}</div>`).join('');
      ghost.style.fontSize = `${targetPx}px`;

      const gw = ghost.scrollWidth;
      const gh = ghost.scrollHeight;

      if (gw <= 0 || gh <= 0) return 1;
      return Math.min((cw / gw) * 0.98, (ch / gh) * 0.98);
    };

    let bestS = 0;
    let bestL: string[] = [text];
    const limit = Math.min(maxLines, words.length, 4);

    for (let i = 1; i <= limit; i++) {
      const candidateL = splitIntoLines(i);
      const s = measure(candidateL);

      // Heuristic: Prefer fewer lines if scale is similar
      const bias = (limit - i) * 0.01;
      if (s + bias > bestS) {
        bestS = s;
        bestL = candidateL;
      }
      if (i === 1 && s >= 0.98) break; 
    }

    setLayout({ 
        lines: bestL, 
        scale: Math.max(minScale, Math.min(maxScale, bestS || 1)),
        finalPx: targetPx
    });
  }, [text, baseFontSize, minScale, maxScale, maxLines]);

  useLayoutEffect(() => {
    calculateLayout();
    const observer = new ResizeObserver(() => {
        requestAnimationFrame(calculateLayout);
    });
    if (containerRef.current) observer.observe(containerRef.current);
    return () => observer.disconnect();
  }, [calculateLayout]);

  // Robust check for font loading
  useEffect(() => {
    if (!('fonts' in document)) return;
    const update = () => requestAnimationFrame(calculateLayout);
    document.fonts.addEventListener('loadingdone', update);
    return () => document.fonts.removeEventListener('loadingdone', update);
  }, [calculateLayout]);

  if (!text) return null;

  return (
    <div 
      ref={containerRef} 
      className={`w-full h-full flex justify-center items-center relative leading-none overflow-hidden ${className}`}
    >
      {/* Ghost measuring element - strictly positioned off-screen but visible to the engine */}
      <div
        ref={ghostRef}
        className={`absolute pointer-events-none flex flex-col items-center text-center opacity-0`}
        style={{ 
            fontSize: `${layout.finalPx}px`, 
            left: '-1000vw', 
            top: 0, 
            whiteSpace: 'nowrap',
            visibility: 'visible' 
        }}
      />

      <div
        style={{ 
          transformOrigin: 'center center',
          transform: `scale(${layout.scale})`,
          fontSize: `${layout.finalPx}px`,
          width: 'max-content',
          minWidth: 'max-content'
        }}
        className="flex flex-col items-center justify-center leading-[1.0] text-center"
      >
        {layout.lines.map((line, idx) => (
            <div key={idx} className="whitespace-nowrap">
                {line}
            </div>
        ))}
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { ScreenKey } from '../../types';
import { useUser } from '../../contexts/UserContext';
import { SlantedButton } from '../ui/SlantedButton';
import { GameText } from '../ui/GameText';
import { audio } from '../../services/audio';
import { Portal } from '../ui/Portal';

interface HomeCommandBarProps {
    onNavigate: (s: ScreenKey) => void;
}

const getRelativeTimeString = (isoString: string) => {
    const date = new Date(isoString);
    const now = new Date();
    const diffInMs = now.getTime() - date.getTime();
    const diffInDays = Math.floor(diffInMs / (1000 * 60 * 60 * 24));
    if (diffInDays <= 0) return 'today';
    if (diffInDays === 1) return 'yesterday';
    if (diffInDays < 7) return `${diffInDays} days ago`;
    const diffInWeeks = Math.floor(diffInDays / 7);
    if (diffInWeeks === 1) return 'a week ago';
    if (diffInWeeks < 4) return `${diffInWeeks} weeks ago`;
    const diffInMonths = Math.floor(diffInDays / 30);
    if (diffInMonths === 1) return 'a month ago';
    if (diffInMonths < 12) return `${diffInMonths} months ago`;
    return 'a long time ago';
};

export const HomeCommandBar: React.FC<HomeCommandBarProps> = ({ onNavigate }) => {
    const { user, activeDeck, setActiveDeck } = useUser();
    const [isRollerOpen, setIsRollerOpen] = useState(false);

    const activeDeckId = user.activeDeckId;
    const activeDeckName = user.deckNames[activeDeckId] || 'UNTITLED';
    const isMainDeckValid = activeDeck.length === 12;

    const deckIds = Object.keys(user.decks).map(Number).sort((a, b) => a - b);
    const count = deckIds.length;
    const angleStep = 360 / count;
    const radius = 130;

    const drumRef = useRef<HTMLDivElement>(null);
    const itemsRef = useRef<(HTMLDivElement | null)[]>([]);
    const rotationRef = useRef((activeDeckId - 1) * angleStep);
    const velocityRef = useRef(0);
    const isDraggingRef = useRef(false);
    const lastPointerY = useRef(0);
    const lastTime = useRef(0);
    const requestRef = useRef<number | null>(null);

    const lastCenteredIndexRef = useRef<number>(activeDeckId - 1);
    const lastTickStepRef = useRef<number>(Math.round(rotationRef.current / angleStep));
    const lastAudioTimeRef = useRef<number>(0);
    const canPlayAudioRef = useRef<boolean>(true);

    const updateDom = useCallback((rot: number) => {
        if (!drumRef.current) return;

        drumRef.current.style.transform = `translate3d(0, 0, -${radius}px) rotateX(${rot}deg)`;

        let currentCenterI = -1;

        for (let i = 0; i < itemsRef.current.length; i++) {
            const item = itemsRef.current[i];
            if (!item) continue;

            const angle = -i * angleStep;
            let normalizedAngle = (angle + rot) % 360;
            if (normalizedAngle > 180) normalizedAngle -= 360;
            else if (normalizedAngle < -180) normalizedAngle += 360;

            const absAngle = Math.abs(normalizedAngle);

            if (absAngle < 110) {
                const distanceScale = 1 - (absAngle / 100) * 0.35;
                const opacity = 1 - (absAngle / 130);

                item.style.transform = `rotateX(${angle}deg) translate3d(0, 0, ${radius}px) scale(${distanceScale})`;
                item.style.opacity = Math.max(0.1, opacity).toString();
                item.style.visibility = 'visible';

                if (absAngle < (angleStep / 2)) currentCenterI = i;
            } else {
                if (item.style.visibility !== 'hidden') {
                    item.style.visibility = 'hidden';
                    item.style.opacity = '0';
                }
            }
        }

        if (currentCenterI !== -1 && currentCenterI !== lastCenteredIndexRef.current) {
            const prevItem = itemsRef.current[lastCenteredIndexRef.current];
            const nextItem = itemsRef.current[currentCenterI];
            if (prevItem) prevItem.classList.remove('is-visually-center');
            if (nextItem) nextItem.classList.add('is-visually-center');
            lastCenteredIndexRef.current = currentCenterI;
        }

        const currentStep = Math.round(rot / angleStep);
        if (currentStep !== lastTickStepRef.current) {
            const now = performance.now();
            const elapsed = now - lastAudioTimeRef.current;

            if (!isDraggingRef.current && elapsed > 1000) {
                canPlayAudioRef.current = false;
            }

            if (canPlayAudioRef.current && elapsed > 15) {
                audio.play('sfx_ui_click', 0.4);
                lastAudioTimeRef.current = now;
            }
            lastTickStepRef.current = currentStep;
        }
    }, [angleStep, radius]);

    const animate = useCallback(() => {
        if (isDraggingRef.current) return;

        velocityRef.current *= 0.96;
        rotationRef.current += velocityRef.current;

        if (Math.abs(velocityRef.current) < 0.4) {
            const targetIndex = Math.round(rotationRef.current / angleStep);
            const targetRotation = targetIndex * angleStep;
            const diff = targetRotation - rotationRef.current;

            rotationRef.current += diff * 0.5;

            if (Math.abs(diff) < 0.15) {
                rotationRef.current = targetRotation;
                velocityRef.current = 0;
                updateDom(rotationRef.current);

                const finalId = ((targetIndex % count + count) % count) + 1;
                if (finalId !== user.activeDeckId) setActiveDeck(finalId);
                return;
            }
        }
        updateDom(rotationRef.current);
        requestRef.current = requestAnimationFrame(animate);
    }, [angleStep, count, user.activeDeckId, setActiveDeck, updateDom]);

    const handlePointerDown = (e: React.PointerEvent) => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
        isDraggingRef.current = true;
        canPlayAudioRef.current = true;
        lastAudioTimeRef.current = performance.now();
        lastPointerY.current = e.clientY;
        lastTime.current = performance.now();
    };

    const handlePointerMove = (e: React.PointerEvent) => {
        if (!isDraggingRef.current) return;
        const now = performance.now();
        const deltaY = e.clientY - lastPointerY.current;
        const deltaTime = now - lastTime.current;
        const rotationDelta = -(deltaY / 100) * angleStep;
        rotationRef.current += rotationDelta;
        updateDom(rotationRef.current);
        if (deltaTime > 0) {
            const instantVelocity = rotationDelta / (deltaTime / 16.67);
            velocityRef.current = velocityRef.current * 0.25 + instantVelocity * 0.75;
        }
        lastPointerY.current = e.clientY;
        lastTime.current = now;
    };

    const handlePointerUp = () => {
        if (!isDraggingRef.current) return;
        isDraggingRef.current = false;
        requestRef.current = requestAnimationFrame(animate);
    };

    useEffect(() => {
        if (isRollerOpen) {
            const t = setTimeout(() => updateDom(rotationRef.current), 50);
            return () => clearTimeout(t);
        }
    }, [isRollerOpen, updateDom]);

    return (
        <div className="w-full flex items-end justify-center px-2 pb-3 gap-2 pointer-events-none relative h-16 overflow-visible">
            {isRollerOpen && (
                <Portal>
                    <div 
                        className="fixed inset-0 z-[600] pointer-events-auto bg-black/40 backdrop-blur-md flex flex-col items-center justify-center" 
                        onClick={() => setIsRollerOpen(false)}
                        onPointerDown={handlePointerDown}
                        onPointerMove={handlePointerMove}
                        onPointerUp={handlePointerUp}
                        onPointerLeave={handlePointerUp}
                    >
                        <div className="w-full h-[32rem] perspective-[1500px] flex items-center justify-center select-none touch-none animate-pop overflow-visible">
                            <div 
                                ref={drumRef}
                                className="relative w-64 h-24 transform-style-3d pointer-events-none will-change-transform"
                                style={{ transform: `translate3d(0, 0, -${radius}px) rotateX(${rotationRef.current}deg)` }}
                            >
                                {deckIds.map((id, i) => {
                                    const stats = user.deckStats[id];
                                    const dateStr = stats ? getRelativeTimeString(stats.lastModified) : 'some time ago';
                                    const isInitialCenter = user.activeDeckId === id;
                                    const isValid = (user.decks[id]?.length || 0) === 12;
                                    const statsText = `cq: ${stats?.conquestWins || 0}/${stats?.conquestTotal || 0} (${stats?.conquestWinRate || 0}%) - ld ${stats?.ladderWins || 0}/${stats?.ladderLosses || 0} (${stats?.ladderWinRate || 0}%)`;

                                    return (
                                        <div 
                                            key={id}
                                            ref={el => itemsRef.current[i] = el}
                                            className={`absolute inset-0 backface-hidden transform-style-3d will-change-transform ${isInitialCenter ? 'is-visually-center' : ''} ${isValid ? 'deck-valid' : 'deck-invalid'}`}
                                            style={{ 
                                                transform: `rotateX(${-i * angleStep}deg) translate3d(0, 0, ${radius}px)`,
                                                opacity: isInitialCenter ? 1 : 0.4,
                                                zIndex: i === lastCenteredIndexRef.current ? 50 : 10
                                            }}
                                        >
                                            <SlantedButton variant="secondary" fullWidth size="lg" className="!h-full shadow-2xl drum-item-button">
                                                <div className="flex flex-col items-center justify-center w-full h-full pointer-events-none px-4">
                                                    <div className="w-full h-8"><GameText text={user.deckNames[id] || 'UNTITLED'} baseFontSize={1.4} className="text-white font-black italic tracking-tighter uppercase" maxLines={1} /></div>
                                                    <div className="w-full h-4 flex items-center justify-center opacity-90">
                                                        <GameText text={statsText} baseFontSize={0.7} maxLines={1} className="text-white font-bold font-black italic tracking-tighter uppercase" />
                                                    </div>
                                                    <div className="w-full h-3 mt-1 opacity-50"><GameText text={`Changed ${dateStr}`} baseFontSize={0.65} className="lowercase italic font-black tracking-tighter" /></div>
                                                </div>
                                            </SlantedButton>
                                        </div>
                                    );
                                })}
                            </div>
                        </div>
                    </div>
                </Portal>
            )}

            <div className="w-[11.5%] pointer-events-auto">
                <SlantedButton variant="blue" size="md" onClick={() => onNavigate('HISTORY')} className="w-full !h-10 shadow-blue-900/40" icon={
                    <div className="flex items-center justify-center scale-75 drop-shadow-[0_2px_3px_rgba(0,0,0,0.8)] translate-x-[0.05rem]">
                        <svg className="w-6 h-6 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
                        </svg>
                    </div>
                } />
            </div>

            <div className="w-[20.5%] pointer-events-auto">
                <SlantedButton variant="blue" fullWidth size="lg" onClick={() => onNavigate('GAME')} className="!h-13 shadow-blue-900/50">
                    <div className="flex flex-col items-center justify-center w-full h-full text-center px-0.5 pt-1">
                        <div className="w-full h-4 opacity-60"><GameText text="PLAY" baseFontSize={0.75} className="font-black italic tracking-tighter uppercase" /></div>
                        <div className="w-full h-8"><GameText text="CONQUEST" baseFontSize={1.3} maxLines={1} className="italic tracking-tighter font-black uppercase" /></div>
                    </div>
                </SlantedButton>
            </div>

            <div className="w-[20.5%] pointer-events-auto">
                <SlantedButton 
                    variant={isMainDeckValid ? 'success' : 'danger'} 
                    fullWidth
                    size="lg"
                    onClick={() => { setIsRollerOpen(!isRollerOpen); audio.playUiClick(); }}
                    className={`!h-13 shadow-slate-900/40 relative z-[70] transition-transform ${isRollerOpen ? 'scale-105' : ''}`}
                >
                    <div className="flex flex-col items-center justify-center w-full h-full text-center px-0.5 pt-1">
                        <div className="flex items-center justify-center gap-1 w-full h-4 opacity-60">
                            <div className="w-max h-full"><GameText text="DECK" baseFontSize={0.75} className="font-black italic tracking-tighter uppercase" /></div>
                            {!isMainDeckValid && <div className="w-1.5 h-1.5 rounded-full bg-amber-500 animate-pulse" />}
                        </div>
                        <div className="w-full h-8"><GameText text={activeDeckName} baseFontSize={1.15} maxLines={2} className="italic tracking-tighter leading-none font-black uppercase" /></div>
                    </div>
                </SlantedButton>
            </div>

            <div className="w-[20.5%] pointer-events-auto">
                <SlantedButton variant="blue" fullWidth size="lg" onClick={() => onNavigate('GAME')} className="!h-13 shadow-blue-900/50">
                    <div className="flex flex-col items-center justify-center w-full h-full text-center px-0.5 pt-1">
                        <div className="w-full h-4 opacity-60"><GameText text="PLAY" baseFontSize={0.75} className="font-black italic tracking-tighter uppercase" /></div>
                        <div className="w-full h-8"><GameText text="LADDER" baseFontSize={1.3} maxLines={1} className="italic tracking-tighter font-black uppercase" /></div>
                    </div>
                </SlantedButton>
            </div>

            <div className="w-[11.5%] pointer-events-auto">
                <SlantedButton variant="blue" size="md" onClick={() => onNavigate('RANK')} className="w-full !h-10 shadow-blue-900/40">
                    <div className="flex flex-col items-center justify-center w-full h-full text-center px-0.5 pt-1">
                        <div className="w-full h-4 opacity-60"><GameText text="RANK" baseFontSize={0.7} className="font-black italic tracking-tighter uppercase text-white" /></div>
                        <div className="w-full h-6"><GameText text={user.rank.toString()} baseFontSize={1.4} className="text-white font-black italic tracking-tighter" /></div>
                    </div>
                </SlantedButton>
            </div>

            <style>{`
                .transform-style-3d { transform-style: preserve-3d; }
                .backface-hidden { backface-visibility: hidden; }
                .is-visually-center.deck-valid .drum-item-button > div:first-child { background: linear-gradient(to bottom, #059669, #064e3b) !important; border-color: #34d399 !important; box-shadow: 0 0.2rem 0 #064e3b, 0 0 20px rgba(16, 185, 129, 0.3) !important; }
                .is-visually-center.deck-invalid .drum-item-button > div:first-child { background: linear-gradient(to bottom, #dc2626, #7f1d1d) !important; border-color: #f87171 !important; box-shadow: 0 0.2rem 0 #7f1d1d, 0 0 20px rgba(239, 68, 68, 0.3) !important; }
                .is-visually-center { filter: grayscale(0) !important; }
            `}</style>
        </div>
    );
};

import React, { useState, useRef, useEffect } from 'react';
import { GameText } from './GameText';

type ButtonVariant = 'primary' | 'secondary' | 'success' | 'danger' | 'warning' | 'blue';

interface SlantedButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
    variant?: ButtonVariant;
    fullWidth?: boolean;
    size?: 'sm' | 'md' | 'lg';
    icon?: React.ReactNode;
    holdDuration?: number; 
    onHoldChange?: (isHolding: boolean) => void;
    onProgressChange?: (progress: number) => void;
}

export const SlantedButton: React.FC<SlantedButtonProps> = ({ 
    children, 
    variant = 'primary', 
    fullWidth = false,
    size = 'md',
    icon,
    className = '',
    holdDuration = 0,
    onHoldChange,
    onProgressChange,
    onClick,
    ...props 
}) => {
    const [progress, setProgress] = useState(0);
    const [isHolding, setIsHolding] = useState(false);
    const timerRef = useRef<number | null>(null);
    const startTimeRef = useRef<number>(0);

    const variants = {
        primary: "from-purple-600 to-purple-900 border-purple-400 shadow-[0_0.2rem_0_rgb(88,28,135)]",
        secondary: "from-slate-700 to-slate-900 border-slate-500 shadow-[0_0.2rem_0_rgb(15,23,42)]",
        success: "from-emerald-600 to-emerald-900 border-emerald-400 shadow-[0_0.2rem_0_rgb(6,78,59)]",
        danger: "from-red-600 to-red-900 border-red-400 shadow-[0_0.2rem_0_rgb(127,29,29)]",
        warning: "from-amber-600 to-amber-900 border-amber-400 shadow-[0_0.2rem_0_rgb(120,53,15)]",
        blue: "from-blue-600 to-blue-900 border-blue-400 shadow-[0_0.2rem_0_rgb(30,58,138)]",
    };

    const sizeConfigs = {
        sm: { height: "h-7", fontSize: 1.15, padding: "px-2" },
        md: { height: "h-10", fontSize: 1.25, padding: "px-4" },
        lg: { height: "h-14", fontSize: 1.35, padding: "px-6" }
    };

    const config = sizeConfigs[size];

    const startHold = (e: React.PointerEvent) => {
        if (!holdDuration || props.disabled) return;

        setIsHolding(true);
        onHoldChange?.(true);
        startTimeRef.current = Date.now();

        timerRef.current = window.setInterval(() => {
            const elapsed = Date.now() - startTimeRef.current;
            const p = Math.min((elapsed / holdDuration) * 100, 100);
            setProgress(p);
            onProgressChange?.(p);

            if (p >= 100) {
                if (timerRef.current) clearInterval(timerRef.current);
                timerRef.current = null;

                setProgress(100);
                onProgressChange?.(100);

                setTimeout(() => {
                    if (onClick) {
                        const syntheticEvent = { 
                            clientX: e.clientX,
                            clientY: e.clientY,
                            target: e.target,
                            currentTarget: e.currentTarget,
                            type: 'click',
                            bubbles: true,
                            cancelable: true,
                            nativeEvent: e.nativeEvent,
                        } as unknown as React.MouseEvent<HTMLButtonElement>;
                        onClick(syntheticEvent);
                    }
                    setIsHolding(false);
                    onHoldChange?.(false);
                    setProgress(0);
                    onProgressChange?.(0);
                }, 60);
            }
        }, 16);
    };

    const cancelHold = () => {
        if (timerRef.current) {
            clearInterval(timerRef.current);
            timerRef.current = null;
        }
        setIsHolding(false);
        onHoldChange?.(false);
        setProgress(0);
        onProgressChange?.(0);
    };

    useEffect(() => {
        return () => {
            if (timerRef.current) clearInterval(timerRef.current);
        };
    }, []);

    const widthOverride = className.match(/w-\[?[\w.%]+\]?/)?.[0] || '';
    const widthClass = fullWidth ? 'w-full' : (widthOverride ? widthOverride : 'w-max');
    const textShadowClass = "drop-shadow-[0_2px_3px_rgba(0,0,0,0.8)]";

    return (
        <div className={`relative group ${widthClass} ${config.height} ${props.disabled ? 'opacity-50 pointer-events-none' : ''}`}>
            <button 
                className={`w-full h-full relative z-10 active:translate-y-0.5 transition-all outline-none ${className}`}
                onPointerDown={holdDuration ? startHold : undefined}
                onPointerUp={holdDuration ? cancelHold : undefined}
                onPointerLeave={holdDuration ? cancelHold : undefined}
                onClick={holdDuration ? undefined : onClick}
                role="button"
                aria-busy={isHolding}
                {...props}
            >
                {/* Slanted Background Plate */}
                <div className={`
                    absolute inset-0 bg-gradient-to-b border rounded skew-x-[-10deg] 
                    [@media(hover:hover)]:group-hover:brightness-110 transition-all duration-200 overflow-hidden
                    ${variants[variant]}
                `}>
                    {holdDuration > 0 && (
                        <div 
                            className="absolute inset-y-0 left-0 bg-white/20 transition-all duration-75 ease-linear pointer-events-none"
                            style={{ width: `${progress}%` }}
                        />
                    )}
                </div>

                {/* Content Container - NOT skewed, to keep text and icons upright and centerable */}
                <div className={`relative z-20 h-full pointer-events-none flex items-center justify-center ${config.padding}`}>
                    <div className={`flex items-center justify-center w-full h-full transition-opacity ${isHolding ? 'opacity-40' : 'opacity-100'}`}>
                        {icon && (
                            <div className={`shrink-0 flex items-center justify-center ${children ? 'mr-1.5' : ''}`}>
                                {icon}
                            </div>
                        )}

                        {children && (
                            typeof children === 'string' || typeof children === 'number' ? (
                                <div className="flex-1 h-full min-w-0">
                                    <GameText 
                                        text={children.toString()} 
                                        baseFontSize={config.fontSize} 
                                        maxScale={1.0}
                                        className={`text-white font-black tracking-tighter italic uppercase ${textShadowClass}`}
                                        minScale={0.3} 
                                    />
                                </div>
                            ) : (
                                <div className={`h-full w-full flex items-center justify-center ${textShadowClass}`} style={{ fontSize: `${config.fontSize}em` }}>
                                    {children}
                                </div>
                            )
                        )}
                    </div>
                </div>
            </button>
        </div>
    );
};

import React, { useState, useLayoutEffect, useRef, useEffect, useCallback } from 'react';

interface GameTextProps {
  text: string;
  className?: string;
  /** 
   * RELATIVE SCALE BASIS
   * Interpreted as 'em' relative to container font-size.
   */
  baseFontSize: number;
  /** How much we allow the text to shrink. Default 0.2 */
  minScale?: number;
  /** How much we allow the text to grow beyond its base size. Default 1.0 */
  maxScale?: number;
  /** Max lines for wrapping. Default 1 */
  maxLines?: number;
}

/**
 * GAMETEXT ENGINE
 * A high-performance typographic scaler that prevents text overflow 
 * and provides intelligent multi-line wrapping for UI labels.
 */
export const GameText: React.FC<GameTextProps> = ({ 
  text, 
  className = '', 
  baseFontSize, 
  minScale = 0.2,
  maxScale = 1.0,
  maxLines = 1
}) => {
  const [layout, setLayout] = useState<{ lines: string[], scale: number, finalPx: number }>({ 
      lines: [text || ''], 
      scale: 1,
      finalPx: 16
  });
  const containerRef = useRef<HTMLDivElement>(null);
  const ghostRef = useRef<HTMLDivElement>(null);

  const calculateLayout = useCallback(() => {
    const container = containerRef.current;
    const ghost = ghostRef.current;
    if (!container || !ghost || !text) return;

    // Use getBoundingClientRect for more sub-pixel accuracy in responsive layouts
    const containerRect = container.getBoundingClientRect();
    const cw = containerRect.width;
    const ch = containerRect.height;

    // If container isn't ready or visible yet, don't crash
    if (cw <= 0 || ch <= 0) return;

    const parentStyle = window.getComputedStyle(container);
    const parentPx = parseFloat(parentStyle.fontSize) || 16;
    const targetPx = parentPx * baseFontSize;

    const words = text.split(/\s+/);

    const splitIntoLines = (num: number): string[] => {
      if (num <= 1 || words.length <= 1) return [text];
      const targetLen = text.length / num;
      const res: string[][] = Array.from({ length: num }, () => []);
      let curLine = 0;
      let curChars = 0;

      words.forEach((word) => {
        if (curLine < num - 1) {
            const dStay = Math.abs((curChars + word.length) - targetLen);
            const dMove = Math.abs(curChars - targetLen);
            if (curChars > 0 && dMove < dStay) {
                curLine++;
                curChars = 0;
            }
        }
        res[curLine].push(word);
        curChars += word.length + 1;
      });
      return res.map(l => l.join(' ')).filter(s => s.length > 0);
    };

    const measure = (lines: string[]) => {
      ghost.innerHTML = lines.map(l => `<div>${l}</div>`).join('');
      ghost.style.fontSize = `${targetPx}px`;

      // Use offsetWidth/Height to get the real pixel space occupied
      const gw = ghost.offsetWidth;
      const gh = ghost.offsetHeight;

      if (gw <= 0 || gh <= 0) return 1;

      // Calculate ratios with a small buffer for rounding errors
      const widthRatio = (cw / gw) * 0.98;
      const heightRatio = (ch / gh) * 0.98;

      return Math.min(widthRatio, heightRatio);
    };

    let bestS = 0;
    let bestL: string[] = [text];
    const limit = Math.min(maxLines, words.length, 4);

    for (let i = 1; i <= limit; i++) {
      const candidateL = splitIntoLines(i);
      const s = measure(candidateL);

      // Heuristic: Prefer fewer lines if scale is similar
      const bias = (limit - i) * 0.02;
      if (s + bias > bestS) {
        bestS = s;
        bestL = candidateL;
      }

      // If single line fits well, stop there
      if (i === 1 && s >= 0.95) break; 
    }

    setLayout({ 
        lines: bestL, 
        scale: Math.max(minScale, Math.min(maxScale, bestS || 1)),
        finalPx: targetPx
    });
  }, [text, baseFontSize, minScale, maxScale, maxLines]);

  useLayoutEffect(() => {
    calculateLayout();
    const observer = new ResizeObserver((entries) => {
        if (entries[0].contentRect.width > 0) {
            requestAnimationFrame(calculateLayout);
        }
    });
    if (containerRef.current) observer.observe(containerRef.current);
    return () => observer.disconnect();
  }, [calculateLayout]);

  useEffect(() => {
    if (!('fonts' in document)) return;
    const update = () => requestAnimationFrame(calculateLayout);
    document.fonts.addEventListener('loadingdone', update);
    return () => document.fonts.removeEventListener('loadingdone', update);
  }, [calculateLayout]);

  if (!text) return null;

  return (
    <div 
      ref={containerRef} 
      className={`w-full h-full flex justify-center items-center relative leading-none overflow-hidden ${className}`}
    >
      {/* Ghost measuring element */}
      <div
        ref={ghostRef}
        className={`absolute pointer-events-none flex flex-col items-center text-center opacity-0 ${className}`}
        style={{ 
            fontSize: `${layout.finalPx}px`, 
            left: '-1000vw', 
            top: 0, 
            whiteSpace: 'nowrap',
            visibility: 'visible',
            width: 'max-content'
        }}
      />

      <div
        style={{ 
          transformOrigin: 'center center',
          transform: `scale(${layout.scale})`,
          fontSize: `${layout.finalPx}px`,
          width: 'max-content',
          minWidth: 'max-content'
        }}
        className="flex flex-col items-center justify-center leading-[1.0] text-center"
      >
        {layout.lines.map((line, idx) => (
            <div key={idx} className="whitespace-nowrap">
                {line}
            </div>
        ))}
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { ScreenKey } from '../../types';
import { useUser } from '../../contexts/UserContext';
import { SlantedButton } from '../ui/SlantedButton';
import { GameText } from '../ui/GameText';
import { audio } from '../../services/audio';
import { Portal } from '../ui/Portal';

interface HomeCommandBarProps {
    onNavigate: (s: ScreenKey) => void;
}

const getRelativeTimeString = (isoString: string) => {
    const date = new Date(isoString);
    const now = new Date();
    const diffInMs = now.getTime() - date.getTime();
    const diffInDays = Math.floor(diffInMs / (1000 * 60 * 60 * 24));
    if (diffInDays <= 0) return 'today';
    if (diffInDays === 1) return 'yesterday';
    if (diffInDays < 7) return `${diffInDays} days ago`;
    const diffInWeeks = Math.floor(diffInDays / 7);
    if (diffInWeeks === 1) return 'a week ago';
    if (diffInWeeks < 4) return `${diffInWeeks} weeks ago`;
    const diffInMonths = Math.floor(diffInDays / 30);
    if (diffInMonths === 1) return 'a month ago';
    if (diffInMonths < 12) return `${diffInMonths} months ago`;
    return 'a long time ago';
};

export const HomeCommandBar: React.FC<HomeCommandBarProps> = ({ onNavigate }) => {
    const { user, activeDeck, setActiveDeck } = useUser();
    const [isRollerOpen, setIsRollerOpen] = useState(false);

    const activeDeckId = user.activeDeckId;
    const activeDeckName = user.deckNames[activeDeckId] || 'UNTITLED';
    const isMainDeckValid = activeDeck.length === 12;

    const deckIds = Object.keys(user.decks).map(Number).sort((a, b) => a - b);
    const count = deckIds.length;
    const angleStep = 360 / count;
    const radius = 130;

    const drumRef = useRef<HTMLDivElement>(null);
    const itemsRef = useRef<(HTMLDivElement | null)[]>([]);
    const rotationRef = useRef((activeDeckId - 1) * angleStep);
    const velocityRef = useRef(0);
    const isDraggingRef = useRef(false);
    const lastPointerY = useRef(0);
    const lastTime = useRef(0);
    const requestRef = useRef<number | null>(null);

    const lastCenteredIndexRef = useRef<number>(activeDeckId - 1);
    const lastTickStepRef = useRef<number>(Math.round(rotationRef.current / angleStep));
    const lastAudioTimeRef = useRef<number>(0);
    const canPlayAudioRef = useRef<boolean>(true);

    const updateDom = useCallback((rot: number) => {
        if (!drumRef.current) return;

        drumRef.current.style.transform = `translate3d(0, 0, -${radius}px) rotateX(${rot}deg)`;

        let currentCenterI = -1;

        for (let i = 0; i < itemsRef.current.length; i++) {
            const item = itemsRef.current[i];
            if (!item) continue;

            const angle = -i * angleStep;
            let normalizedAngle = (angle + rot) % 360;
            if (normalizedAngle > 180) normalizedAngle -= 360;
            else if (normalizedAngle < -180) normalizedAngle += 360;

            const absAngle = Math.abs(normalizedAngle);

            if (absAngle < 110) {
                const distanceScale = 1 - (absAngle / 100) * 0.35;
                const opacity = 1 - (absAngle / 130);

                item.style.transform = `rotateX(${angle}deg) translate3d(0, 0, ${radius}px) scale(${distanceScale})`;
                item.style.opacity = Math.max(0.1, opacity).toString();
                item.style.visibility = 'visible';

                if (absAngle < (angleStep / 2)) currentCenterI = i;
            } else {
                if (item.style.visibility !== 'hidden') {
                    item.style.visibility = 'hidden';
                    item.style.opacity = '0';
                }
            }
        }

        if (currentCenterI !== -1 && currentCenterI !== lastCenteredIndexRef.current) {
            const prevItem = itemsRef.current[lastCenteredIndexRef.current];
            const nextItem = itemsRef.current[currentCenterI];
            if (prevItem) prevItem.classList.remove('is-visually-center');
            if (nextItem) nextItem.classList.add('is-visually-center');
            lastCenteredIndexRef.current = currentCenterI;
        }

        const currentStep = Math.round(rot / angleStep);
        if (currentStep !== lastTickStepRef.current) {
            const now = performance.now();
            const elapsed = now - lastAudioTimeRef.current;

            if (!isDraggingRef.current && elapsed > 1000) {
                canPlayAudioRef.current = false;
            }

            if (canPlayAudioRef.current && elapsed > 15) {
                audio.play('sfx_ui_click', 0.4);
                lastAudioTimeRef.current = now;
            }
            lastTickStepRef.current = currentStep;
        }
    }, [angleStep, radius]);

    const animate = useCallback(() => {
        if (isDraggingRef.current) return;

        velocityRef.current *= 0.96;
        rotationRef.current += velocityRef.current;

        if (Math.abs(velocityRef.current) < 0.4) {
            const targetIndex = Math.round(rotationRef.current / angleStep);
            const targetRotation = targetIndex * angleStep;
            const diff = targetRotation - rotationRef.current;

            rotationRef.current += diff * 0.5;

            if (Math.abs(diff) < 0.15) {
                rotationRef.current = targetRotation;
                velocityRef.current = 0;
                updateDom(rotationRef.current);

                const finalId = ((targetIndex % count + count) % count) + 1;
                if (finalId !== user.activeDeckId) setActiveDeck(finalId);
                return;
            }
        }
        updateDom(rotationRef.current);
        requestRef.current = requestAnimationFrame(animate);
    }, [angleStep, count, user.activeDeckId, setActiveDeck, updateDom]);

    const handlePointerDown = (e: React.PointerEvent) => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
        isDraggingRef.current = true;
        canPlayAudioRef.current = true;
        lastAudioTimeRef.current = performance.now();
        lastPointerY.current = e.clientY;
        lastTime.current = performance.now();
    };

    const handlePointerMove = (e: React.PointerEvent) => {
        if (!isDraggingRef.current) return;
        const now = performance.now();
        const deltaY = e.clientY - lastPointerY.current;
        const deltaTime = now - lastTime.current;
        const rotationDelta = -(deltaY / 100) * angleStep;
        rotationRef.current += rotationDelta;
        updateDom(rotationRef.current);
        if (deltaTime > 0) {
            const instantVelocity = rotationDelta / (deltaTime / 16.67);
            velocityRef.current = velocityRef.current * 0.25 + instantVelocity * 0.75;
        }
        lastPointerY.current = e.clientY;
        lastTime.current = now;
    };

    const handlePointerUp = () => {
        if (!isDraggingRef.current) return;
        isDraggingRef.current = false;
        requestRef.current = requestAnimationFrame(animate);
    };

    useEffect(() => {
        if (isRollerOpen) {
            const t = setTimeout(() => updateDom(rotationRef.current), 50);
            return () => clearTimeout(t);
        }
    }, [isRollerOpen, updateDom]);

    return (
        <div className="w-full flex items-end justify-center px-2 pb-3 gap-2 pointer-events-none relative h-16 overflow-visible">
            {isRollerOpen && (
                <Portal>
                    <div 
                        className="fixed inset-0 z-[600] pointer-events-auto bg-black/40 backdrop-blur-md flex flex-col items-center justify-center" 
                        onClick={() => setIsRollerOpen(false)}
                        onPointerDown={handlePointerDown}
                        onPointerMove={handlePointerMove}
                        onPointerUp={handlePointerUp}
                        onPointerLeave={handlePointerUp}
                    >
                        <div className="w-full h-[32rem] perspective-[1500px] flex items-center justify-center select-none touch-none animate-pop overflow-visible">
                            <div 
                                ref={drumRef}
                                className="relative w-64 h-24 transform-style-3d pointer-events-none will-change-transform"
                                style={{ transform: `translate3d(0, 0, -${radius}px) rotateX(${rotationRef.current}deg)` }}
                            >
                                {deckIds.map((id, i) => {
                                    const stats = user.deckStats[id];
                                    const dateStr = stats ? getRelativeTimeString(stats.lastModified) : 'some time ago';
                                    const isInitialCenter = user.activeDeckId === id;
                                    const isValid = (user.decks[id]?.length || 0) === 12;
                                    const statsText = `cq: ${stats?.conquestWins || 0}/${stats?.conquestTotal || 0} (${stats?.conquestWinRate || 0}%) - ld ${stats?.ladderWins || 0}/${stats?.ladderLosses || 0} (${stats?.ladderWinRate || 0}%)`;

                                    return (
                                        <div 
                                            key={id}
                                            ref={el => itemsRef.current[i] = el}
                                            className={`absolute inset-0 backface-hidden transform-style-3d will-change-transform ${isInitialCenter ? 'is-visually-center' : ''} ${isValid ? 'deck-valid' : 'deck-invalid'}`}
                                            style={{ 
                                                transform: `rotateX(${-i * angleStep}deg) translate3d(0, 0, ${radius}px)`,
                                                opacity: isInitialCenter ? 1 : 0.4,
                                                zIndex: i === lastCenteredIndexRef.current ? 50 : 10
                                            }}
                                        >
                                            <SlantedButton variant="secondary" fullWidth size="lg" className="!h-full shadow-2xl drum-item-button">
                                                <div className="flex flex-col items-center justify-center w-full h-full pointer-events-none px-4">
                                                    <div className="w-full h-8"><GameText text={user.deckNames[id] || 'UNTITLED'} baseFontSize={1.4} className="text-white font-black italic tracking-tighter uppercase" maxLines={1} /></div>
                                                    <div className="w-full h-4 flex items-center justify-center opacity-90">
                                                        <GameText text={statsText} baseFontSize={0.7} maxLines={1} className="text-white font-bold font-black italic tracking-tighter uppercase" />
                                                    </div>
                                                    <div className="w-full h-3 mt-1 opacity-50"><GameText text={`Changed ${dateStr}`} baseFontSize={0.65} className="lowercase italic font-black tracking-tighter" /></div>
                                                </div>
                                            </SlantedButton>
                                        </div>
                                    );
                                })}
                            </div>
                        </div>
                    </div>
                </Portal>
            )}

            <div className="w-[11.5%] pointer-events-auto">
                <SlantedButton variant="blue" size="md" onClick={() => onNavigate('HISTORY')} className="w-full !h-10 shadow-blue-900/40" icon={
                    <div className="flex items-center justify-center scale-90 drop-shadow-[0_2px_3px_rgba(0,0,0,0.8)]">
                        <svg className="w-6 h-6 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
                        </svg>
                    </div>
                } />
            </div>

            <div className="w-[20.5%] pointer-events-auto">
                <SlantedButton variant="blue" fullWidth size="lg" onClick={() => onNavigate('GAME')} className="!h-13 shadow-blue-900/50">
                    <div className="flex flex-col items-center justify-center w-full h-full text-center px-0.5 pt-1">
                        <div className="w-full h-4 opacity-60"><GameText text="PLAY" baseFontSize={0.75} className="font-black italic tracking-tighter uppercase" /></div>
                        <div className="w-full h-8"><GameText text="CONQUEST" baseFontSize={1.25} maxLines={1} className="italic tracking-tighter font-black uppercase" /></div>
                    </div>
                </SlantedButton>
            </div>

            <div className="w-[20.5%] pointer-events-auto">
                <SlantedButton 
                    variant={isMainDeckValid ? 'success' : 'danger'} 
                    fullWidth
                    size="lg"
                    onClick={() => { setIsRollerOpen(!isRollerOpen); audio.playUiClick(); }}
                    className={`!h-13 shadow-slate-900/40 relative z-[70] transition-transform ${isRollerOpen ? 'scale-105' : ''}`}
                >
                    <div className="flex flex-col items-center justify-center w-full h-full text-center px-0.5 pt-1">
                        <div className="flex items-center justify-center gap-1 w-full h-4 opacity-60">
                            <div className="w-max h-full"><GameText text="DECK" baseFontSize={0.75} className="font-black italic tracking-tighter uppercase" /></div>
                            {!isMainDeckValid && <div className="w-1.5 h-1.5 rounded-full bg-amber-500 animate-pulse" />}
                        </div>
                        <div className="w-full h-8"><GameText text={activeDeckName} baseFontSize={1.15} maxLines={2} className="italic tracking-tighter leading-none font-black uppercase" /></div>
                    </div>
                </SlantedButton>
            </div>

            <div className="w-[20.5%] pointer-events-auto">
                <SlantedButton variant="blue" fullWidth size="lg" onClick={() => onNavigate('GAME')} className="!h-13 shadow-blue-900/50">
                    <div className="flex flex-col items-center justify-center w-full h-full text-center px-0.5 pt-1">
                        <div className="w-full h-4 opacity-60"><GameText text="PLAY" baseFontSize={0.75} className="font-black italic tracking-tighter uppercase" /></div>
                        <div className="w-full h-8"><GameText text="LADDER" baseFontSize={1.25} maxLines={1} className="italic tracking-tighter font-black uppercase" /></div>
                    </div>
                </SlantedButton>
            </div>

            <div className="w-[11.5%] pointer-events-auto">
                <SlantedButton variant="blue" size="md" onClick={() => onNavigate('RANK')} className="w-full !h-10 shadow-blue-900/40">
                    <div className="flex flex-col items-center justify-center w-full h-full text-center px-0.5 pt-1">
                        <div className="w-full h-4 opacity-60"><GameText text="RANK" baseFontSize={0.7} className="font-black italic tracking-tighter uppercase text-white" /></div>
                        <div className="w-full h-6"><GameText text={user.rank.toString()} baseFontSize={1.4} className="text-white font-black italic tracking-tighter" /></div>
                    </div>
                </SlantedButton>
            </div>

            <style>{`
                .transform-style-3d { transform-style: preserve-3d; }
                .backface-hidden { backface-visibility: hidden; }
                .is-visually-center.deck-valid .drum-item-button > div:first-child { background: linear-gradient(to bottom, #059669, #064e3b) !important; border-color: #34d399 !important; box-shadow: 0 0.2rem 0 #064e3b, 0 0 20px rgba(16, 185, 129, 0.3) !important; }
                .is-visually-center.deck-invalid .drum-item-button > div:first-child { background: linear-gradient(to bottom, #dc2626, #7f1d1d) !important; border-color: #f87171 !important; box-shadow: 0 0.2rem 0 #7f1d1d, 0 0 20px rgba(239, 68, 68, 0.3) !important; }
                .is-visually-center { filter: grayscale(0) !important; }
            `}</style>
        </div>
    );
};

import React, { useState, useRef, useEffect } from 'react';
import { GameText } from './GameText';

type ButtonVariant = 'primary' | 'secondary' | 'success' | 'danger' | 'warning' | 'blue';

interface SlantedButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
    variant?: ButtonVariant;
    fullWidth?: boolean;
    size?: 'sm' | 'md' | 'lg';
    icon?: React.ReactNode;
    holdDuration?: number; 
    onHoldChange?: (isHolding: boolean) => void;
    onProgressChange?: (progress: number) => void;
}

export const SlantedButton: React.FC<SlantedButtonProps> = ({ 
    children, 
    variant = 'primary', 
    fullWidth = false,
    size = 'md',
    icon,
    className = '',
    holdDuration = 0,
    onHoldChange,
    onProgressChange,
    onClick,
    ...props 
}) => {
    const [progress, setProgress] = useState(0);
    const [isHolding, setIsHolding] = useState(false);
    const timerRef = useRef<number | null>(null);
    const startTimeRef = useRef<number>(0);

    const variants = {
        primary: "from-purple-600 to-purple-900 border-purple-400 shadow-[0_0.2rem_0_rgb(88,28,135)]",
        secondary: "from-slate-700 to-slate-900 border-slate-500 shadow-[0_0.2rem_0_rgb(15,23,42)]",
        success: "from-emerald-600 to-emerald-900 border-emerald-400 shadow-[0_0.2rem_0_rgb(6,78,59)]",
        danger: "from-red-600 to-red-900 border-red-400 shadow-[0_0.2rem_0_rgb(127,29,29)]",
        warning: "from-amber-600 to-amber-900 border-amber-400 shadow-[0_0.2rem_0_rgb(120,53,15)]",
        blue: "from-blue-600 to-blue-900 border-blue-400 shadow-[0_0.2rem_0_rgb(30,58,138)]",
    };

    const sizeConfigs = {
        sm: { height: "h-7", fontSize: 1.15, padding: "px-2" },
        md: { height: "h-10", fontSize: 1.25, padding: "px-4" },
        lg: { height: "h-14", fontSize: 1.35, padding: "px-6" }
    };

    const config = sizeConfigs[size];

    const startHold = (e: React.PointerEvent) => {
        if (!holdDuration || props.disabled) return;
        setIsHolding(true);
        onHoldChange?.(true);
        startTimeRef.current = Date.now();
        timerRef.current = window.setInterval(() => {
            const elapsed = Date.now() - startTimeRef.current;
            const p = Math.min((elapsed / holdDuration) * 100, 100);
            setProgress(p);
            onProgressChange?.(p);
            if (p >= 100) {
                if (timerRef.current) clearInterval(timerRef.current);
                timerRef.current = null;
                setProgress(100);
                onProgressChange?.(100);
                setTimeout(() => {
                    if (onClick) {
                        const sEvent = { clientX: e.clientX, clientY: e.clientY, target: e.target, currentTarget: e.currentTarget, type: 'click' } as any;
                        onClick(sEvent);
                    }
                    setIsHolding(false);
                    onHoldChange?.(false);
                    setProgress(0);
                    onProgressChange?.(0);
                }, 60);
            }
        }, 16);
    };

    const cancelHold = () => {
        if (timerRef.current) { clearInterval(timerRef.current); timerRef.current = null; }
        setIsHolding(false);
        onHoldChange?.(false);
        setProgress(0);
        onProgressChange?.(0);
    };

    useEffect(() => { return () => { if (timerRef.current) clearInterval(timerRef.current); }; }, []);

    const widthOverride = className.match(/w-\[?[\w.%]+\]?/)?.[0] || '';
    const widthClass = fullWidth ? 'w-full' : (widthOverride ? widthOverride : 'w-max');
    const textShadowClass = "drop-shadow-[0_2px_3px_rgba(0,0,0,0.8)]";

    return (
        <div className={`relative group ${widthClass} ${config.height} ${props.disabled ? 'opacity-50 pointer-events-none' : ''}`}>
            <button 
                className={`w-full h-full relative z-10 active:translate-y-0.5 transition-all outline-none ${className}`}
                onPointerDown={holdDuration ? startHold : undefined}
                onPointerUp={holdDuration ? cancelHold : undefined}
                onPointerLeave={holdDuration ? cancelHold : undefined}
                onClick={holdDuration ? undefined : onClick}
                role="button"
                {...props}
            >
                <div className={`absolute inset-0 bg-gradient-to-b border rounded skew-x-[-10deg] transition-all duration-200 overflow-hidden ${variants[variant]}`}>
                    {holdDuration > 0 && (
                        <div className="absolute inset-y-0 left-0 bg-white/20 transition-all duration-75 ease-linear pointer-events-none" style={{ width: `${progress}%` }} />
                    )}
                </div>

                {/* Content Container - No Skew. We remove padding if ONLY an icon exists for perfect centering. */}
                <div className={`relative z-20 h-full pointer-events-none flex items-center justify-center ${children ? config.padding : 'px-0'}`}>
                    <div className={`flex items-center justify-center w-full h-full transition-opacity ${isHolding ? 'opacity-40' : 'opacity-100'}`}>
                        {icon && (
                            <div className={`shrink-0 flex items-center justify-center ${children ? 'mr-1.5' : ''}`}>
                                {icon}
                            </div>
                        )}

                        {children && (
                            typeof children === 'string' || typeof children === 'number' ? (
                                <div className="flex-1 h-full min-w-0">
                                    <GameText 
                                        text={children.toString()} 
                                        baseFontSize={config.fontSize} 
                                        maxScale={1.0}
                                        className={`text-white font-black italic tracking-tighter uppercase ${textShadowClass}`}
                                        minScale={0.3} 
                                    />
                                </div>
                            ) : (
                                <div className={`h-full w-full flex items-center justify-center ${textShadowClass}`}>
                                    {children}
                                </div>
                            )
                        )}
                    </div>
                </div>
            </button>
        </div>
    );
};

import React, { useState, useLayoutEffect, useRef, useEffect, useCallback } from 'react';

interface GameTextProps {
  text: string;
  className?: string;
  baseFontSize: number;
  minScale?: number;
  maxScale?: number;
  maxLines?: number;
}

export const GameText: React.FC<GameTextProps> = ({ 
  text, 
  className = '', 
  baseFontSize, 
  minScale = 0.2,
  maxScale = 1.0,
  maxLines = 1
}) => {
  const [layout, setLayout] = useState<{ lines: string[], scale: number, finalPx: number, ready: boolean }>({ 
      lines: [text || ''], 
      scale: 1,
      finalPx: 16,
      ready: false
  });
  const containerRef = useRef<HTMLDivElement>(null);
  const ghostRef = useRef<HTMLDivElement>(null);

  const calculateLayout = useCallback(() => {
    const container = containerRef.current;
    const ghost = ghostRef.current;
    if (!container || !ghost || !text) return;

    const containerRect = container.getBoundingClientRect();
    const cw = containerRect.width;
    const ch = containerRect.height;

    // FAIL-SAFE: If parent is collapsed, stay at scale 1.0 and wait for ResizeObserver
    if (cw <= 0 || ch <= 0) {
        setLayout(prev => ({ ...prev, ready: false }));
        return;
    }

    const parentStyle = window.getComputedStyle(container);
    const parentPx = parseFloat(parentStyle.fontSize) || 16;
    const targetPx = parentPx * baseFontSize;
    const words = text.split(/\s+/);

    const splitIntoLines = (num: number): string[] => {
      if (num <= 1 || words.length <= 1) return [text];
      const targetLen = text.length / num;
      const res: string[][] = Array.from({ length: num }, () => []);
      let curLine = 0;
      let curChars = 0;
      words.forEach((word) => {
        if (curLine < num - 1) {
            const dStay = Math.abs((curChars + word.length) - targetLen);
            const dMove = Math.abs(curChars - targetLen);
            if (curChars > 0 && dMove < dStay) { curLine++; curChars = 0; }
        }
        res[curLine].push(word);
        curChars += word.length + 1;
      });
      return res.map(l => l.join(' ')).filter(s => s.length > 0);
    };

    const measure = (lines: string[]) => {
      ghost.innerHTML = lines.map(l => `<div>${l}</div>`).join('');
      ghost.style.fontSize = `${targetPx}px`;
      const gw = ghost.offsetWidth;
      const gh = ghost.offsetHeight;
      if (gw <= 0 || gh <= 0) return 1;
      return Math.min((cw / gw) * 0.99, (ch / gh) * 0.99);
    };

    let bestS = 0;
    let bestL: string[] = [text];
    const limit = Math.min(maxLines, words.length, 4);

    for (let i = 1; i <= limit; i++) {
      const candidateL = splitIntoLines(i);
      const s = measure(candidateL);
      const bias = (limit - i) * 0.02;
      if (s + bias > bestS) { bestS = s; bestL = candidateL; }
      if (i === 1 && s >= 0.95) break; 
    }

    setLayout({ 
        lines: bestL, 
        scale: Math.max(minScale, Math.min(maxScale, bestS || 1)),
        finalPx: targetPx,
        ready: true
    });
  }, [text, baseFontSize, minScale, maxScale, maxLines]);

  useLayoutEffect(() => {
    calculateLayout();
    const obs = new ResizeObserver((entries) => {
        if (entries[0].contentRect.width > 0) requestAnimationFrame(calculateLayout);
    });
    if (containerRef.current) obs.observe(containerRef.current);
    return () => obs.disconnect();
  }, [calculateLayout]);

  useEffect(() => {
    if (!('fonts' in document)) return;
    const update = () => requestAnimationFrame(calculateLayout);
    document.fonts.addEventListener('loadingdone', update);
    return () => document.fonts.removeEventListener('loadingdone', update);
  }, [calculateLayout]);

  if (!text) return null;

  return (
    <div ref={containerRef} className={`w-full h-full flex justify-center items-center relative leading-none overflow-hidden ${className}`}>
      <div ref={ghostRef} className={`absolute pointer-events-none flex flex-col items-center text-center opacity-0 ${className}`} style={{ fontSize: `${layout.finalPx}px`, left: '-1000vw', top: 0, whiteSpace: 'nowrap', visibility: 'visible', width: 'max-content' }} />
      <div style={{ transformOrigin: 'center center', transform: `scale(${layout.scale})`, fontSize: `${layout.finalPx}px`, width: 'max-content', minWidth: 'max-content', opacity: layout.ready ? 1 : 0 }} className="flex flex-col items-center justify-center leading-[1.0] text-center transition-opacity duration-150">
        {layout.lines.map((line, idx) => ( <div key={idx} className="whitespace-nowrap">{line}</div> ))}
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { ScreenKey } from '../../types';
import { useUser } from '../../contexts/UserContext';
import { SlantedButton } from '../ui/SlantedButton';
import { GameText } from '../ui/GameText';
import { audio } from '../../services/audio';
import { Portal } from '../ui/Portal';

interface HomeCommandBarProps {
    onNavigate: (s: ScreenKey) => void;
}

const getRelativeTimeString = (isoString: string) => {
    const date = new Date(isoString);
    const now = new Date();
    const diffInMs = now.getTime() - date.getTime();
    const diffInDays = Math.floor(diffInMs / (1000 * 60 * 60 * 24));
    if (diffInDays <= 0) return 'today';
    if (diffInDays === 1) return 'yesterday';
    if (diffInDays < 7) return `${diffInDays} days ago`;
    const diffInWeeks = Math.floor(diffInDays / 7);
    if (diffInWeeks === 1) return 'a week ago';
    if (diffInWeeks < 4) return `${diffInWeeks} weeks ago`;
    const diffInMonths = Math.floor(diffInDays / 30);
    if (diffInMonths === 1) return 'a month ago';
    if (diffInMonths < 12) return `${diffInMonths} months ago`;
    return 'a long time ago';
};

export const HomeCommandBar: React.FC<HomeCommandBarProps> = ({ onNavigate }) => {
    const { user, activeDeck, setActiveDeck } = useUser();
    const [isRollerOpen, setIsRollerOpen] = useState(false);

    const activeDeckId = user.activeDeckId;
    const activeDeckName = user.deckNames[activeDeckId] || 'UNTITLED';
    const isMainDeckValid = activeDeck.length === 12;

    const deckIds = Object.keys(user.decks).map(Number).sort((a, b) => a - b);
    const count = deckIds.length;
    const angleStep = 360 / count;
    const radius = 130;

    const drumRef = useRef<HTMLDivElement>(null);
    const itemsRef = useRef<(HTMLDivElement | null)[]>([]);
    const rotationRef = useRef((activeDeckId - 1) * angleStep);
    const velocityRef = useRef(0);
    const isDraggingRef = useRef(false);
    const lastPointerY = useRef(0);
    const lastTime = useRef(0);
    const requestRef = useRef<number | null>(null);

    const lastCenteredIndexRef = useRef<number>(activeDeckId - 1);
    const lastTickStepRef = useRef<number>(Math.round(rotationRef.current / angleStep));
    const lastAudioTimeRef = useRef<number>(0);
    const canPlayAudioRef = useRef<boolean>(true);

    const updateDom = useCallback((rot: number) => {
        if (!drumRef.current) return;
        drumRef.current.style.transform = `translate3d(0, 0, -${radius}px) rotateX(${rot}deg)`;
        let currentCenterI = -1;
        for (let i = 0; i < itemsRef.current.length; i++) {
            const item = itemsRef.current[i];
            if (!item) continue;
            const angle = -i * angleStep;
            let normalizedAngle = (angle + rot) % 360;
            if (normalizedAngle > 180) normalizedAngle -= 360;
            else if (normalizedAngle < -180) normalizedAngle += 360;
            const absAngle = Math.abs(normalizedAngle);
            if (absAngle < 110) {
                const distanceScale = 1 - (absAngle / 100) * 0.35;
                const opacity = 1 - (absAngle / 130);
                item.style.transform = `rotateX(${angle}deg) translate3d(0, 0, ${radius}px) scale(${distanceScale})`;
                item.style.opacity = Math.max(0.1, opacity).toString();
                item.style.visibility = 'visible';
                if (absAngle < (angleStep / 2)) currentCenterI = i;
            } else {
                if (item.style.visibility !== 'hidden') {
                    item.style.visibility = 'hidden';
                    item.style.opacity = '0';
                }
            }
        }
        if (currentCenterI !== -1 && currentCenterI !== lastCenteredIndexRef.current) {
            const prevItem = itemsRef.current[lastCenteredIndexRef.current];
            const nextItem = itemsRef.current[currentCenterI];
            if (prevItem) prevItem.classList.remove('is-visually-center');
            if (nextItem) nextItem.classList.add('is-visually-center');
            lastCenteredIndexRef.current = currentCenterI;
        }
        const currentStep = Math.round(rot / angleStep);
        if (currentStep !== lastTickStepRef.current) {
            const now = performance.now();
            const elapsed = now - lastAudioTimeRef.current;
            if (!isDraggingRef.current && elapsed > 1000) canPlayAudioRef.current = false;
            if (canPlayAudioRef.current && elapsed > 15) {
                audio.play('sfx_ui_click', 0.4);
                lastAudioTimeRef.current = now;
            }
            lastTickStepRef.current = currentStep;
        }
    }, [angleStep, radius]);

    const animate = useCallback(() => {
        if (isDraggingRef.current) return;
        velocityRef.current *= 0.96;
        rotationRef.current += velocityRef.current;
        if (Math.abs(velocityRef.current) < 0.4) {
            const targetIndex = Math.round(rotationRef.current / angleStep);
            const targetRotation = targetIndex * angleStep;
            const diff = targetRotation - rotationRef.current;
            rotationRef.current += diff * 0.5;
            if (Math.abs(diff) < 0.15) {
                rotationRef.current = targetRotation;
                velocityRef.current = 0;
                updateDom(rotationRef.current);
                const finalId = ((targetIndex % count + count) % count) + 1;
                if (finalId !== user.activeDeckId) setActiveDeck(finalId);
                return;
            }
        }
        updateDom(rotationRef.current);
        requestRef.current = requestAnimationFrame(animate);
    }, [angleStep, count, user.activeDeckId, setActiveDeck, updateDom]);

    const handlePointerDown = (e: React.PointerEvent) => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
        isDraggingRef.current = true;
        canPlayAudioRef.current = true;
        lastAudioTimeRef.current = performance.now();
        lastPointerY.current = e.clientY;
        lastTime.current = performance.now();
    };

    const handlePointerMove = (e: React.PointerEvent) => {
        if (!isDraggingRef.current) return;
        const now = performance.now();
        const deltaY = e.clientY - lastPointerY.current;
        const deltaTime = now - lastTime.current;
        const rotationDelta = -(deltaY / 100) * angleStep;
        rotationRef.current += rotationDelta;
        updateDom(rotationRef.current);
        if (deltaTime > 0) {
            const instantVelocity = rotationDelta / (deltaTime / 16.67);
            velocityRef.current = velocityRef.current * 0.25 + instantVelocity * 0.75;
        }
        lastPointerY.current = e.clientY;
        lastTime.current = now;
    };

    const handlePointerUp = () => {
        if (!isDraggingRef.current) return;
        isDraggingRef.current = false;
        requestRef.current = requestAnimationFrame(animate);
    };

    useEffect(() => {
        if (isRollerOpen) {
            const t = setTimeout(() => updateDom(rotationRef.current), 50);
            return () => clearTimeout(t);
        }
    }, [isRollerOpen, updateDom]);

    return (
        <div className="w-full flex items-end justify-center px-2 pb-3 gap-2 pointer-events-none relative h-16 overflow-visible">
            {isRollerOpen && (
                <Portal>
                    <div className="fixed inset-0 z-[600] pointer-events-auto bg-black/40 backdrop-blur-md flex flex-col items-center justify-center" onClick={() => setIsRollerOpen(false)} onPointerDown={handlePointerDown} onPointerMove={handlePointerMove} onPointerUp={handlePointerUp} onPointerLeave={handlePointerUp}>
                        <div className="w-full h-[32rem] perspective-[1500px] flex items-center justify-center select-none touch-none animate-pop overflow-visible">
                            <div ref={drumRef} className="relative w-64 h-24 transform-style-3d pointer-events-none will-change-transform" style={{ transform: `translate3d(0, 0, -${radius}px) rotateX(${rotationRef.current}deg)` }}>
                                {deckIds.map((id, i) => {
                                    const stats = user.deckStats[id];
                                    const dateStr = stats ? getRelativeTimeString(stats.lastModified) : 'some time ago';
                                    const isInitialCenter = user.activeDeckId === id;
                                    const isValid = (user.decks[id]?.length || 0) === 12;
                                    const statsText = `CQ: ${stats?.conquestWins || 0}/${stats?.conquestTotal || 0} - LD: ${stats?.ladderWins || 0}/${stats?.ladderLosses || 0}`;
                                    return (
                                        <div key={id} ref={el => itemsRef.current[i] = el} className={`absolute inset-0 backface-hidden transform-style-3d will-change-transform ${isInitialCenter ? 'is-visually-center' : ''} ${isValid ? 'deck-valid' : 'deck-invalid'}`} style={{ transform: `rotateX(${-i * angleStep}deg) translate3d(0, 0, ${radius}px)`, opacity: isInitialCenter ? 1 : 0.4, zIndex: i === lastCenteredIndexRef.current ? 50 : 10 }}>
                                            <SlantedButton variant="secondary" fullWidth size="lg" className="!h-full shadow-2xl drum-item-button">
                                                <div className="flex flex-col items-center justify-center w-full h-full pointer-events-none px-4">
                                                    <div className="w-full h-8"><GameText text={user.deckNames[id] || 'UNTITLED'} baseFontSize={1.4} className="text-white font-black italic tracking-tighter uppercase" maxLines={1} /></div>
                                                    <div className="w-full h-4 flex items-center justify-center opacity-90">
                                                        <GameText text={statsText} baseFontSize={0.7} maxLines={1} className="text-white font-bold italic tracking-tighter uppercase" />
                                                    </div>
                                                    <div className="w-full h-3 mt-1 opacity-50"><GameText text={`Changed ${dateStr}`} baseFontSize={0.65} className="lowercase italic font-black tracking-tighter" /></div>
                                                </div>
                                            </SlantedButton>
                                        </div>
                                    );
                                })}
                            </div>
                        </div>
                    </div>
                </Portal>
            )}

            <div className="w-[11.5%] pointer-events-auto">
                <SlantedButton variant="blue" size="md" onClick={() => onNavigate('HISTORY')} className="w-full !h-10 shadow-blue-900/40" icon={
                    <div className="flex items-center justify-center scale-90 drop-shadow-[0_2px_3px_rgba(0,0,0,0.8)]">
                        <svg className="w-6 h-6 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
                        </svg>
                    </div>
                } />
            </div>

            <div className="w-[20.5%] pointer-events-auto">
                <SlantedButton variant="blue" fullWidth size="lg" onClick={() => onNavigate('GAME')} className="!h-14 shadow-blue-900/50">
                    <div className="flex flex-col items-center justify-center w-full h-full text-center px-0.5">
                        <div className="w-full h-5 mb-0.5"><GameText text="PLAY" baseFontSize={1.1} className="font-black italic tracking-tighter uppercase opacity-70" /></div>
                        <div className="w-full h-9"><GameText text="CONQUEST" baseFontSize={1.25} maxLines={1} className="italic tracking-tighter font-black uppercase" /></div>
                    </div>
                </SlantedButton>
            </div>

            <div className="w-[20.5%] pointer-events-auto">
                <SlantedButton variant={isMainDeckValid ? 'success' : 'danger'} fullWidth size="lg" onClick={() => { setIsRollerOpen(!isRollerOpen); audio.playUiClick(); }} className={`!h-14 shadow-slate-900/40 relative z-[70] transition-transform ${isRollerOpen ? 'scale-105' : ''}`}>
                    <div className="flex flex-col items-center justify-center w-full h-full text-center px-0.5">
                        <div className="flex items-center justify-center gap-1 w-full h-5 mb-0.5">
                            <div className="w-max h-full"><GameText text="DECK" baseFontSize={1.1} className="font-black italic tracking-tighter uppercase opacity-70" /></div>
                            {!isMainDeckValid && <div className="w-1.5 h-1.5 rounded-full bg-amber-500 animate-pulse" />}
                        </div>
                        <div className="w-full h-9"><GameText text={activeDeckName} baseFontSize={1.1} maxLines={2} className="italic tracking-tighter leading-none font-black uppercase" /></div>
                    </div>
                </SlantedButton>
            </div>

            <div className="w-[20.5%] pointer-events-auto">
                <SlantedButton variant="blue" fullWidth size="lg" onClick={() => onNavigate('GAME')} className="!h-14 shadow-blue-900/50">
                    <div className="flex flex-col items-center justify-center w-full h-full text-center px-0.5">
                        <div className="w-full h-5 mb-0.5"><GameText text="PLAY" baseFontSize={1.1} className="font-black italic tracking-tighter uppercase opacity-70" /></div>
                        <div className="w-full h-9"><GameText text="LADDER" baseFontSize={1.25} maxLines={1} className="italic tracking-tighter font-black uppercase" /></div>
                    </div>
                </SlantedButton>
            </div>

            <div className="w-[11.5%] pointer-events-auto">
                <SlantedButton variant="blue" size="md" onClick={() => onNavigate('RANK')} className="w-full !h-10 shadow-blue-900/40">
                    <div className="flex flex-col items-center justify-center w-full h-full text-center px-0.5 pt-0.5">
                        <div className="w-full h-4"><GameText text="RANK" baseFontSize={0.8} className="font-black italic tracking-tighter uppercase text-white opacity-60" /></div>
                        <div className="w-full h-6 mt-0.5"><GameText text={user.rank.toString()} baseFontSize={1.4} className="text-white font-black italic tracking-tighter" /></div>
                    </div>
                </SlantedButton>
            </div>

            <style>{`
                .transform-style-3d { transform-style: preserve-3d; }
                .backface-hidden { backface-visibility: hidden; }
                .is-visually-center.deck-valid .drum-item-button > div:first-child { background: linear-gradient(to bottom, #059669, #064e3b) !important; border-color: #34d399 !important; box-shadow: 0 0.2rem 0 #064e3b, 0 0 20px rgba(16, 185, 129, 0.3) !important; }
                .is-visually-center.deck-invalid .drum-item-button > div:first-child { background: linear-gradient(to bottom, #dc2626, #7f1d1d) !important; border-color: #f87171 !important; box-shadow: 0 0.2rem 0 #7f1d1d, 0 0 20px rgba(239, 68, 68, 0.3) !important; }
                .is-visually-center { filter: grayscale(0) !important; }
            `}</style>
        </div>
    );
};

import React, { useState, useLayoutEffect, useRef, useEffect, useCallback } from 'react';

interface GameTextProps {
  text: string;
  className?: string;
  baseFontSize: number;
  minScale?: number;
  maxScale?: number;
  maxLines?: number;
}

export const GameText: React.FC<GameTextProps> = ({ 
  text, 
  className = '', 
  baseFontSize, 
  minScale = 0.1,
  maxScale = 1.0,
  maxLines = 1
}) => {
  const [layout, setLayout] = useState<{ lines: string[], scale: number, finalPx: number, ready: boolean }>({ 
      lines: [text || ''], 
      scale: 1,
      finalPx: 16,
      ready: false
  });
  const containerRef = useRef<HTMLDivElement>(null);
  const ghostRef = useRef<HTMLDivElement>(null);

  const calculateLayout = useCallback(() => {
    const container = containerRef.current;
    const ghost = ghostRef.current;
    if (!container || !ghost || !text) return;

    const cw = container.offsetWidth;
    const ch = container.offsetHeight;

    // PROTECTION: If container hasn't layouted yet (0 width), stay at scale 1 and wait
    if (cw <= 0 || ch <= 0) {
        if (layout.ready) setLayout(prev => ({ ...prev, ready: false }));
        return;
    }

    const parentStyle = window.getComputedStyle(container);
    const parentPx = parseFloat(parentStyle.fontSize) || 20;
    const targetPx = parentPx * baseFontSize;
    const words = text.split(/\s+/);

    const splitIntoLines = (num: number): string[] => {
      if (num <= 1 || words.length <= 1) return [text];
      const targetLen = text.length / num;
      const res: string[][] = Array.from({ length: num }, () => []);
      let curLine = 0;
      let curChars = 0;
      words.forEach((word) => {
        if (curLine < num - 1) {
            const dStay = Math.abs((curChars + word.length) - targetLen);
            const dMove = Math.abs(curChars - targetLen);
            if (curChars > 0 && dMove < dStay) { curLine++; curChars = 0; }
        }
        res[curLine].push(word);
        curChars += word.length + 1;
      });
      return res.map(l => l.join(' ')).filter(s => s.length > 0);
    };

    const measure = (lines: string[]) => {
      ghost.innerHTML = lines.map(l => `<div>${l}</div>`).join('');
      ghost.style.fontSize = `${targetPx}px`;

      // Use scrollWidth/Height to capture the full bounds of the content
      const gw = ghost.scrollWidth;
      const gh = ghost.scrollHeight;

      if (gw <= 0 || gh <= 0) return 1;
      return Math.min((cw / gw) * 0.98, (ch / gh) * 0.98);
    };

    let bestS = 0;
    let bestL: string[] = [text];
    const limit = Math.min(maxLines, words.length, 4);

    for (let i = 1; i <= limit; i++) {
      const candidateL = splitIntoLines(i);
      const s = measure(candidateL);
      const bias = (limit - i) * 0.05; // Strong bias toward fewer lines
      if (s + bias > bestS) {
        bestS = s;
        bestL = candidateL;
      }
      if (i === 1 && s >= 0.95) break; 
    }

    setLayout({ 
        lines: bestL, 
        scale: Math.max(minScale, Math.min(maxScale, bestS || 1)),
        finalPx: targetPx,
        ready: true
    });
  }, [text, baseFontSize, minScale, maxScale, maxLines, layout.ready]);

  useLayoutEffect(() => {
    calculateLayout();
    const obs = new ResizeObserver((entries) => {
        if (entries[0].contentRect.width > 0) requestAnimationFrame(calculateLayout);
    });
    if (containerRef.current) obs.observe(containerRef.current);
    return () => obs.disconnect();
  }, [calculateLayout]);

  useEffect(() => {
    if (!('fonts' in document)) return;
    const update = () => requestAnimationFrame(calculateLayout);
    document.fonts.addEventListener('loadingdone', update);
    return () => document.fonts.removeEventListener('loadingdone', update);
  }, [calculateLayout]);

  if (!text) return null;

  return (
    <div ref={containerRef} className={`w-full h-full flex justify-center items-center relative leading-none overflow-hidden ${className}`}>
      {/* Ghost measuring element */}
      <div ref={ghostRef} className="absolute pointer-events-none flex flex-col items-center text-center opacity-0" style={{ fontSize: `${layout.finalPx}px`, left: '-5000px', top: 0, whiteSpace: 'nowrap', visibility: 'visible', width: 'max-content' }} />

      {/* Actual Scaler */}
      <div 
        style={{ 
          transformOrigin: 'center center', 
          transform: `scale(${layout.scale})`, 
          fontSize: `${layout.finalPx}px`,
          opacity: layout.ready ? 1 : 0
        }} 
        className="flex-none flex flex-col items-center justify-center leading-[1.0] text-center transition-opacity duration-150"
      >
        {layout.lines.map((line, idx) => ( <div key={idx} className="whitespace-nowrap">{line}</div> ))}
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { ScreenKey } from '../../types';
import { useUser } from '../../contexts/UserContext';
import { SlantedButton } from '../ui/SlantedButton';
import { GameText } from '../ui/GameText';
import { audio } from '../../services/audio';
import { Portal } from '../ui/Portal';

interface HomeCommandBarProps {
    onNavigate: (s: ScreenKey) => void;
}

const getRelativeTimeString = (isoString: string) => {
    const date = new Date(isoString);
    const now = new Date();
    const diffInMs = now.getTime() - date.getTime();
    const diffInDays = Math.floor(diffInMs / (1000 * 60 * 60 * 24));
    if (diffInDays <= 0) return 'today';
    if (diffInDays === 1) return 'yesterday';
    if (diffInDays < 7) return `${diffInDays} days ago`;
    const diffInWeeks = Math.floor(diffInDays / 7);
    if (diffInWeeks === 1) return 'a week ago';
    if (diffInWeeks < 4) return `${diffInWeeks} weeks ago`;
    const diffInMonths = Math.floor(diffInDays / 30);
    if (diffInMonths === 1) return 'a month ago';
    if (diffInMonths < 12) return `${diffInMonths} months ago`;
    return 'a long time ago';
};

export const HomeCommandBar: React.FC<HomeCommandBarProps> = ({ onNavigate }) => {
    const { user, activeDeck, setActiveDeck } = useUser();
    const [isRollerOpen, setIsRollerOpen] = useState(false);

    const activeDeckId = user.activeDeckId;
    const activeDeckName = user.deckNames[activeDeckId] || 'UNTITLED';
    const isMainDeckValid = activeDeck.length === 12;

    const deckIds = Object.keys(user.decks).map(Number).sort((a, b) => a - b);
    const count = deckIds.length;
    const angleStep = 360 / count;
    const radius = 130;

    const drumRef = useRef<HTMLDivElement>(null);
    const itemsRef = useRef<(HTMLDivElement | null)[]>([]);
    const rotationRef = useRef((activeDeckId - 1) * angleStep);
    const velocityRef = useRef(0);
    const isDraggingRef = useRef(false);
    const lastPointerY = useRef(0);
    const lastTime = useRef(0);
    const requestRef = useRef<number | null>(null);

    const lastCenteredIndexRef = useRef<number>(activeDeckId - 1);
    const lastTickStepRef = useRef<number>(Math.round(rotationRef.current / angleStep));
    const lastAudioTimeRef = useRef<number>(0);
    const canPlayAudioRef = useRef<boolean>(true);

    const updateDom = useCallback((rot: number) => {
        if (!drumRef.current) return;
        drumRef.current.style.transform = `translate3d(0, 0, -${radius}px) rotateX(${rot}deg)`;
        let currentCenterI = -1;
        for (let i = 0; i < itemsRef.current.length; i++) {
            const item = itemsRef.current[i];
            if (!item) continue;
            const angle = -i * angleStep;
            let normalizedAngle = (angle + rot) % 360;
            if (normalizedAngle > 180) normalizedAngle -= 360;
            else if (normalizedAngle < -180) normalizedAngle += 360;
            const absAngle = Math.abs(normalizedAngle);
            if (absAngle < 110) {
                const distanceScale = 1 - (absAngle / 100) * 0.35;
                const opacity = 1 - (absAngle / 130);
                item.style.transform = `rotateX(${angle}deg) translate3d(0, 0, ${radius}px) scale(${distanceScale})`;
                item.style.opacity = Math.max(0.1, opacity).toString();
                item.style.visibility = 'visible';
                if (absAngle < (angleStep / 2)) currentCenterI = i;
            } else {
                if (item.style.visibility !== 'hidden') {
                    item.style.visibility = 'hidden';
                    item.style.opacity = '0';
                }
            }
        }
        if (currentCenterI !== -1 && currentCenterI !== lastCenteredIndexRef.current) {
            const prevItem = itemsRef.current[lastCenteredIndexRef.current];
            const nextItem = itemsRef.current[currentCenterI];
            if (prevItem) prevItem.classList.remove('is-visually-center');
            if (nextItem) nextItem.classList.add('is-visually-center');
            lastCenteredIndexRef.current = currentCenterI;
        }
        const currentStep = Math.round(rot / angleStep);
        if (currentStep !== lastTickStepRef.current) {
            const now = performance.now();
            const elapsed = now - lastAudioTimeRef.current;
            if (!isDraggingRef.current && elapsed > 1000) canPlayAudioRef.current = false;
            if (canPlayAudioRef.current && elapsed > 15) {
                audio.play('sfx_ui_click', 0.4);
                lastAudioTimeRef.current = now;
            }
            lastTickStepRef.current = currentStep;
        }
    }, [angleStep, radius]);

    const animate = useCallback(() => {
        if (isDraggingRef.current) return;
        velocityRef.current *= 0.96;
        rotationRef.current += velocityRef.current;
        if (Math.abs(velocityRef.current) < 0.4) {
            const targetIndex = Math.round(rotationRef.current / angleStep);
            const targetRotation = targetIndex * angleStep;
            const diff = targetRotation - rotationRef.current;
            rotationRef.current += diff * 0.5;
            if (Math.abs(diff) < 0.15) {
                rotationRef.current = targetRotation;
                velocityRef.current = 0;
                updateDom(rotationRef.current);
                const finalId = ((targetIndex % count + count) % count) + 1;
                if (finalId !== user.activeDeckId) setActiveDeck(finalId);
                return;
            }
        }
        updateDom(rotationRef.current);
        requestRef.current = requestAnimationFrame(animate);
    }, [angleStep, count, user.activeDeckId, setActiveDeck, updateDom]);

    const handlePointerDown = (e: React.PointerEvent) => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
        isDraggingRef.current = true;
        canPlayAudioRef.current = true;
        lastAudioTimeRef.current = performance.now();
        lastPointerY.current = e.clientY;
        lastTime.current = performance.now();
    };

    const handlePointerMove = (e: React.PointerEvent) => {
        if (!isDraggingRef.current) return;
        const now = performance.now();
        const deltaY = e.clientY - lastPointerY.current;
        const deltaTime = now - lastTime.current;
        const rotationDelta = -(deltaY / 100) * angleStep;
        rotationRef.current += rotationDelta;
        updateDom(rotationRef.current);
        if (deltaTime > 0) {
            const instantVelocity = rotationDelta / (deltaTime / 16.67);
            velocityRef.current = velocityRef.current * 0.25 + instantVelocity * 0.75;
        }
        lastPointerY.current = e.clientY;
        lastTime.current = now;
    };

    const handlePointerUp = () => {
        if (!isDraggingRef.current) return;
        isDraggingRef.current = false;
        requestRef.current = requestAnimationFrame(animate);
    };

    useEffect(() => {
        if (isRollerOpen) {
            const t = setTimeout(() => updateDom(rotationRef.current), 50);
            return () => clearTimeout(t);
        }
    }, [isRollerOpen, updateDom]);

    return (
        <div className="w-full flex items-end justify-center px-2 pb-3 gap-2 pointer-events-none relative h-16 overflow-visible">
            {isRollerOpen && (
                <Portal>
                    <div className="fixed inset-0 z-[600] pointer-events-auto bg-black/40 backdrop-blur-md flex flex-col items-center justify-center" onClick={() => setIsRollerOpen(false)} onPointerDown={handlePointerDown} onPointerMove={handlePointerMove} onPointerUp={handlePointerUp} onPointerLeave={handlePointerUp}>
                        <div className="w-full h-[32rem] perspective-[1500px] flex items-center justify-center select-none touch-none animate-pop overflow-visible">
                            <div ref={drumRef} className="relative w-64 h-24 transform-style-3d pointer-events-none will-change-transform" style={{ transform: `translate3d(0, 0, -${radius}px) rotateX(${rotationRef.current}deg)` }}>
                                {deckIds.map((id, i) => {
                                    const stats = user.deckStats[id];
                                    const dateStr = stats ? getRelativeTimeString(stats.lastModified) : 'some time ago';
                                    const isInitialCenter = user.activeDeckId === id;
                                    const isValid = (user.decks[id]?.length || 0) === 12;
                                    const statsText = `CQ: ${stats?.conquestWins || 0}/${stats?.conquestTotal || 0} - LD: ${stats?.ladderWins || 0}/${stats?.ladderLosses || 0}`;
                                    return (
                                        <div key={id} ref={el => itemsRef.current[i] = el} className={`absolute inset-0 backface-hidden transform-style-3d will-change-transform ${isInitialCenter ? 'is-visually-center' : ''} ${isValid ? 'deck-valid' : 'deck-invalid'}`} style={{ transform: `rotateX(${-i * angleStep}deg) translate3d(0, 0, ${radius}px)`, opacity: isInitialCenter ? 1 : 0.4, zIndex: i === lastCenteredIndexRef.current ? 50 : 10 }}>
                                            <SlantedButton variant="secondary" fullWidth size="lg" className="!h-full shadow-2xl drum-item-button">
                                                <div className="flex flex-col items-center justify-center w-full h-full pointer-events-none px-4">
                                                    <div className="w-full h-8"><GameText text={user.deckNames[id] || 'UNTITLED'} baseFontSize={1.4} className="text-white font-black italic tracking-tighter uppercase" maxLines={1} /></div>
                                                    <div className="w-full h-4 flex items-center justify-center opacity-90">
                                                        <GameText text={statsText} baseFontSize={0.7} maxLines={1} className="text-white font-bold italic tracking-tighter uppercase" />
                                                    </div>
                                                    <div className="w-full h-3 mt-1 opacity-50"><GameText text={`Changed ${dateStr}`} baseFontSize={0.65} className="lowercase italic font-black tracking-tighter" /></div>
                                                </div>
                                            </SlantedButton>
                                        </div>
                                    );
                                })}
                            </div>
                        </div>
                    </div>
                </Portal>
            )}

            <div className="w-[11.5%] pointer-events-auto">
                <SlantedButton variant="blue" size="md" onClick={() => onNavigate('HISTORY')} className="w-full !h-10 shadow-blue-900/40" icon={
                    <div className="flex items-center justify-center scale-90 drop-shadow-[0_2px_3px_rgba(0,0,0,0.8)]">
                        <svg className="w-6 h-6 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
                        </svg>
                    </div>
                } />
            </div>

            <div className="w-[20.5%] pointer-events-auto">
                <SlantedButton variant="blue" fullWidth size="lg" onClick={() => onNavigate('GAME')} className="!h-15 shadow-blue-900/50">
                    <div className="flex flex-col items-center justify-center w-full h-full text-center px-0.5">
                        <div className="w-full h-6 mb-0.5"><GameText text="PLAY" baseFontSize={1.1} className="font-black italic tracking-tighter uppercase opacity-70" /></div>
                        <div className="w-full h-10"><GameText text="CONQUEST" baseFontSize={1.3} maxLines={1} className="italic tracking-tighter font-black uppercase" /></div>
                    </div>
                </SlantedButton>
            </div>

            <div className="w-[20.5%] pointer-events-auto">
                <SlantedButton variant={isMainDeckValid ? 'success' : 'danger'} fullWidth size="lg" onClick={() => { setIsRollerOpen(!isRollerOpen); audio.playUiClick(); }} className={`!h-15 shadow-slate-900/40 relative z-[70] transition-transform ${isRollerOpen ? 'scale-105' : ''}`}>
                    <div className="flex flex-col items-center justify-center w-full h-full text-center px-0.5">
                        <div className="flex items-center justify-center gap-1 w-full h-6 mb-0.5">
                            <div className="w-max h-full"><GameText text="DECK" baseFontSize={1.1} className="font-black italic tracking-tighter uppercase opacity-70" /></div>
                            {!isMainDeckValid && <div className="w-1.5 h-1.5 rounded-full bg-amber-500 animate-pulse" />}
                        </div>
                        <div className="w-full h-10"><GameText text={activeDeckName} baseFontSize={1.15} maxLines={2} className="italic tracking-tighter leading-none font-black uppercase" /></div>
                    </div>
                </SlantedButton>
            </div>

            <div className="w-[20.5%] pointer-events-auto">
                <SlantedButton variant="blue" fullWidth size="lg" onClick={() => onNavigate('GAME')} className="!h-15 shadow-blue-900/50">
                    <div className="flex flex-col items-center justify-center w-full h-full text-center px-0.5">
                        <div className="w-full h-6 mb-0.5"><GameText text="PLAY" baseFontSize={1.1} className="font-black italic tracking-tighter uppercase opacity-70" /></div>
                        <div className="w-full h-10"><GameText text="LADDER" baseFontSize={1.3} maxLines={1} className="italic tracking-tighter font-black uppercase" /></div>
                    </div>
                </SlantedButton>
            </div>

            <div className="w-[11.5%] pointer-events-auto">
                <SlantedButton variant="blue" size="md" onClick={() => onNavigate('RANK')} className="w-full !h-10 shadow-blue-900/40">
                    <div className="flex flex-col items-center justify-center w-full h-full text-center px-0.5 pt-0.5">
                        <div className="w-full h-4"><GameText text="RANK" baseFontSize={0.8} className="font-black italic tracking-tighter uppercase text-white opacity-60" /></div>
                        <div className="w-full h-6 mt-0.5"><GameText text={user.rank.toString()} baseFontSize={1.4} className="text-white font-black italic tracking-tighter" /></div>
                    </div>
                </SlantedButton>
            </div>

            <style>{`
                .transform-style-3d { transform-style: preserve-3d; }
                .backface-hidden { backface-visibility: hidden; }
                .is-visually-center.deck-valid .drum-item-button > div:first-child { background: linear-gradient(to bottom, #059669, #064e3b) !important; border-color: #34d399 !important; box-shadow: 0 0.2rem 0 #064e3b, 0 0 20px rgba(16, 185, 129, 0.3) !important; }
                .is-visually-center.deck-invalid .drum-item-button > div:first-child { background: linear-gradient(to bottom, #dc2626, #7f1d1d) !important; border-color: #f87171 !important; box-shadow: 0 0.2rem 0 #7f1d1d, 0 0 20px rgba(239, 68, 68, 0.3) !important; }
                .is-visually-center { filter: grayscale(0) !important; }
            `}</style>
        </div>
    );
};

import React, { useState, useRef, useEffect } from 'react';
import { GameText } from './GameText';

type ButtonVariant = 'primary' | 'secondary' | 'success' | 'danger' | 'warning' | 'blue';

interface SlantedButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
    variant?: ButtonVariant;
    fullWidth?: boolean;
    size?: 'sm' | 'md' | 'lg';
    icon?: React.ReactNode;
    holdDuration?: number; 
    onHoldChange?: (isHolding: boolean) => void;
    onProgressChange?: (progress: number) => void;
}

export const SlantedButton: React.FC<SlantedButtonProps> = ({ 
    children, 
    variant = 'primary', 
    fullWidth = false,
    size = 'md',
    icon,
    className = '',
    holdDuration = 0,
    onHoldChange,
    onProgressChange,
    onClick,
    ...props 
}) => {
    const [progress, setProgress] = useState(0);
    const [isHolding, setIsHolding] = useState(false);
    const timerRef = useRef<number | null>(null);
    const startTimeRef = useRef<number>(0);

    const variants = {
        primary: "from-purple-600 to-purple-900 border-purple-400 shadow-[0_0.2rem_0_rgb(88,28,135)]",
        secondary: "from-slate-700 to-slate-900 border-slate-500 shadow-[0_0.2rem_0_rgb(15,23,42)]",
        success: "from-emerald-600 to-emerald-900 border-emerald-400 shadow-[0_0.2rem_0_rgb(6,78,59)]",
        danger: "from-red-600 to-red-900 border-red-400 shadow-[0_0.2rem_0_rgb(127,29,29)]",
        warning: "from-amber-600 to-amber-900 border-amber-400 shadow-[0_0.2rem_0_rgb(120,53,15)]",
        blue: "from-blue-600 to-blue-900 border-blue-400 shadow-[0_0.2rem_0_rgb(30,58,138)]",
    };

    const sizeConfigs = {
        sm: { height: "h-7", fontSize: 1.15, padding: "px-2" },
        md: { height: "h-10", fontSize: 1.25, padding: "px-4" },
        lg: { height: "h-15", fontSize: 1.35, padding: "px-6" }
    };

    const config = sizeConfigs[size];

    const startHold = (e: React.PointerEvent) => {
        if (!holdDuration || props.disabled) return;
        setIsHolding(true);
        onHoldChange?.(true);
        startTimeRef.current = Date.now();
        timerRef.current = window.setInterval(() => {
            const elapsed = Date.now() - startTimeRef.current;
            const p = Math.min((elapsed / holdDuration) * 100, 100);
            setProgress(p);
            onProgressChange?.(p);
            if (p >= 100) {
                if (timerRef.current) clearInterval(timerRef.current);
                timerRef.current = null;
                setProgress(100);
                onProgressChange?.(100);
                setTimeout(() => {
                    if (onClick) {
                        const sEvent = { clientX: e.clientX, clientY: e.clientY, target: e.target, currentTarget: e.currentTarget, type: 'click' } as any;
                        onClick(sEvent);
                    }
                    setIsHolding(false);
                    onHoldChange?.(false);
                    setProgress(0);
                    onProgressChange?.(0);
                }, 60);
            }
        }, 16);
    };

    const cancelHold = () => {
        if (timerRef.current) { clearInterval(timerRef.current); timerRef.current = null; }
        setIsHolding(false);
        onHoldChange?.(false);
        setProgress(0);
        onProgressChange?.(0);
    };

    useEffect(() => { return () => { if (timerRef.current) clearInterval(timerRef.current); }; }, []);

    const widthOverride = className.match(/w-\[?[\w.%]+\]?/)?.[0] || '';
    const widthClass = fullWidth ? 'w-full' : (widthOverride ? widthOverride : 'w-max');
    const textShadowClass = "drop-shadow-[0_2px_3px_rgba(0,0,0,0.8)]";

    return (
        <div className={`relative group ${widthClass} ${config.height} ${props.disabled ? 'opacity-50 pointer-events-none' : ''}`}>
            <button 
                className={`w-full h-full relative z-10 active:translate-y-0.5 transition-all outline-none ${className}`}
                onPointerDown={holdDuration ? startHold : undefined}
                onPointerUp={holdDuration ? cancelHold : undefined}
                onPointerLeave={holdDuration ? cancelHold : undefined}
                onClick={holdDuration ? undefined : onClick}
                role="button"
                {...props}
            >
                <div className={`absolute inset-0 bg-gradient-to-b border rounded skew-x-[-10deg] transition-all duration-200 overflow-hidden ${variants[variant]}`}>
                    {holdDuration > 0 && (
                        <div className="absolute inset-y-0 left-0 bg-white/20 transition-all duration-75 ease-linear pointer-events-none" style={{ width: `${progress}%` }} />
                    )}
                </div>

                <div className={`relative z-20 h-full pointer-events-none flex items-center justify-center ${children ? config.padding : 'px-0'}`}>
                    <div className={`flex items-center justify-center w-full h-full transition-opacity ${isHolding ? 'opacity-40' : 'opacity-100'}`}>
                        {icon && (
                            <div className={`shrink-0 flex items-center justify-center ${children ? 'mr-1.5' : ''}`}>
                                {icon}
                            </div>
                        )}

                        {children && (
                            typeof children === 'string' || typeof children === 'number' ? (
                                <div className="flex-1 h-full min-w-0">
                                    <GameText 
                                        text={children.toString()} 
                                        baseFontSize={config.fontSize} 
                                        maxScale={1.0}
                                        className={`text-white font-black italic tracking-tighter uppercase ${textShadowClass}`}
                                        minScale={0.3} 
                                    />
                                </div>
                            ) : (
                                <div className={`h-full w-full flex items-center justify-center ${textShadowClass}`}>
                                    {children}
                                </div>
                            )
                        )}
                    </div>
                </div>
            </button>
        </div>
    );
};

