    return (
        <div className={`relative group ${widthClass} ${config.height} ${props.disabled ? 'opacity-50 pointer-events-none' : ''}`}>
            <button 
                className={`w-full h-full relative z-10 active:translate-y-0.5 transition-all outline-none ${className}`}
                onPointerDown={holdDuration ? startHold : undefined}
                onPointerUp={holdDuration ? cancelHold : undefined}
                onPointerLeave={holdDuration ? cancelHold : undefined}
                onClick={holdDuration ? undefined : onClick}
                role="button"
                {...props}
            >
                <div className={`absolute inset-0 bg-gradient-to-b border rounded skew-x-[-10deg] transition-all duration-200 overflow-hidden ${variants[variant]}`}>
                    {holdDuration > 0 && (
                        <div className="absolute inset-y-0 left-0 bg-white/20 transition-all duration-75 ease-linear pointer-events-none" style={{ width: `${progress}%` }} />
                    )}
                </div>

                {/* 
                  DETERMINISTIC GRID WRAPPER
                  Using a 2-row grid system for consistent vertical alignment.
                  Column 1 is for icons, Column 2 is for text content.
                */}
                <div className={`relative z-20 h-full pointer-events-none grid grid-cols-[auto_1fr] items-center justify-center ${children ? config.padding : 'px-0'}`}>
                    {icon && (
                        <div className="flex items-center justify-center pr-1.5 h-full">
                            {icon}
                        </div>
                    )}

                    <div className={`col-start-2 h-full w-full grid grid-rows-[auto_1fr] items-center justify-center transition-opacity ${isHolding ? 'opacity-40' : 'opacity-100'}`}>
                        {children && (
                            typeof children === 'string' || typeof children === 'number' ? (
                                <div className="row-span-2 w-full h-full">
                                    <GameText 
                                        text={children.toString()} 
                                        baseFontSize={config.fontSize} 
                                        maxScale={1.0}
                                        className="text-white font-black italic tracking-tighter uppercase drop-shadow-[0_2px_3px_rgba(0,0,0,0.8)]"
                                        minScale={0.3} 
                                    />
                                </div>
                            ) : (
                                <div className="row-span-2 w-full h-full drop-shadow-[0_2px_3px_rgba(0,0,0,0.8)]">
                                    {children}
                                </div>
                            )
                        )}
                    </div>
                </div>
            </button>
        </div>
    );
};

import React, { useState, useLayoutEffect, useRef, useEffect, useCallback } from 'react';

interface GameTextProps {
  text: string;
  className?: string;
  baseFontSize: number;
  minScale?: number;
  maxScale?: number;
  maxLines?: number;
}

export const GameText: React.FC<GameTextProps> = ({ 
  text, 
  className = '', 
  baseFontSize, 
  minScale = 0.1,
  maxScale = 1.0,
  maxLines = 1
}) => {
  const [layout, setLayout] = useState<{ lines: string[], scale: number, finalPx: number, ready: boolean }>({ 
      lines: [text || ''], 
      scale: 1,
      finalPx: 16,
      ready: false
  });
  const containerRef = useRef<HTMLDivElement>(null);
  const ghostRef = useRef<HTMLDivElement>(null);

  const calculateLayout = useCallback(() => {
    const container = containerRef.current;
    const ghost = ghostRef.current;
    if (!container || !ghost || !text) return;

    // Use getBoundingClientRect for sub-pixel accuracy in Grid/Flex environments
    const rect = container.getBoundingClientRect();
    const cw = rect.width;
    const ch = rect.height;

    // Measurement Gate: If the container isn't visible yet, don't shrink the text.
    if (cw <= 0 || ch <= 0) {
        return;
    }

    const parentStyle = window.getComputedStyle(container);
    const parentPx = parseFloat(parentStyle.fontSize) || 20;
    const targetPx = parentPx * baseFontSize;
    const words = text.split(/\s+/);

    const splitIntoLines = (num: number): string[] => {
      if (num <= 1 || words.length <= 1) return [text];
      const targetLen = text.length / num;
      const res: string[][] = Array.from({ length: num }, () => []);
      let curLine = 0;
      let curChars = 0;
      words.forEach((word) => {
        if (curLine < num - 1) {
            const dStay = Math.abs((curChars + word.length) - targetLen);
            const dMove = Math.abs(curChars - targetLen);
            if (curChars > 0 && dMove < dStay) { curLine++; curChars = 0; }
        }
        res[curLine].push(word);
        curChars += word.length + 1;
      });
      return res.map(l => l.join(' ')).filter(s => s.length > 0);
    };

    const measure = (lines: string[]) => {
      ghost.innerHTML = lines.map(l => `<div>${l}</div>`).join('');
      ghost.style.fontSize = `${targetPx}px`;

      const gw = ghost.scrollWidth;
      const gh = ghost.scrollHeight;

      if (gw <= 0 || gh <= 0) return 1;
      return Math.min((cw / gw) * 0.98, (ch / gh) * 0.98);
    };

    let bestS = 0;
    let bestL: string[] = [text];
    const limit = Math.min(maxLines, words.length, 4);

    for (let i = 1; i <= limit; i++) {
      const candidateL = splitIntoLines(i);
      const s = measure(candidateL);
      const bias = (limit - i) * 0.05; 
      if (s + bias > bestS) {
        bestS = s;
        bestL = candidateL;
      }
      if (i === 1 && s >= 0.95) break; 
    }

    setLayout({ 
        lines: bestL, 
        scale: Math.max(minScale, Math.min(maxScale, bestS || 1)),
        finalPx: targetPx,
        ready: true
    });
  }, [text, baseFontSize, minScale, maxScale, maxLines]);

  useLayoutEffect(() => {
    calculateLayout();
    const obs = new ResizeObserver((entries) => {
        if (entries[0].contentRect.width > 0) requestAnimationFrame(calculateLayout);
    });
    if (containerRef.current) obs.observe(containerRef.current);
    return () => obs.disconnect();
  }, [calculateLayout]);

  useEffect(() => {
    if (!('fonts' in document)) return;
    const update = () => requestAnimationFrame(calculateLayout);
    document.fonts.addEventListener('loadingdone', update);
    return () => document.fonts.removeEventListener('loadingdone', update);
  }, [calculateLayout]);

  if (!text) return null;

  return (
    <div ref={containerRef} className={`w-full h-full flex justify-center items-center relative leading-none overflow-hidden ${className}`}>
      <div ref={ghostRef} className="absolute pointer-events-none flex flex-col items-center text-center opacity-0" style={{ fontSize: `${layout.finalPx}px`, left: '-5000px', top: 0, whiteSpace: 'nowrap', visibility: 'visible', width: 'max-content' }} />
      <div 
        style={{ 
          transformOrigin: 'center center', 
          transform: `scale(${layout.scale})`, 
          fontSize: `${layout.finalPx}px`,
          opacity: layout.ready ? 1 : 0
        }} 
        className="flex-none flex flex-col items-center justify-center leading-[1.0] text-center transition-opacity duration-150"
      >
        {layout.lines.map((line, idx) => ( <div key={idx} className="whitespace-nowrap">{line}</div> ))}
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { ScreenKey } from '../../types';
import { useUser } from '../../contexts/UserContext';
import { SlantedButton } from '../ui/SlantedButton';
import { GameText } from '../ui/GameText';
import { audio } from '../../services/audio';
import { Portal } from '../ui/Portal';

interface HomeCommandBarProps {
    onNavigate: (s: ScreenKey) => void;
}

const getRelativeTimeString = (isoString: string) => {
    const date = new Date(isoString);
    const now = new Date();
    const diffInMs = now.getTime() - date.getTime();
    const diffInDays = Math.floor(diffInMs / (1000 * 60 * 60 * 24));
    if (diffInDays <= 0) return 'today';
    if (diffInDays === 1) return 'yesterday';
    if (diffInDays < 7) return `${diffInDays} days ago`;
    const diffInWeeks = Math.floor(diffInDays / 7);
    if (diffInWeeks === 1) return 'a week ago';
    if (diffInWeeks < 4) return `${diffInWeeks} weeks ago`;
    const diffInMonths = Math.floor(diffInDays / 30);
    if (diffInMonths === 1) return 'a month ago';
    if (diffInMonths < 12) return `${diffInMonths} months ago`;
    return 'a long time ago';
};

export const HomeCommandBar: React.FC<HomeCommandBarProps> = ({ onNavigate }) => {
    const { user, activeDeck, setActiveDeck } = useUser();
    const [isRollerOpen, setIsRollerOpen] = useState(false);

    const activeDeckId = user.activeDeckId;
    const activeDeckName = user.deckNames[activeDeckId] || 'UNTITLED';
    const isMainDeckValid = activeDeck.length === 12;

    const deckIds = Object.keys(user.decks).map(Number).sort((a, b) => a - b);
    const count = deckIds.length;
    const angleStep = 360 / count;
    const radius = 130;

    const drumRef = useRef<HTMLDivElement>(null);
    const itemsRef = useRef<(HTMLDivElement | null)[]>([]);
    const rotationRef = useRef((activeDeckId - 1) * angleStep);
    const velocityRef = useRef(0);
    const isDraggingRef = useRef(false);
    const lastPointerY = useRef(0);
    const lastTime = useRef(0);
    const requestRef = useRef<number | null>(null);

    const lastCenteredIndexRef = useRef<number>(activeDeckId - 1);
    const lastTickStepRef = useRef<number>(Math.round(rotationRef.current / angleStep));
    const lastAudioTimeRef = useRef<number>(0);
    const canPlayAudioRef = useRef<boolean>(true);

    const updateDom = useCallback((rot: number) => {
        if (!drumRef.current) return;
        drumRef.current.style.transform = `translate3d(0, 0, -${radius}px) rotateX(${rot}deg)`;
        let currentCenterI = -1;
        for (let i = 0; i < itemsRef.current.length; i++) {
            const item = itemsRef.current[i];
            if (!item) continue;
            const angle = -i * angleStep;
            let normalizedAngle = (angle + rot) % 360;
            if (normalizedAngle > 180) normalizedAngle -= 360;
            else if (normalizedAngle < -180) normalizedAngle += 360;
            const absAngle = Math.abs(normalizedAngle);
            if (absAngle < 110) {
                const distanceScale = 1 - (absAngle / 100) * 0.35;
                const opacity = 1 - (absAngle / 130);
                item.style.transform = `rotateX(${angle}deg) translate3d(0, 0, ${radius}px) scale(${distanceScale})`;
                item.style.opacity = Math.max(0.1, opacity).toString();
                item.style.visibility = 'visible';
                if (absAngle < (angleStep / 2)) currentCenterI = i;
            } else {
                if (item.style.visibility !== 'hidden') {
                    item.style.visibility = 'hidden';
                    item.style.opacity = '0';
                }
            }
        }
        if (currentCenterI !== -1 && currentCenterI !== lastCenteredIndexRef.current) {
            const prevItem = itemsRef.current[lastCenteredIndexRef.current];
            const nextItem = itemsRef.current[currentCenterI];
            if (prevItem) prevItem.classList.remove('is-visually-center');
            if (nextItem) nextItem.classList.add('is-visually-center');
            lastCenteredIndexRef.current = currentCenterI;
        }
        const currentStep = Math.round(rot / angleStep);
        if (currentStep !== lastTickStepRef.current) {
            const now = performance.now();
            const elapsed = now - lastAudioTimeRef.current;
            if (!isDraggingRef.current && elapsed > 1000) canPlayAudioRef.current = false;
            if (canPlayAudioRef.current && elapsed > 15) {
                audio.play('sfx_ui_click', 0.4);
                lastAudioTimeRef.current = now;
            }
            lastTickStepRef.current = currentStep;
        }
    }, [angleStep, radius]);

    const animate = useCallback(() => {
        if (isDraggingRef.current) return;
        velocityRef.current *= 0.96;
        rotationRef.current += velocityRef.current;
        if (Math.abs(velocityRef.current) < 0.4) {
            const targetIndex = Math.round(rotationRef.current / angleStep);
            const targetRotation = targetIndex * angleStep;
            const diff = targetRotation - rotationRef.current;
            rotationRef.current += diff * 0.5;
            if (Math.abs(diff) < 0.15) {
                rotationRef.current = targetRotation;
                velocityRef.current = 0;
                updateDom(rotationRef.current);
                const finalId = ((targetIndex % count + count) % count) + 1;
                if (finalId !== user.activeDeckId) setActiveDeck(finalId);
                return;
            }
        }
        updateDom(rotationRef.current);
        requestRef.current = requestAnimationFrame(animate);
    }, [angleStep, count, user.activeDeckId, setActiveDeck, updateDom]);

    const handlePointerDown = (e: React.PointerEvent) => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
        isDraggingRef.current = true;
        canPlayAudioRef.current = true;
        lastAudioTimeRef.current = performance.now();
        lastPointerY.current = e.clientY;
        lastTime.current = performance.now();
    };

    const handlePointerMove = (e: React.PointerEvent) => {
        if (!isDraggingRef.current) return;
        const now = performance.now();
        const deltaY = e.clientY - lastPointerY.current;
        const deltaTime = now - lastTime.current;
        const rotationDelta = -(deltaY / 100) * angleStep;
        rotationRef.current += rotationDelta;
        updateDom(rotationRef.current);
        if (deltaTime > 0) {
            const instantVelocity = rotationDelta / (deltaTime / 16.67);
            velocityRef.current = velocityRef.current * 0.25 + instantVelocity * 0.75;
        }
        lastPointerY.current = e.clientY;
        lastTime.current = now;
    };

    const handlePointerUp = () => {
        if (!isDraggingRef.current) return;
        isDraggingRef.current = false;
        requestRef.current = requestAnimationFrame(animate);
    };

    useEffect(() => {
        if (isRollerOpen) {
            const t = setTimeout(() => updateDom(rotationRef.current), 50);
            return () => clearTimeout(t);
        }
    }, [isRollerOpen, updateDom]);

    return (
        <div className="w-full flex items-end justify-center px-2 pb-3 gap-2 pointer-events-none relative h-16 overflow-visible">
            {isRollerOpen && (
                <Portal>
                    <div className="fixed inset-0 z-[600] pointer-events-auto bg-black/40 backdrop-blur-md flex flex-col items-center justify-center" onClick={() => setIsRollerOpen(false)} onPointerDown={handlePointerDown} onPointerMove={handlePointerMove} onPointerUp={handlePointerUp} onPointerLeave={handlePointerUp}>
                        <div className="w-full h-[32rem] perspective-[1500px] flex items-center justify-center select-none touch-none animate-pop overflow-visible">
                            <div ref={drumRef} className="relative w-64 h-24 transform-style-3d pointer-events-none will-change-transform" style={{ transform: `translate3d(0, 0, -${radius}px) rotateX(${rotationRef.current}deg)` }}>
                                {deckIds.map((id, i) => {
                                    const stats = user.deckStats[id];
                                    const dateStr = stats ? getRelativeTimeString(stats.lastModified) : 'some time ago';
                                    const isInitialCenter = user.activeDeckId === id;
                                    const isValid = (user.decks[id]?.length || 0) === 12;
                                    const statsText = `CQ: ${stats?.conquestWins || 0}/${stats?.conquestTotal || 0} - LD: ${stats?.ladderWins || 0}/${stats?.ladderLosses || 0}`;
                                    return (
                                        <div key={id} ref={el => itemsRef.current[i] = el} className={`absolute inset-0 backface-hidden transform-style-3d will-change-transform ${isInitialCenter ? 'is-visually-center' : ''} ${isValid ? 'deck-valid' : 'deck-invalid'}`} style={{ transform: `rotateX(${-i * angleStep}deg) translate3d(0, 0, ${radius}px)`, opacity: isInitialCenter ? 1 : 0.4, zIndex: i === lastCenteredIndexRef.current ? 50 : 10 }}>
                                            <SlantedButton variant="secondary" fullWidth size="lg" className="!h-full shadow-2xl drum-item-button">
                                                <div className="grid grid-rows-[2rem_1.2rem_1rem] items-center justify-center w-full h-full pointer-events-none px-4">
                                                    <div className="w-full h-8"><GameText text={user.deckNames[id] || 'UNTITLED'} baseFontSize={1.4} className="text-white font-black italic tracking-tighter uppercase" maxLines={1} /></div>
                                                    <div className="w-full h-4 flex items-center justify-center opacity-90">
                                                        <GameText text={statsText} baseFontSize={0.7} maxLines={1} className="text-white font-bold italic tracking-tighter uppercase" />
                                                    </div>
                                                    <div className="w-full h-3 mt-1 opacity-50"><GameText text={`Changed ${dateStr}`} baseFontSize={0.65} className="lowercase italic font-black tracking-tighter" /></div>
                                                </div>
                                            </SlantedButton>
                                        </div>
                                    );
                                })}
                            </div>
                        </div>
                    </div>
                </Portal>
            )}

            <div className="w-[11.5%] pointer-events-auto">
                <SlantedButton variant="blue" size="md" onClick={() => onNavigate('HISTORY')} className="w-full !h-10 shadow-blue-900/40" icon={
                    <div className="flex items-center justify-center scale-90 drop-shadow-[0_2px_3px_rgba(0,0,0,0.8)]">
                        <svg className="w-6 h-6 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
                        </svg>
                    </div>
                } />
            </div>

            <div className="w-[20.5%] pointer-events-auto">
                <SlantedButton variant="blue" fullWidth size="lg" onClick={() => onNavigate('GAME')} className="!h-15 shadow-blue-900/50">
                    <div className="grid grid-rows-[1.5rem_2.5rem] items-center justify-center w-full h-full text-center px-0.5">
                        <div className="w-full h-full"><GameText text="PLAY" baseFontSize={1.1} className="font-black italic tracking-tighter uppercase opacity-70" /></div>
                        <div className="w-full h-full"><GameText text="CONQUEST" baseFontSize={1.3} maxLines={1} className="italic tracking-tighter font-black uppercase" /></div>
                    </div>
                </SlantedButton>
            </div>

            <div className="w-[20.5%] pointer-events-auto">
                <SlantedButton variant={isMainDeckValid ? 'success' : 'danger'} fullWidth size="lg" onClick={() => { setIsRollerOpen(!isRollerOpen); audio.playUiClick(); }} className={`!h-15 shadow-slate-900/40 relative z-[70] transition-transform ${isRollerOpen ? 'scale-105' : ''}`}>
                    <div className="grid grid-rows-[1.5rem_2.5rem] items-center justify-center w-full h-full text-center px-0.5">
                        <div className="flex items-center justify-center gap-1 w-full h-full">
                            <div className="w-max h-full"><GameText text="DECK" baseFontSize={1.1} className="font-black italic tracking-tighter uppercase opacity-70" /></div>
                            {!isMainDeckValid && <div className="w-1.5 h-1.5 rounded-full bg-amber-500 animate-pulse" />}
                        </div>
                        <div className="w-full h-full"><GameText text={activeDeckName} baseFontSize={1.15} maxLines={2} className="italic tracking-tighter leading-none font-black uppercase" /></div>
                    </div>
                </SlantedButton>
            </div>

            <div className="w-[20.5%] pointer-events-auto">
                <SlantedButton variant="blue" fullWidth size="lg" onClick={() => onNavigate('GAME')} className="!h-15 shadow-blue-900/50">
                    <div className="grid grid-rows-[1.5rem_2.5rem] items-center justify-center w-full h-full text-center px-0.5">
                        <div className="w-full h-full"><GameText text="PLAY" baseFontSize={1.1} className="font-black italic tracking-tighter uppercase opacity-70" /></div>
                        <div className="w-full h-full"><GameText text="LADDER" baseFontSize={1.3} maxLines={1} className="italic tracking-tighter font-black uppercase" /></div>
                    </div>
                </SlantedButton>
            </div>

            <div className="w-[11.5%] pointer-events-auto">
                <SlantedButton variant="blue" size="md" onClick={() => onNavigate('RANK')} className="w-full !h-10 shadow-blue-900/40">
                    <div className="grid grid-rows-[1rem_1.5rem] items-center justify-center w-full h-full text-center px-0.5 pt-0.5">
                        <div className="w-full h-full"><GameText text="RANK" baseFontSize={0.8} className="font-black italic tracking-tighter uppercase text-white opacity-60" /></div>
                        <div className="w-full h-full"><GameText text={user.rank.toString()} baseFontSize={1.4} className="text-white font-black italic tracking-tighter" /></div>
                    </div>
                </SlantedButton>
            </div>

            <style>{`
                .transform-style-3d { transform-style: preserve-3d; }
                .backface-hidden { backface-visibility: hidden; }
                .is-visually-center.deck-valid .drum-item-button > div:first-child { background: linear-gradient(to bottom, #059669, #064e3b) !important; border-color: #34d399 !important; box-shadow: 0 0.2rem 0 #064e3b, 0 0 20px rgba(16, 185, 129, 0.3) !important; }
                .is-visually-center.deck-invalid .drum-item-button > div:first-child { background: linear-gradient(to bottom, #dc2626, #7f1d1d) !important; border-color: #f87171 !important; box-shadow: 0 0.2rem 0 #7f1d1d, 0 0 20px rgba(239, 68, 68, 0.3) !important; }
                .is-visually-center { filter: grayscale(0) !important; }
            `}</style>
        </div>
    );
};

import React, { useState, useRef, useEffect } from 'react';
import { GameText } from './GameText';

type ButtonVariant = 'primary' | 'secondary' | 'success' | 'danger' | 'warning' | 'blue';

interface SlantedButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
    variant?: ButtonVariant;
    fullWidth?: boolean;
    size?: 'sm' | 'md' | 'lg';
    icon?: React.ReactNode;
    holdDuration?: number; 
    onHoldChange?: (isHolding: boolean) => void;
    onProgressChange?: (progress: number) => void;
}

export const SlantedButton: React.FC<SlantedButtonProps> = ({ 
    children, 
    variant = 'primary', 
    fullWidth = false,
    size = 'md',
    icon,
    className = '',
    holdDuration = 0,
    onHoldChange,
    onProgressChange,
    onClick,
    ...props 
}) => {
    const [progress, setProgress] = useState(0);
    const [isHolding, setIsHolding] = useState(false);
    const timerRef = useRef<number | null>(null);
    const startTimeRef = useRef<number>(0);

    const variants = {
        primary: "from-purple-600 to-purple-900 border-purple-400 shadow-[0_0.2rem_0_rgb(88,28,135)]",
        secondary: "from-slate-700 to-slate-900 border-slate-500 shadow-[0_0.2rem_0_rgb(15,23,42)]",
        success: "from-emerald-600 to-emerald-900 border-emerald-400 shadow-[0_0.2rem_0_rgb(6,78,59)]",
        danger: "from-red-600 to-red-900 border-red-400 shadow-[0_0.2rem_0_rgb(127,29,29)]",
        warning: "from-amber-600 to-amber-900 border-amber-400 shadow-[0_0.2rem_0_rgb(120,53,15)]",
        blue: "from-blue-600 to-blue-900 border-blue-400 shadow-[0_0.2rem_0_rgb(30,58,138)]",
    };

    const sizeConfigs = {
        sm: { height: "h-7", fontSize: 1.15, padding: "px-2" },
        md: { height: "h-10", fontSize: 1.25, padding: "px-4" },
        lg: { height: "h-15", fontSize: 1.35, padding: "px-3" }
    };

    const config = sizeConfigs[size];

    const startHold = (e: React.PointerEvent) => {
        if (!holdDuration || props.disabled) return;
        setIsHolding(true);
        onHoldChange?.(true);
        startTimeRef.current = Date.now();
        timerRef.current = window.setInterval(() => {
            const elapsed = Date.now() - startTimeRef.current;
            const p = Math.min((elapsed / holdDuration) * 100, 100);
            setProgress(p);
            onProgressChange?.(p);
            if (p >= 100) {
                if (timerRef.current) clearInterval(timerRef.current);
                timerRef.current = null;
                setProgress(100);
                onProgressChange?.(100);
                setTimeout(() => {
                    if (onClick) {
                        const sEvent = { clientX: e.clientX, clientY: e.clientY, target: e.target, currentTarget: e.currentTarget, type: 'click' } as any;
                        onClick(sEvent);
                    }
                    setIsHolding(false);
                    onHoldChange?.(false);
                    setProgress(0);
                    onProgressChange?.(0);
                }, 60);
            }
        }, 16);
    };

    const cancelHold = () => {
        if (timerRef.current) { clearInterval(timerRef.current); timerRef.current = null; }
        setIsHolding(false);
        onHoldChange?.(false);
        setProgress(0);
        onProgressChange?.(0);
    };

    useEffect(() => { return () => { if (timerRef.current) clearInterval(timerRef.current); }; }, []);

    const widthOverride = className.match(/w-\[?[\w.%]+\]?/)?.[0] || '';
    const widthClass = fullWidth ? 'w-full' : (widthOverride ? widthOverride : 'w-max');

    return (
        <div className={`relative group ${widthClass} ${config.height} ${props.disabled ? 'opacity-50 pointer-events-none' : ''}`}>
            <button 
                className={`w-full h-full relative z-10 active:translate-y-0.5 transition-all outline-none ${className}`}
                onPointerDown={holdDuration ? startHold : undefined}
                onPointerUp={holdDuration ? cancelHold : undefined}
                onPointerLeave={holdDuration ? cancelHold : undefined}
                onClick={holdDuration ? undefined : onClick}
                role="button"
                {...props}
            >
                <div className={`absolute inset-0 bg-gradient-to-b border rounded skew-x-[-10deg] transition-all duration-200 overflow-hidden ${variants[variant]}`}>
                    {holdDuration > 0 && (
                        <div className="absolute inset-y-0 left-0 bg-white/20 transition-all duration-75 ease-linear pointer-events-none" style={{ width: `${progress}%` }} />
                    )}
                </div>

                {/* 
                  DETERMINISTIC STACKING GRID 
                  All content is placed in a single 1fr cell.
                  This ensures standard centering for single-line text,
                  but allows multi-line children to define their own internal rows.
                */}
                <div className={`relative z-20 h-full pointer-events-none grid grid-cols-[auto_1fr] items-center ${children ? config.padding : 'px-0'}`}>
                    {icon && (
                        <div className="flex items-center justify-center pr-1.5 h-full">
                            {icon}
                        </div>
                    )}

                    <div className={`col-start-2 h-full w-full grid place-items-center transition-opacity ${isHolding ? 'opacity-40' : 'opacity-100'}`}>
                        {children && (
                            typeof children === 'string' || typeof children === 'number' ? (
                                <div className="w-full h-full">
                                    <GameText 
                                        text={children.toString()} 
                                        baseFontSize={config.fontSize} 
                                        maxScale={1.0}
                                        className="text-white font-black italic tracking-tighter uppercase drop-shadow-[0_2px_3px_rgba(0,0,0,0.8)]"
                                        minScale={0.3} 
                                    />
                                </div>
                            ) : (
                                <div className="w-full h-full flex items-center justify-center drop-shadow-[0_2px_3px_rgba(0,0,0,0.8)]">
                                    {children}
                                </div>
                            )
                        )}
                    </div>
                </div>
            </button>
        </div>
    );
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { ScreenKey } from '../../types';
import { useUser } from '../../contexts/UserContext';
import { SlantedButton } from '../ui/SlantedButton';
import { GameText } from '../ui/GameText';
import { audio } from '../../services/audio';
import { Portal } from '../ui/Portal';

interface HomeCommandBarProps {
    onNavigate: (s: ScreenKey) => void;
}

const getRelativeTimeString = (isoString: string) => {
    const date = new Date(isoString);
    const now = new Date();
    const diffInMs = now.getTime() - date.getTime();
    const diffInDays = Math.floor(diffInMs / (1000 * 60 * 60 * 24));
    if (diffInDays <= 0) return 'today';
    if (diffInDays === 1) return 'yesterday';
    if (diffInDays < 7) return `${diffInDays} days ago`;
    const diffInWeeks = Math.floor(diffInDays / 7);
    if (diffInWeeks === 1) return 'a week ago';
    if (diffInWeeks < 4) return `${diffInWeeks} weeks ago`;
    const diffInMonths = Math.floor(diffInDays / 30);
    if (diffInMonths === 1) return 'a month ago';
    if (diffInMonths < 12) return `${diffInMonths} months ago`;
    return 'a long time ago';
};

export const HomeCommandBar: React.FC<HomeCommandBarProps> = ({ onNavigate }) => {
    const { user, activeDeck, setActiveDeck } = useUser();
    const [isRollerOpen, setIsRollerOpen] = useState(false);

    const activeDeckId = user.activeDeckId;
    const activeDeckName = user.deckNames[activeDeckId] || 'UNTITLED';
    const isMainDeckValid = activeDeck.length === 12;

    const deckIds = Object.keys(user.decks).map(Number).sort((a, b) => a - b);
    const count = deckIds.length;
    const angleStep = 360 / count;
    const radius = 130;

    const drumRef = useRef<HTMLDivElement>(null);
    const itemsRef = useRef<(HTMLDivElement | null)[]>([]);
    const rotationRef = useRef((activeDeckId - 1) * angleStep);
    const velocityRef = useRef(0);
    const isDraggingRef = useRef(false);
    const lastPointerY = useRef(0);
    const lastTime = useRef(0);
    const requestRef = useRef<number | null>(null);

    const lastCenteredIndexRef = useRef<number>(activeDeckId - 1);
    const lastTickStepRef = useRef<number>(Math.round(rotationRef.current / angleStep));
    const lastAudioTimeRef = useRef<number>(0);
    const canPlayAudioRef = useRef<boolean>(true);

    const updateDom = useCallback((rot: number) => {
        if (!drumRef.current) return;
        drumRef.current.style.transform = `translate3d(0, 0, -${radius}px) rotateX(${rot}deg)`;
        let currentCenterI = -1;
        for (let i = 0; i < itemsRef.current.length; i++) {
            const item = itemsRef.current[i];
            if (!item) continue;
            const angle = -i * angleStep;
            let normalizedAngle = (angle + rot) % 360;
            if (normalizedAngle > 180) normalizedAngle -= 360;
            else if (normalizedAngle < -180) normalizedAngle += 360;
            const absAngle = Math.abs(normalizedAngle);
            if (absAngle < 110) {
                const distanceScale = 1 - (absAngle / 100) * 0.35;
                const opacity = 1 - (absAngle / 130);
                item.style.transform = `rotateX(${angle}deg) translate3d(0, 0, ${radius}px) scale(${distanceScale})`;
                item.style.opacity = Math.max(0.1, opacity).toString();
                item.style.visibility = 'visible';
                if (absAngle < (angleStep / 2)) currentCenterI = i;
            } else {
                if (item.style.visibility !== 'hidden') {
                    item.style.visibility = 'hidden';
                    item.style.opacity = '0';
                }
            }
        }
        if (currentCenterI !== -1 && currentCenterI !== lastCenteredIndexRef.current) {
            const prevItem = itemsRef.current[lastCenteredIndexRef.current];
            const nextItem = itemsRef.current[currentCenterI];
            if (prevItem) prevItem.classList.remove('is-visually-center');
            if (nextItem) nextItem.classList.add('is-visually-center');
            lastCenteredIndexRef.current = currentCenterI;
        }
        const currentStep = Math.round(rot / angleStep);
        if (currentStep !== lastTickStepRef.current) {
            const now = performance.now();
            const elapsed = now - lastAudioTimeRef.current;
            if (!isDraggingRef.current && elapsed > 1000) canPlayAudioRef.current = false;
            if (canPlayAudioRef.current && elapsed > 15) {
                audio.play('sfx_ui_click', 0.4);
                lastAudioTimeRef.current = now;
            }
            lastTickStepRef.current = currentStep;
        }
    }, [angleStep, radius]);

    const animate = useCallback(() => {
        if (isDraggingRef.current) return;
        velocityRef.current *= 0.96;
        rotationRef.current += velocityRef.current;
        if (Math.abs(velocityRef.current) < 0.4) {
            const targetIndex = Math.round(rotationRef.current / angleStep);
            const targetRotation = targetIndex * angleStep;
            const diff = targetRotation - rotationRef.current;
            rotationRef.current += diff * 0.5;
            if (Math.abs(diff) < 0.15) {
                rotationRef.current = targetRotation;
                velocityRef.current = 0;
                updateDom(rotationRef.current);
                const finalId = ((targetIndex % count + count) % count) + 1;
                if (finalId !== user.activeDeckId) setActiveDeck(finalId);
                return;
            }
        }
        updateDom(rotationRef.current);
        requestRef.current = requestAnimationFrame(animate);
    }, [angleStep, count, user.activeDeckId, setActiveDeck, updateDom]);

    const handlePointerDown = (e: React.PointerEvent) => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
        isDraggingRef.current = true;
        canPlayAudioRef.current = true;
        lastAudioTimeRef.current = performance.now();
        lastPointerY.current = e.clientY;
        lastTime.current = performance.now();
    };

    const handlePointerMove = (e: React.PointerEvent) => {
        if (!isDraggingRef.current) return;
        const now = performance.now();
        const deltaY = e.clientY - lastPointerY.current;
        const deltaTime = now - lastTime.current;
        const rotationDelta = -(deltaY / 100) * angleStep;
        rotationRef.current += rotationDelta;
        updateDom(rotationRef.current);
        if (deltaTime > 0) {
            const instantVelocity = rotationDelta / (deltaTime / 16.67);
            velocityRef.current = velocityRef.current * 0.25 + instantVelocity * 0.75;
        }
        lastPointerY.current = e.clientY;
        lastTime.current = now;
    };

    const handlePointerUp = () => {
        if (!isDraggingRef.current) return;
        isDraggingRef.current = false;
        requestRef.current = requestAnimationFrame(animate);
    };

    useEffect(() => {
        if (isRollerOpen) {
            const t = setTimeout(() => updateDom(rotationRef.current), 50);
            return () => clearTimeout(t);
        }
    }, [isRollerOpen, updateDom]);

    return (
        <div className="w-full flex items-end justify-center px-2 pb-3 gap-2 pointer-events-none relative h-16 overflow-visible">
            {isRollerOpen && (
                <Portal>
                    <div className="fixed inset-0 z-[600] pointer-events-auto bg-black/40 backdrop-blur-md flex flex-col items-center justify-center" onClick={() => setIsRollerOpen(false)} onPointerDown={handlePointerDown} onPointerMove={handlePointerMove} onPointerUp={handlePointerUp} onPointerLeave={handlePointerUp}>
                        <div className="w-full h-[32rem] perspective-[1500px] flex items-center justify-center select-none touch-none animate-pop overflow-visible">
                            <div ref={drumRef} className="relative w-64 h-24 transform-style-3d pointer-events-none will-change-transform" style={{ transform: `translate3d(0, 0, -${radius}px) rotateX(${rotationRef.current}deg)` }}>
                                {deckIds.map((id, i) => {
                                    const stats = user.deckStats[id];
                                    const dateStr = stats ? getRelativeTimeString(stats.lastModified) : 'some time ago';
                                    const isInitialCenter = user.activeDeckId === id;
                                    const isValid = (user.decks[id]?.length || 0) === 12;
                                    const statsText = `CQ: ${stats?.conquestWins || 0}/${stats?.conquestTotal || 0} - LD: ${stats?.ladderWins || 0}/${stats?.ladderLosses || 0}`;
                                    return (
                                        <div key={id} ref={el => itemsRef.current[i] = el} className={`absolute inset-0 backface-hidden transform-style-3d will-change-transform ${isInitialCenter ? 'is-visually-center' : ''} ${isValid ? 'deck-valid' : 'deck-invalid'}`} style={{ transform: `rotateX(${-i * angleStep}deg) translate3d(0, 0, ${radius}px)`, opacity: isInitialCenter ? 1 : 0.4, zIndex: i === lastCenteredIndexRef.current ? 50 : 10 }}>
                                            <SlantedButton variant="secondary" fullWidth size="lg" className="!h-full shadow-2xl drum-item-button">
                                                <div className="grid grid-rows-[1.8rem_1rem_0.8rem] items-center justify-center w-full h-full pointer-events-none px-4">
                                                    <div className="w-full h-full"><GameText text={user.deckNames[id] || 'UNTITLED'} baseFontSize={1.4} className="text-white font-black italic tracking-tighter uppercase" maxLines={1} /></div>
                                                    <div className="w-full h-full flex items-center justify-center opacity-90">
                                                        <GameText text={statsText} baseFontSize={0.7} maxLines={1} className="text-white font-bold italic tracking-tighter uppercase" />
                                                    </div>
                                                    <div className="w-full h-full opacity-50"><GameText text={`Changed ${dateStr}`} baseFontSize={0.6} className="lowercase italic font-black tracking-tighter" /></div>
                                                </div>
                                            </SlantedButton>
                                        </div>
                                    );
                                })}
                            </div>
                        </div>
                    </div>
                </Portal>
            )}

            <div className="w-[11.5%] pointer-events-auto">
                <SlantedButton variant="blue" size="md" onClick={() => onNavigate('HISTORY')} className="w-full !h-10 shadow-blue-900/40" icon={
                    <div className="flex items-center justify-center scale-90 drop-shadow-[0_2px_3px_rgba(0,0,0,0.8)]">
                        <svg className="w-6 h-6 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
                        </svg>
                    </div>
                } />
            </div>

            <div className="w-[20.5%] pointer-events-auto">
                <SlantedButton variant="blue" fullWidth size="lg" onClick={() => onNavigate('GAME')} className="!h-15 shadow-blue-900/50">
                    <div className="grid grid-rows-[1.2rem_2.2rem] items-center justify-center w-full h-full text-center px-0.5">
                        <div className="w-full h-full"><GameText text="PLAY" baseFontSize={1.1} className="font-black italic tracking-tighter uppercase opacity-70" /></div>
                        <div className="w-full h-full"><GameText text="CONQUEST" baseFontSize={1.3} maxLines={1} className="italic tracking-tighter font-black uppercase" /></div>
                    </div>
                </SlantedButton>
            </div>

            <div className="w-[20.5%] pointer-events-auto">
                <SlantedButton variant={isMainDeckValid ? 'success' : 'danger'} fullWidth size="lg" onClick={() => { setIsRollerOpen(!isRollerOpen); audio.playUiClick(); }} className={`!h-15 shadow-slate-900/40 relative z-[70] transition-transform ${isRollerOpen ? 'scale-105' : ''}`}>
                    <div className="grid grid-rows-[1.2rem_2.2rem] items-center justify-center w-full h-full text-center px-0.5">
                        <div className="flex items-center justify-center gap-1 w-full h-full">
                            <div className="w-max h-full"><GameText text="DECK" baseFontSize={1.1} className="font-black italic tracking-tighter uppercase opacity-70" /></div>
                            {!isMainDeckValid && <div className="w-1.5 h-1.5 rounded-full bg-amber-500 animate-pulse" />}
                        </div>
                        <div className="w-full h-full"><GameText text={activeDeckName} baseFontSize={1.15} maxLines={2} className="italic tracking-tighter leading-none font-black uppercase" /></div>
                    </div>
                </SlantedButton>
            </div>

            <div className="w-[20.5%] pointer-events-auto">
                <SlantedButton variant="blue" fullWidth size="lg" onClick={() => onNavigate('GAME')} className="!h-15 shadow-blue-900/50">
                    <div className="grid grid-rows-[1.2rem_2.2rem] items-center justify-center w-full h-full text-center px-0.5">
                        <div className="w-full h-full"><GameText text="PLAY" baseFontSize={1.1} className="font-black italic tracking-tighter uppercase opacity-70" /></div>
                        <div className="w-full h-full"><GameText text="LADDER" baseFontSize={1.3} maxLines={1} className="italic tracking-tighter font-black uppercase" /></div>
                    </div>
                </SlantedButton>
            </div>

            <div className="w-[11.5%] pointer-events-auto">
                <SlantedButton variant="blue" size="md" onClick={() => onNavigate('RANK')} className="w-full !h-10 shadow-blue-900/40">
                    <div className="grid grid-rows-[0.8rem_1.4rem] items-center justify-center w-full h-full text-center px-0.5 pt-0.5">
                        <div className="w-full h-full"><GameText text="RANK" baseFontSize={0.8} className="font-black italic tracking-tighter uppercase text-white opacity-60" /></div>
                        <div className="w-full h-full"><GameText text={user.rank.toString()} baseFontSize={1.4} className="text-white font-black italic tracking-tighter" /></div>
                    </div>
                </SlantedButton>
            </div>

            <style>{`
                .transform-style-3d { transform-style: preserve-3d; }
                .backface-hidden { backface-visibility: hidden; }
                .is-visually-center.deck-valid .drum-item-button > div:first-child { background: linear-gradient(to bottom, #059669, #064e3b) !important; border-color: #34d399 !important; box-shadow: 0 0.2rem 0 #064e3b, 0 0 20px rgba(16, 185, 129, 0.3) !important; }
                .is-visually-center.deck-invalid .drum-item-button > div:first-child { background: linear-gradient(to bottom, #dc2626, #7f1d1d) !important; border-color: #f87171 !important; box-shadow: 0 0.2rem 0 #7f1d1d, 0 0 20px rgba(239, 68, 68, 0.3) !important; }
                .is-visually-center { filter: grayscale(0) !important; }
            `}</style>
        </div>
    );
};

import { AUDIO_MANIFEST } from '../utils/assets';
import { CARDS, LOCATION_DEFS } from '../constants';
import { audio } from './audio';

/**
 * PRODUCTION-GRADE ASSET PIPELINE
 * Ensures images, audio, and CRITICAL typographic metrics are settled.
 */
export const preloadAssets = async (onProgress: (progress: number) => void) => {
  let loaded = 0;

  const imagesToLoad = [
    ...CARDS.map(c => c.imageUrl),
    ...LOCATION_DEFS.map(l => l.imageUrl),
  ];

  const audioKeys = Object.keys(AUDIO_MANIFEST);
  const totalAssets = imagesToLoad.length + audioKeys.length + 40; // Buffering for font iterations

  const updateProgress = (steps = 1) => {
    loaded += steps;
    const percentage = Math.min(100, Math.floor((loaded / totalAssets) * 100));
    onProgress(percentage);
  };

  // 1. Safety Timeout Gate
  const timeoutPromise = new Promise((_, reject) => 
    setTimeout(() => reject(new Error("Asset load timeout")), 12000)
  );

  const mainLoadTask = (async () => {
      // 2. Parallel Image Loading
      const imagePromises = imagesToLoad.map(src => {
        return new Promise<void>((resolve) => {
          const img = new Image();
          img.src = src;
          img.onload = () => { updateProgress(); resolve(); };
          img.onerror = () => { updateProgress(); resolve(); }; 
        });
      });

      // 3. Audio Init
      audio.init();
      updateProgress(audioKeys.length);

      // 4. METRIC VERIFICATION LOOP (Defeats Font-Snap)
      if ('fonts' in document) {
        try {
            // Wait for API to acknowledge presence
            await (document as any).fonts.ready;
            updateProgress(5);

            // Create a metric verification target using our most complex font weight
            const tester = document.createElement('div');
            tester.style.cssText = 'position:fixed;top:-9999px;font-family:"IBM Plex Sans";font-weight:700;font-style:italic;font-size:100px;visibility:hidden;white-space:nowrap;';
            tester.innerText = 'GALACTIC_SNAP_METRIC_LOCK';
            document.body.appendChild(tester);

            let stableFrames = 0;
            let lastWidth = 0;

            // Poll for stability. Browsers often report "ready" before layout engine has swapped glyphs.
            for (let i = 0; i < 40; i++) {
                const currentWidth = tester.getBoundingClientRect().width;

                // If width is > 0 and hasn't changed for several frames, we have physical glyph data
                if (currentWidth > 0 && Math.abs(currentWidth - lastWidth) < 0.1) {
                    stableFrames++;
                } else {
                    stableFrames = 0;
                }

                lastWidth = currentWidth;
                updateProgress(0.5);

                if (stableFrames >= 8) break; // Require 8 consecutive frames of stability
                await new Promise(r => requestAnimationFrame(r));
            }

            document.body.removeChild(tester);
            document.body.classList.add('fonts-ready');
            updateProgress(10);
        } catch (e) {
            console.warn("Typography calibration bypassed:", e);
            document.body.classList.add('fonts-ready');
        }
      } else {
          document.body.classList.add('fonts-ready');
      }

      await Promise.all([...imagePromises]);
  })();

  try {
      await Promise.race([mainLoadTask, timeoutPromise]);
  } catch (err) {
      console.warn("Preload safety gate triggered. Some assets may stream in late.");
      document.body.classList.add('fonts-ready');
  }

  onProgress(100);
};

import React, { useState, useEffect, useRef, useLayoutEffect } from 'react';
import { AppShell } from './components/ui/AppShell';
import { LoadingScreen } from './components/screens/LoadingScreen';
import { LoginScreen } from './components/screens/LoginScreen';
import { NavigationBar } from './components/ui/NavigationBar';
import { InspectorOverlay } from './components/InspectorOverlay';
import { preloadAssets } from './services/assetLoader';
import { audio } from './services/audio';
import { api } from './services/api';
import { useSpatialNavigation } from './hooks/useSpatialNavigation';
import { ScreenKey, UserProfile } from './types';
import { UserProvider } from './contexts/UserContext';

export default function App() {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [loadingProgress, setLoadingProgress] = useState(0);
  const [isAppReady, setIsAppReady] = useState(false); 
  const [userProfile, setUserProfile] = useState<UserProfile | null>(null);

  const gridRef = useRef<HTMLDivElement>(null);
  const musicInitializedRef = useRef(false);

  const { 
      activeScreen, 
      prevScreen, 
      isTransitioning, 
      containerStyle, 
      navigateTo, 
      resetToMenu, 
      WORLDS 
  } = useSpatialNavigation();

  // 1. BOOTSTRAP & CALIBRATION
  useEffect(() => {
    const initApp = async () => {
      try {
          const profile = await api.getProfile('u1');
          setUserProfile(profile);

          // PHASE 1: Preload Raw Assets & Verify Metrics
          await preloadAssets((progress) => setLoadingProgress(progress));

          // PHASE 2: Force Synchronous Layout Reflow
          // Now that assetLoader has applied .fonts-ready, measurements are valid.
          if (gridRef.current) {
              const screens = gridRef.current.children;
              for (let i = 0; i < screens.length; i++) {
                  const s = screens[i] as HTMLElement;
                  void s.offsetHeight; 
                  const rect = s.getBoundingClientRect();
                  console.debug(`Warmed up screen ${i}: ${rect.width}x${rect.height}`);
              }
          }

          // PHASE 3: Triple-Frame Buffer
          // Final flush to ensure GPU paints are consistent
          requestAnimationFrame(() => {
              requestAnimationFrame(() => {
                  requestAnimationFrame(() => {
                      setIsAppReady(true);
                  });
              });
          });

      } catch (err) {
          console.error("Critical System Failure:", err);
          setIsAppReady(true);
      }
    };
    initApp();
  }, []);

  // 2. AUDIO MANAGEMENT
  useEffect(() => {
      if (!isLoggedIn || !isAppReady) return;
      const targetBgm = activeScreen === 'GAME' ? 'bgm_game' : 'bgm_menu';
      audio.playBgm(targetBgm);
  }, [activeScreen, isLoggedIn, isAppReady]);

  const handleLogin = async () => {
      await audio.init(); 
      audio.playUiClick();
      setIsLoggedIn(true);
      musicInitializedRef.current = true;
  };

  const handleLogout = () => {
      audio.playUiClick();
      audio.stopBgm();
      setIsLoggedIn(false);
      musicInitializedRef.current = false;
      resetToMenu();
  };

  const handleStartGame = () => navigateTo('GAME');

  if (!userProfile) {
      return (
          <AppShell>
              <LoadingScreen progress={loadingProgress} isVisible={true} />
          </AppShell>
      );
  }

  return (
    <UserProvider initialUser={userProfile}>
        <AppShell>
            <LoadingScreen 
                progress={loadingProgress} 
                isVisible={!isAppReady} 
            />

            <div 
                className={`w-full h-full relative transition-opacity duration-1000 ${isAppReady ? 'opacity-100' : 'opacity-0'}`}
                aria-hidden={!isAppReady}
            >

                {!isLoggedIn && (
                    <div className="absolute inset-0 z-[100] bg-slate-950">
                        <LoginScreen onLogin={handleLogin} />
                    </div>
                )}

                <InspectorOverlay />

                <div 
                    ref={gridRef}
                    className="w-full h-full relative transition-transform duration-500 ease-[cubic-bezier(0.22,1,0.36,1)] will-change-transform"
                    style={containerStyle}
                >
                    {(Object.keys(WORLDS) as ScreenKey[]).map((key) => {
                        const config = WORLDS[key];
                        const activeConfig = WORLDS[activeScreen];

                        const dx = Math.abs(config.x - activeConfig.x);
                        const dy = Math.abs(config.y - activeConfig.y);
                        const isNeighbor = dx <= 1 && dy <= 1;
                        const isPrev = key === prevScreen;

                        const shouldRender = !isAppReady || isNeighbor || isPrev;

                        if (!shouldRender) return null;

                        const ScreenComponent = config.component;
                        const isActive = key === activeScreen;

                        return (
                            <div 
                                key={key} 
                                className={`absolute w-full h-full top-0 left-0 overflow-hidden transition-opacity duration-300 ${!isActive && !isTransitioning ? 'pointer-events-none invisible opacity-0' : 'pointer-events-auto visible opacity-100'}`}
                                style={{ 
                                    transform: `translate3d(${config.x * 100}%, ${config.y * 100}%, 0)`,
                                }}
                                data-screen-key={key}
                            >
                                <ScreenComponent 
                                    activeScreen={activeScreen} 
                                    onNavigate={navigateTo} 
                                    onExit={() => navigateTo('MENU')}
                                    onBack={() => navigateTo('MENU')}
                                    onStartGame={handleStartGame}
                                    onLogout={handleLogout}
                                />
                            </div>
                        );
                    })}
                </div>

                {isLoggedIn && activeScreen !== 'GAME' && (
                    <NavigationBar activeScreen={activeScreen} onNavigate={navigateTo} />
