import React from 'react';

interface GameTextProps {
  text: string;
  className?: string;
  baseFontSize: number;
  minScale?: number; // Deprecated
  maxScale?: number; // Deprecated
  maxLines?: number; // Deprecated
}

/**
 * ULTRA-SNAPPY GAMETEXT
 * Replaces expensive measurement loops with a pure CSS scale heuristic.
 * This ensures 60fps transitions regardless of how many buttons are on screen.
 */
export const GameText: React.FC<GameTextProps> = ({ 
  text, 
  className = '', 
  baseFontSize,
}) => {
  if (!text) return null;

  // Heuristic: Shrink text if it exceeds standard button capacity (approx 12 chars)
  // This is O(1) and requires zero DOM access.
  const charLimit = 12;
  const scale = text.length > charLimit 
    ? Math.max(0.65, 1 - (text.length - charLimit) * 0.03) 
    : 1;

  return (
    <div 
        className={`w-full h-full flex justify-center items-center overflow-hidden pointer-events-none select-none ${className}`}
        style={{ fontSize: `${baseFontSize}rem` }}
    >
      <div 
        style={{ 
          transform: scale !== 1 ? `scale(${scale})` : 'none',
          transformOrigin: 'center center'
        }} 
        className="whitespace-nowrap leading-none transition-transform duration-200"
      >
        {text}
      </div>
    </div>
  );
};

