import { audio } from './services/audio';
import { api } from './services/api';
import { useSpatialNavigation } from './hooks/useSpatialNavigation';
import { ScreenKey, UserProfile } from './types';
import { UserProvider } from './contexts/UserContext';

export default function App() {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [loadingProgress, setLoadingProgress] = useState(0);
  const [isAppReady, setIsAppReady] = useState(false); 
  const [userProfile, setUserProfile] = useState<UserProfile | null>(null);

  const gridRef = useRef<HTMLDivElement>(null);

  const { 
      activeScreen, 
      prevScreen, 
      isTransitioning, 
      containerStyle, 
      navigateTo, 
      resetToMenu, 
      WORLDS 
  } = useSpatialNavigation();

  // 1. BOOTSTRAP
  useEffect(() => {
    const initApp = async () => {
      try {
          const profile = await api.getProfile('u1');
          setUserProfile(profile);

          await preloadAssets((progress) => setLoadingProgress(progress));

          // Double RAF ensures browser has parsed CSS and initialized fonts
          requestAnimationFrame(() => {
              requestAnimationFrame(() => {
                  setIsAppReady(true);
              });
          });

      } catch (err) {
          console.error("Critical System Failure:", err);
          setIsAppReady(true);
      }
    };
    initApp();
  }, []);

  // 2. AUDIO MANAGEMENT
  useEffect(() => {
      if (!isLoggedIn || !isAppReady) return;
      const targetBgm = activeScreen === 'GAME' ? 'bgm_game' : 'bgm_menu';
      audio.playBgm(targetBgm);
  }, [activeScreen, isLoggedIn, isAppReady]);

  // 3. PERSISTENT RENDER SET
  // This memo determines which screens are in the DOM.
  // Screens are rendered if they are: Persistent, Active, or immediate neighbors of the Active/Prev screen.

  // FIX: activeConfig and prevConfig must be available in both useMemo and the render loop below.
  const activeConfig = WORLDS[activeScreen];
  const prevConfig = prevScreen ? WORLDS[prevScreen] : null;

  const renderedScreens = useMemo(() => {
      const keys = Object.keys(WORLDS) as ScreenKey[];

      return keys.filter(key => {
          // While preloading, we render everything once to prime the DOM
          if (!isAppReady) return true;

          const config = WORLDS[key];

          // Rule A: Screen is flagged as permanent
          if (config.isPersistent) return true;

          // Rule B: Current neighbors
          const dx = Math.abs(config.x - activeConfig.x);
          const dy = Math.abs(config.y - activeConfig.y);
          if (dx <= 1 && dy <= 1) return true;

          // Rule C: Outgoing neighbors (keep-alive during slide)
          if (isTransitioning && prevConfig) {
              const pdx = Math.abs(config.x - prevConfig.x);
              const pdy = Math.abs(config.y - prevConfig.y);
              return pdx <= 1 && pdy <= 1;
          }

          return false;
      });
  }, [activeScreen, prevScreen, isTransitioning, isAppReady, WORLDS, activeConfig, prevConfig]);

  const handleLogin = async () => {
      await audio.init(); 
      audio.playUiClick();
      setIsLoggedIn(true);
  };

  const handleLogout = () => {
      audio.playUiClick();
      audio.stopBgm();
      setIsLoggedIn(false);
      resetToMenu();
  };

  const handleStartGame = () => navigateTo('GAME');

  if (!userProfile) {
      return (
          <AppShell>
              <LoadingScreen progress={loadingProgress} isVisible={true} />
          </AppShell>
      );
  }

  return (
    <UserProvider initialUser={userProfile}>
        <AppShell>
            <LoadingScreen 
                progress={loadingProgress} 
                isVisible={!isAppReady} 
            />

            <div 
                className={`w-full h-full relative transition-opacity duration-700 ${isAppReady ? 'opacity-100' : 'opacity-0'}`}
                aria-hidden={!isAppReady}
            >
                {!isLoggedIn && (
                    <div className="absolute inset-0 z-[100] bg-slate-950">
                        <LoginScreen onLogin={handleLogin} />
                    </div>
                )}

                <InspectorOverlay />

                <div 
                    ref={gridRef}
                    className="w-full h-full relative transition-transform duration-500 ease-[cubic-bezier(0.22,1,0.36,1)] will-change-transform"
                    style={containerStyle}
                >
                    {renderedScreens.map((key) => {
                        const config = WORLDS[key];
                        const ScreenComponent = config.component;

                        // VISIBILITY GATE
                        // A screen is 'Active' if it is the current target OR the neighbor during transition
                        const isActive = key === activeScreen;
                        // FIX: activeConfig and prevConfig are now defined in the component scope and accessible here.
                        const activeNeighbor = isTransitioning && (
                             Math.abs(config.x - activeConfig.x) <= 1 && 
                             Math.abs(config.y - activeConfig.y) <= 1
                        );
                        const prevNeighbor = isTransitioning && prevConfig && (
                             Math.abs(config.x - prevConfig.x) <= 1 && 
                             Math.abs(config.y - prevConfig.y) <= 1
                        );

                        const isVisible = isActive || activeNeighbor || prevNeighbor;

                        return (
                            <div 
                                key={key} 
                                className={`absolute w-full h-full top-0 left-0 overflow-hidden transition-opacity duration-300 ${!isVisible ? 'pointer-events-none invisible opacity-0' : 'pointer-events-auto visible opacity-100'}`}
                                style={{ 
                                    transform: `translate3d(${config.x * 100}%, ${config.y * 100}%, 0)`,
                                }}
                            >
                                <ScreenComponent 
                                    activeScreen={activeScreen} 
                                    onNavigate={navigateTo} 
                                    onExit={() => navigateTo('MENU')}
                                    onBack={() => navigateTo('MENU')}
                                    onStartGame={handleStartGame}
                                    onLogout={handleLogout}
                                />
                            </div>
                        );
                    })}
                </div>

                {isLoggedIn && activeScreen !== 'GAME' && (
                    <NavigationBar activeScreen={activeScreen} onNavigate={navigateTo} />
                )}
            </div>
        </AppShell>
    </UserProvider>
  );
}

import React, { useState, useLayoutEffect, useRef, useEffect } from 'react';

interface GameTextProps {
  text: string;
  className?: string;
  baseFontSize: number; // in rem
  maxScale?: number;
  minScale?: number;
}

/**
 * HIGH-PRECISION MEASURED GAMETEXT
 * Calculates exact fit-to-width scaling using DOM metrics.
 * Now high-performance because screens are persistent and state is cached.
 */
export const GameText: React.FC<GameTextProps> = ({ 
  text, 
  className = '', 
  baseFontSize,
  maxScale = 1.0,
  minScale = 0.4
}) => {
  const [scale, setScale] = useState(1);
  const containerRef = useRef<HTMLDivElement>(null);
  const textRef = useRef<HTMLDivElement>(null);

  // Use useLayoutEffect to measure BEFORE the browser paints
  // This prevents the "flash" of giant text
  useLayoutEffect(() => {
    const measure = () => {
      if (!containerRef.current || !textRef.current) return;

      const containerWidth = containerRef.current.offsetWidth;
      const textWidth = textRef.current.scrollWidth;

      if (containerWidth > 0 && textWidth > 0) {
        // Calculate the ratio needed to fit
        // We add a tiny 0.98 multiplier for safety margins
        const targetScale = (containerWidth / textWidth) * 0.98;

        // Clamp between our defined limits
        const finalScale = Math.min(maxScale, Math.max(minScale, targetScale));

        setScale(finalScale);
      }
    };

    // Initial measurement
    measure();

    // Re-measure if the container size changes (e.g. window resize)
    if (typeof ResizeObserver !== 'undefined' && containerRef.current) {
        const observer = new ResizeObserver(measure);
        observer.observe(containerRef.current);
        return () => observer.disconnect();
    }
  }, [text, baseFontSize, maxScale, minScale]);

  return (
    <div 
        ref={containerRef}
        className={`w-full h-full flex justify-center items-center overflow-hidden pointer-events-none select-none ${className}`}
        style={{ fontSize: `${baseFontSize}rem` }}
    >
      <div 
        ref={textRef}
        style={{ 
          transform: scale < 1 ? `scale(${scale})` : 'none',
          transformOrigin: 'center center',
          display: 'inline-block'
        }} 
        className="whitespace-nowrap leading-none transition-transform duration-300 ease-out"
      >
        {text}
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { GameText } from './GameText';

type ButtonVariant = 'primary' | 'secondary' | 'success' | 'danger' | 'warning' | 'blue';

interface SlantedButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
    variant?: ButtonVariant;
    fullWidth?: boolean;
    size?: 'sm' | 'md' | 'lg';
    icon?: React.ReactNode;
    holdDuration?: number; 
    onHoldChange?: (isHolding: boolean) => void;
    onProgressChange?: (progress: number) => void;
}

export const SlantedButton: React.FC<SlantedButtonProps> = ({ 
    children, 
    variant = 'primary', 
    fullWidth = false,
    size = 'md',
    icon,
    className = '',
    holdDuration = 0,
    onHoldChange,
    onProgressChange,
    onClick,
    ...props 
}) => {
    const [progress, setProgress] = useState(0);
    const [isHolding, setIsHolding] = useState(false);
    const timerRef = useRef<number | null>(null);
    const startTimeRef = useRef<number>(0);

    const variants = {
        primary: "from-purple-600 to-purple-900 border-purple-400 shadow-[0_0.2rem_0_rgb(88,28,135)]",
        secondary: "from-slate-700 to-slate-900 border-slate-500 shadow-[0_0.2rem_0_rgb(15,23,42)]",
        success: "from-emerald-600 to-emerald-900 border-emerald-400 shadow-[0_0.2rem_0_rgb(6,78,59)]",
        danger: "from-red-600 to-red-900 border-red-400 shadow-[0_0.2rem_0_rgb(127,29,29)]",
        warning: "from-amber-600 to-amber-900 border-amber-400 shadow-[0_0.2rem_0_rgb(120,53,15)]",
        blue: "from-blue-600 to-blue-900 border-blue-400 shadow-[0_0.2rem_0_rgb(30,58,138)]",
    };

    const sizeConfigs = {
        sm: { height: "h-7", fontSize: 1.15, padding: "px-2" },
        md: { height: "h-10", fontSize: 1.25, padding: "px-4" },
        lg: { height: "h-15", fontSize: 1.35, padding: "px-3" }
    };

    const config = sizeConfigs[size];

    const startHold = (e: React.PointerEvent) => {
        if (!holdDuration || props.disabled) return;
        setIsHolding(true);
        onHoldChange?.(true);
        startTimeRef.current = Date.now();
        timerRef.current = window.setInterval(() => {
            const elapsed = Date.now() - startTimeRef.current;
            const p = Math.min((elapsed / holdDuration) * 100, 100);
            setProgress(p);
            onProgressChange?.(p);
            if (p >= 100) {
                if (timerRef.current) clearInterval(timerRef.current);
                timerRef.current = null;
                setProgress(100);
                onProgressChange?.(100);
                setTimeout(() => {
                    if (onClick) {
                        const sEvent = { clientX: e.clientX, clientY: e.clientY, target: e.target, currentTarget: e.currentTarget, type: 'click' } as any;
                        onClick(sEvent);
                    }
                    setIsHolding(false);
                    onHoldChange?.(false);
                    setProgress(0);
                    onProgressChange?.(0);
                }, 60);
            }
        }, 16);
    };

    const cancelHold = () => {
        if (timerRef.current) { clearInterval(timerRef.current); timerRef.current = null; }
        setIsHolding(false);
        onHoldChange?.(false);
        setProgress(0);
        onProgressChange?.(0);
    };

    useEffect(() => { return () => { if (timerRef.current) clearInterval(timerRef.current); }; }, []);

    const widthOverride = className.match(/w-\[?[\w.%]+\]?/)?.[0] || '';
    const widthClass = fullWidth ? 'w-full' : (widthOverride ? widthOverride : 'w-max');

    return (
        <div className={`relative group ${widthClass} ${config.height} ${props.disabled ? 'opacity-50 pointer-events-none' : ''}`}>
            <button 
                className={`w-full h-full relative z-10 active:translate-y-0.5 transition-all outline-none ${className}`}
                onPointerDown={holdDuration ? startHold : undefined}
                onPointerUp={holdDuration ? cancelHold : undefined}
                onPointerLeave={holdDuration ? cancelHold : undefined}
                onClick={holdDuration ? undefined : onClick}
                role="button"
                {...props}
            >
                <div className={`absolute inset-0 bg-gradient-to-b border rounded skew-x-[-10deg] transition-all duration-200 overflow-hidden ${variants[variant]}`}>
                    {holdDuration > 0 && (
                        <div className="absolute inset-y-0 left-0 bg-white/20 transition-all duration-75 ease-linear pointer-events-none" style={{ width: `${progress}%` }} />
                    )}
                </div>

                <div className={`relative z-20 h-full pointer-events-none grid grid-cols-[auto_1fr] items-center ${children ? config.padding : 'px-0'}`}>
                    {icon && (
                        <div className="flex items-center justify-center pr-1.5 h-full">
                            {icon}
                        </div>
                    )}

                    <div className={`col-start-2 h-full w-full grid place-items-center transition-opacity ${isHolding ? 'opacity-40' : 'opacity-100'}`}>
                        {children && (
                            typeof children === 'string' || typeof children === 'number' ? (
                                <div className="w-full h-full">
                                    <GameText 
                                        text={children.toString()} 
                                        baseFontSize={config.fontSize} 
                                        className="text-white font-black italic tracking-tighter uppercase drop-shadow-[0_2px_3px_rgba(0,0,0,0.8)]"
                                    />
                                </div>
                            ) : (
                                <div className="w-full h-full flex items-center justify-center drop-shadow-[0_2px_3px_rgba(0,0,0,0.8)]">
                                    {children}
                                </div>
                            )
                        )}
                    </div>
                </div>
            </button>
        </div>
    );
};

import React, { useState, useRef, useEffect } from 'react';
import { GameText } from './GameText';

type ButtonVariant = 'primary' | 'secondary' | 'success' | 'danger' | 'warning' | 'blue';

interface HexButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
    variant?: ButtonVariant;
    fullWidth?: boolean;
    size?: 'sm' | 'md' | 'lg';
    icon?: React.ReactNode;
    holdDuration?: number; 
    onHoldChange?: (isHolding: boolean) => void;
    onProgressChange?: (progress: number) => void;
}

export const HexButton: React.FC<HexButtonProps> = ({ 
    children, 
    variant = 'primary', 
    fullWidth = false,
    size = 'md',
    icon,
    className = '',
    holdDuration = 0,
    onHoldChange,
    onProgressChange,
    onClick,
    ...props 
}) => {
    const [progress, setProgress] = useState(0);
    const [isHolding, setIsHolding] = useState(false);
    const timerRef = useRef<number | null>(null);
    const startTimeRef = useRef<number>(0);

    const variants = {
        primary: "from-purple-600 to-purple-900 border-purple-400 shadow-[0_0.2rem_0_rgb(88,28,135)]",
        secondary: "from-slate-700 to-slate-900 border-slate-500 shadow-[0_0.2rem_0_rgb(15,23,42)]",
        success: "from-emerald-600 to-emerald-900 border-emerald-400 shadow-[0_0.2rem_0_rgb(6,78,59)]",
        danger: "from-red-600 to-red-900 border-red-400 shadow-[0_0.2rem_0_rgb(127,29,29)]",
        warning: "from-amber-600 to-amber-900 border-amber-400 shadow-[0_0.2rem_0_rgb(120,53,15)]",
        blue: "from-blue-600 to-blue-900 border-blue-400 shadow-[0_0.2rem_0_rgb(30,58,138)]",
    };

    const sizeConfigs = {
        sm: { height: "h-7", fontSize: 0.8, padding: "px-4" },
        md: { height: "h-10", fontSize: 1.0, padding: "px-6" },
        lg: { height: "h-14", fontSize: 1.2, padding: "px-8" }
    };

    const config = sizeConfigs[size];

    const startHold = (e: React.PointerEvent) => {
        if (!holdDuration || props.disabled) return;

        setIsHolding(true);
        onHoldChange?.(true);
        startTimeRef.current = Date.now();

        timerRef.current = window.setInterval(() => {
            const elapsed = Date.now() - startTimeRef.current;
            const p = Math.min((elapsed / holdDuration) * 100, 100);
            setProgress(p);
            onProgressChange?.(p);

            if (p >= 100) {
                if (timerRef.current) clearInterval(timerRef.current);
                timerRef.current = null;

                setProgress(100);
                onProgressChange?.(100);

                setTimeout(() => {
                    if (onClick) {
                        const syntheticEvent = { 
                            clientX: e.clientX,
                            clientY: e.clientY,
                            target: e.target,
                            currentTarget: e.currentTarget,
                            type: 'click',
                            bubbles: true,
                            cancelable: true,
                            nativeEvent: e.nativeEvent,
                        } as unknown as React.MouseEvent<HTMLButtonElement>;
                        onClick(syntheticEvent);
                    }
                    setIsHolding(false);
                    onHoldChange?.(false);
                    setProgress(0);
                    onProgressChange?.(0);
                }, 60);
            }
        }, 16);
    };

    const cancelHold = () => {
        if (timerRef.current) {
            clearInterval(timerRef.current);
            timerRef.current = null;
        }
        setIsHolding(false);
        onHoldChange?.(false);
        setProgress(0);
        onProgressChange?.(0);
    };

    useEffect(() => {
        return () => {
            if (timerRef.current) clearInterval(timerRef.current);
        };
    }, []);

    const widthClass = fullWidth ? 'w-full' : 'w-max min-w-[3.5rem]';

    return (
        <div className={`relative group ${widthClass} ${config.height} ${props.disabled ? 'opacity-50 pointer-events-none' : ''}`}>
            <button 
                className={`w-full h-full relative z-10 active:translate-y-0.5 transition-all outline-none ${className}`}
                onPointerDown={holdDuration ? startHold : undefined}
                onPointerUp={holdDuration ? cancelHold : undefined}
                onPointerLeave={holdDuration ? cancelHold : undefined}
                onClick={holdDuration ? undefined : onClick}
                role="button"
                aria-busy={isHolding}
                {...props}
            >
                <div className={`
                    absolute inset-0 bg-gradient-to-b border rounded skew-x-[-10deg] 
                    group-hover:brightness-110 transition-all duration-200 overflow-hidden
                    ${variants[variant]}
                `}>
                    {holdDuration > 0 && (
                        <div 
                            className="absolute inset-y-0 left-0 bg-white/20 transition-all duration-75 ease-linear pointer-events-none"
                            style={{ width: `${progress}%` }}
                        />
                    )}
                </div>

                <div className={`relative z-20 skew-x-[-10deg] ${config.padding} flex items-center justify-center h-full pointer-events-none`}>
                    <div className={`w-full h-full flex items-center justify-center gap-2 transition-opacity ${isHolding ? 'opacity-40' : 'opacity-100'}`}>
                        {icon && (
                            <div className="shrink-0 flex items-center justify-center">
                                {icon}
                            </div>
                        )}

                        {typeof children === 'string' ? (
                            <div className="flex-1 h-full min-w-0">
                                <GameText 
                                    text={children} 
                                    baseFontSize={config.fontSize} 
                                    className="text-white drop-shadow-md"
                                />
                            </div>
                        ) : (
                            <div className="font-black text-white italic tracking-tight uppercase drop-shadow-md flex items-center gap-1 h-full w-full" style={{ fontSize: `${config.fontSize}rem` }}>
                                {children}
                            </div>
                        )}
                    </div>
                </div>
            </button>
        </div>
    );
};

import React, { useState, useLayoutEffect, useRef } from 'react';

interface GameTextProps {
  text: string;
  className?: string;
  baseFontSize: number; // in rem
  maxScale?: number;
  minScale?: number;
  skewFactor?: number; // Adjustment for slanted buttons (e.g. 0.85)
}

/**
 * BULLETPROOF MEASURED GAMETEXT
 * Optimized for persistent screens. Handles the "zero-width" mount state 
 * by retrying measurement until the container is visible in the DOM.
 */
export const GameText: React.FC<GameTextProps> = React.memo(({ 
  text, 
  className = '', 
  baseFontSize,
  maxScale = 1.0,
  minScale = 0.35,
  skewFactor = 1.0 
}) => {
  const [scale, setScale] = useState(1);
  const containerRef = useRef<HTMLDivElement>(null);
  const textRef = useRef<HTMLDivElement>(null);

  useLayoutEffect(() => {
    let rafId: number;

    const measure = () => {
      if (!containerRef.current || !textRef.current) return;

      const containerWidth = containerRef.current.clientWidth * skewFactor;
      const textWidth = textRef.current.scrollWidth;

      // If screen is persistent but hidden (visibility: hidden), width is 0.
      // We retry until it's actually laid out.
      if (containerWidth <= 0) {
        rafId = requestAnimationFrame(measure);
        return;
      }

      if (textWidth > 0) {
        // Safe 96% margin to account for font-weight and italic overhangs
        const targetScale = (containerWidth / textWidth) * 0.96;
        const finalScale = Math.min(maxScale, Math.max(minScale, targetScale));
        setScale(finalScale);
      }
    };

    measure();

    if (typeof ResizeObserver !== 'undefined' && containerRef.current) {
        const observer = new ResizeObserver(measure);
        observer.observe(containerRef.current);
        return () => {
            observer.disconnect();
            cancelAnimationFrame(rafId);
        };
    }
  }, [text, baseFontSize, maxScale, minScale, skewFactor]);

  return (
    <div 
        ref={containerRef}
        className={`w-full h-full flex justify-center items-center overflow-visible pointer-events-none select-none ${className}`}
        style={{ fontSize: `${baseFontSize}rem` }}
    >
      <div 
        ref={textRef}
        style={{ 
          transform: scale < 1 ? `scale(${scale})` : 'none',
          transformOrigin: 'center center',
          display: 'inline-block'
        }} 
        className="whitespace-nowrap leading-none transition-transform duration-300 ease-out will-change-transform"
      >
        {text}
      </div>
    </div>
  );
});

