                            className="italic tracking-tighter font-black uppercase leading-none" 
                        />
                        {!isMainDeckValid && (
                            <div className="absolute top-2 right-2 w-2 h-2 rounded-full bg-amber-500 animate-pulse shadow-[0_0_8px_rgba(245,158,11,0.6)]" />
