            <div className="w-[23.5%] pointer-events-auto">
                <SlantedButton variant="blue" fullWidth size="lg" onClick={() => onNavigate('GAME')} className="shadow-blue-900/50">
                    <GameText 
                        text={`PLAY\nCONQUEST`} 
                        baseFontSize={1.75} 
                        skewFactor={0.95}
                        maxLines={2} 
                        className="italic tracking-tighter font-black uppercase" 
                    />
                </SlantedButton>
            </div>

            <div className="w-[23.5%] pointer-events-auto">
                <SlantedButton variant={isMainDeckValid ? 'success' : 'danger'} fullWidth size="lg" onClick={() => { setIsRollerOpen(!isRollerOpen); audio.playUiClick(); }} className={`shadow-slate-900/40 relative z-[70] transition-transform ${isRollerOpen ? 'scale-105' : ''}`}>
                    <div className="w-full h-full relative">
                        <GameText 
                            text={`DECK\n${activeDeckName}`} 
                            baseFontSize={1.65} 
                            skewFactor={0.95}
                            maxLines={2} 
                            className="italic tracking-tighter font-black uppercase leading-none" 
                        />
                        {!isMainDeckValid && (
                            <div className="absolute top-2 right-2 w-2 h-2 rounded-full bg-amber-500 animate-pulse shadow-[0_0_8px_rgba(245,158,11,0.6)]" />
