import React, { useState, useLayoutEffect, useRef } from 'react';

interface GameTextProps {
  text: string;
  className?: string;
  baseFontSize: number; // in rem
  maxScale?: number;
  minScale?: number;
  skewFactor?: number; 
  maxLines?: number;
}

/**
 * HIGH-PRECISION TEXT SCALING ENGINE
 * Optimized for centering and deterministic fitting.
 */
export const GameText: React.FC<GameTextProps> = React.memo(({ 
  text, 
  className = '', 
  baseFontSize,
  maxScale = 1.0,
  minScale = 0.2,
  skewFactor = 1.0,
  maxLines = 1
}) => {
  const [scale, setScale] = useState(1);
  const containerRef = useRef<HTMLDivElement>(null);
  const textRef = useRef<HTMLDivElement>(null);

  useLayoutEffect(() => {
    let rafId: number;

    const measure = () => {
      const container = containerRef.current;
      const textEl = textRef.current;
      if (!container || !textEl) return;

      const containerW = container.clientWidth * skewFactor;
      const containerH = container.clientHeight;

      if (containerW <= 0 || containerH <= 0) {
        rafId = requestAnimationFrame(measure);
        return;
      }

      // MEASUREMENT CLONE - EXACT DUPLICATE OF RENDERING STYLE
      const clone = document.createElement('div');
      clone.style.position = 'absolute';
      clone.style.visibility = 'hidden';
      clone.style.left = '-9999px';
      clone.style.top = '-9999px';
      clone.style.fontSize = `${baseFontSize}rem`;
      const computedStyle = getComputedStyle(textEl);
      clone.style.fontFamily = computedStyle.fontFamily;
      clone.style.fontWeight = computedStyle.fontWeight;
      clone.style.fontStyle = computedStyle.fontStyle;
      clone.style.letterSpacing = computedStyle.letterSpacing;
      clone.style.textTransform = computedStyle.textTransform;
      clone.style.lineHeight = '0.8'; // Tightened for better multi-line fitting
      clone.style.textAlign = 'center';

      const isMultiLine = maxLines > 1;

      // Measure natural unwrapped width
      clone.style.whiteSpace = 'nowrap';
      clone.style.width = 'auto';
      clone.innerText = text.replace(/\n/g, ' '); 
      document.body.appendChild(clone);
      const naturalUnwrappedW = clone.scrollWidth;

      // Calculate a "Wrap Budget"
      const idealWrapWidth = isMultiLine ? Math.max(naturalUnwrappedW / maxLines, containerW * 0.8) : naturalUnwrappedW;

      // Measure height with wrapping if applicable
      if (isMultiLine) {
          clone.style.whiteSpace = 'pre-line';
          clone.style.width = `${idealWrapWidth}px`;
          clone.innerText = text;
      }
      const wrappedH = clone.scrollHeight;
      const wrappedW = isMultiLine ? clone.scrollWidth : naturalUnwrappedW;

      document.body.removeChild(clone);

      // SCALING CALCULATION
      const scaleW = containerW / wrappedW;
      const scaleH = containerH / wrappedH;
      const targetScale = Math.min(scaleW, scaleH);

      const finalScale = Math.min(maxScale, Math.max(minScale, targetScale));
      setScale(finalScale);
    };

    measure();

    if (typeof ResizeObserver !== 'undefined' && containerRef.current) {
        const observer = new ResizeObserver(measure);
        observer.observe(containerRef.current);
        return () => {
            observer.disconnect();
            cancelAnimationFrame(rafId);
        };
    }
  }, [text, baseFontSize, maxScale, minScale, skewFactor, maxLines]);

  return (
    <div 
        ref={containerRef}
        className={`w-full h-full flex justify-center items-center overflow-hidden pointer-events-none select-none ${className}`}
        style={{ fontSize: `${baseFontSize}rem` }}
    >
      <div 
        ref={textRef}
        style={{ 
          transform: scale < 1 ? `scale(${scale})` : 'none',
          transformOrigin: 'center center',
          display: 'flex', 
          flexDirection: 'column',
          alignItems: 'center',
          justifyContent: 'center',
          width: 'max-content',
          lineHeight: 0.8, // Tightened for better multi-line fitting
          textAlign: 'center'
        }} 
        className="transition-transform duration-300 ease-out will-change-transform"
      >
        {text.split('\n').map((line, i) => (
            <span key={i} className="block whitespace-nowrap">{line}</span>
        ))}
      </div>
    </div>
  );
});

import React, { useState, useRef, useEffect } from 'react';
import { GameText } from './GameText';

type ButtonVariant = 'primary' | 'secondary' | 'success' | 'danger' | 'warning' | 'blue';

interface SlantedButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
    variant?: ButtonVariant;
    fullWidth?: boolean;
    size?: 'sm' | 'md' | 'lg';
    icon?: React.ReactNode;
    holdDuration?: number; 
    onHoldChange?: (isHolding: boolean) => void;
    onProgressChange?: (progress: number) => void;
}

export const SlantedButton: React.FC<SlantedButtonProps> = ({ 
    children, 
    variant = 'primary', 
    fullWidth = false,
    size = 'md',
    icon,
    className = '',
    holdDuration = 0,
    onHoldChange,
    onProgressChange,
    onClick,
    ...props 
}) => {
    const [progress, setProgress] = useState(0);
    const [isHolding, setIsHolding] = useState(false);
    const timerRef = useRef<number | null>(null);
    const startTimeRef = useRef<number>(0);

    const variants = {
        primary: "from-purple-600 to-purple-900 border-purple-400 shadow-[0_0.2rem_0_rgb(88,28,135)]",
        secondary: "from-slate-700 to-slate-900 border-slate-500 shadow-[0_0.2rem_0_rgb(15,23,42)]",
        success: "from-emerald-600 to-emerald-900 border-emerald-400 shadow-[0_0.2rem_0_rgb(6,78,59)]",
        danger: "from-red-600 to-red-900 border-red-400 shadow-[0_0.2rem_0_rgb(127,29,29)]",
        warning: "from-amber-600 to-amber-900 border-amber-400 shadow-[0_0.2rem_0_rgb(120,53,15)]",
        blue: "from-blue-600 to-blue-900 border-blue-400 shadow-[0_0.2rem_0_rgb(30,58,138)]",
    };

    const sizeConfigs = {
        sm: { height: "h-8", fontSize: 1.15, padding: "px-2" },
        md: { height: "h-10", fontSize: 1.25, padding: "px-2" },
        lg: { height: "h-16", fontSize: 1.5, padding: "px-2" }
    };

    const config = sizeConfigs[size];

    const startHold = (e: React.PointerEvent) => {
        if (!holdDuration || props.disabled) return;
        setIsHolding(true);
        onHoldChange?.(true);
        startTimeRef.current = Date.now();
        timerRef.current = window.setInterval(() => {
            const elapsed = Date.now() - startTimeRef.current;
            const p = Math.min((elapsed / holdDuration) * 100, 100);
            setProgress(p);
            onProgressChange?.(p);
            if (p >= 100) {
                if (timerRef.current) clearInterval(timerRef.current);
                timerRef.current = null;
                setProgress(100);
                onProgressChange?.(100);
                setTimeout(() => {
                    if (onClick) {
                        const sEvent = { clientX: e.clientX, clientY: e.clientY, target: e.target, currentTarget: e.currentTarget, type: 'click' } as any;
                        onClick(sEvent);
                    }
                    setIsHolding(false);
                    onHoldChange?.(false);
                    setProgress(0);
                    onProgressChange?.(0);
                }, 60);
            }
        }, 16);
    };

    const cancelHold = () => {
        if (timerRef.current) { clearInterval(timerRef.current); timerRef.current = null; }
        setIsHolding(false);
        onHoldChange?.(false);
        setProgress(0);
        onProgressChange?.(0);
    };

    useEffect(() => { return () => { if (timerRef.current) clearInterval(timerRef.current); }; }, []);

    const hasExplicitWidth = className.includes('w-') || className.includes('max-w-');
    const widthClass = fullWidth ? 'w-full' : (hasExplicitWidth ? '' : 'w-max');

    const containerJustify = (icon && children) ? 'justify-start' : 'justify-center';

    return (
        <div className={`relative group ${widthClass} ${config.height} ${props.disabled ? 'opacity-50 pointer-events-none' : ''} ${className}`}>
            <button 
                className={`w-full h-full relative z-10 active:translate-y-0.5 transition-all outline-none`}
                onPointerDown={holdDuration ? startHold : undefined}
                onPointerUp={holdDuration ? cancelHold : undefined}
                onPointerLeave={holdDuration ? cancelHold : undefined}
                onClick={holdDuration ? undefined : onClick}
                role="button"
                {...props}
            >
                {/* SLANTED BACKGROUND - Skew reduced to -9deg */}
                <div className={`absolute inset-0 bg-gradient-to-b border rounded skew-x-[-9deg] transition-all duration-200 overflow-hidden ${variants[variant]}`}>
                    {holdDuration > 0 && (
                        <div className="absolute inset-y-0 left-0 bg-white/20 transition-all duration-75 ease-linear pointer-events-none" style={{ width: `${progress}%` }} />
                    )}
                </div>

                {/* SLANTED CONTENT WRAPPER - Skew reduced to -9deg */}
                <div className={`relative z-20 h-full w-full pointer-events-none flex items-center ${containerJustify} skew-x-[-9deg] ${children ? config.padding : 'px-1'}`}>
                    <div className={`flex items-center ${containerJustify} gap-1.5 w-full h-full transition-opacity ${isHolding ? 'opacity-40' : 'opacity-100'}`}>
                        {icon && (
                            <div className="shrink-0 flex items-center justify-center drop-shadow-[0_2px_3px_rgba(0,0,0,0.8)]">
                                {icon}
                            </div>
                        )}

                        {children && (
                            <div className="flex-1 h-full min-w-0 flex items-center justify-center">
                                {typeof children === 'string' || typeof children === 'number' ? (
                                    <GameText 
                                        text={children.toString()} 
                                        baseFontSize={config.fontSize} 
                                        skewFactor={0.92} 
                                        maxLines={2} 
                                        className="text-white font-black italic tracking-tighter uppercase drop-shadow-[0_2px_3px_rgba(0,0,0,0.8)]"
                                    />
                                ) : (
                                    <div className="flex items-center justify-center drop-shadow-[0_2px_3px_rgba(0,0,0,0.8)] w-full h-full">
                                        {children}
                                    </div>
                                )}
                            </div>
                        )}
                    </div>
                </div>
            </button>
        </div>
    );
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { ScreenKey } from '../../types';
import { useUser } from '../../contexts/UserContext';
import { SlantedButton } from '../ui/SlantedButton';
import { audio } from '../../services/audio';
import { Portal } from '../ui/Portal';
import { GameText } from '../ui/GameText';

interface HomeCommandBarProps {
    onNavigate: (screen: ScreenKey) => void;
    isActive: boolean;
}

const getRelativeTimeString = (isoString: string) => {
    const date = new Date(isoString);
    const now = new Date();
    const diffInMs = now.getTime() - date.getTime();
    const diffInDays = Math.floor(diffInMs / (1000 * 60 * 60 * 24));
    if (diffInDays <= 0) return 'today';
    if (diffInDays === 1) return 'yesterday';
    if (diffInDays < 7) return `${diffInDays} days ago`;
    return 'a long time ago';
};

export const HomeCommandBar: React.FC<HomeCommandBarProps> = ({ onNavigate, isActive }) => {
    const { user, activeDeck, setActiveDeck } = useUser();
    const [isRollerOpen, setIsRollerOpen] = useState(false);

    useEffect(() => {
        if (!isActive && isRollerOpen) {
            setIsRollerOpen(false);
        }
    }, [isActive, isRollerOpen]);

    const activeDeckId = user.activeDeckId;
    const activeDeckName = user.deckNames[activeDeckId] || 'UNTITLED';
    const isMainDeckValid = activeDeck.length === 12;

    const deckIds = Object.keys(user.decks).map(Number).sort((a, b) => a - b);
    const count = deckIds.length;
    const angleStep = 360 / count;
    const radius = 130;

    const drumRef = useRef<HTMLDivElement>(null);
    const itemsRef = useRef<(HTMLDivElement | null)[]>([]);
    const rotationRef = useRef((activeDeckId - 1) * angleStep);
    const velocityRef = useRef(0);
    const isDraggingRef = useRef(false);
    const lastPointerY = useRef(0);
    const lastTime = useRef(0);
    const requestRef = useRef<number | null>(null);

    const lastCenteredIndexRef = useRef<number>(activeDeckId - 1);
    const lastTickStepRef = useRef<number>(Math.round(rotationRef.current / angleStep));
    const lastAudioTimeRef = useRef<number>(0);
    const canPlayAudioRef = useRef<boolean>(true);

    const updateDom = useCallback((rot: number) => {
        if (!drumRef.current) return;
        drumRef.current.style.transform = `translate3d(0, 0, -${radius}px) rotateX(${rot}deg)`;
        let currentCenterI = -1;
        for (let i = 0; i < itemsRef.current.length; i++) {
            const item = itemsRef.current[i];
            if (!item) continue;
            const angle = -i * angleStep;
            let normalizedAngle = (angle + rot) % 360;
            if (normalizedAngle > 180) normalizedAngle -= 360;
            else if (normalizedAngle < -180) normalizedAngle += 360;
            const absAngle = Math.abs(normalizedAngle);
            if (absAngle < 110) {
                const distanceScale = 1 - (absAngle / 100) * 0.35;
                const opacity = 1 - (absAngle / 130);
                item.style.transform = `rotateX(${angle}deg) translate3d(0, 0, ${radius}px) scale(${distanceScale})`;
                item.style.opacity = Math.max(0.1, opacity).toString();
                item.style.visibility = 'visible';
                if (absAngle < (angleStep / 2)) currentCenterI = i;
            } else {
                if (item.style.visibility !== 'hidden') {
                    item.style.visibility = 'hidden';
                    item.style.opacity = '0';
                }
            }
        }
        if (currentCenterI !== -1 && currentCenterI !== lastCenteredIndexRef.current) {
            const prevItem = itemsRef.current[lastCenteredIndexRef.current];
            const nextItem = itemsRef.current[currentCenterI];
            if (prevItem) prevItem.classList.remove('is-visually-center');
            if (nextItem) nextItem.classList.add('is-visually-center');
            lastCenteredIndexRef.current = currentCenterI;
        }
        const currentStep = Math.round(rot / angleStep);
        if (currentStep !== lastTickStepRef.current) {
            const now = performance.now();
            const elapsed = now - lastAudioTimeRef.current;
            if (!isDraggingRef.current && elapsed > 1000) canPlayAudioRef.current = false;
            if (canPlayAudioRef.current && elapsed > 15) {
                audio.play('sfx_ui_click', 0.4);
                lastAudioTimeRef.current = now;
            }
            lastTickStepRef.current = currentStep;
        }
    }, [angleStep, radius]);

    const animate = useCallback(() => {
        if (isDraggingRef.current) return;
        velocityRef.current *= 0.96;
        rotationRef.current += velocityRef.current;
        if (Math.abs(velocityRef.current) < 0.4) {
            const targetIndex = Math.round(rotationRef.current / angleStep);
            const targetRotation = targetIndex * angleStep;
            const diff = targetRotation - rotationRef.current;
            rotationRef.current += diff * 0.5;
            if (Math.abs(diff) < 0.15) {
                rotationRef.current = targetRotation;
                velocityRef.current = 0;
                updateDom(rotationRef.current);
                const finalId = ((targetIndex % count + count) % count) + 1;
                if (finalId !== user.activeDeckId) setActiveDeck(finalId);
                return;
            }
        }
        updateDom(rotationRef.current);
        requestRef.current = requestAnimationFrame(animate);
    }, [angleStep, count, user.activeDeckId, setActiveDeck, updateDom]);

    const handlePointerDown = (e: React.PointerEvent) => {
        if (requestRef.current) cancelAnimationFrame(requestRef.current);
        isDraggingRef.current = true;
        canPlayAudioRef.current = true;
        lastAudioTimeRef.current = performance.now();
        lastPointerY.current = e.clientY;
        lastTime.current = performance.now();
    };

    const handlePointerMove = (e: React.PointerEvent) => {
        if (!isDraggingRef.current) return;
        const now = performance.now();
        const deltaY = e.clientY - lastPointerY.current;
        const deltaTime = now - lastTime.current;
        const rotationDelta = -(deltaY / 100) * angleStep;
        rotationRef.current += rotationDelta;
        updateDom(rotationRef.current);
        if (deltaTime > 0) {
            const instantVelocity = rotationDelta / (deltaTime / 16.67);
            velocityRef.current = velocityRef.current * 0.25 + instantVelocity * 0.75;
        }
        lastPointerY.current = e.clientY;
        lastTime.current = now;
    };

    const handlePointerUp = () => {
        if (!isDraggingRef.current) return;
        isDraggingRef.current = false;
        requestRef.current = requestAnimationFrame(animate);
    };

    useEffect(() => {
        if (isRollerOpen) {
            const t = setTimeout(() => updateDom(rotationRef.current), 50);
            return () => clearTimeout(t);
        }
    }, [isRollerOpen, updateDom]);

    return (
        <div className="w-full h-full grid grid-cols-[0.8fr_2.2fr_2.4fr_2.2fr_0.8fr] items-end px-1 pb-3 gap-1 pointer-events-none relative overflow-visible">
            {isRollerOpen && (
                <Portal>
                    <div className="fixed inset-0 z-[600] pointer-events-auto bg-black/40 backdrop-blur-md flex flex-col items-center justify-center" onClick={() => setIsRollerOpen(false)} onPointerDown={handlePointerDown} onPointerMove={handlePointerMove} onPointerUp={handlePointerUp} onPointerLeave={handlePointerUp}>
                        <div className="w-full h-[32rem] perspective-[1500px] flex items-center justify-center select-none touch-none animate-pop overflow-visible">
                            <div ref={drumRef} className="relative w-64 h-24 transform-style-3d pointer-events-none will-change-transform" style={{ transform: `translate3d(0, 0, -${radius}px) rotateX(${rotationRef.current}deg)` }}>
                                {deckIds.map((id, i) => {
                                    const stats = user.deckStats[id];
                                    const dateStr = stats ? getRelativeTimeString(stats.lastModified) : 'some time ago';
                                    const isInitialCenter = user.activeDeckId === id;
                                    const isValid = (user.decks[id]?.length || 0) === 12;
                                    const statsText = `CQ: ${stats?.conquestWins || 0}/${stats?.conquestTotal || 0} - LD: ${stats?.ladderWins || 0}/${stats?.ladderLosses || 0}`;
                                    return (
                                        <div key={id} ref={el => itemsRef.current[i] = el} className={`absolute inset-0 backface-hidden transform-style-3d will-change-transform ${isInitialCenter ? 'is-visually-center' : ''} ${isValid ? 'deck-valid' : 'deck-invalid'}`} style={{ transform: `rotateX(${-i * angleStep}deg) translate3d(0, 0, ${radius}px)`, opacity: isInitialCenter ? 1 : 0.4, zIndex: i === lastCenteredIndexRef.current ? 50 : 10 }}>
                                            <SlantedButton variant="secondary" fullWidth size="lg" className="!h-full shadow-2xl drum-item-button">
                                                <div className="flex flex-col items-stretch justify-center w-full h-full pointer-events-none px-4 py-2">
                                                    <div className="flex-[3] w-full min-h-0">
                                                        <GameText text={user.deckNames[id] || 'UNTITLED'} baseFontSize={1.4} className="text-white font-black italic tracking-tighter uppercase" maxLines={2} />
                                                    </div>
                                                    <div className="flex-[2] w-full min-h-0 flex items-center justify-center opacity-90">
                                                        <GameText text={statsText} baseFontSize={0.7} maxLines={1} className="text-white font-bold italic tracking-tighter uppercase" />
                                                    </div>
                                                    <div className="flex-1 w-full min-h-0 opacity-50">
                                                        <GameText text={`Changed ${dateStr}`} baseFontSize={0.6} className="lowercase italic font-black tracking-tighter" />
                                                    </div>
                                                </div>
                                            </SlantedButton>
                                        </div>
                                    );
                                })}
                            </div>
                        </div>
                    </div>
                </Portal>
            )}

            <div className="pointer-events-auto">
                <SlantedButton variant="blue" size="md" onClick={() => onNavigate('HISTORY')} className="w-full shadow-blue-900/40" icon={
                    <svg className="w-5 h-5 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
                    </svg>
                } />
            </div>

            <div className="pointer-events-auto">
                <SlantedButton 
                    variant="blue" 
                    fullWidth 
                    size="lg" 
                    onClick={() => onNavigate('GAME')} 
                    className="shadow-blue-900/50"
                >
                    {`PLAY\nCONQUEST`}
                </SlantedButton>
            </div>

            <div className="pointer-events-auto relative z-[70]">
                <SlantedButton 
                    variant={isMainDeckValid ? 'success' : 'danger'} 
                    fullWidth 
                    size="lg" 
                    onClick={() => onNavigate('DECK')} 
                    className="shadow-slate-900/40 transition-transform"
                    icon={!isMainDeckValid ? <div className="w-2 h-2 rounded-full bg-amber-500 animate-pulse shadow-[0_0_8px_rgba(245,158,11,0.6)]" /> : undefined}
                >
                    {`DECK\n${activeDeckName}`}
                </SlantedButton>
            </div>

            <div className="pointer-events-auto">
                <SlantedButton 
                    variant="blue" 
                    fullWidth 
                    size="lg" 
                    onClick={() => onNavigate('GAME')} 
                    className="shadow-blue-900/50"
                >
                    {`PLAY\nLADDER`}
                </SlantedButton>
            </div>

            <div className="pointer-events-auto">
                <SlantedButton 
                    variant="blue" 
                    size="md" 
                    onClick={() => onNavigate('RANK')} 
                    className="w-full shadow-blue-900/40"
                >
                    {`RANK\n${user.rank}`}
                </SlantedButton>
            </div>

            <style>{`
                .transform-style-3d { transform-style: preserve-3d; }
                .backface-hidden { backface-visibility: hidden; }
                .is-visually-center.deck-valid .drum-item-button > div:first-child { background: linear-gradient(to bottom, #059669, #064e3b) !important; border-color: #34d399 !important; box-shadow: 0 0.2rem 0 #064e3b, 0 0 20px rgba(16, 185, 129, 0.3) !important; }
                .is-visually-center.deck-invalid .drum-item-button > div:first-child { background: linear-gradient(to bottom, #dc2626, #7f1d1d) !important; border-color: #f87171 !important; box-shadow: 0 0.2rem 0 #7f1d1d, 0 0 20px rgba(239, 68, 68, 0.3) !important; }
                .is-visually-center { filter: grayscale(0) !important; }
            `}</style>
        </div>
    );
};

import React, { useState, useRef, useEffect } from 'react';
import { GameText } from './GameText';

type ButtonVariant = 'primary' | 'secondary' | 'success' | 'danger' | 'warning' | 'blue';

interface SlantedButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
