import React, { useState, useEffect, useCallback, useRef } from 'react';
import { CardDefinition } from '../types';
import { useUser } from '../contexts/UserContext';

export interface CollectionDragState {
  card: CardDefinition;
  origin: 'archive' | 'vault';
  startPos: { x: number; y: number };
  currentPos: { x: number; y: number };
  offset: { x: number; y: number };
  rect: DOMRect;
  active: boolean;
}

interface UseCollectionDragProps {
  onAdd: (id: string) => void;
  onRemove: (id: string) => void;
  vaultRef: React.RefObject<HTMLElement>;
  archiveRef: React.RefObject<HTMLElement>;
}

// Gesture Constants
const DRAG_MOVE_THRESHOLD = 15; // Pixels moved before locking into drag
const PICKUP_DELAY = 180;        // Long-press duration for card pickup

export const useCollectionDrag = ({ onAdd, onRemove, vaultRef, archiveRef }: UseCollectionDragProps) => {
    const { user, inspect } = useUser();
    const [dragState, setDragState] = useState<CollectionDragState | null>(null);

    const stateRef = useRef({
        isDragging: false,
        isIntentLocked: false, 
        startPos: { x: 0, y: 0 },
        lastValidPos: { x: 0, y: 0 },
        hasCard: false,
    });

    const dragTargetRef = useRef<HTMLElement | null>(null);
    const pickupTimerRef = useRef<number | null>(null);

    const handlePointerDown = useCallback((
        e: React.PointerEvent, 
        card: CardDefinition | null,
        origin: 'archive' | 'vault'
    ) => {
        if (e.button !== 0 || !card) return;

        const target = e.currentTarget as HTMLElement;
        dragTargetRef.current = target;

        const rect = target.getBoundingClientRect();
        const startPos = { x: e.clientX, y: e.clientY };

        const isOwned = user.collection.includes(card.id);
        const inDeck = user.decks[user.activeDeckId]?.includes(card.id);
        const canDrag = origin === 'vault' || (isOwned && !inDeck);

        stateRef.current = {
            isDragging: false,
            isIntentLocked: false,
            startPos,
            lastValidPos: startPos,
            hasCard: true
        };

        setDragState({
            card,
            origin,
            active: false,
            startPos,
            currentPos: startPos,
            rect,
            offset: { x: e.clientX - rect.left, y: e.clientY - rect.top },
        });

        if (canDrag) {
            // Start the "Pickup" timer
            pickupTimerRef.current = window.setTimeout(() => {
                stateRef.current.isIntentLocked = true;
                // If the user is still holding and hasn't scrolled far, activate drag
                setDragState(prev => prev ? { ...prev, active: true } : null);
                // Lock pointer to this element so we don't lose the drag during fast moves
                try { target.setPointerCapture(e.pointerId); } catch(err) {}
            }, PICKUP_DELAY);
        }
    }, [user]);

    useEffect(() => {
        if (!dragState) return;

        const handlePointerMove = (e: PointerEvent) => {
            const g = stateRef.current;
            const deltaX = e.clientX - g.startPos.x;
            const deltaY = e.clientY - g.startPos.y;
            const moveDist = Math.hypot(deltaX, deltaY);

            g.lastValidPos = { x: e.clientX, y: e.clientY };

            // If we move too much before the pickup delay, cancel the pickup
            // (User is likely trying to scroll)
            if (!g.isIntentLocked && moveDist > DRAG_MOVE_THRESHOLD) {
                if (pickupTimerRef.current) {
                    clearTimeout(pickupTimerRef.current);
                    pickupTimerRef.current = null;
                }
            }

            if (dragState.active) {
                // Once dragging, we consume the events
                if (e.cancelable) e.preventDefault();
                setDragState(prev => prev ? { ...prev, currentPos: { x: e.clientX, y: e.clientY } } : null);
            }
        };

        const handlePointerUp = (e: PointerEvent) => {
            if (pickupTimerRef.current) clearTimeout(pickupTimerRef.current);

            if (dragTargetRef.current) {
                try { dragTargetRef.current.releasePointerCapture(e.pointerId); } catch (err) {}
                dragTargetRef.current = null;
            }

            const g = stateRef.current;
            const endX = e.type === 'pointercancel' ? g.lastValidPos.x : e.clientX;
            const endY = e.type === 'pointercancel' ? g.lastValidPos.y : e.clientY;
            const moveDist = Math.hypot(endX - g.startPos.x, endY - g.startPos.y);

            const isInside = (ref: React.RefObject<HTMLElement>, x: number, y: number) => {
                if (!ref.current) return false;
                const rect = ref.current.getBoundingClientRect();
                return x >= rect.left && x <= rect.right && y >= rect.top && y <= rect.bottom;
            };

            if (dragState.active) {
                // Handle drop logic
                if (dragState.origin === 'archive' && isInside(vaultRef, endX, endY)) {
                    onAdd(dragState.card.id);
                } else if (dragState.origin === 'vault' && isInside(archiveRef, endX, endY)) {
                    onRemove(dragState.card.id);
                }
            } else if (moveDist < DRAG_MOVE_THRESHOLD) {
                // Pure Tap logic: Inspect the card
                inspect(dragState.card);
            }

            setDragState(null);
            g.isDragging = false;
            g.isIntentLocked = false;
        };

        window.addEventListener('pointermove', handlePointerMove, { passive: false });
        window.addEventListener('pointerup', handlePointerUp);
        window.addEventListener('pointercancel', handlePointerUp);

        return () => {
            window.removeEventListener('pointermove', handlePointerMove);
            window.removeEventListener('pointerup', handlePointerUp);
            window.removeEventListener('pointercancel', handlePointerUp);
            if (pickupTimerRef.current) clearTimeout(pickupTimerRef.current);
        };
    }, [dragState, inspect, onAdd, onRemove, vaultRef, archiveRef]);

    return { dragState, handlePointerDown };
};

import React, { useMemo } from 'react';
import { CARDS } from '../../constants';
import { Card } from '../Card';
import { CardDefinition } from '../../types';
import { useUser } from '../../contexts/UserContext';

interface CollectionGridProps {
    scrollRef: React.RefObject<HTMLDivElement>;
    ownedIds: string[];
    activeDeckIds: string[];
    draggingCardId?: string;
    onPointerDown: (e: React.PointerEvent, card: CardDefinition | null) => void;
}

export const CollectionGrid: React.FC<CollectionGridProps> = ({ 
    scrollRef, ownedIds, activeDeckIds, draggingCardId, onPointerDown 
}) => {
    const { collectionSort, collectionFilterSearch, collectionFilterTags } = useUser();

    const filteredAndSortedCards = useMemo(() => {
        let results = [...CARDS];

        if (collectionFilterSearch) {
            const query = collectionFilterSearch.toLowerCase();
            results = results.filter(c => 
                c.name.toLowerCase().includes(query) || 
                c.baseText.toLowerCase().includes(query)
            );
        }

        if (collectionFilterTags.length > 0) {
            results = results.filter(c => {
                return collectionFilterTags.some(tag => {
                    if (tag === 'None') return c.tags.length === 0;
                    return c.tags.includes(tag);
                });
            });
        }

        return results.sort((a, b) => {
            const aOwned = ownedIds.includes(a.id);
            const bOwned = ownedIds.includes(b.id);
            if (aOwned !== bOwned) return aOwned ? -1 : 1;

            if (collectionSort === 'Cost') return a.baseCost - b.baseCost;
            if (collectionSort === 'Power') return b.basePower - a.basePower;
            if (collectionSort === 'Newest') {
                const aIdx = CARDS.findIndex(c => c.id === a.id);
                const bIdx = CARDS.findIndex(c => c.id === b.id);
                return bIdx - aIdx;
            }
            return a.name.localeCompare(b.name);
        });
    }, [ownedIds, collectionSort, collectionFilterSearch, collectionFilterTags]);

    return (
        <div className="w-full h-full flex flex-col">
            {/* 
                REFACTORED: Switched overflow-hidden to overflow-y-auto for native scrolling.
                Switched touch-none to touch-pan-y to allow vertical scroll gestures 
                while intercepting pointer events for long-press drag.
            */}
            <div 
                ref={scrollRef} 
                className="flex-1 overflow-y-auto overflow-x-hidden px-2.5 pt-2 pb-52 touch-pan-y select-none scroll-smooth"
            >
                 {filteredAndSortedCards.length === 0 ? (
                     <div className="w-full py-20 flex flex-col items-center justify-center text-slate-700 pointer-events-none">
                         <svg className="w-12 h-12 mb-2 opacity-20" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                         <span className="text-[0.6rem] font-black uppercase tracking-widest">No matching cards</span>
                     </div>
                 ) : (
                     <div className="grid grid-cols-5 gap-x-1.5 gap-y-2.5 justify-items-center">
                         {filteredAndSortedCards.map((def) => {
                             const isOwned = ownedIds.includes(def.id);
                             const inDeck = activeDeckIds.includes(def.id);
                             const isDragging = draggingCardId === def.id;

                             let stateClasses = '';
                             if (isDragging) {
                                 stateClasses = 'opacity-0';
                             } else if (!isOwned) {
                                 stateClasses = 'opacity-40 grayscale scale-95';
                             } else if (inDeck) {
                                 stateClasses = 'opacity-50 grayscale'; 
                             } else {
                                 stateClasses = 'hover:scale-105'; 
                             }

                             return (
                                 <div 
                                    key={def.id} 
                                    className={`relative transition-all duration-300 rounded-md w-full flex justify-center ${stateClasses}`}
                                    onPointerDown={(e) => {
                                        // We don't stop propagation here so the container can still 
                                        // potentially handle gestures, but the hook uses the capture API.
                                        onPointerDown(e, def);
                                    }}
                                    onContextMenu={(e) => e.preventDefault()}
                                 >
                                     <div className="w-full aspect-[5/7] rounded-md transition-all duration-300 cursor-grab active:cursor-grabbing">
                                         <Card 
                                            card={def} 
                                            size="xs" 
                                            variant="default" 
                                         />
                                     </div>
                                 </div>
                             );
                         })}
                     </div>
                 )}

                 <div className="h-12 w-full flex items-center justify-center mt-12 mb-8 pointer-events-none">
                     <div className="text-[0.55rem] text-slate-800 font-black uppercase tracking-[0.5em]">Terminal Archive End</div>
                 </div>
            </div>
        </div>
    );
}

import React, { useState, useCallback, useMemo, useRef, useEffect } from 'react';
import { StandardHeader } from '../ui/StandardHeader';
