import React, { useState, useEffect, useCallback, useRef } from 'react';
import { CardDefinition } from '../types';
import { useUser } from '../contexts/UserContext';

export interface CollectionDragState {
  card: CardDefinition;
  origin: 'archive' | 'vault';
  startPos: { x: number; y: number };
  currentPos: { x: number; y: number };
  offset: { x: number; y: number };
  rect: DOMRect;
  active: boolean;
}

interface UseCollectionDragProps {
  onAdd: (id: string) => void;
  onRemove: (id: string) => void;
  scrollRef: React.RefObject<HTMLElement>;
}

// Physics Constants for Premium Feel
const DRAG_THRESHOLD = 8;
const SCROLL_THRESHOLD = 4;
const PICKUP_DELAY = 120; 
const FRICTION = 0.96; 
const MIN_VELOCITY = 0.2;

export const useCollectionDrag = ({ onAdd, onRemove, scrollRef }: UseCollectionDragProps) => {
    const { user, inspect } = useUser();
    const [dragState, setDragState] = useState<CollectionDragState | null>(null);

    // Internal refs for high-frequency updates without React re-render overhead
    const gestureRef = useRef({
        isScrolling: false,
        isDragging: false,
        startPos: { x: 0, y: 0 },
        startScrollTop: 0,
        hasCard: false,
        lastY: 0,
        lastTime: 0,
        velocity: 0,
        samples: [] as { dy: number, dt: number }[]
    });

    const inertiaFrameRef = useRef<number | null>(null);
    const dragTargetRef = useRef<HTMLElement | null>(null);
    const pickupTimerRef = useRef<number | null>(null);

    const runInertia = useCallback(() => {
        if (!scrollRef.current) return;

        const g = gestureRef.current;
        const el = scrollRef.current;

        el.scrollTop -= g.velocity;
        g.velocity *= FRICTION;

        // Boundary safety
        if (el.scrollTop <= 0 || el.scrollTop >= el.scrollHeight - el.clientHeight) {
            g.velocity = 0;
        }

        if (Math.abs(g.velocity) > MIN_VELOCITY) {
            inertiaFrameRef.current = requestAnimationFrame(runInertia);
        } else {
            g.velocity = 0;
            inertiaFrameRef.current = null;
        }
    }, [scrollRef]);

    const stopInertia = useCallback(() => {
        if (inertiaFrameRef.current !== null) {
            cancelAnimationFrame(inertiaFrameRef.current);
            inertiaFrameRef.current = null;
        }
        gestureRef.current.velocity = 0;
        gestureRef.current.samples = [];
    }, []);

    const handlePointerDown = useCallback((
        e: React.PointerEvent, 
        card: CardDefinition | null,
        origin: 'archive' | 'vault'
    ) => {
        if (e.button !== 0) return;

        stopInertia();

        const target = e.currentTarget as HTMLElement;
        dragTargetRef.current = target;
        try { target.setPointerCapture(e.pointerId); } catch (err) {}

        const rect = target.getBoundingClientRect();
        const startPos = { x: e.clientX, y: e.clientY };

        gestureRef.current = {
            isScrolling: false,
            isDragging: false,
            startPos,
            startScrollTop: scrollRef.current?.scrollTop || 0,
            hasCard: !!card,
            lastY: e.clientY,
            lastTime: performance.now(),
            velocity: 0,
            samples: []
        };

        setDragState({
            card: card || ({} as CardDefinition),
            origin,
            active: false,
            startPos,
            currentPos: startPos,
            rect,
            offset: card ? { x: e.clientX - rect.left, y: e.clientY - rect.top } : { x: 0, y: 0 },
        });

        // Resolve timing for archive pickup
        if (origin === 'vault' && card) {
            gestureRef.current.isDragging = true;
            setDragState(prev => prev ? { ...prev, active: true } : null);
        } else if (origin === 'archive' && card) {
            pickupTimerRef.current = window.setTimeout(() => {
                if (!gestureRef.current.isScrolling) {
                    gestureRef.current.isDragging = true;
                    setDragState(prev => prev ? { ...prev, active: true } : null);
                }
            }, PICKUP_DELAY);
        }
    }, [scrollRef, stopInertia]);

    useEffect(() => {
        if (!dragState) return;

        const handlePointerMove = (e: PointerEvent) => {
            const g = gestureRef.current;
            const now = performance.now();
            const dt = now - g.lastTime;
            const deltaX = e.clientX - g.startPos.x;
            const deltaY = e.clientY - g.startPos.y;

            if (dt > 0) {
                const dy = e.clientY - g.lastY;
                g.samples.push({ dy, dt });
                if (g.samples.length > 3) g.samples.shift();

                const totalDy = g.samples.reduce((sum, s) => sum + s.dy, 0);
                const totalDt = g.samples.reduce((sum, s) => sum + s.dt, 0);
                g.velocity = totalDy / (totalDt / 16.67);

                g.lastY = e.clientY;
                g.lastTime = now;
            }

            // GESTURE ARBITRATION
            if (!g.isScrolling && !g.isDragging) {
                const absX = Math.abs(deltaX);
                const absY = Math.abs(deltaY);

                if (deltaY > SCROLL_THRESHOLD) {
                    g.isScrolling = true;
                    if (pickupTimerRef.current) clearTimeout(pickupTimerRef.current);
                } 
                else if (deltaY < -SCROLL_THRESHOLD) {
                    const isFastSwipe = Math.abs(g.velocity) > 10;
                    if (g.hasCard && !isFastSwipe) {
                        if (absY > DRAG_THRESHOLD) {
                            g.isDragging = true;
                            if (pickupTimerRef.current) clearTimeout(pickupTimerRef.current);
                            setDragState(prev => prev ? { ...prev, active: true, currentPos: { x: e.clientX, y: e.clientY } } : null);
                        }
                    } else {
                        g.isScrolling = true;
                        if (pickupTimerRef.current) clearTimeout(pickupTimerRef.current);
                    }
                }
                else if (absX > DRAG_THRESHOLD && g.hasCard) {
                    g.isDragging = true;
                    if (pickupTimerRef.current) clearTimeout(pickupTimerRef.current);
                    setDragState(prev => prev ? { ...prev, active: true, currentPos: { x: e.clientX, y: e.clientY } } : null);
                }
            }

            if (g.isScrolling && scrollRef.current) {
                scrollRef.current.scrollTop = g.startScrollTop - deltaY;
                return;
            }

            if (g.isDragging) {
                if (e.cancelable) e.preventDefault();
                setDragState(prev => prev ? { ...prev, currentPos: { x: e.clientX, y: e.clientY } } : null);
            }
        };

        const handlePointerUp = (e: PointerEvent) => {
            if (pickupTimerRef.current) clearTimeout(pickupTimerRef.current);
            if (dragTargetRef.current) {
                try { dragTargetRef.current.releasePointerCapture(e.pointerId); } catch (err) {}
                dragTargetRef.current = null;
            }

            const { isDragging, isScrolling, startPos, hasCard, velocity } = gestureRef.current;

            if (isScrolling && Math.abs(velocity) > MIN_VELOCITY) {
                inertiaFrameRef.current = requestAnimationFrame(runInertia);
            }

            if (isDragging && hasCard) {
                const els = document.elementsFromPoint(e.clientX, e.clientY);
                const vaultZone = els.find((el) => el.getAttribute('data-drop-zone') === 'vault');
                const archiveZone = els.find((el) => el.getAttribute('data-drop-zone') === 'archive');

                if (dragState.origin === 'archive' && vaultZone) {
                    onAdd(dragState.card.id);
                } else if (dragState.origin === 'vault' && (archiveZone || !user.collection.includes(dragState.card.id))) {
                    onRemove(dragState.card.id);
                }
            } else if (!isScrolling && !isDragging && hasCard) {
                const dist = Math.hypot(e.clientX - startPos.x, e.clientY - startPos.y);
                if (dist < DRAG_THRESHOLD) inspect(dragState.card);
            }

            setDragState(null);
            gestureRef.current.isScrolling = false;
            gestureRef.current.isDragging = false;
        };

        window.addEventListener('pointermove', handlePointerMove, { passive: false });
        window.addEventListener('pointerup', handlePointerUp);
        window.addEventListener('pointercancel', handlePointerUp);

        return () => {
            window.removeEventListener('pointermove', handlePointerMove);
            window.removeEventListener('pointerup', handlePointerUp);
            window.removeEventListener('pointercancel', handlePointerUp);
            if (pickupTimerRef.current) clearTimeout(pickupTimerRef.current);
        };
    }, [dragState, inspect, onAdd, onRemove, scrollRef, runInertia, user]);

    return { dragState, handlePointerDown };
};

import React, { useMemo } from 'react';
import { CARDS } from '../../constants';
import { Card } from '../Card';
import { CardDefinition } from '../../types';
import { useUser } from '../../contexts/UserContext';

interface CollectionGridProps {
    scrollRef: React.RefObject<HTMLDivElement>;
    ownedIds: string[];
    activeDeckIds: string[];
    draggingCardId?: string;
    onPointerDown: (e: React.PointerEvent, card: CardDefinition | null) => void;
}

export const CollectionGrid: React.FC<CollectionGridProps> = ({ 
    scrollRef, ownedIds, activeDeckIds, draggingCardId, onPointerDown 
}) => {
    const { collectionSort, collectionFilterSearch, collectionFilterTags } = useUser();

    const filteredAndSortedCards = useMemo(() => {
        let results = [...CARDS];

        if (collectionFilterSearch) {
            const query = collectionFilterSearch.toLowerCase();
            results = results.filter(c => 
                c.name.toLowerCase().includes(query) || 
                c.baseText.toLowerCase().includes(query)
            );
        }

        if (collectionFilterTags.length > 0) {
            results = results.filter(c => {
                return collectionFilterTags.some(tag => {
                    if (tag === 'None') return c.tags.length === 0;
                    return c.tags.includes(tag);
                });
            });
        }

        return results.sort((a, b) => {
            const aOwned = ownedIds.includes(a.id);
            const bOwned = ownedIds.includes(b.id);
            if (aOwned !== bOwned) return aOwned ? -1 : 1;

            if (collectionSort === 'Cost') return a.baseCost - b.baseCost;
            if (collectionSort === 'Power') return b.basePower - a.basePower;
            if (collectionSort === 'Newest') {
                const aIdx = CARDS.findIndex(c => c.id === a.id);
                const bIdx = CARDS.findIndex(c => c.id === b.id);
                return bIdx - aIdx;
            }
            return a.name.localeCompare(b.name);
        });
    }, [ownedIds, collectionSort, collectionFilterSearch, collectionFilterTags]);

    return (
        <div className="w-full h-full flex flex-col">
            <div 
                ref={scrollRef} 
                className="flex-1 overflow-hidden px-2.5 pt-2 pb-52 touch-none select-none"
            >
                 {filteredAndSortedCards.length === 0 ? (
                     <div className="w-full py-20 flex flex-col items-center justify-center text-slate-700 pointer-events-none">
                         <svg className="w-12 h-12 mb-2 opacity-20" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                         <span className="text-[0.6rem] font-black uppercase tracking-widest">No matching cards</span>
                     </div>
                 ) : (
                     <div className="grid grid-cols-5 gap-x-1.5 gap-y-2.5 justify-items-center">
                         {filteredAndSortedCards.map((def) => {
                             const isOwned = ownedIds.includes(def.id);
                             const inDeck = activeDeckIds.includes(def.id);
                             const isDragging = draggingCardId === def.id;

                             let stateClasses = '';
                             if (isDragging) {
                                 stateClasses = 'opacity-0';
                             } else if (!isOwned) {
                                 stateClasses = 'opacity-40 grayscale scale-95';
                             } else if (inDeck) {
                                 stateClasses = 'opacity-50 grayscale'; 
                             } else {
                                 stateClasses = 'hover:scale-105'; 
                             }

                             return (
                                 <div 
                                    key={def.id} 
                                    className={`relative transition-all duration-300 rounded-md w-full flex justify-center ${stateClasses}`}
                                    onPointerDown={(e) => onPointerDown(e, def)}
                                    onContextMenu={(e) => e.preventDefault()}
                                 >
                                     <div className="w-full aspect-[5/7] rounded-md transition-all duration-300 cursor-grab active:cursor-grabbing">
                                         <Card 
                                            card={def} 
                                            size="xs" 
                                            variant="default" 
                                         />
                                     </div>
                                 </div>
                             );
                         })}
                     </div>
                 )}

                 <div className="h-12 w-full flex items-center justify-center mt-12 mb-8 pointer-events-none">
                     <div className="text-[0.55rem] text-slate-800 font-black uppercase tracking-[0.5em]">Terminal Archive End</div>
                 </div>
            </div>
        </div>
    );
}

import React, { useState, useCallback, useMemo, useRef, useEffect } from 'react';
import { StandardHeader } from '../ui/StandardHeader';
import { DeckSelector } from '../game/DeckSelector';
import { CollectionGrid } from '../deck/CollectionGrid';
import { DeckVault } from '../deck/DeckVault';
import { ComicArchive } from '../deck/ComicArchive';
import { InventoryStash } from '../deck/InventoryStash';
import { CollectionDragOverlay } from '../CollectionDragOverlay';
import { useUser } from '../../contexts/UserContext';
import { useCollectionDrag } from '../../hooks/useCollectionDrag';
import { CARDS } from '../../constants';
import { CardDefinition, CollectionTab, ScreenKey } from '../../types';
import { HexBadge } from '../ui/HexBadge';

interface DeckScreenProps {
    onNavigate: (s: ScreenKey) => void;
    activeScreen?: ScreenKey; 
}

export const DeckScreen: React.FC<DeckScreenProps> = ({ activeScreen }) => {
    const { user, updateDeck, activeDeck, setActiveDeck } = useUser();
    const [activeTab, setActiveTab] = useState<CollectionTab>('CARDS');

    useEffect(() => {
        if (activeScreen === 'DECK') {
            setActiveTab('CARDS');
        }
    }, [activeScreen]);

    const scrollRef = useRef<HTMLDivElement>(null);
    const vaultRef = useRef<HTMLDivElement>(null);
    const archiveRef = useRef<HTMLDivElement>(null);

    const handleAddCard = useCallback((cardId: string) => {
        if (activeDeck.length < 12 && !activeDeck.includes(cardId)) {
            updateDeck(user.activeDeckId, [...activeDeck, cardId]);
        }
    }, [activeDeck, user.activeDeckId, updateDeck]);

    const handleRemoveCard = useCallback((cardId: string) => {
        updateDeck(user.activeDeckId, activeDeck.filter(id => id !== cardId));
    }, [activeDeck, user.activeDeckId, updateDeck]);

    const { dragState, handlePointerDown } = useCollectionDrag({
        onAdd: handleAddCard,
        onRemove: handleRemoveCard,
        scrollRef: scrollRef
    });

    const deckCards = useMemo(() => {
        return activeDeck
            .map(id => CARDS.find(c => c.id === id))
            .filter((c): c is CardDefinition => !!c)
            .sort((a, b) => {
                if (a.baseCost !== b.baseCost) {
                    return a.baseCost - b.baseCost;
                }
                return a.name.localeCompare(b.name);
            });
    }, [activeDeck]);

    const renderContent = () => {
        switch(activeTab) {
            case 'COMICS': return <ComicArchive />;
            case 'INVENTORY': return <InventoryStash />;
            default:
                return (
                    <div className="flex flex-col h-full overflow-hidden">
                        {/* 1. DECK SELECTION & VAULT ZONE */}
                        <div 
                            ref={vaultRef}
                            className={`shrink-0 border-b border-slate-700/50 z-20 transition-all duration-300 ${dragState?.active && dragState.origin === 'archive' ? 'ring-2 ring-inset ring-indigo-500/50' : ''}`}
                            data-drop-zone="vault"
                        >
                            <DeckSelector 
                                activeDeckId={user.activeDeckId} 
                                onSelectDeck={setActiveDeck}
                            />
                            <div className="px-3 pb-2">
                                <DeckVault 
                                    cards={deckCards} 
                                    draggingCardId={dragState?.active && dragState.origin === 'vault' ? dragState.card.id : undefined}
                                    onPointerDown={(e, card) => handlePointerDown(e, card, 'vault')}
                                />
                            </div>
                        </div>

                        {/* 2. COLLECTION ARCHIVE */}
                        <div 
                            ref={archiveRef}
                            className={`flex-1 min-h-0 relative transition-all duration-300 ${dragState?.active && dragState.origin === 'vault' ? 'bg-indigo-500/5' : ''}`}
                            data-drop-zone="archive"
                        >
                            <CollectionGrid 
                                scrollRef={scrollRef}
                                ownedIds={user.collection}
                                activeDeckIds={activeDeck}
                                draggingCardId={dragState?.active && dragState.origin === 'archive' ? dragState.card.id : undefined}
                                onPointerDown={(e, card) => handlePointerDown(e, card, 'archive')}
                            />
                        </div>
                    </div>
                );
        }
    };

    return (
        <div className="w-full h-full flex flex-col bg-transparent overflow-hidden relative">
            <StandardHeader 
                title="COLLECTION" 
                className="!py-1.5"
                leftContent={
                    <div className="flex items-center gap-2 ml-1 cursor-pointer group active:scale-95 transition-transform">
                        <HexBadge variant="primary" size="sm" glow className="group-hover:scale-110 transition-transform">
                            42
                        </HexBadge>
                        <div className="flex flex-col">
                            <span className="text-[0.45rem] font-black text-indigo-400 uppercase leading-none tracking-widest">Mastery</span>
                            <span className="text-[0.6rem] font-black text-white italic tracking-tighter leading-none mt-0.5">RANK 1,402</span>
                        </div>
                    </div>
                }
                rightContent={
                    <div className="flex items-center gap-1 mr-1">
                        <TabButton 
                            active={activeTab === 'CARDS'} 
                            onClick={() => setActiveTab('CARDS')}
                            icon={<svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" /></svg>}
                        />
                        <TabButton 
                            active={activeTab === 'COMICS'} 
                            onClick={() => setActiveTab('COMICS')}
                            icon={<svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.247 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" /></svg>}
                        />
                        <TabButton 
                            active={activeTab === 'INVENTORY'} 
                            onClick={() => setActiveTab('INVENTORY')}
                            icon={<svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4" /></svg>}
                        />
                    </div>
                }
            />

            <CollectionDragOverlay dragState={dragState} />

            <div className="flex-1 overflow-hidden">
                {renderContent()}
            </div>
        </div>
    );
};

const TabButton: React.FC<{ active: boolean; onClick: () => void; icon: React.ReactNode }> = ({ active, onClick, icon }) => (
    <button 
        onClick={onClick}
        className={`w-9 h-8 flex items-center justify-center rounded skew-x-[-12deg] transition-all duration-300 border-b-2 ${active ? 'bg-indigo-600 border-indigo-300 text-white shadow-[0_0_12px_rgba(79,70,229,0.4)] scale-105 z-10' : 'bg-slate-800/80 border-slate-700 text-slate-500 active:scale-95'}`}
    >
        <div className="skew-x-[12deg] flex items-center justify-center drop-shadow-md">
            {icon}
        </div>
    </button>
);

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { CardDefinition } from '../types';
import { useUser } from '../contexts/UserContext';

export interface CollectionDragState {
  card: CardDefinition;
  origin: 'archive' | 'vault';
  startPos: { x: number; y: number };
  currentPos: { x: number; y: number };
  offset: { x: number; y: number };
  rect: DOMRect;
  active: boolean;
}

interface UseCollectionDragProps {
  onAdd: (id: string) => void;
  onRemove: (id: string) => void;
  scrollRef: React.RefObject<HTMLElement>;
}

const DRAG_THRESHOLD = 8;
const SCROLL_THRESHOLD = 4;
const PICKUP_DELAY = 120; // Fast response for premium feel
const FRICTION = 0.96; // Slightly less friction for longer glides
const MIN_VELOCITY = 0.2;

export const useCollectionDrag = ({ onAdd, onRemove, scrollRef }: UseCollectionDragProps) => {
    // FIX: Destructure 'user' from useUser to fix the missing name error in pointerUp
    const { user, inspect } = useUser();
    const [dragState, setDragState] = useState<CollectionDragState | null>(null);

    // Internal refs for high-frequency updates
    const gestureRef = useRef({
        isScrolling: false,
        isDragging: false,
        startPos: { x: 0, y: 0 },
        startScrollTop: 0,
        hasCard: false,
        lastY: 0,
        lastTime: 0,
        velocity: 0,
        samples: [] as { dy: number, dt: number }[] // For velocity smoothing
    });

    const inertiaFrameRef = useRef<number | null>(null);
    const dragTargetRef = useRef<HTMLElement | null>(null);
    const pickupTimerRef = useRef<number | null>(null);

    const runInertia = useCallback(() => {
        if (!scrollRef.current) return;

        const g = gestureRef.current;
        const el = scrollRef.current;

        el.scrollTop -= g.velocity;
        g.velocity *= FRICTION;

        // Boundary check for "bounce" or hard stop
        if (el.scrollTop <= 0 || el.scrollTop >= el.scrollHeight - el.clientHeight) {
            g.velocity = 0;
        }

        if (Math.abs(g.velocity) > MIN_VELOCITY) {
            inertiaFrameRef.current = requestAnimationFrame(runInertia);
        } else {
            g.velocity = 0;
            inertiaFrameRef.current = null;
        }
    }, [scrollRef]);

    const stopInertia = useCallback(() => {
        if (inertiaFrameRef.current !== null) {
            cancelAnimationFrame(inertiaFrameRef.current);
            inertiaFrameRef.current = null;
        }
        gestureRef.current.velocity = 0;
        gestureRef.current.samples = [];
    }, []);

    const handlePointerDown = useCallback((
        e: React.PointerEvent, 
        card: CardDefinition | null,
        origin: 'archive' | 'vault'
    ) => {
        if (e.button !== 0) return;

        stopInertia();

        const target = e.currentTarget as HTMLElement;
        dragTargetRef.current = target;
        try { target.setPointerCapture(e.pointerId); } catch (err) {}

        const rect = target.getBoundingClientRect();
        const startPos = { x: e.clientX, y: e.clientY };

        gestureRef.current = {
            isScrolling: false,
            isDragging: false,
            startPos,
            startScrollTop: scrollRef.current?.scrollTop || 0,
            hasCard: !!card,
            lastY: e.clientY,
            lastTime: performance.now(),
            velocity: 0,
            samples: []
        };

        setDragState({
            card: card || ({} as CardDefinition),
            origin,
            active: false,
            startPos,
            currentPos: startPos,
            rect,
            offset: card ? { x: e.clientX - rect.left, y: e.clientY - rect.top } : { x: 0, y: 0 },
        });

        if (origin === 'vault' && card) {
            gestureRef.current.isDragging = true;
            setDragState(prev => prev ? { ...prev, active: true } : null);
        } else if (origin === 'archive' && card) {
            pickupTimerRef.current = window.setTimeout(() => {
                if (!gestureRef.current.isScrolling) {
                    gestureRef.current.isDragging = true;
                    setDragState(prev => prev ? { ...prev, active: true } : null);
                }
            }, PICKUP_DELAY);
        }

    }, [scrollRef, stopInertia]);

    useEffect(() => {
        if (!dragState) return;

        const handlePointerMove = (e: PointerEvent) => {
            const g = gestureRef.current;
            const now = performance.now();
            const dt = now - g.lastTime;
            const deltaX = e.clientX - g.startPos.x;
            const deltaY = e.clientY - g.startPos.y;

            if (dt > 0) {
                const dy = e.clientY - g.lastY;
                // Add sample for moving average
                g.samples.push({ dy, dt });
                if (g.samples.length > 3) g.samples.shift();

                // Calculate smoothed velocity
                const totalDy = g.samples.reduce((sum, s) => sum + s.dy, 0);
                const totalDt = g.samples.reduce((sum, s) => sum + s.dt, 0);
                g.velocity = totalDy / (totalDt / 16.67);

                g.lastY = e.clientY;
                g.lastTime = now;
            }

            // GESTURE DETECTION
            if (!g.isScrolling && !g.isDragging) {
                const absX = Math.abs(deltaX);
                const absY = Math.abs(deltaY);

                // If moving finger down (deltaY > 0), it's always a scroll
                if (deltaY > SCROLL_THRESHOLD) {
                    g.isScrolling = true;
                    if (pickupTimerRef.current) clearTimeout(pickupTimerRef.current);
                } 
                // If moving finger up (deltaY < 0), we check intent
                else if (deltaY < -SCROLL_THRESHOLD) {
                    const isFastSwipe = Math.abs(g.velocity) > 10;
                    if (g.hasCard && !isFastSwipe) {
                        // Slow upward move with card = potential drag
                        if (absY > DRAG_THRESHOLD) {
                            g.isDragging = true;
                            if (pickupTimerRef.current) clearTimeout(pickupTimerRef.current);
                            setDragState(prev => prev ? { ...prev, active: true, currentPos: { x: e.clientX, y: e.clientY } } : null);
                        }
                    } else {
                        // Fast upward move or no card = scroll
                        g.isScrolling = true;
                        if (pickupTimerRef.current) clearTimeout(pickupTimerRef.current);
                    }
                }
                // Horizontal move
                else if (absX > DRAG_THRESHOLD) {
                    if (g.hasCard) {
                        g.isDragging = true;
                        if (pickupTimerRef.current) clearTimeout(pickupTimerRef.current);
                        setDragState(prev => prev ? { ...prev, active: true, currentPos: { x: e.clientX, y: e.clientY } } : null);
                    }
                }
            }

            if (g.isScrolling && scrollRef.current) {
                scrollRef.current.scrollTop = g.startScrollTop - deltaY;
                return;
            }

            if (g.isDragging) {
                if (e.cancelable) e.preventDefault();
                setDragState(prev => prev ? { ...prev, currentPos: { x: e.clientX, y: e.clientY } } : null);
            }
        };

        const handlePointerUp = (e: PointerEvent) => {
            if (pickupTimerRef.current) clearTimeout(pickupTimerRef.current);
            if (dragTargetRef.current) {
                try { dragTargetRef.current.releasePointerCapture(e.pointerId); } catch (err) {}
                dragTargetRef.current = null;
            }

            const { isDragging, isScrolling, startPos, hasCard, velocity } = gestureRef.current;

            if (isScrolling && Math.abs(velocity) > MIN_VELOCITY) {
                inertiaFrameRef.current = requestAnimationFrame(runInertia);
            }

            if (isDragging && hasCard) {
                const els = document.elementsFromPoint(e.clientX, e.clientY);
                const vaultZone = els.find((el) => el.getAttribute('data-drop-zone') === 'vault');
                const archiveZone = els.find((el) => el.getAttribute('data-drop-zone') === 'archive');

                if (dragState.origin === 'archive' && vaultZone) {
                    onAdd(dragState.card.id);
                } else if (dragState.origin === 'vault' && (archiveZone || !user.collection.includes(dragState.card.id))) {
                    // Logic to ensure cards are only dropped where valid
                    onRemove(dragState.card.id);
                }
            } else if (!isScrolling && !isDragging && hasCard) {
                const dist = Math.hypot(e.clientX - startPos.x, e.clientY - startPos.y);
                if (dist < DRAG_THRESHOLD) inspect(dragState.card);
            }

            setDragState(null);
            gestureRef.current.isScrolling = false;
            gestureRef.current.isDragging = false;
        };

        window.addEventListener('pointermove', handlePointerMove, { passive: false });
        window.addEventListener('pointerup', handlePointerUp);
        window.addEventListener('pointercancel', handlePointerUp);

        return () => {
            window.removeEventListener('pointermove', handlePointerMove);
            window.removeEventListener('pointerup', handlePointerUp);
            window.removeEventListener('pointercancel', handlePointerUp);
            if (pickupTimerRef.current) clearTimeout(pickupTimerRef.current);
        };
    }, [dragState, inspect, onAdd, onRemove, scrollRef, runInertia, user]);

    return { dragState, handlePointerDown };
};

import React, { useMemo } from 'react';
import { CARDS } from '../../constants';
import { Card } from '../Card';
import { CardDefinition } from '../../types';
import { useUser } from '../../contexts/UserContext';

interface CollectionGridProps {
    scrollRef: React.RefObject<HTMLDivElement>;
    ownedIds: string[];
    activeDeckIds: string[];
    draggingCardId?: string;
    onPointerDown: (e: React.PointerEvent, card: CardDefinition | null) => void;
}

export const CollectionGrid: React.FC<CollectionGridProps> = ({ 
    scrollRef, ownedIds, activeDeckIds, draggingCardId, onPointerDown 
}) => {
    const { collectionSort, collectionFilterSearch, collectionFilterTags } = useUser();

    const filteredAndSortedCards = useMemo(() => {
        let results = [...CARDS];

        if (collectionFilterSearch) {
            const query = collectionFilterSearch.toLowerCase();
            results = results.filter(c => 
                c.name.toLowerCase().includes(query) || 
                c.baseText.toLowerCase().includes(query)
            );
        }

        if (collectionFilterTags.length > 0) {
            results = results.filter(c => {
                return collectionFilterTags.some(tag => {
                    if (tag === 'None') return c.tags.length === 0;
                    return c.tags.includes(tag);
                });
            });
        }

        return results.sort((a, b) => {
            const aOwned = ownedIds.includes(a.id);
            const bOwned = ownedIds.includes(b.id);
            if (aOwned !== bOwned) return aOwned ? -1 : 1;

            if (collectionSort === 'Cost') return a.baseCost - b.baseCost;
            if (collectionSort === 'Power') return b.basePower - a.basePower;
            if (collectionSort === 'Newest') {
                const aIdx = CARDS.findIndex(c => c.id === a.id);
                const bIdx = CARDS.findIndex(c => c.id === b.id);
                return bIdx - aIdx;
            }
            return a.name.localeCompare(b.name);
        });
    }, [ownedIds, collectionSort, collectionFilterSearch, collectionFilterTags]);

    return (
        <div className="w-full h-full flex flex-col">
            <div 
                ref={scrollRef} 
                className="flex-1 overflow-hidden px-2.5 pt-2 pb-52 touch-none select-none"
            >
                 {filteredAndSortedCards.length === 0 ? (
                     <div className="w-full py-20 flex flex-col items-center justify-center text-slate-700 pointer-events-none">
                         <svg className="w-12 h-12 mb-2 opacity-20" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                         <span className="text-[0.6rem] font-black uppercase tracking-widest">No matching cards</span>
                     </div>
                 ) : (
                     <div className="grid grid-cols-5 gap-x-1.5 gap-y-2.5 justify-items-center">
                         {filteredAndSortedCards.map((def) => {
                             const isOwned = ownedIds.includes(def.id);
                             const inDeck = activeDeckIds.includes(def.id);
                             const isDragging = draggingCardId === def.id;

                             let stateClasses = '';
                             if (isDragging) {
                                 stateClasses = 'opacity-0';
                             } else if (!isOwned) {
                                 stateClasses = 'opacity-40 grayscale scale-95';
                             } else if (inDeck) {
                                 stateClasses = 'opacity-50 grayscale'; 
                             } else {
                                 stateClasses = 'hover:scale-105'; 
                             }

                             return (
                                 <div 
                                    key={def.id} 
                                    className={`relative transition-all duration-300 rounded-md w-full flex justify-center ${stateClasses}`}
                                    onPointerDown={(e) => onPointerDown(e, def)}
                                    onContextMenu={(e) => e.preventDefault()}
                                 >
                                     <div className="w-full aspect-[5/7] rounded-md transition-all duration-300 cursor-grab active:cursor-grabbing">
                                         <Card 
                                            card={def} 
                                            size="xs" 
                                            variant="default" 
                                         />
                                     </div>
                                 </div>
                             );
                         })}
                     </div>
                 )}

                 <div className="h-12 w-full flex items-center justify-center mt-12 mb-8 pointer-events-none">
                     <div className="text-[0.55rem] text-slate-800 font-black uppercase tracking-[0.5em]">Terminal Archive End</div>
                 </div>
            </div>
        </div>
    );
}

import React, { useState, useCallback, useMemo, useRef, useEffect } from 'react';
