        // CRITICAL FIX: Do not return early if card is in deck. 
        // We must initialize the gesture system to allow scrolling.
        const canDragThisCard = card && !(origin === 'archive' && activeDeck.includes(card.id));

        gestureRef.current = {
            isScrolling: false,
            isDragging: false,
            startPos,
            startScrollTop: scrollRef.current?.scrollTop || 0,
            hasCard: !!canDragThisCard,
            lastY: e.clientY,
            lastTime: performance.now(),
            velocity: 0,
            samples: []
        };

        // Always set dragState to ensure the event listeners in useEffect are active
        setDragState({
            card: card || ({} as CardDefinition),
            origin,
            active: false,
            startPos,
            currentPos: startPos,
            rect,
            offset: card ? { x: e.clientX - rect.left, y: e.clientY - rect.top } : { x: 0, y: 0 },
        });

        if (origin === 'vault' && canDragThisCard) {
            gestureRef.current.isDragging = true;
            setDragState(prev => prev ? { ...prev, active: true } : null);
        } else if (origin === 'archive' && canDragThisCard) {
            pickupTimerRef.current = window.setTimeout(() => {
                if (!gestureRef.current.isScrolling) {
                    gestureRef.current.isDragging = true;
                    setDragState(prev => prev ? { ...prev, active: true } : null);
                }
            }, PICKUP_DELAY);
        }
    }, [scrollRef, stopInertia, activeDeck]);

    useEffect(() => {
        if (!dragState) return;

        const handlePointerMove = (e: PointerEvent) => {
            const g = gestureRef.current;
            const now = performance.now();
            const dt = now - g.lastTime;
            const deltaX = e.clientX - g.startPos.x;
            const deltaY = e.clientY - g.startPos.y;

            if (dt > 0) {
                const dy = e.clientY - g.lastY;
                g.samples.push({ dy, dt });
                if (g.samples.length > 3) g.samples.shift();

                const totalDy = g.samples.reduce((sum, s) => sum + s.dy, 0);
                const totalDt = g.samples.reduce((sum, s) => sum + s.dt, 0);
                g.velocity = totalDy / (totalDt / 16.67);

                g.lastY = e.clientY;
                g.lastTime = now;
            }

            // GESTURE ARBITRATION
            if (!g.isScrolling && !g.isDragging) {
                const absX = Math.abs(deltaX);
                const absY = Math.abs(deltaY);

                // Check for scroll intent
                if (absY > SCROLL_THRESHOLD) {
                    g.isScrolling = true;
                    if (pickupTimerRef.current) {
                        clearTimeout(pickupTimerRef.current);
                        pickupTimerRef.current = null;
                    }
                } 
                // Check for drag intent
                else if (absX > DRAG_THRESHOLD && g.hasCard) {
                    g.isDragging = true;
                    if (pickupTimerRef.current) {
                        clearTimeout(pickupTimerRef.current);
                        pickupTimerRef.current = null;
                    }
                    setDragState(prev => prev ? { ...prev, active: true, currentPos: { x: e.clientX, y: e.clientY } } : null);
                }
            }

            if (g.isScrolling && scrollRef.current) {
                // Ensure we block native scroll to prevent double-scroll artifacts
                if (e.cancelable) e.preventDefault();
                scrollRef.current.scrollTop = g.startScrollTop - deltaY;
                return;
            }

            if (g.isDragging) {
                if (e.cancelable) e.preventDefault();
                setDragState(prev => prev ? { ...prev, currentPos: { x: e.clientX, y: e.clientY } } : null);
            }
        };

        const handlePointerUp = (e: PointerEvent) => {
            if (pickupTimerRef.current) {
                clearTimeout(pickupTimerRef.current);
                pickupTimerRef.current = null;
            }

            if (dragTargetRef.current) {
                try { dragTargetRef.current.releasePointerCapture(e.pointerId); } catch (err) {}
                dragTargetRef.current = null;
            }

            const { isDragging, isScrolling, startPos, hasCard, velocity } = gestureRef.current;

            if (isScrolling && Math.abs(velocity) > MIN_VELOCITY) {
                inertiaFrameRef.current = requestAnimationFrame(runInertia);
            }

            if (isDragging && hasCard) {
                const els = document.elementsFromPoint(e.clientX, e.clientY);
                const vaultZone = els.find((el) => el.getAttribute('data-drop-zone') === 'vault');
                const archiveZone = els.find((el) => el.getAttribute('data-drop-zone') === 'archive');

                if (dragState.origin === 'archive' && vaultZone) {
                    onAdd(dragState.card.id);
                } else if (dragState.origin === 'vault' && (archiveZone || !user.collection.includes(dragState.card.id))) {
                    onRemove(dragState.card.id);
                }
            } else if (!isScrolling && !isDragging && dragState.card.id) {
                // Treats small dist as a click for inspection
                const dist = Math.hypot(e.clientX - startPos.x, e.clientY - startPos.y);
                if (dist < DRAG_THRESHOLD) {
                    inspect(dragState.card);
                }
            }

            setDragState(null);
            gestureRef.current.isScrolling = false;
            gestureRef.current.isDragging = false;
        };

        window.addEventListener('pointermove', handlePointerMove, { passive: false });
        window.addEventListener('pointerup', handlePointerUp);
        window.addEventListener('pointercancel', handlePointerUp);

        return () => {
            window.removeEventListener('pointermove', handlePointerMove);
            window.removeEventListener('pointerup', handlePointerUp);
            window.removeEventListener('pointercancel', handlePointerUp);
            if (pickupTimerRef.current) clearTimeout(pickupTimerRef.current);
        };
    }, [dragState, inspect, onAdd, onRemove, scrollRef, runInertia, user]);

    return { dragState, handlePointerDown };
};

