        { label: 'On Reveal', tag: 'OnReveal' },
        { label: 'Ongoing', tag: 'Ongoing' },
        { label: 'Destroy', tag: 'Destroy' },
        { label: 'No Ability', tag: 'None' }
    ];

    return (
        <div className="w-full flex items-end justify-between px-4 pb-0.5 gap-3 relative pointer-events-none">

