                                    <span className="text-indigo-300 font-black mr-2">{log.type}</span>
                                    <span className="text-slate-400 truncate block">{JSON.stringify(log.payload)}</span>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            )}

            <GameHeader />

            {/* 3D VIEWPORT CONTAINER */}
            <div className="flex-1 min-h-0 relative">
                {/* 
                   In the final build, the GameBoard would be replaced by an <iframe> 
                   or a transparent Viewport. For now, we maintain the HTML board
                   but style it as a "Virtual Lens".
                */}
                <div className="absolute inset-0 pointer-events-none border-[1px] border-white/5 z-40 rounded-lg ring-inset ring-black/40 ring-4"></div>
                <GameBoard />
            </div>

            <div className="shrink-0 z-30 flex flex-col bg-slate-950/80 backdrop-blur-sm">
                <PlayerHand />
                <ControlBar />
            </div>
        </div>
    );
}

import React from 'react';
import { CardInstance, CardDefinition } from '../types';
import { UnifiedCardView } from './card/UnifiedCardView';

interface CardProps {
  card: CardInstance | CardDefinition;
  onClick?: () => void;
  size?: 'xs' | 'sm' | 'md' | 'lg';
  hidden?: boolean;
  onPointerDown?: (e: React.PointerEvent) => void;
  isDragging?: boolean;
  borderOverride?: string; 
  // Fix: Added variant prop to support different rendering styles like 'board' or 'thumbnail'
  variant?: string;
}

/**
 * Card Component
 * A high-performance wrapper that delegates all rendering to the UnifiedCardView engine.
 */
const CardComponent: React.FC<CardProps> = ({ 
  card, 
  onClick, 
  size = 'md', 
  hidden, 
  onPointerDown,
  isDragging,
  borderOverride,
  // Fix: Pass variant to UnifiedCardView
  variant
}) => {
  return (
    <UnifiedCardView
        card={card}
        size={size}
        hidden={hidden}
        isDragging={isDragging}
        onPointerDown={onPointerDown}
        onClick={onClick}
        borderOverride={borderOverride}
        variant={variant}
    />
  );
};

export const Card = React.memo(CardComponent, (prev, next) => {
    if (prev.size !== next.size || prev.isDragging !== next.isDragging || prev.hidden !== next.hidden || prev.borderOverride !== next.borderOverride || prev.variant !== next.variant) return false;

    const isInstance = (c: any): c is CardInstance => c && 'instanceId' in c;

    if (isInstance(prev.card) && isInstance(next.card)) {
        return prev.card.instanceId === next.card.instanceId && 
               prev.card.totalPower === next.card.totalPower && 
               prev.card.totalCost === next.card.totalCost &&
               prev.card.faceUp === next.card.faceUp;
    }

    const getDefinitionId = (card: CardInstance | CardDefinition) => 
        isInstance(card) ? card.definitionId : card.id;

    return getDefinitionId(prev.card) === getDefinitionId(next.card);
});

import React from 'react';
import { CardDefinition, CardInstance } from '../../types';
import { getCardVisualState } from '../../utils/cardStyles';
