export const CardBadge: React.FC<CardBadgeProps> = ({ instanceId, value, type, colorClass }) => {
    const isCost = type === 'cost';
    const badgeSize = '1.05em'; 
    const offset = '-0.05em'; 
    const position = isCost ? { top: offset, left: offset } : { top: offset, right: offset };
    const bgColor = isCost ? '#2563eb' : '#dc2626';

    // Direct DOM Reference for Svelte-like performance
    const textRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        if (!instanceId) return;

        // Subscribe to the Signal. 
        // This callback updates the DOM directly, Bypassing React.render()
        const signal = isCost 
            ? gameSignals.getCostSignal(instanceId, value)
            : gameSignals.getPowerSignal(instanceId, value);

        return signal.subscribe((newVal) => {
            if (textRef.current) {
                // Update raw text node for maximum performance
                textRef.current.innerText = newVal.toString();

                // Trigger a "Jiggle" animation if the value changed
                textRef.current.animate([
                    { transform: 'scale(1.4)', color: '#fff' },
                    { transform: 'scale(1)', color: 'inherit' }
                ], { duration: 300, easing: 'ease-out' });
            }
        });
    }, [instanceId, isCost, value]);

    return (
        <div 
            className="absolute z-30 pointer-events-none"
            style={{ 
                width: badgeSize, 
                height: badgeSize,
                filter: 'drop-shadow(0 0.06em 0.1em rgba(0,0,0,0.8))',
                ...position
            }}
        >
            <svg viewBox="0 0 100 100" className="w-full h-full overflow-visible">
                <path 
                    d="M50 5 L95 25 L95 75 L50 95 L5 75 L5 25 Z" 
