                    <div ref={textRef} style={{ fontSize: '0.8em' }}>
                        {value}
                    </div>
                </div>
            </div>
        </div>
    );
};

import { useState, useEffect, useCallback, useRef } from 'react';
import { GameState, GameEvent } from '../types';
import { createInitialGameState, moveCardsToBoard, getNextReveal, revealCard, resolveEndOfTurn, startNextTurn, calculateWinner, stepExecutionQueue } from '../services/engine';
import { PendingMove } from '../services/planning';
import { unityBridge } from '../services/unityBridge';
import { gameSignals } from '../services/signals';

export const useTurnManager = () => {
    const [gameState, setGameState] = useState<GameState>(createInitialGameState());
    const [events, setEvents] = useState<GameEvent[]>([]);
    const [isResolving, setIsResolving] = useState(false);
    const [isWaiting, setIsWaiting] = useState(false);

    const gameStateRef = useRef(gameState);
    useEffect(() => { 
        gameStateRef.current = gameState; 

        // SYNC SIGNALS: Push board state to signals for Direct-DOM performance
        gameState.lanes.forEach(lane => {
            [...lane.p1Slots, ...lane.p2Slots].forEach(card => {
                if (card) gameSignals.sync(card.instanceId, card.totalPower, card.totalCost);
            });
        });
        gameSignals.p1Energy.value = gameState.players.p1.energy;

    }, [gameState]);

    const updateStateWithEvents = useCallback((newState: GameState) => {
        if (newState.eventQueue.length > 0) {
             const newEvents = [...newState.eventQueue];
             newState.eventQueue = [];

             newEvents.forEach(event => {
                 if (event.type === 'VFX_PLAY') {
                     unityBridge.send('TRIGGER_VFX', event);
                 }
             });

             setEvents(prev => [...prev, ...newEvents]);
        }
        setGameState(newState);
    }, []);

    const startResolution = useCallback((p1Moves: PendingMove[], p2Moves: PendingMove[]) => {
        setIsWaiting(false);

        unityBridge.send('TURN_END', { 
            p1Moves: p1Moves.map(m => ({ id: m.cardInstanceId, lane: m.laneIdx })),
            p2Moves: p2Moves.map(m => ({ id: m.cardInstanceId, lane: m.laneIdx }))
        });

        const newState = moveCardsToBoard(gameState, p1Moves, p2Moves);
        newState.phase = 'resolving';
        updateStateWithEvents(newState);
        setIsResolving(true);
    }, [gameState, updateStateWithEvents]);

    useEffect(() => {
        if (!isResolving) return;

        let active = true;

        const runLoop = async () => {
            if (!active) return active = false;
            const currentState = gameStateRef.current;

            if (currentState.executionQueue.length > 0) {
                const nextState = stepExecutionQueue(currentState);
                updateStateWithEvents(nextState);

                unityBridge.send('UPDATE_STATS', { 
                    lanes: nextState.lanes.map(l => ({ 
                        p1Power: 0, // Simplified
                    }))
                });

                setTimeout(runLoop, 350);
                return;
            }

            const nextReveal = getNextReveal(currentState);
            if (nextReveal) {
                setTimeout(() => {
                    if (!active) return;
                    unityBridge.send('PLAY_CARD', { ...nextReveal, reveal: true });
                    const s = revealCard(gameStateRef.current, nextReveal.laneIdx, nextReveal.slotIdx, nextReveal.owner);
                    updateStateWithEvents(s);
                    runLoop(); 
                }, 600);
                return;
            }

            const s = resolveEndOfTurn(currentState);
            if (s.executionQueue.length > 0) {
                updateStateWithEvents(s);
                setTimeout(runLoop, 50); 
                return;
            }

            let finalState = s;
            if (finalState.turn >= finalState.maxTurns) {
                finalState.phase = 'gameover';
                finalState.winner = calculateWinner(finalState);
                unityBridge.send('MATCH_OVER', { winner: finalState.winner });
                updateStateWithEvents(finalState);
                setIsResolving(false);
            } else {
                finalState = startNextTurn(finalState);
                unityBridge.send('TURN_START', { turn: finalState.turn });
                updateStateWithEvents(finalState);
                if (finalState.executionQueue.length > 0) {
                    setTimeout(runLoop, 50);
                    return;
                }
                setIsResolving(false);
            }
        };

        const t = setTimeout(runLoop, 100);
        return () => {
            active = false;
            clearTimeout(t);
        };

    }, [isResolving, updateStateWithEvents]);

    const restartGame = useCallback(() => {
        unityBridge.send('INIT_MATCH', { seed: Math.random() });
        setGameState(createInitialGameState());
        setEvents([]);
        setIsResolving(false);
        setIsWaiting(false);
    }, []);

    const resign = useCallback(() => {
        if (gameState.winner) return;
        unityBridge.send('MATCH_OVER', { winner: 'p2', reason: 'RESIGN' });
        setGameState(prev => ({ ...prev, winner: 'p2', phase: 'gameover' }));
    }, [gameState.winner]);

    return {
        gameState,
        events,
        isResolving,
        isWaiting,
        setIsWaiting,
        startResolution,
        restartGame,
        resign
    };
};

import React from 'react';
import { CardDefinition, CardInstance } from '../../types';
import { getCardVisualState } from '../../utils/cardStyles';
import { CardBadge } from './CardBadge';
import { GameText } from '../ui/GameText';

interface UnifiedCardViewProps {
    card: CardInstance | CardDefinition;
    size: 'xs' | 'sm' | 'md' | 'lg';
    hidden?: boolean;
    isDragging?: boolean;
    onPointerDown?: (e: React.PointerEvent) => void;
    onClick?: () => void;
    borderOverride?: string;
    variant?: string;
}

const SCALE_MAP = {
    xs: 0.5,   // Board
    sm: 0.75,  // Hand
    md: 1.0,   // Standard
    lg: 1.8    // Inspector
};

export const UnifiedCardView: React.FC<UnifiedCardViewProps> = ({
    card, size, hidden, isDragging, onPointerDown, onClick, borderOverride, variant
}) => {
    const scale = SCALE_MAP[size];
    const { 
        def, currentPower, currentCost, 
        powerColor, costColor, primaryColor, glowColor 
    } = getCardVisualState(card);

    const isInstance = (c: any): c is CardInstance => c && 'instanceId' in c;
    const instanceId = isInstance(card) ? card.instanceId : undefined;

    const baseWidth = 5.2; 

    if (hidden) {
        return (
            <div 
                className="w-full h-full bg-indigo-950 flex items-center justify-center overflow-hidden shadow-inner cursor-pointer"
                style={{ 
                    fontSize: `${scale}rem`,
                    borderRadius: '0.5em',
                    border: '0.12em solid rgba(129, 140, 248, 0.4)',
                    aspectRatio: '5/7'
                }}
                onPointerDown={onPointerDown}
                onClick={onClick}
            >
                <div className="w-1/2 h-1/2 rounded-full bg-indigo-500/20 animate-pulse blur-xl" />
                <div className="absolute font-black text-indigo-300/30 italic rotate-[-45deg] tracking-tighter" style={{ fontSize: '1.5em' }}>SNAP</div>
            </div>
        );
    }

    const finalBorderColor = borderOverride || primaryColor;

    return (
        <div
            onPointerDown={onPointerDown}
            onClick={onClick}
            className={`
                relative select-none touch-none overflow-hidden transition-opacity duration-200 group
                ${isDragging ? 'opacity-0' : 'opacity-100'}
            `}
            style={{ 
                width: `${baseWidth * scale}rem`,
                fontSize: `${scale}rem`, 
                aspectRatio: '5/7',
                borderRadius: '0.45em',
                boxShadow: `0 0 0.6em ${glowColor}, inset 0 0 0.5em rgba(0,0,0,0.6)`,
                border: `0.15em solid ${finalBorderColor}`,
                backgroundColor: '#0f172a'
            }}
        >
            <div className="absolute inset-0 bg-black">
                <img 
                    src={def.imageUrl} 
                    alt={def.name} 
                    className="w-full h-full object-cover pointer-events-none transition-transform duration-700 [@media(hover:hover)]:group-hover:scale-105 opacity-90" 
                />
            </div>

            <div className="absolute inset-0 bg-gradient-to-b from-black/20 via-transparent to-black/70 pointer-events-none" />
            <div className="absolute inset-0 border border-white/10 pointer-events-none rounded-[inherit]" />

            <CardBadge instanceId={instanceId} value={currentCost} type="cost" colorClass={costColor} />
            <CardBadge instanceId={instanceId} value={currentPower} type="power" colorClass={powerColor} />

            <div 
                className="absolute inset-x-0 pointer-events-none flex flex-col items-center justify-end bg-gradient-to-t from-black via-black/90 to-transparent"
                style={{ 
