import React from 'react';
import { GameText } from './GameText';

interface GenomeBadgeProps {
    level: number;
    className?: string;
}

/**
 * GENOME BADGE (Collection Level)
 * Rebuilt to match the HexBadge visual language but with a variable-width 
 * "Tablet" geometry to support 1 to 5+ digit levels.
 * Height calibrated to 2.2rem to match SlantedButton perceived height.
 */
export const GenomeBadge: React.FC<GenomeBadgeProps> = ({ level, className = '' }) => {
    const digits = level.toString().length;
    // Balanced horizontal scaling for the 2.2rem height
    // Increased base width and multiplier slightly to accommodate larger verticality
    const widthRem = Math.max(2.6, 1.4 + (digits * 0.45));

    return (
        <div 
            className={`relative h-[2.2rem] flex items-center shrink-0 drop-shadow-[0_2px_4px_rgba(0,0,0,0.6)] ${className}`}
            style={{ width: `${widthRem}rem` }}
        >
            {/* SVG ASSET LAYER */}
            <svg 
                viewBox="0 0 100 100" 
                preserveAspectRatio="none" 
                className="absolute inset-0 w-full h-full overflow-visible"
            >
                <defs>
                    <linearGradient id="geno_bg_primary" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="0%" stopColor="#4338ca" />
                        <stop offset="100%" stopColor="#1e1b4b" />
                    </linearGradient>

                    <clipPath id="genoClip">
                        <path d="M5 10 L95 10 L100 50 L95 90 L5 90 L0 50 Z" />
                    </clipPath>

                    <filter id="genoInnerShadow">
                        <feComponentTransfer in="SourceAlpha">
                            <feFuncA type="table" tableValues="1 0" />
                        </feComponentTransfer>
                        <feGaussianBlur stdDeviation="2.5" />
                        <feOffset dx="0" dy="1.5" result="offsetblur" />
                        <feFlood floodColor="black" floodOpacity="0.7" />
                        <feComposite in2="offsetblur" operator="in" />
                        <feComposite in2="SourceAlpha" operator="in" />
                        <feMerge>
                            <feMergeNode />
                            <feMergeNode in="SourceGraphic" />
                        </feMerge>
                    </filter>
                </defs>

                {/* THE FRAME: Scaled Hex Tablet */}
                <path 
                    d="M5 5 L95 5 L100 50 L95 95 L5 95 L0 50 Z" 
                    fill="url(#geno_bg_primary)"
                    filter="url(#genoInnerShadow)"
                    stroke="#6366f1" 
                    strokeWidth="4" 
                    strokeLinejoin="round"
                />

                {/* Inner Highlight Detail */}
                <path 
                    d="M7 15 L93 15" 
                    stroke="#a5b4fc" 
                    strokeWidth="1.5" 
                    strokeLinecap="round"
                    opacity="0.3"
                />

                {/* Visual Glint */}
                <path 
                    d="M-20 42 L120 -18 L120 42 L-20 102 Z" 
                    fill="white" 
                    fillOpacity="0.05" 
                    clipPath="url(#genoClip)"
                    pointerEvents="none"
                />
            </svg>

            {/* THE DATA READOUT */}
            <div className="relative z-10 w-full h-full flex items-center justify-center px-2">
                <GameText 
                    text={level.toLocaleString()} 
