  name: string;
  rarity: CardRarity;
  baseCost: number;
  basePower: number;
  tags: string[]; 
  baseText: string;
  effect: string; 
  imageUrl: string;
  flavorText?: string;

  sfxOnPlay?: SfxKey;   
  sfxOnReveal?: SfxKey; 
  vfxOnReveal?: VfxKey; 
}

export interface StatModifier {
  source: string; 
  value: number;
  type: "BASE" | "PERMANENT" | "CONTINUOUS";
}

export interface CardInstance {
  instanceId: string;
  definitionId: string;
  owner: PlayerID;

  zone: Zone;
  laneIndex: number | null;
  slotIndex: number | null;
  faceUp: boolean;
  turnPlayed: number | null;
