interface GenomeBadgeProps {
    level: number;
    className?: string;
    onClick?: () => void;
}

/**
 * GENOME BADGE (Collection Level)
 * Optimized for high-digit level numbers in a compact header.
 * Uses 'k' notation for levels >= 10,000 to reclaim space.
 * Now supports onClick for progression track navigation.
 */
export const GenomeBadge: React.FC<GenomeBadgeProps> = ({ level, className = '', onClick }) => {
    const formattedLevel = level >= 10000 
        ? (level / 1000).toFixed(1).replace(/\.0$/, '') + 'k'
        : level.toString();

    return (
        <SlantedButton 
            variant="primary" 
            size="xs"
            className={`!w-[16vw] max-w-[4.5rem] shadow-lg [&_div.z-20]:!px-0 ${className}`}
            onClick={onClick}
        >
            {formattedLevel}
        </SlantedButton>
    );
};

import React, { useRef, useEffect, useMemo } from 'react';
import { StandardHeader } from '../ui/StandardHeader';
import { ScreenKey, CardDefinition } from '../../types';
import { useUser } from '../../contexts/UserContext';
import { HexBadge } from '../ui/HexBadge';
import { CARDS } from '../../constants';
import { RewardIconGraphic } from '../ui/RewardItemVisual';

interface ProgressionScreenProps {
    onNavigate: (s: ScreenKey) => void;
}

/**
 * SECTOR GRID LAYOUT
 * A high-fidelity 3-column staggered grid for collection levels.
 * Replaces the 'lame' linear snap layout with a technical helix path.
 */
export const ProgressionScreen: React.FC<ProgressionScreenProps> = ({ onNavigate }) => {
    const { user, inspect } = useUser();
    const scrollRef = useRef<HTMLDivElement>(null);
    const activeRef = useRef<HTMLDivElement>(null);

    // Generate a window of levels around the user's current level
    const trackItems = useMemo(() => {
        // Levels 0 to (user.level + 200) in steps of 2 or 4
        const items = [];
        const maxLevel = Math.max(user.level + 48, 100);

        for (let lvl = 0; lvl <= maxLevel; lvl += 4) {
            let type: 'card' | 'credits' | 'gold' | 'booster' = 'credits';
            let amount: string | number = 50;
            let cardDef: CardDefinition | undefined;

            if (lvl % 48 === 0) {
                type = 'card';
                cardDef = CARDS[Math.floor((lvl / 48) % CARDS.length)];
            } else if (lvl % 12 === 0) {
                type = 'gold';
                amount = 100;
            } else if (lvl % 8 === 0) {
                type = 'booster';
                amount = 10;
            }

            items.push({
                level: lvl,
                type,
                amount,
                cardDef,
                isClaimed: lvl < user.level,
                isActive: lvl === user.level,
                isLocked: lvl > user.level
            });
        }
        return items;
    }, [user.level]);

    useEffect(() => {
        const timer = setTimeout(() => {
            if (activeRef.current && scrollRef.current) {
                const container = scrollRef.current;
                const active = activeRef.current;
                const top = active.offsetTop - (container.offsetHeight / 2) + (active.offsetHeight / 2);
                container.scrollTo({ top, behavior: 'smooth' });
            }
        }, 300);
        return () => clearTimeout(timer);
    }, []);

    return (
        <div className="w-full h-full flex flex-col bg-slate-950 overflow-hidden relative">
            {/* Background Tech Mesh */}
            <div className="absolute inset-0 opacity-10 pointer-events-none bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')]"></div>

            <StandardHeader 
                title="PROGRESSION" 
                leftContent={
                    <button 
                        onClick={() => onNavigate('DECK')}
                        className="w-8 h-8 rounded-full bg-white/5 border border-white/10 flex items-center justify-center text-white active:scale-90 transition-transform"
                    >
                        <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M15 19l-7-7 7-7" /></svg>
                    </button>
                }
            />

            <div 
                ref={scrollRef}
                className="flex-1 overflow-y-auto p-4 space-y-2 pb-32 relative"
            >
                {/* Visual Helix Connector - Drawn between nodes */}
                <div className="absolute left-1/2 top-0 bottom-0 w-px bg-indigo-500/20 -translate-x-1/2 pointer-events-none"></div>

                {trackItems.map((item, idx) => {
                    // Column logic: 0 = Left, 1 = Center, 2 = Right
                    // Milestone (Cards) are always Center. Resources zig-zag.
                    const isMilestone = item.type === 'card';
                    const col = isMilestone ? 1 : (idx % 2 === 0 ? 0 : 2);

                    const colClasses = [
                        "justify-start pr-12",
                        "justify-center",
                        "justify-end pl-12"
                    ][col];

                    return (
                        <div 
                            key={item.level} 
                            ref={item.isActive ? activeRef : null}
                            className={`flex w-full ${colClasses} relative py-4`}
                        >
                            {/* Path Connecting Lines (Visual abstraction) */}
                            {idx < trackItems.length - 1 && (
                                <div className="absolute left-1/2 top-1/2 h-16 w-16 pointer-events-none opacity-20 border-l-2 border-indigo-500 -translate-x-1/2 -skew-x-12"></div>
                            )}

                            <div 
                                className={`
                                    relative flex flex-col items-center group cursor-pointer transition-all duration-300
                                    ${item.isLocked ? 'opacity-40 grayscale blur-[1px]' : 'opacity-100'}
                                    ${item.isActive ? 'scale-110' : 'active:scale-95'}
                                `}
                                onClick={() => inspect({
                                    type: 'level_info',
                                    level: item.level,
                                    rewardType: item.type,
                                    rewardAmount: item.amount,
                                    isClaimed: item.isClaimed,
                                    cardDef: item.cardDef
                                })}
                            >
                                {/* Level Badge */}
                                <div className="absolute -top-3 -right-3 z-20">
                                    <HexBadge 
                                        variant={item.isClaimed ? "secondary" : (item.isActive ? "primary" : "secondary")}
                                        size="xs"
                                        glow={item.isActive}
                                    >
                                        {item.level}
                                    </HexBadge>
                                </div>

                                {/* Reward Node */}
                                <div className={`
                                    w-16 h-16 rounded-xl flex items-center justify-center border-2 transition-all duration-500 shadow-2xl relative overflow-hidden
                                    ${item.isClaimed ? 'bg-slate-900 border-slate-700' : ''}
                                    ${item.isActive ? 'bg-indigo-600 border-indigo-400 ring-4 ring-indigo-500/20' : 'bg-slate-800 border-slate-600'}
                                `}>
                                    {/* Reward Visual */}
                                    <div className="scale-75">
                                        <RewardIconGraphic type={item.type} cardDef={item.cardDef} size="sm" />
                                    </div>

                                    {/* Scanline Overlay for Active Node */}
                                    {item.isActive && (
                                        <div className="absolute inset-0 bg-gradient-to-b from-transparent via-white/10 to-transparent h-4 w-full -top-4 animate-[scanline_2s_linear_infinite]"></div>
                                    )}

                                    {/* Claimed Indicator */}
                                    {item.isClaimed && (
                                        <div className="absolute inset-0 bg-black/40 flex items-center justify-center">
                                             <svg className="w-6 h-6 text-emerald-400" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={4}><path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" /></svg>
                                        </div>
                                    )}
                                </div>

                                {/* Label */}
                                <div className="mt-2 text-center">
                                    <span className={`text-[0.45rem] font-black uppercase tracking-widest ${item.isActive ? 'text-indigo-300' : 'text-slate-500'}`}>
                                        {isMilestone ? "MILESTONE" : item.type}
                                    </span>
                                </div>
                            </div>
                        </div>
                    );
                })}

                {/* Vertical Text Decoration */}
                <div className="fixed left-2 top-1/2 -translate-y-1/2 -rotate-90 origin-left pointer-events-none">
                    <span className="text-4xl font-black text-white/5 uppercase tracking-[0.5em] whitespace-nowrap">
                        Helix Sector Trace
                    </span>
                </div>
            </div>

            <style>{`
                @keyframes scanline {
                    0% { top: -20%; }
                    100% { top: 120%; }
                }
            `}</style>
        </div>
    );
};

import React, { useState, useCallback, useMemo, useRef, useEffect } from 'react';
import { StandardHeader } from '../ui/StandardHeader';
import { DeckSelector } from '../game/DeckSelector';
