import React, { useRef, useEffect, useMemo, useState } from 'react';
import { StandardHeader } from '../ui/StandardHeader';
import { ScreenKey, CardDefinition } from '../../types';
import { useUser } from '../../contexts/UserContext';
import { CARDS } from '../../constants';
import { RewardIconGraphic } from '../ui/RewardItemVisual';

interface ProgressionScreenProps {
    onNavigate: (s: ScreenKey) => void;
}

/**
 * THE GALACTIC ATLAS
 * A 2D spatial progression map that treats collection levels as coordinates 
 * in a star system rather than a boring list.
 */
export const ProgressionScreen: React.FC<ProgressionScreenProps> = ({ onNavigate }) => {
    const { user, inspect } = useUser();
    const mapRef = useRef<HTMLDivElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);

    // Windowed Rendering: Only calculate nodes around current level to prevent DOM bloat
    const atlasNodes = useMemo(() => {
        const nodes = [];
        const currentLvl = user.level;

        // We render a "Sector" of +/- 60 levels (120 levels total)
        const start = Math.max(0, Math.floor(currentLvl / 4) * 4 - 60);
        const end = start + 120;

        for (let lvl = start; lvl <= end; lvl += 4) {
            let type: 'card' | 'credits' | 'gold' | 'booster' = 'credits';
            let amount: string | number = 50;
            let cardDef: CardDefinition | undefined;

            if (lvl % 48 === 0) {
                type = 'card';
                cardDef = CARDS[Math.floor((lvl / 48) % CARDS.length)];
            } else if (lvl % 12 === 0) {
                type = 'gold';
                amount = 100;
            } else if (lvl % 8 === 0) {
                type = 'booster';
                amount = 10;
            }

            // Spatial Logic: Calculate X, Y based on level
            // Horizontal Spine with sin-wave variance
            const x = (lvl - start) * 120; 
            const y = Math.sin(lvl * 0.1) * 100; // Slant/Wave

            // Side-orbits for resources
            const isResource = type !== 'card';
            const xOffset = isResource ? (lvl % 8 === 0 ? 40 : -40) : 0;
            const yOffset = isResource ? (lvl % 8 === 0 ? 80 : -80) : 0;

            nodes.push({
                level: lvl,
                type,
                amount,
                cardDef,
                isClaimed: lvl < currentLvl,
                isActive: lvl === Math.floor(currentLvl / 4) * 4,
                isLocked: lvl > currentLvl,
                x: x + xOffset,
                y: 150 + y + yOffset // Center in vertical container
            });
        }
        return nodes;
    }, [user.level]);

    // Initial positioning: Center on the active node
    useEffect(() => {
        const timer = setTimeout(() => {
            if (containerRef.current) {
                const active = containerRef.current.querySelector('[data-active="true"]') as HTMLElement;
                if (active && mapRef.current) {
                    const map = mapRef.current;
                    const left = active.offsetLeft - (map.offsetWidth / 2) + (active.offsetWidth / 2);
                    const top = active.offsetTop - (map.offsetHeight / 2) + (active.offsetHeight / 2);
                    map.scrollTo({ left, top, behavior: 'auto' });
                }
            }
        }, 100);
        return () => clearTimeout(timer);
    }, [user.level]);

    return (
        <div className="w-full h-full flex flex-col bg-slate-950 overflow-hidden relative">
            {/* Background Parallax Layer */}
            <div className="absolute inset-0 pointer-events-none opacity-20">
                <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/stardust.png')] animate-[pulse_10s_infinite]"></div>
                <div className="absolute inset-0 bg-gradient-to-tr from-indigo-900/40 via-transparent to-purple-900/40"></div>
            </div>

            <StandardHeader 
                title="GALACTIC ATLAS" 
                leftContent={
                    <button 
                        onClick={() => onNavigate('DECK')}
                        className="w-8 h-8 rounded-full bg-white/5 border border-white/10 flex items-center justify-center text-white active:scale-90 transition-transform"
                    >
                        <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M15 19l-7-7 7-7" /></svg>
                    </button>
                }
            />

            {/* 2D SPATIAL MAP CONTAINER */}
            <div 
                ref={mapRef}
                className="flex-1 overflow-auto relative scroll-smooth cursor-grab active:cursor-grabbing select-none scrollbar-hide"
            >
                <div 
                    ref={containerRef}
                    className="relative w-[15000px] h-[600px]" // Wide field for horizontal journey
                >
                    {/* SVG PATH LAYER (Drawn behind nodes) */}
                    <svg className="absolute inset-0 w-full h-full pointer-events-none opacity-30">
                        <defs>
                            <filter id="glow">
                                <feGaussianBlur stdDeviation="2" result="coloredBlur"/>
                                <feMerge>
                                    <feMergeNode in="coloredBlur"/><feMergeNode in="SourceGraphic"/>
                                </feMerge>
                            </filter>
                        </defs>
                        <polyline
                            points={atlasNodes.map(n => `${n.x + 32},${n.y + 32}`).join(' ')}
                            fill="none"
                            stroke="rgba(99, 102, 241, 0.5)"
                            strokeWidth="2"
                            strokeDasharray="8,4"
                            filter="url(#glow)"
                        />
                    </svg>

                    {/* RENDER NODES */}
                    {atlasNodes.map((node) => (
                        <div 
                            key={node.level}
                            data-active={node.isActive}
                            className={`
                                absolute flex flex-col items-center transition-all duration-500
                                ${node.isLocked ? 'opacity-40 grayscale blur-[0.5px]' : 'opacity-100'}
                                ${node.isActive ? 'z-50 scale-110' : 'z-10'}
                            `}
                            style={{ left: node.x, top: node.y }}
                            onClick={() => inspect({
                                type: 'level_info',
                                level: node.level,
                                rewardType: node.type,
                                rewardAmount: node.amount,
                                isClaimed: node.isClaimed,
                                cardDef: node.cardDef
                            })}
                        >
                            {/* Technical Readout Label */}
                            <div className="absolute -top-6 whitespace-nowrap">
                                <span className={`text-[0.4rem] font-mono font-black uppercase tracking-tighter ${node.isActive ? 'text-indigo-400' : 'text-slate-600'}`}>
                                    LVL_{node.level} // SYST_{node.type.substring(0, 4)}
                                </span>
                            </div>

                            {/* Node Core */}
                            <div className={`
                                w-14 h-14 flex items-center justify-center relative rounded-sm border-2 transition-all duration-300
                                ${node.isClaimed ? 'bg-slate-900 border-slate-700' : 'bg-slate-800 border-indigo-500/50'}
                                ${node.isActive ? 'bg-indigo-600 border-indigo-300 shadow-[0_0_25px_rgba(99,102,241,0.6)]' : ''}
                                ${node.type === 'card' ? 'rotate-45' : ''}
                            `}>
                                <div className={`scale-50 ${node.type === 'card' ? '-rotate-45' : ''}`}>
                                    <RewardIconGraphic type={node.type} cardDef={node.cardDef} size="sm" />
                                </div>

                                {node.isClaimed && (
                                    <div className="absolute -bottom-1 -right-1 w-5 h-5 bg-emerald-500 rounded-full flex items-center justify-center border-2 border-slate-950">
                                         <svg className="w-3 h-3 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={5}><path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" /></svg>
                                    </div>
                                )}

                                {node.isActive && (
                                    <>
                                        <div className="absolute inset-0 bg-white/10 animate-pulse"></div>
                                        <div className="absolute -inset-2 border border-indigo-400/20 rounded-lg animate-[ping_3s_infinite]"></div>
                                    </>
                                )}
                            </div>

                            {/* Resource Title (Subtle) */}
                            <div className="mt-1">
                                <span className={`text-[0.45rem] font-black uppercase tracking-[0.2em] ${node.isActive ? 'text-white' : 'text-slate-500'}`}>
                                    {node.type === 'card' ? 'STATION' : node.type}
                                </span>
                            </div>
                        </div>
                    ))}
                </div>

                {/* HUD Overlay: Sector Info */}
                <div className="fixed bottom-24 left-6 pointer-events-none">
                     <div className="flex flex-col border-l-2 border-indigo-500/30 pl-3">
                        <span className="text-[0.5rem] font-black text-indigo-400 uppercase tracking-widest">Navigation HUD</span>
                        <span className="text-xl font-black text-white italic uppercase tracking-tighter leading-none">SECTOR {Math.floor(user.level / 100)}</span>
                        <span className="text-[0.45rem] font-mono text-slate-500 uppercase mt-1">COORD: {user.level}.00 // AZIMUTH: 142.4</span>
                     </div>
                </div>
            </div>

            {/* Bottom Controls: Snap-back to player */}
            <div className="absolute bottom-6 right-6 z-50">
                 <button 
                    onClick={() => {
                        const active = containerRef.current?.querySelector('[data-active="true"]') as HTMLElement;
                        if (active && mapRef.current) {
                            mapRef.current.scrollTo({ left: active.offsetLeft - (mapRef.current.offsetWidth/2), top: active.offsetTop - (mapRef.current.offsetHeight/2), behavior: 'smooth' });
                        }
                    }}
                    className="w-12 h-12 rounded-xl bg-indigo-600 border-2 border-indigo-300 flex items-center justify-center text-white shadow-2xl active:scale-90 transition-transform"
                 >
                    <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 10l7-7m0 0l7 7m-7-7v18" /></svg>
                 </button>
            </div>

            <style>{`
                .scrollbar-hide::-webkit-scrollbar { display: none; }
                .scrollbar-hide { -ms-overflow-style: none; scrollbar-width: none; }
            `}</style>
        </div>
    );
};

import React, { useMemo } from 'react';
