interface GeneratorProps {
    label: string;
    type: 'card' | 'gold' | 'credits' | 'booster';
    currentLevel: number;
    cycleSize: number;
    color: string;
    onInspect: (reward: any) => void;
}

const Generator: React.FC<GeneratorProps> = ({ label, type, currentLevel, cycleSize, color, onInspect }) => {
    const progress = currentLevel % cycleSize;
    const percent = (progress / cycleSize) * 100;
    const isReady = progress === 0 && currentLevel > 0;

    // Calculate what the reward is
    const rewardAmount = useMemo(() => {
        if (type === 'card') return 'NEW UNIT';
        if (type === 'gold') return 100;
        if (type === 'credits') return 50;
        return 10;
    }, [type]);

    const cardDef = useMemo(() => {
        if (type !== 'card') return undefined;
        return CARDS[Math.floor((currentLevel / cycleSize) % CARDS.length)];
    }, [type, currentLevel, cycleSize]);

    return (
        <div 
            className="flex-1 flex flex-col items-center group cursor-pointer"
            onClick={() => onInspect({
                type: 'level_info',
                level: currentLevel,
                rewardType: type,
                rewardAmount: rewardAmount,
                cardDef: cardDef
            })}
        >
            {/* Telemetry Label */}
            <div className="mb-2 flex flex-col items-center">
                <span className="text-[0.4rem] font-mono font-black text-slate-500 uppercase tracking-widest">{label}</span>
                <span className={`text-[0.6rem] font-mono font-black ${color} tracking-tighter`}>
                    {percent.toFixed(1)}% SYNC
                </span>
            </div>

            {/* Physical Tube Container */}
            <div className="flex-1 w-full max-w-[3.5rem] bg-black/40 rounded-full border-x border-t border-white/5 relative overflow-hidden shadow-[inset_0_0_20px_rgba(0,0,0,0.8)] flex flex-col justify-end p-1">
                {/* Plasma Fill */}
                <div 
                    className={`w-full rounded-full transition-all duration-1000 ease-out relative ${color.replace('text-', 'bg-')}`}
                    style={{ 
                        height: `${percent}%`,
                        boxShadow: `0 0 20px ${color.includes('indigo') ? 'rgba(99,102,241,0.4)' : color.includes('amber') ? 'rgba(245,158,11,0.4)' : 'rgba(59,130,246,0.4)'}`
                    }}
                >
                    {/* Bubbles / Energy Particles */}
                    <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/stardust.png')] opacity-30 animate-pulse"></div>
                    <div className="absolute top-0 left-0 right-0 h-4 bg-white/20 blur-sm rounded-full -translate-y-1/2"></div>
