                <div className="absolute inset-0 flex flex-col justify-between py-8 px-1 pointer-events-none opacity-20">
                    {Array.from({ length: 10 }).map((_, i) => (
                        <div key={i} className="w-full h-px bg-white"></div>
                    ))}
                </div>
            </div>

            {/* Reward Preview Socket */}
            <div className="mt-4 w-12 h-12 rounded-lg bg-slate-900 border border-slate-800 flex items-center justify-center relative shadow-lg group-hover:border-white/20 transition-colors">
                <div className="scale-50">
                    <RewardIconGraphic type={type} cardDef={cardDef} size="sm" />
                </div>
                {isReady && (
                    <div className="absolute -inset-1 border border-white/40 rounded-lg animate-ping"></div>
                )}
            </div>

            <div className="mt-2">
                 <span className={`text-[0.45rem] font-black uppercase tracking-[0.2em] ${isReady ? 'text-white' : 'text-slate-600'}`}>
                    {isReady ? 'READY' : 'CHARGING'}
                 </span>
            </div>
        </div>
    );
};

