import { useUser } from '../../contexts/UserContext';
import { CARDS } from '../../constants';
import { RewardIconGraphic } from '../ui/RewardItemVisual';
import { SeasonProgress } from '../ui/SeasonProgress';

interface RewardCycle {
    label: string;
    type: 'booster' | 'credits' | 'gold' | 'box' | 'card';
    cycleSize: number;
    color: string;
}

const CYCLES: RewardCycle[] = [
    { label: 'Boosters', type: 'booster', cycleSize: 4, color: 'text-purple-400' },
    { label: 'Credits', type: 'credits', cycleSize: 12, color: 'text-blue-400' },
    { label: 'Gold', type: 'gold', cycleSize: 24, color: 'text-amber-400' },
    { label: 'Omega Box', type: 'box', cycleSize: 32, color: 'text-indigo-400' },
    { label: 'New Card', type: 'card', cycleSize: 48, color: 'text-emerald-400' },
];

interface ProgressionScreenProps {
    onNavigate: (screen: ScreenKey) => void;
}

export const ProgressionScreen: React.FC<ProgressionScreenProps> = ({ onNavigate }) => {
    const { user, inspect } = useUser();

    const tracks = useMemo(() => {
        return CYCLES.map(cycle => {
            const progress = user.level % cycleSize;
            const remaining = cycle.cycleSize - (progress === 0 && user.level > 0 ? 0 : progress);
            const percent = ((cycle.cycleSize - remaining) / cycle.cycleSize) * 100;

            let cardDef: CardDefinition | undefined;
            if (cycle.type === 'card') {
                cardDef = CARDS[Math.floor((user.level / cycle.cycleSize) % CARDS.length)];
            }

            return {
                ...cycle,
                remaining,
                percent,
                cardDef,
                amount: cycle.type === 'gold' ? 100 : cycle.type === 'credits' ? 50 : 10
            };
        });
    }, [user.level]);

    // Find the reward closest to completion
    const nextReward = useMemo(() => {
        return [...tracks].sort((a, b) => a.remaining - b.remaining)[0];
    }, [tracks]);

    const handleInspectReward = (track: typeof tracks[0]) => {
        if (track.type === 'box') {
            inspect({
                type: 'box',
                boxType: 'MEGA',
                title: 'Omega Box',
                description: 'Contains a guaranteed variant and massive resources.'
            });
        } else {
            inspect({
                type: 'level_info',
                level: user.level + track.remaining,
                rewardType: track.type === 'box' ? 'credits' : track.type, // Fallback for box icon
                rewardAmount: track.type === 'card' ? 'NEW UNIT' : track.amount,
                cardDef: track.cardDef
            });
        }
    };

    return (
        <div className="w-full h-full flex flex-col bg-slate-950 overflow-hidden relative">
            <StandardHeader 
                title="COLLECTION TRACK" 
                leftContent={
                    <button 
                        onClick={() => onNavigate('DECK')}
                        className="w-8 h-8 rounded-full bg-white/5 border border-white/10 flex items-center justify-center text-white active:scale-90 transition-transform"
                    >
                        <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M15 19l-7-7 7-7" /></svg>
                    </button>
                }
            />

            <div className="flex-1 flex flex-col p-4 space-y-8 overflow-y-auto pb-32">

                {/* UP NEXT HERO SECTION */}
                <div 
                    className="bg-indigo-600/10 border border-indigo-500/30 rounded-2xl p-6 flex flex-col items-center relative overflow-hidden group cursor-pointer"
                    onClick={() => handleInspectReward(nextReward)}
                >
                    <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-indigo-400 to-transparent"></div>

                    <span className="text-[0.6rem] font-black text-indigo-400 uppercase tracking-[0.4em] mb-4">Up Next In {nextReward.remaining} Levels</span>

                    <div className="relative mb-4 transition-transform duration-500 group-hover:scale-110">
