                            <div className="w-20 h-20 bg-indigo-500/20 rounded-xl border-2 border-indigo-400 flex items-center justify-center shadow-[0_0_30px_rgba(99,102,241,0.4)]">
                                <span className="text-4xl">📦</span>
                            </div>
                        ) : (
                            <RewardIconGraphic type={nextReward.type as any} size="lg" cardDef={nextReward.cardDef} />
                        )}
                    </div>

                    <div className="text-center">
                        <h3 className="text-xl font-black text-white italic tracking-tighter uppercase leading-none">
                            {nextReward.type === 'card' ? nextReward.cardDef?.name : `${nextReward.amount} ${nextReward.label}`}
                        </h3>
                        <p className="text-[0.5rem] font-bold text-slate-500 uppercase tracking-widest mt-1">Estimated Arrival: Level {user.level + nextReward.remaining}</p>
                    </div>
                </div>

                {/* THE 5 PROGRESS TRACKS */}
                <div className="space-y-6">
                    <div className="flex items-center justify-between px-1">
                        <span className="text-[0.55rem] font-black text-slate-500 uppercase tracking-[0.3em]">Matrix Synchronization</span>
                        <span className="text-[0.55rem] font-mono text-indigo-500 font-bold">LVL {user.level}</span>
                    </div>

                    <div className="space-y-5">
                        {tracks.map((track) => (
                            <div 
                                key={track.type} 
                                className="flex flex-col gap-2 group cursor-pointer"
                                onClick={() => handleInspectReward(track)}
                            >
                                <div className="flex items-center justify-between px-1">
                                    <span className={`text-[0.6rem] font-black uppercase tracking-widest ${track.color}`}>
                                        {track.label}
                                    </span>
                                    <span className="text-[0.5rem] font-black text-slate-500 uppercase">
                                        {track.remaining} Levels Left
                                    </span>
                                </div>

                                <div className="flex items-center gap-3">
                                    <div className="flex-1">
                                        <SeasonProgress 
                                            level={Math.floor(user.level / track.cycleSize)} 
                                            progressPercent={track.percent} 
                                            className="!max-w-none scale-100 origin-left"
                                        />
                                    </div>
                                    <div className={`w-10 h-10 rounded-lg bg-slate-900 border border-slate-800 flex items-center justify-center transition-colors group-hover:border-white/20`}>
                                        <div className="scale-[0.4]">
                                            {track.type === 'box' ? (
                                                <span className="text-3xl grayscale group-hover:grayscale-0 transition-all">📦</span>
                                            ) : (
                                                <RewardIconGraphic type={track.type as any} size="sm" cardDef={track.cardDef} />
                                            )}
                                        </div>
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>

            </div>

            {/* Subliminal Decor */}
            <div className="absolute bottom-6 left-1/2 -translate-x-1/2 pointer-events-none opacity-10">
                <div className="text-[0.4rem] font-black uppercase tracking-[1em] whitespace-nowrap">
                    Authorized Progression Protocol // {user.id}
                </div>
            </div>
        </div>
    );
};

