                                        className={`h-full bg-gradient-to-r ${track.color} transition-all duration-1000 ease-out`}
                                        style={{ width: `${track.percent}%` }}
                                    />
                                    <div className="absolute inset-0 flex items-center justify-end pr-3">
                                        <span className="text-[0.45rem] font-bold text-white/30 italic uppercase">{track.label}</span>
                                    </div>
                                </div>
                                <div className="absolute -right-3 top-1/2 -translate-y-1/2 z-40 scale-110 group-hover:scale-150 transition-transform">
                                     {track.type === 'box' ? <span className="text-2xl drop-shadow-xl">📦</span> : <RewardIconGraphic type={track.type as any} size="sm" cardDef={track.cardDef} />}
                                </div>
