                    <div className="bg-slate-900/40 rounded-xl border border-white/5 divide-y divide-white/5 max-h-48 overflow-y-auto">
                        {history.map((item, i) => (
                            <div key={i} className="flex items-center justify-between p-3">
                                <div className="flex flex-col">
                                    <span className="text-[0.65rem] font-black text-white italic uppercase tracking-tighter">{item.reward}</span>
                                    <span className="text-[0.45rem] font-bold text-slate-600 uppercase">{item.date}</span>
