            </div>

            <div className="flex-1 overflow-y-auto px-4 space-y-8 pb-32 pt-4">

                {/* HERO SECTION */}
                <div className="space-y-4">
                    <h3 className="text-[0.6rem] font-black text-indigo-400 uppercase tracking-[0.3em] px-1">Next Reward</h3>
                    <div 
                        className="relative h-16 flex items-center cursor-pointer group active:scale-[0.99] transition-transform"
                        onClick={() => handleInspect(nextHero)}
                    >
                        {/* THE BAR (Mimics Season Pass) */}
                        <div className="absolute left-6 right-6 h-6 bg-indigo-950/60 border border-indigo-400/40 rounded-full overflow-hidden shadow-2xl z-10">
                            <div 
