                        </div>

                        {/* OVERLAPPING HEX */}
                        <div className="absolute left-0 z-50 drop-shadow-2xl">
                            <HexBadge variant="primary" size="md" glow>{nextHero.rewardIndex}</HexBadge>
                        </div>

                        {/* FLOATING ICON (Large) */}
                        <div className="absolute -right-2 top-1/2 -translate-y-1/2 z-50 transition-transform group-hover:scale-110">
                             <RewardItemVisual 
                                type={nextHero.type as any} 
                                amount={nextHero.type === 'card' ? 'UNIT' : nextHero.amount} 
