interface RewardCycle {
    label: string;
    type: 'booster' | 'credits' | 'gold' | 'box' | 'card';
    cycleSize: number;
    color: string;
}

// FIXED ORDER: Boosters, Credits, Gold, Omega Box, Card
const CYCLES: RewardCycle[] = [
    { label: 'Boosters', type: 'booster', cycleSize: 4, color: 'from-purple-600 to-purple-400' },
    { label: 'Credits', type: 'credits', cycleSize: 12, color: 'from-blue-600 to-blue-400' },
    { label: 'Gold', type: 'gold', cycleSize: 24, color: 'from-amber-600 to-amber-400' },
    { label: 'Omega Box', type: 'box', cycleSize: 32, color: 'from-indigo-600 to-indigo-400' },
    { label: 'New Card', type: 'card', cycleSize: 48, color: 'from-emerald-600 to-emerald-400' },
];

interface ProgressionScreenProps {
    onNavigate: (screen: ScreenKey) => void;
}

export const ProgressionScreen: React.FC<ProgressionScreenProps> = ({ onNavigate }) => {
    const { user, inspect } = useUser();

    const tracks = useMemo(() => {
        return CYCLES.map(cycle => {
            const progress = user.level % cycle.cycleSize;
            const remaining = cycle.cycleSize - (progress === 0 && user.level > 0 ? 0 : progress);
            const percent = ((cycle.cycleSize - remaining) / cycle.cycleSize) * 100;
            const rewardIndex = Math.floor(user.level / cycle.cycleSize) + 1;

            let cardDef: CardDefinition | undefined;
            if (cycle.type === 'card') {
                cardDef = CARDS[Math.floor((user.level / cycle.cycleSize) % CARDS.length)];
            }

            const unclaimedCount = Math.max(0, Math.floor(user.level / (cycle.cycleSize * 8)) - 1);

            return {
                ...cycle,
                currentXP: cycle.cycleSize - remaining,
                remaining,
                percent,
                rewardIndex,
                cardDef,
                unclaimedCount,
                amount: cycle.type === 'gold' ? 100 : cycle.type === 'credits' ? 50 : 10
            };
        });
    }, [user.level]);

    const nextHero = useMemo(() => {
        return [...tracks].sort((a, b) => a.remaining - b.remaining)[0];
    }, [tracks]);

    const handleInspect = (track: any) => {
        inspect({
            type: track.type === 'box' ? 'box' : 'level_info',
