import React, { useMemo } from 'react';
import { StandardHeader } from '../ui/StandardHeader';
import { ScreenKey, CardDefinition } from '../../types';
import { useUser } from '../../contexts/UserContext';
import { CARDS } from '../../constants';
import { RewardItemVisual } from '../ui/RewardItemVisual';
import { GameText } from '../ui/GameText';
import { HexBadge } from '../ui/HexBadge';

interface RewardCycle {
    label: string;
    type: 'booster' | 'credits' | 'gold' | 'box' | 'card';
    cycleSize: number;
    color: string;
}

// FIXED ORDER: Boosters, Credits, Gold, Omega Box, Card
const CYCLES: RewardCycle[] = [
    { label: 'Boosters', type: 'booster', cycleSize: 4, color: 'from-purple-600 to-purple-400' },
    { label: 'Credits', type: 'credits', cycleSize: 12, color: 'from-blue-600 to-blue-400' },
    { label: 'Gold', type: 'gold', cycleSize: 24, color: 'from-amber-600 to-amber-400' },
    { label: 'Omega Box', type: 'box', cycleSize: 32, color: 'from-indigo-600 to-indigo-400' },
    { label: 'New Card', type: 'card', cycleSize: 48, color: 'from-emerald-600 to-emerald-400' },
];

interface ProgressionScreenProps {
    onNavigate: (screen: ScreenKey) => void;
}

export const ProgressionScreen: React.FC<ProgressionScreenProps> = ({ onNavigate }) => {
    const { user, inspect } = useUser();

    const tracks = useMemo(() => {
        return CYCLES.map(cycle => {
            const progress = user.level % cycle.cycleSize;
            const remaining = cycle.cycleSize - (progress === 0 && user.level > 0 ? 0 : progress);
            const percent = ((cycle.cycleSize - remaining) / cycle.cycleSize) * 100;
            const rewardIndex = Math.floor(user.level / cycle.cycleSize) + 1;

            let cardDef: CardDefinition | undefined;
            if (cycle.type === 'card') {
                cardDef = CARDS[Math.floor((user.level / cycle.cycleSize) % CARDS.length)];
            }

            const unclaimedCount = Math.max(0, Math.floor(user.level / (cycle.cycleSize * 8)) - 1);

            const amount = cycle.type === 'gold' ? 100 : cycle.type === 'credits' ? 50 : 10;

            // Mapping types to requested display names with amounts
            let typeLabel = '';
            if (cycle.type === 'booster') typeLabel = `${amount} boosters`;
            else if (cycle.type === 'credits') typeLabel = `${amount} credits`;
            else if (cycle.type === 'gold') typeLabel = `${amount} gold`;
            else if (cycle.type === 'box') typeLabel = `omega box`;
            else if (cycle.type === 'card') typeLabel = '';

            return {
                ...cycle,
                currentXP: cycle.cycleSize - remaining,
                remaining,
                percent,
                rewardIndex,
                cardDef,
                unclaimedCount,
                typeLabel,
                amount
            };
        });
    }, [user.level]);

    const nextHero = useMemo(() => {
        return [...tracks].sort((a, b) => a.remaining - b.remaining)[0];
    }, [tracks]);

    const handleInspect = (track: any) => {
        inspect({
            type: track.type === 'box' ? 'box' : 'level_info',
            level: user.level + track.remaining,
            rewardType: track.type,
            rewardAmount: track.type === 'card' ? 'UNIT' : track.amount,
            cardDef: track.cardDef,
            boxType: 'MEGA',
            title: track.label,
            description: 'Acquired through progression.'
        });
    };

    return (
        <div className="w-full h-full flex flex-col bg-slate-950 overflow-hidden relative">
            <StandardHeader 
                title="COLLECTION" 
                leftContent={
                    <button 
                        onClick={() => onNavigate('DECK')}
                        className="w-8 h-8 rounded-full bg-white/5 border border-white/10 flex items-center justify-center text-white active:scale-90 transition-transform"
                    >
                        <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M15 19l-7-7 7-7" /></svg>
                    </button>
                }
            />

            {/* COLLECTION LEVEL READOUT */}
            <div className="shrink-0 pt-6 pb-2 flex flex-col items-center">
                <span className="text-[0.6rem] font-black text-slate-500 uppercase tracking-[0.4em] mb-1">Collection Level</span>
                <div className="h-10 w-full px-4">
                    <GameText 
                        text={user.level.toLocaleString()} 
                        baseFontSize={3.5} 
                        className="text-white font-black italic tracking-tighter drop-shadow-lg" 
                    />
                </div>
            </div>

            <div className="flex-1 overflow-y-auto px-4 space-y-12 pb-32 pt-6">

                {/* HERO SECTION */}
                <div className="space-y-4">
                    <h3 className="text-[0.6rem] font-black text-indigo-400 uppercase tracking-[0.3em] px-1 text-center">Next Objective</h3>
                    <div 
                        className="relative h-24 flex items-center cursor-pointer group active:scale-[0.99] transition-transform"
                        onClick={() => handleInspect(nextHero)}
                    >
                        {/* THE HEX ANCHOR (z-50) */}
                        <div className="absolute left-0 z-50 drop-shadow-[0_0_25px_rgba(79,70,229,0.4)]">
                            <HexBadge variant="primary" size="xl" glow>
                                <div className="relative w-full h-full overflow-visible">
                                    {/* ICON - DEAD CENTERED, REDUCED SCALE */}
                                    <div className="absolute inset-0 flex items-center justify-center scale-[0.85]">
                                        <RewardItemVisual 
                                            type={nextHero.type as any} 
                                            size="xl" 
                                            cardDef={nextHero.cardDef} 
                                        />
                                    </div>
                                    {/* TEXT - OVERLAPPING BOTTOM EDGE - Font size increased */}
                                    <div className="absolute bottom-[-10%] inset-x-0 h-6 z-50">
                                        <GameText 
                                            text={nextHero.typeLabel} 
                                            baseFontSize={0.9} 
                                            className="text-white font-black italic uppercase drop-shadow-[0_2px_4px_rgba(0,0,0,1)] tracking-widest"
                                        />
                                    </div>
                                </div>
                            </HexBadge>
                        </div>

                        {/* XP BAR (Season Pass Style) */}
                        <div className="absolute left-10 right-2 h-8 bg-indigo-950 border-2 border-indigo-500/40 rounded-full overflow-hidden shadow-[inset_0_2px_4px_rgba(0,0,0,0.8)] z-10">
                            <div 
                                className="h-full bg-gradient-to-r from-indigo-700 via-indigo-500 to-indigo-800 transition-all duration-1000 ease-out relative"
                                style={{ width: `${nextHero.percent}%` }}
                            >
                                <div className="absolute inset-0 bg-white/10 animate-[pulse_2s_infinite]" />
                            </div>
                            {/* Centered Progress Text */}
                            <div className="absolute inset-0 flex items-center justify-center pl-10">
                                <span className="text-[0.7rem] font-black text-white italic drop-shadow-[0_2px_4px_rgba(0,0,0,1)] tracking-widest uppercase">
                                    {nextHero.currentXP} / {nextHero.cycleSize} XP
                                </span>
                            </div>
                        </div>
                    </div>
                </div>

                {/* DIVIDER */}
                <div className="h-px w-full bg-white/10 relative">
                    <div className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 w-2 h-2 bg-slate-950 border border-white/20 rotate-45" />
                </div>

                {/* TRACKS MATRIX */}
                <div className="space-y-12">
                    {tracks.map(track => (
                        <div key={track.type} className="grid grid-cols-[1fr_4rem] gap-4 items-center">

                            {/* XP TRACK */}
                            <div 
                                className="relative h-16 flex items-center cursor-pointer group" 
                                onClick={() => handleInspect(track)}
                            >
                                {/* SMALL HEX ANCHOR */}
                                <div className="absolute left-0 z-40 transition-transform group-hover:scale-110 origin-center drop-shadow-xl">
                                    <HexBadge variant="secondary" size="lg">
                                        <div className="relative w-full h-full overflow-visible">
                                            {/* ICON - DEAD CENTERED, REDUCED SCALE */}
                                            <div className="absolute inset-0 flex items-center justify-center scale-[0.7]">
                                                <RewardItemVisual 
                                                    type={track.type as any} 
                                                    size="lg" 
                                                    cardDef={track.cardDef} 
                                                />
                                            </div>
                                            {/* TEXT - OVERLAPPING BOTTOM EDGE - Font size increased */}
                                            <div className="absolute bottom-[-10%] inset-x-0 h-4 z-50">
                                                <GameText 
                                                    text={track.typeLabel} 
                                                    baseFontSize={0.65} 
                                                    className="text-white font-black italic uppercase drop-shadow-[0_1px_2px_rgba(0,0,0,1)] tracking-tighter"
                                                />
                                            </div>
                                        </div>
                                    </HexBadge>
                                </div>

                                {/* XP BAR (Outline + Centered Text) */}
                                <div className="absolute left-8 right-4 h-6 bg-slate-900 border-2 border-slate-700 rounded-full overflow-hidden z-10 shadow-inner group-hover:border-slate-500 transition-colors">
                                    <div 
                                        className={`h-full bg-gradient-to-r ${track.color} transition-all duration-1000 ease-out`}
                                        style={{ width: `${track.percent}%` }}
                                    />
                                    <div className="absolute inset-0 flex items-center justify-center pl-10">
                                        <span className="text-[0.5rem] font-black text-white italic drop-shadow-md tracking-widest">
                                            {track.currentXP} / {track.cycleSize} XP
                                        </span>
                                    </div>
                                </div>

                                {/* SEQUENCE TAG */}
                                <div className="absolute right-0 z-30 scale-[0.6] opacity-30 translate-x-1/2">
                                    <span className="text-[0.7rem] font-black text-white">#{track.rewardIndex}</span>
                                </div>
                            </div>

                            {/* CLAIM BUTTON */}
                            <div className="flex flex-col items-center">
                                {track.unclaimedCount > 0 ? (
                                    <button 
                                        className="w-12 h-12 rounded-xl bg-amber-500 flex flex-col items-center justify-center shadow-[0_0_20px_rgba(245,158,11,0.5)] border-2 border-amber-300 active:scale-90 transition-transform"
                                        onClick={(e) => { e.stopPropagation(); alert(`Claiming ${track.label}`); }}
                                    >
                                        <span className="text-[0.5rem] font-black text-amber-950 leading-none mb-0.5 uppercase">CLAIM</span>
                                        <span className="text-sm font-black text-white italic leading-none drop-shadow-md">x{track.unclaimedCount}</span>
                                    </button>
                                ) : (
                                    <div className="w-10 h-10 rounded-lg border border-white/5 bg-white/5 flex items-center justify-center opacity-20">
                                        <div className="w-1.5 h-1.5 rounded-full bg-white/30" />
                                    </div>
                                )}
                            </div>
                        </div>
                    ))}
                </div>

                {/* LOG */}
                <div className="pt-6">
                    <div className="flex items-center gap-2 mb-4 px-1 opacity-40">
                        <div className="h-px flex-1 bg-white" />
                        <span className="text-[0.5rem] font-black uppercase tracking-[0.4em]">Log History</span>
                        <div className="h-px flex-1 bg-white" />
                    </div>

                    <div className="bg-slate-900/60 rounded-xl border border-white/5 divide-y divide-white/5 max-h-56 overflow-y-auto scrollbar-hide backdrop-blur-sm">
                        {[
                            { date: 'MAY 20', level: user.level - 4, reward: '10 Boosters' },
                            { date: 'MAY 18', level: user.level - 12, reward: '50 Credits' },
                            { date: 'MAY 15', level: user.level - 24, reward: '100 Gold' },
                        ].map((item, i) => (
                            <div key={i} className="flex items-center justify-between p-3 hover:bg-white/5 transition-colors">
                                <div className="flex flex-col">
                                    <span className="text-[0.65rem] font-black text-white italic uppercase tracking-tighter">{item.reward}</span>
                                    <span className="text-[0.45rem] font-bold text-slate-600 uppercase tracking-widest">{item.date}</span>
                                </div>
                                <span className="text-[0.5rem] font-mono text-indigo-500 font-bold bg-indigo-500/10 px-2 py-1 rounded border border-indigo-500/20">LVL {item.level}</span>
                            </div>
                        ))}
                    </div>
                </div>

            </div>
        </div>
    );
};

