    // SCALE LOGIC: Isolated to this screen
    const getScale = (type: string) => {
        if (type === 'gold' || type === 'credits') return 'scale-[0.54]'; // Reduced by 20% from 0.67
        if (type === 'booster') return 'scale-[0.88]'; // Reduced by 20% from 1.1
        if (type === 'card') return 'scale-[0.5]'; // Reduced by 50%
