import React from 'react';
import { CreditIcon, GoldIcon } from './CurrencyIcons';
import { CardDefinition } from '../../types';
import { Card } from '../Card';

export type SeasonRewardType = 'gold' | 'credits' | 'card' | 'booster';

interface RewardItemVisualProps {
    type: SeasonRewardType;
    amount?: string | number;
    imageUrl?: string;
    level?: number;
    className?: string;
    size?: 'sm' | 'lg' | 'xl';
    cardDef?: CardDefinition; 
}

/**
 * REWARD ITEM VISUAL
 * Focused on pure centering of the icon graphic.
 * Layout margins removed to allow parent containers (like HexBadges)
 * to control composition via absolute positioning or flex alignment.
 */
export const RewardItemVisual: React.FC<RewardItemVisualProps> = ({ 
    type, 
    amount, 
    level, 
    className = "",
    size = 'sm',
    cardDef
}) => {
    const isLarge = size === 'lg' || size === 'xl';
    const shouldHideText = type === 'card';

    return (
        <div className={`flex flex-col items-center justify-center pointer-events-none w-full h-full ${className}`}>
            {/* ICON LAYER - No margins, pure centering */}
            <div className="flex items-center justify-center transition-transform duration-500">
                <RewardIconGraphic type={type} level={level} size={size} cardDef={cardDef} />
            </div>

            {/* TEXT LABEL LAYER */}
            {amount && !shouldHideText && (
                <div className={`${isLarge ? 'mt-4' : 'mt-1'} flex flex-col items-center justify-center leading-none w-full`}>
                    <span className={`
                        ${size === 'xl' ? 'text-4xl' : (size === 'lg' ? 'text-xl' : 'text-[0.55rem]')} 
                        font-black uppercase tracking-tighter text-white drop-shadow-[0_1px_3px_rgba(0,0,0,1)] text-center italic
                    `}>
                        {amount} {type}
                    </span>
                </div>
            )}
        </div>
    );
};

export const RewardIconGraphic: React.FC<{ 
    type: SeasonRewardType; 
    level?: number;
    size?: 'sm' | 'lg' | 'xl';
    cardDef?: CardDefinition;
}> = ({ type, level, size = 'sm', cardDef }) => {
    const isLarge = size === 'lg';
    const isHero = size === 'xl';

    const iconSize = isHero ? 'xl' : (isLarge ? 'lg' : 'sm');

    switch (type) {
        case 'gold': return <GoldIcon size={iconSize} animate={isHero} />;
        case 'credits': return <CreditIcon size={iconSize} />;
        case 'card': 
            if (cardDef) {
                return (
                    <div className={`${isHero ? 'w-44' : (isLarge ? 'w-36' : 'w-9')} aspect-[5/7] flex items-center justify-center shadow-2xl`}>
                        <Card 
                            card={cardDef} 
                            size={isHero ? 'lg' : (isLarge ? 'md' : 'xs')} 
                            borderOverride="white" 
                        />
                    </div>
                );
            }
            return (
                <div className={`${isHero ? 'w-20 h-20' : (isLarge ? 'w-12 h-12' : 'w-6 h-6')} text-indigo-200`}>
                    <svg className="w-full h-full" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" />
                    </svg>
                </div>
            );
