                    </linearGradient>
                    <linearGradient id="bg_warning" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="0%" stopColor="#92400e" /><stop offset="100%" stopColor="#451a03" />
                    </linearGradient>
                    <linearGradient id="bg_blue" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="0%" stopColor="#1e40af" /><stop offset="100%" stopColor="#172554" />
                    </linearGradient>

                    <clipPath id="hexClip">
                        <path d="M50 2 L95 25 L95 75 L50 98 L5 75 L5 25 Z" />
                    </clipPath>

                    <filter id="innerShadow">
                        <feComponentTransfer in="SourceAlpha">
                            <feFuncA type="table" tableValues="1 0" />
                        </feComponentTransfer>
                        <feGaussianBlur stdDeviation="2.5" />
                        <feOffset dx="0" dy="1.5" result="offsetblur" />
                        <feFlood floodColor="black" floodOpacity="0.7" />
                        <feComposite in2="offsetblur" operator="in" />
                        <feComposite in2="SourceAlpha" operator="in" />
                        <feMerge>
                            <feMergeNode />
                            <feMergeNode in="SourceGraphic" />
                        </feMerge>
                    </filter>
                </defs>

                <path 
                    d="M50 2 L95 25 L95 75 L50 98 L5 75 L5 25 Z" 
                    fill="black" 
                    fillOpacity="0.25" 
                    transform="translate(0, 2.5)"
                />

                <path 
                    d="M50 2 L95 25 L95 75 L50 98 L5 75 L5 25 Z" 
                    fill={v.fill}
                    filter="url(#innerShadow)"
                />

                <path 
                    d="M50 2 L95 25 L95 75 L50 98 L5 75 L5 25 Z" 
                    fill="none" 
                    stroke={v.stroke} 
                    strokeWidth={s.strokeWidth} 
                    strokeLinejoin="round"
                />

                <path 
                    d="M50 5 L91 26 L91 74 L50 95 L9 74 L9 26 Z" 
                    fill="none" 
                    stroke={v.innerStroke} 
                    strokeWidth="1.8" 
                    opacity="0.5"
                    strokeLinejoin="round"
                />

                <path 
                    d="M-20 42 L120 -18 L120 42 L-20 102 Z" 
                    fill="white" 
                    fillOpacity="0.1" 
                    clipPath="url(#hexClip)"
                    pointerEvents="none"
                />
            </svg>

            <div className="relative z-10 w-full h-full flex items-center justify-center pointer-events-none">
                <div className="w-[82%] h-[82%] flex items-center justify-center">
                    {typeof children === 'string' || typeof children === 'number' ? (
                        <GameText 
                            text={children.toString()} 
                            baseFontSize={s.fontSize}
                            maxScale={1.0}
                            className={`${v.text} font-black italic tracking-tighter uppercase drop-shadow-[0_1px_3px_rgba(0,0,0,0.85)]`}
                        />
                    ) : (
                        <div className={`w-full h-full flex items-center justify-center ${v.text}`}>
                            {children}
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

import React, { useMemo } from 'react';
import { StandardHeader } from '../ui/StandardHeader';
import { ScreenKey, CardDefinition } from '../../types';
import { useUser } from '../../contexts/UserContext';
import { CARDS } from '../../constants';
import { RewardIconGraphic } from '../ui/RewardItemVisual';
import { GameText } from '../ui/GameText';
import { HexBadge } from '../ui/HexBadge';

interface RewardCycle {
    label: string;
    type: 'booster' | 'credits' | 'gold' | 'box' | 'card';
    cycleSize: number;
    color: string;
    variant: 'primary' | 'secondary' | 'success' | 'danger' | 'warning' | 'blue';
    borderColor: string;
    bgTrack: string;
}

const CYCLES: RewardCycle[] = [
    { 
        label: 'Boosters', 
        type: 'booster', 
        cycleSize: 4, 
        color: 'from-emerald-400 to-emerald-600', 
        variant: 'success', 
        borderColor: 'border-emerald-400/50',
        bgTrack: 'bg-emerald-900/40' // Colorful dark sea
    },
    { 
        label: 'Credits', 
        type: 'credits', 
        cycleSize: 12, 
        color: 'from-blue-400 to-blue-600', 
        variant: 'blue', 
        borderColor: 'border-blue-400/50',
        bgTrack: 'bg-blue-900/40'
    },
    { 
        label: 'Gold', 
        type: 'gold', 
        cycleSize: 24, 
        color: 'from-amber-400 to-amber-600', 
        variant: 'warning', 
        borderColor: 'border-amber-400/50',
        bgTrack: 'bg-amber-900/40'
    },
    { 
        label: 'Omega Box', 
        type: 'box', 
        cycleSize: 32, 
        color: 'from-indigo-400 to-indigo-600', 
        variant: 'primary', 
        borderColor: 'border-indigo-400/50',
        bgTrack: 'bg-indigo-900/40'
    },
    { 
        label: 'New Card', 
        type: 'card', 
        cycleSize: 48, 
        color: 'from-white to-slate-400', 
        variant: 'secondary', 
        borderColor: 'border-white/50',
        bgTrack: 'bg-slate-800/40'
    },
];

export const ProgressionScreen: React.FC<{ onNavigate: (screen: ScreenKey) => void }> = ({ onNavigate }) => {
    const { user, inspect } = useUser();

    const tracks = useMemo(() => {
        return CYCLES.map(cycle => {
            const progress = user.level % cycle.cycleSize;
            const remaining = cycle.cycleSize - (progress === 0 && user.level > 0 ? 0 : progress);
            const percent = ((cycle.cycleSize - remaining) / cycle.cycleSize) * 100;
            const rewardIndex = Math.floor(user.level / cycle.cycleSize) + 1;

            let cardDef: CardDefinition | undefined;
            if (cycle.type === 'card') {
                cardDef = CARDS[Math.floor((user.level / cycle.cycleSize) % CARDS.length)];
            }

            const unclaimedCount = Math.max(0, Math.floor(user.level / (cycle.cycleSize * 8)) - 1);
            const amount = cycle.type === 'gold' ? 100 : cycle.type === 'credits' ? 50 : 10;

            let typeLabel = '';
            if (cycle.type === 'booster') typeLabel = `${amount} boosters`;
            else if (cycle.type === 'credits') typeLabel = `${amount} credits`;
            else if (cycle.type === 'gold') typeLabel = `${amount} gold`;
            else if (cycle.type === 'box') typeLabel = `omega box`;
            else if (cycle.type === 'card') typeLabel = '';

            return {
                ...cycle,
                currentXP: cycle.cycleSize - remaining,
                remaining,
                percent,
                rewardIndex,
                cardDef,
                unclaimedCount,
                typeLabel,
                amount
            };
        });
    }, [user.level]);

    const nextHero = useMemo(() => {
        return [...tracks].sort((a, b) => a.remaining - b.remaining)[0];
    }, [tracks]);

    const handleInspect = (track: any) => {
        inspect({
            type: track.type === 'box' ? 'box' : 'level_info',
            level: user.level + track.remaining,
            rewardType: track.type,
            rewardAmount: track.type === 'card' ? 'UNIT' : track.amount,
            cardDef: track.cardDef,
            boxType: 'MEGA',
            title: track.label,
            description: 'Acquired through progression.'
        });
    };

    // SCALE LOGIC: Reduced another 10% (0.32 -> 0.29, 0.52 -> 0.47)
    const getScale = (type: string) => {
        if (type === 'gold' || type === 'credits') return 'scale-[0.29]'; 
        if (type === 'booster') return 'scale-[0.47]'; 
        if (type === 'card') return 'scale-[0.45]'; 
        return 'scale-[1.0]';
    };

    return (
        <div className="w-full h-full flex flex-col bg-slate-950 overflow-hidden relative">
            <StandardHeader 
                title="COLLECTION" 
                leftContent={
                    <button 
                        onClick={() => onNavigate('DECK')}
                        className="w-8 h-8 rounded-full bg-white/5 border border-white/10 flex items-center justify-center text-white active:scale-90 transition-transform"
                    >
                        <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M15 19l-7-7 7-7" /></svg>
                    </button>
                }
            />

            <div className="shrink-0 pt-6 pb-2 flex flex-col items-center">
                <span className="text-[0.6rem] font-black text-slate-500 uppercase tracking-[0.4em] mb-1">Collection Level</span>
                <div className="h-10 w-full px-4">
                    <GameText text={user.level.toLocaleString()} baseFontSize={3.5} className="text-white font-black italic tracking-tighter drop-shadow-lg" />
                </div>
            </div>

            <div className="flex-1 overflow-y-auto px-4 space-y-12 pb-32 pt-6">

                {/* HERO SECTION */}
                <div className="space-y-4">
                    <h3 className="text-[0.6rem] font-black text-indigo-400 uppercase tracking-[0.3em] px-1 text-center">Next Objective</h3>
                    <div 
                        className="relative h-24 flex items-center cursor-pointer group active:scale-[0.99] transition-transform"
                        onClick={() => handleInspect(nextHero)}
                    >
                        <div className="absolute left-0 z-50 drop-shadow-[0_0_25px_rgba(79,70,229,0.4)]">
                            <HexBadge variant={nextHero.variant} size="xl" glow>
                                <div className="relative w-full h-full overflow-visible">
                                    <div className={`absolute inset-0 flex items-center justify-center ${getScale(nextHero.type)}`}>
                                        <RewardIconGraphic 
                                            type={nextHero.type as any} 
                                            size="xl" 
                                            cardDef={nextHero.cardDef} 
                                        />
                                    </div>
                                    <div className="absolute bottom-[-15%] inset-x-0 h-6 z-50">
                                        <GameText 
                                            text={nextHero.typeLabel} 
                                            baseFontSize={1.1} 
                                            className="text-white font-black italic uppercase drop-shadow-[0_2px_4px_rgba(0,0,0,1)] tracking-widest"
                                        />
                                    </div>
                                </div>
                            </HexBadge>
                        </div>

                        <div className={`absolute left-10 right-2 h-8 ${nextHero.bgTrack} border-2 ${nextHero.borderColor} rounded-full overflow-hidden shadow-[inset_0_2px_4px_rgba(0,0,0,0.8)] z-10 transition-colors duration-500`}>
                            <div className={`h-full bg-gradient-to-r ${nextHero.color} transition-all duration-1000 ease-out relative`} style={{ width: `${nextHero.percent}%` }}>
                                <div className="absolute inset-0 bg-white/10 animate-[pulse_2s_infinite]" />
                            </div>
                            <div className="absolute inset-0 flex items-center justify-center pl-10">
                                <span className="text-[0.7rem] font-black text-white italic drop-shadow-[0_2px_4px_rgba(0,0,0,1)] tracking-widest uppercase">
                                    {nextHero.currentXP} / {nextHero.cycleSize} XP
                                </span>
                            </div>
                        </div>
                    </div>
                </div>

                <div className="h-px w-full bg-white/10 relative">
                    <div className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 w-2 h-2 bg-slate-950 border border-white/20 rotate-45" />
                </div>

                {/* TRACKS MATRIX */}
                <div className="space-y-12">
                    {tracks.map(track => (
                        <div key={track.type} className="grid grid-cols-[1fr_4rem] gap-4 items-center">
                            <div className="relative h-16 flex items-center cursor-pointer group" onClick={() => handleInspect(track)}>
                                <div className="absolute left-0 z-40 transition-transform group-hover:scale-110 origin-center drop-shadow-xl">
                                    <HexBadge variant={track.variant} size="lg">
                                        <div className="relative w-full h-full overflow-visible">
                                            <div className={`absolute inset-0 flex items-center justify-center ${getScale(track.type)}`}>
                                                <RewardIconGraphic 
                                                    type={track.type as any} 
                                                    size="lg" 
                                                    cardDef={track.cardDef} 
                                                />
                                            </div>
                                            <div className="absolute bottom-[-15%] inset-x-0 h-4 z-50">
                                                <GameText 
                                                    text={track.typeLabel} 
                                                    baseFontSize={0.8} 
                                                    className="text-white font-black italic uppercase drop-shadow-[0_1px_2px_rgba(0,0,0,1)] tracking-tighter"
                                                />
                                            </div>
                                        </div>
                                    </HexBadge>
                                </div>

                                <div className={`absolute left-8 right-4 h-6 ${track.bgTrack} border-2 ${track.borderColor} rounded-full overflow-hidden z-10 shadow-inner group-hover:border-white/40 transition-colors`}>
                                    <div className={`h-full bg-gradient-to-r ${track.color} transition-all duration-1000 ease-out`} style={{ width: `${track.percent}%` }} />
                                    <div className="absolute inset-0 flex items-center justify-center pl-10">
                                        <span className="text-[0.5rem] font-black text-white italic drop-shadow-md tracking-widest">
                                            {track.currentXP} / {track.cycleSize} XP
                                        </span>
                                    </div>
                                </div>

                                <div className="absolute right-0 z-30 scale-[0.6] opacity-30 translate-x-1/2">
                                    <span className="text-[0.7rem] font-black text-white">#{track.rewardIndex}</span>
                                </div>
                            </div>

                            <div className="flex flex-col items-center">
                                {track.unclaimedCount > 0 ? (
                                    <button 
                                        className="w-12 h-12 rounded-xl bg-amber-500 flex flex-col items-center justify-center shadow-[0_0_20px_rgba(245,158,11,0.5)] border-2 border-amber-300 active:scale-90 transition-transform"
                                        onClick={(e) => { e.stopPropagation(); alert(`Claiming ${track.label}`); }}
                                    >
                                        <span className="text-[0.5rem] font-black text-amber-950 leading-none mb-0.5 uppercase">CLAIM</span>
                                        <span className="text-sm font-black text-white italic leading-none drop-shadow-md">x{track.unclaimedCount}</span>
                                    </button>
                                ) : (
                                    <div className="w-10 h-10 rounded-lg border border-white/5 bg-white/5 flex items-center justify-center opacity-20">
                                        <div className="w-1.5 h-1.5 rounded-full bg-white/30" />
                                    </div>
                                )}
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        </div>
    );
};

