import React from 'react';
import { GameText } from './GameText';

type BadgeVariant = 'primary' | 'secondary' | 'success' | 'danger' | 'warning' | 'blue';

interface HexBadgeProps {
    children: React.ReactNode;
    variant?: BadgeVariant;
    size?: 'xs' | 'sm' | 'md' | 'lg' | 'xl';
    className?: string;
    glow?: boolean;
}

export const HexBadge: React.FC<HexBadgeProps> = ({ 
    children, 
    variant = 'primary', 
    size = 'md',
    className = '',
    glow = false
}) => {
    const variants = {
        primary: {
            fill: 'url(#bg_primary)',
            stroke: '#818cf8', // indigo-400
            innerStroke: '#c7d2fe', // indigo-200
            text: 'text-white',
            glowColor: 'rgba(99, 102, 241, 0.95)'
        },
        secondary: {
            fill: 'url(#bg_secondary)',
            stroke: '#f1f5f9', // slate-100
            innerStroke: '#ffffff', // white
            text: 'text-slate-900', 
            glowColor: 'rgba(255, 255, 255, 0.6)'
        },
        success: {
            fill: 'url(#bg_success)',
            stroke: '#34d399', // emerald-400
            innerStroke: '#a7f3d0', // emerald-200
            text: 'text-white',
            glowColor: 'rgba(16, 185, 129, 0.8)'
        },
        danger: {
            fill: 'url(#bg_danger)',
            stroke: '#f87171', // red-400
            innerStroke: '#fecaca', // red-200
            text: 'text-white',
            glowColor: 'rgba(239, 68, 68, 0.8)'
        },
        warning: {
            fill: 'url(#bg_warning)',
            stroke: '#fbbf24', // amber-400
            innerStroke: '#fde68a', // amber-200
            text: 'text-white',
            glowColor: 'rgba(245, 158, 11, 0.85)'
        },
        blue: {
            fill: 'url(#bg_blue)',
            stroke: '#60a5fa', // blue-400
            innerStroke: '#bfdbfe', // blue-200
            text: 'text-white',
            glowColor: 'rgba(59, 130, 246, 0.85)'
        }
    };

    const sizeConfigs = {
        xs: { box: 'w-[1.25rem] h-[1.25rem]', fontSize: 0.5, strokeWidth: 11 },
        sm: { box: 'w-[2.0rem] h-[2.0rem]', fontSize: 0.7, strokeWidth: 9 },
        md: { box: 'w-[2.4rem] h-[2.4rem]', fontSize: 0.85, strokeWidth: 8 },
        lg: { box: 'w-[3.2rem] h-[3.2rem]', fontSize: 1.1, strokeWidth: 7 },
        xl: { box: 'w-[4.8rem] h-[4.8rem]', fontSize: 1.6, strokeWidth: 5 }
    };

    const v = variants[variant];
    const s = sizeConfigs[size];

    return (
        <div className={`relative ${s.box} flex items-center justify-center shrink-0 drop-shadow-[0_2px_4px_rgba(0,0,0,0.6)] ${className}`}>
            <svg 
                viewBox="0 0 100 100" 
                className="absolute inset-0 w-full h-full overflow-visible"
                style={glow ? { filter: `drop-shadow(0 0 15px ${v.glowColor})` } : {}}
            >
                <defs>
                    <linearGradient id="bg_primary" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="0%" stopColor="#3730a3" /><stop offset="100%" stopColor="#1e1b4b" />
                    </linearGradient>
                    <linearGradient id="bg_secondary" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="0%" stopColor="#64748b" /><stop offset="100%" stopColor="#334155" />
                    </linearGradient>
                    <linearGradient id="bg_success" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="0%" stopColor="#065f46" /><stop offset="100%" stopColor="#064e3b" />
                    </linearGradient>
                    <linearGradient id="bg_danger" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="0%" stopColor="#991b1b" /><stop offset="100%" stopColor="#7f1d1d" />
                    </linearGradient>
                    <linearGradient id="bg_warning" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="0%" stopColor="#92400e" /><stop offset="100%" stopColor="#78350f" />
                    </linearGradient>
                    <linearGradient id="bg_blue" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="0%" stopColor="#1e40af" /><stop offset="100%" stopColor="#1e3a8a" />
                    </linearGradient>

                    <clipPath id="hexClip">
                        <path d="M50 2 L95 25 L95 75 L50 98 L5 75 L5 25 Z" />
                    </clipPath>

                    <filter id="innerShadow">
                        <feComponentTransfer in="SourceAlpha">
                            <feFuncA type="table" tableValues="1 0" />
                        </feComponentTransfer>
                        <feGaussianBlur stdDeviation="2.5" />
                        <feOffset dx="0" dy="1.5" result="offsetblur" />
                        <feFlood floodColor="black" floodOpacity="0.7" />
                        <feComposite in2="offsetblur" operator="in" />
                        <feComposite in2="SourceAlpha" operator="in" />
                        <feMerge>
                            <feMergeNode />
                            <feMergeNode in="SourceGraphic" />
                        </feMerge>
                    </filter>
                </defs>

                <path 
                    d="M50 2 L95 25 L95 75 L50 98 L5 75 L5 25 Z" 
                    fill="black" 
                    fillOpacity="0.25" 
                    transform="translate(0, 2.5)"
                />

                <path 
                    d="M50 2 L95 25 L95 75 L50 98 L5 75 L5 25 Z" 
                    fill={v.fill}
                    filter="url(#innerShadow)"
                />

                <path 
                    d="M50 2 L95 25 L95 75 L50 98 L5 75 L5 25 Z" 
                    fill="none" 
                    stroke={v.stroke} 
                    strokeWidth={s.strokeWidth} 
                    strokeLinejoin="round"
                />

                <path 
                    d="M50 5 L91 26 L91 74 L50 95 L9 74 L9 26 Z" 
                    fill="none" 
                    stroke={v.innerStroke} 
                    strokeWidth="1.8" 
                    opacity="0.5"
                    strokeLinejoin="round"
                />

                <path 
                    d="M-20 42 L120 -18 L120 42 L-20 102 Z" 
                    fill="white" 
                    fillOpacity="0.1" 
                    clipPath="url(#hexClip)"
                    pointerEvents="none"
                />
            </svg>

            <div className="relative z-10 w-full h-full flex items-center justify-center pointer-events-none">
                <div className="w-[82%] h-[82%] flex items-center justify-center">
                    {typeof children === 'string' || typeof children === 'number' ? (
                        <GameText 
                            text={children.toString()} 
                            baseFontSize={s.fontSize}
                            maxScale={1.0}
                            className={`${v.text} font-black italic tracking-tighter uppercase drop-shadow-[0_1px_3px_rgba(0,0,0,0.85)]`}
                        />
                    ) : (
                        <div className={`w-full h-full flex items-center justify-center ${v.text}`}>
                            {children}
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

import React, { useMemo } from 'react';
import { StandardHeader } from '../ui/StandardHeader';
import { ScreenKey, CardDefinition } from '../../types';
import { useUser } from '../../contexts/UserContext';
import { CARDS } from '../../constants';
import { RewardIconGraphic } from '../ui/RewardItemVisual';
import { GameText } from '../ui/GameText';
import { HexBadge } from '../ui/HexBadge';

interface RewardCycle {
    label: string;
    type: 'booster' | 'credits' | 'gold' | 'box' | 'card';
    cycleSize: number;
    color: string;
    variant: 'primary' | 'secondary' | 'success' | 'danger' | 'warning' | 'blue';
    borderColor: string;
    bgTrack: string;
}

const CYCLES: RewardCycle[] = [
    { 
        label: 'Boosters', 
        type: 'booster', 
        cycleSize: 4, 
        color: 'from-emerald-400 to-emerald-600', 
        variant: 'success', 
        borderColor: 'border-emerald-400/50',
        bgTrack: 'bg-[#064e3b]' 
    },
    { 
        label: 'Credits', 
        type: 'credits', 
        cycleSize: 12, 
        color: 'from-blue-400 to-blue-600', 
        variant: 'blue', 
        borderColor: 'border-blue-400/50',
        bgTrack: 'bg-[#1e3a8a]' 
    },
    { 
        label: 'Gold', 
        type: 'gold', 
        cycleSize: 24, 
        color: 'from-amber-400 to-amber-600', 
        variant: 'warning', 
        borderColor: 'border-amber-400/50',
        bgTrack: 'bg-[#78350f]' 
    },
    { 
        label: 'Omega Box', 
        type: 'box', 
        cycleSize: 32, 
        color: 'from-indigo-400 to-indigo-600', 
        variant: 'primary', 
        borderColor: 'border-indigo-400/50',
        bgTrack: 'bg-[#1e1b4b]' 
    },
    { 
        label: 'New Card', 
        type: 'card', 
        cycleSize: 48, 
        color: 'from-white to-slate-400', 
        variant: 'secondary', 
        borderColor: 'border-white/50',
        bgTrack: 'bg-[#334155]' 
    },
];

const RewardTypeIcon: React.FC<{ type: string }> = ({ type }) => {
    switch (type) {
        case 'booster': return <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M11.3 1.046A1 1 0 0112 2v5h4a1 1 0 01.82 1.573l-7 10A1 1 0 018 18v-5H4a1 1 0 01-.82-1.573l7-10a1 1 0 011.12-.38z" clipRule="evenodd" /></svg>;
        case 'credits': return <div className="w-4 h-4 bg-blue-400 rotate-45 border border-white/40 shadow-[0_0_8px_rgba(96,165,250,0.8)]" />;
        case 'gold': return <div className="w-5 h-3 bg-amber-400 rounded-sm border border-white/40 shadow-[0_0_8px_rgba(251,191,36,0.8)]" />;
        case 'box': return <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4" /></svg>;
        case 'card': return <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 4v16m8-8H4" /></svg>;
        default: return null;
    }
};

const getClaimStyles = (variant: string) => {
    switch (variant) {
        case 'success': return { btn: 'bg-emerald-500 border-emerald-300 shadow-emerald-500/40', text: 'text-emerald-500' };
        case 'blue': return { btn: 'bg-blue-500 border-blue-300 shadow-blue-500/40', text: 'text-blue-500' };
        case 'warning': return { btn: 'bg-amber-500 border-amber-300 shadow-amber-500/40', text: 'text-amber-500' };
        case 'primary': return { btn: 'bg-indigo-500 border-indigo-300 shadow-indigo-500/40', text: 'text-indigo-500' };
        case 'secondary': return { btn: 'bg-slate-400 border-slate-200 shadow-slate-400/40', text: 'text-slate-400' };
        default: return { btn: 'bg-slate-500 border-slate-300 shadow-slate-500/40', text: 'text-slate-500' };
    }
};

export const ProgressionScreen: React.FC<{ onNavigate: (screen: ScreenKey) => void }> = ({ onNavigate }) => {
    const { user, inspect } = useUser();

    const tracks = useMemo(() => {
        return CYCLES.map(cycle => {
            const progress = user.level % cycle.cycleSize;
            const remaining = cycle.cycleSize - (progress === 0 && user.level > 0 ? 0 : progress);
            const percent = ((cycle.cycleSize - remaining) / cycle.cycleSize) * 100;
            const rewardIndex = Math.floor(user.level / cycle.cycleSize) + 1;

            let cardDef: CardDefinition | undefined;
            if (cycle.type === 'card') {
                cardDef = CARDS[Math.floor((user.level / cycle.cycleSize) % CARDS.length)];
            }

            const unclaimedCount = Math.max(0, Math.floor(user.level / (cycle.cycleSize * 8)) - 1);
            const amount = cycle.type === 'gold' ? 100 : cycle.type === 'credits' ? 50 : 10;

            let typeLabel = '';
            if (cycle.type === 'booster') typeLabel = `${amount} boosters`;
            else if (cycle.type === 'credits') typeLabel = `${amount} credits`;
            else if (cycle.type === 'gold') typeLabel = `${amount} gold`;
            else if (cycle.type === 'box') typeLabel = `omega box`;
            else if (cycle.type === 'card') typeLabel = '';

            return {
                ...cycle,
                currentXP: cycle.cycleSize - remaining,
                remaining,
                percent,
                rewardIndex,
                cardDef,
                unclaimedCount,
                typeLabel,
                amount
            };
        });
    }, [user.level]);

    const nextHero = useMemo(() => {
        return [...tracks].sort((a, b) => a.remaining - b.remaining)[0];
    }, [tracks]);

    const handleInspect = (track: any) => {
        inspect({
            type: track.type === 'box' ? 'box' : 'level_info',
            level: user.level + track.remaining,
            rewardType: track.type,
            rewardAmount: track.type === 'card' ? 'UNIT' : track.amount,
            cardDef: track.cardDef,
            boxType: 'MEGA',
            title: track.label,
            description: 'Acquired through progression.'
        });
    };

    const getScale = (type: string) => {
        if (type === 'gold' || type === 'credits') return 'scale-[0.55]'; 
        if (type === 'booster') return 'scale-[0.72]'; 
        if (type === 'card') return 'scale-[0.65]'; 
        return 'scale-[1.1]';
    };

    return (
        <div className="w-full h-full flex flex-col bg-slate-950 overflow-hidden relative">
            <StandardHeader 
                title="COLLECTION" 
                leftContent={
                    <button 
                        onClick={() => onNavigate('DECK')}
                        className="w-8 h-8 rounded-full bg-white/5 border border-white/10 flex items-center justify-center text-white active:scale-90 transition-transform"
                    >
                        <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M15 19l-7-7 7-7" /></svg>
                    </button>
                }
            />

            <div className="shrink-0 pt-6 pb-2 flex flex-col items-center">
                <span className="text-[0.6rem] font-black text-slate-500 uppercase tracking-[0.4em] mb-1">Collection Level</span>
                <div className="h-10 w-full px-4">
                    <GameText text={user.level.toLocaleString()} baseFontSize={3.0} className="text-white font-black italic tracking-tighter drop-shadow-lg" />
                </div>
            </div>

            <div className="flex-1 overflow-y-auto px-4 space-y-12 pb-32 pt-6">

                {/* HERO SECTION */}
                <div className="space-y-4">
                    <h3 className="text-[0.6rem] font-black text-indigo-400 uppercase tracking-[0.3em] px-1 text-center">Next Objective</h3>
                    <div 
                        className="relative h-24 flex items-center cursor-pointer group active:scale-[0.99] transition-transform"
                        onClick={() => handleInspect(nextHero)}
                    >
                        <div className="absolute left-0 z-50 drop-shadow-[0_0_25px_rgba(79,70,229,0.4)]">
                            <HexBadge variant={nextHero.variant} size="xl" glow>
                                <div className="relative w-full h-full overflow-visible">
                                    <div className={`absolute inset-0 flex items-center justify-center ${getScale(nextHero.type)}`}>
                                        <RewardIconGraphic 
                                            type={nextHero.type as any} 
                                            size="xl" 
                                            cardDef={nextHero.cardDef} 
                                        />
                                    </div>
                                    <div className="absolute bottom-[-15%] inset-x-0 h-6 z-50">
                                        <GameText 
                                            text={nextHero.typeLabel} 
                                            baseFontSize={0.9} 
                                            className="text-white font-black italic uppercase drop-shadow-[0_2px_4px_rgba(0,0,0,1)] tracking-widest"
                                        />
                                    </div>
                                </div>
                            </HexBadge>
                        </div>

                        <div className={`absolute left-10 right-2 h-10 ${nextHero.bgTrack} border-2 ${nextHero.borderColor} rounded-full overflow-hidden shadow-[inset_0_2px_8px_rgba(0,0,0,0.8)] z-10 transition-colors duration-500`}>
                            <div className={`h-full bg-gradient-to-r ${nextHero.color} transition-all duration-1000 ease-out relative shadow-[0_0_15px_rgba(255,255,255,0.2)]`} style={{ width: `${nextHero.percent}%` }}>
                                <div className="absolute inset-0 bg-white/10 animate-[pulse_2s_infinite]" />
                            </div>
                            <div className="absolute inset-0 flex items-center justify-center pl-12 pr-4 py-0 pointer-events-none">
                                <GameText 
                                    text={`${nextHero.currentXP} / ${nextHero.cycleSize} XP`} 
                                    baseFontSize={1.65} 
                                    className="text-white font-black italic tracking-widest uppercase drop-shadow-[0_2px_4px_rgba(0,0,0,1)]"
                                />
                            </div>
                        </div>
                    </div>
                </div>

                <div className="h-px w-full bg-white/10 relative">
                    <div className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 w-2 h-2 bg-slate-950 border border-white/20 rotate-45" />
                </div>

                {/* TRACKS MATRIX */}
                <div className="space-y-12">
                    {tracks.map(track => {
                        const styles = getClaimStyles(track.variant);
                        return (
                            <div key={track.type} className="grid grid-cols-[1fr_4.5rem] gap-4 items-center">
                                <div className="relative h-16 flex items-center cursor-pointer group" onClick={() => handleInspect(track)}>
                                    <div className="absolute left-0 z-40 transition-transform group-hover:scale-110 origin-center drop-shadow-xl">
                                        <HexBadge variant={track.variant} size="lg">
                                            <div className="relative w-full h-full overflow-visible">
                                                <div className={`absolute inset-0 flex items-center justify-center ${getScale(track.type)}`}>
                                                    <RewardIconGraphic 
                                                        type={track.type as any} 
                                                        size="lg" 
                                                        cardDef={track.cardDef} 
                                                    />
                                                </div>
                                                <div className="absolute bottom-[-15%] inset-x-0 h-4 z-50">
                                                    <GameText 
                                                        text={track.typeLabel} 
                                                        baseFontSize={0.6} 
                                                        className="text-white font-black italic uppercase drop-shadow-[0_1px_2px_rgba(0,0,0,1)] tracking-tighter"
                                                    />
                                                </div>
                                            </div>
                                        </HexBadge>
                                    </div>

                                    <div className={`absolute left-8 right-4 h-7 ${track.bgTrack} border-2 ${track.borderColor} rounded-full overflow-hidden z-10 shadow-[inset_0_2px_4px_rgba(0,0,0,0.5)] group-hover:border-white/40 transition-colors`}>
