        case 'blue': return { btn: 'bg-blue-500 border-blue-300 shadow-blue-500/40', text: 'text-blue-500' };
        case 'warning': return { btn: 'bg-amber-500 border-amber-300 shadow-amber-500/40', text: 'text-amber-500' };
        case 'primary': return { btn: 'bg-indigo-500 border-indigo-300 shadow-indigo-500/40', text: 'text-indigo-500' };
        case 'secondary': return { btn: 'bg-slate-400 border-slate-200 shadow-slate-400/40', text: 'text-slate-400' };
