};

export const ProgressionScreen: React.FC<{ onNavigate: (screen: ScreenKey) => void }> = ({ onNavigate }) => {
    const { user, inspect } = useUser();

    const tracks = useMemo(() => {
        return CYCLES.map(cycle => {
            const progress = user.level % cycle.cycleSize;
            const remaining = cycle.cycleSize - (progress === 0 && user.level > 0 ? 0 : progress);
            const percent = ((cycle.cycleSize - remaining) / cycle.cycleSize) * 100;
            const rewardIndex = Math.floor(user.level / cycle.cycleSize) + 1;

            let cardDef: CardDefinition | undefined;
            if (cycle.type === 'card') {
                cardDef = CARDS[Math.floor((user.level / cycle.cycleSize) % CARDS.length)];
            }

            const unclaimedCount = Math.max(0, Math.floor(user.level / (cycle.cycleSize * 8)) - 1);
            const amount = cycle.type === 'gold' ? 100 : cycle.type === 'credits' ? 50 : 10;

            let typeLabel = '';
            if (cycle.type === 'booster') typeLabel = `${amount} boosters`;
            else if (cycle.type === 'credits') typeLabel = `${amount} credits`;
            else if (cycle.type === 'gold') typeLabel = `${amount} gold`;
            else if (cycle.type === 'box') typeLabel = `omega box`;
            else if (cycle.type === 'card') typeLabel = '';

            return {
                ...cycle,
                currentXP: cycle.cycleSize - remaining,
                remaining,
                percent,
                rewardIndex,
                cardDef,
                unclaimedCount,
                typeLabel,
                amount
            };
        });
    }, [user.level]);

    const nextHero = useMemo(() => {
        return [...tracks].sort((a, b) => a.remaining - b.remaining)[0];
    }, [tracks]);

    const handleInspect = (track: any) => {
        inspect({
            type: track.type === 'box' ? 'box' : 'level_info',
            level: user.level + track.remaining,
            rewardType: track.type,
            rewardAmount: track.type === 'card' ? 'UNIT' : track.amount,
            cardDef: track.cardDef,
            boxType: 'MEGA',
            title: track.label,
            description: 'Acquired through progression.'
        });
    };

    // REVERTED ICON SCALES: Back to previous balanced values
    const getScale = (type: string) => {
        if (type === 'gold' || type === 'credits') return 'scale-[0.48]'; 
        if (type === 'booster') return 'scale-[0.68]'; 
        if (type === 'card') return 'scale-[0.60]'; 
        return 'scale-[1.0]';
    };

    return (
        <div className="w-full h-full flex flex-col bg-slate-950 overflow-hidden relative">
            <StandardHeader 
                title="COLLECTION" 
                leftContent={
                    <button 
                        onClick={() => onNavigate('DECK')}
                        className="w-8 h-8 rounded-full bg-white/5 border border-white/10 flex items-center justify-center text-white active:scale-90 transition-transform"
                    >
                        <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M15 19l-7-7 7-7" /></svg>
                    </button>
                }
            />

            <div className="shrink-0 pt-6 pb-2 flex flex-col items-center">
                <span className="text-[0.6rem] font-black text-slate-500 uppercase tracking-[0.4em] mb-1">Collection Level</span>
                <div className="h-10 w-full px-4">
                    <GameText text={user.level.toLocaleString()} baseFontSize={3.0} className="text-white font-black italic tracking-tighter drop-shadow-lg" />
                </div>
            </div>

            <div className="flex-1 overflow-y-auto px-4 space-y-12 pb-32 pt-6">

                {/* HERO SECTION */}
                <div className="space-y-4">
                    <h3 className="text-[0.6rem] font-black text-indigo-400 uppercase tracking-[0.3em] px-1 text-center">Next Objective</h3>
                    <div 
                        className="relative h-24 flex items-center cursor-pointer group active:scale-[0.99] transition-transform"
                        onClick={() => handleInspect(nextHero)}
                    >
                        <div className="absolute left-0 z-50 drop-shadow-[0_0_25px_rgba(79,70,229,0.4)]">
                            <HexBadge variant={nextHero.variant} size="xl" glow>
                                <div className="relative w-full h-full overflow-visible">
                                    <div className={`absolute inset-0 flex items-center justify-center ${getScale(nextHero.type)}`}>
                                        <RewardIconGraphic 
                                            type={nextHero.type as any} 
                                            size="xl" 
                                            cardDef={nextHero.cardDef} 
                                        />
                                    </div>
                                    <div className="absolute bottom-[-15%] inset-x-0 h-6 z-50">
                                        <GameText 
                                            text={nextHero.typeLabel} 
                                            baseFontSize={0.9} 
                                            className="text-white font-black italic uppercase drop-shadow-[0_2px_4px_rgba(0,0,0,1)] tracking-widest"
                                        />
                                    </div>
                                </div>
                            </HexBadge>
                        </div>

                        <div className={`absolute left-10 right-2 h-10 ${nextHero.bgTrack} border-2 ${nextHero.borderColor} rounded-full overflow-hidden shadow-[inset_0_2px_8px_rgba(0,0,0,0.8)] z-10 transition-colors duration-500`}>
                            <div className={`h-full bg-gradient-to-r ${nextHero.color} transition-all duration-1000 ease-out relative shadow-[0_0_15px_rgba(255,255,255,0.2)]`} style={{ width: `${nextHero.percent}%` }}>
                                <div className="absolute inset-0 bg-white/10 animate-[pulse_2s_infinite]" />
                            </div>
                            <div className="absolute inset-0 flex items-center justify-center pl-12 pr-4 py-0 pointer-events-none">
                                <GameText 
                                    text={`${nextHero.currentXP} / ${nextHero.cycleSize} XP`} 
                                    baseFontSize={1.3} 
                                    className="text-white font-black italic tracking-widest uppercase drop-shadow-[0_2px_4px_rgba(0,0,0,1)]"
                                />
                            </div>
