                                            <span className={`text-[0.45rem] font-black uppercase tracking-[0.2em] leading-none drop-shadow-sm whitespace-nowrap ${labelTextColor}`}>
                                                CLAIM X{track.unclaimedCount}
                                            </span>
                                        </>
                                    ) : (
                                        <div className="w-10 h-10 rounded-lg border border-white/5 bg-white/5 flex items-center justify-center opacity-20">
                                            <div className="w-1.5 h-1.5 rounded-full bg-white/30" />
                                        </div>
                                    )}
                                </div>
                            </div>
                        );
                    })}
                </div>
            </div>
        </div>
    );
};

