import React from 'react';
import { CreditIcon, GoldIcon } from './CurrencyIcons';
import { CardDefinition } from '../../types';
import { Card } from '../Card';

export type SeasonRewardType = 'gold' | 'credits' | 'card' | 'booster' | 'box';

interface RewardItemVisualProps {
    type: SeasonRewardType;
    amount?: string | number;
    imageUrl?: string;
    level?: number;
    className?: string;
    size?: 'sm' | 'lg' | 'xl';
    cardDef?: CardDefinition; 
}

/**
 * REWARD ITEM VISUAL
 * Focused on pure centering of the icon graphic.
 * Layout margins removed to allow parent containers (like HexBadges)
 * to control composition via absolute positioning or flex alignment.
 */
export const RewardItemVisual: React.FC<RewardItemVisualProps> = ({ 
    type, 
    amount, 
    level, 
    className = "",
    size = 'sm',
    cardDef
}) => {
    const isLarge = size === 'lg' || size === 'xl';
    const shouldHideText = type === 'card';

    return (
        <div className={`flex flex-col items-center justify-center pointer-events-none w-full h-full ${className}`}>
            {/* ICON LAYER - No margins, pure centering */}
            <div className="flex items-center justify-center transition-transform duration-500">
                <RewardIconGraphic type={type} level={level} size={size} cardDef={cardDef} />
            </div>

            {/* TEXT LABEL LAYER */}
            {amount && !shouldHideText && (
                <div className={`${isLarge ? 'mt-4' : 'mt-1'} flex flex-col items-center justify-center leading-none w-full`}>
                    <span className={`
                        ${size === 'xl' ? 'text-4xl' : (size === 'lg' ? 'text-xl' : 'text-[0.55rem]')} 
                        font-black uppercase tracking-tighter text-white drop-shadow-[0_1px_3px_rgba(0,0,0,1)] text-center italic
                    `}>
                        {amount} {type}
                    </span>
                </div>
            )}
        </div>
    );
};

export const RewardIconGraphic: React.FC<{ 
    type: SeasonRewardType; 
    level?: number;
    size?: 'sm' | 'lg' | 'xl';
    cardDef?: CardDefinition;
}> = ({ type, level, size = 'sm', cardDef }) => {
    const isLarge = size === 'lg';
    const isHero = size === 'xl';

    const iconSize = isHero ? 'xl' : (isLarge ? 'lg' : 'sm');

    switch (type) {
        case 'gold': return <GoldIcon size={iconSize} animate={isHero} />;
        case 'credits': return <CreditIcon size={iconSize} />;
        case 'card': 
            if (cardDef) {
                return (
                    <div className={`${isHero ? 'w-44' : (isLarge ? 'w-36' : 'w-9')} aspect-[5/7] flex items-center justify-center shadow-2xl`}>
                        <Card 
                            card={cardDef} 
                            size={isHero ? 'lg' : (isLarge ? 'md' : 'xs')} 
                            borderOverride="white" 
                        />
                    </div>
                );
            }
            return (
                <div className={`${isHero ? 'w-20 h-20' : (isLarge ? 'w-12 h-12' : 'w-6 h-6')} text-indigo-200`}>
                    <svg className="w-full h-full" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" />
                    </svg>
                </div>
            );
        case 'booster': return (
            <div className={`${isHero ? 'w-24 h-24' : (isLarge ? 'w-12 h-12' : 'w-6 h-6')} text-emerald-400 drop-shadow-[0_0_20px_rgba(52,211,153,0.4)]`}>
                <svg className="w-full h-full" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={isHero ? 2.5 : 3} d="M13 10V3L4 14h7v7l9-11h-7z" />
                </svg>
            </div>
        );
        case 'box': return (
            <div className={`${isHero ? 'w-24 h-24' : (isLarge ? 'w-12 h-12' : 'w-6 h-6')} drop-shadow-[0_0_20px_rgba(79,70,229,0.4)]`}>
                <svg className="w-full h-full" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                    <defs>
                        <linearGradient id="omegaBoxGrad" x1="0%" y1="0%" x2="0%" y2="100%">
                            <stop offset="0%" stopColor="#c7d2fe" />
                            <stop offset="100%" stopColor="#6366f1" />
                        </linearGradient>
                    </defs>
                    <path 
                        d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4" 
                        stroke="url(#omegaBoxGrad)" 
                        strokeWidth={isHero ? 1.4 : 1.8} 
                        strokeLinecap="round" 
                        strokeLinejoin="round" 
                    />
                </svg>
            </div>
        );
        default: return null;
    }
};

import React, { useMemo } from 'react';
import { StandardHeader } from '../ui/StandardHeader';
import { ScreenKey, CardDefinition } from '../../types';
import { useUser } from '../../contexts/UserContext';
import { CARDS } from '../../constants';
import { RewardIconGraphic } from '../ui/RewardItemVisual';
import { GameText } from '../ui/GameText';
import { HexBadge } from '../ui/HexBadge';
import { SlantedButton } from '../ui/SlantedButton';

interface RewardCycle {
    label: string;
    type: 'booster' | 'credits' | 'gold' | 'box' | 'card';
    cycleSize: number;
    color: string;
    variant: 'primary' | 'secondary' | 'success' | 'danger' | 'warning' | 'blue';
    borderColor: string;
    bgTrack: string;
}

const CYCLES: RewardCycle[] = [
    { 
        label: 'Boosters', 
        type: 'booster', 
        cycleSize: 4, 
        color: 'from-emerald-400 to-emerald-600', 
        variant: 'success', 
        borderColor: 'border-emerald-400/50',
        bgTrack: 'bg-[#064e3b]' 
    },
    { 
        label: 'Credits', 
        type: 'credits', 
        cycleSize: 12, 
        color: 'from-blue-400 to-blue-600', 
        variant: 'blue', 
        borderColor: 'border-blue-400/50',
        bgTrack: 'bg-[#1e3a8a]' 
    },
    { 
        label: 'Gold', 
        type: 'gold', 
        cycleSize: 24, 
        color: 'from-amber-400 to-amber-600', 
        variant: 'warning', 
        borderColor: 'border-amber-400/50',
        bgTrack: 'bg-[#78350f]' 
    },
    { 
        label: 'Omega Box', 
        type: 'box', 
        cycleSize: 32, 
        color: 'from-indigo-400 to-indigo-600', 
        variant: 'primary', 
        borderColor: 'border-indigo-400/50',
        bgTrack: 'bg-[#1e1b4b]' 
    },
    { 
        label: 'New Card', 
        type: 'card', 
        cycleSize: 48, 
        color: 'from-white to-slate-400', 
        variant: 'secondary', 
        borderColor: 'border-white/50',
        bgTrack: 'bg-[#334155]' 
    },
];

const getClaimTextStyles = (variant: string) => {
    switch (variant) {
        case 'success': return 'text-emerald-500';
        case 'blue': return 'text-blue-500';
        case 'warning': return 'text-amber-500';
        case 'primary': return 'text-indigo-500';
        case 'secondary': return 'text-slate-400';
        default: return 'text-slate-500';
    }
};

export const ProgressionScreen: React.FC<{ onNavigate: (screen: ScreenKey) => void }> = ({ onNavigate }) => {
    const { user, inspect } = useUser();

    const tracks = useMemo(() => {
        return CYCLES.map(cycle => {
            const progress = user.level % cycle.cycleSize;
            const remaining = cycle.cycleSize - (progress === 0 && user.level > 0 ? 0 : progress);
            const percent = ((cycle.cycleSize - remaining) / cycle.cycleSize) * 100;
            const rewardIndex = Math.floor(user.level / cycle.cycleSize) + 1;

            let cardDef: CardDefinition | undefined;
            if (cycle.type === 'card') {
                cardDef = CARDS[Math.floor((user.level / cycle.cycleSize) % CARDS.length)];
            }

            const unclaimedCount = Math.max(0, Math.floor(user.level / (cycle.cycleSize * 2.5)) - 1);
            const amount = cycle.type === 'gold' ? 100 : cycle.type === 'credits' ? 50 : 10;

            let typeLabel = '';
            let shortLabel = '';
            if (cycle.type === 'booster') { typeLabel = `${amount} boosters`; shortLabel = `${amount} boosters`; }
            else if (cycle.type === 'credits') { typeLabel = `${amount} credits`; shortLabel = `${amount} credits`; }
            else if (cycle.type === 'gold') { typeLabel = `${amount} gold`; shortLabel = `${amount} gold`; }
            else if (cycle.type === 'box') { typeLabel = `omega box`; shortLabel = `omega box`; }
            else if (cycle.type === 'card') { typeLabel = 'card'; shortLabel = 'card'; }

            return {
                ...cycle,
                currentXP: cycle.cycleSize - remaining,
                remaining,
                percent,
                rewardIndex,
                cardDef,
                unclaimedCount,
                typeLabel,
                shortLabel,
                amount
            };
        });
    }, [user.level]);

    const nextHero = useMemo(() => {
        return [...tracks].sort((a, b) => a.remaining - b.remaining)[0];
    }, [tracks]);

    const handleInspect = (track: any) => {
        inspect({
            type: track.type === 'box' ? 'box' : 'level_info',
            level: user.level + track.remaining,
            rewardType: track.type,
            rewardAmount: track.type === 'card' ? 'UNIT' : track.amount,
            cardDef: track.cardDef,
            boxType: 'MEGA',
            title: track.label,
            description: 'Acquired through progression.'
        });
    };

    const getScale = (type: string) => {
        if (type === 'gold' || type === 'credits') return 'scale-[0.48]'; 
        if (type === 'booster') return 'scale-[0.68]'; 
        if (type === 'card') return 'scale-[0.60]'; 
        return 'scale-[1.0]';
    };

    return (
        <div className="w-full h-full flex flex-col bg-slate-950 overflow-hidden relative">
            <StandardHeader 
                title="COLLECTION" 
                leftContent={
                    <button 
                        onClick={() => onNavigate('DECK')}
                        className="w-8 h-8 rounded-full bg-white/5 border border-white/10 flex items-center justify-center text-white active:scale-90 transition-transform"
                    >
                        <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M15 19l-7-7 7-7" /></svg>
                    </button>
                }
            />

            <div className="shrink-0 pt-6 pb-2 flex flex-col items-center">
                <span className="text-[0.6rem] font-black text-slate-500 uppercase tracking-[0.4em] mb-1">Collection Level</span>
                <div className="h-10 w-full px-4">
                    <GameText text={user.level.toLocaleString()} baseFontSize={3.2} className="text-white font-black italic tracking-tighter drop-shadow-lg" />
                </div>
            </div>

            <div className="flex-1 overflow-y-auto px-4 space-y-12 pb-32 pt-6">

                {/* HERO SECTION */}
                <div className="space-y-4">
                    <h3 className="text-[0.6rem] font-black text-indigo-400 uppercase tracking-[0.3em] px-1 text-center">Next Objective</h3>
                    <div 
                        className="relative h-24 flex items-center cursor-pointer group active:scale-[0.99] transition-transform"
                        onClick={() => handleInspect(nextHero)}
                    >
                        {/* Upper Label using Negative Spacing Logic */}
                        <div className="absolute top-[-35%] left-12 right-0 h-6 z-50">
                            <GameText 
                                text={`${nextHero.typeLabel} Bundle #${nextHero.rewardIndex}`} 
                                baseFontSize={1.4} 
                                className="text-white font-black italic uppercase drop-shadow-[0_2px_4px_rgba(0,0,0,1)] tracking-widest text-left"
                            />
                        </div>

                        <div className="absolute left-0 z-50 drop-shadow-[0_0_25px_rgba(79,70,229,0.4)]">
                            <HexBadge variant={nextHero.variant} size="xl" glow>
                                <div className="relative w-full h-full overflow-visible">
                                    <div className={`absolute inset-0 flex items-center justify-center ${getScale(nextHero.type)}`}>
                                        <RewardIconGraphic 
                                            type={nextHero.type as any} 
                                            size="xl" 
                                            cardDef={nextHero.cardDef} 
                                        />
                                    </div>
                                </div>
                            </HexBadge>
                        </div>

                        <div className={`absolute left-10 right-2 h-10 ${nextHero.bgTrack} border-2 ${nextHero.borderColor} rounded-full overflow-hidden shadow-[inset_0_2px_8px_rgba(0,0,0,0.8)] z-10 transition-colors duration-500`}>
                            <div className={`h-full bg-gradient-to-r ${nextHero.color} transition-all duration-1000 ease-out relative shadow-[0_0_15px_rgba(255,255,255,0.2)]`} style={{ width: `${nextHero.percent}%` }}>
                                <div className="absolute inset-0 bg-white/10 animate-[pulse_2s_infinite]" />
                            </div>
                            <div className="absolute inset-0 flex items-center justify-center pl-12 pr-4 py-0 pointer-events-none">
                                <GameText 
                                    text={`${nextHero.currentXP} / ${nextHero.cycleSize} XP`} 
                                    baseFontSize={1.3} 
                                    className="text-white font-black italic tracking-widest uppercase drop-shadow-[0_2px_4px_rgba(0,0,0,1)]"
                                />
                            </div>
                        </div>
                    </div>
                </div>

                <div className="h-px w-full bg-white/10 relative">
                    <div className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 w-2 h-2 bg-slate-950 border border-white/20 rotate-45" />
                </div>

                {/* TRACKS MATRIX */}
                <div className="space-y-16">
                    {tracks.map(track => {
                        const labelTextColor = getClaimTextStyles(track.variant);
                        return (
                            <div key={track.type} className="grid grid-cols-[1fr_6rem] gap-2 items-end">
                                <div className="relative h-16 flex items-center cursor-pointer group" onClick={() => handleInspect(track)}>

                                    {/* Upper Label using Negative Spacing Logic */}
                                    <div className="absolute top-[-45%] left-10 right-0 h-5 z-50 pointer-events-none">
                                        <GameText 
                                            text={`${track.typeLabel} Bundle #${track.rewardIndex}`} 
                                            baseFontSize={0.9} 
                                            className="text-white/90 font-black italic uppercase drop-shadow-[0_2px_4px_rgba(0,0,0,1)] tracking-tighter text-left"
                                        />
                                    </div>

                                    <div className="absolute left-0 z-40 transition-transform group-hover:scale-110 origin-center drop-shadow-xl">
                                        <HexBadge variant={track.variant} size="lg">
                                            <div className="relative w-full h-full overflow-visible">
                                                <div className={`absolute inset-0 flex items-center justify-center ${getScale(track.type)}`}>
                                                    <RewardIconGraphic 
                                                        type={track.type as any} 
                                                        size="lg" 
                                                        cardDef={track.cardDef} 
                                                    />
                                                </div>
                                            </div>
                                        </HexBadge>
                                    </div>

                                    <div className={`absolute left-8 right-0 h-7 ${track.bgTrack} border-2 ${track.borderColor} rounded-full overflow-hidden z-10 shadow-[inset_0_2px_4px_rgba(0,0,0,0.5)] group-hover:border-white/40 transition-colors`}>
                                        <div className={`h-full bg-gradient-to-r ${track.color} transition-all duration-1000 ease-out`} style={{ width: `${track.percent}%` }} />
                                        <div className="absolute inset-0 flex items-center justify-center pl-10 pr-2 py-0 pointer-events-none">
                                            <GameText 
                                                text={`${track.currentXP} / ${track.cycleSize} XP`} 
                                                baseFontSize={0.9} 
                                                className="text-white font-black italic tracking-widest drop-shadow-md"
                                            />
                                        </div>
                                    </div>
                                </div>

                                <div className="flex flex-col items-center gap-1.5 pb-0.5">
                                    {track.unclaimedCount > 0 ? (
                                        <>
                                            <SlantedButton 
                                                variant={track.variant}
                                                size="xs"
                                                className="!w-24 !h-9 shadow-lg"
                                                onClick={(e) => { e.stopPropagation(); alert(`Claiming ${track.label}`); }}
                                            >
                                                {`CLAIM\n${track.shortLabel}`}
                                            </SlantedButton>
                                            <span className={`text-[0.45rem] font-black uppercase tracking-[0.2em] leading-none drop-shadow-sm whitespace-nowrap ${labelTextColor}`}>
                                                {track.unclaimedCount} UNCLAIMED
                                            </span>
                                        </>
                                    ) : (
                                        <div className="w-24 h-9 rounded bg-white/5 border border-white/5 flex items-center justify-center opacity-20 skew-x-[-9deg]">
                                            <div className="w-1.5 h-1.5 rounded-full bg-white/30" />
                                        </div>
                                    )}
                                </div>
                            </div>
                        );
                    })}
                </div>
            </div>
        </div>
    );
};

