            else if (cycle.type === 'gold') { typeLabel = `${amount} gold`; shortLabel = `${amount} gold`; }
            else if (cycle.type === 'box') { typeLabel = `omega box`; shortLabel = `omega box`; }
            else if (cycle.type === 'card') { typeLabel = 'new card'; shortLabel = 'card'; }

