type LogCategory = 'all' | 'booster' | 'credits' | 'gold' | 'box' | 'card';

interface LogItemData {
    title: string;
    type: 'booster' | 'credits' | 'gold' | 'box' | 'card';
    date: string;
    time: string;
    amount?: string | number;
    cardDef?: CardDefinition;
}

const MOCK_LOG: LogItemData[] = [
    { title: "Portal Mage", type: 'card', date: "14 MAY", time: "22:15", cardDef: CARDS[8] },
    { title: "Omega Box", type: 'box', date: "12 MAY", time: "14:20" },
