                                        </HexBadge>
                                    </div>

                                    <div className={`absolute left-8 right-0 h-7 ${track.bgTrack} border-2 ${track.borderColor} rounded-full overflow-hidden z-10 shadow-[inset_0_2px_4px_rgba(0,0,0,0.5)] group-hover:border-white/40 transition-colors`}>
                                        <div className={`h-full bg-gradient-to-r ${track.color} transition-all duration-1000 ease-out`} style={{ width: `${track.percent}%` }} />
                                        <div className="absolute inset-0 flex items-center justify-center pl-10 pr-2 py-0 pointer-events-none">
                                            <GameText 
                                                text={`${track.currentXP} / ${track.cycleSize} XP`} 
                                                baseFontSize={0.9} 
                                                className="text-white font-black italic tracking-widest drop-shadow-md"
                                            />
                                        </div>
                                    </div>
                                </div>

                                <div className="flex flex-col items-center gap-1.5 pb-0.5">
                                    {track.unclaimedCount > 0 ? (
                                        <>
                                            <SlantedButton 
                                                variant={track.variant}
                                                size="xs"
                                                className="!w-24 !h-9 shadow-lg"
                                                onClick={(e) => { e.stopPropagation(); alert(`Claiming ${track.label}`); }}
                                            >
                                                {`CLAIM\n${track.shortLabel}`}
                                            </SlantedButton>
                                            <span className={`text-[0.45rem] font-black uppercase tracking-[0.2em] leading-none drop-shadow-sm whitespace-nowrap text-slate-300/80`}>
                                                {track.unclaimedCount} UNCLAIMED
                                            </span>
                                        </>
                                    ) : (
                                        <div className="w-24 h-9 rounded bg-white/5 border border-white/5 flex items-center justify-center opacity-20 skew-x-[-9deg]">
                                            <div className="w-1.5 h-1.5 rounded-full bg-white/30" />
                                        </div>
                                    )}
                                </div>
                            </div>
                        );
                    })}
                </div>

                {/* CLAIM ACTIVITY LOG SECTION */}
                <div className="pt-12 pb-12">
                    <div className="flex flex-col gap-4 mb-6 px-1">
                        <div className="flex items-center gap-3">
                            <h3 className="text-[0.65rem] font-black text-slate-500 uppercase tracking-[0.4em] whitespace-nowrap">Activity Log</h3>
                            <div className="flex-1 h-px bg-white/10" />
                        </div>

                        {/* CATEGORY FILTERS - Slanted Buttons matching Nav Bar gutter */}
                        <div className="flex gap-1.5 overflow-x-auto scrollbar-hide py-1 px-1">
                            {(['all', 'credits', 'gold', 'card', 'box', 'booster'] as LogCategory[]).map(cat => (
                                <SlantedButton 
                                    key={cat}
                                    variant={logFilter === cat ? 'primary' : 'secondary'}
                                    size="xs"
                                    onClick={() => setLogFilter(cat)}
                                    className="!w-[14vw] max-w-[3.5rem] shadow-lg"
                                >
                                    {renderFilterIcon(cat)}
                                </SlantedButton>
                            ))}
                        </div>
                    </div>

                    <div className="space-y-2.5 opacity-90 scale-95 origin-top min-h-[10rem]">
                        {filteredLog.length > 0 ? (
                            filteredLog.map((item, idx) => (
                                <ActivityLogItem key={`${item.type}-${idx}`} item={item} />
                            ))
                        ) : (
                            <div className="h-24 flex items-center justify-center border border-dashed border-white/10 rounded-xl bg-white/5">
                                <span className="text-[0.6rem] font-black text-slate-700 uppercase tracking-[0.4em]">Archive Empty</span>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

