        bgTrack: 'bg-[#1e3a8a]' 
    },
    { 
        label: 'Gold', 
        type: 'gold', 
        cycleSize: 24, 
        color: 'from-amber-400 to-amber-600', 
        variant: 'warning', 
        borderColor: 'border-amber-400/50',
        bgTrack: 'bg-[#78350f]' 
    },
    { 
