    { title: "100 Gold", type: 'gold', date: "09 MAY", time: "12:00", amount: 100 },
];

const ActivityLogItem: React.FC<{ item: LogItemData }> = ({ item }) => {
    // Scaling logic: Card is 0.75, Credits/Gold bumped by 33% (1.46 -> 1.94), others stay 1.46
    let iconScale = 'scale-[1.46]';
    if (item.type === 'card') iconScale = 'scale-75';
    else if (item.type === 'credits' || item.type === 'gold') iconScale = 'scale-[1.94]';

    return (
        <div className="flex items-center justify-between py-2 px-3 bg-slate-800/80 border border-slate-700 rounded-lg shadow-sm hover:border-slate-600 transition-colors cursor-default group">
