const ActivityLogItem: React.FC<{ item: LogItemData }> = ({ item }) => {
    // Scaling logic: Card is 0.75, Credits/Gold bumped by 33% (1.46 -> 1.94), others stay 1.46
    let iconScale = 'scale-[1.46]';
