    async purchaseOffer(user: UserProfile, offerId: string, transactionId: string): Promise<PurchaseResponse> {
        await new Promise(resolve => setTimeout(resolve, 800 + Math.random() * 400));
        if (processedTransactions.has(transactionId)) return { success: false, errorCode: 'ERR_DUPLICATE_TRANSACTION', transactionId };
        const offer = MOCK_STORE_OFFERS.find(o => o.id === offerId);
        if (!offer) return { success: false, errorCode: 'ERR_OFFER_NOT_FOUND', transactionId };
        if (offer.cooldownSeconds && user.lastClaimedDates[offer.id]) {
            const lastClaimed = new Date(user.lastClaimedDates[offer.id]).getTime();
            if (Date.now() < lastClaimed + (offer.cooldownSeconds * 1000)) return { success: false, errorCode: 'ERR_COOLDOWN_ACTIVE', transactionId };
        }
        if (offer.priceType === 'gold' && user.gold < (offer.priceAmount || 0)) return { success: false, errorCode: 'ERR_INSUFFICIENT_FUNDS', transactionId };
        if (offer.priceType === 'credits' && user.credits < (offer.priceAmount || 0)) return { success: false, errorCode: 'ERR_INSUFFICIENT_FUNDS', transactionId };
        processedTransactions.add(transactionId);
        const updatedProfile: UserProfile = { ...user };
        if (offer.priceType === 'gold') updatedProfile.gold -= (offer.priceAmount || 0);
        if (offer.priceType === 'credits') updatedProfile.credits -= (offer.priceAmount || 0);
        offer.contents.forEach(item => {
            if (item.type === 'currency') {
                if (item.currencyType === 'gold') updatedProfile.gold += item.amount;
                if (item.currencyType === 'credits') updatedProfile.credits += item.amount;
            } else if (item.type === 'card' && !updatedProfile.collection.includes(item.definitionId)) {
                updatedProfile.collection = [...updatedProfile.collection, item.definitionId];
            }
        });
        updatedProfile.purchasedOfferIds = [...updatedProfile.purchasedOfferIds, offerId];
        updatedProfile.lastClaimedDates = { ...updatedProfile.lastClaimedDates, [offerId]: new Date().toISOString() };
        return { success: true, transactionId, updatedProfile };
    },

    // --- Progression API ---
    async getProgression(user: UserProfile): Promise<ProgressionData> {
        await new Promise(resolve => setTimeout(resolve, 400));

        const cycleConfigs: { type: ProgressionRewardType, label: string, cycleSize: number }[] = [
            { type: 'booster', label: 'Boosters', cycleSize: 4 },
            { type: 'credits', label: 'Credits', cycleSize: 12 },
            { type: 'gold', label: 'Gold', cycleSize: 24 },
            { type: 'box', label: 'Omega Box', cycleSize: 32 },
            { type: 'card', label: 'New Card', cycleSize: 48 }
        ];

        // Fix: Added ProgressionTrack to imports to resolve 'Cannot find name ProgressionTrack'
        const tracks: ProgressionTrack[] = cycleConfigs.map(config => {
            const progress = user.level % config.cycleSize;
            const remaining = config.cycleSize - (progress === 0 && user.level > 0 ? 0 : progress);

            let nextRewardCardDef: any = undefined;
            if (config.type === 'card') {
                nextRewardCardDef = CARDS[Math.floor((user.level / config.cycleSize) % CARDS.length)];
            }

            const amount = config.type === 'gold' ? 100 : config.type === 'credits' ? 50 : 10;

            return {
                type: config.type,
                label: config.label,
                currentXP: config.cycleSize - remaining,
                targetXP: config.cycleSize,
                unclaimedCount: progressionStore.unclaimedCounts[config.type],
                nextRewardAmount: config.type === 'card' ? 'UNIT' : amount,
                nextRewardCardDef
            };
        });

        return {
            collectionLevel: user.level,
            tracks
        };
    },

    async getActivityLog(type: string = 'all'): Promise<ActivityLogEntry[]> {
        await new Promise(resolve => setTimeout(resolve, 200));
        if (type === 'all') return progressionStore.activityLog;
        return progressionStore.activityLog.filter(log => log.type === type);
    },

    async claimProgressionReward(user: UserProfile, type: ProgressionRewardType): Promise<{ success: boolean, updatedProfile?: UserProfile, claimedReward?: any }> {
        await new Promise(resolve => setTimeout(resolve, 500));

        if (progressionStore.unclaimedCounts[type] <= 0) {
            return { success: false };
        }

        // Mutation: Server-side
        progressionStore.unclaimedCounts[type]--;

        const updatedProfile = { ...user };
        let rewardTitle = '';
        let rewardAmount: string | number = '';
        let rewardCardDef = undefined;

        if (type === 'credits') {
            updatedProfile.credits += 50;
            rewardTitle = "50 Credits";
            rewardAmount = 50;
        } else if (type === 'gold') {
            updatedProfile.gold += 100;
            rewardTitle = "100 Gold";
            rewardAmount = 100;
        } else if (type === 'card') {
            const card = CARDS[Math.floor(Math.random() * CARDS.length)];
            updatedProfile.collection.push(card.id);
            rewardTitle = card.name;
            rewardCardDef = card;
        } else if (type === 'booster') {
            rewardTitle = "10 Boosters";
            rewardAmount = 10;
        } else if (type === 'box') {
            rewardTitle = "Omega Box";
        }

        // Add to log
        const now = new Date();
        progressionStore.activityLog.unshift({
            id: generateInstanceId(),
            title: rewardTitle,
            type: type,
            date: `${now.getDate()} ${now.toLocaleString('default', { month: 'short' }).toUpperCase()}`,
            time: `${now.getHours()}:${now.getMinutes().toString().padStart(2, '0')}`,
            amount: rewardAmount,
            cardDef: rewardCardDef
        });

        return { 
            success: true, 
            updatedProfile, 
            claimedReward: { title: rewardTitle, amount: rewardAmount, cardDef: rewardCardDef } 
        };
    }
};

