        if (offer.cooldownSeconds && user.lastClaimedDates[offer.id]) {
            const lastClaimed = new Date(user.lastClaimedDates[offer.id]).getTime();
            if (Date.now() < lastClaimed + (offer.cooldownSeconds * 1000)) return { success: false, errorCode: 'ERR_COOLDOWN_ACTIVE', transactionId };
        }
        if (offer.priceType === 'gold' && user.gold < (offer.priceAmount || 0)) return { success: false, errorCode: 'ERR_INSUFFICIENT_FUNDS', transactionId };
        if (offer.priceType === 'credits' && user.credits < (offer.priceAmount || 0)) return { success: false, errorCode: 'ERR_INSUFFICIENT_FUNDS', transactionId };
        processedTransactions.add(transactionId);
        const updatedProfile: UserProfile = { ...user };
        if (offer.priceType === 'gold') updatedProfile.gold -= (offer.priceAmount || 0);
        if (offer.priceType === 'credits') updatedProfile.credits -= (offer.priceAmount || 0);
        offer.contents.forEach(item => {
            if (item.type === 'currency') {
                if (item.currencyType === 'gold') updatedProfile.gold += item.amount;
                if (item.currencyType === 'credits') updatedProfile.credits += item.amount;
            } else if (item.type === 'card' && !updatedProfile.collection.includes(item.definitionId)) {
                updatedProfile.collection = [...updatedProfile.collection, item.definitionId];
            }
        });
        updatedProfile.purchasedOfferIds = [...updatedProfile.purchasedOfferIds, offerId];
        updatedProfile.lastClaimedDates = { ...updatedProfile.lastClaimedDates, [offerId]: new Date().toISOString() };
        return { success: true, transactionId, updatedProfile };
    },

    // --- Progression API ---
    async getProgression(user: UserProfile): Promise<ProgressionData> {
        await new Promise(resolve => setTimeout(resolve, 400));

        const cycleConfigs: { type: ProgressionRewardType, label: string, cycleSize: number }[] = [
            { type: 'booster', label: 'Boosters', cycleSize: 4 },
            { type: 'credits', label: 'Credits', cycleSize: 12 },
            { type: 'gold', label: 'Gold', cycleSize: 24 },
            { type: 'box', label: 'Omega Box', cycleSize: 32 },
            { type: 'card', label: 'New Card', cycleSize: 48 }
        ];

        const tracks: ProgressionTrack[] = cycleConfigs.map(config => {
            const progress = user.level % config.cycleSize;
            const remaining = config.cycleSize - (progress === 0 && user.level > 0 ? 0 : progress);

            let nextRewardCardDef: any = undefined;
            if (config.type === 'card') {
                nextRewardCardDef = CARDS[Math.floor((user.level / config.cycleSize) % CARDS.length)];
            }

            const amount = config.type === 'gold' ? 100 : config.type === 'credits' ? 50 : 10;

            return {
                type: config.type,
                label: config.label,
                currentXP: config.cycleSize - remaining,
                targetXP: config.cycleSize,
                unclaimedCount: progressionStore.unclaimedCounts[config.type],
                nextRewardAmount: config.type === 'card' ? 'UNIT' : amount,
                nextRewardCardDef
            };
        });

        return {
            collectionLevel: user.level,
            tracks
        };
    },

    async getActivityLog(type: string = 'all'): Promise<ActivityLogEntry[]> {
        await new Promise(resolve => setTimeout(resolve, 200));
        if (type === 'all') return progressionStore.activityLog;
        return progressionStore.activityLog.filter(log => log.type === type);
    },

    async claimProgressionReward(user: UserProfile, type: ProgressionRewardType): Promise<{ success: boolean, updatedProfile?: UserProfile, claimedReward?: any }> {
        await new Promise(resolve => setTimeout(resolve, 500));

        if (progressionStore.unclaimedCounts[type] <= 0) {
            return { success: false };
        }

        // Mutation: Server-side
        progressionStore.unclaimedCounts[type]--;

        const updatedProfile = { ...user };
        let rewardTitle = '';
        let rewardAmount: string | number = '';
        let rewardCardDef = undefined;

        if (type === 'credits') {
            updatedProfile.credits += 50;
            rewardTitle = "50 Credits";
            rewardAmount = 50;
        } else if (type === 'gold') {
            updatedProfile.gold += 100;
            rewardTitle = "100 Gold";
            rewardAmount = 100;
        } else if (type === 'card') {
            const card = CARDS[Math.floor(Math.random() * CARDS.length)];
            updatedProfile.collection.push(card.id);
            rewardTitle = card.name;
            rewardCardDef = card;
        } else if (type === 'booster') {
            rewardTitle = "10 Boosters";
            rewardAmount = 10;
        } else if (type === 'box') {
            rewardTitle = "Omega Box";
        }

        // Add to log
        const now = new Date();
        progressionStore.activityLog.unshift({
            id: generateInstanceId(),
            title: rewardTitle,
            type: type,
            date: `${now.getDate()} ${now.toLocaleString('default', { month: 'short' }).toUpperCase()}`,
            time: `${now.getHours()}:${now.getMinutes().toString().padStart(2, '0')}`,
            amount: rewardAmount,
            cardDef: rewardCardDef
        });

        return { 
            success: true, 
            updatedProfile, 
            claimedReward: { title: rewardTitle, amount: rewardAmount, cardDef: rewardCardDef } 
        };
    }
};

import React, { useMemo, useState } from 'react';
import { StandardHeader } from '../ui/StandardHeader';
import { ScreenKey, CardDefinition, ActivityLogEntry, ProgressionRewardType, ProgressionTrack } from '../../types';
import { useUser } from '../../contexts/UserContext';
import { RewardIconGraphic } from '../ui/RewardItemVisual';
import { GameText } from '../ui/GameText';
import { HexBadge } from '../ui/HexBadge';
import { SlantedButton } from '../ui/SlantedButton';
import { CreditIcon, GoldIcon, CardIcon, BoosterIcon, OmegaBoxIcon } from '../../components/ui/CurrencyIcons';

type LogCategory = 'all' | 'credits' | 'gold' | 'booster' | 'box' | 'card';

const ActivityLogItem: React.FC<{ item: ActivityLogEntry }> = ({ item }) => {
    // Scaling logic: Card is 0.75, Credits/Gold/Booster/Box bumped to ~1.82-1.94 for uniformity and visibility
    let iconScale = 'scale-[1.82]'; 
    if (item.type === 'card') iconScale = 'scale-75';
    else if (item.type === 'credits' || item.type === 'gold') iconScale = 'scale-[1.94]';

    return (
        <div className="flex items-center justify-between py-1 px-3 bg-slate-800/80 border border-slate-500 rounded-lg shadow-sm hover:border-slate-400 transition-colors cursor-default group">
            <div className="flex items-center gap-3">
                <div className="w-12 h-12 flex items-center justify-center overflow-visible">
                    <div className={iconScale}>
                        <RewardIconGraphic type={item.type as any} size="sm" cardDef={item.cardDef} />
                    </div>
                </div>
                <div>
                    <div className="font-black text-[0.8rem] tracking-tight text-white uppercase italic leading-tight">{item.title}</div>
                    <div className="text-[0.6rem] text-slate-300/80 font-bold uppercase tracking-widest mt-0.5">
                        {item.type === 'card' ? 'Unit Unlocked' : 'Manifest Claim'}
                    </div>
                </div>
            </div>
            <div className="text-right flex flex-col items-end">
                 <div className="text-[0.75rem] font-black text-white uppercase tracking-tighter tabular-nums leading-none mb-1">{item.date}</div>
                 <div className="text-[0.65rem] font-bold text-slate-300/80 uppercase tracking-widest tabular-nums">{item.time}</div>
            </div>
        </div>
    );
};

export const ProgressionScreen: React.FC<{ onNavigate: (screen: ScreenKey) => void }> = ({ onNavigate }) => {
    const { user, progressionData, activityLog, isProgressionLoading, claimProgressionReward, inspect } = useUser();
    const [logFilter, setLogFilter] = useState<LogCategory>('all');

    const filteredLog = useMemo(() => {
        if (logFilter === 'all') return activityLog;
        return activityLog.filter(item => item.type === logFilter);
    }, [activityLog, logFilter]);

    const nextHero = useMemo(() => {
        if (!progressionData) return null;
        return [...progressionData.tracks].sort((a, b) => (a.targetXP - a.currentXP) - (b.targetXP - b.currentXP))[0];
    }, [progressionData]);

    const handleInspect = (track: ProgressionTrack) => {
        inspect({
            type: track.type === 'box' ? 'box' : 'level_info',
            level: user.level + (track.targetXP - track.currentXP),
            rewardType: track.type,
            rewardAmount: track.nextRewardAmount,
            cardDef: track.nextRewardCardDef,
            boxType: 'MEGA',
            title: track.label,
            description: 'Acquired through progression.'
        });
    };

    const getScale = (type: string) => {
        if (type === 'gold' || type === 'credits') return 'scale-[0.48]'; 
        if (type === 'booster') return 'scale-[0.68]'; 
        if (type === 'card') return 'scale-[0.60]'; 
        return 'scale-[1.0]';
    };

    const getVariant = (type: ProgressionRewardType) => {
        switch(type) {
            case 'booster': return 'success';
            case 'credits': return 'blue';
            case 'gold': return 'warning';
            case 'box': return 'primary';
            case 'card': return 'secondary';
            default: return 'secondary';
        }
    };

    const getColors = (type: ProgressionRewardType) => {
        switch(type) {
            case 'booster': return { color: 'from-emerald-400 to-emerald-600', bgTrack: 'bg-[#064e3b]', borderColor: 'border-emerald-400/50' };
            case 'credits': return { color: 'from-blue-400 to-blue-600', bgTrack: 'bg-[#1e3a8a]', borderColor: 'border-blue-400/50' };
            case 'gold': return { color: 'from-amber-400 to-amber-600', bgTrack: 'bg-[#78350f]', borderColor: 'border-amber-400/50' };
            case 'box': return { color: 'from-indigo-400 to-indigo-600', bgTrack: 'bg-[#1e1b4b]', borderColor: 'border-indigo-400/50' };
            case 'card': return { color: 'from-white to-slate-400', bgTrack: 'bg-[#334155]', borderColor: 'border-white/50' };
        }
    };

    const renderFilterIcon = (cat: LogCategory) => {
        switch(cat) {
            case 'all': return <span className="font-black text-[0.65rem] -skew-x-[9deg]">ALL</span>;
            case 'credits': return <CreditIcon size="sm" />;
            case 'gold': return <GoldIcon size="sm" />;
            case 'card': return <CardIcon size="sm" />;
            case 'box': return <OmegaBoxIcon size="sm" />;
            case 'booster': return <BoosterIcon size="sm" />;
            default: return null;
        }
    };

    if (!progressionData || isProgressionLoading) {
        return (
            <div className="w-full h-full flex flex-col items-center justify-center bg-slate-950">
                <div className="w-8 h-8 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin mb-4" />
                <span className="text-[0.6rem] font-black text-indigo-400 uppercase tracking-[0.3em] animate-pulse">Syncing Sector Data...</span>
            </div>
        );
    }

    return (
        <div className="w-full h-full flex flex-col bg-slate-950 overflow-hidden relative">
            <StandardHeader 
                title="CAREER" 
                leftContent={
                    <button 
                        onClick={() => onNavigate('DECK')}
                        className="w-8 h-8 rounded-full bg-white/5 border border-white/10 flex items-center justify-center text-white active:scale-90 transition-transform"
                    >
